Object.assign(window.TEM8_DICTIONARY, {"human":{"media":{"uk":"media/uk/human__gb_1.mp3","us":"media/us/human__us_1.mp3"},"oxford":{"phon":"ˈhjuːmən","pos":"adjective","senses":[{"en":"of or connected with people rather than animals, machines or gods","cn":"人的","g":"[only before noun]","ex":{"en":"the human body/brain","cn":"人体；人脑"}},{"en":"showing the weaknesses and desires that are typical of people, which means that other people should not criticize the person too much","cn":"显示人性弱点（或欲望的）的；人本性的","ex":{"en":"human weaknesses/failings","cn":"人性的弱点／缺点"}},{"en":"having the same feelings and emotions as most ordinary people","cn":"有人情味的；通人情的","ex":{"en":"He's really very human when you get to know him.","cn":"你若了解他，就知道他确实很有人情味。"}},{"en":"a person rather than an animal or a machine","cn":"人","ex":{"en":"Dogs can hear much better than humans.","cn":"狗的听觉比人灵敏得多。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"人的;人类的","en":"Human means relating to or concerning people.","ex":{"en":"...the human body.","cn":"人体"}},{"pos":"N-COUNT 可数名词","cn":"（尤指与动物或机器相对的）人","en":"You can refer to people as humans, especially when you are comparing them with animals or machines.","ex":{"en":"Its rate of growth was fast — much more like that of an ape than that of a human.","cn":"它的发育速度很快——更像猿，而不像人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情感、弱点、错误等）人特有的显示人的本性的","en":"Human feelings, weaknesses, or errors are ones that are typical of humans rather than machines.","ex":{"en":"...an ever growing risk of human error","cn":"越来越高的人为错误的风险"}}]},"examples":[{"en":"Firefighters formed a human chain (= a line of people) to carry the children to safety.","cn":"消防队员组成人链把孩子们救到了安全的地方。"},{"en":"It's only human to want the best for your children.","cn":"为自己的孩子谋求最好的条件是人之常情。"}]},"housing":{"media":{"uk":"media/uk/housing__gb_1.mp3","us":"media/us/housing__us_1.mp3"},"oxford":{"phon":"ˈhaʊzɪŋ","pos":"noun","senses":[{"en":"houses, flats, etc. that people live in, especially when referring to their type, price or condition","cn":"（统称，尤指住房类型、价格、条件）住房，住宅","g":"[uncountable]","ex":{"en":"rental/student housing","cn":"租赁／学生住房"}},{"en":"the job of providing houses, flats, etc. for people to live in","cn":"住房供给","g":"[uncountable]","ex":{"en":"Tenants may only keep pets with the written consent of the housing department.","cn":"租户只有在获得住房部门书面同意的情况下才可以饲养宠物。"}},{"en":"a hard cover that protects part of a machine","cn":"（机器的）外壳，套","g":"[countable]","ex":{"en":"a car’s rear axle housing","cn":"汽车的后轴套"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"住房;住宅","en":"You refer to the buildings in which people live as housing when you are talking about their standard, price, or availability.","ex":{"en":"...a shortage of affordable housing","cn":"保障房的短缺"}},{"pos":"N-UNCOUNT 不可数名词","cn":"住房供给;住房建设","en":"Housing is the job of providing houses for people to live in.","ex":{"en":"...graduate courses in housing and public administration","cn":"住房建设和公共管理的研究生课程"}},{"pos":"N-COUNT 可数名词","cn":"（机器的）外壳，外罩，护盖","en":"A housing is a case or covering which protects parts of a machine.","ex":{"en":"Both housings are waterproof to a depth of two metres.","cn":"两个机罩的防水深度均为两米。"}}]},"examples":[{"en":"the housing market (= the activity of buying and selling houses, etc.)","cn":"住房市场"},{"en":"public/private housing","cn":"公共/私人住房"}],"base":"house"},"hammer":{"media":{"img":["media/pic/tools_diy_comp.jpg","media/thumb/hammer.jpg"],"uk":"media/uk/hammer__gb_1.mp3","us":"media/us/hammer__us_1.mp3"},"oxford":{"phon":"ˈhæmə(r)","pos":"noun","senses":[{"en":"a tool with a handle and a heavy metal head, used for breaking things or hitting nails","cn":"锤子；榔头","g":"[countable]","sc":"tool","ex":{"en":"a gentle tap with a hammer","cn":"用锤子轻轻敲击"}},{"en":"a tool with a handle and a wooden head, used by a person in charge of an auction (= a sale at which things are sold to the person who offers the most money) in order to get people’s attention when something is just being sold","cn":"（拍卖用的）木槌","g":"[countable]","sc":"tool","ex":{"en":"to come/go under the hammer (= to be sold at auction)","cn":"被拍卖"}},{"en":"a small wooden part inside a piano, that hits the strings to produce a sound","cn":"音槌","g":"[countable]","sc":"in piano"},{"en":"a part inside a gun that makes the gun fire","cn":"击铁","g":"[countable]","sc":"in gun"},{"en":"a metal ball attached to a wire, thrown as a sport","cn":"链球","g":"[countable]","sc":"sport"},{"en":"the event or sport of throwing the hammer","cn":"掷链球（运动）","g":"[singular]","sc":"sport"},{"en":"the first of three small bones in the middle ear that carry sound to the inner ear","cn":"锤骨（引导声波从中耳传至内耳的三块小骨之一）","g":"[countable]","lab":"anatomy","sc":"in ear"},{"en":"to hit something with a hammer","cn":"（用锤子）敲，锤打","g":"[intransitive, transitive]","sc":"hit with tool","ex":{"en":"I could hear somebody hammering next door.","cn":"我听到隔壁有人在锤打东西。"},"pos":"verb"},{"en":"to hit something hard many times, especially so that it makes a loud noise","cn":"反复敲打，连续击打（尤指发出大声）","g":"[intransitive, transitive]","lab":"figurative","sc":"hit many times","ex":{"en":"Someone was hammering at the door.","cn":"有人在砰砰地捶门。"},"pos":"verb"},{"en":"to kick or hit a ball very hard","cn":"猛踢；猛击","g":"[transitive]","lab":"informal","sc":"kick/hit ball","ex":{"en":"He hammered the ball into the net.","cn":"他一记猛射，将球踢进网。"},"pos":"verb"},{"en":"to defeat somebody very easily","cn":"轻易击败","g":"[transitive]","lab":"informal","sc":"defeat easily","ex":{"en":"Our team was hammered 5–1.","cn":"我队以 1:5 的悬殊比分败北。"},"pos":"verb"},{"en":"to affect somebody/something very badly","cn":"重创；严重打击","g":"[transitive]","lab":"informal","sc":"affect badly","ex":{"en":"Eastern counties were brutally hammered by the weekend flooding.","cn":"东部各县在周末的洪水中受灾惨重。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"锤子;榔头","en":"A hammer is a tool that consists of a heavy piece of metal at the end of a handle. It is used, for example, to hit nails into a piece of wood or a wall, or to break things into pieces.","ex":{"en":"He used a hammer and chisel to chip away at the wall.","cn":"他用榔头和凿子铲墙。"}},{"pos":"VERB 动词","cn":"用锤击;锤打","en":"If you hammer an object such as a nail, you hit it with a hammer.","ex":{"en":"To avoid damaging the tree, hammer a wooden peg into the hole","cn":"为了不毁坏树，用锤子将一个木栓钉进洞里。"}},{"pos":"VERB 动词","cn":"（反复）敲打","en":"If you hammer on a surface, you hit it several times in order to make a noise, or to emphasize something you are saying when you are angry.","ex":{"en":"We had to hammer and shout before they would open up","cn":"我们不停地拍门、叫喊，他们才开了门。"}},{"pos":"VERB 动词","cn":"强行灌输;反复强调","en":"If you hammer something such as an idea into people or you hammer at it, you keep repeating it forcefully so that it will have an effect on people.","ex":{"en":"He hammered it into me that I had not suddenly become a rotten goalkeeper","cn":"他反复告诉我，我并没有一下子变成个差劲的守门员。"}},{"pos":"VERB 动词","cn":"猛烈攻击;大力批评;严厉惩罚","en":"If you say that someone hammers another person, you mean that they attack, criticize, or punish the other person severely.","ex":{"en":"The report hammers the private motorist","cn":"该报告严词谴责了那个私家车司机。"}},{"pos":"V-PASSIVE 被动动词","cn":"（因税收政策变化、经济不景气等）使（企业）受到打击","en":"If you say that businesses are being hammered, you mean that they are being unfairly harmed, for example by a change in taxes or by bad economic conditions.","ex":{"en":"Look at the numbers of small businesses that are being hammered unmercifully","cn":"看看有多少小企业正在遭受无情的打击。"}},{"pos":"VERB 动词","cn":"（在体育比赛中）使惨败，大败","en":"In sports, if you say that one player or team hammered another, you mean that the first player or team defeated the second completely and easily.","ex":{"en":"He hammered the young Austrian player in four straight sets.","cn":"他直落4局轻取年轻的奥地利对手。"}},{"pos":"VERB 动词","cn":"（通常指因恐惧而心脏）快速跳动","en":"If someone's heart is hammering, it is beating very fast, usually because they are frightened.","ex":{"en":"My heart was hammering. The footsteps had stopped outside my door.","cn":"我的心怦怦直跳。脚步声已停在我的门外。"}},{"pos":"N-COUNT 可数名词","cn":"（机械设备中的）锤状物;（枪上的）击铁;(钢琴的）音槌","en":"In machines and instruments, a hammer is a part that hits another part. For example, in a gun the hammer causes the explosion which makes the bullet shoot out of it, and in a piano the hammers hit the strings and cause the sounds."},{"pos":"N-COUNT 可数名词","cn":"（田径运动中所掷的）链球","en":"In athletics, a hammer is a heavy weight on a piece of wire, which the athlete throws as far as possible.","ex":{"en":"Events like the hammer and the discus are not traditional crowd-pullers in the West.","cn":"掷链球和铁饼等在西方算不上传统的受欢迎项目。"}},{"pos":"PHRASE 短语","cn":"满腔热情地;劲头十足地","en":"If you say that someone was going at something hammer and tongs, you mean that they were doing it with great enthusiasm or energy.","ex":{"en":"He loved gardening. He went at it hammer and tongs as soon as he got back from work","cn":"他酷爱侍弄花草。只要下班一回到家，他就兴冲冲地忙活起来。"}},{"pos":"PHRASE 短语","cn":"被拍卖","en":"If you say that something goes, comes, or is under the hammer, you mean that it is going to be sold at an auction.","ex":{"en":"Ian Fleming's original unpublished notes are to go under the hammer at London auctioneers Sotheby's.","cn":"伊恩·弗莱明未出版的原版笔记将在伦敦的苏富比拍卖行进行拍卖。"}},{"pos":"","cn":"","en":"相关词组：hammer away hammer in hammer out"}]},"examples":[{"en":"( figurative ) The decision is a hammer blow for the steel industry.","cn":"这一决定对于钢铁业是一个沉重的打击。"},{"en":"Our team was hammered 5-1.","cn":"我队以 1:5 的悬殊比分败北。"}]},"hometown":{"media":{"uk":"media/uk/hometown__gb_1.mp3","us":"media/us/hometown__us_1.mp3"},"oxford":{"phon":"ˈhəʊmtaʊn","pos":"noun","senses":[{"en":"the place where you were born or lived as a child","cn":"家乡；故乡"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"家乡;故乡","en":"Someone's hometown is the town where they live or the town that they come from.","ex":{"en":"I went to work as a painter in my hometown, Natrona Heights, Pennsylvania.","cn":"我在家乡宾夕法尼亚州的纳特罗纳海茨当了个油漆匠。"}}]}},"hide":{"oxford":{"phon":"haɪd","pos":"verb","senses":[{"en":"to put or keep somebody/something in a place where they/it cannot be seen or found","cn":"藏；隐蔽","g":"[transitive]","ex":{"en":"He hid the letter in a drawer.","cn":"他把信藏在抽屉里。"}},{"en":"to go somewhere where you hope you will not be seen or found","cn":"躲避；隐匿","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"Quick, hide!","cn":"快，躲起来！"}},{"en":"to cover somebody/something so that they/it cannot be seen","cn":"遮住；遮挡","g":"[transitive]","ex":{"en":"He hid his face in his hands.","cn":"他用手捂住了脸。"}},{"en":"to keep something secret, especially your feelings","cn":"掩盖，隐瞒（尤指感情）","g":"[transitive]","ex":{"en":"They didn't try to hide the fact that the film was a remake.","cn":"这部电影是翻拍的，他们并没有试图掩盖这一事实。"}},{"en":"a place from which people can watch wild animals or birds, without being seen by them","cn":"（观看野生动物的）隐蔽处，藏身处","g":"[countable]","lab":"British English","pos":"noun"},{"en":"an animal’s skin, especially when it is bought or sold or used for leather","cn":"（尤指买卖或用作皮革的）皮，毛皮","g":"[countable, uncountable]","ex":{"en":"boots made from buffalo hide","cn":"用水牛皮做的靴子"},"pos":"noun"},{"en":"used to refer to somebody’s life or safety when they are in a difficult situation","cn":"（困境中的）生命，人身安全","g":"[singular]","lab":"especially North American English, informal，，","ex":{"en":"All he's worried about is his own hide (= himself).","cn":"他所担心的只是他自己的生命安全。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…藏起来;隐藏","en":"If you hide something or someone, you put them in a place where they cannot easily be seen or found.","ex":{"en":"He hid the bicycle in the hawthorn hedge","cn":"他把自行车藏在山楂树篱中。"}},{"pos":"VERB 动词","cn":"躲藏;隐藏","en":"If you hide or if you hide yourself, you go somewhere where you cannot easily be seen or found.","ex":{"en":"At their approach the little boy scurried away and hid","cn":"他们走近时，小男孩急忙跑开藏了起来。"}},{"pos":"VERB 动词","cn":"捂住（脸）;将（脸）埋进","en":"If you hide your face, you press your face against something or cover your face with something, so that people cannot see it.","ex":{"en":"She hid her face under the collar of his jacket and she started to cry","cn":"她将脸埋在他外套的衣领下，开始哭了起来。"}},{"pos":"VERB 动词","cn":"隐瞒;使不外露","en":"If you hide what you feel or know, you keep it a secret, so that no one knows about it.","ex":{"en":"Lee tried to hide his excitement","cn":"李试图掩饰自己的激动心情。"}},{"pos":"VERB 动词","cn":"掩蔽;遮盖","en":"If something hides an object, it covers it and prevents it from being seen.","ex":{"en":"The man's heavy moustache hid his upper lip completely","cn":"那个男人浓密的髭须完全遮住了他的上唇。"}},{"pos":"N-COUNT 可数名词","cn":"（狩猎或观察、拍摄野生动物等的）隐蔽处，藏身处","en":"A hide is a place which is built to look like its surroundings. Hides are used by people who want to watch or photograph animals and birds without being seen by them."},{"pos":"N-VAR 可变名词","cn":"兽皮;毛皮","en":"A hide is the skin of a large animal such as a cow, horse, or elephant, which can be used for making leather.","ex":{"en":"...the process of tanning animal hides.","cn":"鞣制兽皮的工序"}}]},"media":{"uk":"media/uk/hide__gb_1.mp3","us":"media/us/hide__us_1.mp3"},"examples":[{"en":"They hid me from the police in their attic.","cn":"他们把我藏在他们的阁楼上躲避警察。"},{"en":"No amount of make-up could hide her age.","cn":"再多的化妆品也遮掩不住她的年龄。"}]},"hail":{"oxford":{"phon":"heɪl","pos":"verb","senses":[{"en":"to describe somebody/something as being very good or special, especially in newspapers, etc.","cn":"赞扬（或称颂）…为（尤用于报章等）","g":"[transitive, usually passive]","ex":{"en":"The conference was hailed as a great success.","cn":"会议被称颂为一次巨大的成功。"}},{"en":"to signal to a taxi or a bus, in order to get the driver to stop","cn":"招手叫（出租车或公共汽车）","g":"[transitive]","ex":{"en":"to hail a taxi/cab","cn":"打手势叫出租车"}},{"en":"to call to somebody in order to say hello to them or attract their attention","cn":"跟…打招呼；向…喊","g":"[transitive]","lab":"literary","ex":{"en":"A voice hailed us from the other side of the street.","cn":"街对面有个声音招呼我们。"}},{"en":"when it hails, small balls of ice fall like rain from the sky","cn":"下雹","g":"[intransitive]","ex":{"en":"It's hailing!","cn":"正下着冰雹！"}},{"en":"small balls of ice that fall like rain","cn":"雹；冰雹","g":"[uncountable]","ex":{"en":"We drove through hail and snow.","cn":"我们顶着冰雹和大雪开车。"},"pos":"noun"},{"en":"a large number or amount of something that is aimed at somebody in order to harm them","cn":"一阵像冰雹般袭来的事物；雹子般的一阵","g":"[singular]","ex":{"en":"a hail of arrows/bullets","cn":"一阵乱箭／弹雨"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"赞扬，称颂（人、事件或成就）","en":"If a person, event, or achievement is hailed as important or successful, they are praised publicly.","ex":{"en":"Faulkner has been hailed as the greatest American novelist of his generation","cn":"福克纳被誉为他那一代人中最伟大的美国小说家。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"雹子;冰雹","en":"Hail consists of small balls of ice that fall like rain from the sky.","ex":{"en":"...a sharp short-lived storm with heavy hail.","cn":"一阵短暂的大雹暴"}},{"pos":"VERB 动词","cn":"下雹;下冰雹","en":"When it hails, hail falls like rain from the sky.","ex":{"en":"It started to hail, huge great stones.","cn":"开始下雹，而且是很大的雹子。"}},{"pos":"N-SING 单数名词","cn":"雹子般的一阵","en":"A hail of things, usually small objects, is a large number of them that hit you at the same time and with great force.","ex":{"en":"The victim was hit by a hail of bullets","cn":"受害者被一阵弹雨击中。"}},{"pos":"VERB 动词","cn":"（人）生于，来自","en":"Someone who hails from a particular place was born there or lives there.","ex":{"en":"I hail from Brighton","cn":"我来自布赖顿。"}},{"pos":"VERB 动词","cn":"（人或物）来自","en":"If someone or something hails from a particular background, they come from it.","ex":{"en":"He hails from an affluent background","cn":"他出身于一个富有的家庭。"}},{"pos":"VERB 动词","cn":"招呼;喊","en":"If you hail someone, you call to them.","ex":{"en":"Jill saw him and hailed him","cn":"吉尔看到了他，并和他打招呼。"}},{"pos":"VERB 动词","cn":"招呼，叫（出租车）","en":"If you hail a taxi, you wave at it in order to stop it because you want the driver to take you somewhere.","ex":{"en":"I hurried away to hail a taxi.","cn":"我赶紧去叫出租车。"}},{"pos":"CONVENTION 惯用语","cn":"致意;致敬","en":"Hail is used as a word of greeting.","ex":{"en":"Hail to the new champion Bengali D'Albret.","cn":"向新科冠军本·贾利·达阿尔布雷致敬。"}}]},"media":{"uk":"media/uk/hail__gb_1.mp3","us":"media/us/hail__us_1.mp3"},"examples":[{"en":"Teenager Matt Brown is being hailed a hero for saving a young child from drowning.","cn":"因救起一名溺水儿童，少年马特 · 布朗被誉为英雄。"},{"en":"The conference was hailed as a great success.","cn":"会议被称颂为一次巨大的成功。"}]},"hair":{"media":{"img":["media/pic/hair_comp.jpg","media/thumb/ponytail.jpg"],"uk":"media/uk/hair__gb_1.mp3","us":"media/us/hair__us_1.mp3"},"oxford":{"phon":"heə(r)","pos":"noun","senses":[{"en":"the substance that looks like a mass of fine threads growing on a person's head","cn":"头发","g":"[uncountable]","lab":"North American English also","ex":{"en":"She has long dark hair.","cn":"她留着长长的黑发。"}},{"en":"hair growing on the body of a person or an animal","cn":"（人或动物身上的）毛","g":"[uncountable]","ex":{"en":"body/facial/pubic hair","cn":"体毛；脸毛；阴毛"}},{"en":"a piece of hair from a person or an animal","cn":"（一根）毛，头发","g":"[countable]","ex":{"en":"There's a hair in my soup.","cn":"我的汤里有根毛。"}},{"en":"having the type of hair mentioned","cn":"有…毛发（或头发）的","ex":{"en":"dark-haired","cn":"黑发的"}},{"en":"a thing that looks like a fine thread growing on the leaves and stems of some plants","cn":"（植物叶、茎上的）茸毛","g":"[countable]"},{"en":"a 'rock musical' play (1967) about hippies. It opened in New York and a year later in London. It was criticized (and attracted audiences) because in one scene the actors were naked and because the characters were against the Vietnam War and thought that drugs were fun. The songs include Let the Sunshine In and The Age of Aquarius. A film version appeared in 1979.","cn":"头发：关于嬉皮士的摇滚音乐剧（1967）。它在纽约开业，一年后在伦敦开业。它受到批评（并吸引了观众），因为在一个场景中，演员是赤裸裸的，并且因为角色反对越战，并认为毒品很有趣。歌曲包括《放进阳光》和《水瓶座的时代》。电影版本出现在1979年。","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"头发","en":"Your hair is the fine threads that grow in a mass on your head.","ex":{"en":"I wash my hair every night","cn":"我每晚都洗头。"}},{"pos":"N-VAR 可变名词","cn":"毛发;汗毛;体毛","en":"Hair is the short, fine threads that grow on different parts of your body.","ex":{"en":"The majority of men have hair on their chest","cn":"大多数男子长有胸毛。"}},{"pos":"N-VAR 可变名词","cn":"（动物的）毛;（马的）鬃，鬣","en":"Hair is the threads that cover the body of an animal such as a dog, or make up a horse's mane and tail.","ex":{"en":"I am allergic to cat hair.","cn":"我对猫毛过敏。"}},{"pos":"N-COUNT 可数名词","cn":"（昆虫、植物上的）茸毛","en":"Hairs are short, very fine threads that grow on some insects and plants.","ex":{"en":"The stinging nettle has a square stem and little hairs.","cn":"荨麻长有四方茎和细小茸毛。"}},{"pos":"PHRASE 短语","cn":"彻底放松;玩个痛快;无拘无束","en":"If you let your hair down, you relax completely and enjoy yourself.","ex":{"en":"...the world-famous Oktoberfest, a time when everyone in Munich really lets their hair down.","cn":"全球闻名的啤酒节，一个让所有身在慕尼黑的人都尽情放松的节日"}},{"pos":"PHRASE 短语","cn":"使…毛骨悚然","en":"Something that makes your hair stand on end shocks or frightens you very much.","ex":{"en":"This was the kind of smile that made your hair stand on end.","cn":"这是那种让人不寒而栗的微笑。"}},{"pos":"PHRASE 短语","cn":"非常整洁;衣冠楚楚","en":"If you say that someone has not a hair out of place, you are emphasizing that they are extremely smart and neatly dressed.","ex":{"en":"She had a lot of make-up on and not a hair out of place.","cn":"她化了浓妆，精致得让人挑不出一丝瑕疵。"}},{"pos":"PHRASE 短语","cn":"面不改色;毫不惊慌;泰然自若","en":"If you say that someone faced with a shock or a problem does not turn a hair, you mean that they do not show any surprise or fear, and remain completely calm.","ex":{"en":"No one seems to turn a hair at the thought of the divorced Princess marrying.","cn":"似乎没有人对离异的公主再婚感到丝毫地吃惊。"}},{"pos":"PHRASE 短语","cn":"在细节上过分纠缠","en":"If you say that someone is splitting hairs, you mean that they are making unnecessary distinctions between things when the differences between them are so small they are not important.","ex":{"en":"Don't split hairs. You know what I'm getting at.","cn":"别钻牛角尖了。你知道我指什么。"}}]},"examples":[{"en":"( informal ) I'll be down in a minute. I'm doing (= brushing, arranging, etc.) my hair.","cn":"我马上就下来。我在梳头呢。"},{"en":"I'm having my hair cut this afternoon.","cn":"我今天下午要去理发。"}]},"hug":{"media":{"uk":"media/uk/hug__gb_1.mp3","us":"media/us/hug__us_1.mp3"},"oxford":{"phon":"hʌɡ","pos":"verb","senses":[{"en":"to put your arms around somebody and hold them tightly, especially to show that you like or love them","cn":"拥抱；搂抱","g":"[transitive, intransitive]","ex":{"en":"They hugged each other.","cn":"他们相互拥抱。"}},{"en":"to put your arms around something and hold it close to your body","cn":"抱紧","g":"[transitive]","ex":{"en":"She sat in the chair, hugging her knees.","cn":"她双臂抱膝坐在椅子上。"}},{"en":"to keep close to something for a distance","cn":"有一段距离地挨着（某物）","g":"[transitive]","ex":{"en":"The track hugs the coast for a mile.","cn":"那条小径离海岸只有一英里。"}},{"en":"to fit tightly around something, especially a person’s body","cn":"缠紧，缚紧（某物，尤指人体）","g":"[transitive]","ex":{"en":"figure-hugging jeans","cn":"紧身牛仔裤"}},{"en":"an act of putting your arms around somebody and holding them tightly, especially to show that you like or love them","cn":"拥抱；搂抱","ex":{"en":"She gave her mother a big hug.","cn":"她热烈地拥抱了她的母亲。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"拥抱;搂抱","en":"When you hug someone, you put your arms around them and hold them tightly, for example because you like them or are pleased to see them. You can also say that two people hug each other or that they hug .","ex":{"en":"She had hugged him exuberantly and invited him to dinner the next day","cn":"她兴高采烈地拥抱了他，并邀请他第二天一起吃晚饭。"}},{"pos":"VERB 动词","cn":"抱住，抱紧（某物）","en":"If you hug something, you hold it close to your body with your arms tightly round it.","ex":{"en":"Shaerl trudged toward them, hugging a large box","cn":"谢尔抱着一个大箱子步履艰难地向他们走去。"}},{"pos":"VERB 动词","cn":"紧挨;濒临","en":"Something that hugs the ground or a stretch of land or water stays very close to it.","ex":{"en":"The road hugs the coast for hundreds of miles","cn":"公路沿着海岸延伸数百英里。"}}]},"examples":[{"en":"He stopped to receive hugs and kisses from the fans.","cn":"他停下来接受追随者的拥抱亲吻。"},{"en":"The track hugs the coast for a mile.","cn":"那条小径有一英里紧靠海岸。"}]},"has":{"oxford":{"phon":"hɑː","pos":"exclamation","senses":[{"en":"the sound that people make when they are surprised or pleased or when they have discovered sth （","cn":"惊奇、高兴或有所发现时用）哈"},{"en":"the word for the sound that people make when they laugh （","cn":"笑声）哈"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Has is the third person singular of the present tense of have."}]},"media":{"uk":"media/uk/has__gb_1.mp3","us":"media/us/has__us_1.mp3"}},"hinting":{"lemma":"hint"},"humanitarian":{"media":{"uk":"media/uk/humanitarian__gb_1.mp3","us":"media/us/humanitarian__us_1.mp3"},"oxford":{"phon":"hjuːˌmænɪˈteəriən","pos":"adjective","senses":[{"en":"connected with helping people who are suffering and improving the conditions that they are living in","cn":"人道主义的；人道主义精神的","ex":{"en":"to provide humanitarian aid to the war zone","cn":"给战区提供人道主义援助"}},{"en":"describing an event or situation that causes or involves a lot of human suffering, especially one that requires aid to be provided to a large number of people","cn":"人道主义的：描述导致或涉及很多人痛苦的事件或情况，尤其是需要向大量人提供援助的事件或情况","ex":{"en":"a humanitarian crisis","cn":"人道主义危机"}},{"en":"a person who tries to help people who are suffering and improve the conditions that they are living in","cn":"人道主义的（主张减轻人类苦难、改善人类生活）；慈善的","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"人道主义的;博爱的","en":"If a person or society has humanitarian ideas or behaviour, they try to avoid making people suffer or they help people who are suffering.","ex":{"en":"Air bombardment raised criticism on the humanitarian grounds that innocent civilians might suffer.","cn":"空袭遭到了批评，因为从人道主义的立场来看，无辜的平民可能会受到伤害。"}}]},"examples":[{"en":"The expulsion of thousands of people represents a humanitarian catastrophe of enormous proportions.","cn":"驱逐成千上万人意味着人道主义的巨大灾难。"},{"en":"They are calling for the release of the hostages on humanitarian grounds.","cn":"他们站在人道主义立场要求释放人质。"}]},"housework":{"media":{"uk":"media/uk/housework__gb_1.mp3","us":"media/us/housework__us_1.mp3"},"oxford":{"phon":"ˈhaʊswɜːk","pos":"noun","senses":[{"en":"the work involved in taking care of a home and family, for example cleaning and cooking","cn":"家务劳动；家务事","ex":{"en":"to do the housework","cn":"做家务"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"家务劳动","en":"Housework is the work such as cleaning, washing, and ironing that you do in your home."}]},"examples":[{"en":"to do the housework","cn":"做家务"}]},"horns":{"lemma":"horn"},"however":{"media":{"uk":"media/uk/however__gb_1.mp3","us":"media/us/however__us_1.mp3"},"oxford":{"phon":"haʊˈevə(r)","pos":"adverb","senses":[{"en":"used to introduce a statement that contrasts with something that has just been said","cn":"然而；不过；仍然","ex":{"en":"He was feeling bad. He went to work, however, and tried to concentrate.","cn":"他感觉不舒服，但他仍然去上班，并且努力集中精神工作。"}},{"en":"used with an adjective or adverb to mean ‘to whatever degree’","cn":"（与形容词或副词连用）无论到什么程度，不管多么","ex":{"en":"He wanted to take no risks, however small.","cn":"他再小的风险也不想冒。"}},{"en":"in whatever way","cn":"不管怎样；无论如何","ex":{"en":"However you look at it, it's going to cost a lot.","cn":"不管你怎么看，它都要花很多钱。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"然而;不过;仍然","en":"You use however when you are adding a comment which is surprising or which contrasts with what has just been said.","ex":{"en":"This was not an easy decision. It is, however, a decision that we feel is dictated by our duty","cn":"这很难抉择。不过，我们觉得自己有义务作出决定。"}},{"pos":"ADV 副词","cn":"（后接形容词或副词用于强调）不管怎样，无论多么","en":"You use however before an adjective or adverb to emphasize that the degree or extent of something cannot change a situation.","ex":{"en":"You should always strive to achieve more, however well you have done before","cn":"无论之前取得何等辉煌的成就，都应该不断努力进取。"}},{"pos":"CONJ-SUBORD 连词","cn":"不管用什么方式;无论如何","en":"You use however when you want to say that it makes no difference how something is done.","ex":{"en":"However we adopt healthcare reform, it isn't going to save major amounts of money","cn":"不管我们采取何种医疗改革措施，都省不下太多钱。"}},{"pos":"ADV 副词","cn":"…左右;…上下","en":"You use however in expressions such as or however long it takes and or however many there were to indicate that the figure you have just mentioned may not be accurate.","ex":{"en":"The 20,000 or however many who come to watch would love to be out on the pitch","cn":"约两万名来看比赛的观众都希望能身处球场之上。"}},{"pos":"QUEST 疑问词","cn":"究竟怎样，到底如何（用于强调地询问令人吃惊的事情;一些人认为此用法不正确，用how ever较为妥当）","en":"You can use however to ask in an emphatic way how something has happened which you are very surprised about. Some speakers of English think that this form is incorrect and prefer to use 'how ever'.","ex":{"en":"However did you find this place in such weather?","cn":"你到底是怎样在这样的天气里找到这个地方的？"}}]},"examples":[{"en":"He was feeling bad. He went to work, however, and tried to concentrate.","cn":"他感觉不舒服，但他仍然去上班，并且努力集中精神工作。"},{"en":"We thought the figures were correct. However, we have now discovered some errors.","cn":"我们原以为这些数据正确，不过我们现在发现了一些错误。"}]},"hull":{"media":{"uk":"media/uk/hull__gb_1.mp3","us":"media/us/hull__us_1.mp3"},"oxford":{"phon":"hʌl","pos":"noun","senses":[{"en":"the main, bottom part of a ship, that goes in the water","cn":"船身；船体","ex":{"en":"a wooden/steel hull","cn":"木质／钢质船体"}},{"en":"to remove the outer layer that covers peas, beans, grain, etc. or the ring of leaves attached to strawberries","cn":"剥去（豆子、谷物等）的外壳；摘掉（草莓）的花萼","ex":{"en":"First wash and hull the strawberries.","cn":"首先将草莓洗净并去皮。"},"pos":"verb"},{"en":"a port and industrial centre in Humberside in north-eastern England. It is on the River Humber.","cn":"船体：英格兰东北部亨伯赛德的港口和工业中心。它在亨伯河上。","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"船体;（坦克的）车身","en":"The hull of a boat or tank is the main body of it.","ex":{"en":"The hull had suffered extensive damage to the starboard side.","cn":"船体右舷遭到重创。"}},{"pos":"N-COUNT 可数名词","cn":"（草莓等浆果的）花萼","en":"The hull of a soft fruit such as a strawberry is the stalk and ring of leaves at the base."},{"pos":"VERB 动词","cn":"除去（草莓等浆果）的花萼","en":"If you hull soft fruit such as strawberries, you remove the hulls.","ex":{"en":"Wash and hull the strawberries.","cn":"洗一下草莓，并摘掉花萼。"}}]},"examples":[{"en":"They climbed onto the upturned hull and waited to be rescued.","cn":"他们爬上了倾覆的船体，等候救援。"},{"en":"a wooden/steel hull","cn":"木质/钢质船体"}]},"heel":{"media":{"uk":"media/uk/heel__gb_1.mp3","us":"media/us/heel__us_1.mp3","img":["media/ldoce/img/shoes.jpg"]},"oxford":{"phon":"hiːl","pos":"noun","senses":[{"en":"the back part of the foot below the ankle","cn":"脚跟；脚后跟","g":"[countable]","sc":"part of foot","ex":{"en":"Apply the cream to dry, cracked heels before bed.","cn":"睡前将霜涂抹在干燥、开裂的脚后跟上。"}},{"en":"the part of a sock, etc. that covers the heel","cn":"（袜子等的）后跟","g":"[countable]","sc":"part of sock/shoe"},{"en":"the raised part on the bottom of a shoe, boot, etc. that makes the shoe, etc. higher at the back","cn":"（鞋、靴子等的）后跟","g":"[countable]","sc":"part of sock/shoe","ex":{"en":"shoes with a low/high heel","cn":"低跟鞋；高跟鞋"}},{"en":"having the type of heel mentioned","cn":"有…后跟的","sc":"-heeled","ex":{"en":"high-heeled shoes","cn":"高跟鞋"}},{"en":"a pair of shoes that have high heels","cn":"高跟鞋","g":"[plural]","sc":"shoes","ex":{"en":"She doesn't often wear heels.","cn":"她不常穿高跟鞋。"}},{"en":"the raised part of the inside of the hand where it joins the wrist","cn":"手掌根（手掌靠近腕部的隆起部分）","g":"[countable]","sc":"part of hand"},{"en":"a man who is unpleasant to other people and cannot be trusted","cn":"卑鄙的家伙；浑蛋","g":"[countable]","lab":"old-fashioned, informal，，","sc":"unpleasant man"},{"en":"to repair the heel of a shoe, etc.","cn":"给（鞋等）修理后跟","g":"[transitive]","sc":"repair shoe","pos":"verb"},{"en":"to lean over to one side","cn":"倾侧；倾斜","g":"[intransitive]","sc":"of boat","ex":{"en":"The boat heeled over in the strong wind.","cn":"船在狂风中倾侧了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"足跟;脚后跟;踵","en":"Your heel is the back part of your foot, just below your ankle."},{"pos":"N-COUNT 可数名词","cn":"（鞋）后跟","en":"The heel of a shoe is the raised part on the bottom at the back.","ex":{"en":"He kicked it shut with the heel of his boot.","cn":"他用靴子的后跟将它踢上。"}},{"pos":"N-PLURAL 复数名词","cn":"（女式）高跟鞋","en":"Heels are women's shoes that are raised very high at the back.","ex":{"en":"...two well-dressed ladies in high heels","cn":"两位穿着高跟鞋、打扮入时的女士"}},{"pos":"N-COUNT 可数名词","cn":"（袜子的）后跟","en":"The heel of a sock or stocking is the part that covers your heel."},{"pos":"N-COUNT 可数名词","cn":"（近腕处的）手掌根","en":"The heel of your hand is the rounded pad at the bottom of your palm.","ex":{"en":"He shoved the heel of his hand against the side of my face.","cn":"他用手掌根使劲推我的脸颊。"}},{"pos":"PHRASE 短语","cn":"紧跟在后","en":"If a person or an animal is at your heels, they are following close behind you.","ex":{"en":"She strode off down the restaurant with Cavendish following close at her heels.","cn":"她大步向餐馆里面走去，卡文迪什紧随其后。"}},{"pos":"PHRASE 短语","cn":"使听话;使就范","en":"If you bring someone to heel, you force them to obey you.","ex":{"en":"It's still not clear how the president will use his power to bring the republics to heel.","cn":"总统将如何行使自己的权力使共和党人就范仍不太清楚。"}},{"pos":"PHRASE 短语","cn":"咔嚓一声立正（敬礼或问候）","en":"If someone such as a soldier clicks their heels, they make a sound by knocking the heels of their shoes together when saluting or greeting someone.","ex":{"en":"...a courtly European who still clicked his heels when he met a lady.","cn":"遇见女士仍咔嚓一声行礼的彬彬有礼的欧洲人"}},{"pos":"PHRASE 短语","cn":"久等;空等","en":"If you are cooling your heels, someone is deliberately keeping you waiting, so that you get bored or impatient.","ex":{"en":"Cohen didn't mention that he had Ted Forstmann cooling his heels in a back room.","cn":"科恩没有提起自己让泰德·福斯特曼在后室里空等的事。"}},{"pos":"PHRASE 短语","cn":"坚持立场;固执己见","en":"If you dig your heels in or dig in your heels, you refuse to do something such as change your opinions or plans, especially when someone is trying very hard to make you do so.","ex":{"en":"It was really the British who, by digging their heels in, prevented any last-minute deal.","cn":"实际上是因为英国人拒不让步，才使得最后一刻达成协议的希望落空了。"}},{"pos":"PHRASE 短语","cn":"（时间上）紧跟…之后，紧接着","en":"If you say that one event follows hard on the heels of another or hot on the heels of another, you mean that one happens very quickly or immediately after another.","ex":{"en":"Unfortunately, bad news has come hard on the heels of good","cn":"很遗憾，好消息的后面紧跟着就是坏消息。"}},{"pos":"PHRASE 短语","cn":"紧追…之后;紧随…之后","en":"If you say that someone is hot on your heels, you are emphasizing that they are chasing you and are not very far behind you.","ex":{"en":"They sped through the American southwest with the law hot on their heels.","cn":"他们飞车穿越美国西南部，警察紧追其后。"}},{"pos":"PHRASE 短语","cn":"无聊地等;不耐烦地等待","en":"If you are kicking your heels, you are having to wait around with nothing to do, so that you get bored or impatient.","ex":{"en":"The authorities wouldn't grant us permission to fly all the way down to San Francisco, so I had to kick my heels at Tunis Airport.","cn":"当局不允许我们直飞旧金山，所以我只好在突尼斯机场不耐烦地等待。"}},{"pos":"PHRASE 短语","cn":"（尤指因生气或吃惊而）突然转身","en":"If you turn on your heel or spin on your heel, you suddenly turn round, especially because you are angry or surprised.","ex":{"en":"He simply turned on his heel and walked away.","cn":"他突然就转身走开了。"}},{"pos":"PHRASE 短语","cn":"逃走;脚底开溜","en":"If you take to your heels, you run away.","ex":{"en":"He stood, for a moment, staring defiantly back at her, then took to his heels.","cn":"他站着不服地回瞪了她一会儿，然后就逃走了。"}},{"pos":"","cn":"","en":"head over heels→see: ; to drag your heels→see: ;"},{"pos":"","cn":"","en":"相关词组：heel over"}]},"examples":[{"en":"News of rising unemployment followed hard on the heels of falling export figures.","cn":"出口数字下降之后紧接着就是失业率上升的消息。"},{"en":"He fled from the stadium with the police at his heels.","cn":"他逃离了运动场，警察在后面紧追不舍。"}]},"housewife":{"media":{"uk":"media/uk/housewife__gb_1.mp3","us":"media/us/housewife__us_1.mp3"},"oxford":{"phon":"ˈhaʊswaɪf","pos":"noun","senses":[{"en":"a woman who stays at home to cook, clean, take care of the children, etc. while her husband or partner goes out to work","cn":"主妇；家庭妇女"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"家庭主妇;家庭妇女","en":"A housewife is a married woman who does not have a paid job, but instead looks after her home and children.","ex":{"en":"...a 42-year-old housewife from Brisbane.","cn":"来自布里斯班的42岁家庭主妇"}}]}},"hay":{"oxford":{"phon":"heɪ","pos":"noun","senses":[{"en":"grass that has been cut and dried and is used as food for animals","cn":"（用作饲料的）干草，草料","ex":{"en":"a bale of hay","cn":"一大捆干草"}},{"en":"a small amount of money","cn":"少量的钱","lab":"North American English, informal，，"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（作饲料用的）干草","en":"Hay is grass which has been cut and dried so that it can be used to feed animals.","ex":{"en":"...bales of hay.","cn":"一捆捆干草"}},{"pos":"PHRASE 短语","cn":"趁太阳好晒草;抓紧有利时机;不失良机","en":"If you say that someone is making hay or is making hay while the sun shines, you mean that they are taking advantage of a situation that is favourable to them while they have the chance to.","ex":{"en":"We knew that war was coming, and were determined to make hay while we could.","cn":"我们知道战争即将爆发，决心要趁早抓住有利时机。"}}]},"media":{"uk":"media/uk/hay__gb_1.mp3","us":"media/us/hay__us_1.mp3"},"examples":[{"en":"a bale of hay","cn":"一大捆干草"}]},"hell":{"oxford":{"phon":"hel","pos":"noun","senses":[{"en":"the place believed to be the home of devils and where bad people go after death","cn":"地狱","g":"[singular]","ex":{"en":"He was terrified of going to hell when he died.","cn":"他以前害怕死后下地狱。"}},{"en":"a very unpleasant experience or situation in which people suffer very much","cn":"苦难的经历；悲惨的境况","g":"[uncountable, singular]","ex":{"en":"The last three months have been hell.","cn":"过去的三个月真受罪。"}},{"en":"a swear word that some people use when they are annoyed or surprised or to emphasize something. Its use is offensive to some people.","cn":"（有人认为含冒犯意）该死，见鬼","g":"[uncountable]","lab":"North American English","ex":{"en":"Oh hell, I've burned the pan.","cn":"真该死，我把锅烧煳了。"}}]},"media":{"uk":"media/uk/hell__gb_1.mp3","us":"media/us/hell__us_1.mp3"},"examples":[{"en":"I can't really afford it, but, what the hell (= it doesn't matter), I'll get it anyway.","cn":"实在说我是买不起，但管它呢，无论如何我买定了。"},{"en":"He was a dirty player and loved to kick hell out of the opposition.","cn":"他是个不讲体育道德的球员，喜欢猛力冲撞对方。"}]},"hard-won":{"oxford":{"phon":"ˌhɑːd ˈwʌn","pos":"adjective","senses":[{"en":"that you only get after fighting or working hard for it","cn":"经奋斗（或努力）得到的；来之不易的","ex":{"en":"She was not going to give up her hard-won freedom so easily.","cn":"她不会这么轻易地放弃得来不易的自由。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"来之不易的;努力争取的","en":"If you describe something that someone has gained or achieved as hard-won, you mean that they worked hard to gain or achieve it.","ex":{"en":"The dispute could destroy Australia's hard-won reputation for industrial stability.","cn":"这场纠纷可能会让澳大利亚劳资关系稳定这一来之不易的名声毁于一旦。"}}]},"media":{"uk":"media/uk/hard_won_1_gb_1.mp3","us":"media/us/hard_won_1_us_1.mp3"},"examples":[{"en":"She was not going to give up her hard-won freedom so easily.","cn":"她不会这么轻易地放弃得来不易的自由。"},{"en":"her hard-won independence","cn":"她得来不易的独立"}]},"highway":{"media":{"uk":"media/uk/highway__gb_1.mp3","us":"media/us/highway__us_1.mp3"},"oxford":{"phon":"ˈhaɪweɪ","pos":"noun","senses":[{"en":"a main road for travelling long distances, especially one connecting and going through cities and towns","cn":"（尤指城镇间的）公路，干道，交通要道","lab":"especially North American English","ex":{"en":"Plans were being made for the construction of a new interstate highway system.","cn":"正在制定建设新的州际公路系统的计划。"}},{"en":"a public road","cn":"公用通道","lab":"British English, formal，，","ex":{"en":"A parked car was obstructing the highway.","cn":"一辆停放的汽车堵住了通道。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指城市间的）公路","en":"A highway is a main road, especially one that connects towns or cities.","ex":{"en":"I crossed the highway, dodging the traffic.","cn":"我避开车流穿过了公路。"}}]},"examples":[{"en":"A parked car was obstructing the highway.","cn":"一辆停放的汽车堵住了通道。"},{"en":"Highway patrol officers closed the road.","cn":"公路巡警关闭了这条路。"}]},"he'll":{"media":{"uk":"media/uk/he_ll_1_gb_1.mp3","us":"media/us/he_ll_1_us_1.mp3"},"oxford":{"phon":"hiːl","pos":"short form","senses":[{"en":"he will","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（he will 的常用口语形式）","en":"He'll is the usual spoken form of 'he will'.","ex":{"en":"By the time he's twenty he'll know everyone worth knowing in Washington.","cn":"到20岁时，他就会认识华盛顿所有值得认识的人。"}}]},"examples":[{"en":"Don’t worry, he’ll be there.","cn":"别担心﹐他会去那里的。"}]},"high-speed":{"oxford":{"phon":"ˌhaɪ ˈspiːd","pos":"adjective","senses":[{"en":"that travels, works or happens very fast","cn":"高速的；高效率的；迅速的","ex":{"en":"We are talking about a network of modern highways, high-speed trains, airports and air routes.","cn":"我们谈的是一个由现代高速公路、高速列车、机场和空中航线组成的网络。"}}]},"media":{"img":["media/pic/trains_comp.jpg","media/thumb/highspeedtrain.jpg"],"uk":"media/uk/high_speed_1_gb_1.mp3","us":"media/us/high_speed_1_us_1.mp3"},"examples":[{"en":"a high-speed car chase","cn":"高速汽车追逐"},{"en":"a high-speed train","cn":"高速列车"}]},"hi":{"oxford":{"phon":"haɪ","pos":"exclamation","senses":[{"en":"used to say hello","cn":"（招呼语）你好，嗨","ex":{"en":"Hi guys!","cn":"嗨，伙计们！"}}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"（用于非正式场合）嗨，你好","en":"In informal situations, you say 'hi' to greet someone.","ex":{"en":"'Hi, Liz,' she said shyly.","cn":"“你好，利兹，”她腼腆地说。"}}]},"media":{"uk":"media/uk/hi__gb_1.mp3","us":"media/us/hi__us_1.mp3"},"examples":[{"en":"Hi guys!","cn":"嗨，伙计们！"},{"en":"Hi, there! How're you doing?","cn":"喂！你好吗？"}]},"headmistress":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（中小学的）女校长","en":"A headmistress is a woman who is the head teacher of a school."}]},"media":{"uk":"media/ldoce/hwd/bre/6/headmistress0205.mp3","us":"media/ldoce/hwd/ame/3/headmistress.mp3"},"oxford":{"phon":"ˌhedˈmɪstrəs","pos":"noun","senses":[{"en":"a female head teacher, especially of a private school","cn":"（尤指私立学校的）女校长","lab":"British English"}]}},"heritage":{"media":{"uk":"media/uk/heritage__gb_1.mp3","us":"media/us/heritage__us_1.mp3"},"oxford":{"phon":"ˈherɪtɪdʒ","pos":"noun","senses":[{"en":"the history, traditions, buildings and objects that a country or society has had for many years and that are considered an important part of its character","cn":"遗产（国家或社会长期形成的文化产物，如历史、传统、建筑、物品等）","ex":{"en":"Spain’s rich cultural heritage","cn":"西班牙的丰富文化遗产"}},{"en":"a person's ethnic or religious background; the countries, cultures, religious groups, etc. that a person's parents or ancestors come from","cn":"一个人的种族或宗教背景；一个人的父母或祖先来自的国家、文化、宗教团体等","ex":{"en":"What's your heritage?","cn":"你的遗产是什么？"}},{"en":"used to describe a traditional product, brand, type of animal or plant variety, especially one that is old-fashioned, rare and of high quality","cn":"传统的，历史悠久的（尤指老式、稀有且优质）","ex":{"en":"Cotswold sheep are considered a heritage breed in Canada.","cn":"科茨沃尔德羊被认为是加拿大的传统品种。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（国家的）遗产，传统","en":"A country's heritage is all the qualities, traditions, or features of life there that have continued over many years and have been passed on from one generation to another.","ex":{"en":"The historic building is as much part of our heritage as the paintings.","cn":"这座历史建筑和这些画一样，都是留给我们的文化遗产的一部分。"}}]},"examples":[{"en":"The building is part of our national heritage.","cn":"这个建筑是我们民族遗产的一部分。"},{"en":"Spain's rich cultural heritage","cn":"西班牙的丰富文化遗产"}]},"husband":{"media":{"uk":"media/uk/husband__gb_1.mp3","us":"media/us/husband__us_1.mp3"},"oxford":{"phon":"ˈhʌzbənd","pos":"noun","senses":[{"en":"the man that somebody is married to; a married man","cn":"丈夫","lab":"especially North American English","ex":{"en":"This is my husband, Steve.","cn":"这位是我的丈夫，史蒂夫。"}},{"en":"to use something very carefully and make sure that you do not waste it","cn":"节俭使用","ex":{"en":"Times are hard and we have to husband our resources.","cn":"时代很艰难，我们必须节约资源。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"丈夫","en":"A woman's husband is the man she is married to.","ex":{"en":"Eva married her husband Jack in 1957","cn":"伊娃和丈夫杰克于1957年结的婚。"}},{"pos":"VERB 动词","cn":"节约地使用;节省","en":"If you husband something valuable, you use it carefully and do not waste it.","ex":{"en":"Husbanding precious resources was part of rural life.","cn":"节约地使用宝贵的资源是乡村生活的一部分。"}}]},"examples":[{"en":"They lived together as husband and wife (= as if they were married) for years.","cn":"他们像夫妻一样共同生活了很多年。"},{"en":"This is my husband, Steve.","cn":"这位是我的丈夫，史蒂夫。"}]},"himself":{"media":{"uk":"media/uk/himself__gb_1.mp3","us":"media/us/himself__us_1.mp3"},"oxford":{"phon":"hɪmˈself","pos":"pronoun","senses":[{"en":"used when the man or boy who performs an action is also affected by it","cn":"（用作男性的反身代词）他自己，自己","ex":{"en":"He introduced himself.","cn":"他作了自我介绍。"}},{"en":"used to emphasize the male subject or object of a sentence","cn":"（强调句中的男性主语或宾语）","ex":{"en":"The doctor said so himself.","cn":"是医生本人这么说的。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"他自己;它自己（指雄性动物）","en":"You use himself to refer to a man, boy, or male animal.","ex":{"en":"He poured himself a whisky and sat down in the chair","cn":"他给自己倒了一杯威士忌，然后坐在椅子上。"}},{"pos":"PRON-REFL 反身代词","cn":"（书面英语中泛指人）他自己，她自己（有些人不喜欢这种用法，更倾向于使用 himself or herself 或 themselves）","en":"In written English, himself is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'himself or herself' or 'themselves'.","ex":{"en":"The child's natural way of expressing himself is play","cn":"孩子表达自己的本能方法就是玩耍。"}},{"pos":"PRON-REFL 反身代词","cn":"（一些宗教中指）上帝","en":"In some religions, Himself is used to refer to God.","ex":{"en":"He thanked God for concealing Himself from the wise and revealing Himself to the simple.","cn":"他感谢上帝，因为上帝在自作聪明的人面前自行隐匿，在心地纯洁的人面前则显现神迹。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"（用于加强语气，有时代替 him 充当宾语）他本人，它本身","en":"You use himself to emphasize the person or thing that you are referring to. Himself is sometimes used instead of 'him' as the object of a verb or preposition.","ex":{"en":"There's no evidence that the Prime Minister himself cancelled the visit.","cn":"没有证据表明是首相本人取消了访问。"}}]},"examples":[{"en":"He has the house to himself during the week.","cn":"一周之中除周末外他可以一人住这座房子。"},{"en":"He didn't seem quite himself this morning.","cn":"他今天上午似乎有点不对劲。"}]},"happily":{"media":{"uk":"media/uk/happily__gb_1.mp3","us":"media/us/happily__us_1.mp3"},"oxford":{"phon":"ˈhæpɪli","pos":"adverb","senses":[{"en":"in a cheerful way; with feelings of pleasure","cn":"快乐地；高兴地；满足地","ex":{"en":"children playing happily on the beach","cn":"在海滩上嬉戏的孩子们"}},{"en":"by good luck","cn":"幸运地","ex":{"en":"Happily, the damage was only slight.","cn":"所幸的是，损伤不大。"}},{"en":"willingly","cn":"欣然；情愿地","ex":{"en":"I'll happily help, if I can.","cn":"如果我能帮忙，我倒很乐意。"}},{"en":"in a way that is suitable or appropriate","cn":"合适地；恰当地","lab":"formal","ex":{"en":"This suggestion did not fit very happily with our existing plans.","cn":"这个建议与我们目前的计划不太契合。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"幸运地;幸运的是","en":"You can add happily to a statement to indicate that you are glad that something happened or is true.","ex":{"en":"Happily, his neck injuries were not serious","cn":"很幸运，他脖子上的伤并不严重。"}}]},"examples":[{"en":"And they all lived happily ever after (= used as the end of a fairy tale ).","cn":"从此他们都过着幸福美满的生活（用作童话故事的结尾）。"},{"en":"This suggestion did not fit very happily with our existing plans.","cn":"这个建议与我们目前的计划不十分契合。"}]},"hardens":{"lemma":"harden"},"handsome":{"media":{"uk":"media/uk/handsome__gb_1.mp3","us":"media/us/handsome__us_1.mp3"},"oxford":{"phon":"ˈhænsəm","pos":"adjective","senses":[{"en":"attractive","cn":"英俊的；漂亮的；有魅力的","ex":{"en":"He had an interesting and rather handsome face.","cn":"他有一张有趣且相当英俊的脸。"}},{"en":"attractive, with large strong features rather than small light ones","cn":"健美的","ex":{"en":"a tall, handsome woman","cn":"一位高个头的健美女子"}},{"en":"beautiful to look at","cn":"美观的；悦目的","ex":{"en":"a handsome horse/house/city","cn":"漂亮的马／房子／城市"}},{"en":"large in amount or quantity","cn":"数量大的","ex":{"en":"They sold the house two years later at a handsome profit.","cn":"两年后他们卖了那所房子，获得一大笔利润。"}},{"en":"generous","cn":"大方的；慷慨的；气量大的","ex":{"en":"She paid him a handsome compliment.","cn":"她大大赞扬了他一番。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（男子）漂亮的，英俊的，帅气的","en":"A handsome man has an attractive face with regular features. →see usage note at:","ex":{"en":"...a tall, dark, handsome sheep farmer.","cn":"高个子、黑皮肤的英俊养羊人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（女子）端庄健美的","en":"A handsome woman has an attractive appearance with features that are large and regular rather than small and delicate.","ex":{"en":"...an extremely handsome woman with a beautiful voice.","cn":"有着甜美嗓音的非常健美的女子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（金额）相当大的，可观的，优厚的","en":"A handsome sum of money is a large or generous amount.","ex":{"en":"They will make a handsome profit on the property.","cn":"他们会从这片地产中赚取丰厚的利润。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（建筑物、庭院等）宽敞而美观的，堂皇的，雄伟的","en":"A place such as a building or garden that is handsome is large and well made with an attractive appearance.","ex":{"en":"...the ports of Dubrovnik and Zadar, with their handsome Renaissance buildings.","cn":"拥有雄伟的文艺复兴时期建筑的杜布罗夫尼克港和扎达尔港"}},{"pos":"ADJ 形容词","cn":"（获胜）比分悬殊的，遥遥领先的","en":"If someone has a handsome win or a handsome victory, they get many more points or votes than their opponent.","ex":{"en":"The opposition won a handsome victory in the election.","cn":"反对党在竞选中以高票获胜。"}}]},"examples":[{"en":"He was aptly described as ‘ tall, dark, and handsome ’.","cn":"他被恰如其分地描述为“高大黝黑、相貌堂堂”。"},{"en":"He's the most handsome man I've ever met.","cn":"他是我见过的最俊美的男子。"}]},"hates":{"lemma":"hate","media":{"img":["media/pic/hats_comp.jpg","media/thumb/panama.jpg"],"uk":"media/uk/hat__gb_1.mp3","us":"media/us/hat__us_1.mp3"}},"henry":{"media":{"uk":"media/uk/henry__gb_1.mp3","us":"media/us/henry__us_1.mp3"},"oxford":{"phon":"ˈhenri","pos":"noun","senses":[{"en":"a unit for measuring the inductance in an electric circuit","cn":"亨，亨利（电感单位）"},{"en":"a first name for boys","cn":"亨利（男子名）","pos":""}]}},"haves":{"lemma":"have","media":{"uk":"media/uk/haves__gb_1.mp3","us":"media/us/haves__us_1.mp3"}},"hovering":{"lemma":"hover"},"humanity":{"media":{"uk":"media/uk/humanity__gb_1.mp3","us":"media/us/humanity__us_1.mp3"},"oxford":{"phon":"hjuːˈmænəti","pos":"noun","senses":[{"en":"people in general","cn":"（统称）人；人类","g":"[uncountable]","lab":"British English","ex":{"en":"He was found guilty of crimes against humanity.","cn":"他被判犯有反人类罪。"}},{"en":"the state of being a person rather than a god, an animal or a machine","cn":"人性","g":"[uncountable]","ex":{"en":"The story was used to emphasize the humanity of Jesus.","cn":"人们用这个故事来强调耶稣人性的一面。"}},{"en":"the quality of being kind to people and animals by making sure that they do not suffer more than is necessary; the quality of being humane","cn":"人道；仁慈","g":"[uncountable]","ex":{"en":"The judge was praised for his courage and humanity.","cn":"法官的勇气和人道受到称赞。"}},{"en":"the subjects of study that are about the way people think and behave, for example literature, language, history and philosophy","cn":"人文学科","g":"[plural]","ex":{"en":"The college offers a wide range of courses in the arts and humanities.","cn":"学院开设多门艺术和人文课程。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"人类;（总称）人","en":"All the people in the world can be referred to as humanity .","ex":{"en":"They face charges of committing crimes against humanity.","cn":"他们被控犯有反人类罪。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人性;人的属性","en":"A person's humanity is their state of being a human being, rather than an animal or an object.","ex":{"en":"...a man who's almost lost his humanity in his bitter hatred of his rivals.","cn":"因痛恨竞争对手而几乎丧失人性的男子"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人道;仁慈;博爱","en":"Humanity is the quality of being kind, thoughtful, and sympathetic towards others.","ex":{"en":"Her speech showed great maturity and humanity.","cn":"她的演讲思想高度成熟，并且洋溢着博爱精神。"}},{"pos":"N-PLURAL 复数名词","cn":"（历史、哲学、文学等）人文学科","en":"The humanities are the subjects such as history, philosophy, and literature which are concerned with human ideas and behaviour.","ex":{"en":"...students majoring in the humanities.","cn":"主修人文学科的学生"}}]},"examples":[{"en":"The story was used to emphasize the humanity of Jesus.","cn":"人们用这个故事来强调耶稣人性的一面。"},{"en":"united by a sense of common humanity","cn":"因一种同是人的情感而团结在一起"}]},"herself":{"media":{"uk":"media/uk/herself__gb_1.mp3","us":"media/us/herself__us_1.mp3"},"oxford":{"phon":"hɜːˈself","pos":"pronoun","senses":[{"en":"used when the woman or girl who performs an action is also affected by it","cn":"（用作女性的反身代词）她自己，自己","ex":{"en":"She hurt herself.","cn":"她弄伤了自己。"}},{"en":"used to emphasize the female subject or object of a sentence","cn":"（强调句中的女性主语或宾语）","ex":{"en":"She told me the news herself.","cn":"是她本人告诉我这个消息的。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"她自己（指女性或雌性动物）","en":"You use herself to refer to a woman, girl, or female animal.","ex":{"en":"She let herself out of the room","cn":"她走出了房间。"}},{"pos":"PRON-REFL 反身代词","cn":"（书面英语中泛指人）他自己，她自己（有些人不喜欢这种用法，更倾向于使用 himself or herself 或 themselves）","en":"In written English, herself is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'himself or herself' or 'themselves'.","ex":{"en":"How can anyone blame her for actions for which she feels herself to be in no way responsible?","cn":"她认为自己对这些行动不负有责任，别人怎么还能因此而责备她呢？"}},{"pos":"PRON-REFL 反身代词","cn":"（指国家或民族）她自己，它自己","en":"Herself is sometimes used to refer to a country or nation.","ex":{"en":"Britain's dream of herself began to fade.","cn":"不列颠民族的梦想开始渐渐幻灭。"}},{"pos":"PRON-REFL 反身代词","cn":"（指汽车、机器或船）她自己，它自己","en":"People sometimes use herself to refer to a car, machine, or ship.","ex":{"en":"The ship adjusted herself to the roll and rhythm of the sea.","cn":"船随着海水的起伏节奏时起时落。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"（用于加强语气，有时代替 her 作动词或介词的宾语）她本人，它本身","en":"You use herself to emphasize the person or thing that you are referring to. Herself is sometimes used instead of 'her' as the object of a verb or preposition.","ex":{"en":"She's so beautiful herself","cn":"她本人是如此美丽。"}}]},"examples":[{"en":"She wants a room all to herself.","cn":"她想要一个完全属于自己的房间。"},{"en":"She didn't seem quite herself this morning.","cn":"她今天早上好像有点不太对劲。"}]},"heated":{"oxford":{"phon":"ˈhiːtɪd","pos":"adjective","senses":[{"en":"full of anger and excitement","cn":"愤怒的；激烈的；十分激动的","ex":{"en":"a heated argument/debate","cn":"激烈的争论／辩论"}},{"en":"made warmer using a heater","cn":"（用加热器）加热了的","ex":{"en":"a heated swimming pool","cn":"温水游泳池"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（讨论或争吵）激烈的","en":"A heated discussion or quarrel is one where the people involved are angry and excited.","ex":{"en":"It was a very heated argument and they were shouting at each other","cn":"争论非常激烈，他们相互之间大喊大叫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"发怒的;激动的","en":"If someone gets heated about something, they get angry and excited about it.","ex":{"en":"You will understand that people get a bit heated about issues such as these","cn":"你要明白，对于这类问题人们不免会有些激动。"}}]},"media":{"uk":"media/uk/heated__gb_1.mp3","us":"media/us/heated__us_1.mp3"},"examples":[{"en":"‘You had no right!’ she said heatedly. “","cn":"你没有权利！”她愤怒地说。"},{"en":"She became very heated.","cn":"她不禁怒火中烧。"}],"base":"heat"},"hebrew":{"media":{"uk":"media/uk/hebrew__gb_1.mp3","us":"media/us/hebrew__us_1.mp3"},"oxford":{"phon":"ˈhiːbruː","pos":"noun","senses":[{"en":"a member of an ancient people living in what is now Israel and Palestine. Their writings and traditions form the basis of the Jewish religion.","cn":"希伯来人"},{"en":"the language traditionally used by the Hebrew people","cn":"希伯来语"},{"en":"a modern form of the Hebrew language which is the official language of modern Israel","cn":"现代希伯来语（现代以色列的官方语言）"},{"en":"of or connected with the Hebrew language or people","cn":"希伯来语的；希伯来人的","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"希伯来语","en":"Hebrew is a language that was spoken by Jews in former times. A modern form of Hebrew is spoken now in Israel.","ex":{"en":"He is a fluent speaker of Hebrew.","cn":"他说一口流利的希伯来语。"}},{"pos":"N-COUNT 可数名词","cn":"希伯来人（旧时指犹太人）","en":"In former times, a Hebrew was a Jewish person.","ex":{"en":"...the exodus of the Hebrews from Egypt.","cn":"希伯来人出埃及之事"}},{"pos":"ADJ 形容词","cn":"希伯来语的;希伯来人的","en":"Hebrew means belonging to or relating to the Hebrew language or people.","ex":{"en":"...the respected Hebrew newspaper Haaretz","cn":"受到尊崇的希伯来语报纸《国土报》"}}]}},"hands-on":{"oxford":{"phon":"ˌhændz ˈɒn","pos":"adjective","senses":[{"en":"doing something rather than just talking about it","cn":"动手的；实际操作的","ex":{"en":"hands-on computer training","cn":"计算机操作培训"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（经历或工作）亲身实践的，实际操作的","en":"Hands-on experience or work involves actually doing a particular thing, rather than just talking about it or getting someone else to do it.","ex":{"en":"Ninety-nine per cent of primary pupils now have hands-on experience of computers","cn":"现在99%的小学生都亲手操作过电脑。"}}]},"media":{"uk":"media/uk/hands_on_1_gb_1.mp3","us":"media/us/hands_on_1_us_1.mp3"},"examples":[{"en":"to gain hands-on experience of industry","cn":"获得勤劳工作的实际经验"},{"en":"a hands-on style of management","cn":"事必躬亲的管理方式"}]},"havoc":{"media":{"uk":"media/uk/havoc__gb_1.mp3","us":"media/us/havoc__us_1.mp3"},"oxford":{"phon":"ˈhævək","pos":"noun","senses":[{"en":"a situation in which things are seriously damaged, destroyed or very confused","cn":"灾害；祸患；浩劫","ex":{"en":"The floods caused havoc throughout the area.","cn":"洪水给整个地区带来了灾害。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"大破坏;大毁坏;大混乱","en":"Havoc is great disorder, and confusion.","ex":{"en":"Rioters caused havoc in the centre of the town.","cn":"暴乱分子在市中心制造了极大混乱。"}},{"pos":"PHRASE 短语","cn":"给…造成混乱（或破坏）","en":"If one thing plays havoc with another or wreaks havoc on it, it prevents it from continuing or functioning as normal, or damages it.","ex":{"en":"Drug addiction soon played havoc with his career","cn":"毒瘾很快就毁掉了他的事业。"}}]},"examples":[{"en":"Continuing strikes are beginning to play havoc with the national economy.","cn":"持续的罢工开始严重破坏国家经济。"},{"en":"The floods caused havoc throughout the area.","cn":"洪水给整个地区带来了灾害。"}]},"halfpenny":{"media":{"uk":"media/uk/halfpenny__gb_1.mp3","us":"media/us/halfpenny__us_1.mp3"},"oxford":{"phon":"ˈhɑːfpeni","pos":"noun","senses":[{"en":"a British coin in use until 1971, worth half a penny. There were 480 halfpennies in a pound.","cn":"半便士硬币（1971 年前使用的英国硬币，480 半便士硬币为一英镑）"},{"en":"a British coin in use between 1971 and 1984, worth half a penny. There were 200 halfpennies in a pound.","cn":"半便士硬币（1971 至 1984 年间使用的英国硬币，200 半便士硬币为一英镑）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（英国旧币制中的）半便士硬币","en":"A halfpenny was a small British coin which was worth half a penny."}]}},"heavily":{"media":{"uk":"media/uk/heavily__gb_1.mp3","us":"media/us/heavily__us_1.mp3"},"oxford":{"phon":"ˈhevɪli","pos":"adverb","senses":[{"en":"to a great degree; in large amounts","cn":"在很大程度上；大量地","ex":{"en":"It was raining heavily.","cn":"雨下得很大。"}},{"en":"with a lot of force or effort","cn":"以猛力；沉重地","ex":{"en":"She fell heavily to the ground.","cn":"她重重地摔倒在地。"}},{"en":"with a large, solid and strong body","cn":"身材壮实"},{"en":"slowly and loudly","cn":"缓慢又高声地","ex":{"en":"She was now breathing heavily.","cn":"她喘着粗气。"}},{"en":"in a slow way that sounds as though you are worried or sad","cn":"缓慢而忧郁地；悲伤地","ex":{"en":"He sighed heavily.","cn":"他长叹了一声。"}},{"en":"in a way that makes you feel uncomfortable or anxious","cn":"令人心情沉重","ex":{"en":"Silence hung heavily in the room.","cn":"房间里寂若死灰。"}},{"en":"full of or loaded with heavy things","cn":"装满（或装载）重物的；重载的","ex":{"en":"a heavily loaded van","cn":"满载重物的货车"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"缓慢沉痛地;费力地;沉重地","en":"If someone says something heavily, they say it in a slow way which shows a feeling such as sadness, tiredness, or annoyance.","ex":{"en":"'I didn't even think about her,' he said heavily.","cn":"“我甚至没有想过她，”他沉重地说道。"}}]},"examples":[{"en":"The burden of guilt weighed heavily on his mind.","cn":"愧疚之情压得他透不过气来。"},{"en":"They are both heavily involved in politics.","cn":"他们俩都深深卷入政治中。"}]},"hype":{"media":{"uk":"media/uk/hype__gb_1.mp3","us":"media/us/hype__us_1.mp3"},"oxford":{"phon":"haɪp","pos":"noun","senses":[{"en":"advertisements and discussion in the media telling the public about a product and about how good or important it is","cn":"夸张的宣传；吹捧；炒作","ex":{"en":"marketing/media hype","cn":"夸张的促销／媒体广告"}},{"en":"to advertise something a lot and make its good qualities seem better than they actually are, in order to get a lot of public attention for it","cn":"夸张地宣传（某事物）","ex":{"en":"This week his much hyped new movie opens in London.","cn":"本周他那部被大肆炒作的新电影在伦敦上映。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"天花乱坠的广告宣传;炒作","en":"Hype is the use of a lot of publicity and advertising to make people interested in something such as a product.","ex":{"en":"We are certainly seeing a lot of hype by some companies","cn":"我们无疑已经看到来自一些公司的大肆宣传。"}},{"pos":"VERB 动词","cn":"大肆宣传（或吹捧）","en":"To hype a product means to advertise or praise it a lot.","ex":{"en":"We had to hype the film to attract the financiers","cn":"我们不得不热炒这部电影以吸引投资人。"}},{"pos":"","cn":"","en":"相关词组：hype up"}]},"examples":[{"en":"Don't believe all the hype — the book isn't that good.","cn":"别相信那些天花乱坠的宣传，那本书没那么好。"},{"en":"This week his much hyped new movie opens in London.","cn":"本周他那部被大肆炒作的新电影在伦敦上映。"}]},"happen":{"media":{"uk":"media/uk/happen__gb_1.mp3","us":"media/us/happen__us_1.mp3"},"oxford":{"phon":"ˈhæpən","pos":"verb","senses":[{"en":"to take place, especially without being planned","cn":"（尤指偶然）发生，出现","g":"[intransitive]","ex":{"en":"You'll never guess what's happened!","cn":"你根本猜不到出了什么事！"}},{"en":"to take place as the result of something","cn":"（作为结果）出现，发生","g":"[intransitive]","ex":{"en":"She pressed the button but nothing happened.","cn":"她按下按钮，但什么反应也没有。"}},{"en":"to do or be something by chance","cn":"碰巧；恰好","g":"[transitive]","ex":{"en":"She happened to be out when we called.","cn":"我们打电话时她刚巧不在。"}},{"en":"used to tell somebody something, especially when you are disagreeing with them or annoyed by what they have said","cn":"（向对方表示异议或不悦等）","g":"[transitive]","ex":{"en":"That happens to be my mother you're talking about!","cn":"你们谈论的是我母亲！"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（偶然）发生，出现","en":"Something that happens occurs or is done without being planned.","ex":{"en":"We cannot say for sure what will happen","cn":"我们无法确定会发生什么事。"}},{"pos":"VERB 动词","cn":"（作为结果）发生，产生","en":"If something happens, it occurs as a result of a situation or course of action.","ex":{"en":"She wondered what would happen if her parents found her","cn":"她不知道如果父母找到自己会有什么结果。"}},{"pos":"VERB 动词","cn":"（尤指不愉快的事）发生（在…身上）;(某人)遭到;遇到","en":"When something, especially something unpleasant, happens to you, it takes place and affects you.","ex":{"en":"If we had been spotted at that point, I don't know what would have happened to us","cn":"如果当时我们被发现了，我不知道会有什么后果。"}},{"pos":"VERB 动词","cn":"碰巧;凑巧","en":"If you happen to do something, you do it by chance. If it happens that something is the case, it occurs by chance.","ex":{"en":"We happened to discover we had a friend in common","cn":"我们凑巧发现我们有一个共同的朋友。"}},{"pos":"PHRASE 短语","cn":"碰巧，恰恰（尤引出令人意外的事）","en":"You use as it happens in order to introduce a statement, especially one that is rather surprising.","ex":{"en":"She called Amy to see if she had any idea of her son's whereabouts. As it happened, Amy had.","cn":"她打电话给埃米，看她是否知道自己儿子的行踪。埃米还真就知道。"}}]},"examples":[{"en":"‘Sorry — I've spilt some wine.’ ‘Never mind. These things happen.’ “","cn":"对不起，我弄洒了些酒。” “没关系。这种事在所难免。”"},{"en":"What happens if nobody comes to the party?","cn":"要是没有人来参加聚会，会怎么样呢？"}]},"hear":{"media":{"uk":"media/uk/hear__gb_1.mp3","us":"media/us/hear__us_1.mp3"},"oxford":{"phon":"hɪə(r)","pos":"verb","senses":[{"en":"to be aware of sounds with your ears","cn":"听见；听到","g":"[intransitive, transitive]","ex":{"en":"I can't hear very well.","cn":"我听觉不太好。"}},{"en":"to listen or pay attention to somebody/something","cn":"听；注意听；倾听","g":"[transitive]","ex":{"en":"Did you hear that play on the radio last night?","cn":"你昨晚收听了那出广播剧吗？"}},{"en":"to be told about something","cn":"听说；得知","g":"[intransitive, transitive]","ex":{"en":"Haven't you heard? She resigned.","cn":"你还没听说吗？她辞职了。"}},{"en":"to listen to and judge a case in court","cn":"审理；听审","g":"[transitive]","ex":{"en":"The appeal was heard in private.","cn":"这件上诉案不公开审理。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"听见;听到","en":"When you hear a sound, you become aware of it through your ears.","ex":{"en":"She heard no further sounds","cn":"她再没有听到别的声音了。"}},{"pos":"VERB 动词","cn":"听，聆听（演讲、音乐等）","en":"If you hear something such as a lecture or a piece of music, you listen to it.","ex":{"en":"You can hear commentary on the match in about half an hour's time","cn":"大约半小时后就能听到这场比赛的解说了。"}},{"pos":"VERB 动词","cn":"脑际响起","en":"If you say that you can hear someone saying something, you mean that you are able to imagine hearing it.","ex":{"en":"Can't you just hear John Motson now?","cn":"你脑海里现在没有响起约翰·莫特森的声音吗？"}},{"pos":"VERB 动词","cn":"（法官或法庭）审理（案件），听取（证词）","en":"When a judge or a court of law hears a case, or evidence in a case, they listen to it officially in order to make a decision about it.","ex":{"en":"The jury have heard evidence from defence witnesses","cn":"陪审团已经听取了辩方证人的证词。"}},{"pos":"VERB 动词","cn":"接到…的信（或电话）","en":"If you hear from someone, you receive a letter or telephone call from them.","ex":{"en":"Drop us a line, it's always great to hear from you","cn":"给我们写封短信，能收到你的信总是让人很高兴。"}},{"pos":"VERB 动词","cn":"（辩论或讨论中）倾听（意见或情况）","en":"In a debate or discussion, if you hear from someone, you listen to them giving their opinion or information.","ex":{"en":"What are you hearing from people there?","cn":"你在那里都听到人们说了些什么？"}},{"pos":"VERB 动词","cn":"听说;得知;了解到","en":"If you hear some news or information about something, you find out about it by someone telling you, or from the radio or television.","ex":{"en":"My mother heard of this school through Leslie","cn":"我母亲是从莱斯利那里知道这所学校的。"}},{"pos":"VERB 动词","cn":"听说（过…）;（对…）有一点了解","en":"If you have heard of something or someone, you know about them, but not in great detail.","ex":{"en":"Many people haven't heard of reflexology.","cn":"很多人没听说过反射学。"}},{"pos":"PHRASE 短语","cn":"已经知道;早就听说过","en":"If you say that you have heard something before, you mean that you are not interested in it, or do not believe it, or are not surprised about it, because you already know about it or have experienced it.","ex":{"en":"Furness shrugs wearily. He has heard it all before","cn":"弗内斯疲倦地耸了耸肩。这事他早就全知道了。"}},{"pos":"CONVENTION 惯用语","cn":"“听见没有？”“你听到我的话了吗？”（要求对方注意听自己的话）","en":"If you say 'Do you hear?' or 'Did you hear me?' to someone, you are telling them in an angry or forceful way to pay attention to what you are saying.","ex":{"en":"If you don't get out I'll call the police. Do you hear?","cn":"如果你不出去，我就要报警了。听见没有？"}},{"pos":"CONVENTION 惯用语","cn":"说得对！说得好！（政治辩论或公众大会上对讲话人表示赞同的喝彩声）","en":"During political debates and public meetings, people sometimes say 'Hear hear!' to express their agreement with what the speaker is saying."},{"pos":"PHRASE 短语","cn":"太吵了;吵死人了","en":"If you say that you can't hear yourself think, you are complaining and emphasizing that there is a lot of noise, and that it is disturbing you or preventing you from doing something.","ex":{"en":"For God's sake shut up. I can't hear myself think!","cn":"看在老天爷的份上，闭嘴吧。吵死我了！"}},{"pos":"PHRASE 短语","cn":"不同意;不允许","en":"If you say that you won't hear of someone doing something, you mean that you refuse to let them do it.","ex":{"en":"I've always wanted to be an actor but Dad wouldn't hear of it","cn":"我一直想当个演员，但爸爸不同意。"}},{"pos":"","cn":"","en":"you could have heard a pin drop→see: ;"},{"pos":"","cn":"","en":"相关词组：hear out"}]},"examples":[{"en":"The last I heard of him he was living in Glasgow.","cn":"我最后一次听到他的消息时，他住在格拉斯哥。"},{"en":"If we don't get her a dog we'll never hear the end of it.","cn":"我们要是不给她弄条狗来，这事就没完没了。"}]},"hugely":{"media":{"uk":"media/uk/hugely__gb_1.mp3","us":"media/us/hugely__us_1.mp3"},"oxford":{"phon":"ˈhjuːdʒli","pos":"adverb","senses":[{"en":"extremely","cn":"极其；极度","ex":{"en":"hugely entertaining/important/popular/successful","cn":"极其有趣／重要／受欢迎／成功"}},{"en":"very much","cn":"非常；深深地；大大地","ex":{"en":"They intended to invest hugely in new technology.","cn":"他们打算在新技术方面投入大量资金。"}}]},"examples":[{"en":"They intended to invest hugely in new technology.","cn":"他们打算在新技术方面投入大量资金。"},{"en":"He turned around, grinning hugely.","cn":"他转过身来，咧着嘴乐。"}]},"hard-boiled":{"oxford":{"phon":"ˌhɑːd ˈbɔɪld","pos":"adjective","senses":[{"en":"boiled until the inside is hard","cn":"煮老的；煮硬的"},{"en":"not showing much emotion","cn":"不动感情的；不流露情感的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（蛋）煮得老的，煮硬的","en":"A hard-boiled egg has been boiled in its shell until the whole of the inside is solid."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）不动感情的，强硬的","en":"You use hard-boiled to describe someone who is tough and does not show much emotion.","ex":{"en":"She's hard-boiled, tough and funny.","cn":"她冷峻、坚韧而风趣。"}}]},"media":{"uk":"media/uk/hard_boiled_1_gb_1.mp3","us":"media/us/hard_boiled_1_us_1.mp3"},"examples":[{"en":"a hard-boiled marketing executive","cn":"一位强悍的营销主管"}]},"horseshoe":{"oxford":{"phon":"ˈhɔːsʃuː","pos":"noun","senses":[{"en":"a piece of curved iron that is attached with nails to the bottom of a horse’s foot. A horseshoe is often used as a symbol of good luck.","cn":"马蹄铁，马掌（常用来象征好运）"},{"en":"anything that is like a horseshoe in shape","cn":"马蹄铁形物","ex":{"en":"a horseshoe bend in the river","cn":"河道中的马蹄形弯曲"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"马蹄铁;马掌","en":"A horseshoe is a piece of metal shaped like a U, which is fixed with nails to the bottom of a horse's foot in order to protect it."},{"pos":"N-COUNT 可数名词","cn":"(尤指婚礼上用的）马蹄铁吉祥物","en":"A horseshoe is an object in the shape of a horseshoe which is used as a symbol of good luck, especially at a wedding."}]},"media":{"uk":"media/uk/horseshoe__gb_1.mp3","us":"media/us/horseshoe__us_1.mp3","img":["media/ldoce/img/horseshoe.jpg"]},"examples":[{"en":"a horseshoe bend in the river","cn":"河道中的马蹄形弯曲"}]},"hearing-impaired":{"collins":{"senses":[{"pos":"","cn":"听觉受损的;有听力障碍的","en":"A hearing-impaired person cannot hear as well as most people.","ex":{"en":"Some hearing-impaired children may work harder to overcome their handicap.","cn":"一些有听障的儿童可能需要花更大的力气来克服这一缺陷。"}}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41hearing-impair.mp3","us":"media/ldoce/hwd/ame/8/laadhearing-impaired.mp3"},"oxford":{"phon":"ˌhɪərɪŋ ɪmˈpeəd","pos":"adjective","senses":[{"en":"not able to hear well; partly or completely deaf","cn":"有听觉障碍的"}]}},"hadn't":{"media":{"uk":"media/uk/hadn_t_1_gb_1.mp3","us":"media/us/hadn_t_1_us_1.mp3"},"oxford":{"phon":"ˈhædnt","pos":"short form","senses":[{"en":"had not","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（had not 的常用口语形式）","en":"Hadn't is the usual spoken form of 'had not'."}]},"examples":[{"en":"If I hadn’t seen it myself, I’d never have believed it.","cn":""}]},"harness":{"media":{"uk":"media/uk/harness__gb_1.mp3","us":"media/us/harness__us_1.mp3","img":["media/ldoce/img/abseiling.jpg"]},"oxford":{"phon":"ˈhɑːnɪs","pos":"noun","senses":[{"en":"a set of narrow pieces of leather and metal pieces that is put around the head and body of an animal, especially a horse, so that the animal can be controlled and fastened to a carriage, etc.","cn":"挽具；马具","ex":{"en":"The sight of horses in harness hauling timber was common a hundred years ago.","cn":"一百年前，套着挽具的马匹拉木材的情景很常见。"}},{"en":"a set of straps (= long narrow pieces of a strong material) for fastening something to a person’s body or to keep them from moving off or falling","cn":"（用于人，起固定或保护作用的）系带，保护带","ex":{"en":"She fastened the safety harness tightly around her waist before starting the descent.","cn":"她把安全带牢牢地系在腰部后才开始下降。"}},{"en":"to put a harness on a horse or other animal; to attach a horse or other animal to something with a harness","cn":"给（马等）上挽具；用挽具把…套到…上","lab":"figurative","ex":{"en":"to harness a horse","cn":"给马上挽具"},"pos":"verb"},{"en":"to control and use the force or strength of something to produce power or to achieve something","cn":"控制，利用（以产生能量等）","ex":{"en":"attempts to harness the sun’s rays as a source of energy","cn":"利用日光作为能源的尝试"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"控制（情感）;利用（自然力）","en":"If you harness something such as an emotion or natural source of energy, you bring it under your control and use it.","ex":{"en":"...the movement's ability to harness the anger of all Ukrainians","cn":"该运动之疏解所有乌克兰人怒气的能力"}},{"pos":"N-COUNT 可数名词","cn":"（系在身上用以携带装备或限制其移动的）系带，背带","en":"A harness is a set of straps which fit under a person's arms and fasten round their body in order to keep a piece of equipment in place or to prevent the person moving from a place."},{"pos":"N-COUNT 可数名词","cn":"马具;挽具","en":"A harness is a set of leather straps and metal links fastened round a horse's head or body so that the horse can have a carriage, cart, or plough fastened to it."},{"pos":"VERB 动词","cn":"给（马等）套上挽具","en":"If a horse or other animal is harnessed, a harness is put on it, especially so that it can pull a carriage, cart, or plough.","ex":{"en":"On Sunday the horses were harnessed to a heavy wagon for a daylong ride over the Border.","cn":"星期天，马匹被套在一辆沉重的马车上，准备踏上长达一天的穿越边境之旅。"}},{"pos":"PHRASE 短语","cn":"互相配合;通力合作","en":"People or things who are working in harness are working together in order to achieve a particular aim.","ex":{"en":"At Opera North he will be in harness with Paul Daniel, the conductor appointed music director last year.","cn":"在北方歌剧公司，他将和去年指挥指定的音乐总监保罗·丹尼尔通力合作。"}},{"pos":"PHRASE 短语","cn":"（常指停止工作一段时间后）正常工作的","en":"If you say that someone is in harness, you mean that they are working, often after a period of not working.","ex":{"en":"You can rest for three or four months and then the longing for work will return and you will be right back in harness.","cn":"你可以休息三四个月，然后又会开始渴望工作，并能很快回到正常的工作状态。"}}]},"examples":[{"en":"( figurative ) In some areas, the poor feel harnessed to their jobs.","cn":"有些地区的穷人感觉终身被套牢在他们的工作上。"},{"en":"We must harness the skill and creativity of our workforce.","cn":"我们必须尽量发挥全体职工的技能和创造力。"}]},"hiding":{"media":{"uk":"media/uk/hiding__gb_1.mp3","us":"media/us/hiding__us_1.mp3"},"oxford":{"phon":"ˈhaɪdɪŋ","pos":"noun","senses":[{"en":"the state of being hidden","cn":"隐藏；躲藏","g":"[uncountable]","ex":{"en":"We spent months in hiding.","cn":"我们躲藏了好几个月。"}},{"en":"the act of hiding something","cn":"隐瞒；掩盖","g":"[uncountable]","ex":{"en":"I could understand the hiding of certain military secrets.","cn":"我能理解隐藏某些军事秘密的做法。"}},{"en":"a physical punishment, usually involving being hit hard many times","cn":"体罚；痛打","g":"[countable, usually singular]","lab":"especially British English, informal，，","ex":{"en":"to give somebody/get a (good) hiding","cn":"给某人／遭到一顿（狠）揍"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"躲藏;藏匿","en":"If someone is in hiding, they have secretly gone somewhere where they cannot be seen or found.","ex":{"en":"Gray is thought to be in hiding near the France/Italy border","cn":"他们认为格雷藏在法国和意大利边境附近。"}},{"pos":"N-COUNT 可数名词","cn":"痛打;狠揍","en":"If you give someone a hiding, you punish them by hitting them many times."},{"pos":"PHRASE 短语","cn":"白白浪费时间;白费工夫;毫无成功希望","en":"If you say that someone who is trying to achieve something is on a hiding to nothing, you are emphasizing that they have absolutely no chance of being successful.","ex":{"en":"As regards commercial survival, a car manufacturer capable of making only 50,000 cars a year is on a hiding to nothing.","cn":"谈到商业生存，一个年产只有5万辆的汽车制造厂家是毫无成功希望的。"}}]},"examples":[{"en":"( figurative ) The team got a hiding in their last game.","cn":"那支球队在最后一场比赛中被打得一败涂地。"},{"en":"After the trial, she had to go into hiding for several weeks.","cn":"审讯后她不得不躲藏了几个星期。"}],"base":"hide"},"he's":{"media":{"uk":"media/uk/he_s_1_gb_1.mp3","us":"media/us/he_s_1_us_1.mp3"},"oxford":{"phon":"hiːz","pos":"short form","senses":[{"en":"he is","cn":""},{"en":"he has","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（尤当 has 为助动词时，he is 或 he has 的常用口语形式）","en":"He's is the usual spoken form of 'he is' or 'he has', especially when 'has' is an auxiliary verb.","ex":{"en":"He's working maybe twenty-five hours a week","cn":"他一周工作大概25个小时。"}}]},"examples":[{"en":"He’s a writer.","cn":"他是一位作家。"},{"en":"He’s reading.","cn":"他正在看书。"}]},"hunt":{"media":{"uk":"media/uk/hunt__gb_1.mp3","us":"media/us/hunt__us_1.mp3"},"oxford":{"phon":"hʌnt","pos":"verb","senses":[{"en":"to go after wild animals in order to catch or kill them for food, sport or to make money","cn":"打猎；猎取；猎杀","g":"[intransitive, transitive]","ex":{"en":"Lions sometimes hunt alone.","cn":"狮子有时单独猎食。"}},{"en":"to look for something that is difficult to find","cn":"搜寻；搜索","g":"[intransitive]","ex":{"en":"She is still hunting for a new job.","cn":"她还在找新工作。"}},{"en":"to look for somebody in order to catch them or harm them","cn":"追踪；追捕","g":"[transitive, intransitive]","ex":{"en":"Police are hunting an escaped criminal.","cn":"警察正在追捕一名逃犯。"}},{"en":"(in the UK) to go after and kill foxes as a sport, riding horses and using dogs. Fox hunting with dogs has been illegal in England and Wales since 2005, but people still ride out with dogs following a scent trail, without an actual fox.","cn":"猎（狐）（骑马用狗猎狐，英格兰和威尔士在 2005 年已立法禁止）","g":"[intransitive, transitive]","ex":{"en":"They hunt when they stay with friends in Ireland.","cn":"他们去爱尔兰时会和那儿的朋友去猎狐。"}},{"en":"an act of looking for somebody/something that is difficult to find","cn":"搜寻；搜索；寻找","g":"[countable, usually singular]","ex":{"en":"The hunt is on for a suitable candidate.","cn":"正在物色合适的人选。"},"pos":"noun"},{"en":"an act of going after wild animals to kill or capture them","cn":"打猎","g":"[countable]","ex":{"en":"a tiger/seal hunt","cn":"猎虎；猎杀海豹"},"pos":"noun"},{"en":"(in the UK) an event at which people ride horses and hunt foxes with dogs as a sport, illegal in England and Wales since 2005","cn":"猎狐（骑马用狗猎狐的运动，英格兰和威尔士在 2005 年已立法禁止）","g":"[countable]","ex":{"en":"There was always a hunt on Boxing Day.","cn":"从前节礼日总会有猎狐活动。"},"pos":"noun"},{"en":"(in the UK) a group of people who regularly hunt foxes as a sport. Since 2005, instead of a fox, they follow a specially laid scent trail.","cn":"猎狐队伍","g":"[countable + singular or plural verb]","ex":{"en":"There were several different hunts in the area.","cn":"该地区曾进行过几次不同的狩猎活动。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"搜寻;寻找","en":"If you hunt for something or someone, you try to find them by searching carefully or thoroughly.","ex":{"en":"A forensic team was hunting for clues","cn":"法医小组正在寻找线索。"}},{"pos":"VERB 动词","cn":"追踪，追捕（罪犯、敌人等）","en":"If you hunt a criminal or an enemy, you search for them in order to catch or harm them.","ex":{"en":"Detectives have been hunting him for seven months","cn":"侦探7个月来一直在追捕他。"}},{"pos":"VERB 动词","cn":"（人）打猎，猎杀;（动物）猎食","en":"When people or animals hunt, they chase and kill wild animals for food or as a sport.","ex":{"en":"As a child I learned to hunt and fish","cn":"从小我就学会了打猎和捕鱼。"}},{"pos":"VERB 动词","cn":"（在英国骑马带狗进行）猎狐","en":"In Britain, when people hunt, they ride horses over fields with dogs called hounds and try to catch and kill foxes, as a sport.","ex":{"en":"She liked to hunt as often as she could.","cn":"她喜欢一有时间就去猎狐。"}},{"pos":"N-COUNT 可数名词","cn":"（英国的）猎狐队伍","en":"In Britain, a hunt is a group of people who meet regularly to hunt foxes."},{"pos":"PHRASE 短语","cn":"（参赛队或参赛者）仍有机会赢取","en":"If a team or competitor is in the hunt for something, they still have a chance of winning it.","ex":{"en":"We're still in the hunt for the League title and we want to go all the way in the Cup.","cn":"我们仍有机会获得联赛冠军，而且我们还想一路杀进足总杯决赛。"}},{"pos":"","cn":"","en":"相关词组：hunt down hunt out"}]},"examples":[{"en":"Hundreds have joined a police hunt for the missing teenager.","cn":"已有几百人和警方一同搜寻那名失踪的少年。"},{"en":"Detectives are hunting for thieves who broke into a warehouse yesterday.","cn":"侦探正在追踪昨天侵入仓库的窃贼。"}]},"homeward":{"media":{"uk":"media/uk/homeward__gb_1.mp3","us":"media/us/homeward__us_1.mp3"},"oxford":{"phon":"ˈhəʊmwəd","pos":"adverb","senses":[{"en":"towards home","cn":"回家的；回国的","ex":{"en":"Commuters were heading homeward at the end of the day.","cn":"一天的工作结束，上班族正赶着回家。"}},{"en":"going towards home","cn":"回家的；回国的","ex":{"en":"the homeward journey","cn":"归家的旅程"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"归家的;还乡的;回国的","en":"If you are on a homeward journey, you are on a journey towards your home.","ex":{"en":"She is ready for her homeward journey.","cn":"她准备好踏上返家之程了。"}},{"pos":"ADV 副词","cn":"向家;向家乡;向本国","en":"If you are travelling homeward or homewards, you are travelling towards your home.","ex":{"en":"John drove homeward through the lanes","cn":"约翰驱车穿过小巷向家驶去。"}}]},"examples":[{"en":"Commuters were heading homeward at the end of the day.","cn":"一天结束时下班的人们正赶着回家。"},{"en":"We drove homewards in silence.","cn":"我们默默地开车回家。"}]},"handles":{"lemma":"handle"},"hispanic":{"oxford":{"phon":"hɪˈspænɪk","pos":"adjective","senses":[{"en":"of or connected with Spain or Spanish-speaking countries, especially those of Latin America","cn":"西班牙的；西班牙语国家（尤指拉丁美洲）的"},{"en":"a person whose first language is Spanish, especially one from a Latin American country living in the US or Canada","cn":"母语为西班牙语的人（尤指住在美国或加拿大的拉丁美洲人）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"拉美裔美国籍的","en":"A Hispanic person is a citizen of the United States of America who originally came from Latin America, or whose family originally came from Latin America.","ex":{"en":"...a group of Hispanic doctors in Washington","cn":"华盛顿的一群拉美裔美国籍医生"}}]},"media":{"uk":"media/uk/hispanic__gb_1.mp3","us":"media/us/hispanic__us_1.mp3"},"examples":[{"en":"In California, Hispanics make up 19.2 percent of the population.","cn":"在加利福尼亚﹐西裔美国人占总人口的19.2%。"},{"en":"Miami’s Hispanic community","cn":"迈阿密的西裔美国人社区"}]},"haircut":{"media":{"uk":"media/uk/haircut__gb_1.mp3","us":"media/us/haircut__us_1.mp3"},"oxford":{"phon":"ˈheəkʌt","pos":"noun","senses":[{"en":"the act of somebody cutting your hair","cn":"理发","ex":{"en":"You need a haircut.","cn":"你该理发了。"}},{"en":"the style in which somebody’s hair is cut","cn":"发型；发式","lab":"North American English also","ex":{"en":"What do you think of my new haircut?","cn":"你觉得我的新发型怎么样？"}},{"en":"a reduction in an amount of money or in the value of an asset","cn":"资金量减少；资产价值下降","ex":{"en":"The Prime Minister says he'd like to see banks take a bigger haircut from bad loans.","cn":"首相称他希望看到银行以更大力度削减不良贷款。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"理发","en":"If you have a haircut, someone cuts your hair for you.","ex":{"en":"Your hair is all right; it's just that you need a haircut.","cn":"你的头发还好;不过你该理发了。"}},{"pos":"N-COUNT 可数名词","cn":"发式;发型","en":"A haircut is the style in which your hair has been cut.","ex":{"en":"Who's that guy with the funny haircut?","cn":"那个发型怪怪的家伙是谁？"}}]},"examples":[{"en":"What do you think of my new haircut?","cn":"你觉得我的新发型怎么样？"},{"en":"I see you've had a haircut.","cn":"我看得出你理发了。"}]},"highlights":{"lemma":"highlight","media":{"uk":"media/uk/highlight__gb_1.mp3","us":"media/us/highlight__us_1.mp3"}},"he'd":{"media":{"uk":"media/uk/he_d_1_gb_1.mp3","us":"media/us/he_d_1_us_1.mp3"},"oxford":{"phon":"hiːd","pos":"short form","senses":[{"en":"he had","cn":""},{"en":"he would","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（尤当 had 为助动词时，he had 的常用口语形式）","en":"He'd is the usual spoken form of 'he had', especially when 'had' is an auxiliary verb.","ex":{"en":"Steve had told her that he'd been in an accident on Wednesday night","cn":"史蒂夫已经告诉过她自己周三晚上出了事故。"}},{"pos":"","cn":"（he would 的口语形式）","en":"He'd is a spoken form of 'he would'.","ex":{"en":"He'd come into the clubhouse every day.","cn":"他每天都会来俱乐部会所。"}}]},"examples":[{"en":"By the time I got there he’d gone.","cn":"我到达那里时﹐他已经走了。"},{"en":"I’m sure he’d help if he could.","cn":"我相信如果他能帮忙的话一定会帮的。"}]},"heat":{"media":{"uk":"media/uk/heat__gb_1.mp3","us":"media/us/heat__us_1.mp3"},"oxford":{"phon":"hiːt","pos":"noun","senses":[{"en":"the quality of being hot","cn":"热","g":"[uncountable, singular]","sc":"being hot/temperature","ex":{"en":"Heat rises.","cn":"热空气向上升。"}},{"en":"heat seen as a form of energy that is transferred from one object or substance to another as a result of a difference in temperature","cn":"热量；热力","g":"[uncountable]","lab":"physics","sc":"being hot/temperature","ex":{"en":"Being a metal, aluminium readily conducts heat.","cn":"铝是一种金属，导热良好。"}},{"en":"the level of temperature","cn":"温度","g":"[uncountable, countable, usually singular]","sc":"being hot/temperature","ex":{"en":"Test the heat of the water before getting in.","cn":"入水之前先试一试水温。"}},{"en":"hot weather; the hot conditions in a building, vehicle, etc.","cn":"暑热；（建筑物、车辆等中的）高温，炎热环境","g":"[uncountable]","sc":"being hot/temperature","ex":{"en":"You should not go out in the heat of the day (= at the hottest time).","cn":"你不应该在天最热的时候外出。"}},{"en":"a source of heat, especially one that you cook food on","cn":"炉灶；灶眼；炉火","g":"[uncountable]","sc":"for cooking","ex":{"en":"Return the pan to the heat and stir.","cn":"把锅放回灶上再搅拌。"}},{"en":"the process of supplying heat to a room or building; a system used to do this","cn":"供暖；供暖系统；暖气设备","g":"[uncountable]","lab":"especially North American English","sc":"in building/room","ex":{"en":"The heat wasn't on and the house was freezing.","cn":"暖气没有开，房子里冰冷。"}},{"en":"a spicy quality in food that makes your mouth feel as if it is burning","cn":"辣","sc":"in spicy food","ex":{"en":"Chilli peppers add taste and heat to food.","cn":"辣椒能给食物提味并增加辣味。"}},{"en":"strong feelings, especially of anger or excitement","cn":"强烈感情；（尤指）愤怒，激动","g":"[uncountable]","sc":"strong feelings","ex":{"en":"‘No, I won't,’ he said with heat in his voice.","cn":"“不，我绝不。”他怒气冲冲地说。"}},{"en":"pressure on somebody to do or achieve something","cn":"压力；逼迫","g":"[uncountable]","sc":"pressure","ex":{"en":"The heat is on now that the election is only a week away.","cn":"离选举只有一个星期了，因此大家开始感觉到有压力了。"}},{"en":"one of a series of races or competitions, the winners of which then compete against each other in the next part of the competition","cn":"预赛；分组赛","g":"[countable]","sc":"race","ex":{"en":"a qualifying heat","cn":"资格赛"}},{"en":"to make something hot or warm; to become hot or warm","cn":"加热；变热；（使）变暖","lab":"British English","ex":{"en":"Heat the oil and add the onions.","cn":"把油烧热后加入洋葱。"},"pos":"verb"},{"en":"a UK magazine published since 1999, that contains photographs and articles about famous people and their private lives. It also covers fashion and beauty, entertainment, etc.","cn":"自1999年以来发行的英国杂志，其中包含有关名人及其私生活的照片和文章。它还涵盖时尚和美容，娱乐等。","pos":""}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…加热;使升温","en":"When you heat something, you raise its temperature, for example by using a flame or a special piece of equipment.","ex":{"en":"Meanwhile, heat the tomatoes and oil in a pan.","cn":"同时，在平底锅里将西红柿和油加热。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"热;高温","en":"Heat is warmth or the quality of being hot.","ex":{"en":"The seas store heat and release it gradually during cold periods","cn":"海洋储存热量，并在寒冷季节里慢慢地把它释放出来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"炎热;高温天气","en":"The heat is very hot weather.","ex":{"en":"As an asthmatic, he cannot cope with the heat and humidity","cn":"他患有哮喘病，经不起高温和潮湿。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"温度;热度","en":"The heat of something is the temperature of something that is warm or that is being heated.","ex":{"en":"Warm the milk to blood heat","cn":"将牛奶热至人体温度。"}},{"pos":"N-SING 单数名词","cn":"热源;炉灶;暖气","en":"You use heat to refer to a source of heat, for example a cooking ring or the heating system of a house.","ex":{"en":"Immediately remove the pan from the heat","cn":"马上把平底锅从灶上端下来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"强烈的感情;（尤指）愤怒，激动","en":"You use heat to refer to a state of strong emotion, especially of anger or excitement.","ex":{"en":"It was all done in the heat of the moment and I have certainly learned by my mistake","cn":"所有的一切都是在一怒之下干的，我无疑已经从自己的错误中吸取了教训。"}},{"pos":"N-SING 单数名词","cn":"（某活动）最激烈的时刻","en":"The heat of a particular activity is the point when there is the greatest activity or excitement.","ex":{"en":"Last week, in the heat of the election campaign, the Prime Minister left for America.","cn":"上周，当竞选活动进行到白热化时，首相启程去了美国。"}},{"pos":"N-COUNT 可数名词","cn":"预赛;分组赛","en":"A heat is one of a series of races or competitions. The winners of a heat take part in another race or competition, against the winners of other heats.","ex":{"en":"...the heats of the men's 100m breaststroke.","cn":"男子100米蛙泳预赛"}},{"pos":"PHRASE 短语","cn":"（雌性动物）正在发情（美国英语中作 in heat）","en":"When a female animal is on heat in British English, or in heat in American English, she is in a state where she is ready to mate with a male animal, as this will probably result in her becoming pregnant."},{"pos":"","cn":"","en":"相关词组：heat up"}]},"examples":[{"en":"He did well in the heats; hopefully he'll do as well in the final.","cn":"他在预赛中成绩很好，且有望在决赛中也有同样出色的表现。"},{"en":"The heat is on now that the election is only a week away.","cn":"离选举只有一个星期了，因此大家开始感觉到有压力了。"}]},"hardened":{"lemma":"harden","media":{"uk":"media/ldoce/hwd/bre/a/ld41hardened.mp3","us":"media/ldoce/hwd/ame/f/laadhardened.mp3"}},"hare":{"oxford":{"phon":"heə(r)","pos":"noun","senses":[{"en":"an animal like a large rabbit with very strong back legs, that can run very fast","cn":"野兔"},{"en":"to run or go somewhere very fast","cn":"飞跑；疾走","ex":{"en":"He hared away down the street.","cn":"他沿着街道狂奔而去。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"野兔","en":"A hare is an animal like a rabbit but larger with long ears, long legs, and a small tail."},{"pos":"VERB 动词","cn":"飞跑;飞奔","en":"If you hare off somewhere, you go there very quickly.","ex":{"en":"...an over-protective mother who keeps haring off to ring the babysitter.","cn":"过于爱护孩子而不断地跑去给保姆打电话的母亲"}}]},"media":{"img":["media/pic/rabbit_hare.jpg","media/thumb/hare.jpg"],"uk":"media/uk/hare__gb_1.mp3","us":"media/us/hare__us_1.mp3"},"examples":[{"en":"He hared off down the road.","cn":"他沿着马路飞快地跑掉了。"}]},"ha":{"oxford":{"phon":"hɑː","pos":"exclamation","senses":[{"en":"the sound that people make when they are surprised or pleased, or when they have discovered something","cn":"（惊奇、高兴或有所发现时用）哈","ex":{"en":"Ha! It serves you right!","cn":"哈！你活该！"}},{"en":"the word for the sound that people make when they laugh","cn":"（笑声）哈"},{"en":"used to show that you do not think that something is funny","cn":"（认为某事并不可笑）","lab":"informal, ironic，，","ex":{"en":"Ha! Ha! Very funny! Now give me back my shoes.","cn":"哈！哈！真有意思！把我的鞋还给我。"}},{"en":"(in writing) hectare","cn":"（书写形式）公顷","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"See also:","cn":"（用在书面语中表示惊讶、生气或高兴）哈","en":"Ha is used in writing to represent a noise that people make to show they are surprised, annoyed, or pleased about something.","ex":{"en":"Ha! said Wren. Think I'd trust you?","cn":"“哈！”雷恩说，“你以为我会相信你？”"}}]},"media":{"uk":"media/uk/haar__gb_1.mp3","us":"media/us/haar__us_1.mp3"},"examples":[{"en":"Ha! Ha! Very funny! Now give me back my shoes.","cn":"哈！哈！真有意思！把我的鞋还给我。"},{"en":"Ha! I knew he was hiding something.","cn":"哈！我就知道他在隐瞒什么。"}]},"hut":{"media":{"img":["media/pic/buildings_comp.jpg","media/thumb/hut.jpg"],"uk":"media/uk/hut__gb_1.mp3","us":"media/us/hut__us_1.mp3"},"oxford":{"phon":"hʌt","pos":"noun","senses":[{"en":"a small, simply built house or shelter","cn":"简陋的小房子（或棚、舍）","ex":{"en":"You can rent a beach hut for about $10 a night.","cn":"你可以租住约10元一晚的海滩棚屋。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（简陋的）小屋;土房;棚屋;茅舍;石寮","en":"A hut is a small house with only one or two rooms, especially one which is made of wood, mud, grass, or stones."},{"pos":"N-COUNT 可数名词","cn":"（花园中的）木屋;（建筑工人等住的）临时工棚","en":"A hut is a small wooden building in someone's garden, or a temporary building used by builders or repair workers."}]},"examples":[{"en":"a beach hut","cn":"海滩棚屋"},{"en":"a wooden hut","cn":"小木屋"}]},"house":{"media":{"img":["media/pic/house_labels_comp.jpg","media/thumb/house.jpg"],"uk":"media/uk/house__gb_1.mp3","us":"media/us/house__us_1.mp3"},"oxford":{"phon":"haʊs","pos":"noun","senses":[{"en":"a building for people to live in, usually for one family","cn":"房屋；房子；住宅","g":"[countable]","lab":"British English","sc":"building","ex":{"en":"We live in a two-bedroom house.","cn":"我们住在一个两居室的房子里。"}},{"en":"all the people living in a house","cn":"住在一所房子里的人；全家人","g":"[singular]","sc":"building","ex":{"en":"Be quiet or you'll wake the whole house!","cn":"安静点，别把全家人都吵醒！"}},{"en":"a building used for a particular purpose, for example for holding meetings in or keeping animals or goods in","cn":"某种用途的建筑物","g":"[countable]","sc":"building","ex":{"en":"an opera house","cn":"歌剧院"}},{"en":"used in the names of office buildings","cn":"（用于办公楼名称）大厦，大楼","g":"[singular]","lab":"British English","sc":"building","ex":{"en":"Their offices are on the second floor of Chester House.","cn":"他们的办公室在切斯特大厦三楼。"}},{"en":"a company involved in a particular kind of business; an institution of a particular kind","cn":"（从事某种生意的）公司，机构","g":"[countable]","sc":"company/institution","ex":{"en":"a fashion/banking/publishing house","cn":"时装公司；银行；出版社"}},{"en":"a restaurant","cn":"餐馆；餐厅","g":"[countable]","sc":"restaurant","ex":{"en":"a steakhouse","cn":"牛排餐馆"}},{"en":"a group of people who meet to discuss and make the laws of a country","cn":"议院；议会；国会","g":"[countable]","sc":"parliament","ex":{"en":"Legislation requires approval by both houses of parliament.","cn":"立法须要得到议会两院的一致通过。"}},{"en":"the House of Commons or the House of Lords in the UK; the House of Representatives in the US","cn":"（英国）下议院，上议院；（美国）众议院","g":"[singular]","sc":"parliament"},{"en":"a group of people discussing something in a formal debate","cn":"（统称）参与辩论的人","g":"[singular]","sc":"in debate","ex":{"en":"I urge the house to vote against the motion.","cn":"我呼吁参加辩论的诸位投票反对这项动议。"}},{"en":"the part of a theatre where the audience sits; the audience at a particular performance","cn":"观众席；（统称）观众","g":"[countable]","sc":"in theatre","ex":{"en":"playing to a full/packed/empty house (= to a large/small audience)","cn":"演出座无虚席／满座／观众寥寥无几"}},{"en":"(in some British schools) an organized group of students of different ages who compete against other groups in sports competitions, etc. and who may, in boarding schools, live together in one building","cn":"（英国某些学校为进行体育比赛或按宿舍将学生分成的）社，舍","g":"[countable]","sc":"in school"},{"en":"an old and famous family","cn":"名门世家；望族","g":"[countable]","sc":"family","ex":{"en":"the House of Windsor (= the British royal family)","cn":"温莎王室"}},{"en":"a type of electronic dance music with a fast beat","cn":"货仓音乐，浩室音乐（一种快节奏电子舞曲）","g":"[uncountable]","sc":"music"},{"en":"to provide a place for a person or an animal to live","cn":"给（人或动物）提供住处","sc":"provide home","ex":{"en":"The government is committed to housing the refugees.","cn":"政府承诺收容难民。"},"pos":"verb"},{"en":"to be the place where something is kept or where something operates from","cn":"是（某物）的贮藏处（或安置处）；收藏；安置","sc":"keep something","ex":{"en":"The library houses a collection of 15 000 books.","cn":"该图书馆藏书 15 000 册。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"房屋;房子;住宅","en":"A house is a building in which people live, usually the people belonging to one family.","ex":{"en":"She has moved to a smaller house.","cn":"她已经搬进了一所小一些的房子。"}},{"pos":"N-SING 单数名词","cn":"住在一幢房子里的人;一家人","en":"You can refer to all the people who live together in a house as the house .","ex":{"en":"If he set his alarm clock for midnight, it would wake the whole house","cn":"如果他把闹钟设在午夜响，那会把全家人都吵醒的。"}},{"pos":"N-COUNT 可数名词","cn":"（用于餐饮场所的名称）餐厅，馆，屋","en":"House is used in the names of types of places where people go to eat and drink.","ex":{"en":"...a steak house.","cn":"牛排餐厅"}},{"pos":"N-COUNT 可数名词","cn":"（尤用于出版、借贷或服装设计等公司的名称）公司，商行","en":"House is used in the names of types of companies, especially ones which publish books, lend money, or design clothes.","ex":{"en":"Many of the clothes come from the world's top fashion houses","cn":"这些服装中有很多出自世界顶级时装设计公司。"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于办公楼、私宅或豪宅名称）大楼，大厦，大宅","en":"House is sometimes used in the names of office buildings and large private homes or expensive houses.","ex":{"en":"I was to go to the very top floor of Bush House in Aldwych.","cn":"我正要去奥尔德威治的布什大厦最顶层。"}},{"pos":"N-COUNT 可数名词","cn":"（英国）上（或下）议院；（美国）众议院","en":"You can refer to the two main bodies of Britain's parliament and the United States of America's legislature as the House or a House.","ex":{"en":"Some members of the House and Senate worked all day yesterday","cn":"一些众议员和参议员昨天工作了整整一天。"}},{"pos":"N-SING 单数名词","cn":"全体辩论者;所有辩手","en":"You can refer to all the people at a debate as the house .","ex":{"en":"The club is planning a public debate on 'This house believes that journalism has not gained from the introduction of new technology'.","cn":"该俱乐部拟就“我方辩手认为新闻报道并没有从新技术中获益”一题进行一次公开辩论。"}},{"pos":"N-COUNT 可数名词","cn":"（英国学校中为进行体育竞赛等所划分的）组，社","en":"In a British school, a house is a group of children of different ages who compete against other groups in sports and other activities. Each house usually has a name.","ex":{"en":"He was a prefect and house captain.","cn":"他是班长兼社长。"}},{"pos":"N-COUNT 可数名词","cn":"贵族;名门望族；（尤指）王室，王族","en":"A house is a family which has been or will be important for many generations, especially the family of a king or queen.","ex":{"en":"...the Saudi Royal House.","cn":"沙特王族"}},{"pos":"N-COUNT 可数名词","cn":"（剧场、影院或其他娱乐场所的）观众席;全体观众","en":"The house is the part of a theatre, cinema, or other place of entertainment where the audience sits. You can also refer to the audience at a particular performance as the house.","ex":{"en":"They played in front of a packed house.","cn":"他们的演出座无虚席。"}},{"pos":"ADJ 形容词","cn":"（餐馆里的葡萄酒）廉价佐餐的，未列入酒水单的","en":"A restaurant's house wine is the cheapest wine it sells, which is not listed by name on the wine list.","ex":{"en":"Tweed ordered a carafe of the house wine.","cn":"特威德点了一瓶佐餐葡萄酒。"}},{"pos":"VERB 动词","cn":"为…提供房屋（或住所）","en":"To house someone means to provide a house or flat for them to live in.","ex":{"en":"Part III of the Housing Act 1985 imposes duties on local authorities to house homeless people","cn":"1985年《住房法案》的第三部分要求地方政府为无家可归者提供住所。"}},{"pos":"VERB 动词","cn":"安置;容纳;作为…之用","en":"A building or container that houses something is the place where it is located or from where it operates.","ex":{"en":"The château itself is open to the public and houses a museum of motorcycles and cars","cn":"古堡本身对公众开放，并设有一个摩托车和汽车博物馆。"}},{"pos":"VERB 动词","cn":"（建筑物）供…居住，供…下榻","en":"If you say that a building houses a number of people, you mean that is the place where they live or where they are staying.","ex":{"en":"The building will house twelve boys and eight girls","cn":"这座房子里会住12个男孩和8个女孩。"}},{"pos":"PHRASE 短语","cn":"(人、表演或演讲）博得全场喝彩，引得哄堂大笑","en":"If a person or their performance or speech brings the house down, the audience claps, laughs, or shouts loudly because the performance or speech is very impressive or amusing.","ex":{"en":"It's really an amazing dance. It just always brings the house down.","cn":"这真是一段精彩绝伦的舞蹈表演，每次总是博得全场喝彩。"}},{"pos":"PHRASE 短语","cn":"很快就打得火热;一见如故;一拍即合","en":"If two people get on like a house on fire, they quickly become close friends, for example because they have many interests in common."},{"pos":"PHRASE 短语","cn":"（不出去工作而）操持家务，当家","en":"If you keep house, you do the cleaning and cooking for your household, and do not go out to work.","ex":{"en":"He lives with an aunt who keeps house for him.","cn":"他和一位帮他料理家务的姑妈住在一起。"}},{"pos":"PHRASE 短语","cn":"（餐馆或酒吧）免费招待的","en":"If you are given something in a restaurant or bar on the house, you do not have to pay for it.","ex":{"en":"The owner knew about the engagement and brought them glasses of champagne on the house.","cn":"店主知道了订婚一事，于是免费请他们喝香槟。"}},{"pos":"PHRASE 短语","cn":"管好自己的事;处理好自身问题","en":"If someone gets their house in order ,puts their house in order, or sets their house in order, they arrange their affairs and solve their problems.","ex":{"en":"Some think Stempel's departure will help the company get its financial house in order","cn":"有些人认为斯坦普尔的离职将有助于公司解决自身的财务问题。"}}]},"examples":[{"en":"They set up house together in a small flat in Brighton.","cn":"他们一同在布莱顿的一个小公寓里建立了家庭。"},{"en":"The gallery houses 2 000 works of modern art.","cn":"美术馆收藏了 2 000 件现代艺术作品。"}]},"hectic":{"media":{"uk":"media/uk/hectic__gb_1.mp3","us":"media/us/hectic__us_1.mp3"},"oxford":{"phon":"ˈhektɪk","pos":"adjective","senses":[{"en":"very busy; full of activity","cn":"忙碌的；繁忙的","ex":{"en":"to lead a hectic life","cn":"生活十分忙碌"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧张忙碌的;忙乱的","en":"A hectic situation is one that is very busy and involves a lot of rushed activity.","ex":{"en":"Despite his hectic work schedule, Benny has rarely suffered poor health","cn":"尽管工作繁忙，本尼却少有身体不好的时候。"}}]},"examples":[{"en":"a hectic schedule","cn":"安排很满的日程表"},{"en":"to lead a hectic life","cn":"生活十分忙碌"}]},"headed":{"media":{"uk":"media/uk/headed__gb_1.mp3","us":"media/us/headed__us_1.mp3"},"oxford":{"phon":"ˈhedɪd","pos":"adjective","senses":[{"en":"having the name and address of a person, an organization, etc. printed at the top","cn":"顶端印有名称和地址的；有信头的","ex":{"en":"headed notepaper","cn":"有信头的便笺纸"}},{"en":"having the type of head or number of heads mentioned","cn":"有…头的；有…个头的","ex":{"en":"a bald-headed man","cn":"秃顶男子"}}]},"examples":[{"en":"headed notepaper","cn":"有信头的便笺纸"},{"en":"a bald-headed man","cn":"秃顶男子"}],"base":"head"},"hindu":{"oxford":{"phon":"ˈhɪnduː","pos":"adjective","senses":[{"en":"connected with Hinduism or people who are Hindus","cn":"印度教的；印度教教徒的","ex":{"en":"a Hindu temple","cn":"印度教庙宇"}},{"en":"a person whose religion is Hinduism","cn":"印度教教徒","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"印度教徒","en":"A Hindu is a person who believes in Hinduism and follows its teachings."},{"pos":"ADJ 形容词","cn":"印度教的","en":"Hindu is used to describe things that belong or relate to Hinduism.","ex":{"en":"...a Hindu temple.","cn":"印度教寺庙"}}]},"media":{"uk":"media/uk/hindu__gb_1.mp3","us":"media/us/hindu__us_1.mp3"},"examples":[{"en":"a Hindu temple","cn":"印度教庙宇"}]},"hundredth":{"media":{"uk":"media/uk/hundredth__gb_1.mp3","us":"media/us/hundredth__us_1.mp3"},"oxford":{"phon":"ˈhʌndrədθ","pos":"ordinal number","senses":[{"en":"100th","cn":"第一百","ex":{"en":"her hundredth birthday","cn":"她的百岁诞辰"}},{"en":"each of one hundred equal parts of something","cn":"百分之一","ex":{"en":"a/one hundredth of a second","cn":"百分之一秒"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ORD 序数词","cn":"第一百","en":"The hundredth item in a series is the one that you count as number one hundred.","ex":{"en":"The bank celebrates its hundredth anniversary in December.","cn":"这家银行将于12月庆祝其成立100周年。"}},{"pos":"FRACTION 分数词","cn":"百分之一","en":"A hundredth of something is one of a hundred equal parts of it.","ex":{"en":"Mitchell beat Lewis by three-hundredths of a second.","cn":"米切尔以0.03秒的微弱优势赢了刘易斯。"}}]},"examples":[{"en":"her hundredth birthday","cn":"她的百岁诞辰"},{"en":"a/one hundredth of a second","cn":"百分之一秒"}]},"hopping":{"media":{"uk":"media/uk/hopping__gb_1.mp3","us":"media/us/hopping__us_1.mp3"},"oxford":{"phon":"ˈhɒpɪŋ","pos":"adjective","senses":[{"en":"very lively or busy","cn":"很活跃的；忙忙碌碌的","ex":{"en":"The clubs in town are really hopping.","cn":"城里的俱乐部真够热闹的。"}}]},"examples":[{"en":"The clubs in town are really hopping.","cn":"城里的俱乐部真够热闹的。"}]},"hard":{"media":{"uk":"media/uk/hard__gb_1.mp3","us":"media/us/hard__us_1.mp3"},"oxford":{"phon":"hɑːd","pos":"adjective","senses":[{"en":"difficult to do, understand or answer","cn":"难做的；难懂的；难以回答的","sc":"difficult","ex":{"en":"a hard choice/decision/question","cn":"艰难的选择／决定；难以回答的问题"}},{"en":"full of difficulty and problems, especially because of a lack of money","cn":"困苦的；艰苦的；艰难的","sc":"difficult","ex":{"en":"Times were hard at the end of the war.","cn":"战争后期生活很艰苦。"}},{"en":"needing or using a lot of physical strength or mental effort","cn":"耗费体力（或脑力）的；辛苦的","sc":"needing/using effort","ex":{"en":"It's hard work shovelling snow.","cn":"铲雪是个苦活儿。"}},{"en":"putting a lot of effort or energy into an activity","cn":"努力的；勤劳的","sc":"needing/using effort","ex":{"en":"She's a very hard worker.","cn":"她工作很卖力。"}},{"en":"done with a lot of strength or force","cn":"用力的；猛烈的","sc":"needing/using effort","ex":{"en":"He gave the door a good hard kick.","cn":"他狠狠踢了一下门。"}},{"en":"solid or stiff and difficult to bend or break","cn":"坚固的；坚硬的；结实的","sc":"solid/stiff","ex":{"en":"Wait for the concrete to go hard.","cn":"等待混凝土凝结。"}},{"en":"showing no kind feelings or sympathy","cn":"冷酷无情的；硬心肠的；无同情心的","sc":"without sympathy","ex":{"en":"My father was a hard man.","cn":"我父亲是个不讲情面的人。"}},{"en":"showing no signs of fear or weakness; ready to fight or compete","cn":"勇敢无畏的；不软弱退缩的","lab":"informal","sc":"not afraid","ex":{"en":"Come and get me if you think you're hard enough.","cn":"你要是觉得自己有种，就冲着我来吧。"}},{"en":"definitely true and based on information that can be proved","cn":"确凿的；可证实的；可靠的","g":"[only before noun]","sc":"facts/evidence","ex":{"en":"Is there any hard evidence either way?","cn":"不管正反，有什么确凿证据吗？"}},{"en":"very cold and severe","cn":"寒冷的；凛冽的","sc":"weather","ex":{"en":"It had been a hard winter.","cn":"那年的冬天特别冷。"}},{"en":"strongly alcoholic","cn":"酒精浓度高的；烈性的","g":"[only before noun]","lab":"informal","sc":"drink","ex":{"en":"hard liquor","cn":"烈酒"}},{"en":"containing calcium and other mineral salts that make mixing with soap difficult","cn":"硬的（含钙及镁等可溶性盐较多）","sc":"water","ex":{"en":"a hard water area","cn":"硬水区"}},{"en":"used to describe a letter c or g when pronounced as in ‘cat’ or ‘go’, rather than as in ‘city’ or ‘giant’","cn":"硬音的（如字母 c 或 g 在 cat 或 go 等词中的发音）","lab":"phonetics","sc":"consonants"},{"en":"with great effort; with difficulty","cn":"努力地；费力地；艰难地","sc":"with effort","ex":{"en":"to work hard","cn":"努力工作"},"pos":"adverb"},{"en":"with great force","cn":"猛力地；猛烈地","lab":"figurative","sc":"with force","ex":{"en":"Don't hit it so hard!","cn":"别这么用力打！"},"pos":"adverb"},{"en":"carefully and completely","cn":"认真而全面地；缜密地","sc":"carefully","ex":{"en":"to think hard","cn":"认真思考"},"pos":"adverb"},{"en":"heavily; a lot or for a long time","cn":"沉重地；大量地；长时间地","sc":"a lot","ex":{"en":"It was raining hard when we set off.","cn":"我们出发时正下着大雨。"},"pos":"adverb"},{"en":"at a sharp angle to the left/right","cn":"向左（或右）急转弯","sc":"left/right","ex":{"en":"Turn hard right at the next junction.","cn":"在下个路口处向右急转弯。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"硬的;坚硬的;坚固的","en":"Something that is hard is very firm and stiff to touch and is not easily bent, cut, or broken.","ex":{"en":"He shuffled his feet on the hard wooden floor","cn":"他拖着脚在硬木地板上走动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难做的;困难的","en":"Something that is hard is very difficult to do or deal with.","ex":{"en":"It's hard to tell what effect this latest move will have","cn":"很难说最近这次行动会有什么结果。"}},{"pos":"ADV-GRADED 副词","cn":"努力地;使劲地","en":"If you work hard doing something, you are very active or work intensely, with a lot of effort.","ex":{"en":"I'll work hard. I don't want to let him down","cn":"我会努力工作，我不想让他失望。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"累人的;费力的;费劲的","en":"Hard work involves a lot of activity and effort.","ex":{"en":"Coping with three babies is very hard work","cn":"照顾3个宝宝是非常累人的活儿。"}},{"pos":"ADV-GRADED 副词","cn":"仔细地;认真地","en":"If you look, listen, or think hard, you do it carefully and with a great deal of attention.","ex":{"en":"He looked at me hard","cn":"他使劲盯着我看。"}},{"pos":"ADV-GRADED 副词","cn":"猛力地;用力地","en":"If you strike or take hold of something hard, you strike or take hold of it with a lot of force.","ex":{"en":"I kicked a dustbin very hard and broke my toe.","cn":"我狠狠地踢了一脚垃圾箱，结果脚趾骨折了。"}},{"pos":"ADV-GRADED 副词","cn":"强烈地;猛烈的;长时间地","en":"You can use hard to indicate that something happens intensely and for a long time.","ex":{"en":"I've never seen Terry laugh so hard","cn":"我从未见过特里如此放声大笑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷酷无情的;心肠硬的","en":"If a person or their expression is hard, they show no kindness or sympathy.","ex":{"en":"His father was a hard man","cn":"他的父亲是个冷酷无情的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"苛刻的;严厉的;不友善的","en":"If you are hard on someone, you treat them severely or unkindly.","ex":{"en":"Don't be so hard on him.","cn":"别对他太苛刻了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有害的;不利的","en":"If you say that something is hard on a person or thing, you mean it affects them in a way that is likely to cause them damage or suffering.","ex":{"en":"The grey light was hard on the eyes","cn":"光线暗淡对眼睛不利。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（生活、一段日子）艰难的，艰苦的","en":"If you have a hard life or a hard period of time, your life or that period is difficult and unpleasant for you.","ex":{"en":"It had been a hard life for her","cn":"对她而言，那是一段非常艰苦的生活。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常寒冷的;凛冽的","en":"A hard winter or a hard frost is a very cold one.","ex":{"en":"...a prolonged period of hard frost","cn":"漫长的强霜冻期"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（颜色）刺目的，晃眼的;（声音）刺耳的，难听的","en":"Hard colours or sounds are harsh or bright and unpleasant to see or hear.","ex":{"en":"The sea was a hard blue.","cn":"大海呈一片耀眼的蓝色。"}},{"pos":"ADJ 形容词","cn":"（证据、资料）可靠的，确凿的","en":"Hard evidence or facts are definitely true and do not need to be questioned.","ex":{"en":"He wanted more hard evidence","cn":"他想要更多确凿的证据。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（水质）硬的（指含钙化合物较多）","en":"Hard water contains a lot of calcium compounds that stop soap making bubbles and sometimes appear as a deposit in kettles and baths."},{"pos":"ADJ 形容词","cn":"（毒品）毒性强的，烈性的","en":"Hard drugs are very strong illegal drugs such as heroin or cocaine."},{"pos":"ADJ 形容词","cn":"（语音）发硬音的","en":"In phonetics, a hard sound is one such as 'c' or 'g' as pronounced in the words 'cat' or 'give', and not as in the words 'cinema' or 'general'."},{"pos":"PREP-PHRASE 短语介词","cn":"离…很近的","en":"If one thing is hard by another, it is very close to it.","ex":{"en":"Paradise Street was a short, crowded street near the railway station and hard by the factory.","cn":"天堂街是火车站附近一条拥挤的小街道，离该工厂很近。"}},{"pos":"PHRASE 短语","cn":"受到不公平待遇的;委屈的","en":"If you feel hard done by, you feel that you have not been treated fairly.","ex":{"en":"The hall porter was feeling hard done by at having to extend his shift.","cn":"酒店行李搬运工因为被迫延长当班时间而愤愤不平。"}},{"pos":"PHRASE 短语","cn":"困难的;艰难的","en":"If you say that something is hard going, you mean it is difficult and requires a lot of effort.","ex":{"en":"The talks had been hard going at the start.","cn":"会谈从一开始就举步维艰。"}},{"pos":"PHRASE 短语","cn":"受到沉重打击的;受严重影响的","en":"To be hard hit by something means to be affected very severely by it.","ex":{"en":"California's been particularly hard hit by the recession.","cn":"加利福尼亚受经济衰退的影响尤为严重。"}},{"pos":"PHRASE 短语","cn":"佯装不感兴趣;故意摆谱","en":"If someone plays hard to get, they pretend not to be interested in another person or in what someone is trying to persuade them to do.","ex":{"en":"I wanted her and she was playing hard to get.","cn":"我想得到她，但她却故意装出不感兴趣的样子。"}},{"pos":"PHRASE 短语","cn":"十分困难的;处于困境的","en":"If someone is hard put to do something or, in British English if they are hard pushed to do something, they have great difficulty doing it.","ex":{"en":"Mr Morton is undoubtedly cleverer than Mr Kirkby, but he will be hard put to match his popularity.","cn":"莫顿先生无疑比柯克比先生更聪明，但他将很难像柯克比先生那样受人欢迎。"}},{"pos":"PHRASE 短语","cn":"为…而非常苦恼（或难受）；因…而沮丧","en":"If you take something hard, you are very upset or depressed by it.","ex":{"en":"Maybe I just took it too hard.","cn":"可能我真的对此事太过耿耿于怀。"}}]},"examples":[{"en":"She won't listen to my advice so she'll just have to learn the hard way.","cn":"她不肯听我的忠告，所以只好吃了苦头才知道厉害。"},{"en":"Looking at a computer screen all day can be very hard on the eyes.","cn":"成天盯着计算机屏幕可能会对眼睛造成严重损害。"}]},"habitats":{"lemma":"habitat","media":{"uk":"media/uk/habitat__gb_1.mp3","us":"media/us/habitat__us_1.mp3"}},"habitat":{"media":{"uk":"media/uk/habitat__gb_1.mp3","us":"media/us/habitat__us_1.mp3"},"oxford":{"phon":"ˈhæbɪtæt","pos":"noun","senses":[{"en":"the place where a particular type of animal or plant is normally found","cn":"（动植物的）生活环境，栖息地","lab":"especially British English","ex":{"en":"The panda's natural habitat is the bamboo forest.","cn":"大熊猫的天然栖息地是竹林。"}},{"en":"a group of shops selling furniture and other things for the home like cushions, china and lamps. It was started in Britain in 1964 by Terence Conran, with some shops opening later in other countries, including France, Spain and Germany. It was especially successful in the 1960s and 1970s when it was one of the first companies to sell original designs of furniture, etc. that many people could afford. By 2011 many of the shops had been closed.","cn":"住所：一组商店，出售家具和其他家居用品，例如靠垫，瓷器和灯具。它于1964年在英国由Terence Conran创立，后来在法国，西班牙和德国等其他国家开设了一些商店。它在1960年代和1970年代特别成功，当时它是最早销售许多人买得起的家具等原始设计的公司之一。到2011年，许多商店都关门了。","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（动植物的）生境，栖生地，产地","en":"The habitat of an animal or plant is the natural environment in which it normally lives or grows.","ex":{"en":"In its natural habitat, the hibiscus will grow up to 25ft","cn":"在原生境中，木槿能长到25英尺高。"}}]},"examples":[{"en":"The panda's natural habitat is the bamboo forest.","cn":"大熊猫的天然栖息地是竹林。"},{"en":"the destruction of wildlife habitat","cn":"野生动植物生存环境的破坏"}]},"helping":{"media":{"uk":"media/uk/helping__gb_1.mp3","us":"media/us/helping__us_1.mp3"},"oxford":{"phon":"ˈhelpɪŋ","pos":"noun","senses":[{"en":"an amount of food given to somebody at a meal","cn":"（进餐时的）一份食物，一客食物","ex":{"en":"a small/generous helping","cn":"一小份／一大份食物"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（食物的）一份，一客","en":"A helping of food is the amount of it that you get in a single serving.","ex":{"en":"She gave them extra helpings of ice-cream.","cn":"她又给了他们几份冰激凌。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指某种特性的）一些，一定量","en":"You can refer to an amount of something, especially a quality, as a helping of that thing.","ex":{"en":"It took a generous helping of entrepreneurial confidence to persevere during this incident.","cn":"在这一事件中坚持下来是有了充足的创业信心的。"}}]},"examples":[{"en":"We all had a second helping of pie.","cn":"我们又都吃了一份馅饼。"},{"en":"a small/generous helping","cn":"一小份/一大份食物"}],"base":"help"},"hydroelectric":{"media":{"uk":"media/uk/hydroelectric__gb_1.mp3","us":"media/us/hydroelectric__us_1.mp3"},"oxford":{"phon":"ˌhaɪdrəʊɪˈlektrɪk","pos":"adjective","senses":[{"en":"using the power of water to produce electricity; produced by the power of water","cn":"使用水力发电的；水力产生的","ex":{"en":"a hydroelectric plant","cn":"水力发电站"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"水力发电的;（电）由水力发的","en":"Hydroelectric means relating to or involving electricity made from the energy of running water."}]},"examples":[{"en":"hydroelectric power","cn":"水力发出的电"},{"en":"a hydroelectric plant","cn":"水力发电站"}]},"hunched":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（常指因寒冷、生病或愁苦）耸肩弓身的，伏首前倾的","en":"If you are hunched, or hunched up, you are leaning forwards with your shoulders raised and your head down, often because you are cold, ill, or unhappy.","ex":{"en":"A solitary hunched figure emerged from Number Ten","cn":"一个缩头弓身的孤独身影从唐宁街10号出来了。"}}]},"media":{"uk":"media/uk/hunched__gb_1.mp3","us":"media/us/hunched__us_1.mp3"},"examples":[{"en":"He sat hunched over his breakfast.","cn":"他弓着背吃早饭。"},{"en":"a hunched figure","cn":"弓着背的人形"}],"oxford":{"phon":"hʌntʃt","pos":"adjective","senses":[{"en":"bending the top part of your body forward and raising your shoulders and back","cn":"弓身；弓背；耸肩","ex":{"en":"a hunched figure","cn":"弓着背的人形"}}]},"base":"hunch"},"half":{"media":{"uk":"media/uk/half__gb_1.mp3","us":"media/us/half__us_1.mp3"},"oxford":{"phon":"hɑːf","pos":"noun","senses":[{"en":"either of two equal parts into which something is or can be divided","cn":"一半；半","ex":{"en":"two and a half kilos (= 2½)","cn":"两公斤半"}},{"en":"either of two periods of time into which a sports game, concert, etc. is divided","cn":"（比赛、音乐会等的）半场，半局","ex":{"en":"No goals were scored in the first half.","cn":"上半场没有得分。"}},{"en":"one of the defending players in hockey or rugby whose position is between those who play at the front of a team and those who play at the back","cn":"（曲棍球或橄榄球）前卫","lab":"North American English"},{"en":"one of the two attacking players in american football whose position is behind the quarterback and next to the full backs","cn":"（美式足球的）半卫","lab":"North American English"},{"en":"the position a half back plays at (also called a tailback in american football)","cn":"半卫的位置","g":"[uncountable]","lab":"North American English"},{"en":"half a pint (= 0.568 of a litre in the UK and some other countries, and 0.473 of a litre in the US) of beer or a similar drink","cn":"（啤酒等饮料的）半品脱","lab":"British English, informal，，","ex":{"en":"Two halves of bitter, please.","cn":"请来两杯半品脱的苦啤酒。"}},{"en":"an amount equal to half of something/somebody","cn":"半数","ex":{"en":"I'll see you in half an hour.","cn":"半小时后见。"},"pos":"determiner, pronoun"},{"en":"the largest part of something","cn":"绝大部分（时间、乐趣、麻烦等）","ex":{"en":"Half the time you don't even listen to what I say.","cn":"你大部分时间甚至没听我说的话。"},"pos":"determiner, pronoun"},{"en":"to the extent of half","cn":"到一半程度；半","ex":{"en":"The glass was half full.","cn":"玻璃杯半满。"},"pos":"adverb"},{"en":"partly","cn":"部分地","ex":{"en":"The chicken was only half cooked.","cn":"鸡只煮了半熟。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"FRACTION 分数词","cn":"半;二分之一","en":"Half of an amount or object is one of two equal parts that together make up the whole number, amount, or object.","ex":{"en":"They need an extra two and a half thousand pounds to complete the project","cn":"他们还需要2,500英镑才能完成该项目。"}},{"pos":"ADV 副词","cn":"部分地;在某种程度上;有点","en":"You use half to say that something is only partly the case or happens to only a limited extent.","ex":{"en":"His eyes were half closed","cn":"他双眼半闭。"}},{"pos":"N-COUNT 可数名词","cn":"（足球、橄榄球、篮球比赛等的）半场，半时，半局","en":"In games such as football, rugby, and basketball, matches are divided into two equal periods of time which are called halves.","ex":{"en":"The only goal was scored by Jakobsen early in the second half.","cn":"唯一的一粒进球是由雅各布森在下半场刚开始时打进的。"}},{"pos":"N-COUNT 可数名词","cn":"（啤酒、苹果酒等的）半品脱","en":"A half is half a pint of a drink such as beer or cider.","ex":{"en":"...a half of lager and a sandwich.","cn":"半品脱淡啤酒和一份三明治"}},{"pos":"N-COUNT 可数名词","cn":"(儿童乘坐公共汽车或火车时的）半（价）票","en":"A half is a half-price bus or train ticket for a child."},{"pos":"ADV 副词","cn":"一半…血统地","en":"You use half to say that someone has parents of different nationalities. For example, if you are half German, one of your parents is German but the other is not.","ex":{"en":"She was half Italian and half English.","cn":"她是半意大利半英国血统。"}},{"pos":"PREP-PHRASE 短语介词","cn":"（时间）…点半","en":"You use half past to refer to a time that is thirty minutes after a particular hour.","ex":{"en":"'What time were you planning lunch?'—'Half past twelve, if that's convenient.'","cn":"“你打算什么时候吃午饭？”“如果方便的话，12点半。”"}},{"pos":"PREP 介词","cn":"同 half past","en":"Half means the same as half past .","ex":{"en":"They are supposed to be here at about half four.","cn":"他们应该在4点半左右到达这里。"}},{"pos":"ADV 副词","cn":"（用于形容词前，表示强调或夸张）非常，极其","en":"You can use half before an adjective describing an extreme quality, as a way of emphasizing and exaggerating something.","ex":{"en":"He felt half dead with tiredness","cn":"他已经累得半死不活了。"}},{"pos":"ADV 副词","cn":"（有时用在否定句中，表示非常肯定的意思）","en":"Half is sometimes used in negative statements, with a positive meaning, to emphasize a particular fact or quality. For example, if you say 'he isn't half lucky', you mean that he is very lucky.","ex":{"en":"You don't half sound confident","cn":"你听起来非常有信心。"}},{"pos":"ADV 副词","cn":"一点也不;差得远","en":"You use not half or not half as to show that you do not think something is as good or impressive as it is meant to be.","ex":{"en":"You're not half the man you think you are","cn":"你根本不是你自己想象的那种人。"}},{"pos":"PHRASE 短语","cn":"非常…的;更…的;非同寻常的","en":"When you use an expression such as a problem and a half or a meal and a half, you are emphasizing that your reaction to it is either very favourable or very unfavourable.","ex":{"en":"It becomes clear that Montgomerie has a job and half on his hands.","cn":"很显然，蒙哥马利手头有一大堆事情要做。"}},{"pos":"PHRASE 短语","cn":"妻子;丈夫;另一半","en":"If you talk about your better half or your other half you mean your wife, your husband, or the person of the opposite sex that you live with.","ex":{"en":"I was worried that my career, my children and my other half might become too much to cope with.","cn":"我担心我的事业、我的孩子们和我的那口子可能会让我应付不过来。"}},{"pos":"PHRASE 短语","cn":"以一半;一半地","en":"If you increase something by half, half of the original amount is added to it. If you decrease it by half, half of the original amount is taken away from it.","ex":{"en":"The number of 7 year olds who read poorly has increased by half over the past 5 years","cn":"不识字的7岁儿童的人数在过去5年里增加了一半。"}},{"pos":"PHRASE 短语","cn":"做事不认真;做事马虎","en":"If you say that someone never does things by halves, you mean that they always do things very thoroughly.","ex":{"en":"In Italy they rarely do things by halves. Designers work thoroughly, producing the world's most wearable clothes in the most beautiful fabrics.","cn":"在意大利，人们很少马虎从事。设计师们精益求精，用最美丽的布料制造出世界上最适合穿着的衣服。"}},{"pos":"PHRASE 短语","cn":"（两人）平均分摊，平分（费用）","en":"If two people go halves, they divide the cost of something equally between them.","ex":{"en":"He's constantly on the phone to his girlfriend. We have to go halves on the phone bill which drives me mad.","cn":"他总和女友煲电话粥。令我抓狂的是电话费可是我们俩平摊的。"}},{"pos":"","cn":"","en":"half the battle→see: ; half an ear→see: ; too clever by half→see: ;"}]},"examples":[{"en":"‘It sounds very difficult.’ ‘ You don't know the half of it. ’ “","cn":"这事听起来很难。” “你还未了解更困难的一面呢。”"},{"en":"You're expecting twins? Well, you never did do anything by halves.","cn":"你要生对双胞胎？唔，你做事倒从来不会只做一半。"}]},"headquarters":{"oxford":{"phon":"ˌhedˈkwɔːtəz","pos":"noun","senses":[{"en":"a place from which an organization or a military operation is controlled; the people who work there","cn":"总部；总公司；大本营；司令部","ex":{"en":"The firm’s headquarters is/are in London.","cn":"公司总部设在伦敦。"}}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"总部;总公司","en":"The headquarters of an organization are its main offices.","ex":{"en":"...fraud squad officers from London's police headquarters","cn":"伦敦警察总部诈骗案调查组的警官们"}}]},"media":{"uk":"media/uk/headquarters__gb_1.mp3","us":"media/us/headquarters__us_1.mp3"},"examples":[{"en":"Several companies have their headquarters in the area.","cn":"有几家公司总部设在这个地区。"},{"en":"Headquarters in Dublin has/have agreed.","cn":"都柏林总部已经同意了。"}]},"hundred":{"media":{"uk":"media/uk/hundred__gb_1.mp3","us":"media/us/hundred__us_1.mp3"},"oxford":{"phon":"ˈhʌndrəd","pos":"number","senses":[{"en":"100","cn":"一百","ex":{"en":"One hundred (of the children) have already been placed with foster families.","cn":"有一百名（儿童）已经获安排领养。"}},{"en":"a large amount","cn":"许多；大量","lab":"usually informal","ex":{"en":"hundreds of miles away","cn":"数百里之遥"}},{"en":"the numbers from 100 to 999","cn":"100 到 999 间的数目；百位数","g":"[plural]","ex":{"en":"We're talking about a figure in the low hundreds.","cn":"我们谈论的是一个两三百的数字。"}},{"en":"the years of a particular century","cn":"某个世纪的年代","g":"[plural]","ex":{"en":"the early nineteen hundreds (= written ‘early 1900s’)","cn":"20 世纪早期"}},{"en":"used to express whole hours in the 24-hour system","cn":"（表示 24 小时制的整点）一点整、两点整、三点整等","ex":{"en":"twelve hundred hours (= 12.00 midday)","cn":"十二点整"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"（数字）100","en":"A hundred or one hundred is the number 100.","ex":{"en":"According to one official more than a hundred people have been arrested.","cn":"一名官员称有一百多人被捕。"}},{"pos":"QUANT 数量词","cn":"许多;大量","en":"If you refer to hundreds of things or people, you are emphasizing that there are very many of them.","ex":{"en":"Hundreds of tree species face extinction","cn":"许许多多树种濒临灭绝。"}},{"pos":"PHRASE 短语","cn":"（表示强调）百分之百，完全","en":"You can use a hundred per cent or one hundred per cent to emphasize that you agree completely with something or that it is completely right or wrong.","ex":{"en":"Are you a hundred per cent sure it's your neighbour?","cn":"你百分之百肯定是你的邻居吗？"}}]},"examples":[{"en":"Every player gave a hundred per cent tonight.","cn":"今天晚上所有的运动员都尽了最大的努力。"},{"en":"If I've said it once, I've said it a hundred times.","cn":"这事我曾经说过，而且是说过很多次了。"}]},"http":{"oxford":{"phon":"ˌeɪtʃ tiː tiː ˈpiː","pos":"abbreviation","senses":[{"en":"Hypertext Transfer Protocol (the set of rules that control the way data is sent and received over the internet)","cn":"超文本传送协议"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（用于因特网信息的格式化和传送的）超文本传输协议","en":"HTTP is a way of formatting and transmitting messages on the Internet. HTTP is an abbreviation for (缩略=) 'hypertext transfer protocol'."}]},"media":{"uk":"media/uk/http__gb_1.mp3","us":"media/us/http__us_1.mp3"}},"halves":{"lemma":"half","media":{"uk":"media/uk/halves__gb_1.mp3","us":"media/us/halves__us_1.mp3"}},"holistic":{"media":{"uk":"media/uk/holistic__gb_1.mp3","us":"media/us/holistic__us_1.mp3"},"oxford":{"phon":"həˈlɪstɪk","pos":"adjective","senses":[{"en":"considering a whole thing or being to be more than a collection of parts","cn":"整体的；全面的","ex":{"en":"a holistic approach to life","cn":"对生命的全面探讨"}},{"en":"treating the whole person rather than just the symptoms (= effects) of a disease","cn":"功能整体性的","lab":"medical","ex":{"en":"holistic medicine","cn":"整体医学"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"整体论的;整体主义的","en":"Holistic means based on the principles of holism.","ex":{"en":"...practitioners of holistic medicine.","cn":"整体医学执业医师"}}]},"examples":[{"en":"a holistic approach to life","cn":"对生命的全面探讨"},{"en":"holistic medicine","cn":"整体医学"}]},"horse":{"media":{"uk":"media/uk/horse__gb_1.mp3","us":"media/us/horse__us_1.mp3"},"oxford":{"phon":"hɔːs","pos":"noun","senses":[{"en":"a large animal with four legs, a mane (= long thick hair on its neck) and a tail. Horses are used for riding on, pulling carriages, etc.","cn":"马","ex":{"en":"to ride a horse","cn":"骑马"}},{"en":"horse racing","cn":"赛马","g":"[plural]","lab":"informal","ex":{"en":"He lost a lot of money on the horses (= by gambling on races).","cn":"他赌赛马输了很多钱。"}},{"en":"a large object with legs, and sometimes handles, used in gymnastics","cn":"（体操器械）木马"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"马","en":"A horse is a large animal which people can ride. Some horses are used for pulling ploughs and carts.","ex":{"en":"A small man on a grey horse had appeared.","cn":"一个骑着灰马的小个子男人出现了。"}},{"pos":"N-PLURAL 复数名词","cn":"赛马","en":"When you talk about the horses, you mean horse races in which people bet money on the horse which they think will win.","ex":{"en":"He still likes to bet on the horses.","cn":"他仍然喜欢赌马。"}},{"pos":"N-COUNT 可数名词","cn":"（体操器械）跳马","en":"A vaulting horse is a tall piece of gymnastics equipment for jumping over."},{"pos":"PHRASE 短语","cn":"从知情人那里直接（获悉）","en":"If you hear something from the horse's mouth, you hear it from someone who knows that it is definitely true.","ex":{"en":"He has got to hear it from the horse's mouth. Then he can make a judgment as to whether his policy is correct or not.","cn":"他必须得到千真万确的信息才行。这样他才能判断自己的政策是否正确。"}},{"pos":"See also:","cn":"","en":"→see: ;"},{"pos":"","cn":"","en":"相关词组：horse around"}]},"examples":[{"en":"He lost a lot of money on the horses (= by gambling on races).","cn":"他赌赛马输了很多钱。"},{"en":"He mounted his horse and rode off.","cn":"他跨上马骑走了。"}]},"have":{"media":{"uk":"media/uk/have__gb_1.mp3","us":"media/us/have__us_1.mp3"},"oxford":{"phon":"həv","pos":"verb","senses":[{"en":"to own, hold or possess something","cn":"有；持有；占有","lab":"British English","sc":"own/hold","ex":{"en":"He had a new car and a boat.","cn":"他有一辆新车和一条船。"}},{"en":"be made up of","cn":"由…组成","sc":"consist of","ex":{"en":"In 2018 the party had 10 000 members.","cn":"2018 年时该党有 1 万名党员。"}},{"en":"to show a quality or feature","cn":"显示出，带有（性质、特征）","sc":"quality/feature","ex":{"en":"The ham had a smoky flavour.","cn":"这火腿散发着一种烟熏的香味。"}},{"en":"to show a particular quality by your actions","cn":"（通过行动）表现出（品质）","sc":"quality/feature","ex":{"en":"Surely she didn't have the nerve to say that to him?","cn":"她一定没有胆量跟他这样说吧？"}},{"en":"used to show a particular relationship","cn":"（表示关系）有","sc":"relationship","ex":{"en":"He's got three children.","cn":"他有三个孩子。"}},{"en":"to be able to make use of something because it is available","cn":"能用","sc":"something available","ex":{"en":"Have you got time to call him?","cn":"你有时间给他打电话吗？"}},{"en":"to be in a position where you ought to do something","cn":"有责任（或义务）","sc":"should/must","ex":{"en":"We have a duty to care for the refugees.","cn":"我们有义务关怀这些难民。"}},{"en":"to be in a position of needing to do something","cn":"须要，有必要（做某事）","sc":"should/must","ex":{"en":"I've got a lot of homework tonight.","cn":"我今晚有很多家庭作业要做。"}},{"en":"to let a feeling or thought come into your mind","cn":"感到；想到","lab":"informal","sc":"feeling/thought","ex":{"en":"He had the strong impression that someone was watching him.","cn":"他强烈地感觉到有人在监视他。"}},{"en":"to suffer from an illness or a disease","cn":"患病；得病；染病","sc":"illness","ex":{"en":"I've got a headache.","cn":"我头痛。"}},{"en":"to hold somebody/something in the way mentioned","cn":"抓住；握着；支承","sc":"hold","ex":{"en":"She'd got him by the collar.","cn":"她抓住了他的衣领。"}},{"en":"to place or keep something in a particular position","cn":"使放在；使保持（在）","sc":"put/keep in a position","ex":{"en":"Mary had her back to me.","cn":"玛丽背对着我。"}},{"en":"to experience something","cn":"经受；经历；经验","sc":"experience","ex":{"en":"I went to a few parties and had a good time.","cn":"我参加了几次聚会，过得很愉快。"}},{"en":"to organize or hold an event","cn":"组织；举办","sc":"event","ex":{"en":"Let's have a party.","cn":"我们办一次聚会吧。"}},{"en":"to eat, drink or smoke something","cn":"吃；喝；吸（烟等）","sc":"eat/drink/smoke","ex":{"en":"to have breakfast/lunch/dinner","cn":"吃早饭；吃午饭；吃正餐"}},{"en":"to perform a particular action","cn":"进行（活动）","lab":"British English","sc":"do something","ex":{"en":"I had a swim to cool down.","cn":"我游了泳，凉快凉快。"}},{"en":"to give birth to somebody/something","cn":"生；生产","sc":"give birth","ex":{"en":"She's going to have a baby.","cn":"她快生孩子了。"}},{"en":"to produce a particular effect","cn":"产生（效果）","sc":"effect","ex":{"en":"His paintings had a strong influence on me as a student.","cn":"我当学生时，他的画对我产生过强烈的影响。"}},{"en":"to receive something from somebody","cn":"收到；接到","lab":"North American English","sc":"receive","ex":{"en":"I had a letter from my brother this morning.","cn":"我今天早晨收到了弟弟的一封信。"}},{"en":"to be given something; to have something done to you","cn":"得到；接受；受到","sc":"receive","ex":{"en":"I'm having treatment for my back problem.","cn":"我正接受背部疾患的治疗。"}},{"en":"to experience the effects of somebody’s actions","cn":"接受（某人行为的效果）","sc":"receive","ex":{"en":"We have orders coming in from all over the world.","cn":"我们接到来自世界各地的订单。"}},{"en":"to suffer the effects of what somebody else does to you","cn":"蒙受（他人所为的后果）","sc":"have something done","ex":{"en":"She had her bag stolen.","cn":"她的包被偷了。"}},{"en":"to cause something to be done for you by somebody else","cn":"让（他人）为你做（某事）","sc":"have something done","ex":{"en":"You've had your hair cut!","cn":"你理发了！"}},{"en":"to tell or arrange for somebody to do something for you","cn":"要（或安排）（某人）做（某事）","lab":"informal","sc":"have something done","ex":{"en":"He had the bouncers throw them out of the club.","cn":"他叫保安人员把他们轰出了俱乐部。"}},{"en":"to cause somebody/something to be in a particular state; to make somebody react in a particular way","cn":"使处于（某状态）；使做出（某种反应）","sc":"put somebody/something in a condition","ex":{"en":"I want to have everything ready in good time.","cn":"我要求一切都得准时备妥。"}},{"en":"to be with somebody","cn":"同（某人）在一起","sc":"be with","ex":{"en":"She had some friends with her.","cn":"她和几个朋友在一起。"}},{"en":"to take care of somebody/something in your home, especially for a limited period","cn":"（尤指短期在自己家中）照料，照看","g":"[no passive]","sc":"guests","ex":{"en":"We're having the kids for the weekend.","cn":"这个周末孩子们要到我们家来由我们照料。"}},{"en":"to entertain somebody in your home","cn":"（在家中）招待，款待","g":"[no passive]","sc":"guests","ex":{"en":"We had some friends to dinner last night.","cn":"我们昨晚请了几位朋友来家里吃饭了。"}},{"en":"to allow something; to accept something without complaining","cn":"允许；容忍","sc":"allow","ex":{"en":"I'm sick of your rudeness—I won't have it any longer!","cn":"你的无礼我已经受够了，我不会再容忍下去了！"}},{"en":"to put somebody at a disadvantage in an argument","cn":"辩过；胜过","lab":"informal","sc":"in argument","ex":{"en":"You've got me there. I hadn't thought of that.","cn":"你把我问住了。我没想过这个。"}},{"en":"to have sex with somebody","cn":"（与某人）发生性关系","lab":"slang","sc":"sex","ex":{"en":"He had her in his office.","cn":"他在他的办公室里和她搞上了。"}},{"en":"to trick or cheat somebody","cn":"欺骗；蒙骗","g":"[usually passive]","lab":"informal","sc":"trick","ex":{"en":"I'm afraid you've been had.","cn":"恐怕你上当了。"}},{"en":"to take or accept somebody for a particular role","cn":"让，接受（某人承担职务）","g":"[no passive]","sc":"for a job","ex":{"en":"Who can we have as treasurer?","cn":"我们让谁来主管财务？"}},{"en":"used with the past participle to form perfect tenses","cn":"（与过去分词连用构成完成时）","lab":"formal","ex":{"en":"I've finished my work.","cn":"我干完我的活儿了。"},"pos":"auxiliary verb"}]},"collins":{"senses":[{"pos":"AUX 助动词","cn":"(have 和 has 与过去分词连用构成动词的现在完成时)","en":"You use the forms have and has with a past participle to form the present perfect tense of verbs.","ex":{"en":"Alex has already gone","cn":"亚历克斯已经走了。"}},{"pos":"AUX 助动词","cn":"(had 与过去分词连用构成动词的过去完成时)","en":"You use the form had with a past participle to form the past perfect tense of verbs.","ex":{"en":"When I met her, she had just returned from a job interview","cn":"我遇见她时，她刚参加完一场求职面试回来。"}},{"pos":"AUX 助动词","cn":"(用于附加疑问句中)","en":"Have is used in question tags.","ex":{"en":"You haven't sent her away, have you?","cn":"你还没有把她送走，是吗？"}},{"pos":"AUX 助动词","cn":"(用于对带有 have,has 或 had 的句子作肯定或否定回答)","en":"You use have when you are confirming or contradicting a statement containing 'have', 'has', or 'had', or answering a question.","ex":{"en":"'You'd never seen the Marilyn Monroe film?' — 'No I hadn't.'","cn":"“你从未看过玛丽莲·梦露的电影？”“对，没有。”"}},{"pos":"AUX 助动词","cn":"（having 和过去分词连用，所引导的分句中提到的动作发生在另一个动作开始之前）","en":"The form having with a past participle can be used to introduce a clause in which you mention an action which had already happened before another action began.","ex":{"en":"He arrived in San Francisco, having left New Jersey on January 19th","cn":"1月19日离开新泽西后，他到了旧金山。"}},{"pos":"VERB 动词","cn":"（have 后接名词代替该名词作动词的用法，描述某一动作或事件）","en":"You can use have followed by a noun to talk about an action or event, when it would be possible to use the same word as a verb. For example, you can say 'I had a look at the photos' instead of 'I looked at the photos.'","ex":{"en":"I went out and had a walk around","cn":"我出去在周围散了一会儿步。"}},{"pos":"VERB 动词","cn":"（在英语口语或书面语中，have可以和很多名词连用以代替某个具体的动词，描述某一动作或事件）","en":"In normal spoken or written English, people use have with a wide range of nouns to talk about actions and events, often instead of a more specific verb. For example people are more likely to say 'we had ice cream' or 'he's had a shock' than 'we ate ice cream', or 'he's suffered a shock'.","ex":{"en":"Come and have a meal with us tonight","cn":"今晚来和我们一起吃饭吧。"}},{"pos":"VERB 动词","cn":"有;拥有","en":"You use have to say that someone or something owns a particular thing, or when you are mentioning one of their qualities or characteristics.","ex":{"en":"Oscar had a new bicycle","cn":"奥斯卡有一辆新自行车。"}},{"pos":"VERB 动词","cn":"有…要（做）；必须（做）","en":"If you have something to do, you are responsible for doing it or must do it.","ex":{"en":"He had plenty of work to do","cn":"他有很多工作要做。"}},{"pos":"VERB 动词","cn":"（用于代替 there is, 表示某事物存在或发生了某事）","en":"You can use have instead of 'there is' to say that something exists or happens. For example, you can say 'you have no alternative' instead of 'there is no alternative', or 'he had a good view from his window' instead of 'there was a good view from his window'.","ex":{"en":"He had two tenants living with him","cn":"有两位房客和他同住。"}},{"pos":"VERB 动词","cn":"（使）保持;（使）处于","en":"If you have something such as a part of your body in a particular position or state, it is in that position or state.","ex":{"en":"Mary had her eyes closed","cn":"玛丽双目紧闭。"}},{"pos":"VERB 动词","cn":"请人做;让人做","en":"If you have something done, someone does it for you or you arrange for it to be done.","ex":{"en":"I had your rooms cleaned and aired","cn":"我请人打扫了你的房间并通了风。"}},{"pos":"VERB 动词","cn":"遭遇（不愉快的事）","en":"If someone has something unpleasant happen to them, it happens to them.","ex":{"en":"We had our money stolen","cn":"我们的钱被偷了。"}},{"pos":"VERB 动词","cn":"劝说;让;命令","en":"If you have someone do something, you persuade, cause, or order them to do it.","ex":{"en":"If you happen to talk to him, have him call me","cn":"如果你碰巧能和他说话，让他给我打个电话。"}},{"pos":"VERB 动词","cn":"抓住（某人身体的某部位）","en":"If someone has you by a part of your body, they are holding you there and they are trying to hurt you or force you to go somewhere.","ex":{"en":"When the police came, Larry had him by the ear and was beating his head against the pavement.","cn":"警方赶到时，拉里正揪着他的耳朵，把他的头往人行道上撞。"}},{"pos":"VERB 动词","cn":"（从某人那里）得到","en":"If you have something from someone, they give it to you.","ex":{"en":"You can have my ticket","cn":"我可以把我的票给你。"}},{"pos":"VERB 动词","cn":"患有（疾病、残疾）","en":"If you have an illness or disability, you suffer from it.","ex":{"en":"I had a headache","cn":"我头疼。"}},{"pos":"VERB 动词","cn":"生（孩子）/怀（孩子）","en":"If a woman has a baby, she gives birth to it. If she is having a baby, she is pregnant.","ex":{"en":"My wife has just had a baby boy","cn":"我妻子刚生了个男孩。"}},{"pos":"VERB 动词","cn":"不允许;不容忍","en":"You can use have in expressions such as 'I won't have it' or 'I'm not having that', to mean that you will not allow or put up with something.","ex":{"en":"She wanted to be alone. They wouldn't have it","cn":"她想一个人呆着。他们不允许。"}},{"pos":"PHRASE 短语","cn":"根据谣传/传说","en":"You can use has it in expressions such as 'rumour has it that' or 'as legend has it' when you are quoting something that you have heard, but you do not necessarily think it is true.","ex":{"en":"Rumour has it that tickets were being sold for £300","cn":"据谣传，票卖到了300英镑。"}},{"pos":"PHRASE 短语","cn":"跟…过不去;总想找…的茬儿","en":"If someone has it in for you, they do not like you and they want to make life difficult for you.","ex":{"en":"He's always had it in for the Dawkins family.","cn":"他老是跟道金斯一家过不去。"}},{"pos":"PHRASE 短语","cn":"深藏不露;有两下子","en":"If you have it in you, you have abilities and skills which you do not usually use and which only show themselves in a difficult situation.","ex":{"en":"'You were brilliant!' he said. 'I didn't know you had it in you.'","cn":"“你真厉害！”他说，“我不知道你还有这两下子。”"}},{"pos":"PHR-RECIP相互短语","cn":"和…发生性关系","en":"To have it off with someone or have it away with someone means to have sex with them.","ex":{"en":"He reckons she's having it off with the gardener.","cn":"他认为她和园丁有一腿。"}},{"pos":"PHRASE 短语","cn":"捉弄;戏弄","en":"If you are having someone on, you are pretending that something is true when it is not true, for example as a joke or in order to tease them.","ex":{"en":"Malone's eyes widened. 'You're having me on, Liam.'","cn":"马隆瞪大了双眼。“你在戏弄我吧，利亚姆。”"}},{"pos":"PHRASE 短语","cn":"和…讲个明白;和…争论出个结果","en":"If you have it out or have things out with someone, you discuss a problem or disagreement very openly with them, even if it means having an argument, because you think this is the best way to solve the problem.","ex":{"en":"Why not have it out with your critic, discuss the whole thing face to face?","cn":"为什么不和批评你的人讲个明白，面对面地把整件事情谈一谈呢？"}},{"pos":"","cn":"","en":"to be had→see: ; to have had it→see: ;"},{"pos":"PHR-MODAL 情态动词短语","cn":"需要;必须;不得不","en":"You use have to when you are saying that something is necessary or required, or must happen. If you do not have to do something, it is not necessary or required.","ex":{"en":"He had to go to Germany","cn":"他不得不去德国。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"肯定;一定","en":"You can use have to in order to say that you feel certain that something is true or will happen.","ex":{"en":"There has to be some kind of way out","cn":"一定会有某种解决办法的。"}}]},"examples":[{"en":"It was no surprise when she left him — everyone knew he had it coming to him.","cn":"她离开了他，这丝毫不奇怪。大家都知道是他自己造成的。"},{"en":"‘Does your brother have brown hair?’ ‘No, he’s got blond hair.’ “","cn":"你弟弟的头发是棕色的吗？” “不，他有一头金发。”"}]},"historical":{"media":{"uk":"media/uk/historical__gb_1.mp3","us":"media/us/historical__us_1.mp3"},"oxford":{"phon":"hɪˈstɒrɪkl","pos":"adjective","senses":[{"en":"connected with the past","cn":"（有关）历史的","ex":{"en":"You must place these events in their historical context.","cn":"必须把这些事件与其历史背景联系起来看。"}},{"en":"connected with the study of history","cn":"有关历史研究的；历史学的","ex":{"en":"historical documents/records/research","cn":"史学文献／档案／研究"}},{"en":"about people and events in the past","cn":"历史题材的","ex":{"en":"a historical novel/setting","cn":"历史小说／背景"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"历史（上）的","en":"Historical people, situations, or things existed in the past and are considered to be a part of history.","ex":{"en":"...an important historical figure.","cn":"重要的历史人物"}},{"pos":"ADJ 形容词","cn":"（书籍、电影或图片）描述历史的，基于史实的","en":"Historical books, films, or pictures describe or represent people, situations, or things that existed in the past.","ex":{"en":"He is writing a historical novel about nineteenth-century France.","cn":"他正在写一本描述19世纪法国的历史小说。"}},{"pos":"ADJ 形容词","cn":"历史学科的;史学的","en":"Historical information, research, and discussion is related to the study of history.","ex":{"en":"...historical records.","cn":"史籍"}},{"pos":"ADJ 形容词","cn":"历史背景的;历史视角的","en":"If you look at an event within a historical context, you look at what was happening at that time and what had happened previously, in order to judge the event and its importance.","ex":{"en":"It was this kind of historical context that Morris brought to his work","cn":"莫里斯的作品正是基于这样一种历史背景。"}}]},"examples":[{"en":"You must place these events in their historical context.","cn":"必须把这些事件同它们的历史环境联系起来看。"},{"en":"The building is of historical importance.","cn":"这栋建筑有重要的历史研究价值。"}]},"happening":{"media":{"uk":"media/uk/happening__gb_1.mp3","us":"media/us/happening__us_1.mp3"},"oxford":{"phon":"ˈhæpənɪŋ","pos":"noun","senses":[{"en":"an event; something that happens, often something unusual","cn":"事件；发生的事情（常指不寻常的）","g":"[usually plural]","ex":{"en":"There have been strange happenings here lately.","cn":"这儿最近发生了一些怪事。"}},{"en":"an artistic performance or event that is not planned","cn":"即兴艺术表演"},{"en":"where there is a lot of exciting activity; fashionable","cn":"热闹的；时髦的","ex":{"en":"a happening place","cn":"时髦的地方"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发生的事情;意外事件;难以解释的事","en":"Happenings are things that happen, often in a way that is unexpected or hard to explain.","ex":{"en":"The Budapest office plans to hire freelance reporters to cover the latest happenings.","cn":"布达佩斯办事处计划聘用自由撰稿记者来报道最近发生的一些事件。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热闹的;活跃的;新潮的","en":"If you describe something or someone as happening, you mean that they are exciting or lively, and involved in the newest fashions or trends.","ex":{"en":"...a definitive area-by-area guide to the hip and happening bands.","cn":"介绍各个地区新潮流行乐队的权威指南"}}]},"examples":[{"en":"There have been strange happenings here lately.","cn":"这儿最近发生了一些怪事。"},{"en":"a happening place","cn":"时髦的地方"}],"base":"happen"},"household":{"media":{"uk":"media/uk/household__gb_1.mp3","us":"media/us/household__us_1.mp3"},"oxford":{"phon":"ˈhaʊshəʊld","pos":"noun","senses":[{"en":"all the people living together in a house or flat","cn":"一家人；家庭；一户","ex":{"en":"Most households now own at least one car.","cn":"大多数家庭现在至少有一辆汽车。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"家庭;一家人;同住一幢房子的人","en":"A household is all the people in a family or group who live together in a house.","ex":{"en":"...growing up in a male-only household","cn":"在一个只有男性的家庭里长大"}},{"pos":"N-SING 单数名词","cn":"家;家务","en":"The household is your home and everything that is connected with looking after it.","ex":{"en":"My husband gave me cash to manage the household, but none of it was ever my own.","cn":"丈夫给我钱来持家，但这些钱一毫一厘都不属于我。"}},{"pos":"ADJ 形容词","cn":"家喻户晓的;众人皆知的","en":"Someone or something that is a household name or word is very well known.","ex":{"en":"Today, fashion designers are household names","cn":"今天，时装设计师是家喻户晓的人物。"}},{"pos":"ADJ 形容词","cn":"（用于王室警卫队名称中）皇家的","en":"Household is used in the names of groups of soldiers who have the job of protecting a king or queen and their family.","ex":{"en":"...the Household Cavalry Mounted Regiment.","cn":"皇家骑兵团"}}]},"examples":[{"en":"Most households now own at least one car.","cn":"大多数家庭现在至少有一辆汽车。"},{"en":"household bills/chores/goods (= connected with looking after a house and the people living in it)","cn":"家庭账单/杂务/用品"}]},"hens":{"lemma":"hen"},"handling":{"oxford":{"phon":"ˈhændlɪŋ","pos":"noun","senses":[{"en":"the way that somebody deals with or treats a situation, a person, an animal, etc.","cn":"（对形势、人、动物等的）处理，对付，对待","ex":{"en":"I was impressed by his handling of the affair.","cn":"他对此事的处理方式我甚感佩服。"}},{"en":"the action of touching, feeling or holding something with your hands","cn":"（手的）触摸，触摸感觉，握，拿","ex":{"en":"toys that can stand up to rough handling","cn":"经得起摔打的玩具"}},{"en":"the action of organizing or controlling something","cn":"组织；控制；管理","ex":{"en":"data handling on computer","cn":"计算机的数据处理"}},{"en":"the cost of dealing with an order, delivering goods, booking tickets, etc.","cn":"（订货、送货、订票等的）费用，手续费","ex":{"en":"a small handling charge","cn":"少许手续费"}},{"en":"the way in which a vehicle can be controlled by the driver","cn":"（车辆的）驾驶，操纵","ex":{"en":"a car designed for easy handling","cn":"为驾驶简便而设计的汽车"}},{"en":"the act or cost of transporting goods from one place to another","cn":"运输；运费","lab":"British English also"}]},"media":{"uk":"media/uk/handling__gb_1.mp3","us":"media/us/handling__us_1.mp3"},"examples":[{"en":"I was impressed by his handling of the affair.","cn":"他对此事的处理方式我甚感佩服。"},{"en":"a car designed for easy handling","cn":"为驾驶简便而设计的汽车"}],"base":"handle"},"handicap":{"media":{"uk":"media/uk/handicap__gb_1.mp3","us":"media/us/handicap__us_1.mp3"},"oxford":{"phon":"ˈhændikæp","pos":"noun","senses":[{"en":"a permanent physical or mental condition that makes it difficult to do some things that most other people can do","cn":"生理缺陷；弱智；残疾","g":"[countable, uncountable]","lab":"old-fashioned, usually offensive，，","ex":{"en":"She was born with what was then called a handicap.","cn":"她生来就患有当时所谓的残疾。"}},{"en":"something that makes it difficult for somebody to do something","cn":"障碍；阻碍","g":"[countable]","ex":{"en":"Not speaking the language proved to be a bigger handicap than I'd imagined.","cn":"事实证明，不会讲这种语言所造成的障碍比我想象的大。"}},{"en":"a race or competition in which those who have most skill must run further, carry extra weight, etc. in order to give all those taking part an equal chance of winning; the disadvantage that is given to somebody you are competing against in such a race or competition","cn":"让赛，让步赛（使参赛的优势方跑得更远、增加负重等）；（让步赛中给优势方施加的）障碍，不利条件","g":"[countable]","lab":"sport"},{"en":"the number of strokes (= hits) over par (= the expected number of strokes for a good player) that a player usually needs to complete a course. Handicaps are used to give an advantage to weaker players so that competition is more equal when they play against stronger players.","cn":"差点（给弱者减少的杆数）","g":"[countable]","ex":{"en":"He plays off a handicap of 5.","cn":"他的让分盘为5。"}},{"en":"to make something more difficult for somebody to do","cn":"妨碍；阻碍","ex":{"en":"Smaller parties are seriously handicapped by the electoral system.","cn":"小党派受到这种选举制度的严重制约。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（生理或智力上的）残障，残疾","en":"A handicap is a physical or mental disability.","ex":{"en":"He lost his leg when he was ten, but learnt to overcome his handicap.","cn":"他10岁时失去了一条腿，但他学会了克服自己的残疾。"}},{"pos":"N-COUNT 可数名词","cn":"不利条件;障碍","en":"A handicap is an event or situation that places you at a disadvantage and makes it harder for you to do something.","ex":{"en":"She was away from school for 15 weeks, a handicap she could have done without","cn":"她有15周没上学，这给她带来了本不该有的障碍。"}},{"pos":"VERB 动词","cn":"妨碍;使不利","en":"If an event or a situation handicaps someone or something, it places them at a disadvantage.","ex":{"en":"Greater levels of stress may seriously handicap some students","cn":"压力的加重可能会给一些学生带来严重的负面影响。"}},{"pos":"N-COUNT 可数名词","cn":"（高尔夫运动中的）给弱者增加的杆数，差点","en":"In golf, a handicap is an advantage given to someone who is not a good player, in order to make the players more equal. As you improve, your handicap gets lower.","ex":{"en":"I see your handicap is down from 16 to 12.","cn":"我发现你的差点已从16杆降到了12杆。"}},{"pos":"N-COUNT 可数名词","cn":"（赛马比赛的）让步赛","en":"In horse racing, a handicap is a race in which some competitors are given a disadvantage of extra weight in an attempt to give everyone an equal chance of winning."}]},"examples":[{"en":"Not speaking the language proved to be a bigger handicap than I'd imagined.","cn":"事实证明不会讲这种语言造成的障碍比我所想像的大。"},{"en":"Despite her handicap, Jane is able to hold down a full-time job.","cn":"简尽管有生理缺陷，却能够保住一份全职工作。"}]},"highlight":{"media":{"uk":"media/uk/highlight__gb_1.mp3","us":"media/us/highlight__us_1.mp3"},"oxford":{"phon":"ˈhaɪlaɪt","pos":"verb","senses":[{"en":"to emphasize something, especially so that people give it more attention","cn":"突出；强调","ex":{"en":"The report highlighted the importance of exercise to maintain a healthy body.","cn":"报告强调了锻炼对保持健康体魄的重要性。"}},{"en":"to mark part of a text with a special coloured pen, or to mark an area on a computer screen, to emphasize it or make it easier to see","cn":"将（文本的某部分）用彩笔做标记；将（计算机屏幕的某区域）增强亮度；使醒目","ex":{"en":"I've highlighted the important passages in yellow.","cn":"我用黄色标出了重要段落。"}},{"en":"to make some parts of your hair a lighter colour than the rest by using a chemical substance on them","cn":"挑染（将部分头发染成浅色）","ex":{"en":"I’m having my hair highlighted.","cn":"我正在突出显示我的头发。"}},{"en":"the best, most interesting or most exciting part of something","cn":"最好（或最精彩、最激动人心）的部分","ex":{"en":"One of the highlights of the trip was seeing the Taj Mahal.","cn":"这次旅行中的最精彩的一件事是参观泰姬陵。"},"pos":"noun"},{"en":"areas of hair that are lighter than the rest, usually because a chemical substance has been put on them","cn":"亮色挑染的头发","g":"[plural]","ex":{"en":"She’s had blonde highlights put into her hair.","cn":"她的头发染上了金色的亮点。"},"pos":"noun"},{"en":"the light or bright part of a picture or photograph","cn":"（图画或照片的）强光部分","g":"[plural]","lab":"specialist","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使突出;强调;使注意","en":"If someone or something highlights a point or problem, they emphasize it or make you think about it.","ex":{"en":"Last year Collins wrote a moving ballad which highlighted the plight of the homeless","cn":"去年，柯林斯写了一首动人的抒情歌曲，突出描绘了无家可归者的苦境。"}},{"pos":"VERB 动词","cn":"（用荧光笔）标出;（在计算机屏幕上）突出显示","en":"To highlight a piece of text means to mark it in a different colour, either with a special type of pen or on a computer screen.","ex":{"en":"Highlight the chosen area by clicking and holding down the left mouse button.","cn":"点击并摁住鼠标左键将所选区域高亮显示。"}},{"pos":"N-COUNT 可数名词","cn":"最有趣（或最精彩、最重要）的部分","en":"The highlights of an event, activity, or period of time are the most interesting or exciting parts of it.","ex":{"en":"...a match that is likely to prove one of the highlights of the tournament","cn":"可能是本次联赛中最精彩的比赛之一"}},{"pos":"N-PLURAL 复数名词","cn":"挑染的头发;（头发经阳光照射后产生强光效果的）浅色部分","en":"Highlights in a person's hair are narrow lighter areas made by dyeing or sunlight."}]},"examples":[{"en":"The report highlights the major problems facing society today.","cn":"报告特别强调了当今社会所面临的主要问题。"},{"en":"One of the highlights of the trip was seeing the Taj Mahal.","cn":"这次旅行中的最精彩的一件事是参观泰姬陵。"}]},"hallucination":{"media":{"uk":"media/uk/hallucination__gb_1.mp3","us":"media/us/hallucination__us_1.mp3"},"oxford":{"phon":"həˌluːsɪˈneɪʃn","pos":"noun","senses":[{"en":"the fact of seeming to see or hear somebody/something that is not really there, especially because of illness or drugs","cn":"幻觉，幻视，幻听（尤指生病或吸毒所致）","g":"[countable, uncountable]","ex":{"en":"to have hallucinations","cn":"产生幻觉"}},{"en":"something that is seen or heard when it is not really there","cn":"幻视（或幻听）到的东西；幻觉；幻象","g":"[countable]","ex":{"en":"Was the figure real or just a hallucination?","cn":"那个人影是真的呢，还是幻象？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（因生病或吸毒所致的）幻觉（体验）","en":"A hallucination is the experience of seeing something that is not really there because you are ill or have taken a drug.","ex":{"en":"The drug induces hallucinations at high doses","cn":"大剂量地服用该药会致幻。"}},{"pos":"N-COUNT 可数名词","cn":"（因生病或吸毒所见到的）幻象","en":"A hallucination is something that is not real that someone sees because they are ill or have taken a drug.","ex":{"en":"Perhaps the footprint was a hallucination.","cn":"脚印可能只是幻象。"}}]},"examples":[{"en":"Was the figure real or just a hallucination?","cn":"那个人影是真的呢，还是幻象？"},{"en":"High temperatures can cause hallucination.","cn":"高烧可使人产生幻觉。"}]},"hurtle":{"oxford":{"phon":"ˈhɜːtl","pos":"verb","senses":[{"en":"to move very fast in a particular direction","cn":"（向某个方向）飞驰，猛冲","ex":{"en":"A runaway car came hurtling towards us.","cn":"一辆失控的汽车朝我们猛冲过来。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"猛冲;飞驰","en":"If someone or something hurtles somewhere, they move there very quickly, often in a rough or violent way.","ex":{"en":"A pretty young girl came hurtling down the stairs.","cn":"一个漂亮的小女孩从楼梯上冲下来。"}}]},"media":{"uk":"media/uk/hurtle__gb_1.mp3","us":"media/us/hurtle__us_1.mp3"},"examples":[{"en":"A runaway car came hurtling towards us.","cn":"一辆失控的汽车朝我们飞驰而来。"},{"en":"All of a sudden, a car came hurtling round the corner.","cn":"突然﹐一辆汽车从拐角处冲了出来。"}]},"humility":{"oxford":{"phon":"hjuːˈmɪləti","pos":"noun","senses":[{"en":"the quality of not thinking that you are better than other people; the quality of being humble","cn":"谦逊；谦虚","ex":{"en":"Her first defeat was an early lesson in humility.","cn":"她的第一次失败使她很早便懂得了谦逊。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"谦逊;谦虚;谦恭","en":"Someone who has humility is not proud and does not believe they are better than other people.","ex":{"en":"...a deep sense of humility","cn":"极为谦虚"}}]},"media":{"uk":"media/uk/humility__gb_1.mp3","us":"media/us/humility__us_1.mp3"},"examples":[{"en":"Her first defeat was an early lesson in humility.","cn":"她的第一次失败使她很早便懂得了谦逊。"},{"en":"an act of genuine humility","cn":"真正谦虚的举动"}]},"hindering":{"lemma":"hinder"},"harming":{"lemma":"harm"},"harshly":{"oxford":{"phon":"ˈhɑːʃli","pos":"adverb","senses":[{"en":"in a cruel, severe and unkind way","cn":"残酷的；严酷的；严厉的","ex":{"en":"She was treated very harshly.","cn":"她受到了苛刻的对待。"}},{"en":"in a way that is too strong and bright; in a way that is ugly or unpleasant to look at","cn":"强烈刺眼的；丑陋的","ex":{"en":"harshly lit supermarkets","cn":"灯光昏暗的超市"}},{"en":"in a way that is unpleasant to listen to","cn":"刺耳的；难听的","ex":{"en":"The bell sounded, ringing harshly in the quiet classroom.","cn":"铃声响起，在安静的教室里响起。"}},{"en":"in a way that is too strong and rough and likely to damage something","cn":"粗糙的；毛糙的；刺激性强的","ex":{"en":"The shovel scraped harshly over the floor.","cn":"铲子狠狠地刮过地板。"}}]},"media":{"uk":"media/uk/harshly__gb_1.mp3","us":"media/us/harshly__us_1.mp3"},"examples":[{"en":"She was treated very harshly.","cn":"她受到了苛刻的对待。"},{"en":"Alec laughed harshly.","cn":"亚历克刺耳地大笑。"}]},"hardship":{"media":{"uk":"media/uk/hardship__gb_1.mp3","us":"media/us/hardship__us_1.mp3"},"oxford":{"phon":"ˈhɑːdʃɪp","pos":"noun","senses":[{"en":"a situation that is difficult and unpleasant because you do not have enough money, food, clothes, etc.","cn":"艰难；困苦；拮据","ex":{"en":"economic/financial, etc. hardship","cn":"经济、财政等困难"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"艰难;艰苦;贫困","en":"Hardship is a situation in which your life is difficult or unpleasant, often because you do not have enough money.","ex":{"en":"Many people are suffering economic hardship","cn":"很多人正处于经济困难之中。"}}]},"examples":[{"en":"It was no hardship to walk home on such a lovely evening.","cn":"在这么一个宜人的傍晚步行回家一点也不辛苦。"},{"en":"People suffered many hardships during that long winter.","cn":"在那个漫长的冬季，人们吃了很多苦头。"}]},"harmful":{"oxford":{"phon":"ˈhɑːmfl","pos":"adjective","senses":[{"en":"causing damage or injury to somebody/something, especially to a person’s health or to the environment","cn":"（尤指对健康或环境）有害的，导致损害的","ex":{"en":"the harmful effects of alcohol","cn":"酒精的害处"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有害的;（尤指）有损健康的","en":"Something that is harmful has a bad effect on something else, especially on a person's health.","ex":{"en":"...the harmful effects of smoking","cn":"吸烟的危害"}}]},"media":{"uk":"media/uk/harmful__gb_1.mp3","us":"media/us/harmful__us_1.mp3"},"examples":[{"en":"Many household products are potentially harmful.","cn":"很多家用产品有潜在的危害。"},{"en":"Fruit juices can be harmful to children's teeth.","cn":"果汁可能损坏儿童的牙齿。"}]},"hands-off":{"oxford":{"phon":"ˌhændz ˈɒf","pos":"adjective","senses":[{"en":"dealing with people or a situation by not becoming involved and by allowing people to do what they want to","cn":"不介入的；放手的","ex":{"en":"a hands-off approach to staff management","cn":"不干涉的职员管理方法"}}]},"media":{"uk":"media/uk/hands_off_1_gb_1.mp3","us":"media/us/hands_off_1_us_1.mp3"},"examples":[{"en":"a hands-off approach to staff management","cn":"不干涉的职员管理方法"},{"en":"The government has a hands-off approach to the industry.","cn":"政府对这一行业采取不干涉的政策。"}]},"hardly":{"media":{"uk":"media/uk/hardly__gb_1.mp3","us":"media/us/hardly__us_1.mp3"},"oxford":{"phon":"ˈhɑːdli","pos":"adverb","senses":[{"en":"almost no; almost not; almost none","cn":"几乎不；几乎没有","ex":{"en":"There's hardly any tea left.","cn":"没有剩什么茶了。"}},{"en":"used especially after ‘can’ or ‘could’ and before the main verb, to emphasize that it is difficult to do something","cn":"（尤用于 can 或 could 之后，主要动词之前，强调做某事很难）","ex":{"en":"I can hardly keep my eyes open (= I'm almost falling asleep).","cn":"我困得都快睁不开眼了。"}},{"en":"used to suggest that something is unlikely or unreasonable or that somebody is silly for saying or doing something","cn":"（表示不大可能、不合理或愚蠢）","ex":{"en":"He is hardly likely to admit he was wrong.","cn":"他不大可能承认自己错了。"}},{"en":"used to say that something has just begun, happened, etc.","cn":"刚刚；才","lab":"formal","ex":{"en":"We can't stop for coffee now, we've hardly started.","cn":"现在不能停下来喝咖啡，我们才刚刚开始工作呢。"}}]},"collins":{"senses":[{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（用于修正作出的陈述，表示不大可能）几乎不，几乎没有","en":"You use hardly to modify a statement when you want to emphasize that it is only a small amount or detail which makes it true, and that therefore it is best to consider the opposite statement as being true.","ex":{"en":"I hardly know you","cn":"我不太认识你。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"几乎不;几乎没有","en":"You use hardly in expressions such as hardly ever ,hardly any, and hardly anyone to mean almost never, almost none, or almost no-one.","ex":{"en":"We ate chips every night, but hardly ever had fish","cn":"我们每晚吃炸薯条，但几乎从不吃鱼。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（用在否定句中构成双重否定，用于强调某事属实或经常发生）几乎不","en":"You use hardly before a negative statement in order to emphasize that something is usually true or usually happens.","ex":{"en":"Hardly a day goes by without a visit from someone.","cn":"几乎每天都有人来。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（用于can之后，表示强调）很难","en":"When you say you can hardly do something, you are emphasizing that it is very difficult for you to do it.","ex":{"en":"I can hardly believe it's been over eight years since you used to go camping at Cedar Creek","cn":"我几乎无法相信现在距离你过去常常去松溪露营的日子已经有8年多了。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（表示两件事情紧接着发生）刚刚，才","en":"If you say hardly had one thing happened when something else happened, you mean that the first event was followed immediately by the second.","ex":{"en":"He had hardly collected the papers on his desk when the door burst open","cn":"他刚收起桌上的文件，门就猛地开了。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（表示希望听者或读者赞同自己）并不，丝毫不","en":"You use hardly to mean 'not' when you want to suggest that you are expecting your listener or reader to agree with your comment.","ex":{"en":"We have not seen the letter, so we can hardly comment on it","cn":"我们还没有看到这封信，所以无从发表意见。"}},{"pos":"CONVENTION 惯用语","cn":"（尤用于对不赞同的说法表示惊奇或不满）不可能，不会吧","en":"You use 'hardly' to mean 'no', especially when you want to express surprise or annoyance at a statement that you disagree with.","ex":{"en":"'They all thought you were marvellous!' —'Well, hardly.'","cn":"“他们都认为你很棒！”“哦，不可能吧！”"}}]},"examples":[{"en":"‘Couldn't you have just said no?’ ‘Well, hardly (= of course not), she's my wife's sister.’ “","cn":"你不能就说声不吗？” “喔，不可能，她是我小姨子。”"},{"en":"We can't stop for coffee now, we've hardly started.","cn":"现在不能停下来喝咖啡，我们刚刚才开始工作呢。"}]},"hardware":{"media":{"uk":"media/uk/hardware__gb_1.mp3","us":"media/us/hardware__us_1.mp3"},"oxford":{"phon":"ˈhɑːdweə(r)","pos":"noun","senses":[{"en":"the machines and electronic parts in a computer or other electronic system","cn":"硬件","lab":"computing","ex":{"en":"We supply computer hardware to businesses.","cn":"我们向公司提供计算机硬件。"}},{"en":"tools and equipment that are used in the house and garden","cn":"（家庭及园艺用）工具，设备，五金制品","lab":"also British English, old-fashioned，，","ex":{"en":"a hardware shop/store","cn":"五金店"}},{"en":"the equipment, machines and vehicles used to do something","cn":"硬件设备；机器；车辆","ex":{"en":"tanks and other military hardware","cn":"坦克和其他军事装备"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（计算机）硬件","en":"In computer systems, hardware refers to the machines themselves as opposed to the programs which tell the machines what to do."},{"pos":"N-UNCOUNT 不可数名词","cn":"重武器;军事装备","en":"Military hardware is the machinery and equipment that is used by the armed forces, such as tanks, aircraft, and missiles."},{"pos":"N-UNCOUNT 不可数名词","cn":"（家庭和园艺用的）五金制品，金属器具","en":"Hardware refers to tools and equipment that are used in the home and garden, for example saucepans, screwdrivers, and lawnmowers."}]},"examples":[{"en":"tanks and other military hardware","cn":"坦克和其他军事装备"},{"en":"a hardware shop","cn":"五金店"}]},"humble":{"media":{"uk":"media/uk/humble__gb_1.mp3","us":"media/us/humble__us_1.mp3"},"oxford":{"phon":"ˈhʌmbl","pos":"adjective","senses":[{"en":"showing you do not think that you are as important as other people","cn":"谦逊的；虚心的","ex":{"en":"Be humble enough to learn from your mistakes.","cn":"要虚心地从自己的错误中学习。"}},{"en":"used to suggest that you are not as important as other people, but in a way that is not sincere or not very serious","cn":"（表示谦逊，但不够诚挚或认真）","lab":"ironic or humorous","ex":{"en":"In my humble opinion, you were in the wrong.","cn":"依拙见，你错了。"}},{"en":"having a low rank or social position","cn":"（级别或地位）低下的，卑微的","ex":{"en":"a man of humble birth/origins","cn":"出身低微的人"}},{"en":"not large or special in any way","cn":"不大的；没有特别之处的","ex":{"en":"a humble farmhouse","cn":"小农舍"}},{"en":"to make somebody feel that they are not as good or important as they thought they were","cn":"贬低；使感到卑微","ex":{"en":"He was humbled by her generosity.","cn":"她的大度使他觉得自己渺小。"},"pos":"verb"},{"en":"to easily defeat an opponent, especially a strong or powerful one","cn":"轻松打败（尤指强大的对手）","g":"[usually passive]","ex":{"en":"The world champion was humbled last night in three rounds.","cn":"这位世界冠军昨晚三个回合就被轻松击败。"},"pos":"verb"},{"en":"to show that you are not too proud to ask for something, admit that you have been wrong, etc.","cn":"低声下气；谦逊；虚心","ex":{"en":"He refused to humble himself and ask her forgiveness.","cn":"他拒绝谦卑自己并请求她的原谅。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"谦逊的;谦虚的;谦卑的","en":"A humble person is not proud and does not believe that they are better than other people.","ex":{"en":"He gave a great performance, but he was very humble","cn":"他的表演非常出色，但他却很谦虚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（社会地位）低下的，卑贱的","en":"People with low social status are sometimes described as humble.","ex":{"en":"Spyros Latsis started his career as a humble fisherman in the Aegean","cn":"斯皮罗斯·拉齐斯的第一份职业是爱琴海上一名地位卑贱的渔夫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗陋的;简陋的;不起眼的","en":"A humble place or thing is ordinary and not special in any way.","ex":{"en":"There are restaurants, both humble and expensive, that specialize in them","cn":"专门做这些菜的餐馆既有毫不起眼的也有价格昂贵的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愚（见）；拙（见）","en":"People use humble in a phrase such as in my humble opinion as a polite way of emphasizing what they think, even though they do not feel humble about it.","ex":{"en":"It is, in my humble opinion, perhaps the best steak restaurant in Great Britain.","cn":"依拙见，这可能是英国最好的牛排馆。"}},{"pos":"PHRASE 短语","cn":"道歉赔不是;承认错误","en":"If you eat humble pie, you speak or behave in a way which tells people that you admit you were wrong about something.","ex":{"en":"Anson was forced to eat humble pie and publicly apologise to her.","cn":"安森被迫认错并公开向她道歉。"}},{"pos":"VERB 动词","cn":"轻易击败（强大的对手）","en":"If you humble someone who is more important or powerful than you, you defeat them easily.","ex":{"en":"Honda won fame in the 1980s as the little car company that humbled the industry giants","cn":"本田在20世纪80年代作为一家轻易挫败行业巨头的小汽车公司而声名鹊起。"}},{"pos":"VERB 动词","cn":"使谦逊;使感到卑微;羞辱","en":"If something or someone humbles you, they make you realize that you are not as important or good as you thought you were.","ex":{"en":"Ted's words humbled me","cn":"特德的话让我感到自惭。"}}]},"examples":[{"en":"The company has worked its way up from humble beginnings to become the market leader.","cn":"公司已从创业期的微不足道发展成了市场的主导者。"},{"en":"The world champion was humbled last night in three rounds.","cn":"这位世界冠军昨晚三个回合就被轻松击败。"}]},"holding":{"media":{"uk":"media/uk/holding__gb_1.mp3","us":"media/us/holding__us_1.mp3"},"oxford":{"phon":"ˈhəʊldɪŋ","pos":"noun","senses":[{"en":"a number of shares that somebody has in a company","cn":"股份","ex":{"en":"She has a 40% holding in the company.","cn":"她持有公司 40% 的股份。"}},{"en":"an amount of property that is owned by a person, museum, library, etc.","cn":"私有财产；（博物馆、图书馆等的）馆藏","ex":{"en":"one of the most important private holdings of Indian art","cn":"印度艺术最重要的私人馆藏之一"}},{"en":"a piece of land that is rented by somebody and used for farming","cn":"租种的土地"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"股份","en":"If you have a holding in a company, you own shares in it.","ex":{"en":"That would increase Olympia & York's holding to 35%","cn":"那样就会使奥林匹亚约克公司的股份上升到35%。"}},{"pos":"N-COUNT 可数名词","cn":"（自有或租用的）农田，耕地","en":"A holding is an area of farm land which is owned or rented by the person who grows crops on it."},{"pos":"N-PLURAL 复数名词","cn":"（博物馆、图书馆、美术馆等的）收藏品，馆藏","en":"The holdings of a place such as a museum, library, or art gallery are the items such as books or paintings which are kept there."},{"pos":"ADJ 形容词","cn":"（活动或行动）暂时用作维持现状的","en":"A holding operation or action is a temporary one that is intended to keep a situation under control and to prevent it from becoming worse.","ex":{"en":"A garden is, at best, a holding operation against nature.","cn":"花园充其量不过是抗拒自然的一时之法。"}}]},"examples":[{"en":"one of the most important private holdings of Indian art","cn":"印度艺术最重大的私人馆藏之一。"},{"en":"She has a 40% holding in the company.","cn":"她持有公司 40% 的股份。"}],"base":"hold"},"huge":{"media":{"uk":"media/uk/huge__gb_1.mp3","us":"media/us/huge__us_1.mp3","img":["media/ldoce/img/huge.jpg"]},"oxford":{"phon":"hjuːdʒ","pos":"adjective","senses":[{"en":"extremely large in size or amount; great in degree","cn":"巨大的；极多的；程度高的","ex":{"en":"The sums of money involved are potentially huge.","cn":"涉及的金额可能很大。"}},{"en":"very successful","cn":"非常成功的；走红的","lab":"informal","ex":{"en":"I think this band is going to be huge.","cn":"我想这支乐队要走红了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（体积）巨大的，庞大的","en":"Something or someone that is huge is extremely large in size.","ex":{"en":"...a tiny little woman with huge black glasses","cn":"戴着一副硕大黑框眼镜的娇小女子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量、程度上）巨大的，极大的","en":"Something that is huge is extremely large in amount or degree.","ex":{"en":"I have a huge number of ties because I never throw them away","cn":"我有超多条领带，因为我从来不肯扔掉它们。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（规模上）巨大的，极大的","en":"Something that is huge exists or happens on a very large scale, and involves a lot of different people or things.","ex":{"en":"Another team is looking at the huge problem of debts between companies","cn":"另一组人正在研究公司间严重的债务问题。"}}]},"examples":[{"en":"He gazed up at her with huge brown eyes.","cn":"他睁着棕色的大眼睛盯着她。"},{"en":"This is going to be a huge problem for us.","cn":"这将是我们的一大难题。"}]},"hood":{"media":{"img":["media/pic/hats_comp.jpg","media/thumb/hood.jpg"],"uk":"media/uk/hood__gb_1.mp3","us":"media/us/hood__us_1.mp3"},"oxford":{"phon":"hʊd","pos":"noun","senses":[{"en":"a part of a coat, etc. that you can pull up to cover the back and top of your head","cn":"风帽，兜帽（外衣的一部分，可拉起蒙住头颈）","ex":{"en":"a jacket with a detachable hood","cn":"有可拆卸风帽的夹克"}},{"en":"a piece of cloth put over somebody’s face and head so that they cannot be recognized or so that they cannot see","cn":"（布质）面罩","ex":{"en":"The detainees were led away with black hoods over their heads.","cn":"被拘留者被带走，头上蒙着黑色头巾。"}},{"en":"a piece of coloured silk or fur worn over an academic gown to show the kind of degree held by the person wearing it","cn":"学位连领帽（表示学位种类）"},{"en":"a folding cover over a car, child's buggy, etc.","cn":"（汽车、婴儿车等的）折叠式车篷","lab":"especially British English","ex":{"en":"We drove all the way with the hood down.","cn":"我们一路上敞着车篷开车。"}},{"en":"the metal part over the front of a vehicle, usually covering the engine","cn":"（车辆的）引擎盖","lab":"North American English","ex":{"en":"the sound of a bird hitting the hood of the car","cn":"鸟撞到汽车发动机罩的声音"}},{"en":"a cover placed over a device or machine, for example, to protect it","cn":"（设备或机器的）防护罩，罩","ex":{"en":"a lens hood","cn":"镜头遮光罩"}},{"en":"hoodlum (= a violent criminal, especially one who is part of a gang)","cn":"暴徒，恶棍（尤指属于某团伙者）","lab":"especially North American English, slang，，"},{"en":"a neighbourhood, especially a person’s own neighbourhood","cn":"街区；邻里；左邻右舍","lab":"especially North American English, slang，，"},{"en":"the state or quality of","cn":"状态；性质；品质","ex":{"en":"childhood","cn":"儿童时期"},"pos":"suffix"},{"en":"a group of people of the type mentioned","cn":"（某类人的）集体","ex":{"en":"the priesthood","cn":"司祭团"},"pos":"suffix"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（外衣的）风帽，兜帽","en":"A hood is a part of a coat which you can pull up to cover your head. It is in the shape of a triangular bag attached to the neck of the coat at the back."},{"pos":"N-COUNT 可数名词","cn":"面罩;头罩","en":"A hood is a bag made of cloth, which is put over someone's head and face so that they cannot be recognized or so that they cannot see."},{"pos":"N-COUNT 可数名词","cn":"（汽车的）发动机罩，引擎罩","en":"The hood of a car is the metal cover over the engine at the front."},{"pos":"N-COUNT 可数名词","cn":"折叠式车篷;（设备上的）罩，防护罩","en":"A hood is a covering on a vehicle or a piece of equipment, which is usually curved and can be removed.","ex":{"en":"Why aren't all lenses supplied with a lens hood?","cn":"为什么不给所有的镜头都配上遮光罩呢？"}},{"pos":"N-COUNT 可数名词","cn":"抽油烟机;（厨房）排气罩","en":"A cooker hood is an electrical device fitted over a cooker above head height, and containing an extractor fan and usually a light."}]},"examples":[{"en":"We drove all the way with the hood down.","cn":"我们一路上敞着车篷开车。"},{"en":"a jacket with a detachable hood","cn":"有拆除式风帽的夹克"}]},"historically":{"oxford":{"phon":"hɪˈstɒrɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with the past","cn":"历史地","ex":{"en":"The book is historically inaccurate.","cn":"这本书与史实不符。"}},{"en":"in a way that is connected with the study of history","cn":"与历史研究相关地；历史学地","ex":{"en":"historically significant documents","cn":"具有历史意义的文件"}}]},"media":{"uk":"media/uk/historically__gb_1.mp3","us":"media/us/historically__us_1.mp3"},"examples":[{"en":"Historically, there has always been a great deal of rivalry between the two families.","cn":"这两个家族世世代代对立斗争。"},{"en":"The book is historically inaccurate.","cn":"这本书与史实不符。"}]},"honesty":{"media":{"uk":"media/uk/honesty__gb_1.mp3","us":"media/us/honesty__us_1.mp3"},"oxford":{"phon":"ˈɒnəsti","pos":"noun","senses":[{"en":"the quality of being honest","cn":"诚实；老实；正直","ex":{"en":"She answered all my questions with her usual honesty.","cn":"她像平常一样老老实实地回答了我的所有问题。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"诚实;正直;坦诚","en":"Honesty is the quality of being honest.","ex":{"en":"They said the greatest virtues in a politician were integrity, correctness and honesty.","cn":"他们说政治家身上最重要的美德就是正直、得体和诚实。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"银扇草;金钱花","en":"Honesty is a plant whose seeds are contained in silvery-white papery discs."}]},"examples":[{"en":"She answered all my questions with her usual honesty.","cn":"她像平常一样老老实实地回答了我的所有问题。"},{"en":"The book isn't, in all honesty, as good as I expected.","cn":"说实话，这本书并没有我预期的那么好。"}]},"heavy":{"media":{"uk":"media/uk/heavy__gb_1.mp3","us":"media/us/heavy__us_1.mp3","img":["media/ldoce/img/heavy.jpg"]},"oxford":{"phon":"ˈhevi","pos":"adjective","senses":[{"en":"weighing a lot; difficult to lift or move","cn":"重的；沉的","lab":"especially North American English","sc":"weighing a lot","ex":{"en":"a heavy weight/load","cn":"重物；重载"}},{"en":"more or worse than usual in amount, degree, etc.","cn":"（在数量、程度等方面）超出一般的，比一般严重的","sc":"worse than usual","ex":{"en":"the noise of heavy traffic","cn":"繁忙交通的噪声"}},{"en":"doing the thing mentioned more, or more deeply, than usual","cn":"（做某事）过量的，超出一般的，过度的","g":"[only before noun]","sc":"drinker/smoker/sleeper","ex":{"en":"a heavy drinker/smoker","cn":"酒瘾／烟瘾大的人"}},{"en":"large and solid","cn":"重型的；大型的","sc":"solid","ex":{"en":"big, dark rooms full of heavy furniture","cn":"装满厚实家具、又大又暗的房间"}},{"en":"thick","cn":"厚的","sc":"material","ex":{"en":"heavy curtains","cn":"厚窗帘"}},{"en":"full of or loaded with something","cn":"充满，满载（某物）","lab":"literary","sc":"full of something","ex":{"en":"trees heavy with apples","cn":"挂满苹果的树"}},{"en":"large and powerful","cn":"重型的；大型的","g":"[usually before noun]","sc":"machines","ex":{"en":"a wide range of engines and heavy machinery/equipment","cn":"各种各样的发动机和重型机械／设备"}},{"en":"involving a lot of work or activity; very busy","cn":"工作（或活动）多的；繁忙的","g":"[usually before noun]","sc":"busy","ex":{"en":"a heavy schedule","cn":"安排很紧的日程"}},{"en":"hard, especially because it requires a lot of physical strength","cn":"辛苦的；费力的","sc":"work","ex":{"en":"heavy lifting","cn":"搬抬重物"}},{"en":"falling or hitting something with a lot of force","cn":"沉重的；猛烈的","sc":"fall/hit","ex":{"en":"a heavy fall/blow","cn":"重重的跌落／一击"}},{"en":"large in amount or very solid","cn":"量大的；厚实的","sc":"meal/food","ex":{"en":"a heavy lunch/dinner/meal","cn":"丰盛的午餐／正餐／一餐"}},{"en":"carrying heavy weapons","cn":"携带重武器的；重装的","g":"[only before noun]","sc":"army","ex":{"en":"the heavy infantry/cavalry","cn":"重步兵；重骑兵"}},{"en":"loud and deep","cn":"响而深沉的","sc":"sound","ex":{"en":"heavy breathing","cn":"粗重的呼吸声"}},{"en":"using a lot of something","cn":"使用很多…的；耗费…的","lab":"informal","sc":"using a lot","ex":{"en":"Older cars are heavy on gas.","cn":"老旧的汽车耗油多。"}},{"en":"serious; difficult to understand or enjoy","cn":"严肃的；难懂的；艰涩的","lab":"usually disapproving","sc":"serious/difficult","ex":{"en":"We found the play very heavy.","cn":"我们觉得这部戏很艰涩。"}},{"en":"dangerous because of big waves, etc.","cn":"危险的；汹涌的","sc":"sea/ocean","ex":{"en":"strong winds and heavy seas","cn":"风急浪高"}},{"en":"hot and without enough fresh air, in a way that feels unpleasant","cn":"闷热的；沉闷的","sc":"air/weather","ex":{"en":"It's very heavy—I think there'll be a storm.","cn":"天气很闷热，我觉得暴风雨要来了。"}},{"en":"wet, sticky and difficult to dig or to move over","cn":"黏重难挖的；泥泞难行的","sc":"soil"},{"en":"very strict and severe","cn":"苛刻的；严厉的","sc":"strict","ex":{"en":"Don't be so heavy on her—it wasn't her fault.","cn":"别对她这么苛刻，这不是她的过错。"}},{"en":"a large strong man whose job is to protect a person or place, often using violence","cn":"保镖；打手","g":"[countable]","lab":"informal","ex":{"en":"He lunged at the minister, but was soon pulled to the ground by a couple of heavies.","cn":"他突然冲向部长，但很快被几个保镖压倒在地。"},"pos":"noun"},{"en":"strong beer, especially bitter","cn":"烈性啤酒；（尤指）苦啤酒","g":"[uncountable]","lab":"Scottish English","ex":{"en":"a pint of heavy","cn":"一品脱烈性啤酒"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重的;沉的","en":"Something that is heavy weighs a lot.","ex":{"en":"These scissors are awfully heavy","cn":"这把剪刀太沉了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有…重的","en":"You use heavy to ask or talk about how much someone or something weighs.","ex":{"en":"How heavy are you?","cn":"你有多重？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大量的;重大的;严重的;强烈的;剧烈的","en":"Heavy means great in amount, degree, or intensity.","ex":{"en":"Heavy fighting has been going on","cn":"激烈的战斗一直持续不断。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"结实的;粗大的;厚重的","en":"Someone or something that is heavy is solid in appearance or structure, or is made of a thick material.","ex":{"en":"We talk in her Belgrade flat, full of heavy old brown furniture","cn":"我们在她位于贝尔格莱德的公寓里进行了交谈，那屋里满是结实的老式棕色家具。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（质地）黏重的","en":"A heavy substance is thick in texture.","ex":{"en":"It is advisable to mix coarse grit into heavy soil to improve drainage.","cn":"建议将粗砂掺到黏重的土壤里，以提高排水性能。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（饭菜）量大的，难消化的","en":"A heavy meal is large in amount and often difficult to digest.","ex":{"en":"He had been feeling drowsy, the effect of an unusually heavy meal.","cn":"他一直感到昏昏沉沉的，这是吃了一顿超级大餐的结果。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满…的;装满…的","en":"Something that is heavy with things is full of them or loaded with them.","ex":{"en":"The air is heavy with moisture","cn":"空气的湿度很大。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（呼吸）粗重的，深沉的","en":"If a person's breathing is heavy, it is very loud and deep.","ex":{"en":"Her breathing became slow and heavy.","cn":"她的呼吸变得缓慢而粗重。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动作）用力的，猛烈的","en":"A heavy movement or action is done with a lot of force or pressure.","ex":{"en":"...a heavy blow on the back of the skull","cn":"后脑勺遭到的一记重击"}},{"pos":"ADJ 形容词","cn":"（机器、武器等）重型的，大型的","en":"A heavy machine or piece of military equipment is very large and very powerful.","ex":{"en":"...government militia backed by tanks and heavy artillery.","cn":"以坦克和重型大炮为后盾的政府国民军"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"繁忙的;(日程)排满的","en":"If you describe a period of time or a schedule as heavy, you mean it involves a lot of work.","ex":{"en":"It's been a heavy day and I'm tired","cn":"忙了一天，我累坏了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"费力的;繁重的","en":"Heavy work requires a lot of strength or energy.","ex":{"en":"The business is thriving and Philippa employs two full-timers for the heavy work.","cn":"业务蒸蒸日上，菲莉帕雇用了两个全职员工来应付繁重的工作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"耗费…多的;大量使用…的","en":"If you say that something is heavy on another thing, you mean that it uses a lot of that thing or too much of that thing.","ex":{"en":"Tanks are heavy on fuel and destructive to roads.","cn":"坦克要耗费大量的燃料，而且会破坏道路。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(空气、天气等）阴沉的，闷热的","en":"Air or weather that is heavy is unpleasantly still, hot, and damp.","ex":{"en":"The outside air was heavy and moist and sultry.","cn":"外面的空气沉滞、潮湿而闷热。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表情）沉痛的，疲惫呆滞的，阴郁的","en":"If you describe a person's face as heavy, you mean that it looks sad, tired, or unfriendly.","ex":{"en":"Many of them were policemen, with their heavy faces and cropped hair.","cn":"他们中有很多人表情阴郁，留着平头，一看就是警察。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（心情）沉重的，悲伤的","en":"If your heart is heavy, you are sad about something.","ex":{"en":"Mr Maddison handed over his resignation letter with a heavy heart.","cn":"麦迪逊先生心情沉重地递上自己的辞呈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（形势）棘手的，难应付的","en":"A situation that is heavy is serious and difficult to cope with.","ex":{"en":"I don't want any more of that heavy stuff.","cn":"我再也不想碰那种麻烦事了。"}},{"pos":"N-COUNT 可数名词","cn":"（雇作保镖或打手的）彪形大汉","en":"A heavy is a large strong man who is employed to protect a person or place, often by using violence.","ex":{"en":"They had employed heavies to evict shop squatters from neighbouring sites.","cn":"他们雇了一些彪形大汉，将附近私自占点的商贩都赶走了。"}},{"pos":"","cn":"","en":"to make heavy weather of something→see: ; a heavy hand→see: ;"}]},"examples":[{"en":"They started shouting at me. It got very heavy.","cn":"他们开始对我大喊大叫，情势变得很激烈。"},{"en":"She was struggling with a heavy suitcase.","cn":"她正费力地拎着一只沉重的手提箱。"}]},"hopeless":{"media":{"uk":"media/uk/hopeless__gb_1.mp3","us":"media/us/hopeless__us_1.mp3"},"oxford":{"phon":"ˈhəʊpləs","pos":"adjective","senses":[{"en":"if something is hopeless, there is no hope that it will get better or succeed","cn":"没有好转（或成功）希望的；无望的","ex":{"en":"a hopeless situation","cn":"无可挽救的局势"}},{"en":"extremely bad","cn":"极差的；糟糕透顶的","lab":"British English, informal，，","ex":{"en":"The buses are absolutely hopeless these days!","cn":"如今的公共汽车简直糟透了。"}},{"en":"very bad (at something); with no ability or skill","cn":"不能胜任的；无能的；缺乏技能的","lab":"especially British English","ex":{"en":"He's an absolutely hopeless driver.","cn":"他是一个绝对无可救药的司机。"}},{"en":"feeling or showing no hope","cn":"感到（或显得）无望的","ex":{"en":"She felt lonely and hopeless.","cn":"她感到孤独绝望。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不抱希望的;绝望的","en":"If you feel hopeless, you feel very unhappy because there seems to be no possibility of a better situation or success.","ex":{"en":"He had not heard her cry before in this uncontrolled, hopeless way","cn":"他从未听到过她如此绝望地失声痛哭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无望的;注定失败的;不会成功的","en":"Someone or something thing that is hopeless is certain to fail or be unsuccessful.","ex":{"en":"I don't believe your situation is as hopeless as you think. If you love each other, you'll work it out","cn":"我认为你们的情况并不像你想的那样无望。如果你们彼此相爱，总会找到解决办法的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）没有希望（做好…）的，不行的，无能的","en":"If someone is hopeless at something, they are very bad at it.","ex":{"en":"I'd be hopeless at working for somebody else","cn":"要是让我为别人工作，我一定做不好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"糟糕透顶的;无可救药的;极坏的","en":"You use hopeless to emphasize how bad or inadequate something or someone is.","ex":{"en":"I don't drive and the buses are quite hopeless","cn":"我不开车，公共汽车条件又太糟糕。"}}]},"examples":[{"en":"Most of the students are making good progress, but Michael is a hopeless case.","cn":"大多数学生都很有进步，唯有迈克尔不可救药。"},{"en":"‘I'll never manage it,’ he said hopelessly. “","cn":"我永远也搞不定。”他绝望地说。"}]},"hubris":{"media":{"uk":"media/uk/hubris__gb_1.mp3","us":"media/us/hubris__us_1.mp3"},"oxford":{"phon":"ˈhjuːbrɪs","pos":"noun","senses":[{"en":"the fact of being too proud. In literature, a character with this quality ignores warnings and laws and this usually results in their downfall and death.","cn":"傲慢；狂妄","ex":{"en":"He thought he was above the law and was ultimately punished for his hubris.","cn":"他认为自己能凌驾于法律之上，最终因狂妄自大受到了惩罚。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"傲慢;自大;自恃","en":"If you accuse someone of hubris, you are accusing them of arrogant pride.","ex":{"en":"...a tale of how an honourable man pursuing honourable goals was afflicted with hubris and led his nation towards catastrophe.","cn":"关于一个追求崇高目标的磊落君子是如何因自高自大而将自己的国家引向灾难的故事"}}]}},"hydrogen":{"oxford":{"phon":"ˈhaɪdrədʒən","pos":"noun","senses":[{"en":"a chemical element. Hydrogen is a gas that is the lightest of all the elements. It combines with oxygen to form water.","cn":"氢；氢气"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"氢;氢气","en":"Hydrogen is a colourless gas that is the lightest and commonest element in the universe."}]},"media":{"uk":"media/uk/hydrogen__gb_1.mp3","us":"media/us/hydrogen__us_1.mp3"}},"honestly":{"oxford":{"phon":"ˈɒnɪstli","pos":"adverb","senses":[{"en":"in an honest way","cn":"诚实地；正当地","ex":{"en":"I can't believe he got that money honestly.","cn":"我不相信他是靠正当手段弄到那笔钱的。"}},{"en":"used to emphasize that what you are saying is true, however surprising it may seem","cn":"真的；确实","ex":{"en":"I didn't tell anyone, honestly!","cn":"我确实没告诉过任何人！"}},{"en":"used to show that you think something is bad and are annoyed by it","cn":"（表示认为某事恶劣而恼火）","lab":"informal","ex":{"en":"Honestly! Whatever will they think of next?","cn":"真是的！他们接下来还会想出什么？"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（强调信念或情感）真的，的确","en":"You use honestly to emphasize that you are referring to your, or someone else's, true beliefs or feelings.","ex":{"en":"I honestly feel I cannot do any more to prove myself","cn":"我的确感到我已经尽全力来证明我自己了。"}},{"pos":"ADV 副词","cn":"（强调所说的是事实）真的，确实","en":"You use honestly to emphasize that you are telling the truth and that you want people to believe you.","ex":{"en":"Honestly, I don't know anything about it","cn":"真的，我对此事一无所知。"}},{"pos":"ADV 副词","cn":"（表示恼怒或不耐烦）天哪，哎呀","en":"You use honestly to indicate that you are annoyed or impatient.","ex":{"en":"Honestly, Nev! Must you be quite so crude!","cn":"哎呀，内夫! 你就非得如此粗俗吗！"}}]},"media":{"uk":"media/uk/honestly__gb_1.mp3","us":"media/us/honestly__us_1.mp3"},"examples":[{"en":"I can't believe he got that money honestly.","cn":"我不相信他是靠正当手段弄到那笔钱的。"},{"en":"Honestly! Whatever will they think of next?","cn":"真是的！他们接下来还会想出什么？"}]},"half-brother":{"oxford":{"phon":"ˈhɑːf brʌðə(r)","pos":"noun","senses":[{"en":"a person’s half-brother is a boy or man with either the same mother or the same father as they have","cn":"同母异父（或同父异母）的兄弟"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同母异父（或同父异母）兄弟","en":"Someone's half-brother is a boy or man who has either the same mother or the same father as they have."}]},"media":{"uk":"media/uk/half_brother_1_gb_1.mp3","us":"media/us/half_brother_1_us_1.mp3"}},"humiliating":{"media":{"uk":"media/uk/humiliating__gb_1.mp3","us":"media/us/humiliating__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人蒙受耻辱的;让人出丑的;丢脸的","en":"If something is humiliating, it embarrasses you and makes you feel ashamed and stupid.","ex":{"en":"The Conservatives have suffered a humiliating defeat","cn":"保守党人遭受到了一次颜面尽失的失败。"}}]},"examples":[{"en":"a humiliating defeat","cn":"耻辱的失败"}],"oxford":{"phon":"hjuːˈmɪlieɪtɪŋ","pos":"adjective","senses":[{"en":"making somebody feel ashamed or stupid and lose the respect of other people","cn":"让某人感到羞耻或愚蠢并失去他人的尊重","ex":{"en":"a humiliating defeat","cn":"耻辱的失败"}}]},"base":"humiliate"},"housebound":{"media":{"uk":"media/uk/housebound__gb_1.mp3","us":"media/us/housebound__us_1.mp3"},"oxford":{"phon":"ˈhaʊsbaʊnd","pos":"adjective","senses":[{"en":"unable to leave your house because you cannot walk very far as a result of being ill or old","cn":"（因病或年迈）不能离家的，出不了门的"},{"en":"people who are housebound","cn":"出不了门的人","g":"[plural]"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（通常指因为生病或步行不便而）出不了门的，足不出户的","en":"Someone who is housebound is unable to go out of their house, usually because they are ill or cannot walk far.","ex":{"en":"If you are housebound, you can arrange for a home visit from a specialist adviser.","cn":"如果您不方便出门，可以安排专业顾问登门拜访。"}}]}},"hijinks":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an American spelling of high jinks high jinks","cn":"的美式拼法"}]},"media":{"uk":"media/uk/hijinks__gb_1.mp3","us":"media/us/hijinks__us_1.mp3"},"oxford":{"phon":"ˈhaɪdʒɪŋks","pos":"noun","senses":[{"en":"lively and excited behaviour","cn":"狂欢作乐；喧闹"}]}},"hastily":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"quickly, perhaps too quickly","cn":"飞快地﹔仓促地"}]},"examples":[{"en":"‘Don’t worry,’ Jenny added hastily. ‘I checked with Lizzie first.’ “","cn":"别担心﹐”珍妮赶紧补充﹐“我先和莉齐核实过了。”","src":"ld"},{"en":"a hastily arranged news conference","cn":"仓促安排的记者招待会","src":"ld"}],"media":{"uk":"media/uk/hastily__gb_1.mp3","us":"media/us/hastily__us_1.mp3"},"oxford":{"phon":"ˈheɪstɪli","pos":"adverb","senses":[{"en":"very quickly, because you are in a hurry, especially when this has bad results","cn":"非常快，因为你很着急，尤其是当有不好的结果时","ex":{"en":"She hastily changed the subject.","cn":"她匆匆换了个话题。"}},{"en":"too quickly, without giving enough thought","cn":"操之过急，不加思索","ex":{"en":"Perhaps I spoke too hastily.","cn":"也许我说话太过草率了。"}}]}},"handshake":{"media":{"uk":"media/uk/handshake__gb_1.mp3","us":"media/us/handshake__us_1.mp3"},"oxford":{"phon":"ˈhændʃeɪk","pos":"noun","senses":[{"en":"an act of shaking somebody’s hand with your own, used especially to say hello or goodbye or when you have made an agreement","cn":"握手","ex":{"en":"Fawcett gave me a hearty handshake.","cn":"福西特和我亲切地握了握手。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"握手","en":"If you give someone a handshake, you take their right hand with your own right hand and hold it firmly or move it up and down, as a sign of greeting or to show that you have agreed about something such as a business deal.","ex":{"en":"John smiled and gave him a hearty handshake","cn":"约翰微笑着和他热情地握手。"}}]},"examples":[{"en":"He greeted me with a handshake and a glass of wine.","cn":"他与我握手问候﹐并递给我一杯酒。"},{"en":"Her handshake was warm and firm.","cn":"她的握手温暖而有力。"}]},"honest":{"media":{"uk":"media/uk/honest__gb_1.mp3","us":"media/us/honest__us_1.mp3"},"oxford":{"phon":"ˈɒnɪst","pos":"adjective","senses":[{"en":"always telling the truth, and never stealing or cheating","cn":"诚实的；老实的；正直的","ex":{"en":"an honest man/woman","cn":"诚实的男人／女人"}},{"en":"not hiding the truth about something","cn":"坦率的；坦诚的","ex":{"en":"Are you being completely honest about your feelings?","cn":"你丝毫没有隐瞒你的感情吗？"}},{"en":"showing an honest mind or attitude","cn":"真诚的；显示内心诚意的；表示态度诚恳的","ex":{"en":"She's got an honest face.","cn":"她有一张真诚的面孔。"}},{"en":"earned or resulting from hard work","cn":"辛勤挣得的；勤劳的","ex":{"en":"He hasn't done an honest day's work in his life.","cn":"他一辈子从未努力认真干过一天活儿。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诚实的;正直的","en":"If you describe someone as honest, you mean that they always tell the truth, and do not try to deceive people or break the law.","ex":{"en":"My dad was the most honest man I ever met","cn":"爸爸是我所见过的最正直的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦诚的;直率的;不隐瞒真相的","en":"If you are honest in a particular situation, you tell the complete truth or give your sincere opinion, even if this is not very pleasant.","ex":{"en":"I was honest about what I was doing","cn":"我对自己所做的事情并无隐瞒。"}},{"pos":"ADV 副词","cn":"真的;确实","en":"You say 'honest' before or after a statement to emphasize that you are telling the truth and that you want people to believe you.","ex":{"en":"I'm not sure, honest.","cn":"我不能肯定，真的。"}},{"pos":"PHRASE 短语","cn":"（表示强调）真的，实在，千真万确","en":"Some people say 'honest to God' to emphasize their feelings or to emphasize that something is really true.","ex":{"en":"I wish we weren't doing this, Lillian, honest to God, I really do","cn":"我希望我们没有在干这事，莉莲，真的，我真这么想。"}},{"pos":"PHRASE 短语","cn":"老实说;说实在的","en":"You can say 'to be honest' before or after a statement to indicate that you are telling the truth about your own opinions or feelings, especially if you think these will disappoint the person you are talking to.","ex":{"en":"To be honest the house is not quite our style","cn":"说实话，这所房子不太适合我们。"}}]},"examples":[{"en":"Let's be honest, she's only interested in Mike because of his money.","cn":"坦率地说吧，她对迈克有好感只不过是因为他有钱。"},{"en":"To be frank with you, I think your son has little chance of passing the exam.","cn":"坦白说，我认为你的儿子不大可能通过考试。"}]},"hunts":{"lemma":"hunt","media":{"uk":"media/uk/hunt__gb_1.mp3","us":"media/us/hunt__us_1.mp3"}},"haven't":{"media":{"uk":"media/uk/haven_t_1_gb_1.mp3","us":"media/us/haven_t_1_us_1.mp3"},"oxford":{"phon":"ˈhævnt","pos":"short form","senses":[{"en":"have not","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（have not 的常用口语形式）","en":"Haven't is the usual spoken form of 'have not'."}]}},"hamburger":{"media":{"uk":"media/uk/hamburger__gb_1.mp3","us":"media/us/hamburger__us_1.mp3"},"oxford":{"phon":"ˈhæmbɜːɡə(r)","pos":"noun","senses":[{"en":"beef cut into small pieces and made into a flat round shape that is then fried, often served in a bread roll","cn":"汉堡包；汉堡牛肉饼","g":"[countable]","lab":"British English also"},{"en":"beef that has been cut very small in a special machine","cn":"绞碎的牛肉；牛肉末","g":"[uncountable]","lab":"all North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"汉堡牛肉饼;汉堡包","en":"A hamburger is minced meat which has been shaped into a flat circle. Hamburgers are fried or grilled and then eaten, often in a bread roll."}]}},"handwriting":{"oxford":{"phon":"ˈhændraɪtɪŋ","pos":"noun","senses":[{"en":"writing that is done with a pen or pencil, not printed or typed","cn":"手写；书写","ex":{"en":"I didn't recognize the handwriting on the envelope.","cn":"我认不出信封上的字迹。"}},{"en":"a person’s particular style of writing in this way","cn":"笔迹；书法","ex":{"en":"I can't read his handwriting.","cn":"我看不懂他写的字。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"笔迹;字迹;笔法","en":"Your handwriting is your style of writing with a pen or pencil.","ex":{"en":"The address was in Anna's handwriting","cn":"地址是安娜的笔迹。"}}]},"media":{"uk":"media/uk/handwriting__gb_1.mp3","us":"media/us/handwriting__us_1.mp3"},"examples":[{"en":"I can't read his handwriting.","cn":"我看不懂他写的字。"},{"en":"I recognised her handwriting on the envelope.","cn":"我认出了信封上她的笔迹。"}]},"hamburgers":{"lemma":"hamburger","media":{"uk":"media/uk/hamburger__gb_1.mp3","us":"media/us/hamburger__us_1.mp3"}},"hints":{"lemma":"hint"},"hatch":{"media":{"uk":"media/uk/hatch__gb_1.mp3","us":"media/us/hatch__us_1.mp3","img":["media/ldoce/img/hatch.jpg"]},"oxford":{"phon":"hætʃ","pos":"verb","senses":[{"en":"to come out of an egg","cn":"孵出；出壳","g":"[intransitive]","ex":{"en":"Ten chicks hatched (out) this morning.","cn":"今早有十只小鸡出壳了。"}},{"en":"to break open so that a young bird, fish, insect, etc. can come out","cn":"孵化；破壳","g":"[intransitive]","ex":{"en":"The eggs are about to hatch.","cn":"这些蛋就要孵化了。"}},{"en":"to make a young bird, fish, insect, etc. come out of an egg","cn":"使（小鸟、小鱼、小虫等）孵出","g":"[transitive]","ex":{"en":"The female must find a warm place to hatch her eggs.","cn":"雌性必须找个温暖的地方孵蛋。"}},{"en":"to create a plan or an idea, especially in secret","cn":"策划；（尤指）密谋","g":"[transitive]","ex":{"en":"Have you been hatching up a deal with her?","cn":"你是不是在和她密谋什么交易？"}},{"en":"an opening or a door in a ship, aircraft or spacecraft","cn":"（飞机或航天器的）舱门","ex":{"en":"The engineer was peering into the service hatch.","cn":"工程师正透过维修舱口往里看。"},"pos":"noun"},{"en":"an opening in a wall between two rooms, especially a kitchen and a dining room, through which food can be passed","cn":"（尤指厨房和餐厅之间供传递食物的）传菜窗口","ex":{"en":"a serving hatch","cn":"传递饭菜的窗口"},"pos":"noun"},{"en":"an opening or a door in a floor or ceiling","cn":"（地面或天花板的）开口，门，盖子","ex":{"en":"a hatch to the attic","cn":"通往阁楼的门"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"孵出;出壳","en":"When a baby bird, insect, or other animal hatches, or when it is hatched, it comes out of its egg by breaking the shell.","ex":{"en":"As soon as the two chicks hatch, they leave the nest burrow","cn":"两只小鸟一出壳就离开了巢穴。"}},{"pos":"V-ERG 及物/不及物动词","cn":"破壳;孵化;孵（蛋）","en":"When an egg hatches or when a bird, insect, or other animal hatches an egg, the egg breaks open and a baby comes out.","ex":{"en":"The eggs hatch after a week or ten days","cn":"蛋在1周或10天后孵化。"}},{"pos":"VERB 动词","cn":"筹划;策划;谋划","en":"If you hatch a plot or a scheme, you think of it and work it out.","ex":{"en":"He has accused opposition parties of hatching a plot to assassinate the Pope.","cn":"他指控反对党密谋暗杀教皇。"}},{"pos":"N-COUNT 可数名词","cn":"（船甲板上的）舱口，舱口盖","en":"A hatch is an opening in the deck of a ship, through which people or cargo can go. You can also refer to the door of this opening as a hatch.","ex":{"en":"He stuck his head up through the hatch","cn":"他从舱口探出头来。"}},{"pos":"N-COUNT 可数名词","cn":"（墙上或屋顶的）小窗口;（尤指厨房和餐厅间传递菜肴等的）小窗口，传菜口","en":"A hatch is an opening in a ceiling or a wall, especially between a kitchen and a dining room, which you can pass something such as food through."},{"pos":"PHRASE 短语","cn":"做好准备（迎接挑战）；未雨绸缪","en":"If someone battens down the hatches, they prepare themselves so that they will be able to survive a coming difficulty or crisis.","ex":{"en":"Many firms are battening down the hatches and preparing to ride out the storm.","cn":"很多公司正在加紧准备，希望能挺过这场暴风雨。"}},{"pos":"","cn":"","en":"相关词组：hatch out"}]},"examples":[{"en":"The female must find a warm place to hatch her eggs.","cn":"母的必须找个温暖的地方孵蛋。"},{"en":"Have you been hatching up a deal with her?","cn":"你是不是在和她密谋什么交易？"}]},"harmonizes":{"lemma":"harmonize"},"hat":{"media":{"img":["media/pic/hats_comp.jpg","media/thumb/panama.jpg"],"uk":"media/uk/hat__gb_1.mp3","us":"media/us/hat__us_1.mp3"},"oxford":{"phon":"hæt","pos":"noun","senses":[{"en":"a piece of clothing made to fit the head, often with a brim (= a flat edge that sticks out), usually worn out of doors","cn":"（常指带檐的）帽子","ex":{"en":"a straw/woolly hat","cn":"草帽；毛线帽"}},{"en":"a position or role, especially an official or professional role, when you have more than one such role","cn":"（双重的）职位，角色（尤指官职或职业角色）","lab":"informal","ex":{"en":"I'm wearing two hats tonight—parent and teacher.","cn":"我今晚身兼两职，既是家长又是老师。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（常指带檐的）帽子","en":"A hat is a head covering, often with a brim round it, which is usually worn out of doors to give protection from the weather."},{"pos":"N-COUNT 可数名词","cn":"角色;职位;工作","en":"If you say that someone is wearing a particular hat, you mean that they are performing a particular role at that time. If you say that they wear several hats, you mean that they have several roles or jobs.","ex":{"en":"...putting on my nationalistic hat.","cn":"扮演我的民族主义角色"}},{"pos":"PHRASE 短语","cn":"毫不犹豫地;非常乐意地","en":"If you say that you are ready to do something at the drop of a hat, you mean that you are willing to do it immediately, without hesitating.","ex":{"en":"India is one part of the world I would go to at the drop of a hat.","cn":"印度是世界上我迫不及待想要去的一个地方。"}},{"pos":"PHRASE 短语","cn":"保守秘密","en":"If you tell someone to keep a piece of information under their hat, you are asking them not to tell anyone else about it.","ex":{"en":"Look, if I tell you something, will you promise to keep it under your hat?","cn":"喂，如果我告诉你一件事，你能答应保守秘密吗？"}},{"pos":"PHRASE 短语","cn":"陈腐;陈旧;老式;过时","en":"If you say that something or someone is old hat, you mean that they have existed or been known for a long time, and they have become uninteresting and boring.","ex":{"en":"The younger generation tell me that religion is 'old hat' and science has proved this.","cn":"年轻的一代告诉我，宗教已经过时了，科学已证明了这一点。"}},{"pos":"PHRASE 短语","cn":"募捐，凑份子（美国英语用 pass the hat）","en":"In British English, if you pass the hat around, you collect money from a group of people, for example in order to give someone a present. In American English, you just say pass the hat .","ex":{"en":"Professors are passing the hat to help staff in their department.","cn":"教授们正在凑钱帮助系里的同事。"}},{"pos":"PHRASE 短语","cn":"赞赏;钦佩","en":"If you say that you take your hat off to someone, you mean that you admire them for something that they have done.","ex":{"en":"I take my hat off to Mr Clarke for taking this action","cn":"我很钦佩克拉克先生的这一举动。"}},{"pos":"CONVENTION 惯用语","cn":"向…致敬","en":"If you say 'Hats off to someone', you are expressing admiration for them.","ex":{"en":"Hats off to them for supporting the homeless.","cn":"向他们帮扶无家可归者的善举致敬！"}},{"pos":"PHRASE 短语","cn":"（常指没落时）出乎意料地获取（胜利、成功）","en":"To pull something out of the hat means to do something unexpected which helps you to succeed, often when you are failing.","ex":{"en":"Southampton had somehow managed to pull another Cup victory out of the hat.","cn":"南安普敦队最终还是出乎意料地又一次获得了足总杯赛的胜利。"}},{"pos":"PHRASE 短语","cn":"（比赛中挑选胜出者时）随机地，任意地","en":"In competitions, if you say that the winners will be drawn or picked out of the hat, you mean that they will be chosen randomly, so everyone has an equal chance of winning.","ex":{"en":"The first 10 correct entries drawn out of the hat will win a pair of tickets, worth £20 each.","cn":"随机抽出的前10位答对问题者将获得两张票，每张价值20英镑。"}},{"pos":"","cn":"","en":"to knock something into a cocked hat→see: ;"}]},"examples":[{"en":"I'm telling you this with my lawyer's hat on, you understand.","cn":"你要明白，我是以律师的身分告诉你这事。"},{"en":"I'm wearing two hats tonight — parent and teacher.","cn":"我今晚身兼两职，既是家长又是老师。"}]},"handled":{"lemma":"handle"},"her":{"media":{"uk":"media/uk/her__gb_1.mp3","us":"media/us/her__us_1.mp3"},"oxford":{"phon":"hə(r)","pos":"pronoun","senses":[{"en":"used as the object of a verb, after the verb be or after a preposition to refer to a woman or girl who has already been mentioned or is easily identified","cn":"（用作动词或介词的宾语，或作表语）她","lab":"British English","ex":{"en":"We're going to call her Sophie.","cn":"我们将给她起名索菲。"}},{"en":"of or belonging to a woman or girl who has already been mentioned or is easily identified","cn":"她的","ex":{"en":"Meg loves her job.","cn":"梅格热爱她的工作。"},"pos":"determiner"}]},"collins":{"senses":[{"pos":"PRON-SING 单数型代词","cn":"她;（雌性动物）它","en":"You use her to refer to a woman, girl, or female animal.","ex":{"en":"I went in the room and told her I had something to say to her","cn":"我走进房间，告诉她我有话要和她说。"}},{"pos":"PRON-SING 单数型代词","cn":"（书面英语中不区分性别地泛指人）他或她（一些人不喜欢这种用法，更倾向于使用 him or her 或 them）","en":"In written English, her is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'him or her' or 'them'.","ex":{"en":"Talk to your baby, play games, and show her how much you enjoy her company.","cn":"和你的宝宝说话，做游戏，让他（她）知道你很喜欢和他（她）在一起。"}},{"pos":"PRON-SING 单数型代词","cn":"（有时指国家或民族）她，它","en":"Her is sometimes used to refer to a country or nation.","ex":{"en":"Our reporter looks at reactions to Britain's apparently deep-rooted distrust of her EU partner.","cn":"英国对其欧盟伙伴显然存在着根深蒂固的不信任，我们的记者就人们对此的反应进行了报道。"}},{"pos":"PRON-SING 单数型代词","cn":"（有时指汽车、机器或船）它","en":"People sometimes use her to refer to a car, machine, or ship.","ex":{"en":"Kemp got out of his car. 'Just fill her up, thanks.'","cn":"肯普下了车。“给它加满油，谢谢。”"}}]},"examples":[{"en":"The manager will be free soon — you can wait for her here.","cn":"经理很快就有空了，你可以在这里等她。"},{"en":"We're going to call her Sophie.","cn":"我们将给她起名索菲。"}]},"horizontal":{"oxford":{"phon":"ˌhɒrɪˈzɒntl","pos":"adjective","senses":[{"en":"flat and level; going across and parallel to the ground rather than going up and down","cn":"水平的；与地面平行的；横的","lab":"informal","ex":{"en":"horizontal lines","cn":"横线"}},{"en":"a horizontal position","cn":"水平位置","g":"[uncountable]","ex":{"en":"He shifted his position from the horizontal.","cn":"他从水平姿势变换成其他姿势。"},"pos":"noun"},{"en":"a horizontal line or surface","cn":"水平线；水平面；横线；横切面","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"水平的;横的","en":"Something that is horizontal is flat and level with the ground, rather than at an angle to it.","ex":{"en":"The board consists of vertical and horizontal lines","cn":"板上画着横纵的线条。"}},{"pos":"N-COUNT 可数名词","cn":"水平线;横线;水平结构","en":"A horizontal is a line or structure that is horizontal.","ex":{"en":"The undulating planes of the countryside provide relief from the hard horizontals and verticals of the urban scene.","cn":"乡村起伏不平的地势使人们摆脱了城市刻板的横平竖直景象。"}}]},"media":{"uk":"media/uk/horizontal__gb_1.mp3","us":"media/us/horizontal__us_1.mp3"},"examples":[{"en":"Cut the cake in half horizontally and spread jam on one half.","cn":"把蛋糕横切成两半，把果酱涂在半面上。"},{"en":"He shifted his position from the horizontal.","cn":"他从水平姿势变换成其他姿势。"}]},"harem":{"media":{"uk":"media/uk/harem__gb_1.mp3","us":"media/us/harem__us_1.mp3"},"oxford":{"phon":"ˈhɑːriːm","pos":"noun","senses":[{"en":"the women or wives belonging to a rich man, especially in some Muslim societies in the past","cn":"哈来姆（尤指旧时某些穆斯林社会中富人的女眷）"},{"en":"the separate part of a traditional Muslim house where the women live","cn":"（穆斯林传统女眷居住的）内室，妇女住房"},{"en":"a group of female animals that share the same male for producing young","cn":"眷群（和同一雄性动物交配的一群雌性动物）","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指伊斯兰教徒的）妻妾，女眷","en":"If a man, especially a Muslim, has several wives or sexual partners living in his house, they can be referred to as his harem."},{"pos":"N-COUNT 可数名词","cn":"（妻妾居住的）闺房，内室","en":"A harem is a part of a building where a harem lives."}]}},"held":{"lemma":"hold","media":{"uk":"media/uk/held__gb_1.mp3","us":"media/us/held__us_1.mp3"}},"homeworkers":{"lemma":"homeworker"},"heading":{"media":{"uk":"media/uk/heading__gb_1.mp3","us":"media/us/heading__us_1.mp3"},"oxford":{"phon":"ˈhedɪŋ","pos":"noun","senses":[{"en":"a title printed at the top of a page or at the beginning of a section of a book","cn":"（页首或章节开头的）标题","ex":{"en":"chapter headings","cn":"篇章标题"}},{"en":"the subject of each section of a speech or piece of writing","cn":"（讲话或作品各章节的）主题","ex":{"en":"The company's aims can be grouped under three main headings.","cn":"公司的目标可分成三大类。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"标题;题目","en":"A heading is the title of a piece of writing, which is written or printed at the top of the page.","ex":{"en":"...helpful chapter headings.","cn":"有用的章节标题"}}]},"examples":[{"en":"The company's aims can be grouped under three main headings.","cn":"公司的目标可分成三大类。"},{"en":"chapter headings","cn":"篇章标题"}],"base":"head"},"hurried":{"media":{"uk":"media/uk/hurried__gb_1.mp3","us":"media/us/hurried__us_1.mp3"},"oxford":{"phon":"ˈhʌrid","pos":"adjective","senses":[{"en":"done too quickly because you do not have enough time","cn":"匆忙完成的；仓促而就的","ex":{"en":"I ate a hurried breakfast and left.","cn":"我匆匆忙忙吃完早饭就离开了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行动）匆忙的，迅速的","en":"A hurried action is done quickly, because you do not have much time to do it in.","ex":{"en":"...a hurried breakfast.","cn":"匆忙塞了几口的早餐"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行动）仓促的，突然的，急于应对的","en":"A hurried action is done suddenly, in reaction to something that has just happened.","ex":{"en":"Downing Street denied there had been a hurried overnight redrafting of the text.","cn":"唐宁街否认连夜赶工改拟了文本。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）做事匆忙的，行动仓促的","en":"Someone who is hurried does things more quickly than they should because they do not have much time to do them.","ex":{"en":"Parisians on the street often looked worried, hurried and unfriendly.","cn":"巴黎街上的路人往往看上去忧心忡忡、匆匆忙忙而且不太友善。"}}]},"examples":[{"en":"I ate a hurried breakfast and left.","cn":"我匆匆忙忙吃完早饭就离开了。"},{"en":"I hurriedly got up and dressed.","cn":"我急忙起床穿好衣服。"}],"base":"hurry"},"honour":{"media":{"uk":"media/uk/honour__gb_1.mp3","us":"media/us/honour__us_1.mp3"},"oxford":{"phon":"ˈɒnə(r)","pos":"noun","senses":[{"en":"great respect for somebody","cn":"尊敬；尊重；崇敬","g":"[uncountable]","sc":"respect","ex":{"en":"the guest of honour (= the most important one)","cn":"贵宾"}},{"en":"something that you are very pleased or proud to do because people are showing you great respect","cn":"荣幸；光荣","g":"[singular]","sc":"privilege","ex":{"en":"It was a great honour to be invited here today.","cn":"今天承蒙邀请到此，深感荣幸。"}},{"en":"the quality of knowing and doing what is morally right","cn":"正义感；道义；节操","g":"[uncountable]","sc":"moral behaviour","ex":{"en":"a man of honour","cn":"品德高尚的人"}},{"en":"a good reputation; respect from other people","cn":"荣誉；名誉；他人的尊敬","g":"[uncountable]","sc":"reputation","ex":{"en":"upholding the honour of your country","cn":"捍卫祖国的荣誉"}},{"en":"a person or thing that causes others to respect and admire something/somebody","cn":"引起尊敬（或尊重、崇敬）的人（或事物）","g":"[singular]","sc":"reputation","ex":{"en":"She is an honour to the profession.","cn":"她是这一行业的光荣。"}},{"en":"an award, official title, etc. given to somebody as a reward for something that they have done","cn":"（为表扬某人的）奖励，荣誉称号，头衔","g":"[countable]","sc":"award","ex":{"en":"the New Year’s Honours list (= in Britain, a list of awards and titles given on January 1 each year)","cn":"（英国）元旦受勋者名册"}},{"en":"a university course that is of a higher level than a basic course (in the US also used to describe a class in school that is at a higher level than other classes)","cn":"大学荣誉学位课程；（美国学校的）优等班","g":"[plural]","lab":"North American English","sc":"at university/school","ex":{"en":"an honours degree/course","cn":"荣誉学位／课程"}},{"en":"if you pass an exam or graduate from a university or school with honours, you receive a special grade for having achieved a very high standard","cn":"优异成绩","g":"[plural]","sc":"at university/school","ex":{"en":"He passed with second-class honours.","cn":"他以二级优等成绩通过了考试。"}},{"en":"a title of respect used when talking to or about a judge or a US mayor","cn":"法官大人；（美国）市长阁下","g":"[countable]","sc":"judge/mayor","ex":{"en":"No more questions, Your Honour.","cn":"没有其他问题了，法官大人。"}},{"en":"the cards that have the highest value","cn":"最大点数的牌","g":"[countable, usually plural]","sc":"in card games"},{"en":"to do something that shows great respect for somebody/something","cn":"尊敬，尊重（某人）","lab":"ironic","sc":"show respect","ex":{"en":"our honoured guests","cn":"我们的贵宾"},"pos":"verb"},{"en":"to give public praise, an award or a title to somebody for something they have done","cn":"给予表扬（或奖励、头衔、称号）","g":"[often passive]","sc":"give award","ex":{"en":"She has never been properly honoured in her own country.","cn":"她在自己的国家从未受到过适当的荣誉。"},"pos":"verb"},{"en":"to do what you have agreed or promised to do","cn":"信守，执行（承诺）","lab":"formal","sc":"keep promise","ex":{"en":"I have every intention of honouring our contract.","cn":"我完全愿意执行我们的合约。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"正义感;道义;气节","en":"Honour means doing what you believe to be right and being confident that you have done what is right.","ex":{"en":"The officers died faithful to Poland and to the honour of a soldier","cn":"这些军官至死都忠于波兰，坚守了军人气节。"}},{"pos":"N-COUNT 可数名词","cn":"荣誉;特殊奖励","en":"An honour is a special award that is given to someone, usually because they have done something good or because they are greatly respected.","ex":{"en":"Most of the high honours usually go to long-serving MPs loyal to the government","cn":"大多数的高级荣誉通常都会授予忠于政府的资深议员。"}},{"pos":"VERB 动词","cn":"授予…荣誉;给予…表彰","en":"If someone is honoured, they are given public praise or an award for something they have done.","ex":{"en":"Two American surgeons were last week honoured with the Nobel Prize for Medicine and Physiology","cn":"两位美国外科医生上周获得了诺贝尔医学和生理学奖。"}},{"pos":"N-SING 单数名词","cn":"荣幸;光荣;殊荣","en":"If you describe doing or experiencing something as an honour, you mean you think it is something special and desirable.","ex":{"en":"Five other cities had been competing for the honour of staging the Games","cn":"还有其他5个城市为赢得该届运动会的主办权一直在进行角逐。"}},{"pos":"V-PASSIVE 被动动词","cn":"使感到荣幸;使引以为荣","en":"If you say that you would be honoured to do something, you are saying very politely and formally that you would be pleased to do it. If you say that you are honoured by something, you are saying that you are grateful for it and pleased about it.","ex":{"en":"Peter Alliss says he would be honoured to be asked","cn":"彼得·艾利斯说若受邀约自己将感到非常荣幸。"}},{"pos":"VERB 动词","cn":"尊重;尊敬","en":"To honour someone means to treat them or regard them with special attention and respect.","ex":{"en":"Her Majesty later honoured the Headmaster with her presence at lunch","cn":"女王陛下随后出席了午宴，以表示对校长的尊重。"}},{"pos":"VERB 动词","cn":"执行（协议）;履行（诺言）","en":"If you honour an arrangement or promise, you do what you said you would do.","ex":{"en":"The two sides agreed to honour a new ceasefire","cn":"双方同意执行新的停火协议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（大学）优等学位，荣誉学位","en":"Honours is a type of university degree which is of a higher standard than a pass or ordinary degree.","ex":{"en":"...an honours degree in business studies.","cn":"商学荣誉学位"}},{"pos":"N-VOC 称呼名词","cn":"（美国对法官、市长等的尊称）阁下，大人（当面称呼时用 your honour，其他场合提及时用 his honour 或 her honour）","en":"Judges, and mayors in the United States, are sometimes called your honour or referred to as his honour or her honour .","ex":{"en":"I bring this up, your honor, because I think it is important to understand the background of the defendant.","cn":"法官大人，我之所以提及此事，是因为我觉得了解被告的背景十分重要。"}},{"pos":"PHRASE 短语","cn":"尽主人之谊;主持","en":"If someone does the honours at a social occasion or public event, they act as host or perform some official function.","ex":{"en":"A well-known television personality did the honours at the official opening of the show.","cn":"一位著名的电视明星主持了该次展览的正式开幕典礼。"}},{"pos":"PREP-PHRASE 短语介词","cn":"为庆祝…","en":"If something is arranged in honour of a particular event, it is arranged in order to celebrate that event.","ex":{"en":"The Foundation is holding a dinner at the Museum of American Art in honour of the opening of their new show.","cn":"该基金会将在美国艺术博物馆举办宴会，庆祝新展览的开幕。"}},{"pos":"PHRASE 短语","cn":"为了向…表示敬意","en":"If something is arranged or happens in someone's honour, it is done specially to show appreciation of them.","ex":{"en":"He will attend an outdoor concert in his honour in the centre of Paris","cn":"他将出席在巴黎市中心特地为他举办的一场露天音乐会。"}}]},"examples":[{"en":"Proving his innocence has become a matter of honour.","cn":"证实他的清白已经成了一件道义上的事。"},{"en":"You're on your honour not to go into my room.","cn":"依你的人格，相信你不会进我的房间。"}]},"handbook":{"oxford":{"phon":"ˈhændbʊk","pos":"noun","senses":[{"en":"a book giving instructions on how to use something or information about a particular subject","cn":"手册；指南","ex":{"en":"A study skills handbook sets out to train the students in all these areas.","cn":"学习技能手册旨在对学生进行所有这些领域的培训。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手册;说明书","en":"A handbook is a book that gives you advice and instructions about a particular subject, tool, or machine.","ex":{"en":"If you have not kept a pet parrot before, it would be wise to purchase a handbook on the subject.","cn":"如果以前没有养过鹦鹉，最好买一本相关的饲养手册。"}}]},"media":{"uk":"media/uk/handbook__gb_1.mp3","us":"media/us/handbook__us_1.mp3"},"examples":[{"en":"the Fiction Writer’s Handbook 《","cn":"小说写作手册》"}]},"he":{"media":{"uk":"media/uk/he__gb_1.mp3","us":"media/us/he__us_1.mp3"},"oxford":{"phon":"hi","pos":"pronoun","senses":[{"en":"a male person or animal that has already been mentioned or is easily identified","cn":"他；它（指雄性动物）","ex":{"en":"Everyone liked my father—he was the perfect gentleman.","cn":"大家都喜欢我父亲，他是真正的绅士。"}},{"en":"a person, male or female, whose sex is not stated or known, especially when referring to somebody mentioned earlier or to a group in general","cn":"人（指性别未说明或不知道的男性或女性，尤指曾提过的人或泛指某群体）","lab":"old-fashioned","ex":{"en":"Every child needs to know that he is loved.","cn":"每个孩子都需要知道自己是有人爱的。"}},{"en":"used when referring to God","cn":"（指上帝）"},{"en":"a male","cn":"雄性","g":"[singular]","lab":"informal","ex":{"en":"What a nice dog—is it a he or a she?","cn":"多好看的狗，它是公的还是母的？"},"pos":"noun"},{"en":"a male animal","cn":"雄性动物","ex":{"en":"a he-goat","cn":"一头公山羊"},"pos":"noun"},{"en":"Her/His Excellency","cn":"阁下","ex":{"en":"HE the Australian Ambassador","cn":"澳大利亚大使阁下"},"pos":"abbreviation"},{"en":"higher education","cn":"高等教育","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"PRON-SING 单数型代词","cn":"他;它（指雄性动物）","en":"You use he to refer to a man, boy, or male animal.","ex":{"en":"He could never quite remember all our names","cn":"他永远也无法记住我们所有人的名字。"}},{"pos":"PRON-SING 单数型代词","cn":"（书面英语中泛指人）他，她（有些人不喜欢这种用法，更倾向于使用 he or she 或 they）","en":"In written English, he is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'he or she' or 'they'.","ex":{"en":"The teacher should encourage the child to proceed as far as he can, and when he is stuck, ask for help.","cn":"老师应该鼓励孩子尽量自己去做，遇到困难时，寻求帮助。"}},{"pos":"PRON-SING 单数型代词","cn":"(某些宗教中）上帝","en":"In some religions, He is used to refer to God."}]},"examples":[{"en":"HE the Australian Ambassador","cn":"澳大利亚大使阁下"},{"en":"‘Where’s Paul?’ ‘He’s gone to the cinema.’ “","cn":"保罗在哪儿？”“他去看电影了。”"}]},"hospital":{"media":{"uk":"media/uk/hospital__gb_1.mp3","us":"media/us/hospital__us_1.mp3"},"oxford":{"phon":"ˈhɒspɪtl","pos":"noun","senses":[{"en":"a large building where people who are ill or injured are given medical treatment and care","cn":"医院","lab":"British English","ex":{"en":"He had to go to/into hospital for treatment.","cn":"他得到医院接受治疗。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"医院","en":"A hospital is a place where people who are ill are looked after by nurses and doctors.","ex":{"en":"...a children's hospital with 120 beds","cn":"拥有120张病床的儿童医院"}}]},"examples":[{"en":"The injured were rushed to (the) hospital in an ambulance.","cn":"救护车把伤员火速送往医院。"},{"en":"I'm going to the hospital to visit my brother.","cn":"我要去医院探望我弟弟。"}]},"how":{"media":{"uk":"media/uk/how__gb_1.mp3","us":"media/us/how__us_1.mp3"},"oxford":{"phon":"haʊ","pos":"adverb","senses":[{"en":"in what way or manner","cn":"怎样；如何","ex":{"en":"How does it work?","cn":"它是如何运作的？"}},{"en":"used to ask about somebody’s health or how well things are going for them","cn":"（询问某人健康状况或近况）","lab":"informal","ex":{"en":"How are you?","cn":"你（身体）好吗？"}},{"en":"used to ask whether something is successful or fun","cn":"（询问是否顺利或愉快）","ex":{"en":"How was your trip?","cn":"你旅行愉快吗？"}},{"en":"used before an adjective or adverb to ask about the amount, degree, etc. of something, or about somebody’s age","cn":"（后接形容词或副词）多少，多么，多大","ex":{"en":"How often do you go swimming?","cn":"你多久去游一次泳？"}},{"en":"used to express surprise, pleasure, etc.","cn":"（表示惊奇、高兴等）","ex":{"en":"How kind of you to help!","cn":"你来帮忙，真是太好了！"}},{"en":"in any way in which","cn":"以任何方式；无论用什么方法","ex":{"en":"I'll dress how I like in my own house!","cn":"我在自己家里爱怎么穿就怎么穿！"}}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"（用于询问方式、方法）怎样，怎么，如何","en":"You use how to ask about the way in which something happens or is done.","ex":{"en":"How do I make payments into my account?","cn":"我如何向自己的账户付款？"}},{"pos":"CONJ-SUBORD 连词","cn":"（用于某些形容词和动词后引出陈述或事实，常指记起之事或希望他人了解之事）","en":"You use how after certain adjectives and verbs to introduce a statement or fact, often something that you remember or expect other people to know about.","ex":{"en":"It's amazing how people collect so much stuff over the years","cn":"人们竟然日积月累地收集了这么多东西，真令人惊叹。"}},{"pos":"QUEST 疑问词","cn":"（用于询问数量、程度）多少，多么","en":"You use how to ask questions about the quantity or degree of something.","ex":{"en":"How much money are we talking about?","cn":"总共是多少钱？"}},{"pos":"QUEST 疑问词","cn":"（用于询问是否成功或愉快）怎么样，如何","en":"You use how when you are asking someone whether something was successful or enjoyable.","ex":{"en":"How was your trip down to Orlando?","cn":"你的奥兰多之行怎么样？"}},{"pos":"QUEST 疑问词","cn":"（用于询问某人的健康或打探有关某人的消息）怎么样，如何","en":"You use how to ask about someone's health or to find out someone's news.","ex":{"en":"Hi! How are you doing?","cn":"嗨！你近来怎么样？"}},{"pos":"CONVENTION 惯用语","cn":"你好（用于初次见面打招呼）","en":"'How do you do' is a polite way of greeting someone when you meet them for the first time.","ex":{"en":"'How do you do, Mrs Bellingham,' Sam said.","cn":"“你好，贝林厄姆夫人，”萨姆说。"}},{"pos":"CONJ-SUBORD 连词","cn":"不管如何;无论怎样","en":"You use how when you want to say that it does not matter which way something is done.","ex":{"en":"Two historical questions — you can answer them how you like","cn":"两个历史问题——你可以随便回答。"}},{"pos":"ADV 副词","cn":"（强调程度）多么，何等，如此","en":"You use how to emphasize the degree to which something is true.","ex":{"en":"I didn't realize how heavy that shopping was going to be","cn":"我没想到买的东西会有多沉。"}},{"pos":"ADV 副词","cn":"（用于感叹句中强调形容词、副词或陈述内容）多么，何等，如此","en":"You use how in exclamations to emphasize an adjective, adverb, or statement.","ex":{"en":"How strange that something so simple as a walk on the beach could suddenly mean so much","cn":"诸如在沙滩散步这样的小事会突然变得如此重要，真是令人感到不可思议。"}},{"pos":"QUEST 疑问词","cn":"（表示不赞成或难以相信）你怎么能，你怎么会","en":"You use how in expressions such as 'How can you...' and 'How could you...' to indicate that you disapprove of what someone has done or that you find it hard to believe.","ex":{"en":"How can you drink so much beer, Luke?","cn":"你怎么能喝这么多啤酒呢，卢克？"}},{"pos":"QUEST 疑问词","cn":"（用于提出建议或邀请）怎么样好吗","en":"You use how in expressions such as 'how about...' or 'how would you like...' when you are making an offer or a suggestion.","ex":{"en":"How about a cup of coffee?","cn":"来杯咖啡怎么样？"}},{"pos":"CONVENTION 惯用语","cn":"（用于询问对方的想法或要求）你呢，你觉得呢","en":"If you ask someone 'How about you?' you are asking them what they think or want.","ex":{"en":"Well, I enjoyed that. How about you two?","cn":"嗯，我觉得那很棒。你们俩呢？"}},{"pos":"CONVENTION 惯用语","cn":"（用于引起他人对刚说过的话或发生的事的注意）神吧，奇妙吧，你信吗？","en":"If you say 'How about that?' you are drawing attention to something that has been said or done that you think is surprising.","ex":{"en":"The twins made their appearance at three o'clock. How about that? Spot on time.","cn":"双胞胎在3点时出现了。神吧？绝对准时。"}},{"pos":"PHRASE 短语","cn":"（用于引出相关的新话题）怎么样，如何","en":"You use how about to introduce a new subject which you think is relevant to the conversation you have been having.","ex":{"en":"Are your products and services competitive? How about marketing?","cn":"你们的产品和服务有竞争力吗？营销又怎么样呢？"}},{"pos":"PHRASE 短语","cn":"（用于因为惊讶而询问）怎么会这样呢，为什么","en":"You ask 'How come?' or 'How so?' when you are surprised by something and are asking why it happened or was said.","ex":{"en":"'They don't say a single word to each other.'—'How come?'","cn":"“他们相互之间一句话都不说。”——“怎么会这样呢？”"}},{"pos":"PHRASE 短语","cn":"你是什么意思;你到底想说什么","en":"If you say 'How do you mean?' to someone, you are asking them to explain or give more details of what they have just said.","ex":{"en":"'The fuel gauge is broken.' — 'Broken? How do you mean?'","cn":"“燃油表坏了。”——“坏了？你说清楚点？”"}},{"pos":"PHRASE 短语","cn":"（用于询问是否可接受或满意）怎么样，行吗","en":"If you say 'How's that?' to someone, you are asking whether something is acceptable or satisfactory.","ex":{"en":"Suppose we meet somewhere for a drink? I'll pay. How's that?","cn":"我们找个地方一起喝一杯吧？我请客。怎么样？"}}]},"examples":[{"en":"I'll tuck your sheets in for you. How's that? Comfortable?","cn":"我给你把被单掖在垫褥下面吧。怎么样？舒服吗？"},{"en":"Ben! How could you? After all they've done for us!","cn":"本！他们为我们做了这么多，你怎么能这样！"}]},"harmonious":{"media":{"uk":"media/uk/harmonious__gb_1.mp3","us":"media/us/harmonious__us_1.mp3"},"oxford":{"phon":"hɑːˈməʊniəs","pos":"adjective","senses":[{"en":"friendly, peaceful and without any arguments","cn":"友好和睦的；和谐的","ex":{"en":"a harmonious alliance between management and workers","cn":"管理层与工人的和谐联盟"}},{"en":"arranged together in a way that is pleasant because each part goes well with the others","cn":"协调的；和谐的","ex":{"en":"a harmonious combination of colours","cn":"协调的色彩搭配"}},{"en":"very pleasant when played or sung together","cn":"和谐的；谐调的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（关系、协定、讨论）融洽的，和睦的，友好的","en":"A harmonious relationship, agreement, or discussion is friendly and peaceful.","ex":{"en":"Their harmonious relationship resulted in part from their similar goals","cn":"他们关系融洽的部分原因是他们有着相似的目标。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（各组成部分）和谐的，协调的","en":"Something that is harmonious has parts which go well together and which are in proportion to each other.","ex":{"en":"The architecture is harmonious and no building is over five or six floors high.","cn":"这里的建筑风格和谐统一，没有哪座楼房高于五六层。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（音调）和谐的，悦耳的","en":"Musical notes that are harmonious produce a pleasant sound when played together.","ex":{"en":"...the mysterious skill involved in producing harmonious sounds.","cn":"发出悦耳声音的神秘技巧"}}]},"examples":[{"en":"They worked very harmoniously together.","cn":"他们合作得十分融洽。"},{"en":"a harmonious combination of colours","cn":"协调的色彩搭配"}]},"hollow":{"media":{"uk":"media/uk/hollow__gb_1.mp3","us":"media/us/hollow__us_1.mp3"},"oxford":{"phon":"ˈhɒləʊ","pos":"adjective","senses":[{"en":"having a hole or empty space inside","cn":"中空的；空心的","ex":{"en":"a hollow ball/centre/tube/tree","cn":"中空的球／中心部位／管子／树"}},{"en":"sinking deeply into the face","cn":"凹陷的","ex":{"en":"hollow eyes/cheeks","cn":"凹陷的双眼／双颊"}},{"en":"making a low sound like that made by an empty object when it is hit","cn":"沉闷回荡的；空响的","g":"[usually before noun]","ex":{"en":"a hollow groan","cn":"低沉的呻吟"}},{"en":"not sincere","cn":"无诚意的；虚伪的","g":"[usually before noun]","ex":{"en":"I've had enough of their hollow promises.","cn":"我已经受够了他们的空头支票。"}},{"en":"without real value","cn":"无真正价值的","g":"[usually before noun]","ex":{"en":"He won something of a hollow victory when his opponent was forced to withdraw with a serious injury.","cn":"当他的对手因重伤被迫退出时，他赢得了一场空洞的胜利。"}},{"en":"an area that is lower than the surface around it, especially on the ground","cn":"凹陷处；坑洼处","ex":{"en":"All but one of the ponds are empty, their sites marked only by muddy hollows.","cn":"除了其中一个池塘外，所有池塘都是空的，只有泥泞的洼地。"},"pos":"noun"},{"en":"a hole or an empty space inside something","cn":"洞；坑","ex":{"en":"The squirrel disappeared into a hollow at the base of the tree.","cn":"松鼠钻进了树根处的一个洞。"},"pos":"noun"},{"en":"to make a flat surface go inward in a curve","cn":"使凹陷；使塌陷","ex":{"en":"The stairs have been hollowed by centuries of use.","cn":"历经几个世纪的使用，楼梯都塌陷下去了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"空的;空心的;中空的","en":"Something that is hollow has a space inside it, as opposed to being solid all the way through.","ex":{"en":"...a hollow tree.","cn":"空心的树"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"凹的;凹陷的","en":"A surface that is hollow curves inwards.","ex":{"en":"He looked young, dark and sharp-featured, with hollow cheeks.","cn":"他看起来很年轻，肤色黝黑，五官分明，双颊凹陷。"}},{"pos":"N-COUNT 可数名词","cn":"树洞","en":"A hollow is a hole inside a tree.","ex":{"en":"I made my home there, in the hollow of a dying elm.","cn":"我在一棵快要枯死的榆树的树洞里安了家。"}},{"pos":"N-COUNT 可数名词","cn":"凹陷处;低洼地","en":"A hollow is an area that is lower than the surrounding surface.","ex":{"en":"Below him the town lay warm in the hollow of the hill.","cn":"在他下方，小镇卧在温暖的山谷里。"}},{"pos":"ADJ 形容词","cn":"空洞的;无用的;无价值的","en":"If you describe a statement, situation, or person as hollow, you mean they have no real value, worth, or effectiveness.","ex":{"en":"Any threat to bring in the police is a hollow one.","cn":"任何威胁说要叫警察来的话都是虚声恫吓。"}},{"pos":"ADJ 形容词","cn":"（笑声等）虚伪的，不真诚的","en":"If someone gives a hollow laugh, they laugh in a way that shows that they do not really find something amusing.","ex":{"en":"Murray Pick's hollow laugh had no mirth in it.","cn":"默里·皮克的干笑里没有一点快乐。"}},{"pos":"ADJ 形容词","cn":"（声音）空洞的，沉闷回荡的","en":"A hollow sound is dull and echoing.","ex":{"en":"...the hollow sound of a gunshot.","cn":"空洞的枪响"}},{"pos":"VERB 动词","cn":"使凹陷;使下陷","en":"If something is hollowed, its surface is made to curve inwards or downwards.","ex":{"en":"The mule's back was hollowed by the weight of its burden.","cn":"骡背被重负压得塌下了。"}},{"pos":"","cn":"","en":"相关词组：hollow out"}]},"examples":[{"en":"Their appeals for an end to the violence had a hollow ring.","cn":"他们要求停止使用暴力的呼吁并不真切。"},{"en":"The village lay secluded in a hollow of the hills (= a small valley).","cn":"村子坐落在一个幽静的小山谷中。"}]},"hurts":{"lemma":"hurt"},"helper":{"media":{"uk":"media/uk/helper__gb_1.mp3","us":"media/us/helper__us_1.mp3"},"oxford":{"phon":"ˈhelpə(r)","pos":"noun","senses":[{"en":"a person who helps somebody to do something","cn":"帮手；助手","ex":{"en":"He recruited a band of willing helpers.","cn":"他动员了一批自愿帮忙的人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"帮助者;帮手;助手","en":"A helper is a person who helps another person or group with a job they are doing."}]},"examples":[{"en":"a willing helper","cn":"自愿帮忙者"},{"en":"I was a classroom helper at the local primary school.","cn":"我是当地小学的课室助理。"}]},"hardy":{"media":{"uk":"media/uk/hardy__gb_1.mp3","us":"media/us/hardy__us_1.mp3"},"oxford":{"phon":"ˈhɑːdi","pos":"adjective","senses":[{"en":"strong and able to survive difficult conditions and bad weather","cn":"能吃苦耐劳的；适应力强的","ex":{"en":"a hardy breed of sheep","cn":"适应力强的绵羊品种"}},{"en":"that can live outside through the winter","cn":"耐寒的；能越冬的","ex":{"en":"a hardy annual/perennial","cn":"耐寒的一年生/多年生植物"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（植物）耐寒的","en":"Plants that are hardy are able to survive cold weather.","ex":{"en":"The silver-leaved varieties of cyclamen are not quite as hardy.","cn":"银叶仙客来品种不太耐寒。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人或动物）强壮的，适应力强的","en":"People and animals that are hardy are strong and able to cope with difficult conditions.","ex":{"en":"It should not surprise us that such an environment has produced a hardy and independent people","cn":"这样的环境造就了一个吃苦耐劳、独立自主的民族，对此我们不应该感到意外。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚定不移的;非常忠诚的;顽强的","en":"If you describe a group of people as hardy, you mean that they have been very patient or loyal, or have been trying hard to do something in difficult conditions.","ex":{"en":"...the ten hardy supporters who had made the trek to Dublin from Riga.","cn":"从里加长途跋涉到都柏林的10名铁杆支持者"}}]},"examples":[{"en":"a hardy breed of sheep","cn":"适应力强的绵羊品种"},{"en":"hardy mountain goats","cn":"能适应恶劣环境的石山羊"}]},"hostel":{"oxford":{"phon":"ˈhɒstl","pos":"noun","senses":[{"en":"a building that provides cheap accommodation and sometimes meals to students, workers or travellers","cn":"宿舍，招待所（提供廉价住宿，有时还提供餐食）","ex":{"en":"We stayed at a student hostel during the conference.","cn":"会议期间我们住在一处学生公寓里。"}},{"en":"a building, usually run by a charity, where people who have no home can stay for a short time","cn":"临时收容所；慈善收容所","lab":"British English","ex":{"en":"He lives in a hostel for homeless people.","cn":"他住在一家为无家可归者提供的旅馆里。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常由当地政府或慈善团体开办的）廉价招待所，临时收容所","en":"A hostel is a large house where people can stay cheaply for a short period of time. Hostels are usually owned by local government authorities or charities."}]},"media":{"uk":"media/uk/hostel__gb_1.mp3","us":"media/us/hostel__us_1.mp3"},"examples":[{"en":"a hostel for the homeless","cn":"流浪者之家"}]},"halfpennies":{"lemma":"halfpenny","media":{"uk":"media/uk/halfpenny__gb_1.mp3","us":"media/us/halfpenny__us_1.mp3"}},"heating":{"oxford":{"phon":"ˈhiːtɪŋ","pos":"noun","senses":[{"en":"the process of supplying heat to a room or building; a system used to do this","cn":"供暖；供暖系统；暖气设备","ex":{"en":"to put/turn the heating on","cn":"打开供暖设备"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指从经济角度考虑的）供暖，暖气供应","en":"Heating is the process of heating a building or room, considered especially from the point of view of how much this costs.","ex":{"en":"You can still find cottages for £150 a week, including heating.","cn":"你仍可以找到包括供暖在内每周租金150英镑的度假别墅。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（建筑物的）供暖系统，暖气设备","en":"Heating is the system and equipment that is used to heat a building.","ex":{"en":"There is no heating in the shed, so the dogs would be bitterly cold at night","cn":"小屋里没有供暖设备，所以这些狗夜里会非常冷。"}}]},"media":{"uk":"media/uk/heating__gb_1.mp3","us":"media/us/heating__us_1.mp3"},"examples":[{"en":"Who turned the heating off?","cn":"谁把暖气关掉了？"},{"en":"What type of heating do you have?","cn":"你们用什么供暖？"}],"base":"heat"},"hooves":{"lemma":"hoof","media":{"uk":"media/uk/hooves__gb_1.mp3","us":"media/us/hooves__us_1.mp3"}},"homework":{"oxford":{"phon":"ˈhəʊmwɜːk","pos":"noun","senses":[{"en":"work that is given by teachers for students to do at home","cn":"（学生的）家庭作业","lab":"especially North American English","ex":{"en":"I always do my homework on the bus.","cn":"我总是在公共汽车上做作业。"}},{"en":"work that somebody does to prepare for something","cn":"准备工作","lab":"informal","ex":{"en":"You could tell that he had really done his homework (= found out all he needed to know).","cn":"你能看得出他确实做好了充分准备。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（学生的）家庭作业","en":"Homework is school work that teachers give to pupils to do at home in the evening or at the weekend.","ex":{"en":"Have you done your homework, Gemma?","cn":"杰玛，你做完家庭作业了吗？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"必要的准备工作","en":"If you do your homework, you find out what you need to know in preparation for something.","ex":{"en":"Before you go near a stockbroker, do your homework.","cn":"找股票经纪人之前，先要做好必要的准备工作。"}}]},"media":{"uk":"media/uk/homework__gb_1.mp3","us":"media/us/homework__us_1.mp3"},"examples":[{"en":"You could tell that he had really done his homework (= found out all he needed to know).","cn":"你能看得出他确实做了充分准备。"},{"en":"I still haven't done my geography homework.","cn":"我还没做完地理科家庭作业呢。"}]},"hour":{"media":{"uk":"media/uk/hour__gb_1.mp3","us":"media/us/hour__us_1.mp3"},"oxford":{"phon":"ˈaʊə(r)","pos":"noun","senses":[{"en":"60 minutes; one of the 24 parts that a day is divided into","cn":"小时","g":"[countable]","ex":{"en":"I spent an hour on the phone.","cn":"我打了一个小时电话。"}},{"en":"a period of about an hour, used for a particular purpose","cn":"约一小时的时间","g":"[countable, usually singular]","ex":{"en":"I spent my lunch hour shopping.","cn":"我用午餐时间去购物了。"}},{"en":"a fixed period of time during which people work, an office is open, etc.","cn":"（工作、办公等的）固定时间","g":"[plural]","ex":{"en":"Opening hours are from 10 to 6 each day.","cn":"营业时间为每天 10 点到 6 点。"}},{"en":"a long time","cn":"很长时间","g":"[plural]","ex":{"en":"It took hours getting there.","cn":"花了好长时间才到那里。"}},{"en":"a particular point in time","cn":"某一时刻","g":"[singular]","ex":{"en":"You can't turn him away at this hour of the night.","cn":"天这么晚了，你不能把他赶走。"}},{"en":"the time when something important happens","cn":"重要时刻","g":"[countable, usually singular]","ex":{"en":"This was often thought of as the country's finest hour.","cn":"一般认为这是该国最美好的一段时光。"}},{"en":"the time when it is exactly 1 o’clock, 2 o’clock, etc.","cn":"整点","g":"[singular]","ex":{"en":"The clock struck the hour.","cn":"钟敲过整点了。"}},{"en":"used when giving the time according to the 24-hour clock, usually in military or other official language","cn":"（按 24 小时制给出的时间，通常用于军事或其他官方用语）点钟","g":"[plural]","ex":{"en":"The first missile was launched at 2300 hours (= at 11 p.m.).","cn":"首枚导弹是在 23 点（晚上 11 点）发射的。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小时","en":"An hour is a period of sixty minutes.","ex":{"en":"They waited for about two hours","cn":"他们等了约两小时。"}},{"pos":"N-PLURAL 复数名词","cn":"长时间","en":"People say that something takes or lasts hours to emphasize that it takes or lasts a very long time, or what seems like a very long time.","ex":{"en":"Getting there would take hours.","cn":"去那里要花很长时间。"}},{"pos":"N-SING 单数名词","cn":"（时钟的）钟点，整点","en":"A clock that strikes the hour strikes when it is exactly one o'clock, two o'clock, and so on."},{"pos":"N-SING 单数名词","cn":"时间;时刻","en":"You can refer to a particular time or moment as a particular hour .","ex":{"en":"...the hour of his execution","cn":"处决他的时间"}},{"pos":"N-COUNT 可数名词","cn":"（人一生中的某个）时候，时期","en":"If you refer, for example, to someone's hour of need or hour of happiness, you are referring to the time in their life when they are or were experiencing that condition or feeling.","ex":{"en":"He recalled her devotion to her husband during his hour of need.","cn":"他回忆起她在丈夫困难之时的忠贞奉献。"}},{"pos":"N-PLURAL 复数名词","cn":"（每天发生或进行某事的）特定时间，固定时间","en":"You can refer to the period of time during which something happens or operates each day as the hours during which it happens or operates.","ex":{"en":"...the hours of darkness","cn":"夜晚"}},{"pos":"N-PLURAL 复数名词","cn":"（每周的）工作时间","en":"If you refer to the hours involved in a job, you are talking about how long you spend each week doing it and when you do it.","ex":{"en":"I worked quite irregular hours","cn":"我的工作时间相当不固定。"}},{"pos":"","cn":"","en":"→see: ; →see: ; →see: ;"},{"pos":"PHRASE 短语","cn":"下班后;营业（或办公、学习）时间以后","en":"If you do something after hours, you do it outside normal business hours or the time when you are usually at work.","ex":{"en":"...a local restaurant where steel workers unwind after hours","cn":"钢厂工人下班后去放松一下的当地餐馆"}},{"pos":"PHRASE 短语","cn":"在（某一时段的）任何时刻","en":"If you say that something happens at all hours of the day or night, you disapprove of it happening at the time that it does or as often as it does.","ex":{"en":"She didn't want her fourteen-year-old daughter coming home at all hours of the morning.","cn":"她不希望自己14岁的女儿凌晨才回家。"}},{"pos":"PHRASE 短语","cn":"在凌晨;在下半夜","en":"If something happens in the early hours or in the small hours, it happens in the early morning after midnight.","ex":{"en":"Gibbs was arrested in the early hours of yesterday morning.","cn":"吉布斯于昨天凌晨被捕。"}},{"pos":"PHRASE 短语","cn":"长时间地;不停地","en":"If you say that someone does something hour after hour, you are emphasizing that they do it continually for a long time.","ex":{"en":"He and my mom were arguing every night, hour after hour.","cn":"他和我妈妈每天晚上都吵个不停。"}},{"pos":"PHRASE 短语","cn":"整点地","en":"If something happens on the hour, it happens every hour at, for example, nine o'clock, ten o'clock, and so on, and not at any number of minutes past an hour."},{"pos":"PHRASE 短语","cn":"整点差…分/ 整点过…分","en":"If you want to state the time exactly, you can give a number of minutes followed by before the hour or past the hour ."},{"pos":"PHRASE 短语","cn":"在通常营业（或工作、学习）时间之外","en":"Something that happens out of hours happens at a time that is not during the usual hours of business or work.","ex":{"en":"Teachers refused to run out of hours sports matches because they weren't being paid.","cn":"教师拒绝课余安排体育比赛，因为他们不会获得薪酬。"}}]},"examples":[{"en":"The first missile was launched at 2300 hours (= at 11 p.m.).","cn":"首枚导弹是在 23 点（晚上 11 点）发射的。"},{"en":"This is the only place to get a drink after hours (= after the normal closing time for pubs).","cn":"这是酒吧正常关门时间之后唯一能喝一杯的地方。"}]},"hits":{"lemma":"hit","media":{"uk":"media/uk/hit__gb_1.mp3","us":"media/us/hit__us_1.mp3"}},"head":{"media":{"uk":"media/uk/head__gb_1.mp3","us":"media/us/head__us_1.mp3"},"oxford":{"phon":"hed","pos":"noun","senses":[{"en":"the part of the body on top of the neck containing the eyes, nose, mouth and brain","cn":"头；头部","g":"[countable]","lab":"informal","sc":"part of body","ex":{"en":"She nodded her head in agreement.","cn":"她点头表示同意。"}},{"en":"the mind or brain","cn":"头脑；脑筋","g":"[countable]","sc":"mind","ex":{"en":"I sometimes wonder what goes on in that head of yours.","cn":"我有时不明白你脑子里在想些什么。"}},{"en":"the size of a person’s or animal’s head, used as a measurement of distance or height","cn":"（人或动物的）一头长，一头高","g":"[singular]","sc":"measurement","ex":{"en":"She's a good head taller than her sister.","cn":"她比妹妹足足高出了一个头。"}},{"en":"a continuous pain in your head","cn":"（持续的）头痛","g":"[countable, usually singular]","lab":"informal","sc":"pain","ex":{"en":"I woke up with a really bad head this morning.","cn":"我今天早晨醒来时头痛得厉害。"}},{"en":"the person in charge of a group of people or an organization","cn":"负责人；领导人","g":"[countable, uncountable]","sc":"of group/organization","ex":{"en":"the heads of government/state","cn":"政府首脑；国家元首"}},{"en":"the person in charge of a school or college","cn":"校长；院长","g":"[countable]","lab":"British English","sc":"of school/college","ex":{"en":"I've been called in to see the Head.","cn":"我接到通知去见校长。"}},{"en":"the side of a coin that has a picture of the head of a person on it, used as one choice when a coin is tossed to decide something","cn":"硬币正面（有人头像）","g":"[uncountable]","sc":"side of coin","ex":{"en":"I called heads and it came down tails.","cn":"我要了正面，可落下来却是反面朝上。"}},{"en":"the end of a long narrow object that is larger or wider than the rest of it","cn":"较宽大的一端；头","g":"[countable, usually singular]","sc":"end of object","ex":{"en":"the head of a nail","cn":"钉子的头"}},{"en":"the top or highest part of something","cn":"顶端；上端","g":"[singular]","sc":"top","ex":{"en":"at the head of the page","cn":"在页眉处"}},{"en":"the place where a river begins","cn":"（河流）源头","g":"[singular]","sc":"of river"},{"en":"the most important seat at a table","cn":"上座（桌子旁最重要的座位）","g":"[singular]","sc":"of table","ex":{"en":"The President sat at the head of the table.","cn":"总统坐在桌子的上首。"}},{"en":"the position at the front of a line of people","cn":"领头位置；排头","g":"[singular]","sc":"of line of people","ex":{"en":"The prince rode at the head of his regiment.","cn":"王子骑马走在卫队的前头。"}},{"en":"the mass of leaves or flowers at the end of a stem","cn":"（茎梗顶端的）叶球，头状花序","g":"[countable]","sc":"of plant","ex":{"en":"Remove the dead heads to encourage new growth.","cn":"把枯萎了的残花除掉以促使新的生长。"}},{"en":"the mass of small bubbles on the top of a glass of beer","cn":"啤酒泡沫；酒头","g":"[singular]","sc":"on beer"},{"en":"the part of a spot on your skin that contains a thick yellow liquid (= pus)","cn":"脓头","g":"[countable]","sc":"of spot"},{"en":"the component of a sound or video recording system that converts data on the disk or tape into digital electronic data (and the other way round)","cn":"（录音或录像设备的）磁头","g":"[countable]","sc":"in recording system"},{"en":"used to say how many animals of a particular type are on a farm, in a herd, etc.","cn":"（表示农场或牧群等的牲畜的数目）头","g":"[plural]","sc":"number of animals","ex":{"en":"200 head of sheep","cn":"200 只绵羊"}},{"en":"the pressure produced by steam in a small space","cn":"蒸汽压力","g":"[singular]","sc":"pressure","ex":{"en":"The old engine still manages to build up a good head of steam.","cn":"旧发动机仍然能够产生良好的蒸汽头。"}},{"en":"oral sex (= using the mouth to give somebody sexual pleasure)","cn":"口交","g":"[uncountable]","lab":"taboo, slang，，","sc":"sex","ex":{"en":"to give head","cn":"进行口交"}},{"en":"the central part of a phrase, which has the same grammatical function as the whole phrase. In the phrase ‘the tall man in a suit’, man is the head.","cn":"（短语的）中心成分，中心词，主导词","g":"[countable]","sc":"linguistics"},{"en":"(in nouns) a person who is very enthusiastic about a particular thing or is addicted to a particular drug","cn":"（构成名词）⋯迷，⋯瘾君子","ex":{"en":"a gearhead","cn":"技术设备发烧友"},"pos":"suffix"},{"en":"to move in a particular direction","cn":"前往","g":"[intransitive]","lab":"figurative","sc":"move towards","ex":{"en":"Where are we heading?","cn":"我们要往哪儿去？"},"pos":"verb"},{"en":"to lead or be in charge of something","cn":"领导；主管","g":"[transitive]","sc":"group/organization","ex":{"en":"She has been appointed to head the research team.","cn":"她受命领导研究小组。"},"pos":"verb"},{"en":"to be at the top of a list of names or at the front of a line of people","cn":"位于排行之首；排在前头","g":"[transitive]","sc":"list/line of people","ex":{"en":"Italy heads the table after two games.","cn":"两场比赛之后意大利队排名榜首。"},"pos":"verb"},{"en":"to put a word or words at the top of a page or section of a book as a title","cn":"在（页或篇章的）顶端加标题","g":"[transitive, usually passive]","sc":"be at top","ex":{"en":"The chapter was headed ‘My Early Life’.","cn":"这一章的标题是“我的早年生活”。"},"pos":"verb"},{"en":"to hit a football with your head","cn":"用头顶（球）","g":"[transitive]","sc":"football","ex":{"en":"Walsh headed the ball into an empty goal.","cn":"沃尔什把球顶进了空门。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（人的）头，头部","en":"Your head is the top part of your body, which has your eyes, mouth, and brain in it.","ex":{"en":"She turned her head away from him","cn":"她把头别过去，不再看他。"}},{"pos":"N-COUNT 可数名词","cn":"头脑;心智;才智","en":"You can use head to refer to your mind and your mental abilities.","ex":{"en":"I can't get that song out of my head.","cn":"那首歌在我脑海中挥之不去。"}},{"pos":"N-SING 单数名词","cn":"（队伍中的）领头位置;队首;排头","en":"The head of a line of people or vehicles is the front of it, or the first person or vehicle in the line.","ex":{"en":"...the head of the queue","cn":"队首"}},{"pos":"VERB 动词","cn":"排在（队列等）的最前面","en":"If someone or something heads a line or procession, they are at the front of it.","ex":{"en":"The parson, heading the procession, had just turned right towards the churchyard.","cn":"走在行进队伍最前面的教区牧师刚刚向右转弯，朝着教堂墓地走去。"}},{"pos":"VERB 动词","cn":"居…之首;在…名列首位","en":"If something heads a list or group, it is at the top of it.","ex":{"en":"Running a business heads the list of ambitions among the 1,000 people interviewed by Good Housekeeping magazine.","cn":"在《好管家》杂志采访过的1,000人中，创立自己的公司在理想抱负中列在首位。"}},{"pos":"N-SING 单数名词","cn":"顶部;上端","en":"The head of something is the highest or top part of it.","ex":{"en":"...the head of the stairs","cn":"楼梯的顶部"}},{"pos":"N-COUNT 可数名词","cn":"（细长物体的）头部，顶端","en":"The head of something long and thin is the end which is wider than or a different shape from the rest, and which is often considered to be the most important part.","ex":{"en":"There should be no exposed screw heads","cn":"螺钉顶端不应该外露。"}},{"pos":"N-COUNT 可数名词","cn":"（中小学的）校长","en":"The head of a school is the teacher who is in charge.","ex":{"en":"She is full of admiration for the head and teachers.","cn":"她对校长和教师们满心钦佩。"}},{"pos":"N-COUNT 可数名词","cn":"（公司、组织的）负责人，领导人，首脑，长，主任","en":"The head of a company or organization is the person in charge of it and in charge of the people in it.","ex":{"en":"Heads of government from more than 100 countries gather in Geneva tomorrow.","cn":"来自100多个国家的政府首脑明日将齐聚日内瓦。"}},{"pos":"VERB 动词","cn":"掌管;主管;负责","en":"If you head a department, company, or organization, you are the person in charge of it.","ex":{"en":"...Michael Williams, who heads the department's Office of Civil Rights.","cn":"负责该部民权处的迈克尔·威廉斯"}},{"pos":"N-COUNT 可数名词","cn":"脓头","en":"The head of an infected spot is its white or yellow centre."},{"pos":"N-COUNT 可数名词","cn":"（啤酒表层的）泡沫;酒头","en":"The head on a glass of beer is the layer of small bubbles that form on the top of the beer."},{"pos":"N-PLURAL 复数名词","cn":"（表示牲畜的数目）头","en":"You can use head to say how many animals of a particular type a farmer has. For example, if they have fifty head of cattle, they have fifty cows."},{"pos":"N-COUNT 可数名词","cn":"头痛","en":"If you have a bad head, you have a headache.","ex":{"en":"I had a terrible head and was extraordinarily drunk.","cn":"我头很痛，已经酩酊大醉。"}},{"pos":"ADV 副词","cn":"（硬币的）有人头像的一面，正面","en":"If you toss a coin and it comes down heads, you can see the side of the coin which has a picture of a head on it.","ex":{"en":"'We might toss up for it,' suggested Ted. 'If it's heads, then we'll talk.'","cn":"“我们可以掷硬币来决定。”特德建议道，“如果是正面，我们就谈谈。”"}},{"pos":"VERB 动词","cn":"朝着（某一地点）行进（美国英语中亦作 are headed）","en":"If you are heading for a particular place, you are going towards that place. In American English, you can also say that you are headed for a particular place.","ex":{"en":"He headed for the bus stop","cn":"他朝着公共汽车站走去。"}},{"pos":"VERB 动词","cn":"很可能要遭受，会招致（美国英语中亦作 is headed for）","en":"If something or someone is heading for a particular result, the situation they are in is developing in a way that makes that result very likely. In American English, you can also say that something or someone is headed for a particular result.","ex":{"en":"The latest talks aimed at ending the civil war appear to be heading for deadlock","cn":"为结束内战而进行的最新谈判好像要陷入僵局。"}},{"pos":"VERB 动词","cn":"标题为","en":"If a piece of writing is headed a particular title, it has that title written at the beginning of it.","ex":{"en":"One chapter is headed, 'Beating the Test'.","cn":"有一章的标题为“战胜考试”。"}},{"pos":"VERB 动词","cn":"（足球比赛中）用头顶（球）","en":"If you head a ball in football, you hit it with your head in order to make it go in a particular direction.","ex":{"en":"He headed the ball across the face of the goal.","cn":"他一个头球，球从球门前横飞而过。"}},{"pos":"PHRASE 短语","cn":"每人/人均","en":"You use a head or per head after stating a cost or amount in order to indicate that that cost or amount is for each person in a particular group.","ex":{"en":"This simple chicken dish costs less than £1 a head","cn":"这道简单的鸡肉菜肴每人的花费还不到1英镑。"}},{"pos":"PHRASE 短语","cn":"让人生气;让人沮丧","en":"If something or someone does your head in, they make you angry or frustrated.","ex":{"en":"Living with my parents is doing my head in.","cn":"和父母住在一起让我很沮丧。"}},{"pos":"PHRASE 短语","cn":"从头到脚;全身","en":"From head to foot means all over your body.","ex":{"en":"Colin had been put into a bath and been scrubbed from head to foot.","cn":"科林被放进浴缸，从头到脚仔仔细细洗了个干净。"}},{"pos":"PHRASE 短语","cn":"擅长","en":"If you have a head for something, you can deal with it easily. For example, if you have a head for figures, you can do arithmetic easily, and if you have a head for heights, you can climb to a great height without feeling afraid.","ex":{"en":"I don't have a head for business.","cn":"我没有生意头脑。"}},{"pos":"PHRASE 短语","cn":"充分理解并接受;打定（主意）","en":"If you get a fact or idea into your head, you suddenly realize or think that it is true and you usually do not change your opinion about it.","ex":{"en":"Once they get an idea into their heads, they never give up.","cn":"一旦接受了一个想法，他们就永远不会放弃。"}},{"pos":"PHRASE 短语","cn":"终于明白","en":"If you say that someone has got something into their head, you mean that they have finally understood or accepted it, and you are usually criticizing them because it has taken them a long time to do this.","ex":{"en":"Managers have at last got it into their heads that they can no longer accept inefficient operations.","cn":"管理者们终于意识到自己不能再安于低效率的运营了。"}},{"pos":"PHRASE 短语","cn":"让…自由行动;对…不加约束","en":"If you give someone their head, you allow them to do what they want to do, without trying to advise or stop them.","ex":{"en":"He recognised ability and gave people their heads.","cn":"他发现别人的才能，并且让他们自由发挥。"}},{"pos":"PHRASE 短语","cn":"（酒）使人感到醉，上头","en":"If alcoholic drink goes to your head, it makes you feel drunk.","ex":{"en":"That wine was strong, it went to your head.","cn":"那酒劲儿很大，喝了会上头。"}},{"pos":"PHRASE 短语","cn":"（赞扬或成功）冲昏…的头脑，使…骄傲自满","en":"If you say that something such as praise or success goes to someone's head, you are criticizing them because you think that it makes them too proud or confident.","ex":{"en":"Ford is definitely not a man to let a little success go to his head.","cn":"福特绝对不是那种会被一点点成功冲昏头脑的人。"}},{"pos":"PHRASE 短语","cn":"深陷情网","en":"If you are head over heels or head over heels in love, you are very much in love.","ex":{"en":"I was very attracted to men and fell head over heels many times.","cn":"我很容易被男性吸引，曾多次深陷情网。"}},{"pos":"PHRASE 短语","cn":"保持镇静/张皇失措","en":"If you keep your head, you remain calm in a difficult situation. If you lose your head, you panic or do not remain calm in a difficult situation.","ex":{"en":"She was able to keep her head and not panic","cn":"她设法保持镇静，没有陷入恐慌。"}},{"pos":"PHRASE 短语","cn":"停止;结束","en":"If you knock something on the head, you stop it.","ex":{"en":"When we stop enjoying ourselves we'll knock it on the head.","cn":"等玩够了，我们就会结束。"}},{"pos":"PHRASE 短语","cn":"（表示强调）大笑/大声尖叫","en":"Phrases such as laugh your head off and scream your head off can be used to emphasize that someone is laughing or screaming a lot or very loudly.","ex":{"en":"He carried on telling a joke, laughing his head off.","cn":"他继续讲笑话，自己笑得前仰后合。"}},{"pos":"PHRASE 短语","cn":"（吸毒后）昏头昏脑的，神志不清的","en":"If you say that someone is off their head, you mean that they have taken so many drugs that they do not know what they are doing."},{"pos":"PHRASE 短语","cn":"昏了头的;愚蠢的","en":"If you say that someone is off their head, you think that their ideas or behaviour are very strange, foolish, or dangerous.","ex":{"en":"He's gone completely off his head.","cn":"他已经完全昏了头了。"}},{"pos":"PHRASE 短语","cn":"倒过来想;从全新的角度理解","en":"If you stand an idea or argument on its head or turn it on its head, you think about it or treat it in a completely new and different way.","ex":{"en":"Their relationship turned the standard notion of marriage on its head.","cn":"他们的关系完全颠覆了传统的婚姻观念。"}},{"pos":"PHRASE 短语","cn":"超过…的理解力","en":"If something such as an idea, joke, or comment goes over someone's head, it is too difficult for them to understand.","ex":{"en":"I admit that a lot of the ideas went way over my head.","cn":"我承认那些想法中有很多远远超出了我的理解力。"}},{"pos":"PHRASE 短语","cn":"未与…商量地;(尤指)越级","en":"If someone does something over another person's head, they do it without asking them or discussing it with them, especially when they should do so because the other person is in a position of authority.","ex":{"en":"He was reprimanded for trying to go over the heads of senior officers.","cn":"他因试图越过高层官员自作主张而受到斥责。"}},{"pos":"PHRASE 短语","cn":"（不好的事情）再次出现，重新抬头","en":"If you say that something unpleasant or embarrassing rears its ugly head or raises its ugly head, you mean that it occurs, often after not occurring for some time.","ex":{"en":"There was a problem which reared its ugly head about a week after she moved back in","cn":"她搬回来大约一周之后，一个问题又重新出现了。"}},{"pos":"PHRASE 短语","cn":"倒立;竖蜻蜓","en":"If you stand on your head, you balance upside down with the top of your head and your hands on the ground."},{"pos":"PHRASE 短语","cn":"理解;弄明白","en":"If you say that you cannot make head nor tail of something or you cannot make head or tail of it, you are emphasizing that you cannot understand it at all.","ex":{"en":"I couldn't make head nor tail of the damn film.","cn":"这部该死的影片我一点儿都看不懂。"}},{"pos":"PHRASE 短语","cn":"突然决定（做某事，尤指古怪或愚蠢的事）；心血来潮","en":"If somebody takes it into their head to do something, especially something strange or foolish, they suddenly decide to do it.","ex":{"en":"He suddenly took it into his head to go out to Australia to stay with his son.","cn":"他突然心血来潮，打算去澳大利亚和儿子一起住。"}},{"pos":"PHRASE 短语","cn":"到了危急关头;到达关键点","en":"If a problem or disagreement comes to a head or is brought to a head, it becomes so bad that something must be done about it.","ex":{"en":"These problems came to a head in September when five of the station's journalists were sacked.","cn":"这些问题在9月变得十分尖锐，当时该台有5名记者遭到辞退。"}},{"pos":"PHRASE 短语","cn":"严厉训斥","en":"If you bang peoples' heads together or knock their heads together, you tell them off severely for doing something wrong or for not doing something they were asked to do.","ex":{"en":"It is now high time he banged his colleagues' heads together.","cn":"现在该是他敲打敲打同事们的时候了。"}},{"pos":"PHRASE 短语","cn":"集体商讨;集思广益","en":"If two or more people put their heads together, they talk about a problem they have and try to solve it.","ex":{"en":"So everyone put their heads together and eventually an amicable arrangement was reached.","cn":"因此大家集思广益，最终作出了妥善的安排。"}},{"pos":"PHRASE 短语","cn":"（尤指在生意方面）勉强逃脱困境","en":"If you keep your head above water, you just avoid getting into difficulties; used especially to talk about business.","ex":{"en":"We are keeping our head above water, but our cash flow position is not too good.","cn":"我们正努力避免陷入困境，但我们的现金流动情况不太好。"}},{"pos":"PHRASE 短语","cn":"有人会遭殃，有人会（因此）受到惩罚（尤指被解雇）","en":"If you say that heads will roll as a result of something bad that has happened, you mean that people will be punished for it, especially by losing their jobs.","ex":{"en":"The group's problems have led to speculation that heads will roll.","cn":"已经有人猜测，该集团的问题会导致一些人被解雇。"}},{"pos":"","cn":"","en":"相关词组：head off head up"}]},"examples":[{"en":"For some reason, she's got it into her head (= believes) that the others don't like her.","cn":"由于某种原因，她有一种感觉，认为其他人都不喜欢她。"},{"en":"The favourite won by a short head (= a distance slightly less than the length of a horse's head).","cn":"最被看好的那匹马以不足一马头之差的优势获胜。"}]},"habitually":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"repeated actions are done on several occasions, especially because they do not have any effect at first","cn":""},{"en":"done often as a habit, especially when this is annoying to other people","cn":""}]},"examples":[{"en":"His drinking had become habitual.","cn":"","src":"ld"},{"en":"James took his habitual morning walk around the garden.","cn":"","src":"ld"}],"media":{"uk":"media/uk/habitually__gb_1.mp3","us":"media/us/habitually__us_1.mp3"},"oxford":{"phon":"həˈbɪtʃuəli","pos":"adverb","senses":[{"en":"in a way that is usual for or typical of somebody/something","cn":"惯常的；典型的","ex":{"en":"the dark glasses he habitually wore","cn":"他常戴的墨镜"}},{"en":"in a way that is annoying or difficult to stop, often because it has become a habit","cn":"习惯性地：以令人讨厌或难以停止的方式，通常是因为它已成为一种习惯","ex":{"en":"We are in an era where politicians habitually lie about everything.","cn":"我们正处在一个政客习惯于对一切事情撒谎的时代。"}}]}},"hms":{"media":{"uk":"media/uk/hms__gb_1.mp3","us":"media/us/hms__us_1.mp3"},"oxford":{"phon":"ˌeɪtʃ em ˈes","pos":"abbreviation","senses":[{"en":"Her/His Majesty’s Ship (used before the name of a ship in the British navy)","cn":"皇家海军舰艇（用于英国海军舰艇名前）","ex":{"en":"HMS Apollo","cn":"皇家海军阿波罗号"}}]},"collins":{"senses":[{"pos":"N-IN-NAMES 名称名词","cn":"英国皇家海军舰艇（用于船名前）","en":"HMS is used before the names of ships in the British Royal Navy. HMS is an abbreviation for (缩略=) 'Her Majesty's Ship' or 'His Majesty's Ship'.","ex":{"en":"...launching HMS Warrior.","cn":"英国皇家海军军舰“勇士号”下水"}}]},"examples":[{"en":"HMS Apollo","cn":"皇家海军阿波罗号"},{"en":"HMS Belfast","cn":"英国皇家海军战舰“贝尔法斯特”号"}]},"hit":{"media":{"uk":"media/uk/hit__gb_1.mp3","us":"media/us/hit__us_1.mp3"},"oxford":{"phon":"hɪt","pos":"verb","senses":[{"en":"to bring your hand, or an object you are holding, against somebody/something quickly and with force","cn":"（用手或器具）击，打","g":"[transitive]","sc":"touch somebody/something with force","ex":{"en":"I was afraid he was going to hit me.","cn":"我怕他会打我。"}},{"en":"to come against something/somebody with force, especially causing damage or injury","cn":"碰撞；撞击（造成损伤）","g":"[transitive, intransitive]","sc":"touch somebody/something with force","ex":{"en":"The bus hit the bridge.","cn":"公共汽车撞到了桥上。"}},{"en":"to knock a part of your body against something","cn":"使（身体部位）碰上（某物）","g":"[transitive]","sc":"touch somebody/something with force","ex":{"en":"I must have hit my knee.","cn":"我肯定撞到了膝盖。"}},{"en":"to reach and touch a person or thing suddenly and with force","cn":"击中；命中","g":"[transitive, often passive]","sc":"touch somebody/something with force","ex":{"en":"The town was hit by bombs again last night.","cn":"这个镇子昨晚又一次遭到了轰炸。"}},{"en":"to bring a bat, etc. against a ball and push it away with force","cn":"击（球）","g":"[transitive]","sc":"ball","ex":{"en":"She hit the ball and ran to first base.","cn":"她击球后跑向一垒。"}},{"en":"to score points by hitting a ball","cn":"击球得分","g":"[transitive]","lab":"sport","sc":"ball","ex":{"en":"to hit a home run","cn":"打出本垒打"}},{"en":"to press something such as a button to operate a machine, etc.","cn":"按，压（按钮等）","g":"[transitive]","lab":"informal","sc":"press button","ex":{"en":"Hit the brakes!","cn":"踩刹车！"}},{"en":"to have a bad effect on somebody/something","cn":"产生不良影响；打击；危害","g":"[transitive, intransitive]","sc":"have bad effect","ex":{"en":"The tax increases will certainly hit the poor.","cn":"增税肯定会加重穷人的负担。"}},{"en":"to attack somebody/something","cn":"攻击；进攻；袭击","g":"[transitive, intransitive]","sc":"attack","ex":{"en":"We hit the enemy when they least expected it.","cn":"我们在敌人最意想不到的时候发动了进攻。"}},{"en":"to reach a place","cn":"到达（某地）","g":"[transitive]","lab":"informal","sc":"reach","ex":{"en":"Follow this footpath and you'll eventually hit the road.","cn":"沿着这条小路走，终会走上大路。"}},{"en":"to reach a particular level","cn":"达到（某水平）","g":"[transitive]","lab":"British English","sc":"reach","ex":{"en":"Temperatures hit 40° yesterday.","cn":"昨天气温高达 40 度。"}},{"en":"to experience something difficult or unpleasant","cn":"遇到（困难）；经历（不愉快的事情）","g":"[transitive]","lab":"informal","sc":"problem/difficulty","ex":{"en":"We seem to have hit a problem.","cn":"我们似乎遇到了问题。"}},{"en":"to come suddenly into your mind","cn":"使突然想起","g":"[transitive]","lab":"informal","sc":"suddenly realize","ex":{"en":"The idea hit me like a tornado.","cn":"这个想法猛然闯进我的脑海。"}},{"en":"to become widely available for sale","cn":"大量上市","g":"[transitive]","lab":"informal","sc":"become available","ex":{"en":"the latest board game to hit the market","cn":"最新上市的桌面游戏"}},{"en":"an act of hitting somebody/something with your hand or with an object held in your hand","cn":"打；击","sc":"act of hitting","ex":{"en":"Give it a good hit.","cn":"用力打它一下。"},"pos":"noun"},{"en":"an occasion when something that has been thrown, fired, etc. at an object reaches that object; the fact of being hit by something","cn":"命中；击中","sc":"act of hitting","ex":{"en":"We finished the first round with a score of two hits and six misses.","cn":"我们在第一轮结束时的分数是两次击中，六次未中。"},"pos":"noun"},{"en":"a person or thing that is very popular","cn":"很受欢迎的人（或事物）","sc":"something popular","ex":{"en":"He's just about to star in the hit musical, ‘Chicago’.","cn":"他即将出演热门音乐剧《芝加哥》。"},"pos":"noun"},{"en":"a successful pop song or record","cn":"风行一时的流行歌曲（或唱片）","sc":"pop music","ex":{"en":"They are about to release an album of their greatest hits.","cn":"他们即将发行收录他们最热门歌曲的专辑。"},"pos":"noun"},{"en":"an occasion on which a web page is displayed or a file is downloaded from the internet","cn":"（网页的）点击；（文件的）下载","lab":"computing","sc":"computing","ex":{"en":"Our website is getting a lot of hits from the USA.","cn":"我们的网站得到很多来自美国的点击。"},"pos":"noun"},{"en":"the fact of finding an item of data that matches a search","cn":"（信息检索的）匹配，结果","lab":"computing","sc":"computing","ex":{"en":"The search generated 1 848 hits.","cn":"这一搜索得到了 1 848 个相关结果。"},"pos":"noun"},{"en":"an amount of an illegal drug that is taken at one time","cn":"毒品的一剂","lab":"slang","sc":"of drug","ex":{"en":"a hit of cocaine/heroin","cn":"吸食可卡因/海洛因"},"pos":"noun"},{"en":"a violent crime or murder","cn":"暴力犯罪；凶杀","lab":"slang, especially North American English，，","sc":"murder","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打;击","en":"If you hit someone or something, you deliberately touch them with a lot of force, with your hand or an object held in your hand.","ex":{"en":"Find the exact grip that allows you to hit the ball hard","cn":"找到能让你大力击球的准确握拍方法。"}},{"pos":"VERB 动词","cn":"撞击;碰撞","en":"When one thing hits another, it touches it with a lot of force.","ex":{"en":"The car had apparently hit a traffic sign before skidding out of control","cn":"汽车显然是撞上了一个交通标志牌后打滑失控的。"}},{"pos":"VERB 动词","cn":"（炸弹、导弹）击中，命中","en":"If a bomb or missile hits its target, it reaches it.","ex":{"en":"...multiple-warhead missiles that could hit many targets at a time","cn":"可一次击中多个目标的多弹头导弹"}},{"pos":"VERB 动词","cn":"打击;使受严重影响","en":"If something hits a person, place, or thing, it affects them very badly.","ex":{"en":"The plan to charge motorists £75 a year to use the motorway is going to hit me hard","cn":"向汽车驾驶员每年收取75英镑高速公路使用费的计划将对我大为不利。"}},{"pos":"VERB 动词","cn":"使突然想起","en":"When a feeling or an idea hits you, it suddenly affects you or comes into your mind.","ex":{"en":"It hit me that I had a choice","cn":"我突然意识到我有选择的余地。"}},{"pos":"VERB 动词","cn":"达到（某一高点或低点）","en":"If you hit a particular high or low point on a scale of something such as success or health, you reach it.","ex":{"en":"He admits to having hit the lowest point in his life ","cn":"他承认自己跌到了一生中的最低谷。"}},{"pos":"N-COUNT 可数名词","cn":"成功而轰动（或风行）一时的事物（如唱片、电影或戏剧）","en":"If a CD, film, or play is a hit, it is very popular and successful.","ex":{"en":"The song became a massive hit in 1945.","cn":"这首歌在1945年风靡大江南北。"}},{"pos":"N-COUNT 可数名词","cn":"（网站的）点击，浏览，访问","en":"A hit is a single visit to a website.","ex":{"en":"Our small company has had 78,000 hits on its Internet pages.","cn":"我们这个小公司的因特网网页已经有了78,000次的点击量。"}},{"pos":"N-COUNT 可数名词","cn":"（在因特网上的）查询结果，检索结果","en":"If someone who is searching for information on the Internet gets a hit, they find a website where there is that information."},{"pos":"PHR-RECIP 相互短语","cn":"一见如故;合得来；投缘","en":"If two people hit it off, they like each other and become friendly as soon as they meet.","ex":{"en":"They hit it off straight away, Daddy and Walter","cn":"爸爸和沃尔特很快就一见如故。"}},{"pos":"PHRASE 短语","cn":"大受欢迎;深受…的喜爱;令…印象深刻","en":"If you make a hit with someone, they like you or are impressed by you when they meet you.","ex":{"en":"He made a hit with Lady Sopwith","cn":"他深受索普威思太太的喜爱。"}},{"pos":"","cn":"","en":"to hit the bottle→see: ; to hit the headlines→see: ; to hit home→see: ; to hit the nail on the head→see: ; to hit the road→see: ; to hit the roof→see: ; to hit someone for six→see: ;"},{"pos":"","cn":"","en":"相关词组：hit back hit on hit out hit upon"}]},"examples":[{"en":"In a rousing speech the minister hit out at racism in the armed forces.","cn":"在一次激励人心的讲话中，部长严厉抨击了军中的种族主义。"},{"en":"I couldn't remember where I'd seen him before, and then it suddenly hit me.","cn":"起初我想不起以前在哪里见过他，后来猛然记起来了。"}]},"horizon":{"media":{"uk":"media/uk/horizon__gb_1.mp3","us":"media/us/horizon__us_1.mp3"},"oxford":{"phon":"həˈraɪzn","pos":"noun","senses":[{"en":"the furthest that you can see, where the sky seems to meet the land or the sea","cn":"地平线；海平线","g":"[singular]","ex":{"en":"The sun sank below the horizon.","cn":"太阳落到了地平线下。"}},{"en":"the limit of your desires, knowledge or interests","cn":"（欲望、知识或兴趣的）范围，眼界","g":"[countable, usually plural]","ex":{"en":"She wanted to travel to broaden her horizons.","cn":"她想旅行，以开阔眼界。"}},{"en":"a television documentary series which is broadcast in Britain, on BBC Two. It started in 1964 and includes programmes on different topics in the areas of science, nature, medicine and natural history.","cn":"地平线：在英国播出的电视纪录片系列，在BBC第二电视台上播出。它始于1964年，包括有关科学，自然，医学和自然历史领域不同主题的课程。","pos":""}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"地平线","en":"The horizon is the line in the far distance where the sky seems to meet the land or the sea.","ex":{"en":"A grey smudge appeared on the horizon. That must be Calais, thought Fay","cn":"一个模糊的灰影出现在地平线上。那里一定是加来，法伊心想。"}},{"pos":"N-COUNT 可数名词","cn":"范围;眼界;见识","en":"Your horizons are the limits of what you want to do or of what you are interested or involved in.","ex":{"en":"As your horizons expand, these new ideas can give a whole new meaning to life","cn":"随着眼界不断开阔，这些新观念会为生活赋予全新的意义。"}},{"pos":"PHRASE 短语","cn":"已露端倪的;即将发生的","en":"If something is on the horizon, it is almost certainly going to happen or be done quite soon.","ex":{"en":"With breast cancer, as with many common diseases, there is no obvious breakthrough on the horizon","cn":"对乳腺癌等很多常见疾病来说，目前还看不到有明显的突破。"}}]},"examples":[{"en":"The company needs new horizons now.","cn":"公司现在需要开拓新的领域。"},{"en":"A ship appeared on the horizon.","cn":"一艘船出现在地平线上。"}]},"half-sister":{"oxford":{"phon":"ˈhɑːf sɪstə(r)","pos":"noun","senses":[{"en":"a person’s half-sister is a girl or woman who has either the same mother or the same father as them","cn":"同母异父（或同父异母）的姐妹"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同母异父（或同父异母）姐妹","en":"Someone's half-sister is a girl or woman who has either the same mother or the same father as they have."}]},"media":{"uk":"media/uk/half_sister_1_gb_1.mp3","us":"media/us/half_sister_1_us_1.mp3"}},"hunted":{"oxford":{"phon":"ˈhʌntɪd","pos":"adjective","senses":[{"en":"showing that somebody is very worried or frightened, as if somebody is following them and trying to catch them","cn":"（像被人追踪般）惴惴不安的，惊恐万分的","ex":{"en":"His eyes had a hunted look.","cn":"他的双眼透露出恐慌的神色。"}}]},"media":{"uk":"media/uk/hunted__gb_1.mp3","us":"media/us/hunted__us_1.mp3"},"examples":[{"en":"His eyes had a hunted look.","cn":"他双眼透露出恐慌的神态。"}],"base":"hunt"},"harsh":{"media":{"uk":"media/uk/harsh__gb_1.mp3","us":"media/us/harsh__us_1.mp3"},"oxford":{"phon":"hɑːʃ","pos":"adjective","senses":[{"en":"cruel, severe and unkind","cn":"残酷的；严酷的；严厉的","ex":{"en":"The punishment was harsh and unfair.","cn":"处罚很重而且不公平。"}},{"en":"very difficult and unpleasant to live in","cn":"恶劣的；艰苦的","ex":{"en":"a harsh winter/wind/climate","cn":"寒冷的冬天；凛冽的风；恶劣的气候"}},{"en":"too strong and bright; ugly or unpleasant to look at","cn":"强烈刺眼的；丑陋的","ex":{"en":"harsh colours","cn":"扎眼的色彩"}},{"en":"unpleasant to listen to","cn":"刺耳的；难听的","ex":{"en":"‘Stop it!’ she said in a harsh voice.","cn":"“停下来！”她用刺耳的嗓音说道。"}},{"en":"too strong and rough and likely to damage something","cn":"粗糙的；毛糙的；刺激性强的","ex":{"en":"harsh detergents","cn":"刺激性强的洗涤剂"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（气候或条件）艰苦的，恶劣的，严峻的","en":"Harsh climates or conditions are very difficult for people, animals, and plants to live in.","ex":{"en":"The weather grew harsh, chilly and unpredictable.","cn":"天气变得恶劣、寒冷且变化莫测。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言行）严厉的，无情的","en":"Harsh actions or speech are unkind and show no understanding or sympathy.","ex":{"en":"...the cold, harsh cruelty of her husband","cn":"她丈夫冷酷无情的残忍"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗陋的;刺目的;粗糙的","en":"Something that is harsh is so hard, bright, or rough that it seems unpleasant or harmful.","ex":{"en":"Tropical colours may look rather harsh in our dull northern light.","cn":"热带色彩在我们北方暗淡的光线下可能显得有点刺目。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声音）刺耳的，难听的","en":"Harsh voices and sounds are ones that are rough and unpleasant to listen to.","ex":{"en":"It's a pity she has such a loud harsh voice.","cn":"可惜她的嗓门太大太难听了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（现实、真相）残酷的，无情的","en":"If you talk about harsh realities or facts, or the harsh truth, you are emphasizing that they are true or real, although they are unpleasant and people try to avoid thinking about them.","ex":{"en":"The harsh truth is that luck plays a big part in who will live or die.","cn":"残酷的事实是，谁死谁活在很大程度上要靠运气。"}}]},"examples":[{"en":"We had to face up to the harsh realities of life sooner or later.","cn":"我们迟早都得正视生活的严酷现实。"},{"en":"He regretted his harsh words.","cn":"他对自己的刻薄言辞感到后悔。"}]},"hearth":{"media":{"uk":"media/uk/hearth__gb_1.mp3","us":"media/us/hearth__us_1.mp3"},"oxford":{"phon":"hɑːθ","pos":"noun","senses":[{"en":"the floor at the bottom of a fireplace (= the space for a fire in the wall of a room); the area in front of this","cn":"壁炉炉床；壁炉前的地面","ex":{"en":"A log fire roared in the open hearth.","cn":"柴火在敞开着的壁炉里熊熊燃烧。"}},{"en":"home and family life","cn":"家和家庭生活","lab":"literary","ex":{"en":"a longing for hearth and home","cn":"对温暖家庭的渴望"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"壁炉地面;壁炉炉床","en":"The hearth is the floor of a fireplace, which sometimes extends into the room.","ex":{"en":"It was winter and there was a huge fire roaring in the hearth.","cn":"时值冬天，壁炉里炉火熊熊。"}},{"pos":"PHRASE 短语","cn":"温暖舒适的家庭生活","en":"A person's home and family life can be referred to as their hearth and home .","ex":{"en":"...a man who leaves his hearth and home to labour as a miner in the inhospitable north.","cn":"离开温暖舒适的家到荒凉的北方做矿工的男子"}}]},"examples":[{"en":"The cat dozed in its favourite spot on the hearth.","cn":"猫躺在壁炉前它最喜欢的地方打盹。"},{"en":"A log fire roared in the open hearth.","cn":"柴火在敞开着的壁炉里熊熊燃烧。"}]},"high-end":{"oxford":{"phon":"ˌhaɪ ˈend","pos":"adjective","senses":[{"en":"expensive and of high quality","cn":"高档的；高端的；价高质优的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（尤指电子产品）最高档的，高端的，最昂贵的","en":"High-end products, especially electronic products, are the most expensive of their kind.","ex":{"en":"...high-end personal computers and computer workstations.","cn":"高端个人计算机和计算机工作站"}}]},"media":{"uk":"media/uk/high_end_1_gb_1.mp3","us":"media/us/high_end_1_us_1.mp3"},"examples":[{"en":"high-end computer memory chips","cn":"高端电脑存储芯片"}]},"heart":{"media":{"uk":"media/uk/heart__gb_1.mp3","us":"media/us/heart__us_1.mp3"},"oxford":{"phon":"hɑːt","pos":"noun","senses":[{"en":"the organ in the chest that sends blood around the body, usually on the left in humans","cn":"心；心脏","g":"[countable]","sc":"part of body","ex":{"en":"The patient's heart stopped beating for a few seconds.","cn":"病人的心跳停顿了几秒钟。"}},{"en":"the outside part of the chest where the heart is","cn":"胸部心脏的部位；胸怀","g":"[countable]","lab":"literary","sc":"part of body","ex":{"en":"She clasped the photo to her heart.","cn":"她把相片紧紧地抱在怀里。"}},{"en":"a thing that is like a heart in shape, often red and used as a symbol of love; a symbol like a heart used to mean the verb ‘love’","cn":"心形物；（常指象征爱的）红心；心形（表示动词“爱”）","g":"[countable]","sc":"shape","ex":{"en":"The words ‘I love you’ were written inside a big red heart.","cn":"“我爱你”这几个字写在一个大红心里。"}},{"en":"the place in a person where the feelings and emotions are thought to be, especially those connected with love","cn":"内心；心肠；（尤指）爱心","g":"[countable]","sc":"feelings/emotions","ex":{"en":"She has a kind heart.","cn":"她有一颗善良的心。"}},{"en":"having the type of character or personality mentioned","cn":"有…性格（或品格）的","sc":"-hearted","ex":{"en":"simple-hearted","cn":"心地单纯"}},{"en":"the most important part of something","cn":"核心；实质；要点","g":"[singular]","sc":"important part","ex":{"en":"the heart of the matter/problem","cn":"事情／问题的核心"}},{"en":"the part that is in the centre of something","cn":"中心；中央","g":"[countable, usually singular]","sc":"centre","ex":{"en":"a quiet hotel in the very heart of the city","cn":"一家位于市中心的安静的旅馆"}},{"en":"the smaller leaves in the middle of a cabbage, lettuce, etc.","cn":"菜心","g":"[countable]","sc":"of vegetable"},{"en":"one of the four suits (= sets) in a pack of cards, with red heart symbols on them","cn":"（扑克牌的）红桃，红心","g":"[plural, uncountable]","sc":"in card games","ex":{"en":"the queen of hearts","cn":"红桃王后"}},{"en":"one card from the suit called hearts","cn":"（一张）红桃，红心","g":"[countable]","sc":"in card games","ex":{"en":"Who played that heart?","cn":"谁打出那张红桃？"}},{"en":"to like somebody/something very much; to love somebody/something","cn":"非常喜欢；爱","ex":{"en":"She wore an ‘I heart Dad’ T-shirt.","cn":"她穿了一件写着“我爱爸爸”的 T 恤衫。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"心;心脏;胸口","en":"Your heart is the organ in your chest that pumps the blood around your body. People also use heart to refer to the area of their chest that is closest to their heart.","ex":{"en":"The bullet had passed less than an inch from Andrea's heart","cn":"子弹在离安德烈亚的心脏不到一英寸的地方穿过。"}},{"pos":"N-COUNT 可数名词","cn":"内心;心灵;心情","en":"You can refer to someone's heart when you are talking about their deep feelings and beliefs.","ex":{"en":"Alik's words filled her heart with pride","cn":"亚利克的话让她心感自豪。"}},{"pos":"N-VAR 可变名词","cn":"心肠;心地;同情心","en":"You use heart when you are talking about someone's character and attitude towards other people, especially when they are kind and generous.","ex":{"en":"She loved his brilliance and his generous heart","cn":"她深爱他的才华横溢和古道热肠。"}},{"pos":"N-SING 单数名词","cn":"爱情;爱恋;感情","en":"If you refer to things of the heart, you mean love and relationships.","ex":{"en":"This is an excellent time for affairs of the heart.","cn":"这是谈情说爱的绝佳时机。"}},{"pos":"N-SING 单数名词","cn":"核心;实质;重点;要点","en":"The heart of something is the most central and important part of it.","ex":{"en":"The heart of the problem is supply and demand","cn":"问题的核心是供求关系。"}},{"pos":"N-SING 单数名词","cn":"（地方的）中心","en":"The heart of a place is its centre.","ex":{"en":"...a busy dentists' practice in the heart of London's West End.","cn":"位于伦敦西区中心的一个繁忙的牙科诊所"}},{"pos":"N-COUNT 可数名词","cn":"（蔬菜的）菜心","en":"The heart of a lettuce, cabbage, or other vegetable is its centre leaves."},{"pos":"N-COUNT 可数名词","cn":"（作为爱的象征的）心形","en":"A heart is a shape that is used as a symbol of love: ♥.","ex":{"en":"...heart-shaped chocolates.","cn":"心形巧克力"}},{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"（纸牌的）红桃，红心","en":"Hearts is one of the four suits in a pack of playing cards. Each card in the suit is marked with one or more red symbols in the shape of a heart.","ex":{"en":"West had to decide whether to play a heart.","cn":"韦斯特必须决定是否要出一张红桃。"}},{"pos":"PHRASE 短语","cn":"全心全意地;真心实意地","en":"If you feel or believe something with all your heart, you feel or believe it very strongly.","ex":{"en":"My own family I loved with all my heart.","cn":"我真心实意地爱我全家人。"}},{"pos":"PHRASE 短语","cn":"（人）本质上，实际上，内心里","en":"If you say that someone is a particular kind of person at heart, you mean that that is what they are really like, even though they may seem very different.","ex":{"en":"He was a very gentle boy at heart.","cn":"他实际上是个非常温柔的男生。"}},{"pos":"PHRASE 短语","cn":"十分关心（某人的利益或福祉）","en":"If you say that someone has your interests or your welfare at heart, you mean that they are concerned about you and that is why they are doing something.","ex":{"en":"She told him she only had his interests at heart.","cn":"她告诉他自己万事都是为了他好。"}},{"pos":"PHRASE 短语","cn":"（通常指因感情破裂而）使…伤心，使…心碎","en":"If someone breaks your heart, they make you very sad and unhappy, usually because they end a love affair or close relationship with you."},{"pos":"PHRASE 短语","cn":"（尤指因对他人的苦难无能为力而）使…伤心，使…心碎","en":"If something breaks your heart, it makes you feel very sad and depressed, especially because people are suffering but you can do nothing to help them.","ex":{"en":"It really breaks my heart to see them this way.","cn":"看到他们这个样子可真让我伤心。"}},{"pos":"PHRASE 短语","cn":"心碎;伤心","en":"If you say that someone has a broken heart, you mean that they are very sad, for example because a love affair has ended unhappily.","ex":{"en":"She never recovered from her broken heart.","cn":"她心上的伤再也没能愈合。"}},{"pos":"PHRASE 短语","cn":"背得出;靠记忆","en":"If you know something such as a poem by heart, you have learned it so well that you can remember it without having to read it.","ex":{"en":"Mack knew this passage by heart.","cn":"麦克会背这一段。"}},{"pos":"PHRASE 短语","cn":"态度的转变","en":"If someone has a change of heart, their attitude towards something changes.","ex":{"en":"Several brokers have had a change of heart about prospects for the company","cn":"几位经纪人对该公司前景的看法已经有所改变。"}},{"pos":"PHRASE 短语","cn":"为…所重视（或关注）","en":"If something such as a subject or project is close to your heart or near to your heart, it is very important to you and you are very interested in it and concerned about it.","ex":{"en":"Animal welfare is a subject very close to my heart.","cn":"动物福利是我非常关注的一个问题。"}},{"pos":"PHRASE 短语","cn":"尽情地;痛痛快快地","en":"If you can do something to your heart's content, you can do it as much as you want.","ex":{"en":"I was delighted to be able to eat my favorite dishes to my heart's content.","cn":"我很高兴能够痛痛快快地吃我最喜爱的菜。"}},{"pos":"CONVENTION 惯用语","cn":"我发誓（所说的是真的）/你敢发誓（所说的是真的）吗？","en":"You can say 'cross my heart' when you want someone to believe that you are telling the truth. You can also ask 'cross your heart?', when you are asking someone if they are really telling the truth.","ex":{"en":"And I won't tell any of the other girls anything you tell me about it. I promise, cross my heart.","cn":"我不会把你告诉我的事告诉任何其他女孩。我发誓，保证不会。"}},{"pos":"PHRASE 短语","cn":"真诚地;发自内心地","en":"If you say something from the heart or from the bottom of your heart, you sincerely mean what you say.","ex":{"en":"He spoke with confidence, from the heart","cn":"他的话充满信心，发自心坎。"}},{"pos":"PHRASE 短语","cn":"鼓励…;使…振作起来","en":"If something gives you heart, it makes you feel more confident or happy about something.","ex":{"en":"It gave me heart to see one thug get what he deserves.","cn":"看到一个恶棍罪有应得真是大快我心。"}},{"pos":"PHRASE 短语","cn":"不忍心（做…）","en":"If you want to do something but do not have the heart to do it, you do not do it because you know it will make someone unhappy or disappointed.","ex":{"en":"We knew all along but didn'thave the heart to tell her.","cn":"我们一直都知道，但却不忍心告诉她。"}},{"pos":"PHRASE 短语","cn":"在心底里;在内心深处","en":"If you believe or know something in your heart of hearts, that is what you really believe or think, even though it may sometimes seem that you do not.","ex":{"en":"I know in my heart of hearts that I am the right man for that mission.","cn":"我心里深知我是完成那项任务的合适人选。"}},{"pos":"PHRASE 短语","cn":"对…无兴趣;心不在…上","en":"If your heart isn't in the thing you are doing, you have very little enthusiasm for it, usually because you are depressed or are thinking about something else.","ex":{"en":"I tried to learn some lines but my heart wasn't really in it.","cn":"我想要背几句台词，但我的心根本不在那上面。"}},{"pos":"PHRASE 短语","cn":"失去信心;灰心;泄气","en":"If you lose heart, you become sad and depressed and are no longer interested in something, especially because it is not progressing as you would like.","ex":{"en":"He appealed to his countrymen not to lose heart.","cn":"他呼吁自己的同胞不要丧失信心。"}},{"pos":"PHRASE 短语","cn":"爱上…；对…倾心","en":"If you lose your heart to someone, you fall in love with them."},{"pos":"PHRASE 短语","cn":"激动非常;焦急万分;害怕得要命","en":"If your heart is in your mouth, you feel very excited, worried, or frightened.","ex":{"en":"My heart was in my mouth when I walked into her office.","cn":"我走进她的办公室时，紧张得心都到了喉咙口。"}},{"pos":"PHRASE 短语","cn":"敞开心扉;倾吐心里话","en":"If you open your heart or pour out your heart to someone, you tell them your most private thoughts and feelings.","ex":{"en":"She opened her heart to millions yesterday and told how she came close to suicide.","cn":"她昨天在数成百万人面前倾吐心声，讲述了自己是如何差点轻生的。"}},{"pos":"PHRASE 短语","cn":"（尽管有其他缺点但）心地善良，心眼儿好","en":"If you say that someone's heart is in the right place, you mean that they are kind, considerate, and generous, although you may disapprove of other aspects of their character.","ex":{"en":"He is a bit of a tearaway but his heart is in the right place.","cn":"他是有点像个阿飞，但心眼儿不错。"}},{"pos":"PHRASE 短语","cn":"一心想要得到;一心想要做","en":"If you have set your heart on something, you want it very much or want to do it very much.","ex":{"en":"He had always set his heart on a career in the fine arts.","cn":"他一直以来都一心想把美术作为自己的事业。"}},{"pos":"PHRASE 短语","cn":"感情外露;心直口快","en":"If you wear your heart on your sleeve, you openly show your feelings or emotions rather than keeping them hidden."},{"pos":"PHRASE 短语","cn":"全心全意地;尽心尽力地","en":"If you put your heart and soul into something, you do it with a great deal of enthusiasm and energy.","ex":{"en":"He will always be successful when he puts his mind to something, because he puts his heart and soul into it.","cn":"当他专心想干某件事时，他总是能成功，因为他会全心全意地投入其中。"}},{"pos":"PHRASE 短语","cn":"（从…）得到鼓舞;（因…）振作精神","en":"If you take heart from something, you are encouraged and made to feel optimistic by it."},{"pos":"PHRASE 短语","cn":"对…耿耿于怀;为…感到不快","en":"If you take something to heart, for example someone's behaviour, you are deeply affected and upset by it.","ex":{"en":"If someone says something critical I take it to heart.","cn":"如果有人提出批评，我会十分介意。"}}]},"examples":[{"en":"My heart sank when I saw how much work there was left.","cn":"我看到还有那么多活没干时，心顿时沉了下去。"},{"en":"The story captured the hearts and minds of a generation.","cn":"这部小说准确地传达了一代人的感情和思想。"}]},"hatred":{"oxford":{"phon":"ˈheɪtrɪd","pos":"noun","senses":[{"en":"a very strong feeling of dislike for somebody/something","cn":"仇恨；憎恨；厌恶","ex":{"en":"He looked at me with intense hatred.","cn":"他满怀敌意地看着我。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"仇恨;憎恶;敌意","en":"Hatred is an extremely strong feeling of dislike for someone or something.","ex":{"en":"Her hatred of them would never lead her to murder","cn":"她虽说仇恨他们，但绝不至于去杀人。"}}]},"media":{"uk":"media/uk/hatred__gb_1.mp3","us":"media/us/hatred__us_1.mp3"},"examples":[{"en":"The debate simply revived old hatreds.","cn":"这一辩论不过是再次挑起了夙仇。"},{"en":"There was fear and hatred in his voice.","cn":"他的声音里透露着恐惧和仇恨。"}]},"hillside":{"media":{"uk":"media/uk/hillside__gb_1.mp3","us":"media/us/hillside__us_1.mp3"},"oxford":{"phon":"ˈhɪlsaɪd","pos":"noun","senses":[{"en":"the side of a hill","cn":"小山坡","ex":{"en":"The crops will not grow on exposed hillsides.","cn":"在裸露的山坡上庄稼没法生长。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（小山的）山坡，山腰","en":"A hillside is the sloping side of a hill."}]},"examples":[{"en":"Our hotel was on the hillside overlooking the lake.","cn":"我们的旅馆位于可俯瞰湖水的小山坡上。"},{"en":"The crops will not grow on exposed hillsides.","cn":"在裸露的山坡上庄稼没法生长。"}]},"hmm":{"media":{"uk":"media/uk/hmm__gb_1.mp3","us":"media/us/hmm__us_1.mp3"},"oxford":{"phon":"m","pos":"exclamation","senses":[{"en":"used in writing to show the sound that you make to express doubt or when you are hesitating","cn":"（书写形式，表示有疑虑或犹豫时发出的声音）呣，嗯，唔，哼"}]}},"hunger":{"media":{"uk":"media/uk/hunger__gb_1.mp3","us":"media/us/hunger__us_1.mp3"},"oxford":{"phon":"ˈhʌŋɡə(r)","pos":"noun","senses":[{"en":"the state of not having enough food to eat, especially when this causes illness or death","cn":"饥饿；饥荒","g":"[uncountable]","ex":{"en":"Around fifty people die of hunger every day in the camp.","cn":"集中营里每天大约有五十人饿死。"}},{"en":"the feeling caused by a need to eat","cn":"饥饿感；食欲；胃口","g":"[uncountable]","ex":{"en":"If you feel hunger pangs between meals, eat some fruit or nuts.","cn":"如果您在两餐之间感到饥饿，可以吃一些水果或坚果。"}},{"en":"a strong desire for something","cn":"渴望；渴求","g":"[singular]","lab":"formal","ex":{"en":"She has an insatiable hunger for knowledge.","cn":"她对知识有着无止境的渴求。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"饥饿感","en":"Hunger is the feeling of weakness or discomfort that you get when you need something to eat.","ex":{"en":"Hunger is the body's signal that levels of blood sugar are too low","cn":"饥饿感是身体发出的信号，表示血糖水平太低。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"饥饿;饥荒","en":"Hunger is a severe lack of food which causes suffering or death.","ex":{"en":"Three hundred people in this town are dying of hunger every day.","cn":"该镇每天有300人濒于饿死。"}},{"pos":"N-SING 单数名词","cn":"渴望;渴求","en":"If you have a hunger for something, you want or need it very much.","ex":{"en":"Geffen has a hunger for success that seems bottomless.","cn":"格芬的成功欲望似乎永无止境。"}},{"pos":"VERB 动词","cn":"渴望;渴求","en":"If you say that someone hungers for something or hungers after it, you are emphasizing that they want it very much.","ex":{"en":"But Jules was not eager for classroom learning, he hungered for adventure.","cn":"但朱尔斯对坐在课堂里学习并不热心，他渴望冒险。"}}]},"examples":[{"en":"The organization works to alleviate world hunger and disease.","cn":"这个机构致力于减少世界上的饥饿和疾病。"},{"en":"Nothing seemed to satisfy their hunger for truth.","cn":"似乎没有什么能满足他们对真理的渴求。"}]},"hides":{"lemma":"hide"},"host":{"media":{"uk":"media/uk/host__gb_1.mp3","us":"media/us/host__us_1.mp3"},"oxford":{"phon":"həʊst","pos":"noun","senses":[{"en":"a person who invites guests to a meal, a party, etc. or who has people staying at their house","cn":"主人","g":"[countable]","ex":{"en":"Ian, our host, introduced us to the other guests.","cn":"主人伊恩把我们介绍给了其他客人。"}},{"en":"a country, a city or an organization that holds and arranges a special event","cn":"东道主；主办国（或城市、机构）","g":"[countable]","ex":{"en":"the host nation/country/city","cn":"主办国／城市"}},{"en":"a person who introduces a television or radio show, and talks to guests","cn":"（电视或广播的）节目主持人","g":"[countable]","ex":{"en":"a radio/TV host","cn":"广播／电视节目主持人"}},{"en":"an animal or a plant on which another animal or plant lives and feeds","cn":"（寄生动植物的）宿主，寄主","g":"[countable]","lab":"specialist"},{"en":"a large number of people or things","cn":"许多；大量","g":"[countable]","ex":{"en":"a host of possibilities","cn":"多种可能性"}},{"en":"the main computer in a network that controls or supplies information to other computers that are connected to it","cn":"（计算机网络的）主机，服务机","g":"[countable]","lab":"computing","ex":{"en":"transferring files from the host to your local computer","cn":"从主机向你的本地机传送文件"}},{"en":"the bread that is used in the Christian service of communion, after it has been blessed","cn":"圣饼（基督教圣餐仪式中经过祝祷的面饼）","g":"[singular]"},{"en":"to organize an event to which others are invited and make all the arrangements for them","cn":"主办，主持（活动）","g":"[transitive]","ex":{"en":"to host an event/a conference/a meeting","cn":"主办活动／大会／会议"},"pos":"verb"},{"en":"to introduce a television or radio programme, a show, etc.","cn":"主持（电视或广播节目等）","g":"[transitive]","ex":{"en":"Charlie Rose will host tonight's show.","cn":"查理·罗斯将主持今晚的节目。"},"pos":"verb"},{"en":"to organize a party that you have invited guests to","cn":"作为主人组织（聚会）；做东","g":"[transitive, intransitive]","ex":{"en":"to host a dinner","cn":"设宴招待客人"},"pos":"verb"},{"en":"to store a website on a computer connected to the internet, usually in return for payment","cn":"为（网站）提供虚拟主机（通常收费）","g":"[transitive]","lab":"computing","ex":{"en":"a company that builds and hosts e-commerce sites","cn":"为电子商务提供网站创建和虚拟主机服务的公司"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（举办聚会等的）主人，东道主","en":"The host at a party is the person who has invited the guests and provides the food, drink, or entertainment.","ex":{"en":"Apart from my host, I didn't know a single person there","cn":"除了主人外，那里的人我一个也不认识。"}},{"pos":"VERB 动词","cn":"作为主人组织，做东举办（聚会等）","en":"If someone hosts a party, dinner, or other function, they have invited the guests and provide the food, drink, or entertainment.","ex":{"en":"Tonight she hosts a ball for 300 guests.","cn":"今晚她做东举办一场有300名客人参加的舞会。"}},{"pos":"N-COUNT 可数名词","cn":"（某项活动的）主办国（或城市、机构）","en":"A country, city, or organization that is the host of an event provides the facilities for that event to take place.","ex":{"en":"Barcelona was chosen to be host of the 1992 Olympic games.","cn":"巴塞罗那获选为1992年奥运会的主办城市。"}},{"pos":"VERB 动词","cn":"（国家、城市或机构）主办（活动）","en":"If a country, city, or organization hosts an event, they provide the facilities for the event to take place.","ex":{"en":"Cannes hosts the annual film festival.","cn":"戛纳每年主办电影节。"}},{"pos":"PHRASE 短语","cn":"主办（活动）;接待（贵客）","en":"If a person or country plays host to an event or an important visitor, they host the event or the visit.","ex":{"en":"In 1987 Canada played host to the Commonwealth Conference","cn":"1987年加拿大主办了英联邦大会。"}},{"pos":"N-COUNT 可数名词","cn":"（广播、电视的）节目主持人","en":"The host of a radio or television show is the person who introduces it and talks to the people who appear in it.","ex":{"en":"I am host of a live radio programme.","cn":"我是一个电台直播节目的主持人。"}},{"pos":"VERB 动词","cn":"主持（广播、电视节目）","en":"The person who hosts a radio or television show introduces it and talks to the people who appear in it.","ex":{"en":"She also hosts a show on St Petersburg Radio.","cn":"她还在圣彼得堡电台主持一个节目。"}},{"pos":"QUANT 数量词","cn":"大量;许多","en":"A host of things is a lot of them.","ex":{"en":"A host of problems may delay the opening of the Channel Tunnel","cn":"可能推迟英吉利海峡隧道开通的问题一大筐。"}},{"pos":"N-COUNT 可数名词","cn":"（生物的）生长地，栖息地","en":"If an area is host to living things, those creatures live and feed in that area.","ex":{"en":"Uganda's beautiful highlands are host to a wide range of wildlife.","cn":"乌干达美丽的高地是众多野生动物的栖息地。"}},{"pos":"N-COUNT 可数名词","cn":"（计算机）主机","en":"A host or a host computer is the main computer in a network of computers, which controls the most important files and programs."},{"pos":"N-COUNT 可数名词","cn":"（寄生物的）寄主，宿主","en":"The host of a parasite is the plant or animal which it lives on or inside and from which it gets its food.","ex":{"en":"When the eggs hatch the larvae eat the living flesh of the host animal.","cn":"当卵孵化后，幼虫取食寄主的鲜肉。"}},{"pos":"N-COUNT 可数名词","cn":"圣体（基督教圣餐礼等宗教仪式中代表耶稣躯体的面饼）","en":"The Host is the bread which is used to represent the body of Christ in Christian church services such as Holy Communion."}]},"examples":[{"en":"a company that builds and hosts e-commerce sites","cn":"在互联网上建立并存贮电子商务网站的公司"},{"en":"The college is playing host to a group of visiting Russian scientists.","cn":"学院正在接待一批来访的俄罗斯科学家。"}]},"hate":{"media":{"uk":"media/uk/hate__gb_1.mp3","us":"media/us/hate__us_1.mp3"},"oxford":{"phon":"heɪt","pos":"verb","senses":[{"en":"to dislike somebody/something very much","cn":"极不喜欢；厌恶","g":"[transitive, intransitive]","ex":{"en":"The two boys hated each other.","cn":"那两个男孩相互厌恶。"}},{"en":"used when saying something that you would prefer not to have to say, or when politely asking to do something","cn":"（表示不愿说某事，或客气地请求）不愿，不想","g":"[no passive]","ex":{"en":"I hate to say it, but I don't think their marriage will last.","cn":"我不愿这么说，但我觉得他们的婚姻不会长久。"}},{"en":"a very strong feeling of dislike for somebody","cn":"憎恨；厌恶；仇恨","g":"[uncountable]","ex":{"en":"She gave him a look of real hate.","cn":"她给了他一个真正仇恨的眼神。"},"pos":"noun"},{"en":"a person or thing that you hate","cn":"所憎恶的人（或事物）","g":"[countable]","lab":"informal","ex":{"en":"Plastic flowers have always been a particular hate of mine.","cn":"我一向特别厌恶塑料花。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"仇恨;憎恨;憎恶","en":"If you hate someone or something, you have an extremely strong feeling of dislike for them.","ex":{"en":"Most people hate him, but they don't dare to say so, because he still rules the country","cn":"人们大多憎恨他，但不敢说，因为他仍在统治这个国家。"}},{"pos":"VERB 动词","cn":"讨厌;厌恶;不喜欢","en":"If you say that you hate something such as a particular activity, you mean that you find it very unpleasant.","ex":{"en":"Ted hated parties, even gatherings of people he liked individually","cn":"特德讨厌各种派对，即便是他自己喜欢的人的聚会也不例外。"}},{"pos":"VERB 动词","cn":"我真不愿麻烦你/我真不想打扰你","en":"You can use hate in expressions such as 'I hate to trouble you' or 'I hate to bother you' when you are apologizing to someone for interrupting them or asking them to do something.","ex":{"en":"I hate to rush you but I have another appointment later on.","cn":"我真不想催你，但我稍后还有一个约会。"}},{"pos":"VERB 动词","cn":"我很抱歉这么说/我很遗憾地通知你","en":"You can use hate in expressions such as 'I hate to say it' or 'I hate to tell you' when you want to express regret about what you are about to say, because you think it is unpleasant or should not be the case.","ex":{"en":"I hate to tell you this, but tomorrow's your last day","cn":"我很抱歉地通知你，明天是你的最后一天了。"}},{"pos":"","cn":"","en":"to hate someone's guts→see: ;"},{"pos":"VERB 动词","cn":"我很不愿意看到/我很不愿意想","en":"You can use hate in expressions such as 'I hate to see' or 'I hate to think' when you are emphasizing that you find a situation or an idea unpleasant.","ex":{"en":"I just hate to see you doing this to yourself.","cn":"我真不愿意看到你这样对待自己。"}},{"pos":"VERB 动词","cn":"真希望…不是真的（或不会发生）","en":"You can use hate in expressions such as 'I'd hate to think' when you hope that something is not true or that something will not happen.","ex":{"en":"I'd hate to think my job would not be secure if I left it temporarily.","cn":"希望我的工作不会因为我暂时休假而不保。"}}]},"examples":[{"en":"Whether you love or loathe their music, you can't deny their talent.","cn":"无论你是否喜欢他们的音乐，你都无法否认他们的才能。"},{"en":"I hate to say it, but I don't think their marriage will last.","cn":"我不愿这么说，但我觉得他们的婚姻不会长久。"}]},"hospitality":{"media":{"uk":"media/uk/hospitality__gb_1.mp3","us":"media/us/hospitality__us_1.mp3"},"oxford":{"phon":"ˌhɒspɪˈtæləti","pos":"noun","senses":[{"en":"friendly and generous behaviour towards guests","cn":"好客；殷勤","ex":{"en":"Thank you for your kind hospitality.","cn":"感谢你的友好款待。"}},{"en":"food, drink or services that are provided by an organization for guests, customers, etc.","cn":"（款待客人、顾客等的）食物，饮料，服务；款待","ex":{"en":"We were entertained in the company's hospitality suite.","cn":"公司款待我们住进他们的迎宾套间。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"殷勤好客;热情友好","en":"Hospitality is friendly, welcoming behaviour towards guests or people you have just met.","ex":{"en":"Every visitor to Georgia is overwhelmed by the kindness, charm and hospitality of the people.","cn":"来到佐治亚州的每位游客都被当地人的善良、可爱和热情好客所深深打动。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（大型活动中公司为来访者或客户提供的）招待茶点，款待","en":"Hospitality is the food, drink, and other privileges which some companies provide for their visitors or clients at major sporting or other public events.","ex":{"en":"A few of us in the press were there, goggle-eyed at the lavish hospitality.","cn":"我们几位记者当时在那里，眼馋地看着丰盛的茶点。"}}]},"examples":[{"en":"We were entertained in the company's hospitality suite.","cn":"公司款待我们住进他们的迎宾套间。"},{"en":"the hospitality industry (= hotels, restaurants, etc.)","cn":"招待性行业（如旅馆、饭店等）"}]},"hollywood":{"media":{"uk":"media/uk/hollywood__gb_1.mp3","us":"media/us/hollywood__us_1.mp3"},"oxford":{"phon":"ˈhɒliwʊd","pos":"noun","senses":[{"en":"the part of Los Angeles where the film industry is based (used to refer to the US film industry and the way of life that is associated with it)","cn":"好莱坞；美国电影业；好莱坞生活方式","lab":"British English"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"（美国的）好莱坞电影业","en":"You use Hollywood to refer to the American film industry that is based in Hollywood, California.","ex":{"en":"...a major Hollywood studio.","cn":"好莱坞一家大制片厂"}}]},"examples":[{"en":"She is one of Hollywood’s major stars.","cn":"她是好莱坞的巨星之一。"}]},"hall":{"media":{"uk":"media/uk/hall__gb_1.mp3","us":"media/us/hall__us_1.mp3"},"oxford":{"phon":"hɔːl","pos":"noun","senses":[{"en":"a space or passage inside the entrance or front door of a building","cn":"门厅；正门过道","lab":"especially in British English","ex":{"en":"Her brother was standing in the front hall.","cn":"她哥哥站在前厅。"}},{"en":"a passage in a building with rooms down either side","cn":"（大楼内的）走廊","lab":"North American English","ex":{"en":"I headed for Scott's office down the hall.","cn":"我沿着走廊直奔斯科特的办公室。"}},{"en":"a building or large room for public meetings, meals, concerts, etc.","cn":"礼堂；大厅","lab":"British English","ex":{"en":"a concert/sports hall","cn":"音乐厅；体育馆"}},{"en":"a building for university or college students to live in","cn":"（大学）学生宿舍","lab":"North American English also","ex":{"en":"She's living in hall(s).","cn":"她住在学生宿舍。"}},{"en":"a large country house","cn":"大庄园府邸","lab":"British English","ex":{"en":"Haddon Hall","cn":"哈登府"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（房子或公寓的）门厅","en":"The hall in a house or flat is the area just inside the front door, into which some of the other rooms open.","ex":{"en":"The lights were on in the hall and in the bedroom.","cn":"门厅和卧室的灯都亮着。"}},{"pos":"N-COUNT 可数名词","cn":"（大楼里的）走廊，过道","en":"A hall in a building is a long passage with doors into rooms on both sides of it."},{"pos":"N-COUNT 可数名词","cn":"大厅;会堂;礼堂","en":"A hall is a large room or building which is used for public events such as concerts, exhibitions, and meetings.","ex":{"en":"Its 300 inhabitants will be celebrating with a dance in the village hall","cn":"300名村民将在村礼堂举行一场舞会以示庆祝。"}},{"pos":"N-COUNT 可数名词","cn":"（大学或学院的）学生宿舍","en":"If students live in hall in British English, or in a hall in American English, they live in a university or college building called a hall of residence."},{"pos":"N-IN-NAMES 名称名词","cn":"（乡间）大庄园，府第（用于住宅名称中）","en":"Hall is sometimes used as part of the name of a large house in the country.","ex":{"en":"He died at Holly Hall, his wife's family home.","cn":"他在妻子的娘家冬青府去世。"}},{"pos":"N-IN-NAMES 名称名词","cn":"厅，会堂，礼堂（尤用于礼堂、音乐厅等名称中）","en":"Hall is sometimes used as part of the name of a large building, especially one where public events or concerts take place","ex":{"en":"...New York's Carnegie Hall.","cn":"纽约的卡内基音乐厅"}}]},"examples":[{"en":"I headed for Scott's office down the hall.","cn":"我沿着走廊直奔斯科特的办公室。"},{"en":"( BrE ) A jumble sale will be held in the village hall on Saturday.","cn":"星期六将在村礼堂举行义卖。"}]},"homesickness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not happy","cn":""},{"en":"sad, especially for a long time – used about people and periods of time","cn":""}]},"media":{"uk":"media/uk/homesickness__gb_1.mp3","us":"media/us/homesickness__us_1.mp3"},"oxford":{"phon":"ˈhəʊmsɪknəs","pos":"noun","senses":[{"en":"the feeling of being sad because you are away from home and you miss your family and friends","cn":"思乡的；想家的；患怀乡病的","ex":{"en":"She soon got over her homesickness.","cn":"她的思乡情绪很快就缓解了。"}}]}},"hand":{"media":{"img":["media/ldoce/img/hand.jpg","media/pic/hand_body_comp.jpg"],"uk":"media/uk/hand__gb_1.mp3","us":"media/us/hand__us_1.mp3"},"oxford":{"phon":"hænd","pos":"noun","senses":[{"en":"the part of the body at the end of the arm, including the fingers and thumb","cn":"手","g":"[countable]","lab":"informal","sc":"part of body","ex":{"en":"Ian placed a hand on her shoulder.","cn":"伊恩把一只手搭在她的肩上。"}},{"en":"using the hand or number of hands mentioned","cn":"用…手的；用…只手的","sc":"-handed","ex":{"en":"a one-handed catch","cn":"单手抓接"}},{"en":"help in doing something","cn":"帮助；协助","g":"[singular]","lab":"informal","sc":"help","ex":{"en":"The neighbours are always willing to lend a hand.","cn":"邻居们总是乐于帮忙。"}},{"en":"the part or role that somebody/something plays in a particular situation; somebody’s influence in a situation","cn":"角色；作用；影响","g":"[singular]","sc":"role in situation","ex":{"en":"Early reports suggest the hand of rebel forces in the bombings.","cn":"早期的报道暗示叛乱武装插手了爆炸案。"}},{"en":"a part of a clock or watch that points to the numbers","cn":"指针","g":"[countable]","sc":"on clock/watch"},{"en":"a person who does physical work on a farm or in a factory","cn":"（农场或工厂的）体力劳动者，工人","g":"[countable]","sc":"worker","ex":{"en":"The farmer would bring in hired hands to help him harvest the crop.","cn":"农民会聘请雇工来帮助他收割庄稼。"}},{"en":"a sailor on a ship","cn":"船员","g":"[countable]","sc":"sailor","ex":{"en":"All hands on deck!","cn":"全体船员到甲板上集合！"}},{"en":"by a person rather than a machine","cn":"手工","sc":"hand-","ex":{"en":"hand-painted pottery","cn":"手绘陶器"}},{"en":"a set of playing cards given to one player in a game","cn":"（分给游戏者的）一手牌","g":"[countable]","lab":"figurative","sc":"in card games","ex":{"en":"to be dealt a good/bad hand","cn":"拿到一手好牌／烂牌"}},{"en":"one stage of a game of cards","cn":"（纸牌游戏的）一盘","g":"[countable]","sc":"in card games","ex":{"en":"I'll have to leave after this hand.","cn":"这一盘打完后我必须走了。"}},{"en":"a particular style of writing","cn":"书法","g":"[singular]","lab":"old use","sc":"writing"},{"en":"a unit for measuring the height of a horse, equal to 4 inches or 10.16 centimetres","cn":"一手之宽（测量马的高度的单位，等于 4 英寸或 10.16 厘米）","g":"[countable]","sc":"measurement for horse"},{"en":"to pass or give something to somebody","cn":"交；递；给","ex":{"en":"She handed the letter to me.","cn":"她把信交给我。"},"pos":"verb"},{"en":"to allow somebody to have something, sometimes too easily","cn":"拱手让给；轻易送给","lab":"sometimes disapproving","ex":{"en":"Missed chances by United players handed a surprise victory to Stoke.","cn":"曼联球员错失良机，斯托克城队意外获胜。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手","en":"Your hands are the parts of your body at the end of your arms. Each hand has four fingers and a thumb.","ex":{"en":"I put my hand into my pocket and pulled out the letter","cn":"我把手伸进口袋，掏出了那封信。"}},{"pos":"N-SING 单数名词","cn":"作用;影响","en":"The hand of someone or something is their influence in an event or situation.","ex":{"en":"The hand of the military authorities can be seen in the entire electoral process","cn":"整个选举过程中都能看出军方的介入。"}},{"pos":"N-PLURAL 复数名词","cn":"照顾;支配;掌管","en":"If you say that something is in a particular person's hands, you mean that they are looking after it, own it, or are responsible for it.","ex":{"en":"I feel that possibly the majority of these dogs are in the wrong hands","cn":"在我看来很可能这些狗大多数都没有人妥善照看。"}},{"pos":"N-SING 单数名词","cn":"帮助;援手","en":"If you ask someone for a hand with something, you are asking them to help you in what you are doing.","ex":{"en":"I could see you'd want a hand with the children","cn":"我能看出你需要有人帮着照看孩子。"}},{"pos":"N-COUNT 可数名词","cn":"（工厂或农场的）工人，体力劳动者（通常指男性）","en":"A hand is someone, usually a man, who does hard physical work, for example in a factory or on a farm, as part of a group of people who all do similar work.","ex":{"en":"He now works as a farm hand","cn":"他现在是一名农场工人。"}},{"pos":"N-SING 单数名词","cn":"（通常指演出前后的）鼓掌，掌声","en":"If someone asks an audience to give someone a hand, they are asking the audience to clap loudly, usually before or after that person performs.","ex":{"en":"Let's give 'em a big hand.","cn":"让我们为他们热烈鼓掌。"}},{"pos":"N-COUNT 可数名词","cn":"（女方的）允婚","en":"If a man asks for a woman's hand in marriage, he asks her or her parents for permission to marry her.","ex":{"en":"He came to ask Usha's father for her hand in marriage.","cn":"他来请求乌莎的父亲把女儿嫁给他。"}},{"pos":"N-COUNT 可数名词","cn":"（纸牌游戏中的）手中的牌，一手牌","en":"In a game of cards, your hand is the set of cards that you are holding in your hand at a particular time or the cards that are dealt to you at the beginning of the game.","ex":{"en":"He carefully inspected his hand.","cn":"他仔细地审视着自己手中的牌。"}},{"pos":"N-COUNT 可数名词","cn":"一手之宽（测量马匹高度的单位，等于4英寸）","en":"A hand is a measurement of four inches, which is used for measuring the height of a horse from its front feet to its shoulders.","ex":{"en":"I had a very good 14.2 hands pony, called Brandy.","cn":"我有一匹很棒的14.2手高的小马，名叫布朗迪。"}},{"pos":"N-COUNT 可数名词","cn":"（钟表上的）指针","en":"The hands of a clock or watch are the thin pieces of metal or plastic that indicate what time it is."},{"pos":"N-SING 单数名词","cn":"字迹;手迹;笔迹","en":"Your hand is the style in which you write with a pen or pencil.","ex":{"en":"The manuscripts were written in the composer's own hand.","cn":"手稿是作曲家亲笔写的。"}},{"pos":"PHRASE 短语","cn":"（空间或时间上）接近的，不远的","en":"If something is at hand ,near at hand, or close at hand, it is very near in place or time.","ex":{"en":"Having the right equipment at hand will be enormously helpful","cn":"手头上有合适的设备将会帮上大忙。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…手中，从…那里（尤指受到不好的待遇）","en":"If someone experiences a particular kind of treatment, especially unpleasant treatment, at the hands of a person or organization, they receive it from them.","ex":{"en":"The civilian population were suffering greatly at the hands of the security forces.","cn":"老百姓吃尽了安全部队的苦头。"}},{"pos":"PHRASE 短语","cn":"用手工","en":"If you do something by hand, you do it using your hands rather than a machine.","ex":{"en":"Each pleat was stitched in place by hand.","cn":"每条褶裥都是手工缝制到位的。"}},{"pos":"PHRASE 短语","cn":"变换所有权;易主;易手","en":"When something changes hands, its ownership changes, usually because it is sold to someone else.","ex":{"en":"The firm has changed hands many times over the years.","cn":"该公司多年来已几易其主。"}},{"pos":"PHRASE 短语","cn":"完全受（某人）支配;完全听命于（某人）","en":"If you have someone eating out of your hand, they are completely under your control.","ex":{"en":"Parker could have customers eating out of his hand.","cn":"帕克能让顾客对自己言听计从。"}},{"pos":"PHRASE 短语","cn":"连手带脚地，手脚一起地（捆绑）","en":"If someone is bound hand and foot, both their hands and both their feet are tied together."},{"pos":"PHRASE 短语","cn":"迫使（某人）提前行动（或公开其所作所为）","en":"If you force someone's hand, you force them to act sooner than they want to, or to act in public when they would prefer to keep their actions secret.","ex":{"en":"He blamed the press for forcing his hand.","cn":"他指责新闻界迫使自己采取行动。"}},{"pos":"PHRASE 短语","cn":"（为…）忙得不可开交;（因…）应接不暇","en":"If you have your hands full with something, you are very busy because of it.","ex":{"en":"She had her hands full with new arrivals.","cn":"她忙于应付新来的人。"}},{"pos":"PHRASE 短语","cn":"自行决定权;自由行动权","en":"If someone gives you a free hand, they give you the freedom to use your own judgment and to do exactly as you wish.","ex":{"en":"He gave Stephanie a free hand in the decoration.","cn":"他放手让斯蒂芬妮全权负责装修一事。"}},{"pos":"PHRASE 短语","cn":"迅速而大量地（赚钱或花钱）","en":"If you say that someone is making or losing money hand over fist, you mean that they are getting or losing a lot of money very quickly."},{"pos":"PHRASE 短语","cn":"（通常指经过努力后）获得，得到","en":"If you get your hands on something or lay your hands on something, you manage to find it or obtain it, usually after some difficulty.","ex":{"en":"Patty began reading everything she could get her hands on.","cn":"帕蒂开始阅读她能找到的所有东西。"}},{"pos":"PHRASE 短语","cn":"（与某人）密切合作地","en":"If you work hand in glove with someone, you work very closely with them.","ex":{"en":"The UN inspectors work hand in glove with the Western intelligence agencies.","cn":"联合国观察员和西方情报机构之间密切合作。"}},{"pos":"PHRASE 短语","cn":"（常指为表示爱意而）手拉手的，携着手的","en":"If two people are hand in hand, they are holding each other's nearest hand, usually while they are walking or sitting together. People often do this to show their affection for each other.","ex":{"en":"I saw them making their way, hand in hand, down the path.","cn":"我看到他们手拉手沿着小路往前走去。"}},{"pos":"PHRASE 短语","cn":"（两件事）密切相关地，同时并进地","en":"If two things go hand in hand, they are closely connected and cannot be considered separately from each other.","ex":{"en":"For us, research and teaching go hand in hand","cn":"对我们而言，研究和教学是齐头并进的。"}},{"pos":"PHRASE 短语","cn":"参加;参与","en":"If you have a hand in something such as an event or activity, you are involved in it.","ex":{"en":"He thanked all who had a hand in his release.","cn":"他向所有帮助自己获得释放的人表示感谢。"}},{"pos":"PHRASE 短语","cn":"（统治者）用高压手段，严厉地","en":"If you say that someone such as the ruler of a country treats people with a heavy hand, you are criticizing them because they are very strict and severe with them.","ex":{"en":"Henry and Richard both ruled with a heavy hand.","cn":"亨利和理查都用高压手段实行统治。"}},{"pos":"PHR-RECIP 相互短语","cn":"（常指为表示爱意而）手拉手，牵手","en":"If two people are holding hands, they are holding each other's nearest hand, usually while they are walking or sitting together. People often do this to show their affection for each other.","ex":{"en":"She approached a young couple holding hands on a bench.","cn":"她走近一对手拉手坐在长椅上的年轻情侣。"}},{"pos":"PHRASE 短语","cn":"给…精神上的支持","en":"If you ask someone to hold your hand at an event that you are worried about, you ask them to support you by being there with you.","ex":{"en":"I don't need anyone to hold my hand.","cn":"我不需要任何人的精神安慰。"}},{"pos":"PHRASE 短语","cn":"（比赛）尚待进行","en":"In a competition, if someone has games or matches in hand, they have more games or matches left to play than their opponent and therefore have the possibility of scoring more points.","ex":{"en":"Wales are three points behind Romania in the group but have a game in hand.","cn":"威尔士队在小组中以3分之差落后于罗马尼亚队，但他们还有一场比赛没踢。"}},{"pos":"PHRASE 短语","cn":"（时间或金钱）宽余的","en":"If you have time or money in hand, you have more time or money than you need.","ex":{"en":"Hughes finished with 15 seconds in hand.","cn":"休斯提前了15秒完成。"}},{"pos":"PHRASE 短语","cn":"（工作或问题）办理中的，处理中的","en":"The job or problem in hand is the job or problem that you are dealing with at the moment.","ex":{"en":"The business in hand was approaching some kind of climax.","cn":"手头的生意似乎快到紧要关头了。"}},{"pos":"PHRASE 短语","cn":"（局势）在控制下，在掌握中","en":"If a situation is in hand, it is under control.","ex":{"en":"The Olympic organisers say that matters are well in hand.","cn":"奥运会的组织方说各项事务都在掌控之中。"}},{"pos":"PHRASE 短语","cn":"偶尔练习以保持熟练","en":"If you do something to keep your hand in, you practise a skill or hobby occasionally in order to remain fairly good at it.","ex":{"en":"He still plays keyboards for a local band to keep his hand in.","cn":"他仍在一个本地乐队里担任键盘手，以免技艺生疏。"}},{"pos":"PHRASE 短语","cn":"趴着;四肢着地","en":"If you are on your hands and knees, your knees and feet and the palms of your hands are touching the ground.","ex":{"en":"Chris crawled on his hands and knees out onto the highway.","cn":"克里斯手脚并用爬上了公路。"}},{"pos":"PHRASE 短语","cn":"向…伸出援手;给予…帮助","en":"If you lend someone a hand, you help them.","ex":{"en":"I'd be glad to lend a hand.","cn":"我很乐意帮忙。"}},{"pos":"PHRASE 短语","cn":"（不客气的警告语）别碰…，别干涉…","en":"If you tell someone to keep their hands off something or to take their hands off it, you are telling them in a rather aggressive way not to touch it or interfere with it.","ex":{"en":"Keep your hands off my milk.","cn":"不准打我的牛奶的主意。"}},{"pos":"PHRASE 短语","cn":"马上;立即;无需询问（或查证）","en":"If you do not know something off hand, you do not know it without having to ask someone else or look it up in a book.","ex":{"en":"I can't think of any off hand.","cn":"我现在一个也想不出来。"}},{"pos":"PHRASE 短语","cn":"由…负责/不再由…负责","en":"If you have a problem or responsibility on your hands, you have to deal with it. If it is off your hands, you no longer have to deal with it.","ex":{"en":"They now have yet another drug problem on their hands","cn":"他们现在又有个吸毒问题需要解决。"}},{"pos":"PHRASE 短语","cn":"在手头;在近处;现有","en":"If someone or something is on hand, they are near and able to be used if they are needed.","ex":{"en":"The Bridal Department will have experts on hand to give you all the help and advice you need","cn":"婚礼用品部会有现成的专家为您提供所需的一切帮助和建议。"}},{"pos":"PHRASE 短语","cn":"一方面…（另一方面…）","en":"You use on the one hand to introduce the first of two contrasting points, facts, or ways of looking at something. It is always followed later by on the other hand or 'on the other'.","ex":{"en":"On the one hand, if the body doesn't have enough cholesterol, we would not be able to survive. On the other hand, if the body has too much cholesterol, the excess begins to line the arteries.","cn":"一方面，如果体内没有足够的胆固醇，我们就无法存活下去。另一方面，如果体内胆固醇过高，多余的胆固醇就会附着在动脉内壁上。"}},{"pos":"PHRASE 短语","cn":"（从）另一方面（来说）（用于引出相对照的另一点）","en":"You use on the other hand to introduce the second of two contrasting points, facts, or ways of looking at something.","ex":{"en":"Well, all right, hospitals lose money. But, on the other hand, if people are healthy, don't think of it as losing money; think of it as saving lives.","cn":"嗯，好吧，医院是赔钱。但从另一个角度看，如果人们都健健康康的，就不能认为是在赔钱，而应该想成是在救死扶伤。"}},{"pos":"PHRASE 短语","cn":"失去控制;不可收拾","en":"If a person or a situation gets out of hand, you are no longer able to control them.","ex":{"en":"His drinking had got out of hand.","cn":"他酗酒的恶习已无法控制。"}},{"pos":"PHRASE 短语","cn":"立即，不假思索地（屏弃、拒绝等）","en":"If you dismiss or reject something out of hand, you do so immediately and do not consider believing or accepting it.","ex":{"en":"I initially dismissed the idea out of hand.","cn":"我起初不假思索地就否定了这个想法。"}},{"pos":"PHRASE 短语","cn":"因失算而让…占便宜;做对…有利的事","en":"If you play into someone's hands, you do something which they want you to do and which places you in their power.","ex":{"en":"He is playing into the hands of racists.","cn":"他这样做正中种族主义分子的下怀。"}},{"pos":"PHRASE 短语","cn":"摊牌;亮出底牌;表明自己的真实意图","en":"If you show your hand, you show how much power you have and the way you intend to act.","ex":{"en":"He has grown more serious about running for president, although he refuses to show his hand.","cn":"尽管他拒绝亮出自己的底牌，他对竞选总统一事却越来越认真了。"}},{"pos":"PHRASE 短语","cn":"（尤指为有所改善）接手，照管，担任起对…的责任","en":"If you take something or someone in hand, you take control or responsibility over them, especially in order to improve them.","ex":{"en":"I hope that Parliament will soon take the NHS in hand","cn":"我希望议会能很快接管国民医疗保健系统。"}},{"pos":"PHRASE 短语","cn":"（因愤怒、绝望或厌恶而）骤然举起双手","en":"If someone throws up their hands, they express their anger, frustration, or disgust when a situation becomes so bad that they can no longer accept it.","ex":{"en":"She threw up her hands in despair","cn":"她绝望地举起双手表示放弃。"}},{"pos":"PHRASE 短语","cn":"受到束缚;放不开手脚","en":"If you say that your hands are tied, you mean that something is preventing you from acting in the way that you want to.","ex":{"en":"Politicians are always saying that they want to help us but their hands are tied","cn":"政客们总是说想帮助我们，但却身不由己。"}},{"pos":"PHRASE 短语","cn":"在手边;在附近","en":"If you have something to hand or near to hand, you have it with you or near you, ready to use when needed.","ex":{"en":"You may want to keep this brochure safe, so you have it to hand whenever you may need it.","cn":"你应该保管好这份手册，这样随时想用都能马上在手边找到。"}},{"pos":"PHRASE 短语","cn":"（通常指初次）尝试，试身手","en":"If you try your hand at an activity, you attempt to do it, usually for the first time.","ex":{"en":"After he left school, he tried his hand at a variety of jobs—bricklayer, cinema usher, coal man.","cn":"离开学校后，他尝试过各种工作，如泥瓦匠、电影院引座员、运煤工。"}},{"pos":"PHRASE 短语","cn":"着手学做","en":"If you turn your hand to something such as a practical activity, you learn about it and do it for the first time.","ex":{"en":"...a person who can turn his hand to anything.","cn":"什么事都能学着做的人"}},{"pos":"PHRASE 短语","cn":"洗手不干;不再管;和…断绝关系","en":"If you wash your hands of someone or something, you refuse to be involved with them any more or to take responsibility for them.","ex":{"en":"He seems to have washed his hands of the job.","cn":"那份工作他好像已经洗手不干了。"}},{"pos":"PHRASE 短语","cn":"轻易取胜","en":"If you win hands down, you win very easily."},{"pos":"See also:","cn":"","en":"with one's bare hands→see: ; to overplay one's hand→see: ; to shake someone's hand→see: ; to shake hands→see: ;"},{"pos":"VERB 动词","cn":"递;交;给","en":"If you hand something to someone, you pass it to them.","ex":{"en":"He handed me a little rectangle of white paper","cn":"他递给我一张小小的长方形白纸片。"}},{"pos":"PHRASE 短语","cn":"你不得不佩服…","en":"You say things such as 'You have to hand it to her' or 'You've got to hand it to them' when you admire someone for their skills or achievements and you think they deserve a lot of praise.","ex":{"en":"You've got to hand it to Melissa, she certainly gets around.","cn":"你不得不佩服梅利莎，她到哪里都吃得开。"}},{"pos":"","cn":"","en":"相关词组：hand around hand back hand down hand in hand on hand out hand over hand round"}]},"examples":[{"en":"On the one hand they'd love to have kids, but on the other, they don't want to give up their freedom.","cn":"一方面，他们想要孩子，但另一方面，他们又不想放弃自由自在的生活。"},{"en":"The property is ideally located with all local amenities close at hand.","cn":"这处房地产的位置很理想，离当地的福利设施都近。"}]},"hanging":{"media":{"uk":"media/uk/hanging__gb_1.mp3","us":"media/us/hanging__us_1.mp3"},"oxford":{"phon":"ˈhæŋɪŋ","pos":"noun","senses":[{"en":"the practice of killing somebody as a punishment by tying a rope around their neck and allowing them to drop from a high place; an occasion when this happens","cn":"绞死；绞刑","g":"[uncountable, countable]","ex":{"en":"to sentence somebody to death by hanging","cn":"判处某人绞刑"}},{"en":"a large piece of material that is hung on a wall or around a bed for decoration","cn":"墙幔；床幔；帷幔","g":"[countable, usually plural]","ex":{"en":"wall hangings","cn":"挂在墙上的装饰织物"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（作装饰的）壁挂，墙幔，帷幔","en":"A hanging is a large piece of cloth that you put as a decoration on a wall.","ex":{"en":"...a giant antique embroidered hanging.","cn":"巨幅古董刺绣壁挂"}}]},"examples":[{"en":"to sentence sb to death by hanging","cn":"判处某人绞刑"},{"en":"wall hangings","cn":"挂在墙上的装饰织物"}],"base":"hang"},"helplessly":{"oxford":{"phon":"ˈhelpləsli","pos":"adverb","senses":[{"en":"in a way that shows that you are unable to do anything in a particular situation","cn":"无助：以某种方式表明您无法在特定情况下执行任何操作","ex":{"en":"They watched helplessly as their home went up in flames.","cn":"他们无助地看着自己的房子被大火吞噬。"}},{"en":"in a way that shows that you are unable to control a strong feeling","cn":"无法抑制的","ex":{"en":"Both sisters started to laugh helplessly.","cn":"姐妹俩都无奈地笑起来。"}}]},"media":{"uk":"media/uk/helplessly__gb_1.mp3","us":"media/us/helplessly__us_1.mp3"},"examples":[{"en":"They watched helplessly as their home went up in flames.","cn":"他们无奈地看着自己的家被大火吞没。"},{"en":"He began to feel depressed and helpless.","cn":""}]},"height":{"media":{"uk":"media/uk/height__gb_1.mp3","us":"media/us/height__us_1.mp3"},"oxford":{"phon":"haɪt","pos":"noun","senses":[{"en":"the measurement of how tall a person or thing is","cn":"（人或物的）身高，高度","g":"[uncountable, countable]","sc":"measurement","ex":{"en":"Height: 210 mm. Width: 57 mm. Length: 170 mm.","cn":"高：210 毫米；宽：57 毫米；长：170 毫米。"}},{"en":"the quality of being tall or high","cn":"高","g":"[uncountable]","sc":"being tall","ex":{"en":"The height of the mountain did not discourage them.","cn":"山高并没有使他们泄气。"}},{"en":"a particular distance above the ground","cn":"高度","g":"[countable, uncountable]","sc":"distance above ground","ex":{"en":"The aircraft was gaining height.","cn":"飞机在爬高。"}},{"en":"a high place or position","cn":"高地；高处；高位","g":"[countable, usually plural]","sc":"high place","ex":{"en":"Brooklyn Heights","cn":"布鲁克林高地"}},{"en":"the point when something is at its strongest or best","cn":"最强点；最佳点；顶点","g":"[singular]","sc":"strongest point/level","ex":{"en":"The fire reached its height around 2 a.m.","cn":"大火在半夜两点钟左右烧得最猛。"}},{"en":"a better or greater level of something; a situation where something is very good","cn":"更好；更高水平；极佳状况","g":"[plural]","sc":"strongest point/level","ex":{"en":"Their success had reached new heights.","cn":"他们的成就达到新高水平。"}},{"en":"an extreme example of a particular quality","cn":"极端；极度","g":"[singular]","sc":"extreme example","ex":{"en":"It would be the height of folly (= very stupid) to change course now.","cn":"现在改变方向可谓愚蠢至极。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（从底到顶的）身高;高度","en":"The height of a person or thing is their size or length from the bottom to the top.","ex":{"en":"Her weight is about normal for her height","cn":"按她的身高，她的体重基本正常。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"高","en":"Height is the quality of being tall.","ex":{"en":"She admits that her height is intimidating for some men.","cn":"她承认自己的高个头会令有些男人却步。"}},{"pos":"N-VAR 可变名词","cn":"（距离地面或他物的某一）高度","en":"A particular height is the distance that something is above the ground or above something else mentioned.","ex":{"en":"At the speed and height at which he was moving, he was never more than half a second from disaster.","cn":"以这样的速度在这么高的地方移动，他离灾难始终只有半步之遥。"}},{"pos":"N-COUNT 可数名词","cn":"高处;高地","en":"A height is a high position or place above the ground.","ex":{"en":"From a height, it looks like a desert","cn":"从高处看，它像一片沙漠。"}},{"pos":"N-SING 单数名词","cn":"处于顶峰;处于高潮","en":"When an activity, situation, or organization is at its height, it is at its most successful, powerful, or intense.","ex":{"en":"During the early sixth century emigration from Britain to Brittany was at its height","cn":"6世纪初，从不列颠涌向布列塔尼的移民潮达到了高峰。"}},{"pos":"N-SING 单数名词","cn":"（某一特性）的极致","en":"If you say that something is the height of a particular quality, you are emphasizing that it has that quality to the greatest degree possible.","ex":{"en":"The hip-hugging black and white polka-dot dress was the height of fashion","cn":"黑白圆点花纹的紧身连衣裙当时是最时尚的。"}},{"pos":"N-PLURAL 复数名词","cn":"极度;极点","en":"If something reaches great heights, it becomes very extreme or intense.","ex":{"en":"...the mid-1980s, when house prices rose to absurd heights","cn":"房价高得离谱的20世纪80年代中期"}}]},"examples":[{"en":"Height: 210 mm. Width: 57 mm. Length: 170 mm.","cn":"高：210 毫米；宽：57 毫米；长：170 毫米。"},{"en":"We looked out over the city from the heights of Edinburgh Castle.","cn":"我们从爱丁堡城堡所在的高处俯视整个城市。"}]},"humour":{"oxford":{"phon":"ˈhjuːmə(r)","pos":"noun","senses":[{"en":"the quality in something that makes it funny; the ability to laugh at things that are funny","cn":"幽默；幽默感","g":"[uncountable]","ex":{"en":"It was a story full of gentle humour.","cn":"这是一个充满温柔幽默的故事。"}},{"en":"the state of your feelings or mind at a particular time","cn":"感觉；心情；精神状态","g":"[countable, uncountable]","lab":"formal","ex":{"en":"to be in the best of humours","cn":"情绪极好"}},{"en":"one of the four liquids that were thought in the past to be in a person’s body and to influence health and character","cn":"体液（旧时认为存在人体内，有四种，可影响健康和性格）","g":"[countable]","lab":"old use"},{"en":"to agree with somebody’s wishes, even if they seem unreasonable, in order to keep the person happy","cn":"迁就；顺应","ex":{"en":"She thought it best to humour him rather than get into an argument.","cn":"她想最好是顺他的意，而不是和他争吵。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"幽默的谈吐;笑话","en":"You can refer to the amusing things that people say as their humour .","ex":{"en":"Her humour and determination were a source of inspiration to others.","cn":"她的幽默言谈和坚定决心对其他人来说是一种鼓舞。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"幽默;诙谐;滑稽","en":"Humour is a quality in something that makes you laugh, for example in a situation, in someone's words or actions, or in a book or film.","ex":{"en":"She felt sorry for the man but couldn't ignore the humour of the situation.","cn":"她很同情这个男人，但这一情景又让她忍俊不禁。"}},{"pos":"N-VAR 可变名词","cn":"心情;情绪","en":"If you are in a good humour, you feel cheerful and happy, and are pleasant to people. If you are in a bad humour, you feel bad-tempered and unhappy, and are unpleasant to people.","ex":{"en":"Christina was still not clear why he had been in such ill humour","cn":"克里斯蒂娜仍搞不清楚为什么他情绪这么差。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"精神状态","en":"If you do something with good humour, you do it cheerfully and pleasantly.","ex":{"en":"Hugo bore his illness with great courage and good humour.","cn":"雨果以巨大的勇气和良好的精神状态面对疾病。"}},{"pos":"VERB 动词","cn":"迁就;迎合","en":"If you humour someone who is behaving strangely, you try to please them or pretend to agree with them, so that they will not become upset.","ex":{"en":"She disliked Dido but was prepared to tolerate her for a weekend in order to humour her husband.","cn":"她不喜欢迪多，但准备暂时忍受她一个周末，以迁就自己的丈夫。"}}]},"media":{"uk":"media/uk/humour__gb_1.mp3","us":"media/us/humour__us_1.mp3"},"examples":[{"en":"The film is only funny if you appreciate French humour (= things that cause French people to laugh).","cn":"只有能理解法国式的幽默才会领略这部电影的趣味。"},{"en":"She thought it best to humour him rather than get into an argument.","cn":"她想最好是顺他的意，而不和他争吵。"}]},"hideously":{"media":{"uk":"media/uk/hideously__gb_1.mp3","us":"media/us/hideously__us_1.mp3"},"collins":{"senses":[{"pos":"ADV 副词","cn":"可怕地;丑陋地","en":"You use hideously to emphasize that something is very ugly or unattractive.","ex":{"en":"Everything is hideously ugly","cn":"一切都非常丑陋。"}},{"pos":"ADV-GRADED 副词","cn":"令人无法接受地;极其恶劣地","en":"You can use hideously to emphasize that something is very unpleasant or unacceptable.","ex":{"en":"...a hideously complex program.","cn":"极其复杂的程序"}}]},"examples":[{"en":"His face was hideously deformed.","cn":"他的脸严重变形。"},{"en":"Dinnertime that day was hideous.","cn":""}],"oxford":{"phon":"ˈhɪdiəsli","pos":"adverb","senses":[{"en":"in a very ugly or unpleasant way","cn":"十分丑陋的；令人厌恶的","ex":{"en":"His face was hideously deformed.","cn":"他的脸严重变形，十分可怕。"}}]}},"happy":{"media":{"uk":"media/uk/happy__gb_1.mp3","us":"media/us/happy__us_1.mp3"},"oxford":{"phon":"ˈhæpi","pos":"adjective","senses":[{"en":"feeling or showing pleasure; pleased","cn":"感到（或显得）快乐的；高兴的","sc":"feeling/giving pleasure","ex":{"en":"a happy family","cn":"幸福的家庭"}},{"en":"giving or causing pleasure","cn":"给予（或带来）快乐的；使人高兴的；幸福的","sc":"feeling/giving pleasure","ex":{"en":"She had a very happy life.","cn":"她有过非常幸福的生活。"}},{"en":"if you wish somebody a Happy Birthday, Happy New Year, etc. you mean that you hope they have a pleasant celebration","cn":"（表示祝愿，如 Happy Birthday 生日快乐、Happy New Year 新年好等）","sc":"at celebration"},{"en":"satisfied that something is good or right; not anxious","cn":"（对事物）满意的，放心的","sc":"satisfied","ex":{"en":"I don't know what you've done, but the boss isn't happy.","cn":"我不知道你做了什么，但老板不高兴。"}},{"en":"willing or pleased to do something","cn":"情愿，乐意（做某事）","lab":"formal","sc":"willing","ex":{"en":"I'm perfectly happy to leave it till tomorrow.","cn":"我非常愿意把它留到明天再做。"}},{"en":"lucky; successful","cn":"幸运的；成功的","sc":"lucky","ex":{"en":"By a happy coincidence, we arrived at exactly the same time.","cn":"碰巧运气好，我们恰恰同时到达。"}},{"en":"suitable and appropriate for a particular situation","cn":"合适的；恰当的","lab":"formal","sc":"suitable","ex":{"en":"That wasn't the happiest choice of words.","cn":"那样的措辞并不是十分恰当。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高兴的;快乐的","en":"Someone who is happy has feelings of pleasure, usually because something nice has happened or because they feel satisfied with their life.","ex":{"en":"Marina was a confident, happy child","cn":"玛丽娜是个自信、快乐的孩子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（时光、地点或关系）令人愉快的，幸福的","en":"A happy time, place, or relationship is full of happy feelings and pleasant experiences, or has an atmosphere in which people feel happy.","ex":{"en":"Except for her illnesses, she had had a particularly happy childhood","cn":"除了体弱多病外，她的童年特别幸福。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对情况或安排）满意的，放心的","en":"If you are happy about a situation or arrangement, you are satisfied with it, for example because you think that something is being done in the right way.","ex":{"en":"If you are not happy about a repair, go back and complain","cn":"如果你对修理效果不满意，可以再找他们投诉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐意的;情愿的","en":"If you say you are happy to do something, you mean that you are very willing to do it.","ex":{"en":"I'll be happy to answer any questions if there are any","cn":"如果有问题，我很乐意回答。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表示祝福）…快乐","en":"Happy is used in greetings and other conventional expressions to say that you hope someone will enjoy a special occasion. many happy returns→see: ;","ex":{"en":"Happy Birthday!","cn":"生日快乐！"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（巧合）幸运的，令人愉快的","en":"A happy coincidence is one that results in something pleasant or helpful happening.","ex":{"en":"By happy coincidence, Robert met Richard and Julia and discovered they were experiencing similar problems.","cn":"幸运的是，罗伯特碰巧遇到了理查德和朱莉娅，发现原来他们也碰到了类似的问题。"}}]},"examples":[{"en":"We are happy to announce the engagement of our daughter.","cn":"我们高兴地宣布，我们的女儿已订婚。"},{"en":"If there's anything you're not happy about, come and ask.","cn":"你如果有什么不满意的，来说一声。"}]},"harden":{"oxford":{"phon":"ˈhɑːdn","pos":"verb","senses":[{"en":"to become or make something become solid or stiff","cn":"（使）变硬，硬化","g":"[intransitive, transitive]","ex":{"en":"The varnish takes a few hours to harden.","cn":"清漆需要几个小时才能干透。"}},{"en":"if your voice, face, etc. hardens, or you harden it, it becomes more serious or severe","cn":"（使声音、面孔等）更严肃，更严厉","g":"[intransitive, transitive]","ex":{"en":"Her face hardened into an expression of hatred.","cn":"她的脸沉下来，面带恨意。"}},{"en":"if somebody’s feelings or attitudes harden or somebody/something hardens them, they become more fixed and determined","cn":"（使）更坚定，更强硬","g":"[intransitive, transitive]","ex":{"en":"Public attitudes to the strike have hardened.","cn":"公众对这次罢工所持的态度已强硬起来。"}},{"en":"to make somebody less kind or less affected by extreme situations","cn":"使变得无情；使不被打动","g":"[transitive]","ex":{"en":"Joe sounded different, hardened by the war.","cn":"乔让人觉得他变了，因战争变得冷酷无情了。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）变硬;（使）硬化","en":"When something hardens or when you harden it, it becomes stiff or firm.","ex":{"en":"Mould the mixture into shape while hot, before it hardens","cn":"在混合物还没有变硬之前，趁热将它塑成形。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（态度、想法）变得更坚定;（使）变得更强硬","en":"When an attitude or opinion hardens or is hardened, it becomes harsher, stronger, or fixed.","ex":{"en":"Their action can only serve to harden the attitude of landowners","cn":"他们的行动只会让土地拥有者的态度变得更坚定。"}},{"pos":"VERB 动词","cn":"（价格、经济）变得更稳定","en":"When prices and economies harden, they become much more stable than they were.","ex":{"en":"Property prices are just beginning to harden again.","cn":"房地产价格刚开始重新趋于稳定。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）变得坚强;（使）变得冷酷无情;（使）变得麻木不仁","en":"When events harden people or when people harden, they become less easily affected emotionally and less sympathetic and gentle than they were before.","ex":{"en":"Her years of drunken bickering hardened my heart","cn":"她多年来醉酒寻衅的恶习让我变得麻木。"}},{"pos":"VERB 动词","cn":"（表情、眼神）变得严肃，变得不快","en":"If you say that someone's face or eyes harden, you mean that they suddenly look serious or angry.","ex":{"en":"His smile died and the look in his face hardened.","cn":"他的笑容消失了，脸上的表情严肃了起来。"}}]},"media":{"uk":"media/uk/harden__gb_1.mp3","us":"media/us/harden__us_1.mp3"},"examples":[{"en":"In this job you have to harden your heart to pain and suffering.","cn":"做这项工作面对伤痛和病患时你得保持沉着冷静。"},{"en":"Joe sounded different, hardened by the war.","cn":"乔让人觉得变了，因战争变得冷酷无情了。"}]},"hire":{"media":{"uk":"media/uk/hire__gb_1.mp3","us":"media/us/hire__us_1.mp3"},"oxford":{"phon":"ˈhaɪə(r)","pos":"verb","senses":[{"en":"to give somebody a job","cn":"聘用；录用；雇用","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"She was hired three years ago.","cn":"她是三年前录用的。"}},{"en":"to employ somebody for a short time to do a particular job","cn":"临时雇用","g":"[transitive]","ex":{"en":"to hire a lawyer/detective","cn":"聘请律师；雇用侦探"}},{"en":"to pay money to borrow something for a short time","cn":"租用；租借","g":"[transitive]","lab":"especially British English","ex":{"en":"to hire a room/studio","cn":"租房间；租工作室"}},{"en":"the act of paying to use something for a short time","cn":"租借；租用；租赁","g":"[uncountable]","lab":"especially British English","ex":{"en":"a hire car","cn":"供租用的汽车"},"pos":"noun"},{"en":"a person who has recently been given a job by a company","cn":"新雇员；新员工","g":"[countable]","lab":"especially North American English","ex":{"en":"New hires get raises after a set period of time.","cn":"新雇用的人在规定时间以后可获晋升。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"雇用","en":"If you hire someone, you employ them or pay them to do a particular job for you.","ex":{"en":"Sixteen of the contestants have hired lawyers and are suing the organisers","cn":"有16名参赛者已经请了律师，正在起诉主办方。"}},{"pos":"VERB 动词","cn":"（短期）租用","en":"If you hire something, you pay money to the owner so that you can use it for a period of time.","ex":{"en":"To hire a car you must produce a passport and a current driving licence","cn":"租车须出示护照及有效驾照。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"租赁（业）;出租（业务）","en":"You use hire to refer to the activity or business of hiring something.","ex":{"en":"They booked our hotel, and organised car hire","cn":"他们为我们订好了旅馆并安排了租车事宜。"}},{"pos":"PHRASE 短语","cn":"供出租;待租","en":"If something is for hire, it is available for you to hire.","ex":{"en":"Fishing tackle is available for hire.","cn":"有钓具可供出租。"}},{"pos":"","cn":"","en":"相关词组：hire out"}]},"examples":[{"en":"They hired a firm of consultants to design the new system.","cn":"他们请了一家咨询公司来设计新的系统。"},{"en":"He does the hiring and firing in our company.","cn":"他在我们公司负责员工的聘用和辞退。"}]},"handle":{"oxford":{"phon":"ˈhændl","pos":"verb","senses":[{"en":"to deal with a situation, a person, an area of work or a strong emotion","cn":"处理，应付（局势、人、工作或感情）","g":"[transitive]","lab":"informal","sc":"deal with","ex":{"en":"A new man was appointed to handle the crisis.","cn":"新指派了一个人来处理这场危机。"}},{"en":"to touch, hold or move something with your hands","cn":"（用手）触，拿，搬动","g":"[transitive]","sc":"touch with hands","ex":{"en":"Our cat hates being handled.","cn":"我们的猫不喜欢被人摸弄。"}},{"en":"to control a vehicle, an animal, a tool, etc.","cn":"控制，操纵（车辆、动物、工具等）","g":"[transitive]","sc":"control","ex":{"en":"I wasn't sure if I could handle such a powerful car.","cn":"我没有把握是否能驾驶功率这样大的车。"}},{"en":"to be easy/difficult to drive or control","cn":"（容易／难以）驾驶，操纵","g":"[intransitive]","sc":"control","ex":{"en":"The car handles well in any weather.","cn":"这辆车在任何天气下开起来都很灵便。"}},{"en":"to buy or sell something","cn":"买；卖","g":"[transitive]","sc":"buy/sell","ex":{"en":"They were arrested for handling stolen goods.","cn":"他们因收售赃物而遭逮捕。"}},{"en":"the part of a door, window, etc. that you use to open it","cn":"把手；拉手","sc":"of door/window","ex":{"en":"She turned the handle and opened the door.","cn":"她转动把手，打开了门。"},"pos":"noun"},{"en":"the part of an object, such as a cup, a bag or a tool, that you use to hold it or carry it","cn":"柄；把；提梁；把手","sc":"of cup/bag/tool","ex":{"en":"the handle of a knife","cn":"刀柄"},"pos":"noun"},{"en":"having the number or type of handle mentioned","cn":"有…个柄的；有…柄的","sc":"-handled","ex":{"en":"a long-handled spoon","cn":"一把长柄匙"},"pos":"noun"},{"en":"a name or nickname","cn":"名字；绰号","sc":"name","pos":"noun"},{"en":"a person's username on a social media site or online forum","cn":"（在社交媒体或网络论坛上的）用户名，网名","sc":"name","ex":{"en":"I added my handle at the top of my blog page so that readers could view my tweets as well as my blog posts.","cn":"我在我的博客页面顶部添加了推特账号，这样读者既能看到我的博客帖子，又可以查看我在推特发送的信息。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（门上的）拉手，把手","en":"A handle is a small round object or a lever that is attached to a door and is used for opening and closing it.","ex":{"en":"I turned the handle and found the door was open.","cn":"我转了一下门把手，发现门开着。"}},{"pos":"N-COUNT 可数名词","cn":"（工具、包、杯等的）柄，把手，提手","en":"A handle is the part of an object such as a tool, bag, or cup that you hold in order to be able to pick up and use the object.","ex":{"en":"The handle of a cricket bat protruded from under his arm.","cn":"一个板球拍柄从他的胳肢窝下面伸了出来。"}},{"pos":"VERB 动词","cn":"有能力应付;（成功地）处理","en":"If you say that someone can handle a problem or situation, you mean that they have the ability to deal with it successfully.","ex":{"en":"To tell the truth, I don't know if I can handle the job","cn":"说实话，我不知道自己是否能做好这份工作。"}},{"pos":"VERB 动词","cn":"（以…方式）应付，处理","en":"If you talk about the way that someone handles a problem or situation, you mention whether or not they are successful in achieving the result they want.","ex":{"en":"I think I would handle a meeting with Mr. Siegel very badly","cn":"我觉得和西格尔先生会谈我可能会搞得一团糟。"}},{"pos":"VERB 动词","cn":"负责（某项工作）","en":"If you handle a particular area of work, you have responsibility for it.","ex":{"en":"She handled travel arrangements for the press corps during the presidential campaign","cn":"她负责了总统竞选活动期间新闻报道团的行程安排。"}},{"pos":"VERB 动词","cn":"使用，操纵（武器、车辆等）;训练，使唤（动物）","en":"When you handle something such as a weapon, vehicle, or animal, you use it or control it, especially by using your hands.","ex":{"en":"I had never handled an automatic.","cn":"我从未用过自动手枪。"}},{"pos":"VERB 动词","cn":"（车辆等容易）操纵，驾驶","en":"If something such as a vehicle handles well, it is easy to use or control.","ex":{"en":"His ship had handled like a dream!","cn":"他的船操纵起来非常灵便。"}},{"pos":"VERB 动词","cn":"拿;抓;搬动","en":"When you handle something, you hold it or move it with your hands.","ex":{"en":"Wear rubber gloves when handling cat litter.","cn":"清理猫粪时要带上橡胶手套。"}},{"pos":"N-SING 单数名词","cn":"（理解、解决问题的）方法，途径","en":"If you have a handle on a subject or problem, you have a way of approaching it that helps you to understand it or deal with it.","ex":{"en":"When you have got a handle on your anxiety you can begin to control it.","cn":"一旦了解了自己焦虑的原因，你就开始能控制它了。"}},{"pos":"PHRASE 短语","cn":"大发脾气;勃然大怒","en":"If you fly off the handle, you suddenly and completely lose your temper.","ex":{"en":"He flew off the handle at the slightest thing.","cn":"他为一点小事就大发脾气。"}}]},"media":{"img":["media/pic/handle_comp.jpg","media/thumb/handle.jpg"],"uk":"media/uk/handle__gb_1.mp3","us":"media/us/handle__us_1.mp3"},"examples":[{"en":"We can handle up to 500 calls an hour at our new offices.","cn":"我们的新办公室每小时可处理 500 通电话。"},{"en":"( informal ) ‘Any problems?’ ‘Nothing I can't handle. ’ “","cn":"有问题吗？” “没有什么我不能对付的。”"}]},"harlequin":{"media":{"uk":"media/uk/harlequin__gb_1.mp3","us":"media/us/harlequin__us_1.mp3"},"oxford":{"phon":"ˈhɑːləkwɪn","pos":"noun","senses":[{"en":"a humorous character in some traditional plays, who wears special brightly coloured clothes with a diamond pattern","cn":"（传统戏剧中穿色彩斑斓菱形花纹服装的）滑稽角色"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（常为菱形图案组成的）五颜六色的","en":"You use harlequin to describe something that has a lot of different colours, often in a diamond pattern.","ex":{"en":"...the striking harlequin floor.","cn":"醒目的彩色地板"}}]}},"hearing":{"oxford":{"phon":"ˈhɪərɪŋ","pos":"noun","senses":[{"en":"the ability to hear","cn":"听力；听觉","g":"[uncountable]","ex":{"en":"Her hearing is poor.","cn":"她的听觉不灵。"}},{"en":"an official meeting at which the facts about a crime, complaint, etc. are presented to the person or group of people who will have to decide what action to take","cn":"审讯；审理；听审；听证会","g":"[countable]","lab":"especially North American English","ex":{"en":"a court/disciplinary hearing","cn":"庭审；纪律聆讯"}},{"en":"an opportunity to explain your actions, ideas or opinions","cn":"（行为、思想或意见的）解释机会，申辩机会","g":"[singular]","ex":{"en":"to get/give somebody a fair hearing","cn":"得到／给予某人公正的申辩机会"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"听觉;听力","en":"A person's or animal's hearing is the sense which makes it possible for them to be aware of sounds.","ex":{"en":"His mind still seemed clear and his hearing was excellent.","cn":"他的头脑似乎还清楚，听觉也很好。"}},{"pos":"N-COUNT 可数名词","cn":"听证会;听审;聆讯","en":"A hearing is an official meeting which is held in order to collect facts about an incident or problem.","ex":{"en":"The judge adjourned the hearing until next Tuesday.","cn":"法官宣布休庭至下周二再审。"}},{"pos":"PHRASE 短语","cn":"发表意见的机会","en":"If someone gives you a fair hearing or a hearing, they listen to you when you give your opinion about something.","ex":{"en":"Weber gave a fair hearing to anyone who held a different opinion.","cn":"韦伯让持不同意见的人都能有机会发表意见。"}},{"pos":"PHRASE 短语","cn":"在…听力所及的范围内","en":"If someone says something in your hearing or within your hearing, you can hear what they say because they are with you or near you.","ex":{"en":"No one spoke disparagingly of her father in her hearing.","cn":"没有人在她跟前说过她父亲的坏话。"}}]},"media":{"uk":"media/uk/hearing__gb_1.mp3","us":"media/us/hearing__us_1.mp3"},"examples":[{"en":"His views may be unfashionable but he deserves a hearing.","cn":"他的观点可能不合潮流，但应该给他机会解释。"},{"en":"to get/give sb a fair hearing","cn":"得到/给予某人公正的申辩机会"}],"base":"hear"},"history":{"media":{"uk":"media/uk/history__gb_1.mp3","us":"media/us/history__us_1.mp3"},"oxford":{"phon":"ˈhɪstri","pos":"noun","senses":[{"en":"all the events that happened in the past","cn":"历史（指过去发生的所有事情）","g":"[uncountable]","ex":{"en":"The battle was a turning point in human history.","cn":"这场战役是人类历史的转折点。"}},{"en":"the past events connected with the development of a particular place, subject, etc.","cn":"（有关某个地方、主题等的）发展史，历史","g":"[singular, uncountable]","ex":{"en":"the history of science/music/philosophy","cn":"科学史；音乐史；哲学史"}},{"en":"the study of past events, especially as a subject at school or university","cn":"历史课；历史学","g":"[uncountable]","ex":{"en":"a history professor/teacher","cn":"历史教授／老师"}},{"en":"a written or spoken account of real past events","cn":"历史（指真实历史事件的记载或口述）","g":"[countable, uncountable]","ex":{"en":"She's writing a new history of Europe.","cn":"她正在写一部新的欧洲史。"}},{"en":"the set of facts that are known about somebody/something's past","cn":"（某人的）过往事迹；（某事物的）来历，沿革","g":"[countable]","ex":{"en":"I know nothing about his personal history.","cn":"我对他的个人历史一无所知。"}},{"en":"a record of something happening frequently in the past life of a person, family or place","cn":"个人经历；家族史；地方志","g":"[countable, usually singular]","ex":{"en":"He has a history of violent crime.","cn":"他有暴力犯罪的前科。"}},{"en":"a record kept by a web browser of the web pages and other files it has been used to access","cn":"（网页浏览和文件读取的）历史记录","g":"[uncountable]","ex":{"en":"Clearing your browser history prevents websites from following and tracking your actions.","cn":"清除浏览器历史记录可防止网站跟踪你的活动。"}},{"en":"a relationship between two people, groups, companies, etc. that started in the past and continued for a period of time, especially one involving bad or complicated feelings","cn":"纠葛关系；旧怨；过节","g":"[uncountable, singular]","ex":{"en":"Sure there's history between Anna Mae and me, like you said.","cn":"当然，我和安娜·梅之间有过节，就像你说的。"}},{"en":"a historical play","cn":"历史剧","g":"[countable]","ex":{"en":"Shakespeare's comedies, histories and tragedies","cn":"莎士比亚的喜剧、历史剧和悲剧"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"历史","en":"You can refer to the events of the past as history. You can also refer to the past events which concern a particular topic or place as its history.","ex":{"en":"The Catholic Church has played a prominent role throughout Polish history.","cn":"天主教会在整个波兰历史上曾发挥过举足轻重的作用。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"历史学;史学","en":"History is a subject studied in schools, colleges, and universities that deals with events that have happened in the past."},{"pos":"N-COUNT 可数名词","cn":"过去事件的记载;发展史","en":"A history is an account of events that have happened in the past.","ex":{"en":"...his magnificent history of broadcasting in Canada.","cn":"他在加拿大辉煌的播音史"}},{"pos":"N-COUNT 可数名词","cn":"记录;习惯;（某地的）沿革","en":"If a person or a place has a history of something, it has been very common or has happened frequently in their past.","ex":{"en":"He had a history of drink problems","cn":"他过去酗酒度日。"}},{"pos":"N-COUNT 可数名词","cn":"履历;经历","en":"Someone's history is the set of facts that are known about their past.","ex":{"en":"He couldn't get a new job because of his medical history.","cn":"由于他的病史，他无法找到新的工作。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"历史的陈迹;（无关紧要的）往事","en":"If you say that an event, thing, or person is history, you mean that they are no longer important.","ex":{"en":"The Charlottetown agreement is history.","cn":"夏洛特敦协定已成为历史。"}},{"pos":"PHRASE 短语","cn":"接下来的事就世人皆知了","en":"If you are telling someone about an event and say the rest is history, you mean that you do not need to tell them what happened next because everyone knows about it already.","ex":{"en":"We met at college, the rest is history.","cn":"我们是在上大学时认识的，接下来的事大家都知道了。"}}]},"examples":[{"en":"The area was inhabited long before the dawn of recorded history (= before people wrote about events).","cn":"早在有历史记载之前很久这个地区就有人居住了。"},{"en":"The school traces its history back to 1865.","cn":"这个学校的历史可以追溯到 1865 年。"}]},"hotel":{"media":{"uk":"media/uk/hotel__gb_1.mp3","us":"media/us/hotel__us_1.mp3"},"oxford":{"phon":"həʊˈtel","pos":"noun","senses":[{"en":"a building where people stay, usually for a short time, paying for their rooms and meals","cn":"旅馆；旅社","lab":"British English","ex":{"en":"a two-star/five-star, etc. hotel","cn":"两星级、五星级等旅馆"}},{"en":"a pub","cn":"酒吧；酒馆","lab":"Australian English, New Zealand English，，"},{"en":"a restaurant","cn":"餐馆","lab":"Indian English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宾馆;旅馆;酒店","en":"A hotel is a building where people stay, for example on holiday, paying for their rooms and meals."}]},"examples":[{"en":"We stayed at/in a hotel.","cn":"我们住在旅馆里。"},{"en":"a friendly, family-run hotel","cn":"一家亲切随和、家庭经营的旅店"}]},"haul":{"media":{"uk":"media/uk/haul__gb_1.mp3","us":"media/us/haul__us_1.mp3"},"oxford":{"phon":"hɔːl","pos":"verb","senses":[{"en":"to pull something/somebody with a lot of effort","cn":"（用力）拖，拉，拽","ex":{"en":"The wagons were hauled by horses.","cn":"那些货车是马拉的。"}},{"en":"to move yourself somewhere slowly and with a lot of effort","cn":"用力缓慢挪动到（某处）","ex":{"en":"She hauled herself out of bed.","cn":"她费劲地下了床。"}},{"en":"to force somebody to go somewhere they do not want to go","cn":"强迫（某人）去某处","ex":{"en":"A number of suspects have been hauled in for questioning.","cn":"一批嫌疑犯被拘捕接受讯问。"}},{"en":"to make somebody appear in court in order to be judged","cn":"使某人出庭受审；把某人提交法庭","g":"[usually passive]","ex":{"en":"He was hauled up before the local magistrates for dangerous driving.","cn":"他因危险驾驶而被移交地方法庭审判。"}},{"en":"a large amount of something that has been stolen or that is illegal","cn":"大批赃物；大量非法物品","ex":{"en":"a haul of weapons","cn":"大批非法武器"},"pos":"noun"},{"en":"a large number of points, goals, etc.","cn":"很高的得分","ex":{"en":"His haul of 40 goals in a season is a record.","cn":"他在一个赛季中得了 40 分，创下了纪录。"},"pos":"noun"},{"en":"the distance covered in a particular journey","cn":"旅行的距离；旅程","g":"[usually singular]","ex":{"en":"They began the long slow haul to the summit.","cn":"他们踏上了攀登顶峰的漫长行程。"},"pos":"noun"},{"en":"a quantity of fish caught at one time","cn":"一次捕获的鱼；一网鱼","ex":{"en":"The fishermen had a good haul.","cn":"渔民捕得满满一网鱼。"},"pos":"noun"},{"en":"a hard pull","cn":"（用力的）拖，拉，拽","g":"[usually singular]","ex":{"en":"When I shout, give a haul on the rope.","cn":"听到我喊就用力拉绳子。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(用力地）拉，拖","en":"If you haul something which is heavy or difficult to move, you move it using a lot of effort.","ex":{"en":"A crane had to be used to haul the car out of the stream","cn":"只好用了起重机，才将轿车从河里拖出来。"}},{"pos":"VERB 动词","cn":"使出庭受审;使去见掌权者","en":"If someone is hauled before a court or someone in authority, they are made to appear before them because they are accused of having done something wrong.","ex":{"en":"She was hauled before magistrates for refusing to reveal her age to a policeman","cn":"她因拒绝告诉警察自己的年龄而被地方法院传讯。"}},{"pos":"N-COUNT 可数名词","cn":"（警方或海关查获的）一批赃物，一批违禁品","en":"A haul is a quantity of things that are stolen, or a quantity of stolen or illegal goods found by police or customs.","ex":{"en":"The size of the drugs haul shows that the international trade in heroin is still flourishing","cn":"本次查获的毒品量表明，海洛因在国际上的交易仍很猖獗。"}},{"pos":"PHRASE 短语","cn":"费时费力的事;耗时累人的行程","en":"If you say that a task or a journey is a long haul, you mean that it takes a long time and a lot of effort.","ex":{"en":"Revitalising the Romanian economy will be a long haul.","cn":"罗马尼亚经济的复兴将是一项长期而艰巨的工作。"}}]},"examples":[{"en":"His haul of 40 goals in a season is a record.","cn":"他在一个赛季中得了 40 分，创下了纪录。"},{"en":"He was hauled up before the local magistrates for dangerous driving.","cn":"他因危险驾驶而被移交地方法庭审判。"}]},"holiday":{"media":{"uk":"media/uk/holiday__gb_1.mp3","us":"media/us/holiday__us_1.mp3"},"oxford":{"phon":"ˈhɒlədeɪ","pos":"noun","senses":[{"en":"a period of time when you are not at work or school","cn":"假期","g":"[uncountable]","lab":"both British English","ex":{"en":"the school/summer/Christmas holidays","cn":"学校假期；暑假；圣诞节假期"}},{"en":"a period of time spent travelling or resting away from home","cn":"度假","g":"[countable]","lab":"British English","ex":{"en":"a camping/skiing/walking holiday","cn":"露营／滑雪／远足度假"}},{"en":"a day when most people do not go to work or school, especially because of a religious or national celebration","cn":"假日，节日（尤指宗教节日或国家庆典日）","g":"[countable]","ex":{"en":"The president's birthday was declared a national holiday.","cn":"总统的生日被定为全国假日。"}},{"en":"the time from late November to early January that includes Thanksgiving, Christmas, Hanukkah and New Year","cn":"节日假期（从十一月底到一月上旬，期间有感恩节、圣诞节、修殿节和新年）","g":"[plural]","lab":"North American English","ex":{"en":"Happy Holidays!","cn":"节日愉快！"}},{"en":"to spend a holiday somewhere","cn":"度假；休假","ex":{"en":"She was holidaying with her family in Ireland.","cn":"她当时正和家人在爱尔兰度假。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（外出度过的）假期","en":"A holiday is a period of time during which you relax and enjoy yourself away from home. People sometimes refer to their holiday as their holidays.","ex":{"en":"I've just come back from a holiday in the United States","cn":"我刚从美国度假回来。"}},{"pos":"N-COUNT 可数名词","cn":"公众假日;节日","en":"A holiday is a day when people do not go to work or school because of a religious or national festival.","ex":{"en":"New Year's Day is a public holiday throughout Britain","cn":"元旦是全英国的公众假日。"}},{"pos":"N-PLURAL 复数名词","cn":"（学校的）假期","en":"The holidays are the time when children do not have to go to school.","ex":{"en":"...the first day of the school holidays.","cn":"学校放假的第一天"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（不上班的）休假期","en":"If you have a particular number of days' or weeks' holiday, you do not have to go to work for that number of days or weeks.","ex":{"en":"Every worker will be entitled to four weeks' paid holiday a year.","cn":"每位工人每年都能享受4周的带薪休假。"}},{"pos":"VERB 动词","cn":"（外出）度假","en":"If you are holidaying in a place away from home, you are on holiday there.","ex":{"en":"Sampling the local cuisine is one of the delights of holidaying abroad","cn":"品尝当地菜肴是海外度假的乐趣之一。"}}]},"examples":[{"en":"The package includes 20 days' paid holiday a year.","cn":"这一揽子福利包括每年 20 天的带薪假。"},{"en":"I'm afraid Mr Walsh is away on holiday this week.","cn":"很抱歉，沃尔什先生这个星期休假去了。"}]},"hostile":{"media":{"uk":"media/uk/hostile__gb_1.mp3","us":"media/us/hostile__us_1.mp3"},"oxford":{"phon":"ˈhɒstaɪl","pos":"adjective","senses":[{"en":"aggressive or unfriendly and ready to argue or fight","cn":"敌意的；敌对的","ex":{"en":"The speaker got a hostile reception from the audience.","cn":"演讲人遭到了听众喝倒彩。"}},{"en":"strongly rejecting something","cn":"坚决否定；强烈反对","ex":{"en":"The proposals have provoked a hostile response from opposition parties.","cn":"这些提案激起了各反对党派的强烈不满。"}},{"en":"making it difficult for something to happen or to be achieved","cn":"有阻碍的；不利的","ex":{"en":"hostile conditions for plants to grow in","cn":"不利于植物生长的环境"}},{"en":"belonging to a military enemy","cn":"敌军的；敌人的","ex":{"en":"hostile territory","cn":"敌方领土"}},{"en":"not wanted by the company that is to be bought","cn":"不受（被购公司）欢迎的；敌意的","lab":"business","ex":{"en":"a hostile takeover bid","cn":"出价敌意收购"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"敌对的;不赞成的","en":"If you are hostile to another person or an idea, you disagree with them or disapprove of them, often showing this in your behaviour.","ex":{"en":"Many people felt he would be hostile to the idea of foreign intervention","cn":"很多人觉得他会反对外国干预的主意。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怀有敌意的;不友善的","en":"Someone who is hostile is unfriendly and aggressive.","ex":{"en":"Drinking may make a person feel relaxed and happy, or it may make her hostile, violent, or depressed","cn":"喝酒可能让人感到放松和愉快，也可能让人变得不友善、暴力或阴郁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情况、形势等）不利的，恶劣的，造成阻碍的","en":"Hostile situations and conditions make it difficult for you to achieve something.","ex":{"en":"...some of the most hostile climatic conditions in the world","cn":"世界上最恶劣的几种气候条件"}},{"pos":"ADJ 形容词","cn":"（收购）恶意的，不受（被购公司）欢迎的","en":"A hostile takeover bid is one that is opposed by the company that is being bid for.","ex":{"en":"Kingfisher launched a hostile bid for Dixons.","cn":"翠丰集团对迪克森公司展开了恶意竞购。"}},{"pos":"ADJ 形容词","cn":"（战争中）敌方的，敌人的","en":"In a war, you use hostile to describe your enemy's forces, organizations, weapons, land, and activities.","ex":{"en":"The city is encircled by a hostile army","cn":"该市被敌军包围了。"}}]},"examples":[{"en":"The speaker got a hostile reception from the audience.","cn":"演讲人遭到了听众喝倒彩。"},{"en":"She was openly hostile towards her parents.","cn":"她公然对抗她的父母。"}]},"halfway":{"media":{"uk":"media/uk/halfway__gb_1.mp3","us":"media/us/halfway__us_1.mp3"},"oxford":{"phon":"ˌhɑːfˈweɪ","pos":"adjective","senses":[{"en":"at an equal distance between two points; in the middle of a period of time","cn":"在…的中间；在中途；到一半","ex":{"en":"I got the ball on the halfway line.","cn":"我在中场线拿到了球。"}},{"en":"part of the way towards doing or achieving something","cn":"部分地做（或达到）…","ex":{"en":"the halfway point/stage","cn":"中间点／阶段"}},{"en":"at an equal distance between two points; in the middle of a period of time","cn":"在…的中间；在中途；到一半","ex":{"en":"It's about halfway between London and Bristol.","cn":"它大约位于伦敦和布里斯托尔的中间。"},"pos":"adverb"},{"en":"part of the way towards doing or achieving something","cn":"部分地做（或达到）…","ex":{"en":"This only goes halfway to explaining what really happened.","cn":"这只是部分地解释了实际发生的事。"},"pos":"adverb"},{"en":"fairly, but not very, good","cn":"还不错的；过得去的","lab":"informal","ex":{"en":"Any halfway decent map will give you that information.","cn":"任何一张还算像样的地图都能提供那些信息。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（空间上）在中间，在中途","en":"Halfway means in the middle of a place or between two points, at an equal distance from each of them.","ex":{"en":"Half-way across the car-park, he noticed she was walking with her eyes closed","cn":"走到停车场中间时，他看到她在闭着眼走路。"}},{"pos":"ADV 副词","cn":"（时间）到一半;（事情）进行到中途","en":"Halfway means in the middle of a period of time or of an event.","ex":{"en":"By then, it was October and we were more than halfway through our tour.","cn":"那时已是10月，我们已经完成了行程的一大半了。"}},{"pos":"PHRASE 短语","cn":"对…作部分让步;与…妥协","en":"If you meet someone halfway, you accept some of the points they are making so that you can come to an agreement with them.","ex":{"en":"The Democrats are willing to meet the president halfway.","cn":"民主党人愿意向总统作部分让步。"}},{"pos":"ADV 副词","cn":"过得去地;大致上","en":"Halfway means reasonably.","ex":{"en":"You need hard currency to get anything halfway decent","cn":"你得有硬通货才能买到还算不错的东西。"}}]},"examples":[{"en":"Any halfway decent map will give you that information.","cn":"任何一张还算像样的地图都能提供那些信息。"},{"en":"It's about halfway between London and Bristol.","cn":"它大约位于伦敦和布里斯托尔的中间。"}]},"hero":{"media":{"uk":"media/uk/hero__gb_1.mp3","us":"media/us/hero__us_1.mp3"},"oxford":{"phon":"ˈhɪərəʊ","pos":"noun","senses":[{"en":"a person who is admired by many people for doing something brave or good","cn":"英雄；豪杰","ex":{"en":"a war hero (= somebody who was very brave during a war)","cn":"战斗英雄"}},{"en":"the main male character in a story, novel, film, etc.","cn":"（故事、小说、电影等的）男主人公，男主角","ex":{"en":"The hero of the novel is a ten-year old boy.","cn":"这部小说的主人公是个十岁的男孩。"}},{"en":"a person that you admire because of a particular quality or skill that they have","cn":"崇拜的对象；偶像","ex":{"en":"my childhood hero","cn":"我孩提时的偶像"}},{"en":"a long bread roll split open along its length and filled with various types of food","cn":"潜艇三明治，长卷三明治（用长卷面包纵向切开，内夹各种食物）","lab":"all North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（书、戏剧、电影或故事中品行端正的）男主角，男主人公","en":"The hero of a book, play, film, or story is the main male character, who usually has good qualities.","ex":{"en":"The hero of Doctor Zhivago dies in 1929.","cn":"《日瓦戈医生》的男主角于1929年去世。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指男性）英雄，英雄人物，豪杰，勇士","en":"A hero is someone, especially a man, who has done something brave, new, or good, and who is therefore greatly admired by a lot of people.","ex":{"en":"He called Mr Mandela a hero who had inspired millions.","cn":"他称曼德拉先生为鼓舞了数百万民众的英雄。"}},{"pos":"N-COUNT 可数名词","cn":"偶像;崇拜对象;心目中的英雄","en":"If you describe someone as your hero, you mean that you admire them a great deal, usually because of a particular quality or skill that they have.","ex":{"en":"My boyhood hero was Bobby Charlton","cn":"我童年时代的偶像是博比·查尔顿。"}}]},"examples":[{"en":"The Olympic team were given a hero's welcome on their return home.","cn":"奥运代表队回国时受到了英雄般的欢迎。"},{"en":"The hero of the novel is a ten-year old boy.","cn":"这部小说的主人公是个十岁的男孩。"}]},"headword":{"oxford":{"phon":"ˈhedwɜːd","pos":"noun","senses":[{"en":"a word that forms a heading in a dictionary, under which its meaning is explained","cn":"（词典中的）词目，首词"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（词典中的）词目","en":"In a dictionary, a headword is a word which is followed by an explanation of its meaning."}]},"media":{"uk":"media/uk/headword__gb_1.mp3","us":"media/us/headword__us_1.mp3"}},"homogeneity":{"oxford":{"phon":"ˌhəʊməʊdʒəˈniːəti","pos":"noun","senses":[{"en":"the quality in a group of people or things of being all the same or all of the same type","cn":"同种；同质","ex":{"en":"Cultural homogeneity is created by education and the media.","cn":"文化同质性是由教育和媒体创造的。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同种;同质","en":"Homogeneity is the quality of being homogeneous.","ex":{"en":"The government panicked into imposing a kind of cultural homogeneity.","cn":"政府在恐慌下开始强制实施某种文化统一政策。"}}]},"media":{"uk":"media/uk/homogeneity__gb_1.mp3","us":"media/us/homogeneity__us_1.mp3"}},"higher":{"media":{"uk":"media/uk/higher__gb_1.mp3","us":"media/us/higher__us_1.mp3"},"oxford":{"phon":"ˈhaɪə(r)","pos":"adjective","senses":[{"en":"at a more advanced level; greater in rank or importance than others","cn":"高等级的；级别较高的；较重要的","ex":{"en":"The case was referred to a higher court.","cn":"案件转到了上级法院。"}},{"en":"(in Scotland) an exam taken in a particular subject at a higher level than National 3, 4 and 5 qualifications. Highers are usually taken around the age of 17 to 18.","cn":"学生高级证书考试（水平高于国家 3、4、5 级资格，应试年龄一般在 17 至 18 岁）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（学历、文凭等）高级的，高等的","en":"A higher degree or diploma is a qualification of an advanced standard or level.","ex":{"en":"...a higher diploma in hotel management.","cn":"酒店管理高级证书"}}]},"examples":[{"en":"My mind was on higher things.","cn":"我那时想着更重要的事。"},{"en":"The case was referred to a higher court.","cn":"案件转到了上级法院。"}]},"high-impact":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（锻炼）高强度的","en":"High-impact exercise puts a lot of stress on your body.","ex":{"en":"...high-impact aerobics.","cn":"高强度有氧健身操"}},{"pos":"ADJ 形容词","cn":"（材料）高强度的，承载重压的","en":"High-impact materials are very strong.","ex":{"en":"The durable high-impact plastic case is water resistant to 100 feet.","cn":"这种结实的高强度塑料盒子在水下100英尺以内是防水的。"}}]}},"hello":{"media":{"uk":"media/uk/hello__gb_1.mp3","us":"media/us/hello__us_1.mp3"},"oxford":{"phon":"həˈləʊ","pos":"exclamation, noun","senses":[{"en":"used as a greeting when you meet somebody, in an email, when you answer the phone or when you want to attract somebody’s attention","cn":"（用于问候、发电邮、接电话或引起注意）哈啰，喂，你好","ex":{"en":"Hello John, how are you?","cn":"哈啰，约翰，你好吗？"}},{"en":"used to show that you are surprised by something","cn":"（表示惊讶）嘿","lab":"British English","ex":{"en":"Hello, hello, what's going on here?","cn":"嘿，嘿，这是在干吗？"}},{"en":"used to show that you think somebody has said something stupid or is not paying attention","cn":"（认为别人说了蠢话或分心）喂，嘿","lab":"informal","ex":{"en":"Hello? You didn't really mean that, did you?","cn":"嘿？你不会真是那个意思吧？"}},{"en":"a popular magazine published each week in Britain which contains photographs of and articles about famous people, and is known for saying only good things about them. It was first published in Britain in 1988 as a British version of the Spanish magazine ¡Hola!. The Hello! website is updated with news every day.","cn":"你好！：每周在英国发行的一本流行杂志，其中载有名人的照片和文章，并因只说出好话而闻名。它于1988年在英国首次发行，当时是西班牙杂志《 Hola！》的英文版。你好！网站每天都会更新新闻。","pos":""}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"哈罗;你好","en":"You say 'Hello' to someone when you meet them.","ex":{"en":"Hello, Trish","cn":"你好，特里茜。"}},{"pos":"CONVENTION 惯用语","cn":"（打电话时的招呼语）喂","en":"You say 'Hello' to someone at the beginning of a telephone conversation, either when you answer the phone or before you give your name or say why you are phoning.","ex":{"en":"A moment later, Cohen picked up the phone. 'Hello?'","cn":"过了一会儿，科恩接起电话。“喂？”"}},{"pos":"CONVENTION 惯用语","cn":"（用于引起别人注意）喂","en":"You can call 'hello' to attract someone's attention.","ex":{"en":"She could see the open door of a departmental office. 'Hello! Excuse me. This is the department of French, isn't it?'","cn":"她看到一个系办公室的门开着。“喂！请问，这是法语系，对吗？”"}}]},"examples":[{"en":"‘Hello, Mark.’ ‘Oh, hi, Kathy! How are you?’ “","cn":"马克，你好。” “噢，凯西，你好！最近好吗？”"},{"en":"I'm like, ‘Hello! Did you even listen?’","cn":"我说：“嘿！你到底有没有听我说话？”"}]},"habit":{"media":{"uk":"media/uk/habit__gb_1.mp3","us":"media/us/habit__us_1.mp3"},"oxford":{"phon":"ˈhæbɪt","pos":"noun","senses":[{"en":"a thing that you do often and almost without thinking, especially something that is hard to stop doing","cn":"习惯","g":"[countable]","ex":{"en":"You need to change your eating habits.","cn":"你得改变你的饮食习惯。"}},{"en":"usual behaviour","cn":"惯常行为；习性","g":"[uncountable]","ex":{"en":"I only do it out of habit.","cn":"我这么做只是出于习惯。"}},{"en":"a strong need to keep using drugs, alcohol or cigarettes regularly","cn":"（吸毒、喝酒、抽烟的）瘾","g":"[countable]","lab":"informal","ex":{"en":"He began to finance his habit through burglary.","cn":"他开始靠盗窃来获取可满足他毒瘾的钱。"}},{"en":"a long piece of clothing worn by a monk or nun","cn":"（修道士或修女穿的）长袍；道袍；道服","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"习惯","en":"A habit is something that you do often or regularly.","ex":{"en":"He has an endearing habit of licking his lips when he's nervous","cn":"他有个一紧张就舔嘴唇的可爱习惯。"}},{"pos":"N-COUNT 可数名词","cn":"坏习惯;积习;恶习;陋习","en":"A habit is an action which is considered bad that someone does repeatedly and finds it difficult to stop doing.","ex":{"en":"A good way to break the habit of eating too quickly is to put your knife and fork down after each mouthful","cn":"改掉吃饭太快的坏习惯有一个好办法，那就是每吃一口就把刀叉放下。"}},{"pos":"N-COUNT 可数名词","cn":"（吸食海洛因、可卡因等的）毒瘾","en":"A drug habit is an addiction to a drug such as heroin or cocaine.","ex":{"en":"She became a prostitute in order to pay for her cocaine habit.","cn":"她以娼养吸。"}},{"pos":"N-COUNT 可数名词","cn":"（修道士或修女穿的）长袍，道袍，道服","en":"A habit is a piece of clothing shaped like a long loose dress, which a nun or monk wears."},{"pos":"PHRASE 短语","cn":"按习惯行事的人;习惯的奴隶","en":"If you say that someone is a creature of habit, you mean that they usually do the same thing at the same time each day, rather than doing new and different things."},{"pos":"PHRASE 短语","cn":"有/养成…的习惯;习惯于","en":"If you are in the habit of doing something, you do it regularly or often. If you get into the habit of doing something, you begin to do it regularly or often.","ex":{"en":"They were in the habit of giving two or three dinner parties a month","cn":"他们每月举办两三次宴会，都成习惯了。"}},{"pos":"PHRASE 短语","cn":"对做…习以为常;使…成为一种习惯","en":"If you make a habit of doing something, you do it regularly or often.","ex":{"en":"You can phone me at work as long as you don't make a habit of it.","cn":"你可以上班时给我打电话，只要别一来二去打上瘾了就成。"}},{"pos":"PHRASE 短语","cn":"思维习惯","en":"If someone has a particular habit of mind, they usually think in that particular way.","ex":{"en":"In accent, mannerism and habit of mind he appeared to be completely Eastern European.","cn":"从口音、举止和思维习惯上看，他完全是东欧人。"}}]},"examples":[{"en":"He began to finance his habit through burglary.","cn":"他开始靠盗窃来获取可满足他毒瘾的金钱。"},{"en":"It's all right to borrow money occasionally, but don't let it become a habit.","cn":"偶尔借点钱倒没关系，但不要养成习惯。"}]},"hoof":{"oxford":{"phon":"huːf","pos":"noun","senses":[{"en":"the hard part of the foot of some animals, for example horses","cn":"（马等动物的）蹄","ex":{"en":"The horse tossed its head and stamped its hooves nervously.","cn":"马摇摇头，紧张地跺着蹄子。"}},{"en":"to kick a ball very hard or a long way","cn":"猛踢（球）；把（球）踢出很远","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（马等动物的）蹄","en":"The hooves of an animal such as a horse are the hard lower parts of its feet.","ex":{"en":"The horses' hooves often could not get a proper grip.","cn":"马蹄经常会打滑。"}}]},"media":{"img":["media/pic/mammals_comp.jpg","media/thumb/hoof.jpg"],"uk":"media/uk/hoof__gb_1.mp3","us":"media/us/hoof__us_1.mp3"},"examples":[{"en":"We hoofed it all the way to 42nd Street.","cn":"我们一路步行到了第 42 街。"}]},"hustle":{"oxford":{"phon":"ˈhʌsl","pos":"verb","senses":[{"en":"to make somebody move quickly by pushing them in a rough aggressive way","cn":"推搡；猛推","g":"[transitive]","ex":{"en":"He grabbed her arm and hustled her out of the room.","cn":"他抓住她的胳膊把她推出房间。"}},{"en":"to force somebody to make a decision before they are ready or sure","cn":"催促（某人做决定）","g":"[transitive]","ex":{"en":"All the family felt that Stephen had been hustled into the engagement by Claire.","cn":"全家人都觉得斯蒂芬是被克莱尔催促订婚的。"}},{"en":"to sell or obtain something, often illegally","cn":"（常指非法地）兜售，取得","g":"[transitive, intransitive]","lab":"informal, especially North American English，，","ex":{"en":"to hustle dope","cn":"兜售麻醉品"}},{"en":"to act in an aggressive way or with a lot of energy","cn":"强行；强迫；硬干","g":"[intransitive]","lab":"North American English, informal，，"},{"en":"to work as a prostitute","cn":"当妓女","g":"[intransitive]","lab":"North American English"},{"en":"busy noisy activity of a lot of people in one place","cn":"忙碌喧嚣","g":"[uncountable]","ex":{"en":"We escaped from the hustle and bustle of the city for the weekend.","cn":"我们周末时躲开了城市的拥挤喧嚣。"},"pos":"noun"},{"en":"a situation in which somebody uses dishonest or illegal methods in order to achieve something, usually to get money","cn":"欺诈行为；欺骗手段","g":"[countable]","lab":"North American English, informal，，","ex":{"en":"Many ex-convicts find it hard to get regular work and return to their old hustles in order to survive.","cn":"许多刑满释放人员发现很难找到正常的工作，为了生存又回到原来的生活。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"猛推;猛拉;推搡","en":"If you hustle someone, you try to make them go somewhere or do something quickly, for example by pulling or pushing them along.","ex":{"en":"The guards hustled Harry out of the car","cn":"卫兵将哈里从车里拉了出来。"}},{"pos":"VERB 动词","cn":"快速行走;赶紧","en":"If you hustle, you go somewhere or do something as quickly as you can.","ex":{"en":"You'll have to hustle if you're to get home for supper","cn":"你想赶回家吃晚饭的话，就得加快速度。"}},{"pos":"VERB 动词","cn":"（常指用不正当或非法的手段）谋取;骗钱;诈取","en":"If someone hustles, they try to earn money or gain an advantage from a situation, often by using dishonest or illegal means.","ex":{"en":"We're expected to hustle and fight for what we want","cn":"我们应该为得到自己想要的而不择手段，奋力争取。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"熙攘;忙碌","en":"Hustle is busy, noisy activity.","ex":{"en":"Shell Cottage provides the perfect retreat from the hustle and bustle of London","cn":"谢尔农舍为想要躲避伦敦的忙碌喧嚣的人们提供了一个绝佳的休闲之所。"}}]},"media":{"uk":"media/uk/hustle__gb_1.mp3","us":"media/us/hustle__us_1.mp3"},"examples":[{"en":"We escaped from the hustle and bustle of the city for the weekend.","cn":"我们周末时躲开了城市的拥挤喧嚣。"},{"en":"He grabbed her arm and hustled her out of the room.","cn":"他抓住她的胳膊把她推出房间。"}]},"halo":{"media":{"uk":"media/uk/halo__gb_1.mp3","us":"media/us/halo__us_1.mp3"},"oxford":{"phon":"ˈheɪləʊ","pos":"noun","senses":[{"en":"(in paintings, etc.) a circle of light shown around or above the head of a holy person","cn":"（绘画等中环绕圣人头上的）光环，光轮","lab":"figurative","ex":{"en":"She played the part of an angel, complete with wings and a halo.","cn":"她扮演天使，身上的双翼和头上的光轮一应俱全。"}},{"en":"a corona (= a ring of light seen around the sun or moon, especially during an eclipse)","cn":"（日、月或其他发光体的）光晕，晕圈","lab":"informal"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（绘画中圣人、天使头上的）光环，光轮","en":"A halo is a circle of light that is shown in pictures round the head of a holy figure such as a saint or angel."},{"pos":"N-COUNT 可数名词","cn":"晕;晕状物","en":"A halo is a circle of light round a person or thing, or something that looks like a circle of light.","ex":{"en":"The sun had a faint halo round it","cn":"环绕太阳有圈淡淡的光晕。"}}]},"examples":[{"en":"She played the part of an angel, complete with wings and a halo.","cn":"她扮演天使，身上的双翼和头上的光轮一应俱全。"},{"en":"( figurative ) a halo of white frizzy hair","cn":"一圈白色鬈发"}]},"hooked":{"media":{"uk":"media/uk/hooked__gb_1.mp3","us":"media/us/hooked__us_1.mp3"},"oxford":{"phon":"hʊkt","pos":"adjective","senses":[{"en":"curved; like a hook in shape","cn":"弯曲的；钩形的","ex":{"en":"a hooked nose/beak/finger","cn":"鹰钩鼻子；钩喙；屈指"}},{"en":"needing something that is bad for you, especially a drug","cn":"上瘾；（尤指）有毒瘾","g":"[not before noun]","lab":"informal","ex":{"en":"People who are truly hooked will go to any lengths to satisfy their craving for the drug.","cn":"真正吸毒成瘾的人为了满足毒瘾会不择手段。"}},{"en":"enjoying something very much, so that you want to do it, see it, etc. as much as possible","cn":"（对某事）着迷","g":"[not before noun]","lab":"informal","ex":{"en":"I first got hooked on scuba diving when I was twelve.","cn":"12 岁时我开始迷上了戴水肺潜水。"}},{"en":"having one or more hooks","cn":"有钩的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"钩状的","en":"If you describe something as hooked, you mean that it is shaped like a hook.","ex":{"en":"He was thin and tall, with a hooked nose.","cn":"他又瘦又高，长着鹰钩鼻。"}},{"pos":"ADJ 形容词","cn":"（被…）迷住的;（对…）入迷的","en":"If you are hooked on something, you enjoy it so much that it takes up a lot of your interest and attention.","ex":{"en":"Many of the leaders have become hooked on power and money","cn":"很多领导人都变得贪恋权力和金钱。"}},{"pos":"ADJ 形容词","cn":"（吸毒）上瘾的","en":"If you are hooked on a drug, you are addicted to it.","ex":{"en":"He spent a number of years hooked on cocaine, heroin and alcohol.","cn":"他有好几年时间吸食可卡因和海洛因成瘾，还整日酗酒。"}}]},"examples":[{"en":"a hooked nose/beak/finger","cn":"鹰钩鼻子；钩喙；屈指"},{"en":"I know a girl who got hooked on cocaine.","cn":"我认识一个染上可卡因毒瘾的姑娘。"}],"base":"hook"},"hush":{"media":{"uk":"media/uk/hush__gb_1.mp3","us":"media/us/hush__us_1.mp3"},"oxford":{"phon":"hʌʃ","pos":"verb","senses":[{"en":"to be quiet; to stop talking or crying","cn":"安静；别说话；别叫喊","g":"[intransitive]","ex":{"en":"Hush now and try to sleep.","cn":"别出声了，睡吧。"}},{"en":"to make somebody/something become quieter; to make somebody stop talking, crying, etc.","cn":"使安静下来；使停止说话（或叫喊等）","g":"[transitive]","ex":{"en":"She tenderly hushed the baby in her arms.","cn":"她温柔地把怀里的孩子安静下来。"}},{"en":"a period of silence, especially following a lot of noise, or when people are expecting something to happen","cn":"寂静；鸦雀无声","lab":"British English, informal，，","ex":{"en":"There was a deathly hush in the theatre.","cn":"戏院里一片寂静。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"（用于要求或命令别人安静）嘘","en":"You say 'Hush!' to someone when you are asking or telling them to be quiet.","ex":{"en":"Hush, my love, it's all right.","cn":"嘘，宝贝，没事了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）安静下来;（使）停止说话","en":"If you hush someone or if they hush, they stop speaking or making a noise.","ex":{"en":"She tried to hush her noisy father","cn":"她试图让吵吵嚷嚷的父亲安静下来。"}},{"pos":"N-SING 单数名词","cn":"寂静;宁静;（突然出现的）安静","en":"You say there is a hush in a place when everything is quiet and peaceful, or suddenly becomes quiet.","ex":{"en":"A hush fell over the crowd and I knew something terrible had happened.","cn":"人群突然一片肃静，我知道一定发生了什么可怕的事。"}},{"pos":"","cn":"","en":"相关词组：hush up"}]},"examples":[{"en":"He claimed that the whole affair had been hushed up by the council.","cn":"他声称整个事件都被议会一手捂住了。"},{"en":"A hush descended over the waiting crowd.","cn":"等候着的人群变得鸦雀无声。"}]},"happiness":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling of being happy","cn":""},{"en":"the feeling you have when you enjoy doing something, or when something happens that you enjoy","cn":""}]},"examples":[{"en":"Juliet’s eyes shone with happiness.","cn":"朱丽叶的双眼闪耀着幸福的光芒。","src":"ld"},{"en":"We want our children to have the best possible chance of happiness.","cn":"我们希望自己的孩子得到追求幸福的最佳机会。","src":"ld"}],"media":{"uk":"media/uk/happiness__gb_1.mp3","us":"media/us/happiness__us_1.mp3"},"oxford":{"phon":"ˈhæpinəs","pos":"noun","senses":[{"en":"the state of feeling or showing pleasure","cn":"快乐；高兴","ex":{"en":"to find true happiness","cn":"找到真正的幸福"}},{"en":"the state of being satisfied that something is good or right","cn":"满意","ex":{"en":"The meeting expressed happiness about the progress made.","cn":"会上大家对进展表示满意。"}}]}},"homogeneous":{"media":{"uk":"media/uk/homogeneous__gb_1.mp3","us":"media/us/homogeneous__us_1.mp3"},"oxford":{"phon":"ˌhɒməˈdʒiːniəs","pos":"adjective","senses":[{"en":"consisting of things or people that are all the same or all of the same type","cn":"由同类事物（或人）组成的；同种类的","ex":{"en":"a homogeneous group/mixture/population","cn":"相同成分组成的群体／混合物；同类人口"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同种类的;同性质的;由相同成分（或部分）组成的","en":"Homogeneous is used to describe a group or thing which has members or parts that are all the same.","ex":{"en":"The unemployed are not a homogeneous group","cn":"失业者不能一概而论。"}}]},"examples":[{"en":"a homogeneous group/mixture/population","cn":"相同成分组成的群体/混合物；同类人口"},{"en":"a homogeneous society","cn":"同种族人组成的社会"}]},"his":{"media":{"uk":"media/uk/his__gb_1.mp3","us":"media/us/his__us_1.mp3"},"oxford":{"phon":"hɪz","pos":"determiner","senses":[{"en":"of or belonging to a man or boy who has already been mentioned or is easily identified","cn":"他的","ex":{"en":"James has sold his car.","cn":"詹姆斯把他的车卖了。"}},{"en":"of or belonging to God","cn":"上帝的；属于上帝的"},{"en":"of or belonging to him","cn":"他的；属于他的","ex":{"en":"He took my hand in his.","cn":"他握住我的手。"},"pos":"pronoun"}]},"collins":{"senses":[{"pos":"DET-POSS 所有格限定词","cn":"他的;（指雄性动物）它的","en":"You use his to indicate that something belongs or relates to a man, boy, or male animal.","ex":{"en":"Brian splashed water on his face, then brushed his teeth","cn":"布赖恩用水冲了把脸，然后刷牙。"}},{"pos":"DET-POSS 所有格限定词","cn":"（书面英语中泛指人）他的，她的（有些人不喜欢这种说法，更倾向于使用 his or her 或 their）","en":"In written English, his is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'his or her' or 'their'.","ex":{"en":"Formerly, the relations between a teacher and his pupils were dominated by fear on the part of the pupils","cn":"以往的师生关系主要是学生惧怕老师。"}},{"pos":"DET-POSS 所有格限定词","cn":"（一些宗教中指）上帝","en":"In some religions, His is used to refer to God.","ex":{"en":"...humble faith in God, and trust in His Church.","cn":"对上帝的谦卑信仰和对教会的信任"}}]},"examples":[{"en":"James has sold his car.","cn":"詹姆斯把他的车卖了。"},{"en":"He broke his leg skiing.","cn":"他滑雪时摔断了腿。"}]},"hers":{"oxford":{"phon":"hɜːz","pos":"pronoun","senses":[{"en":"of or belonging to her","cn":"她的；属于她的","lab":"British English","ex":{"en":"His eyes met hers.","cn":"他的目光和她的相遇了。"}}]},"collins":{"senses":[{"pos":"PRON-POSS 所有格代词","cn":"她的(东西)","en":"You use hers to indicate that something belongs or relates to a woman, girl, or female animal.","ex":{"en":"His hand as it shook hers was warm and firm","cn":"和她握手时他的手温暖而有力。"}},{"pos":"PRON-POSS 所有格代词","cn":"（书面英语中泛指人）他的，她的（有些人不喜欢这种用法，更倾向于使用 his or hers 或 theirs）","en":"In written English, hers is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'his or hers' or 'theirs'.","ex":{"en":"The author can report other people's results which more or less agree with hers.","cn":"作者可以提及其他人得出的和她自己基本吻合的结果。"}},{"pos":"PRON-POSS 所有格代词","cn":"（指国家或民族）她的，它的","en":"Hers is sometimes used to refer to a country or nation."},{"pos":"PRON-POSS 所有格代词","cn":"（指汽车、机器或船）她的，它的","en":"People sometimes use hers to refer to a car, machine, or ship."}]},"media":{"uk":"media/uk/hers__gb_1.mp3","us":"media/us/hers__us_1.mp3"},"examples":[{"en":"His eyes met hers.","cn":"他的目光和她的相遇了。"},{"en":"The choice was hers.","cn":"那个选择是她做出的。"}]},"helicopter":{"media":{"img":["media/ldoce/img/helicopter.jpg","media/pic/aircraft_comp.jpg"],"uk":"media/uk/helicopter__gb_1.mp3","us":"media/us/helicopter__us_1.mp3"},"oxford":{"phon":"ˈhelɪkɒptə(r)","pos":"noun","senses":[{"en":"an aircraft without wings that has large blades (= long flat parts) on top that go round. It can fly straight up from the ground and can also stay in one position in the air.","cn":"直升机","ex":{"en":"a police/rescue helicopter","cn":"警用／救援直升机"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"直升机","en":"A helicopter is an aircraft with long blades on top that go round very fast. It is able to stay still in the air and to move straight upwards or downwards."}]},"examples":[{"en":"He was rushed to the hospital by helicopter.","cn":"他由直升机火速送到医院。"},{"en":"a helicopter pilot","cn":"直升机驾驶员"}]},"hint":{"oxford":{"phon":"hɪnt","pos":"noun","senses":[{"en":"something that you say or do in an indirect way in order to show somebody what you are thinking","cn":"暗示；提示；示意","ex":{"en":"He gave a broad hint (= one that was obvious) that he was thinking of retiring.","cn":"他几乎明示他正在考虑退休。"}},{"en":"something that suggests what will happen in the future","cn":"征兆；迹象","ex":{"en":"At the first hint of trouble, they left.","cn":"他们一发现有点不妙的迹象就离开了。"}},{"en":"a small amount of something","cn":"少许；少量","g":"[usually singular]","ex":{"en":"a hint of a smile","cn":"一丝笑意"}},{"en":"a small piece of practical information or advice","cn":"秘诀；窍门","g":"[usually plural]","ex":{"en":"handy hints on saving money","cn":"省钱妙诀"}},{"en":"to suggest something in an indirect way","cn":"暗示；透露；示意","ex":{"en":"What are you hinting at?","cn":"你在暗示什么？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"暗示","en":"A hint is a suggestion about something that is made in an indirect way.","ex":{"en":"The Minister gave a strong hint that the government were thinking of introducing tax concessions for mothers","cn":"部长明显地暗示政府正在考虑对母亲们实行税收减免。"}},{"pos":"VERB 动词","cn":"暗示;示意","en":"If you hint at something, you suggest it in an indirect way.","ex":{"en":"She suggested a trip to the shops and hinted at the possibility of a treat of some sort","cn":"她建议去逛逛商店，并暗示可能要请客。"}},{"pos":"N-COUNT 可数名词","cn":"有益的建议;不错的主意;好点子","en":"A hint is a helpful piece of advice, usually about how to do something.","ex":{"en":"Here are some helpful hints to make your journey easier","cn":"几条有用的建议可以让你的旅途更轻松。"}},{"pos":"N-SING 单数名词","cn":"少许;微量","en":"A hint of something is a very small amount of it.","ex":{"en":"She added only a hint of vermouth to the gin","cn":"她只在杜松子酒里加了少许苦艾酒。"}}]},"media":{"uk":"media/uk/hint__gb_1.mp3","us":"media/us/hint__us_1.mp3"},"examples":[{"en":"I thought they'd never go — some people just can't take a hint.","cn":"我以为他们永远也不会走的，有些人就是不会看眼色。"},{"en":"Sarah hoped he'd take the hint and leave her alone.","cn":"萨拉希望他能明白她的意思，不来打扰她。"}]},"hook":{"media":{"img":["media/ldoce/img/hook.jpg","media/pic/hook_comp.jpg"],"uk":"media/uk/hook__gb_1.mp3","us":"media/us/hook__us_1.mp3"},"oxford":{"phon":"hʊk","pos":"noun","senses":[{"en":"a curved piece of metal, plastic or wire for hanging things on, catching fish with, etc.","cn":"钩；钓钩；挂钩；鱼钩","ex":{"en":"a picture/curtain/coat hook","cn":"挂图钩；窗帘钩；挂衣钩"}},{"en":"a short hard hit that is made with the elbow bent","cn":"勾拳","ex":{"en":"a left hook to the jaw","cn":"击向下颌的一记左勾拳"}},{"en":"a way of hitting the ball so that it curves to the side instead of going straight ahead (usually by mistake in golf, but deliberately in cricket)","cn":"（高尔夫球）左曲球，内弯球；（板球）曲线球"},{"en":"a thing that is used to make people interested in something","cn":"吸引人的事物；诱饵","ex":{"en":"The images are used as a hook to get children interested in science.","cn":"这些图像用以吸引孩子们对科学产生兴趣。"}},{"en":"to fasten or hang something on something else using a hook; to be fastened or hanging in this way","cn":"（使）钩住，挂住","g":"[transitive, intransitive]","ex":{"en":"We hooked the trailer to the back of the car.","cn":"我们把拖车挂在汽车尾部。"},"pos":"verb"},{"en":"to put something, especially your leg, arm or finger, around something else so that you can hold onto it or move it; to go around something else in this way","cn":"（尤指用腿、胳膊、手指等）钩住，箍住","g":"[transitive, intransitive]","ex":{"en":"He hooked his foot under the stool and dragged it over.","cn":"他用脚从底下钩住凳子，把它拖了过去。"},"pos":"verb"},{"en":"to catch a fish with a hook","cn":"钓（鱼）","g":"[transitive]","lab":"figurative","ex":{"en":"It was the biggest pike I ever hooked.","cn":"那是我钓到的最大的狗鱼。"},"pos":"verb"},{"en":"to hit or kick a ball so that it goes to one side instead of straight ahead (usually by mistake in golf but deliberately in other sports)","cn":"打左曲球；打曲线球；踢弧线球","g":"[transitive]","ex":{"en":"He hooked his drive into the trees.","cn":"他把车挂在树林里。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钩;吊钩;挂钩","en":"A hook is a bent piece of metal or plastic that is used for catching or holding things, or for hanging things up.","ex":{"en":"One of his jackets hung from a hook.","cn":"他的一件夹克衫挂在衣钩上。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（用钩）吊住，挂住，固定","en":"If you hook one thing to another, you attach it there using a hook. If something hooks somewhere, it can be hooked there.","ex":{"en":"Paul hooked his tractor to the car and pulled it to safety.","cn":"保罗把自己的拖拉机挂在汽车上，然后把它拉到了安全的地方。"}},{"pos":"VERB 动词","cn":"（用手臂、腿或脚）钩住，绕住","en":"If you hook your arm, leg, or foot round an object, you place it like a hook round the object in order to move it or hold it.","ex":{"en":"She latched on to his arm, hooking her other arm around a tree","cn":"她拽住他的胳膊不放，另一只胳膊抱紧一棵树。"}},{"pos":"VERB 动词","cn":"钓（鱼）","en":"If you hook a fish, you catch it with a hook on the end of a line.","ex":{"en":"At the first cast I hooked a huge fish.","cn":"第一次抛下钓线，我就钓了一条大鱼。"}},{"pos":"N-COUNT 可数名词","cn":"（通常指拳击运动中的）钩拳","en":"A hook is a short sharp blow with your fist that you make with your elbow bent, usually in a boxing match.","ex":{"en":"Lewis desperately needs to keep clear of Ruddock's big left hook.","cn":"刘易斯无论如何得躲开拉多克凌厉的左钩拳才行。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）参与;（使）涉足","en":"If you are hooked into something, or hook into something, you get involved with it.","ex":{"en":"I'm guessing again now because I'm not hooked into the political circles","cn":"我现在又是在猜测了，因为我没有涉足政界。"}},{"pos":"VERB 动词","cn":"连接到（因特网）;上（网）","en":"If you hook into the Internet, you make a connection with the Internet on a particular occasion so that you can use it.","ex":{"en":"...an interactive media tent where people will be able to hook into the internet.","cn":"人们可以上网的互动式媒体帐篷区"}},{"pos":"PHRASE 短语","cn":"脱离困境;脱身","en":"If someone gets off the hook or is let off the hook, they manage to get out of the awkward or unpleasant situation that they are in.","ex":{"en":"Government officials accused of bribery and corruption get off the hook with monotonous regularity","cn":"被指控贪污受贿的政府官员无一例外总能脱身。"}},{"pos":"PHRASE 短语","cn":"摘下听筒（不让电话响）","en":"If you take a phone off the hook, you take the receiver off the part that it normally rests on, so that the phone will not ring."},{"pos":"PHRASE 短语","cn":"（电话）响个不停","en":"If your phone is ringing off the hook, so many people are trying to telephone you that it is ringing constantly.","ex":{"en":"Since war broke out, the phones at donation centers have been ringing off the hook.","cn":"自从战争爆发以来，捐赠中心的电话就一直响个不停。"}},{"pos":"","cn":"","en":"by hook or by crook→see: ; by hook or by crook→see: ; by hook or by crook→see: ; hook→see: ;"},{"pos":"","cn":"","en":"相关词组：hook up"}]},"examples":[{"en":"The images are used as a hook to get children interested in science.","cn":"这些图像用以吸引孩子们对科学产生兴趣。"},{"en":"He hooked his foot under the stool and dragged it over.","cn":"他用脚从底下钩住凳子，把它拖了过去。"}]},"hive":{"media":{"uk":"media/uk/hive__gb_1.mp3","us":"media/us/hive__us_1.mp3"},"oxford":{"phon":"haɪv","pos":"noun","senses":[{"en":"a structure made for bees to live in","cn":"蜂房；蜂箱","g":"[countable]","ex":{"en":"studying the life of bees in the hive","cn":"研究蜜蜂在蜂巢中的生活"}},{"en":"the bees living in a hive","cn":"一箱蜜蜂；蜂群","g":"[countable]"},{"en":"a place full of people who are busy","cn":"忙碌的场所；繁忙的地方","g":"[countable, usually singular]"},{"en":"red spots on the skin that itch (= make you want to rub your skin with your nails), caused by an allergic reaction, for example to certain foods","cn":"荨麻疹","g":"[uncountable, plural]","lab":"medical"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蜂房;蜂箱","en":"A hive is a structure in which bees are kept, which is designed so that the beekeeper can collect the honey that they produce."},{"pos":"N-COUNT 可数名词","cn":"熙熙攘攘的场所;人群忙碌的地方","en":"If you describe a place as a hive of activity, you approve of the fact that there is a lot of activity there or that people are busy working there.","ex":{"en":"In the morning the house was a hive of activity","cn":"早上，房子里一片繁忙景象。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"荨麻疹","en":"Hives is a condition in which patches of your skin become red and very uncomfortable and itchy."},{"pos":"","cn":"","en":"相关词组：hive off"}]},"examples":[{"en":"The IT department is being hived off into a new company.","cn":"信息技术部正被分拆出来，成立新公司。"},{"en":"This marketplace was once a hive of activity.","cn":"这个市场曾经熙熙攘攘。"}]},"heaving":{"media":{"uk":"media/uk/heaving__gb_1.mp3","us":"media/us/heaving__us_1.mp3"},"oxford":{"phon":"ˈhiːvɪŋ","pos":"adjective","senses":[{"en":"full of somebody/something","cn":"充满（人或事物）","ex":{"en":"The place was heaving with journalists.","cn":"那个地方挤满了记者。"}}]},"examples":[{"en":"The place was heaving with journalists.","cn":"那个地方挤满了记者。"},{"en":"The city was heaving with shoppers.","cn":"这个城市挤满了购物者。"}],"base":"heave"},"hopefully":{"media":{"uk":"media/uk/hopefully__gb_1.mp3","us":"media/us/hopefully__us_1.mp3"},"oxford":{"phon":"ˈhəʊpfəli","pos":"adverb","senses":[{"en":"used to express what you hope will happen","cn":"有希望地；可以指望","ex":{"en":"Hopefully, we'll arrive before dark.","cn":"我们有望在天黑前到达。"}},{"en":"showing hope","cn":"抱有希望地","ex":{"en":"‘Are you free tonight?’ she asked hopefully.","cn":"“你今晚有空吗？”她抱着希望地问。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"但愿，作为希望（一些用词严谨者认为这种用法不正确，但实际上已被频繁地使用）","en":"You say hopefully when mentioning something that you hope will happen. Some careful speakers of English think that this use of hopefully is not correct, but it is very frequently used.","ex":{"en":"Both of them have been through an awful lot and hopefully now I can help them rebuild their lives","cn":"他们两人都曾历经磨难，但愿现在我能帮助他们重建正常的生活。"}}]},"examples":[{"en":"‘Are you free tonight?’ she asked hopefully. “","cn":"你今晚有空吗？”她抱着希望地问。"},{"en":"Hopefully, we'll arrive before dark.","cn":"我们有望在天黑前到达。"}]},"homeworker":{"oxford":{"phon":"ˈhəʊmwɜːkə(r)","pos":"noun","senses":[{"en":"a person who works at home, often doing jobs that are not well paid such as making clothes for shops","cn":"在家工作的人（常做低薪工作）","ex":{"en":"Few homeworkers doing piecework in manufacturing enjoy employee status.","cn":"在制造业中从事计件工作的家庭工人很少享有雇员身份。"}}]},"media":{"uk":"media/uk/homeworker__gb_1.mp3","us":"media/us/homeworker__us_1.mp3"}},"hover":{"oxford":{"phon":"ˈhɒvə(r)","pos":"verb","senses":[{"en":"to stay in the air in one place","cn":"翱翔；盘旋","g":"[intransitive]","ex":{"en":"A hawk hovered over the hill.","cn":"一只鹰在小山的上空翱翔。"}},{"en":"to wait somewhere, especially near somebody, in a shy or uncertain manner","cn":"踌躇，彷徨（尤指在某人身边）","g":"[intransitive]","ex":{"en":"He hovered nervously in the doorway.","cn":"他在门口紧张地来回踱步。"}},{"en":"to stay close to something, or to stay in an uncertain state","cn":"靠近（某事物）；处于不稳定状态","g":"[intransitive]","ex":{"en":"Temperatures hovered around freezing.","cn":"气温在冰点上下徘徊。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"悬浮;（鸟、昆虫等）振翅悬停","en":"To hover means to stay in the same position in the air without moving forwards or backwards. Many birds and insects can hover by moving their wings very quickly.","ex":{"en":"Beautiful butterflies hovered above the wild flowers","cn":"美丽的蝴蝶在野花上方飞舞。"}},{"pos":"VERB 动词","cn":"逗留在一处;徘徊;踌躇","en":"If you hover, you stay in one place and move slightly in a nervous way, for example because you cannot decide what to do.","ex":{"en":"Judith was hovering in the doorway","cn":"朱迪丝在门口徘徊。"}},{"pos":"VERB 动词","cn":"处于不确定状态;犹豫不决","en":"If you hover, you are in an uncertain situation or state of mind.","ex":{"en":"She hovered on the brink of death for three months as doctors battled to save her","cn":"3个月来她一直在死亡线上徘徊，而医生则在全力挽救她的生命。"}},{"pos":"VERB 动词","cn":"（价格、价值、分数等）上下波动左右摇摆","en":"If something such as a price, value, or score hovers around a particular level, it stays at more or less that level and does not change much.","ex":{"en":"In September 1989 the exchange rate hovered around 140 yen to the dollar","cn":"1989年9月，日元对美元的汇率一直在140比1的水平上下浮动。"}}]},"media":{"uk":"media/uk/hover__gb_1.mp3","us":"media/us/hover__us_1.mp3"},"examples":[{"en":"A hawk hovered over the hill.","cn":"一只鹰在小山的上空翱翔。"},{"en":"He hovered nervously in the doorway.","cn":"他在门口紧张地来回踱步。"}]},"harm":{"oxford":{"phon":"hɑːm","pos":"noun","senses":[{"en":"damage or injury that is caused by a person or an event","cn":"伤害；损害","ex":{"en":"He would never frighten anyone or cause them any harm.","cn":"他永远不会吓唬或伤害任何人。"}},{"en":"to hurt or injure somebody or to damage something","cn":"伤害；损害","ex":{"en":"He would never harm anyone.","cn":"他永远不会伤害任何人。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（通常为故意地）伤害，危害","en":"To harm a person or animal means to cause them physical injury, usually on purpose.","ex":{"en":"The hijackers seemed anxious not to harm anyone.","cn":"劫持犯似乎焦虑不安，不想伤害任何人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（通常为故意的）伤害，危害","en":"Harm is physical injury to a person or an animal which is usually caused on purpose.","ex":{"en":"All dogs are capable of doing harm to human beings.","cn":"只要是狗就可能会咬人。"}},{"pos":"VERB 动词","cn":"破坏;损害;对…产生不利影响","en":"To harm a thing, or sometimes a person, means to damage them or make them less effective or successful than they were.","ex":{"en":"...a warning that the product may harm the environment","cn":"该产品可能会危害环境的警告"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（某一行为造成的）损害，危害","en":"Harm is the damage to something which is caused by a particular course of action.","ex":{"en":"The abuse of your powers does harm to all other officers who do their job properly","cn":"滥用权力会对其他所有恪守职责的官员们造成伤害。"}},{"pos":"PHRASE 短语","cn":"不会受损害;不会受到伤害;会安然无恙","en":"If you say that someone or something will come to no harm or that no harm will come to them, you mean that they will not be hurt or damaged in any way.","ex":{"en":"There is always a lifeguard to ensure that no one comes to any harm","cn":"总是有一个救生员在场以确保无人受到伤害。"}},{"pos":"PHRASE 短语","cn":"也许值得（做某事）;不妨（做某事）","en":"If you say it does no harm to do something or there is no harm in doing something, you mean that it might be worth doing, and you will not be blamed for doing it.","ex":{"en":"They are not always willing to take on untrained workers, but there's no harm in asking.","cn":"他们并不总是乐意雇用未经培训的工人，但问问也无妨。"}},{"pos":"PHRASE 短语","cn":"（做某事）没有坏处，有益;不妨（做某事）","en":"If you say that something would do no harm, or do someone no harm, you are recommending a course of action which you think is worthwhile, helpful, or useful.","ex":{"en":"It would do her no harm to try them until we found the one which suited her best.","cn":"她不妨把这些都试试，直到我们找到最适合她的为止。"}},{"pos":"PHRASE 短语","cn":"没有产生危害;没有人受到伤害","en":"If you say that there is no harm done, you are telling someone not to worry about something that has happened because it has not caused any serious injury or damage.","ex":{"en":"There, now, you're all right. No harm done.","cn":"好了，你现在没事了，没人受伤。"}},{"pos":"PHRASE 短语","cn":"处于危险中","en":"If someone is put in harm's way, they are caused to be in a dangerous situation.","ex":{"en":"These men were never told how they'd been put in harm's way","cn":"从来没人告诉这些人他们是如何被置于险境的。"}},{"pos":"PHRASE 短语","cn":"在安全的地方;没有危险","en":"If someone or something is out of harm's way, they are in a safe place away from danger or from the possibility of being damaged.","ex":{"en":"For parents, it is an easy way of keeping their children entertained, or simply out of harm's way","cn":"对父母来说，这是一个能让孩子们开心或者说是让他们远离危险的简单方法。"}}]},"media":{"uk":"media/uk/harm__gb_1.mp3","us":"media/us/harm__us_1.mp3"},"examples":[{"en":"The accident could have been much worse; luckily no harm was done.","cn":"这次事故本来可能糟糕得多；所幸没有造成伤害。"},{"en":"I can't say I like Mark very much, but I don't wish him any harm.","cn":"我不能说我很喜欢马克，但我并不愿他遭到伤害。"}]},"high-pitched":{"oxford":{"phon":"ˌhaɪ ˈpɪtʃt","pos":"adjective","senses":[{"en":"very high","cn":"很高的；尖利的","ex":{"en":"a high-pitched voice/whistle","cn":"尖嗓子；尖锐的口哨声"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尖声的;音调高的","en":"A high-pitched sound is shrill and high in pitch.","ex":{"en":"A woman squealed in a high-pitched voice.","cn":"一个女人大声尖叫。"}}]},"media":{"uk":"media/uk/high_pitched_1_gb_1.mp3","us":"media/us/high_pitched_1_us_1.mp3"},"examples":[{"en":"a high-pitched voice/whistle","cn":"尖嗓子；尖锐的口哨声"}]},"holes":{"lemma":"hole"},"haven":{"oxford":{"phon":"ˈheɪvn","pos":"noun","senses":[{"en":"a place that is safe and peaceful where people or animals are protected","cn":"安全的地方；保护区；避难所","ex":{"en":"The hotel is a haven of peace and tranquillity.","cn":"这家旅馆是一个安宁的去处。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"安全处所;庇护所;避难所","en":"A haven is a place where people or animals feel safe, secure, and happy.","ex":{"en":"It's a real haven at the end of a busy working day.","cn":"忙碌了一整天后，这真是一个安乐窝。"}}]},"media":{"uk":"media/uk/haven__gb_1.mp3","us":"media/us/haven__us_1.mp3"},"examples":[{"en":"The river banks are a haven for wildlife.","cn":"河的两岸是野生动物的自然栖息地。"},{"en":"The hotel is a haven of peace and tranquility.","cn":"这家旅馆是一处安宁的去处。"}]},"horror":{"media":{"uk":"media/uk/horror__gb_1.mp3","us":"media/us/horror__us_1.mp3"},"oxford":{"phon":"ˈhɒrə(r)","pos":"noun","senses":[{"en":"a feeling of great shock or fear","cn":"震惊；恐惧","g":"[uncountable]","ex":{"en":"The thought of being left alone filled her with horror.","cn":"想到被孤零零地留下，她就不寒而栗。"}},{"en":"a very unpleasant or frightening experience","cn":"极其不愉快的（或可怕的）经历","g":"[countable, usually plural]","ex":{"en":"an account of the horrors inflicted on the detainees","cn":"对被拘留者遭受的恐怖经历的描述"}},{"en":"the very unpleasant nature of something, especially when it shocks or frightens you","cn":"（某事物）令人厌恶的性质；（尤指）震惊性，恐怖性","g":"[uncountable]","ex":{"en":"The full horror of the accident was beginning to become clear.","cn":"这次悲惨事故的真相已开始逐渐清晰了。"}},{"en":"a strong feeling of fear or of hating something","cn":"畏惧；痛恨","g":"[singular]","ex":{"en":"a horror of deep water","cn":"恐惧深水"}},{"en":"a type of book, film, etc. that is designed to frighten people","cn":"恐怖题材的作品","g":"[uncountable]","ex":{"en":"In this section you'll find horror and science fiction.","cn":"你可以在这一部分找到恐怖和科幻小说。"}},{"en":"a child who behaves badly","cn":"调皮捣蛋的孩子","g":"[countable]","lab":"British English, informal，，","ex":{"en":"Her son is a little horror.","cn":"她的儿子是个小捣蛋鬼。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"震惊;恐惧;惊恐","en":"Horror is a feeling of great shock, fear, and worry caused by something extremely unpleasant.","ex":{"en":"I felt numb with horror","cn":"我惊呆了。"}},{"pos":"N-SING 单数名词","cn":"惧怕;憎恶","en":"If you have a horror of something, you are afraid of it or dislike it very much.","ex":{"en":"...his horror of death.","cn":"他对死亡的惧怕"}},{"pos":"N-SING 单数名词","cn":"恐怖性;残酷","en":"The horror of something, especially something that hurts people, is its very great unpleasantness.","ex":{"en":"...the horror of this most bloody of civil wars.","cn":"这场极其血腥的内战的惨烈"}},{"pos":"N-COUNT 可数名词","cn":"极其不愉快（或可怕）的经历","en":"You can refer to extremely unpleasant or frightening experiences as horrors .","ex":{"en":"Can you possibly imagine all the horrors we have undergone since I last wrote you?","cn":"你能想象得出自从我上次给你写信以来我们所经历的所有可怕事情吗？"}},{"pos":"N-COUNT 可数名词","cn":"极讨厌（或丑陋）的人（或事物）","en":"If you refer to someone or something as a horror, you mean that you think they are very unpleasant or ugly.","ex":{"en":"Our host was arrogant and offensive. How his sweet wife could tolerate such a horror was baffling.","cn":"招待我们的男主人傲慢无礼。真不知道他温柔的妻子怎么能容忍这样一个讨厌的家伙。"}},{"pos":"ADJ 形容词","cn":"（影片或故事）情节恐怖的，惊悚的","en":"A horror film or story is intended to be very frightening.","ex":{"en":"...a psychological horror film.","cn":"心理恐怖片"}},{"pos":"ADJ 形容词","cn":"（经历或事件）非常不愉快的","en":"You can refer to an account of a very unpleasant experience or event as a horror story.","ex":{"en":"...a horror story about lost luggage while flying.","cn":"乘飞机旅行时丢失行李的糟糕经历"}},{"pos":"PHRASE 短语","cn":"最糟糕不过的事情","en":"Horror of horrors is used to refer to something that you consider to be the worst part of a situation.","ex":{"en":"The company has already boosted its share of the UK tea market with its round tea bags. Now it is successfully converting the nation to (horror of horrors) instant tea.","cn":"该公司已经凭借其袋泡茶提高了自己在英国茶叶市场的占有份额。现在它正在成功地使该国人民改喝（最可怕不过的）速溶茶。"}}]},"examples":[{"en":"I stood up to speak and — horror of horrors — realized I had left my notes behind.","cn":"我站起来讲话，可是，可怕的是，我发现自己忘了带讲稿。"},{"en":"With a look of horror, he asked if the doctor thought he had cancer.","cn":"他惊恐失色地问医生是否认定他患了癌症。"}]},"hurry":{"media":{"uk":"media/uk/hurry__gb_1.mp3","us":"media/us/hurry__us_1.mp3"},"oxford":{"phon":"ˈhʌri","pos":"verb","senses":[{"en":"to move or act quickly because there is not much time","cn":"赶快，匆忙，急忙（做某事）","g":"[intransitive]","ex":{"en":"You'll have to hurry if you want to catch that train.","cn":"如果你想赶上那趟火车就得抓紧时间了。"}},{"en":"to move quickly in a particular direction","cn":"（朝某方向）迅速移动","g":"[intransitive]","ex":{"en":"He picked up his bags and hurried across the courtyard.","cn":"他拎起提包匆匆穿过院子。"}},{"en":"to make somebody do something more quickly","cn":"催促（某人）","g":"[transitive]","ex":{"en":"I don't want to hurry you but we close in twenty minutes.","cn":"我并不想催你，但我们再过二十分钟就要关门。"}},{"en":"to deal with something quickly","cn":"迅速处理","g":"[transitive]","ex":{"en":"Her application was hurried through.","cn":"她的申请很快得到了处理。"}},{"en":"to do something too quickly","cn":"仓促（做某事）","g":"[transitive, usually passive]","ex":{"en":"A good meal should never be hurried.","cn":"美餐绝不能狼吞虎咽。"}},{"en":"the need or wish to get something done quickly","cn":"匆忙；急忙","ex":{"en":"Take your time—there's no hurry.","cn":"悠着点，不用急。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"匆忙地走","en":"If you hurry somewhere, you go there as quickly as you can.","ex":{"en":"Claire hurried along the road","cn":"克莱尔匆匆地沿路而行。"}},{"pos":"VERB 动词","cn":"赶紧（做）;急忙（做）；匆忙（做）","en":"If you hurry to do something, you start doing it as soon as you can, or try to do it quickly.","ex":{"en":"Mrs Hardie hurried to make up for her tactlessness by asking her guest about his holiday","cn":"哈迪夫人赶紧问客人假期过得怎么样，替自己的言不得体打圆场。"}},{"pos":"N-SING 单数名词","cn":"急忙;匆忙;仓促","en":"If you are in a hurry to do something, you need or want to do something quickly. If you do something in a hurry, you do it quickly or suddenly.","ex":{"en":"Kate was in a hurry to grow up, eager for knowledge and experience","cn":"凯特急于长大，渴望获取知识和经验。"}},{"pos":"VERB 动词","cn":"同 hurry up","en":"To hurry something means the same as to hurry up something.","ex":{"en":"...The President's attempt to hurry the process of independence.","cn":"总统试图加快独立进程的努力"}},{"pos":"VERB 动词","cn":"催促;使赶紧","en":"If you hurry someone to a place or into a situation, you try to make them go to that place or get into that situation quickly.","ex":{"en":"Rachel hurried him to his bed","cn":"雷切尔催着他上了床。"}},{"pos":"PHRASE 短语","cn":"不必着急;不忙","en":"If you say to someone 'There's no hurry' or 'I'm in no hurry' you are telling them that there is no need for them to do something immediately.","ex":{"en":"I'll need to talk with you, but there's no hurry","cn":"我得和你谈谈，但不着急。"}},{"pos":"PHRASE 短语","cn":"不愿（做）;不想（做）","en":"If you are in no hurry to do something, you are very unwilling to do it.","ex":{"en":"I love it at St Mirren so I'm in no hurry to go anywhere","cn":"我喜欢在圣米伦的生活，所以我哪里也不愿去。"}},{"pos":"","cn":"","en":"相关词组：hurry along hurry up"}]},"examples":[{"en":"I don't want to hurry you but we close in twenty minutes.","cn":"我并不想催你，但我们再过二十分钟就要关门。"},{"en":"Sorry, I haven't got time to do it now — I'm in a hurry.","cn":"对不起，我现在没时间管这个，我忙着呢。"}]},"heats":{"lemma":"heat","media":{"uk":"media/uk/heat__gb_1.mp3","us":"media/us/heat__us_1.mp3"}},"harvest":{"media":{"uk":"media/uk/harvest__gb_1.mp3","us":"media/us/harvest__us_1.mp3"},"oxford":{"phon":"ˈhɑːvɪst","pos":"noun","senses":[{"en":"the time of year when the crops are gathered in on a farm, etc.; the act of cutting and gathering crops","cn":"收获季节；收割；收获","g":"[countable, uncountable]","ex":{"en":"harvest time","cn":"收获季节"}},{"en":"the crops, or the amount of crops, cut and gathered","cn":"收成；收获量","g":"[countable]","lab":"figurative","ex":{"en":"the grain harvest","cn":"谷物的收成"}},{"en":"to cut and gather a crop; to catch a number of animals or fish to eat","cn":"收割（庄稼）；捕猎（动物、鱼）","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"The nuts are ready to harvest in September.","cn":"九月份坚果就可以收获了。"},"pos":"verb"},{"en":"to collect cells or tissue from somebody’s body for use in medical experiments or operations","cn":"采集（人体的细胞或组织，以供医学实验等）","g":"[transitive]","lab":"medical","ex":{"en":"She had her eggs harvested and frozen for her own future use.","cn":"她做了卵子采集，冷冻以备将来使用。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"收获;收割","en":"The harvest is the gathering of a crop.","ex":{"en":"There were about 300 million tons of grain in the fields at the start of the harvest.","cn":"收获伊始地里大概有3亿吨粮食。"}},{"pos":"N-COUNT 可数名词","cn":"收成;收获量","en":"A harvest is the crop that is gathered in.","ex":{"en":"...a bumper potato harvest","cn":"马铃薯大丰收"}},{"pos":"VERB 动词","cn":"收获;收割","en":"When you harvest a crop, you gather it in.","ex":{"en":"Many farmers are refusing to harvest the cane.","cn":"很多农民正拒绝收割甘蔗。"}},{"pos":"VERB 动词","cn":"获取;收获","en":"If you harvest a large number of things, you collect them, often by making great efforts.","ex":{"en":"In his new career as a restaurateur he has blossomed and harvested many awards.","cn":"转行经营餐饮之后，他在事业上大获成功并获得了许多奖项。"}},{"pos":"PHRASE 短语","cn":"获得成果;尝到苦果","en":"If you reap the harvest, you benefit or suffer from the results of your past actions or of someone else's past actions.","ex":{"en":"The Israeli Prime Minister must be convinced that he will reap a richer harvest of votes by going to the electorate well before October.","cn":"必须说服以色列总理，若在10月份前就尽早走近选民，他会赢得更多选票。"}}]},"examples":[{"en":"( figurative ) The appeal produced a rich harvest of blankets, medicines and clothing.","cn":"呼吁的成果颇丰，收到了大批毛毯、药物和衣服。"},{"en":"She had her eggs harvested and frozen for her own future use.","cn":"她的卵子已经采集下来，冷冻后以备她将来使用。"}]},"hayes":{"oxford":{"phon":"heɪ","pos":"noun","senses":[{"en":"grass that has been cut and dried and is used as food for animals （","cn":"用作饲料的）干草，草料"},{"en":"( NAmE ) ( informal ) a small amount of money","cn":"少量的钱"}]},"media":{"uk":"media/uk/hay__gb_1.mp3","us":"media/us/hay__us_1.mp3"}},"haunting":{"media":{"uk":"media/uk/haunting__gb_1.mp3","us":"media/us/haunting__us_1.mp3"},"oxford":{"phon":"ˈhɔːntɪŋ","pos":"adjective","senses":[{"en":"beautiful, sad or frightening in a way that cannot be forgotten","cn":"萦绕心头的；使人难忘的","ex":{"en":"a haunting melody/experience/image","cn":"难以忘怀的优美乐曲；痛苦难忘的经历；难忘的形象"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声音、形象、话语等）令人难忘的，萦绕心头的","en":"Haunting sounds, images, or words remain in your thoughts because they are very beautiful or sad.","ex":{"en":"...the haunting calls of wild birds in the mahogany trees.","cn":"红木树林中野鸟令人难忘的鸣叫声"}}]},"examples":[{"en":"a haunting melody/experience/image","cn":"难以忘怀的优美乐曲；痛苦难忘的经历；吓人难忘的形象"},{"en":"a haunting melody","cn":"萦绕心头的旋律"}],"base":"haunt"},"highly":{"media":{"uk":"media/uk/highly__gb_1.mp3","us":"media/us/highly__us_1.mp3"},"oxford":{"phon":"ˈhaɪli","pos":"adverb","senses":[{"en":"very","cn":"很；非常","ex":{"en":"It is highly unlikely that she'll be late.","cn":"她不大可能会迟到。"}},{"en":"at or to a high standard, level or amount","cn":"高标准地；高级地；大量地","ex":{"en":"highly trained/educated","cn":"受过高级培训／高等教育"}},{"en":"with great respect or praise","cn":"钦佩地；赞赏地","ex":{"en":"I highly recommend this book.","cn":"我强烈推荐这本书。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"极其;非常","en":"Highly is used before some adjectives to mean 'very'.","ex":{"en":"Mr Singh was a highly successful salesman","cn":"辛格先生是个非常成功的推销员。"}},{"pos":"ADV-GRADED 副词","cn":"身居高位;高级别地","en":"You use highly to indicate that someone has an important position in an organization or set of people.","ex":{"en":"...a highly placed government advisor.","cn":"高级政府顾问"}},{"pos":"ADV-GRADED 副词","cn":"高水平地","en":"If someone is highly paid, they receive a large salary.","ex":{"en":"He was the most highly paid member of staff.","cn":"他是员工中薪酬最高的。"}},{"pos":"ADV-GRADED 副词","cn":"极为（赞许）;（评价）高的","en":"If you think highly of something or someone, you think they are very good indeed.","ex":{"en":"Daphne and Michael thought highly of the school.","cn":"达夫妮和迈克尔对那所学校评价很高。"}}]},"examples":[{"en":"Her novels are very highly regarded.","cn":"她的小说受到很高的评价。"},{"en":"It is highly unlikely that she'll be late.","cn":"她不大可能会迟到。"}]},"hub":{"media":{"uk":"media/uk/hub__gb_1.mp3","us":"media/us/hub__us_1.mp3"},"oxford":{"phon":"hʌb","pos":"noun","senses":[{"en":"a central airport, station, etc. that operates many services","cn":"中心，枢纽（如机场、车站等）","ex":{"en":"The airport has become an international hub.","cn":"这个机场已成为国际枢纽。"}},{"en":"the central and most important part of a particular place or activity","cn":"（某地或活动的）中心，核心","g":"[usually singular]","ex":{"en":"the commercial hub of the city","cn":"城市的商业中心"}},{"en":"the central part of a wheel","cn":"轮毂"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（活动的）中心，核心","en":"You can describe a place as a hub of an activity when it is a very important centre for that activity.","ex":{"en":"The island's social hub is the Cafe Sport","cn":"该岛的社交中心是“体育咖啡馆”。"}},{"pos":"N-COUNT 可数名词","cn":"（轮）毂","en":"The hub of a wheel is the part at the centre."},{"pos":"N-COUNT 可数名词","cn":"航空枢纽;中心机场","en":"A hub or a hub airport is a large airport from which you can travel to many other airports.","ex":{"en":"...a campaign to secure Heathrow's place as Europe's main international hub.","cn":"旨在稳固希思罗机场作为欧洲主要航空枢纽地位的宣传活动"}},{"pos":"","cn":"（网络）集线器","en":"A hub is a device for connecting computers in a network."}]},"examples":[{"en":"the commercial hub of the city","cn":"城市的商业中心"},{"en":"to be at the hub of things (= where things happen and important decisions are made)","cn":"在核心部门"}]},"header":{"oxford":{"phon":"ˈhedə(r)","pos":"noun","senses":[{"en":"an act of hitting the ball with your head","cn":"用头顶球；头球"},{"en":"a line or block of text that appears at the top of every page in a book or document","cn":"页眉；页首","ex":{"en":"The header gives the page number and date of the document.","cn":"页眉印有页码和文档日期。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（足球）头球","en":"In football, a header is the act of hitting the ball in a particular direction with your head."},{"pos":"N-COUNT 可数名词","cn":"（文件的）页眉","en":"A header is text such as a name or a page number that can be automatically displayed at the top of each page of a printed document.","ex":{"en":"...page formatting like headers, footers and page numbers.","cn":"页眉、页脚、页码等页面格式"}}]},"media":{"uk":"media/uk/header__gb_1.mp3","us":"media/us/header__us_1.mp3"}},"helpless":{"media":{"uk":"media/uk/helpless__gb_1.mp3","us":"media/us/helpless__us_1.mp3"},"oxford":{"phon":"ˈhelpləs","pos":"adjective","senses":[{"en":"unable to take care of yourself or do things without the help of other people","cn":"无自理能力的；不能自立的；无助的","ex":{"en":"Children are the most helpless victims of war.","cn":"儿童是战争中最无助的受害者。"}},{"en":"unable to control a strong feeling","cn":"无法抑制的","ex":{"en":"helpless panic/rage","cn":"抑制不住的恐慌／愤怒"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无助的;无力量的;无能力的;不由自主的","en":"If you are helpless, you do not have the strength or power to do anything useful or to control or protect yourself.","ex":{"en":"Parents often feel helpless, knowing that all the cuddles in the world won't stop the tears","cn":"父母经常感到无能为力，因为他们知道无论多少次拥抱也无法止住眼泪。"}}]},"examples":[{"en":"They watched helplessly as their home went up in flames.","cn":"他们无奈地看着自己的家被大火吞没。"},{"en":"It's natural to feel helpless against such abuse.","cn":"对这种虐待感到无能为力是自然的。"}]},"hidden":{"oxford":{"phon":"ˈhɪdn","pos":"adjective","senses":[{"en":"something that is hidden is kept or located in a place where it cannot be seen","cn":"隐藏的；隐匿的","ex":{"en":"Hidden dangers lurk in the ocean depths.","cn":"海洋深处隐藏着危险。"}},{"en":"secret","cn":"秘密的；保密的；隐蔽的","ex":{"en":"She felt sure the letter had some hidden meaning.","cn":"她确信那封信有言外之意。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Hidden is the past participle of hide ."},{"pos":"ADJ 形容词","cn":"难以看见（或发现）的;隐藏的","en":"Hidden facts, feelings, activities, or problems are not easy to notice or discover.","ex":{"en":"Under all the innocent fun, there are hidden dangers, especially for children","cn":"在所有简单无害的娱乐项目背后都隐藏着危险，特别是对儿童而言。"}},{"pos":"ADJ 形容词","cn":"（地方）隐秘的","en":"A hidden place is difficult to find.","ex":{"en":"As you descend, suddenly you see at last the hidden waterfall.","cn":"一直往下走，最终你会突然看到那条隐秘的瀑布。"}}]},"media":{"uk":"media/ldoce/hwd/bre/6/hidden0205.mp3","us":"media/ldoce/hwd/ame/c/laadhidden.mp3"},"examples":[{"en":"Some areas can hold hidden dangers for dogs.","cn":"一些区域可能对狗有隐伏的危险。"},{"en":"the hidden meaning behind his words","cn":"他的言外之意"}],"base":"hide"},"hinder":{"oxford":{"phon":"ˈhɪndə(r)","pos":"verb","senses":[{"en":"to make it difficult for somebody to do something or for something to happen","cn":"阻碍；妨碍；阻挡","ex":{"en":"a political situation that hinders economic growth","cn":"妨碍经济发展的政治局面"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"阻碍;妨碍;阻止","en":"If something hinders you, it makes it more difficult for you to do something or make progress.","ex":{"en":"Does the fact that your players are part-timers help or hinder you?","cn":"队员们都是兼职的，这对你有利还是不利？"}},{"pos":"VERB 动词","cn":"牵制，束缚（动作）","en":"If something hinders your movement, it makes it difficult for you to move forward or move around.","ex":{"en":"A thigh injury increasingly hindered her mobility","cn":"大腿受伤使她行动愈发不便。"}}]},"media":{"uk":"media/uk/hinder__gb_1.mp3","us":"media/us/hinder__us_1.mp3"},"examples":[{"en":"Some teachers felt hindered by a lack of resources.","cn":"有些教师因资源不足而感到困难重重。"},{"en":"An injury was hindering him from playing his best.","cn":"受伤后他无法发挥出最高水平。"}]},"haphazardly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done in a careless and lazy way - use this about someone's work or the way someone writes or speaks","cn":""},{"en":"done extremely carelessly and quickly, without paying any attention to the correct ways of working","cn":""}]},"media":{"uk":"media/uk/haphazardly__gb_1.mp3","us":"media/us/haphazardly__us_1.mp3"},"oxford":{"phon":"hæpˈhæzədli","pos":"adverb","senses":[{"en":"in a way that has no particular order or plan; in a way that is not organized well","cn":"没有特别的顺序或者计划；以一种没有组织好的方式","ex":{"en":"Vehicles are parked haphazardly on the narrow streets.","cn":"狭窄的街道上，车辆随意停放。"}}]}},"hypothetical":{"oxford":{"phon":"ˌhaɪpəˈθetɪkl","pos":"adjective","senses":[{"en":"based on situations or ideas that are possible and imagined rather than real and true","cn":"假设的；假定的","ex":{"en":"a hypothetical question/situation/example","cn":"假定的问题／情况／例子"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（基于）假设的;假定的","en":"If something is hypothetical, it is based on possible ideas or situations rather than actual ones.","ex":{"en":"Let's look at a hypothetical situation in which Carol, a recovering cocaine addict, gets invited to a party.","cn":"让我们假设这样一种情景，卡萝尔，一位正在康复的可卡因成瘾者，应邀去参加一个聚会。"}}]},"media":{"uk":"media/uk/hypothetical__gb_1.mp3","us":"media/us/hypothetical__us_1.mp3"},"examples":[{"en":"Let us take the hypothetical case of Sheila, a mother of two …","cn":"我们且举关于希拉这个假定的例子，她是一位有两个孩子的母亲 …"},{"en":"I wasn't asking about anybody in particular — it was a purely hypothetical question.","cn":"我并没有问到具体某个人，那不过是个纯粹假设性的问题。"}]},"had":{"lemma":"have","media":{"uk":"media/uk/had__gb_1.mp3","us":"media/us/had__us_1.mp3"}},"home":{"media":{"img":["media/pic/homes_comp.jpg","media/thumb/semidetached.jpg"],"uk":"media/uk/home__gb_1.mp3","us":"media/us/home__us_1.mp3"},"oxford":{"phon":"həʊm","pos":"noun","senses":[{"en":"the house or flat that you live in, especially with your family","cn":"家；住所","g":"[countable, uncountable]","sc":"house, etc.","ex":{"en":"Old people prefer to stay in their own homes.","cn":"老年人喜欢待在自己家中。"}},{"en":"a house or flat, etc., when you think of it as property that can be bought and sold","cn":"（可买卖的）房子，住宅，寓所","g":"[countable]","lab":"British English","sc":"house, etc.","ex":{"en":"a holiday/summer home","cn":"假日／消夏寓所"}},{"en":"the town, district, country, etc. that you come from, or where you are living and that you feel you belong to","cn":"家乡；故乡；定居地","g":"[countable, uncountable]","sc":"town/country","ex":{"en":"I often think about my friends back home.","cn":"我常常想起老家的朋友。"}},{"en":"used to refer to a family living together, and the way it behaves","cn":"家庭","g":"[countable]","sc":"family","ex":{"en":"She came from a violent home.","cn":"她出身于一个有暴力行为的家庭。"}},{"en":"a place where people who cannot care for themselves live and are cared for by others","cn":"养老院；养育院","g":"[countable]","sc":"for old people/children","ex":{"en":"a children’s home","cn":"儿童之家"}},{"en":"a place where pets with no owner are taken care of","cn":"收养所","g":"[countable]","sc":"for pets","ex":{"en":"a dogs’/cats’ home","cn":"狗／猫之家"}},{"en":"the place where a plant or animal usually lives; the place where somebody/something can be found","cn":"生息地；栖息地；产地","g":"[singular, uncountable]","sc":"of plant/animal","ex":{"en":"This region is the home of many species of wild flower.","cn":"这个地区有很多种类的野花。"}},{"en":"a place where an object is kept","cn":"（存放东西的）地方，场所","g":"[countable]","lab":"informal","sc":"where something is kept","ex":{"en":"We haven't found a home for all our books yet.","cn":"我们还没有找到地方存放我们所有的书。"}},{"en":"the place where something was first discovered, made or invented","cn":"发源地；发祥地","g":"[singular]","sc":"where something first done","ex":{"en":"New Orleans, the home of jazz","cn":"新奥尔良，爵士乐的发源地"}},{"en":"to or at the place where you live","cn":"到家；向家；在家","lab":"North American English","sc":"where you live","ex":{"en":"Come on, it's time to go home.","cn":"快点，该回家了。"},"pos":"adverb"},{"en":"into the correct position","cn":"到正确的位置","sc":"into correct position","ex":{"en":"She leaned on the door and pushed the bolt home.","cn":"她倚在门上，上好了门闩。"},"pos":"adverb"},{"en":"connected with the place where you live","cn":"家的；家庭的","sc":"where you live","ex":{"en":"home life (= with your family)","cn":"家庭生活"},"pos":"adjective"},{"en":"made or used at home","cn":"在家里做的；家用的","sc":"made/used at home","ex":{"en":"We have a home movie of my dad teaching me to swim.","cn":"我们有一部爸爸教我学游泳的自制家庭影片。"},"pos":"adjective"},{"en":"connected with your own country rather than foreign countries","cn":"本国的；国内的","lab":"especially British English","sc":"own country","ex":{"en":"products for the home market","cn":"为国内市场生产的产品"},"pos":"adjective"},{"en":"connected with a team’s own sports ground","cn":"主场的","sc":"in sport","ex":{"en":"a home game/match/win","cn":"主场赛事／比赛／胜利"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"家;住宅;住所","en":"Someone's home is the house or flat where they live.","ex":{"en":"Last night they stayed at home and watched TV","cn":"昨晚他们呆在了家里看电视。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（强调归属感的）家，家乡，祖国","en":"You can use home to refer in a general way to the house, town, or country where someone lives now or where they were born, often to emphasize that they feel they belong in that place.","ex":{"en":"She gives frequent performances of her work, both at home and abroad","cn":"她经常在国内外演出自己的作品。"}},{"pos":"ADV 副词","cn":"向家;在家","en":"Home means to or at the place where you live.","ex":{"en":"His wife wasn't feeling too well and she wanted to go home","cn":"他的妻子感到有些不舒服，想要回家。"}},{"pos":"ADJ 形容词","cn":"在家里做（或进行）的","en":"Home means made or done in the place where you live.","ex":{"en":"...cheap but healthy home cooking","cn":"便宜而健康的家常菜"}},{"pos":"ADJ 形容词","cn":"本国的;国内的","en":"Home means relating to your own country as opposed to foreign countries.","ex":{"en":"Europe's software companies still have a growing home market.","cn":"欧洲软件公司的国内市场仍在增长中。"}},{"pos":"N-COUNT 可数名词","cn":"养老院;疗养院;养育院","en":"A home is a large house or institution where a number of people live and are looked after, instead of living in their own houses or flats. They usually live there because they are too old or ill to look after themselves or for their families to care for them.","ex":{"en":"It's going to be a home for handicapped children.","cn":"这将是一家残疾儿童福利院。"}},{"pos":"N-COUNT 可数名词","cn":"家庭","en":"You can refer to a family unit as a home .","ex":{"en":"She had, at any rate, provided a peaceful and loving home for Harriet","cn":"她至少为哈丽雅特提供了一个安宁关爱的家。"}},{"pos":"N-SING 单数名词","cn":"发源地;发祥地;产地;生息地","en":"If you refer to the home of something, you mean the place where it began or where it is most typically found.","ex":{"en":"This south-west region of France is the home of claret.","cn":"法国西南部的这个地区是干红葡萄酒的产地。"}},{"pos":"N-COUNT 可数名词","cn":"适于存放…的地方","en":"If you find a home for something, you find a place where it can be kept.","ex":{"en":"The equipment itself is getting smaller, neater and easier to find a home for.","cn":"该设备本身正变得越来越小，越来越轻巧，也越来越便于存放。"}},{"pos":"ADV 副词","cn":"击中要害地;彻底地;深切地;切实地","en":"If you press, drive, or hammer something home, you explain it to people as forcefully as possible.","ex":{"en":"It is now up to all of us to debate this issue and press home the argument.","cn":"现在要靠我们大家对此问题进行辩论，并尽可能将论点阐述清楚。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（比赛的）主场","en":"When a sports team plays at home, they play a game on their own ground, rather than on the opposing team's ground.","ex":{"en":"I scored in both games against Barcelona; we drew at home and beat them away.","cn":"我在两场对阵巴塞罗那队的比赛中都进了球;我们在主场战平，在客场赢了他们。"}},{"pos":"PHRASE 短语","cn":"像在家一样舒适自在;无拘束","en":"If you feel at home, you feel comfortable in the place or situation that you are in.","ex":{"en":"He spoke very good English and appeared pleased to see us, and we soon felt quite at home","cn":"他英语说得非常好，见到我们显得很高兴，我们很快就不拘束了。"}},{"pos":"PHRASE 短语","cn":"使清楚地领会;使深切地感到","en":"To bring something home to someone means to make them understand how important or serious it is.","ex":{"en":"Their sobering conversation brought home to everyone present the serious and worthwhile work the Red Cross does.","cn":"他们发人深省的对话使在座的每个人都清楚地认识到红十字会所从事的严肃而有价值的工作。"}},{"pos":"PHRASE 短语","cn":"大功告成;稳操胜券","en":"If you say that someone is, in British English home and dry, or in American English home free, you mean that they have been successful or that they are certain to be successful.","ex":{"en":"The prime minister and the moderates are not yet home and dry.","cn":"首相和温和派还未大功告成。"}},{"pos":"PHRASE 短语","cn":"切中要害;使人接受（或认清）事实","en":"If a situation or what someone says hits home or strikes home, people accept that it is real or true, even though it may be painful for them to realize.","ex":{"en":"Did the reality of war finally hit home?","cn":"人们终于认清战争的现实了吗？"}},{"pos":"PHRASE 短语","cn":"像家里一样舒适的地方","en":"You can say a home from home in British English or a home away from home in American English to refer to a place in which you are as comfortable as in your own home.","ex":{"en":"Many cottages are a home from home, offering microwaves, dishwashers, tvs and videos.","cn":"很多度假屋都像自家一样，里面有微波炉、洗碗机、电视机和录像机。"}},{"pos":"CONVENTION 惯用语","cn":"请别拘束;请随便","en":"If you say to a guest 'Make yourself at home', you are making them feel welcome and inviting them to behave in an informal, relaxed way."},{"pos":"PHRASE 短语","cn":"平平常常;没有什么特别有趣的地方","en":"If you say that something is nothing to write home about, you mean that it is not very interesting or exciting.","ex":{"en":"So a dreary Monday afternoon in Walthamstow is nothing to write home about, right?","cn":"这么说，在沃尔瑟姆斯托度过的一个沉闷的周一下午没什么值得大书特书的，是吗？"}},{"pos":"PHRASE 短语","cn":"击中目标","en":"If something that is thrown or fired strikes home, it reaches its target.","ex":{"en":"Only two torpedoes struck home.","cn":"只有两枚鱼雷击中了目标。"}},{"pos":"","cn":"","en":"相关词组：home in"}]},"examples":[{"en":"The television pictures brought home to us the full horror of the attack.","cn":"电视画面使我们充分地了解这次袭击有多么恐怖。"},{"en":"He had always wanted a real home with a wife and children.","cn":"他一直想要一个有妻子和孩子的真正的家庭。"}]},"hold":{"media":{"uk":"media/uk/hold__gb_1.mp3","us":"media/us/hold__us_1.mp3","img":["media/ldoce/img/hold.jpg"]},"oxford":{"phon":"həʊld","pos":"verb","senses":[{"en":"to have somebody/something in your hand, arms, etc.","cn":"拿着；抓住；抱住；夹着","g":"[transitive]","sc":"in hand/arms","ex":{"en":"She was holding a large box.","cn":"她提着一只大箱子。"}},{"en":"to put your hand on part of your body, usually because it hurts","cn":"抱住，捂住，按住（受伤的身体部位等）","g":"[transitive]","sc":"in hand/arms","ex":{"en":"She groaned and held her head.","cn":"她呻吟着，用手抱住头。"}},{"en":"to keep somebody/something in a particular position","cn":"使保持（在某位置）","g":"[transitive]","sc":"in position","ex":{"en":"Hold your head up.","cn":"抬起头来。"}},{"en":"to support the weight of somebody/something","cn":"支撑…的重量","g":"[transitive]","sc":"support","ex":{"en":"I don't think that branch will hold your weight.","cn":"我觉得那根树枝撑不住你的重量。"}},{"en":"to have enough space for something/somebody; to contain something/somebody","cn":"容纳；包含","g":"[transitive]","sc":"contain","ex":{"en":"This barrel holds 25 litres.","cn":"这只桶能盛 25 升。"}},{"en":"to have or offer something; to be going to bring something","cn":"拥有；提供；带来","sc":"contain","ex":{"en":"I don't know what the future holds.","cn":"我不知道未来会怎样。"}},{"en":"to have a meeting, competition, conversation, etc.","cn":"召开；举行；进行","g":"[transitive]","sc":"meeting","ex":{"en":"Each month she holds a meeting with her entire staff.","cn":"每个月她都与全体员工举行一次会议。"}},{"en":"to have something you have gained or achieved","cn":"获得；赢得","g":"[transitive]","sc":"record/title","ex":{"en":"Who holds the world record for the long jump?","cn":"跳远世界纪录的保持者是谁？"}},{"en":"to have a particular job or position","cn":"担任；任职","g":"[transitive]","sc":"job","ex":{"en":"How long has he held office?","cn":"他任职有多久了？"}},{"en":"to keep somebody and not allow them to leave","cn":"监禁；拘留","g":"[transitive]","sc":"somebody prisoner","ex":{"en":"Police are holding two men in connection with last Thursday's bank raid.","cn":"警方拘留了两名与上星期四的银行抢劫案有关的男子。"}},{"en":"to keep somebody’s attention or interest","cn":"使（注意力或兴趣）持续不减；吸引住","g":"[transitive]","sc":"keep","ex":{"en":"There wasn't much in the museum to hold my attention.","cn":"博物馆中没有很多让我感兴趣的东西。"}},{"en":"to keep something at the same level, rate, speed, etc.; to stay at the same level, rate, etc.","cn":"（使）保持同样程度（或比率、速度等）","g":"[transitive, intransitive]","sc":"keep","ex":{"en":"Hold your speed at 70.","cn":"把速度保持在 70。"}},{"en":"to keep something so that it can be used later","cn":"保存；存储","g":"[transitive]","sc":"keep","ex":{"en":"Employees do not have access to personal records held on computer.","cn":"雇员没有机会看到存储在计算机中的个人记录。"}},{"en":"to wait until you can speak to the person you have phoned","cn":"（打电话时）等待，不挂断","g":"[intransitive, transitive]","sc":"on phone","ex":{"en":"That extension is busy right now. Can you hold?","cn":"分机现在占线。您能等一会吗？"}},{"en":"to own or have something","cn":"拥有；持有","g":"[transitive]","lab":"rather formal","sc":"own","ex":{"en":"Employees hold 30% of the shares.","cn":"雇员持有 30% 的股份。"}},{"en":"to defend something against attack; to have control of something","cn":"守卫；控制","g":"[transitive]","sc":"control","ex":{"en":"The rebels held the radio station.","cn":"叛乱者占据了电台。"}},{"en":"to remain strong and safe or in position","cn":"承受住；坚持住；保持原位","g":"[intransitive]","sc":"remain","ex":{"en":"They were afraid the dam wouldn't hold.","cn":"他们担心大坝会承受不住。"}},{"en":"to remain the same","cn":"保持不变","g":"[intransitive]","sc":"remain","ex":{"en":"How long will the fine weather hold?","cn":"好天气会持续多久？"}},{"en":"to have a belief or an opinion about somebody/something","cn":"怀有，持有（信念、意见）","g":"[transitive]","sc":"opinion","ex":{"en":"He holds strange views on education.","cn":"他对教育的看法不同寻常。"}},{"en":"to consider that something is true","cn":"认为；相信","g":"[transitive]","lab":"formal","sc":"opinion","ex":{"en":"I still hold that the government's economic policies are mistaken.","cn":"我仍然认为政府的经济政策是错误的。"}},{"en":"to be in close contact with the road and easy to control, especially when driven fast","cn":"（尤指高速行驶时）平稳行驶","g":"[transitive]","sc":"road/course"},{"en":"to continue to move in a particular direction","cn":"保持航线","g":"[transitive]","sc":"road/course"},{"en":"to make a note continue for a particular time","cn":"延长，继续唱（某音符）","g":"[transitive]","sc":"in music"},{"en":"be able to drink a reasonable amount of alcohol without becoming drunk","cn":"有一定的酒量","sc":"alcohol","ex":{"en":"I can hold my drink as well as anyone.","cn":"我的酒量不比任何人差。"}},{"en":"to win a game in which you are serving","cn":"保住发球局，保发（发球方在该局获胜）","g":"[transitive, intransitive]","sc":"in sport","ex":{"en":"Zverev held serve to take the set.","cn":"兹维列夫保住发球胜盘。"}},{"en":"used to tell somebody to stop doing something or not to do something","cn":"停下；不要做","g":"[transitive]","lab":"North American English, informal，，","sc":"stop","ex":{"en":"Hold your fire! (= don't shoot)","cn":"别开枪！"}},{"en":"the action of holding somebody/something; the way you are holding somebody/something","cn":"抓；握；拿；支撑","g":"[singular, uncountable]","sc":"with hand","ex":{"en":"His hold on her arm tightened.","cn":"他把她的胳膊抓得更紧了。"},"pos":"noun"},{"en":"a particular way of holding somebody, especially in a fight or in a sport such as wrestling","cn":"压，握，锁，扣（尤指打斗或摔跤等运动的招式）","g":"[countable]","sc":"in sport/a fight","ex":{"en":"He still had me in a tight hold.","cn":"他仍然紧紧锁住我。"},"pos":"noun"},{"en":"influence, power or control over somebody/something","cn":"影响；权威；控制","g":"[singular]","sc":"power/control","ex":{"en":"He struggled to get a hold of his anger.","cn":"他竭力压制自己的怒火。"},"pos":"noun"},{"en":"a place where you can put your hands or feet when climbing","cn":"支撑点（可手攀或脚踏的地方）","g":"[countable]","sc":"in climbing","ex":{"en":"She put her foot firmly in the hold and pulled herself up.","cn":"她把脚牢牢地踩在船舱里，然后把自己拉了起来。"},"pos":"noun"},{"en":"the part of a ship or plane where the goods being carried are stored","cn":"货舱","g":"[countable]","sc":"on ship/plane","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拿着;握住;托住","en":"When you hold something, you carry or support it, using your hands or your arms.","ex":{"en":"Hold the knife at an angle","cn":"斜握住刀。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（紧紧的）拿，握","en":"Hold is used in expressions such as grab hold of ,catch hold of, and get hold of, to indicate that you close your hand tightly around something, for example to stop something moving or falling.","ex":{"en":"I was woken up by someone grabbing hold of my sleeping bag","cn":"有人猛地抓住了我的睡袋，把我惊醒了。"}},{"pos":"VERB 动词","cn":"（通常为表示喜爱或安慰而）拥抱，抱住","en":"When you hold someone, you put your arms round them, usually because you want to show them how much you like them or because you want to comfort them.","ex":{"en":"If only he would hold her close to him.","cn":"要是他能将她拥入怀中就好了。"}},{"pos":"VERB 动词","cn":"用力使（某人）不得动弹","en":"If you hold someone in a particular position, you use force to keep them in that position and stop them from moving.","ex":{"en":"He then held the man in an armlock until police arrived","cn":"然后他反扭住那名男子的手臂让他动弹不得，直到警察赶到。"}},{"pos":"N-COUNT 可数名词","cn":"（使某人不得动弹的）抓住，夹住","en":"A hold is a particular way of keeping someone in a position using your own hands, arms, or legs.","ex":{"en":"...use of an unauthorized hold on a handcuffed suspect.","cn":"对戴手铐的嫌疑犯使用非法的擒拿方式"}},{"pos":"VERB 动词","cn":"（常指疼伤痛而）按住，捂住","en":"When you hold a part of your body, you put your hand on or against it, often because it hurts.","ex":{"en":"Soon she was crying bitterly about the pain and was holding her throat.","cn":"很快她痛得大哭起来，同时用手捂着自己的喉咙。"}},{"pos":"VERB 动词","cn":"使（身体部位）保持（某种姿势）","en":"When you hold a part of your body in a particular position, you put it into that position and keep it there.","ex":{"en":"Hold your hands in front of your face","cn":"把双手举在面前。"}},{"pos":"VERB 动词","cn":"把…固定住","en":"If one thing holds another in a particular position, it keeps it in that position.","ex":{"en":"...the wooden wedge which held the heavy door open","cn":"卡住沉重的门不让它关上的木楔"}},{"pos":"VERB 动词","cn":"存放;盛放;装","en":"If one thing is used to hold another, it is used to store it.","ex":{"en":"Two knife racks hold her favourite knives.","cn":"两个刀架上存放着她最心爱的刀具。"}},{"pos":"N-COUNT 可数名词","cn":"（船、飞机等的）货舱，行李舱","en":"In a ship or aeroplane, a hold is a place where cargo or luggage is stored.","ex":{"en":"A fire had been reported in the cargo hold.","cn":"行李舱内报称起火了。"}},{"pos":"VERB 动词","cn":"储备;储存","en":"If a place holds something, it keeps it available for reference or for future use.","ex":{"en":"The Small Firms Service holds an enormous amount of information on any business problem","cn":"小型企业服务处备有关于各种商务问题的海量信息。"}},{"pos":"VERB 动词","cn":"容纳得下","en":"If something holds a particular amount of something, it can contain that amount.","ex":{"en":"The small bottles don't seem to hold much","cn":"这些小瓶子好像装不下多少。"}},{"pos":"VERB 动词","cn":"大量喝（酒）而不醉","en":"If you can hold your drink, you are able to drink large quantities of alcohol without becoming ill or getting drunk.","ex":{"en":"...but you had to be able to hold your liquor.","cn":"但你得能喝酒才行。"}},{"pos":"VERB 动词","cn":"（车辆）抓（地）","en":"If a vehicle holds the road well, it remains in close contact with the road and can be controlled safely and easily.","ex":{"en":"I thought the car held the road really well.","cn":"我认为这辆车抓地性能真的非常好。"}},{"pos":"VERB 动词","cn":"持有，怀有（观点、信念等）","en":"Hold is used with words and expressions indicating an opinion or belief, to show that someone has a particular opinion or believes that something is true.","ex":{"en":"He held firm opinions which usually conflicted with my own","cn":"他对自己的观点坚定不移，而这些观点通常和我的相左。"}},{"pos":"VERB 动词","cn":"带给人，使人感到（害怕、神秘等）","en":"Hold is used with words such as 'fear' or 'mystery' to indicate someone's feelings towards something, as if those feelings were a characteristic of the thing itself.","ex":{"en":"Death doesn't hold any fear for me","cn":"死亡对我来说并不可怕。"}},{"pos":"VERB 动词","cn":"担任（职务）;掌握（权力）;负有（责任）","en":"Hold is used with nouns such as 'office', 'power', and 'responsibility' to indicate that someone has a particular position of power or authority.","ex":{"en":"She has never held ministerial office","cn":"她从未担任过部长级职务。"}},{"pos":"VERB 动词","cn":"持有（许可、票证等）;拥有（学位等）","en":"Hold is used with nouns such as 'permit', 'degree', or 'ticket' to indicate that someone has a particular document that allows them to do something.","ex":{"en":"Applicants should normally hold a good Honours degree","cn":"申请人通常应该拥有优秀荣誉学位。"}},{"pos":"VERB 动词","cn":"举行（聚会、会议、会谈、选举、审判等）","en":"Hold is used with nouns such as 'party', 'meeting', 'talks', 'election', and 'trial' to indicate that people are organizing a particular activity.","ex":{"en":"The country will hold democratic elections within a year","cn":"该国将在一年之内举行民主选举。"}},{"pos":"V-RECIP 相互动词","cn":"进行（谈话、采访、会商等）","en":"Hold is used with nouns such as 'conversation', 'interview', and 'talks' to indicate that two or more people meet and discuss something.","ex":{"en":"The Prime Minister, is holding consultations with his colleagues to finalise the deal","cn":"首相正在和同僚进行磋商，以敲定该协议。"}},{"pos":"VERB 动词","cn":"持有（股份、股票等）","en":"Hold is used with nouns such as 'shares' and 'stock' to indicate that someone owns a particular proportion of a business.","ex":{"en":"The group said it continues to hold 1,774,687 Vons shares","cn":"该集团称其继续持有1,774,687股冯氏公司的股份。"}},{"pos":"VERB 动词","cn":"占有（领先地位、优势等）","en":"Hold is used with words such as 'lead' or 'advantage' to indicate that someone is winning or doing well in a contest.","ex":{"en":"He continued to hold a lead in Angola's presidential race","cn":"他继续在安哥拉总统大选中占据领先地位。"}},{"pos":"VERB 动词","cn":"吸引住（注意力）;保持（兴趣）","en":"Hold is used with nouns such as 'attention' or 'interest' to indicate that what you do or say keeps someone interested or listening to you.","ex":{"en":"If you want to hold someone's attention, look them directly in the eye but don't stare","cn":"如果想吸引住某人的注意力，就要直视他们的眼睛，但别死盯着。"}},{"pos":"VERB 动词","cn":"认定（…负有责任）;归（咎）于","en":"If you hold someone responsible, liable, or accountable for something, you will blame them if anything goes wrong.","ex":{"en":"It's impossible to hold any individual responsible.","cn":"不可能归咎于任何个人。"}},{"pos":"VERB 动词","cn":"关押;扣留","en":"If someone holds you in a place, they keep you there as a prisoner and do not allow you to leave.","ex":{"en":"The inside of a van was as good a place as any to hold a kidnap victim","cn":"小货车内是关押被绑架人的好地方。"}},{"pos":"VERB 动词","cn":"（军队、暴乱人群等）占据，控制","en":"If people such as an army or a violent crowd hold a place, they control it by using force.","ex":{"en":"Demonstrators have been holding the square since Sunday.","cn":"示威者从周日起就占领了广场。"}},{"pos":"N-SING 单数名词","cn":"（因握有某人把柄或掌握权力而形成的）控制力，支配力","en":"If you have a hold over someone, you have power or control over them, for example because you know something about them you can use to threaten them or because you are in a position of authority.","ex":{"en":"It's always useful to have a hold over a fellow like Carl May","cn":"能支配像卡尔·梅这样的人总是很有用的。"}},{"pos":"VERB 动词","cn":"（接电话时让对方）稍等，不要挂断","en":"If you ask someone to hold, or to hold the line, when you are answering a telephone call, you are asking them to wait for a short time, for example so that you can find the person they want to speak to.","ex":{"en":"Could you hold the line and I'll just get my pen","cn":"能否请您稍等一会儿，我拿支笔？"}},{"pos":"VERB 动词","cn":"代接（电话）并向受话人转告通话内容","en":"If you hold telephone calls for someone, you do not allow people who phone to speak to that person, but take messages instead.","ex":{"en":"He tells his secretary to hold his calls.","cn":"他让秘书代接电话。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）保持（在一定价值或水平）","en":"If something holds at a particular value or level, or is held there, it is kept at that value or level.","ex":{"en":"OPEC production is holding at around 21.5 million barrels a day","cn":"石油输出国组织的石油产量保持在每天约2,150万桶。"}},{"pos":"VERB 动词","cn":"持续发出（声音、音符）","en":"If you hold a sound or musical note, you continue making it.","ex":{"en":"...a voice which hit and held every note with perfect ease and clarity.","cn":"非常自如清晰地唱出并拉长每个音符的歌喉"}},{"pos":"VERB 动词","cn":"延迟;推迟","en":"If you hold something such as a train, a lift, or an elevator, you delay it.","ex":{"en":"A London Underground spokesman defended the decision to hold the train until police arrived.","cn":"伦敦地铁公司的发言人为推迟发车直到警方赶来的决定作了辩解。"}},{"pos":"VERB 动词","cn":"（提议、邀请等）有效","en":"If an offer or invitation still holds, it is still available for you to accept.","ex":{"en":"Does your offer still hold?","cn":"你的提议仍然有效吗？"}},{"pos":"VERB 动词","cn":"（好形势）保持不变，持续","en":"If a good situation holds, it continues and does not get worse or fail.","ex":{"en":"Our luck couldn't hold for ever","cn":"我们不会永远走运。"}},{"pos":"VERB 动词","cn":"（论点、理论等）站得住脚，成立","en":"If an argument or theory holds, it is true or valid, even after close examination.","ex":{"en":"Today, most people think that argument no longer holds","cn":"今天，大多数人认为那个论点已经站不住脚了。"}},{"pos":"VERB 动词","cn":"（在重压下）保持不倒，支撑住","en":"If part of a structure holds, it does not fall or break although there is a lot of force or pressure on it.","ex":{"en":"How long would the roof hold?","cn":"房顶能支撑多久？"}},{"pos":"VERB 动词","cn":"（法规等）适用，有效","en":"If laws or rules hold, they exist and remain in force.","ex":{"en":"These laws also hold for universities.","cn":"这些法律也适用于各大学。"}},{"pos":"VERB 动词","cn":"坚持（观点或信念）","en":"If you say that you hold to a particular opinion or belief, you are stating firmly that you continue to have that opinion or belief.","ex":{"en":"I hold to my belief that people should be allowed to have private lives","cn":"我坚信应该允许人们拥有自己的私生活。"}},{"pos":"VERB 动词","cn":"遵守，恪守（承诺或高尚的行为准则）","en":"If you hold to a promise or to high standards of behaviour, you keep that promise or continue to behave according to those standards.","ex":{"en":"Will the President be able to hold to this commit-ment?","cn":"总统能恪守此承诺吗？"}},{"pos":"VERB 动词","cn":"使遵守，使恪守（承诺或高尚的行为准则）","en":"If someone or something holds you to a promise or to high standards of behaviour, they make you keep that promise or those standards.","ex":{"en":"I would say it's almost time to hold him to that promise","cn":"我认为已经差不多是时候让他兑现那个承诺了。"}},{"pos":"PHRASE 短语","cn":"（尤指当众）滔滔不绝地说","en":"If you hold forth on a subject, you speak confidently and for a long time about it, especially to a group of people.","ex":{"en":"Barry was holding forth on politics.","cn":"巴里正在滔滔不绝地谈论政治。"}},{"pos":"PHRASE 短语","cn":"（通常指好不容易）得到，获得","en":"If you get hold of an object or information, you obtain it, usually after some difficulty.","ex":{"en":"It is hard to get hold of guns in this country.","cn":"在这个国家里要搞到枪支是很困难的。"}},{"pos":"PHRASE 短语","cn":"领会;弄懂","en":"If you get hold of a fact or a subject, you learn about it and understand it well.","ex":{"en":"He first had to get hold of some basic facts.","cn":"他首先得弄清一些基本事实。"}},{"pos":"PHRASE 短语","cn":"设法和…取得联络","en":"If you get hold of someone, you manage to contact them.","ex":{"en":"The only electrician we could get hold of was miles away.","cn":"我们唯一能够联络到的电工离这里有好几英里远。"}},{"pos":"CONVENTION 惯用语","cn":"停下;慢着","en":"If you say 'Hold it', you are telling someone to stop what they are doing and to wait.","ex":{"en":"Hold it! Don't move!","cn":"停下！别动！"}},{"pos":"PHRASE 短语","cn":"延迟;暂缓;搁置","en":"If you put something on hold, you decide not to do it, deal with it, or change it now, but to leave it until later.","ex":{"en":"He put his retirement on hold until he had found a solution","cn":"他推迟了退休，直到他找到了解决办法。"}},{"pos":"PHRASE 短语","cn":"（面对攻击、反对等）顶住，坚持住","en":"If you hold your own, you are able to resist someone who is attacking or opposing you.","ex":{"en":"The Frenchman held his own against the challenger.","cn":"这名法国人顶住了挑战者的进攻。"}},{"pos":"PHRASE 短语","cn":"与…相匹敌;不比…逊色","en":"If you can do something well enough to hold your own, you do not appear foolish when you are compared with someone who is generally thought to be very good at it.","ex":{"en":"She can hold her own against almost any player.","cn":"她几乎能和任何一名选手一较高下。"}},{"pos":"PHRASE 短语","cn":"不动","en":"If you hold still, you do not move.","ex":{"en":"Can't you hold still for a second?","cn":"你一秒钟不动都做不到吗？"}},{"pos":"PHRASE 短语","cn":"完全控制;彻底影响","en":"If something takes hold, it gains complete control or influence over a person or thing.","ex":{"en":"She felt a strange excitement taking hold of her","cn":"她浑身感到一股莫名的兴奋。"}},{"pos":"PHRASE 短语","cn":"抓紧;抓牢;扶好（以站稳）","en":"If you hold tight, you put your hand round or against something in order to prevent yourself from falling over. A bus driver might say 'Hold tight!' to you if you are standing on a bus when it is about to move.","ex":{"en":"He held tight to the rope","cn":"他牢牢抓住绳子。"}},{"pos":"PHRASE 短语","cn":"暂不行动","en":"If you hold tight, you do not immediately start a course of action that you have been planning or thinking about.","ex":{"en":"The unions have circulated their branches, urging members to hold tight until a national deal is struck.","cn":"各工会已经在其分支机构中作了宣传工作，敦促会员等到达成全国性协议后再行动。"}},{"pos":"","cn":"","en":"to hold something at bay→see: ; to hold your breath→see: ; can't hold a candle to→see: ; to hold something in check→see: ; to hold court→see: ; to hold fast→see: ; to hold the fort→see: ; what the future holds→see: ; to hold your ground→see: ; to hold your peace→see: ; to hold someone to ransom→see: ; to hold sway→see: ; to hold your tongue→see: ;"},{"pos":"","cn":"","en":"相关词组：hold against hold back hold down hold in hold off hold on hold on to hold out hold over hold together hold up hold with"}]},"examples":[{"en":"Do you think that mixed-ability classes hold back the better students?","cn":"你认为把能力参差的学生混在一班会妨碍高水平学生进步吗？"},{"en":"She held off all the last-minute challengers and won the race in a new record time.","cn":"她最后一刻甩掉了所有对手，以新的纪录赢得了赛跑冠军。"}]},"heyday":{"media":{"uk":"media/uk/heyday__gb_1.mp3","us":"media/us/heyday__us_1.mp3"},"oxford":{"phon":"ˈheɪdeɪ","pos":"noun","senses":[{"en":"the time when somebody/something had most power or success, or was most popular","cn":"最为强大（或成功、繁荣）的时期","ex":{"en":"In its heyday, the company ran trains every fifteen minutes.","cn":"公司在最兴隆时期每隔十五分钟就开出一列火车。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"全盛时期","en":"Someone's heyday is the time when they are most powerful, successful, or popular.","ex":{"en":"In its heyday, the studio's boast was that it had more stars than there are in heaven.","cn":"在其全盛时期，该制片公司夸口说，他们旗下的明星比天上的星星还要多。"}}]},"examples":[{"en":"In its heyday, the company ran trains every fifteen minutes.","cn":"公司在最兴隆时期每隔十五分钟就开出一列火车。"},{"en":"a fine example from the heyday of Italian cinema","cn":"意大利电影业全盛期的一部优秀代表作"}]},"humorous":{"media":{"uk":"media/uk/humorous__gb_1.mp3","us":"media/us/humorous__us_1.mp3"},"oxford":{"phon":"ˈhjuːmərəs","pos":"adjective","senses":[{"en":"funny; showing a sense of humour","cn":"滑稽有趣的；有幽默感的","ex":{"en":"He gave a humorous account of their trip to Spain.","cn":"他饶有风趣地讲述了他们的西班牙之行。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"滑稽的;（尤指）幽默的,诙谐的","en":"If someone or something is humorous, they are amusing, especially in a clever or witty way.","ex":{"en":"He was quite humorous, and I liked that about him.","cn":"他很幽默，我喜欢他这一点。"}}]},"examples":[{"en":"He gave a humorous account of their trip to Spain.","cn":"他饶有风趣地讲述了他们的西班牙之行。"},{"en":"The poem humorously describes local characters and traditions.","cn":"那首诗幽默地描述了当地的人物和传统。"}]},"hotly":{"oxford":{"phon":"ˈhɒtli","pos":"adverb","senses":[{"en":"done in an angry or excited way or with a lot of strong feeling","cn":"愤怒地；激动地；强烈地","ex":{"en":"a hotly debated topic","cn":"激烈辩论的话题"}},{"en":"done with a lot of energy and determination","cn":"起劲地；坚决地","ex":{"en":"hotly contested elections","cn":"竞争激烈的选举"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"激烈地;愤怒地;强烈地","en":"If people discuss, argue, or say something hotly, they speak in a lively or angry way, because they feel strongly.","ex":{"en":"'You're a fool, then,' she said hotly","cn":"“那你就是个笨蛋，”她气冲冲地说。"}},{"pos":"ADV-GRADED 副词","cn":"紧追不放地;穷追不舍地","en":"If you are being hotly pursued, someone is trying hard to catch you and is close behind you.","ex":{"en":"He'd snuck out of America hotly pursued by the CIA.","cn":"在中央情报局的穷追不舍下，他已偷偷溜出了美国。"}}]},"media":{"uk":"media/uk/hotly__gb_1.mp3","us":"media/us/hotly__us_1.mp3"},"examples":[{"en":"Recent reports in the press have been hotly denied.","cn":"新闻界最近的报道遭到了坚决否认。"},{"en":"She ran out of the shop, hotly pursued by the store detective.","cn":"她冲出商店，商店侦探在后面猛追。"}]},"hot":{"media":{"uk":"media/uk/hot__gb_1.mp3","us":"media/us/hot__us_1.mp3"},"oxford":{"phon":"hɒt","pos":"adjective","senses":[{"en":"having a high temperature; producing heat","cn":"温度高的；热的","sc":"temperature","ex":{"en":"It's hot today, isn't it?","cn":"今天很热，对吗？"}},{"en":"feeling heat in an unpleasant or uncomfortable way","cn":"觉得闷（或燥、湿）热","sc":"temperature","ex":{"en":"Is anyone too hot?","cn":"有人觉得太热了吗？"}},{"en":"making you feel hot","cn":"使人感到热的","sc":"temperature","ex":{"en":"London was hot and dusty.","cn":"伦敦很热而且灰尘多。"}},{"en":"containing pepper and spices that can produce a burning feeling in your mouth because they have a strong taste and smell","cn":"辣的；辛辣的","sc":"food with spices","ex":{"en":"hot spicy food","cn":"辛辣的食物"}},{"en":"involving a lot of activity, argument or strong feelings","cn":"活跃的；激烈的；强烈的","sc":"causing strong feelings","ex":{"en":"Today we enter the hottest phase of the election campaign.","cn":"今天我们进入了竞选活动最激烈的阶段。"}},{"en":"difficult or dangerous to deal with and making you feel worried or uncomfortable","cn":"艰难的；棘手的；危险的","sc":"difficult/dangerous","ex":{"en":"When things got too hot most journalists left the area.","cn":"事态发展到过于严峻时，大多数记者便撤离了这个地区。"}},{"en":"new, exciting and very popular","cn":"风行的；风靡一时的；走红的","lab":"informal","sc":"popular","ex":{"en":"This is one of the hottest clubs in town.","cn":"这是市里一家最受欢迎的夜总会。"}},{"en":"fresh, very recent and usually exciting","cn":"最新的，新近的（通常令人兴奋）","sc":"news","ex":{"en":"I've got some hot gossip for you!","cn":"我要告诉你一些最新的传闻！"}},{"en":"likely to be successful","cn":"有望成功的","g":"[only before noun]","sc":"tip/favourite","ex":{"en":"She seems to be the hot favourite for the job.","cn":"她似乎是这份工作最热门的人选。"}},{"en":"very good at doing something; knowing a lot about something","cn":"善于（做某事）；（对某事）了解很多","g":"[not before noun]","lab":"informal","sc":"good at something/knowing a lot","ex":{"en":"Don't ask me—I'm not too hot on British history.","cn":"别问我，我不大了解英国历史。"}},{"en":"if somebody has a hot temper they become angry very easily","cn":"易发怒的；（脾气）暴躁的","sc":"anger"},{"en":"feeling or causing sexual excitement","cn":"感到（或引起）性激动的","sc":"sexual excitement","ex":{"en":"You were as hot for me as I was for you.","cn":"当时你想要我，我也想要你。"}},{"en":"containing scenes, statements, etc. that are of an extreme nature and are likely to shock or anger people","cn":"（场面、言辞等）过激的，过火的","sc":"causing shock/anger","ex":{"en":"Some of the nude scenes were regarded as too hot for Broadway.","cn":"有些裸露场面被认为太过火了，不适合在百老汇上演。"}},{"en":"thinking that something is very important and making sure that it always happens or is done","cn":"重视，确保（某事发生或完成）","g":"[not before noun]","sc":"strict","ex":{"en":"They're very hot on punctuality at work.","cn":"他们很重视工作守时。"}},{"en":"having a strong and exciting rhythm","cn":"节奏强的","sc":"music"},{"en":"stolen and difficult to get rid of because they can easily be recognized","cn":"偷来（因容易识别）而难以销赃的","sc":"goods","ex":{"en":"I'd never have touched those phones if I'd known they were hot.","cn":"早知道那些手机是偷来的，我绝不会碰的。"}},{"en":"used in children’s games to say that the person playing is very close to finding a person or thing, or to guessing the correct answer","cn":"快找到了；快猜中了","g":"[not before noun]","sc":"in children’s games","ex":{"en":"You're getting hot!","cn":"你快猜中了！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热的;烫的","en":"Something that is hot has a high temperature.","ex":{"en":"When the oil is hot, add the sliced onion","cn":"油热了后，放入切好的洋葱。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"天气热的;气温高的;炎热的","en":"Hot is used to describe the weather or the air in a room or building when the temperature is high.","ex":{"en":"It was too hot even for a gentle stroll","cn":"天太热，连慢慢散步都吃不消。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）感觉热的","en":"If you are hot, you feel as if your body is at an unpleasantly high temperature.","ex":{"en":"I was too hot and tired to eat more than a few mouthfuls","cn":"我又热又累，只吃了几口就吃不下了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（温度）…高的","en":"You use hot to talk or ask about how high the temperature of something is.","ex":{"en":"They are called incandescent lights, and their colour depends on how hot they are","cn":"这种灯叫做白炽灯，其颜色取决于温度。"}},{"pos":"ADJ 形容词","cn":"（食物）趁热吃的","en":"Hot food is intended to be eaten as soon as it is cooked, as opposed to food that you eat when it has cooled or that you do not cook at all.","ex":{"en":"If you live alone, you might not want to cook a hot meal every day.","cn":"如果单身居住，你可能不会想每天都做一顿热菜热饭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（食物）辣的，辛辣的","en":"You can say that food is hot when it has a strong, burning taste caused by chillies, pepper, or ginger.","ex":{"en":"...hot curries.","cn":"辛辣的咖喱食品"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（议题、话题）热门的，受到广泛关注的","en":"A hot issue or topic is one that is very important at the present time and is receiving a lot of publicity.","ex":{"en":"The role of women in war has been a hot topic of debate in America since the Gulf conflict.","cn":"自海湾冲突以来，妇女在战争中的作用一直是美国国内一个备受争议的热门话题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（消息）刚发布的，最新的，新近的","en":"Hot news is new, recent, and fresh.","ex":{"en":"...eight pages of the latest movies, video releases and the hot news from Tinseltown.","cn":"有关上档电影、发行影碟及好莱坞最新消息的8页报道"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"风行的;走红的;炙手可热的","en":"You can use hot to describe something that is very exciting and that many people want to see, use, obtain, or become involved with.","ex":{"en":"The hottest show in town was the Monet Exhibition at the Art Institute","cn":"全城最轰动的展览是在美术学院举办的莫奈画展。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（常指非法获得的贵重或知名物品）烫手的，难以销赃的","en":"You can use hot to describe something that no one wants to deal with, often because it has been illegally obtained and is very valuable or famous.","ex":{"en":"If too much publicity is given to the theft of important works, the works will become too hot to handle and be destroyed.","cn":"如果重要作品遭窃一事被大肆报道，这些作品就会因为难以转手而被销毁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情形）棘手的;艰难的的","en":"You can describe a situation that is created by a person's behaviour or attitude as hot when it is unpleasant and difficult to deal with.","ex":{"en":"When the streets get too hot for them, they head south in one stolen car after another.","cn":"当他们觉得在街头混不下去了时，就沿途不断偷车换开，一路往南去了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（比赛）激烈的，双方全力以赴的","en":"A hot contest is one that is intense and involves a great deal of activity and determination.","ex":{"en":"It took hot competition from abroad, however, to show us just how good Scottish cashmere really is.","cn":"然而，我们是通过来自国外的激烈竞争才认识到了苏格兰羊绒的优良品质。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"被看好的;最有望获胜的","en":"If a person or team is the hot favourite, people think that they are the one most likely to win a race or competition.","ex":{"en":"Atlantic City is the hot favourite to stage the fight.","cn":"在大西洋城举行这场拳击比赛是众望所归。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（脾气）暴躁的，易怒的","en":"Someone who has a hot temper gets angry very quickly and easily.","ex":{"en":"His hot temper was making it increasingly difficult for others to work with him.","cn":"他的火暴脾气使得别人越来越难以和他合作。"}},{"pos":"PHRASE 短语","cn":"忽冷忽热;反复无常","en":"If someone blows hot and cold, they keep changing their attitude towards something, sometimes being very enthusiastic and at other times expressing no interest at all.","ex":{"en":"The media, meanwhile, has blown hot and cold on the affair.","cn":"同时，媒体对这件事的态度表现得忽冷忽热。"}},{"pos":"PHRASE 短语","cn":"焦虑不安;六神无主;举止失常","en":"If you are hot and bothered, you are so worried and anxious that you cannot think clearly or behave sensibly.","ex":{"en":"Ray was getting very hot and bothered about the idea.","cn":"这个想法让雷心慌意乱。"}},{"pos":"PHRASE 短语","cn":"对…有强烈的情欲","en":"If you say that one person has the hots for another, you mean that they feel a strong sexual attraction to that person.","ex":{"en":"I've had the hots for him ever since he came to college.","cn":"自从他来上大学后，我就对他春心萌动。"}},{"pos":"","cn":"","en":"相关词组：hot up"}]},"examples":[{"en":"The report was highly critical of senior members of the Cabinet and was considered too hot to publish.","cn":"报道中对内阁高级官员的批评被认为过于激烈，不宜发表。"},{"en":"When things got too hot most journalists left the area.","cn":"事态发展到过于严峻时，大多数记者便撤离了这个地区。"}]},"homogenized":{"media":{"uk":"media/uk/homogenized__gb_1.mp3","us":"media/us/homogenized__us_1.mp3"},"oxford":{"phon":"həˈmɒdʒənaɪzd","pos":"adjective","senses":[{"en":"treated so that the cream is mixed in with the rest","cn":"经过均质处理的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（牛奶）均质的","en":"Homogenized milk is milk where the fat has been broken up so that it is evenly distributed."}]}},"high":{"media":{"uk":"media/uk/high__gb_1.mp3","us":"media/us/high__us_1.mp3"},"oxford":{"phon":"haɪ","pos":"adjective","senses":[{"en":"measuring a long distance from the bottom to the top","cn":"高的","sc":"from bottom to top","ex":{"en":"What's the highest mountain in the US?","cn":"美国哪座山最高？"}},{"en":"used to talk about the distance that something measures from the bottom to the top","cn":"有某高度的","sc":"from bottom to top","ex":{"en":"How high is Everest?","cn":"珠穆朗玛峰有多高？"}},{"en":"at a level that is a long way above the ground or above the level of the sea","cn":"（离地面）很高的；海拔很高的","sc":"far above ground","ex":{"en":"a high branch/shelf/window","cn":"高处的树枝／搁板／窗"}},{"en":"greater or better than normal in quantity or quality, size or degree","cn":"（数量、质量、体积或程度）高的，超乎寻常的","sc":"greater than normal","ex":{"en":"a high price/cost/speed/temperature","cn":"高价；高成本；高速；高温"}},{"en":"containing a lot of a particular substance","cn":"含某物多","sc":"containing a lot","ex":{"en":"a high potassium content","cn":"高钾含量"}},{"en":"near the top in rank, status or importance","cn":"上层的；地位（或重要性）高的","g":"[usually before noun]","sc":"rank/status","ex":{"en":"She has held high office under three prime ministers.","cn":"她曾在三任首相手下任过要职。"}},{"en":"of great value","cn":"价值高的","sc":"valuable","ex":{"en":"to play for high stakes","cn":"豪赌"}},{"en":"when a river or the tide is high, the water reaches a long way up the river bank, beach, etc.","cn":"高水位的；高潮位的","sc":"river/sea","ex":{"en":"The river was very high and threatening to flood.","cn":"这条河水位很高，有发洪水的危险。"}},{"en":"morally good","cn":"高尚的；崇高的","g":"[usually before noun]","sc":"ideals/principles","ex":{"en":"a man of high ideals/principles","cn":"有崇高理想／道德准则的人"}},{"en":"showing a lot of approval or respect for somebody","cn":"十分赞同的；非常尊敬的","g":"[usually before noun]","sc":"approving","ex":{"en":"She is held in very high regard by her colleagues.","cn":"她很受同事们的敬重。"}},{"en":"at the upper end of the range of sounds that humans can hear; not deep or low","cn":"高音的","sc":"sound","ex":{"en":"She has a high voice.","cn":"她嗓音很尖。"}},{"en":"used to describe the middle or the most attractive part of a period of time","cn":"中间的；全盛的","g":"[only before noun]","sc":"of period of time","ex":{"en":"high noon","cn":"正午"}},{"en":"beginning to go bad and having a strong smell","cn":"开始变质的；开始发馊的","sc":"food"},{"en":"behaving in an excited way because of the effects of alcohol or drugs","cn":"有醉意；表现兴奋","g":"[not before noun]","lab":"informal","sc":"on alcohol/drugs","ex":{"en":"He was high on drugs.","cn":"他吸毒得很厉害。"}},{"en":"produced with part of the tongue in the highest possible position without limiting the flow of air","cn":"闭的；舌位高的","lab":"phonetics","sc":"phonetics"},{"en":"at or to a position or level that is a long way up from the ground or from the bottom","cn":"在高处；向高处；高","sc":"far from ground/bottom","ex":{"en":"to climb/jump/leap high","cn":"爬／蹦／跳得高"},"pos":"adverb"},{"en":"at or to a large value, amount or price","cn":"（价值或价格）高；（数量）大","sc":"value/amount","ex":{"en":"Prices are expected to rise even higher this year.","cn":"预计今年价格会涨得更高。"},"pos":"adverb"},{"en":"to or at an important position","cn":"到高位；在高位","sc":"important position","ex":{"en":"She never rose very high in the company.","cn":"她在公司里从未升到很高的位置。"},"pos":"adverb"},{"en":"at a high pitch","cn":"音调高","sc":"sound","ex":{"en":"I can't sing that high.","cn":"我唱不了那么高的调子。"},"pos":"adverb"},{"en":"the highest level or number","cn":"最高水平；最大数量","sc":"level/number","ex":{"en":"to hit/reach a high","cn":"达到高水平"},"pos":"noun"},{"en":"an area of high air pressure; an anticyclone","cn":"高气压区；反气旋","sc":"weather","ex":{"en":"A high over southern Europe is bringing fine, sunny weather to all parts.","cn":"欧洲南部上空的高气压正给各地带来阳光灿烂的好天气。"},"pos":"noun"},{"en":"the highest temperature reached during a particular day, week, etc.","cn":"（某天、某星期等的）最高气温","sc":"weather","ex":{"en":"Highs today will be in the region of 25°C.","cn":"今天的最高气温将为 25 摄氏度左右。"},"pos":"noun"},{"en":"the feeling of extreme pleasure and excitement that somebody gets after taking some types of drugs","cn":"（毒品引致的）快感","lab":"informal","sc":"from drugs","ex":{"en":"The high lasted all night.","cn":"那种快感持续了一整夜。"},"pos":"noun"},{"en":"the feeling of extreme pleasure and excitement that somebody gets from doing something fun or being successful at something","cn":"极大欢乐；极度高兴；乐不可支","lab":"informal","sc":"from success/enjoyment","ex":{"en":"He was on a real high after winning the competition.","cn":"他赢了那场比赛后高兴极了。"},"pos":"noun"},{"en":"used in the name of a high school","cn":"（用于中学校名）","sc":"school","ex":{"en":"He graduated from Little Rock High in 2012.","cn":"他 2012 年毕业于小石城中学。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高的（不用于形容人或动植物）","en":"Something that is high extends a long way from the bottom to the top when it is upright. You do not use high to describe people, animals, or plants.","ex":{"en":"...a house, with a high wall all around it","cn":"四周围着高墙的房子"}},{"pos":"ADJ 形容词","cn":"高度为…的;有…高的","en":"You use high to talk or ask about how much something upright measures from the bottom to the top.","ex":{"en":"...an elegant bronze horse only nine inches high","cn":"只有9英寸高的精致青铜马雕塑"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（相对地面、海平面、其他人或物）高的","en":"If something is high, it is a long way above the ground, above sea level, or above a person or thing.","ex":{"en":"I looked down from the high window","cn":"我从高高的窗口往下看。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量、程度、强度等）高的","en":"You can use high to indicate that something is great in amount, degree, or intensity.","ex":{"en":"The European country with the highest birth rate is Ireland","cn":"人口出生率最高的欧洲国家是爱尔兰。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（食物等）含…高的，富含…的","en":"If a food or other substance is high in a particular ingredient, it contains a large amount of that ingredient.","ex":{"en":"Don't indulge in rich sauces, fried food and thick pastry as these are high in fat.","cn":"不要吃太多浓酱汁、油炸食品和甜腻的油酥点心，因为这些食品的脂肪含量很高。"}},{"pos":"N-COUNT 可数名词","cn":"最高点;最高水平","en":"If something reaches a high of a particular amount or degree, that is the greatest it has ever been.","ex":{"en":"Traffic from Jordan to Iraq is down to a dozen loaded lorries a day, compared with a high of 200 a day","cn":"现在从约旦到伊拉克一天只有十几辆装货的卡车通过，而最高峰时可达到一天200辆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（重要性）高的;重要的","en":"If you say that something is a high priority or is high on your list, you mean that you consider it to be one of the most important things you have to do or deal with.","ex":{"en":"The Labour Party has not made the issue a high priority","cn":"工党尚未将该问题列为优先考虑的事项。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地位、职位）高的，显赫的","en":"Someone who is high in a particular profession or society, or has a high position, has a very important position and has great authority and influence.","ex":{"en":"Was there anyone particularly high in the administration who was an advocate of a different policy?","cn":"政府中有没有哪位高层人物支持采取不同政策？"}},{"pos":"ADJ 形容词","cn":"先进的;高级的;复杂的","en":"You can use high to describe something that is advanced or complex.","ex":{"en":"Neither Anna nor I are interested in high finance.","cn":"安娜和我对巨额融资都不感兴趣。"}},{"pos":"ADV-GRADED 副词","cn":"向高的目标（努力）","en":"If you aim high, you try to obtain or to achieve the best that you can.","ex":{"en":"You should not be afraid to aim high in the quest for an improvement in your income","cn":"想让自己的收入有所提高时，你应该敢于给自己设定高的目标。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声望、评价）高的","en":"If someone has a high reputation, or people have a high opinion of them, people think they are very good in some way, for example at their work.","ex":{"en":"She has always had a high reputation for her excellent short stories","cn":"她一直因其优秀的短篇小说享有很高的声望。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（质量、标准）高的","en":"If the quality or standard of something is high, it is very good indeed.","ex":{"en":"This is high quality stuff","cn":"这东西质量很好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"崇高的;高尚的","en":"If someone has high principles, they are morally good.","ex":{"en":"He was a man of the highest principles.","cn":"他是个道德崇高的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（音调）高而尖的，高的","en":"A high sound or voice is close to the top of a particular range of notes.","ex":{"en":"Her high voice really irritated Maria.","cn":"她的尖嗓门实在让玛丽亚很恼火。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（河流）水位高的","en":"When a river is high, it contains much more water than usual.","ex":{"en":"The waters of the Yangtze River are dangerously high for the time of year.","cn":"长江的水位每年这个时候都处于危险的高位。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"兴奋的;兴高采烈的","en":"If your spirits are high, you feel happy and excited.","ex":{"en":"Her spirits were high with the hope of seeing Nick in minutes rather than hours.","cn":"她很兴奋，因为再过几分钟而不是几小时后就有希望见到尼克了。"}},{"pos":"ADJ 形容词","cn":"喝醉了的;（吸毒后）极度兴奋的","en":"If someone is high on drink or drugs, they are affected by the alcoholic drink or drugs they have taken.","ex":{"en":"He was too high on drugs and alcohol to remember them.","cn":"他吸毒酗酒后处于极度兴奋状态，已经记不得他们了。"}},{"pos":"N-COUNT 可数名词","cn":"兴奋;高兴","en":"A high is a feeling or mood of great excitement or happiness."},{"pos":"PHRASE 短语","cn":"上级;上面","en":"If you say that something came from on high, you mean that it came from a person or place of great authority.","ex":{"en":"Orders had come from on high that extra care was to be taken during this week.","cn":"上面下了命令，本周要格外小心。"}},{"pos":"PHRASE 短语","cn":"陷入困境","en":"If you say that you were left high and dry, you are emphasizing that you were left in a difficult situation and were unable to do anything about it.","ex":{"en":"Schools with better reputations will be flooded with applications while poorer schools will be left high and dry.","cn":"较有名气的学校将会收到如潮水涌至般的申请，而差一些的学校则会陷入招生困境。"}},{"pos":"PHRASE 短语","cn":"起起落落;快乐和痛苦;成功和失败","en":"If you refer to the highs and lows of someone's life or career, you are referring to both the successful or happy times, and the unsuccessful or bad times."},{"pos":"PHRASE 短语","cn":"到处;各处","en":"If you say that you looked high and low for something, you are emphasizing that you looked for it in every place that you could think of."},{"pos":"","cn":"","en":"in high dudgeon→see: ; come hell or high water→see: ; to be high time→see: ;"}]},"examples":[{"en":"A high over southern Europe is bringing fine, sunny weather to all parts.","cn":"欧洲南部上空的高气压正给各地带来阳光灿烂的好天气。"},{"en":"Highs today will be in the region of 25°C.","cn":"今天的最高气温将为 25 摄氏度左右。"}]},"handful":{"media":{"uk":"media/uk/handful__gb_1.mp3","us":"media/us/handful__us_1.mp3"},"oxford":{"phon":"ˈhændfʊl","pos":"noun","senses":[{"en":"the amount of something that can be held in one hand","cn":"一把（的量）；用手抓起的数量","g":"[countable]","ex":{"en":"a handful of rice","cn":"一把米"}},{"en":"a small number of people or things","cn":"少数人（或物）","g":"[singular]","ex":{"en":"Only a handful of people came.","cn":"只有少数几个人来了。"}},{"en":"a person or an animal that is difficult to control","cn":"难以控制的人（或动物）","g":"[singular]","lab":"informal","ex":{"en":"Her children can be a real handful.","cn":"她的孩子们有时很难管教。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"几个;少数","en":"A handful of people or things is a small number of them.","ex":{"en":"He surveyed the handful of customers at the bar","cn":"他打量着吧台那边零星的几个顾客。"}},{"pos":"N-COUNT 可数名词","cn":"一把","en":"A handful of something is the amount of it that you can hold in your hand.","ex":{"en":"She scooped up a handful of sand and let it trickle through her fingers.","cn":"她抓起一把沙子，让它从指缝里一点点漏下来。"}},{"pos":"N-SING 单数名词","cn":"难管的人（尤指孩子）","en":"If you say that someone, especially a child, is a handful, you mean that they are difficult to control.","ex":{"en":"Zara can be a handful sometimes.","cn":"扎拉有时很难管教。"}}]},"examples":[{"en":"Her children can be a real handful.","cn":"她的孩子们有时很难管教。"},{"en":"Only a handful of people came.","cn":"只有少数几个人来了。"}]},"hill":{"media":{"uk":"media/uk/hill__gb_1.mp3","us":"media/us/hill__us_1.mp3"},"oxford":{"phon":"hɪl","pos":"noun","senses":[{"en":"an area of land that is higher than the land around it, but not as high as a mountain","cn":"山丘；小山","g":"[countable]","ex":{"en":"a region of gently rolling hills","cn":"缓缓起伏的丘陵地区"}},{"en":"a slope on a road","cn":"（道路的）斜坡","g":"[countable]","ex":{"en":"The motorcade made its way up the hill.","cn":"车队一路上山。"}},{"en":"Capitol Hill (= used to refer to the US Capitol and the activities that take place there)","cn":"国会山（指美国国会）","g":"[singular]","lab":"North American English, informal，，"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"小山;山冈;山丘","en":"A hill is an area of land that is higher than the land that surrounds it.","ex":{"en":"We trudged up the hill to the stadium.","cn":"我们费力地爬到山上的体育场。"}},{"pos":"PHRASE 短语","cn":"人老珠黄;在走下坡路;在衰退中;过气","en":"If you say that someone is over the hill, you are saying rudely that they are old and no longer fit, attractive, or capable of doing useful work.","ex":{"en":"He doesn't take kindly to suggestions that he is over the hill.","cn":"他不爱听别人说他风光不再。"}}]},"examples":[{"en":"The house is built on the side of a hill overlooking the river.","cn":"房子建在可俯视河流的小山坡上。"},{"en":"Always take care when driving down steep hills.","cn":"下陡坡时一定要小心驾驶。"}]},"hole":{"oxford":{"phon":"həʊl","pos":"noun","senses":[{"en":"a hollow space in something solid or in the surface of something","cn":"洞；孔；坑","g":"[countable]","sc":"hollow space","ex":{"en":"He dug a deep hole in the garden.","cn":"他在花园里挖了个深坑。"}},{"en":"a space or opening that goes all the way through something","cn":"裂口；开口；孔眼","g":"[countable]","sc":"opening","ex":{"en":"We drilled a hole through the wall.","cn":"我们在墙上钻了一个洞。"}},{"en":"the home of a small animal","cn":"洞穴；巢穴","g":"[countable]","sc":"animal’s home","ex":{"en":"a mouse hole","cn":"鼠洞"}},{"en":"an unpleasant place to live or be in","cn":"糟糕的住所（或处所）","g":"[countable, usually singular]","lab":"informal, disapproving，，","sc":"unpleasant place","ex":{"en":"I am not going to bring up my child in this hole.","cn":"我不会在这个鬼地方养育孩子的。"}},{"en":"a hollow in the ground that you must get the ball into; one of the sections of a golf course with the tee at the beginning and the hole at the end","cn":"球洞；球座到球洞的区域","g":"[countable]","sc":"in golf","ex":{"en":"The ball rolled into the hole and she had won.","cn":"球滚进了洞，她赢了。"}},{"en":"a fault or weakness in something such as a plan, law or story","cn":"（计划、法律或报道等的）错误，缺陷，漏洞","g":"[countable, usually plural]","sc":"fault/weakness","ex":{"en":"I don't believe what she says—her story is full of holes.","cn":"我不相信她的话，她的说法漏洞百出。"}},{"en":"a place or position that needs to be filled because somebody/something is no longer there","cn":"空缺的地方（或位置）","g":"[singular]","sc":"empty place/position","ex":{"en":"After his wife left, there was a gaping hole in his life.","cn":"妻子离开后，他的人生中出现了一大片空洞。"}},{"en":"to make a hole or holes in something, especially a boat or ship","cn":"（尤指在船上）打洞，造成破洞","g":"[transitive, usually passive]","sc":"make a hole","ex":{"en":"The ship had been holed by a missile.","cn":"那艘船被导弹打了个洞。"},"pos":"verb"},{"en":"to hit a golf ball into the hole","cn":"击球入洞","g":"[transitive, intransitive]","sc":"in golf","ex":{"en":"She holed a 25 foot putt.","cn":"她打了一个 25 英尺远的推杆进洞。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"洞;坑;孔眼","en":"A hole is a hollow space in something solid, with an opening on one side.","ex":{"en":"He took a shovel, dug a hole, and buried his once-prized possessions","cn":"他拿起一把铁锨，挖了个坑，将自己曾经珍爱的物品埋了起来。"}},{"pos":"N-COUNT 可数名词","cn":"（贯穿的）孔洞","en":"A hole is an opening in something that goes right through it.","ex":{"en":"These tiresome creatures eat holes in the leaves","cn":"这些讨厌的虫子在叶子上咬出了洞。"}},{"pos":"N-COUNT 可数名词","cn":"(鼠、兔等小动物的）洞穴，窝","en":"A hole is the home or hiding place of a mouse, rabbit, or other small animal.","ex":{"en":"...a rabbit hole.","cn":"兔窝"}},{"pos":"N-COUNT 可数名词","cn":"（法律、理论、论点等的）漏洞，缺陷，破绽","en":"A hole in a law, theory, or argument is a fault or weakness that it has.","ex":{"en":"There were some holes in that theory, some unanswered questions.","cn":"那个理论中有一些漏洞，一些问题没有解答。"}},{"pos":"N-COUNT 可数名词","cn":"糟糕的地方;鬼地方","en":"If you refer to a place as a hole, you are emphasizing that you think it is very unpleasant.","ex":{"en":"Why don't you leave this awful hole and come to live with me?","cn":"你为什么不离开这个破地方，搬过来和我住？"}},{"pos":"N-COUNT 可数名词","cn":"（9洞或18洞高尔夫球场的）球洞（指从球座到球穴的一段区域）","en":"A hole is also one of the nine or eighteen sections of a golf course.","ex":{"en":"I played nine holes with Gary Player today.","cn":"我今天和加里·普莱耶打了9洞高尔夫球。"}},{"pos":"N-COUNT 可数名词","cn":"（高尔夫球场上的）球穴","en":"A hole is one of the places on a golf course that the ball must drop into, usually marked by a flag."},{"pos":"VERB 动词","cn":"（高尔夫球比赛中）击球入穴","en":"If you hole in a game of golf, you hit the ball so that it goes into the hole.","ex":{"en":"He holed from nine feet at the 18th","cn":"他打到第18洞时从9英尺外击球入穴。"}},{"pos":"VERB 动词","cn":"打出破洞于，炸出窟窿于（建筑物、船只等上）","en":"If something such as a building or ship is holed, holes are made in it by guns or other weapons.","ex":{"en":"Blocks of flats have been holed and some shells have fallen within the historic ramparts.","cn":"几栋公寓楼被炸出了窟窿，几枚炮弹还落在了古护城墙内。"}},{"pos":"PHRASE 短语","cn":"绝对不需要","en":"If you say that you need something or someone like a hole in the head, you are emphasizing that you do not want them and that they would only add to the problems that you already have.","ex":{"en":"We need more folk heroes like we need a hole in the head.","cn":"我们绝对不需要有更多的民间英雄了。"}},{"pos":"PHRASE 短语","cn":"置身困境;处境尴尬","en":"If you say that you are in a hole, you mean that you are in a difficult or embarrassing situation.","ex":{"en":"He admitted that the government was in 'a dreadful hole'.","cn":"他承认政府目前“处境极为尴尬”。"}},{"pos":"PHRASE 短语","cn":"（高尔夫球运动中从发球区的）一杆入穴","en":"If you get a hole in one in golf, you get the golf ball into the hole with a single stroke.","ex":{"en":"All they ever dream about is getting a hole in one.","cn":"他们一直梦想着能一杆入穴。"}},{"pos":"PHRASE 短语","cn":"在（论点或理论）中挑毛病","en":"If you pick holes in an argument or theory, you find weak points in it so that it is no longer valid.","ex":{"en":"He then goes on to pick holes in the article before reaching his conclusion.","cn":"他接着在文章中挑了一番刺儿后才作出结论。"}},{"pos":"","cn":"","en":"相关词组：hole up"}]},"media":{"uk":"media/uk/hole__gb_1.mp3","us":"media/us/hole__us_1.mp3"},"examples":[{"en":"We start the current fiscal year $30 million in the hole.","cn":"我们今年的财政年度一开始便负着 3 000 万元的债。"},{"en":"After his wife left, there was a gaping hole in his life.","cn":"妻子离开后，他的人生中出现了一大片空洞。"}]},"healthy":{"media":{"uk":"media/uk/healthy__gb_1.mp3","us":"media/us/healthy__us_1.mp3"},"oxford":{"phon":"ˈhelθi","pos":"adjective","senses":[{"en":"having good health and not likely to become ill","cn":"健康的；健壮的","lab":"especially British English","ex":{"en":"a healthy child/baby/adult","cn":"健康的孩子／宝宝／成人"}},{"en":"good for your health","cn":"有益健康的","g":"[usually before noun]","ex":{"en":"a healthy diet/lifestyle","cn":"健康的饮食／生活方式"}},{"en":"showing that you are in good health","cn":"反映健康的","g":"[usually before noun]","ex":{"en":"to have a healthy appetite","cn":"胃口好"}},{"en":"normal and sensible","cn":"正常合理的","ex":{"en":"The child showed a healthy curiosity.","cn":"这孩子的好奇心很正常。"}},{"en":"successful and working well","cn":"兴旺的；发达的；顺利的","ex":{"en":"The economy is extremely healthy at the moment.","cn":"目前经济极为繁荣。"}},{"en":"large and showing success","cn":"大而显得成功的；可观的","g":"[usually before noun]","ex":{"en":"a healthy bank balance","cn":"一大笔银行结余"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"健康的;健壮的","en":"Someone who is healthy is well and is not suffering from any illness.","ex":{"en":"Most of us need to lead more balanced lives to be healthy and happy","cn":"我们中大多数人需要过更为平衡的生活，以保持健康和快乐。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"显示健康的;反映健康的","en":"If a feature or quality that you have is healthy, it makes you look well or shows that you are well.","ex":{"en":"...the glow of healthy skin.","cn":"健康的肤色"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有益于健康的;促进健康的","en":"Something that is healthy is good for your health.","ex":{"en":"...a great healthy outdoor pursuit.","cn":"对健康大有裨益的室外活动"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（机构或体系）兴旺的，运作良好的","en":"A healthy organization or system is successful.","ex":{"en":"...an economically healthy socialist state.","cn":"经济繁荣的社会主义国家"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大量的;可观的","en":"A healthy amount of something is a large amount that shows success.","ex":{"en":"He predicts a continuation of healthy profits in the current financial year.","cn":"他预计本财年能继续保持可观的利润。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明智的;聪明的;合理的","en":"If you have a healthy attitude about something, you show good sense.","ex":{"en":"She has a refreshingly healthy attitude to work","cn":"她对工作持一种明智态度，令人耳目一新。"}}]},"examples":[{"en":"Keep healthy by eating well and exercising regularly.","cn":"通过良好饮食和经常性锻炼保持健康。"},{"en":"It's not healthy the way she clings to the past.","cn":"她那种沉湎于过去的态度不明智。"}]},"huddle":{"media":{"uk":"media/uk/huddle__gb_1.mp3","us":"media/us/huddle__us_1.mp3"},"oxford":{"phon":"ˈhʌdl","pos":"verb","senses":[{"en":"to gather closely together, usually because of cold or fear","cn":"（通常因寒冷或害怕）挤在一起","g":"[intransitive]","ex":{"en":"We huddled together for warmth.","cn":"我们挤在一块取暖。"}},{"en":"to hold your arms and legs close to your body, usually because you are cold or frightened","cn":"（通常因寒冷或害怕）蜷缩，缩成一团","g":"[intransitive]","ex":{"en":"I huddled under a blanket on the floor.","cn":"我在地板上盖着毯子缩成一团。"}},{"en":"a small group of people, objects or buildings that are close together, especially when they are not in any particular order","cn":"（尤指杂乱地）挤在一起的人（或物品、建筑）","ex":{"en":"People stood around in huddles.","cn":"人们三五成群地到处聚集着。"},"pos":"noun"},{"en":"a time when the players gather round to hear the plan for the next part of the game","cn":"队员靠拢（磋商战术）","ex":{"en":"The team went into a huddle at half-time to discuss their tactics.","cn":"中场休息时队员围成一圈讨论战术。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（通常因寒冷或恐惧而）蜷缩，缩成一团","en":"If you huddle somewhere, you sit, stand, or lie there holding your arms and legs close to your body, usually because you are cold or frightened.","ex":{"en":"She huddled inside the porch as she rang the bell","cn":"她按门铃时身子在门廊里缩成一团。"}},{"pos":"VERB 动词","cn":"（通常因寒冷或恐惧而）聚在一起，挤成一团","en":"If people huddle together or huddle round something, they stand, sit, or lie close to each other, usually because they all feel cold or frightened.","ex":{"en":"Tired and lost, we huddled together","cn":"我们疲惫不堪，又迷了路，于是大家都挤在一起。"}},{"pos":"V-RECIP 相互动词","cn":"（私下）开会;(暗中)碰头","en":"If people huddle in a group, they gather together to discuss something quietly or secretly.","ex":{"en":"Off to one side, Sticht, Macomber, Jordan, and Kreps huddled to discuss something","cn":"施蒂希特、麦康伯、乔丹和克雷普斯走到一旁私下商量着什么。"}},{"pos":"N-COUNT 可数名词","cn":"拥挤的一群;杂乱的一堆","en":"A huddle is a small group of people or things that are standing very close together or lying on top of each other, usually in a disorganized way.","ex":{"en":"We lay there: a huddle of bodies, gasping for air","cn":"我们横七竖八地挤作一团躺在那里，大口喘着气。"}}]},"examples":[{"en":"The track led them to a huddle of outbuildings.","cn":"那条小路把他们带到了一片杂乱拥挤的棚子。"},{"en":"I huddled under a blanket on the floor.","cn":"我在地板上盖着毯子缩成一团。"}]},"hypothesis":{"oxford":{"phon":"haɪˈpɒθəsɪs","pos":"noun","senses":[{"en":"an idea or explanation of something that is based on a few known facts but that has not yet been proved to be true or correct","cn":"（有少量事实依据但未被证实的）假说，假设","g":"[countable]","ex":{"en":"to formulate/confirm a hypothesis","cn":"提出／证实假设"}},{"en":"guesses and ideas that are not based on certain knowledge","cn":"（凭空的）猜想，猜测","g":"[uncountable]","ex":{"en":"It would be pointless to engage in hypothesis before we have the facts.","cn":"在我们还没掌握事实之前瞎猜是毫无意义的。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"假说;假设","en":"A hypothesis is an idea which is suggested as a possible explanation for a particular situation or condition, but which has not yet been proved to be correct.","ex":{"en":"Work will now begin to test the hypothesis in rats","cn":"现在将开始在老鼠身上做实验以验证该假设。"}}]},"media":{"uk":"media/uk/hypothesis__gb_1.mp3","us":"media/us/hypothesis__us_1.mp3"},"examples":[{"en":"It would be pointless to engage in hypothesis before we have the facts.","cn":"在我们还没掌握事实之前瞎猜是毫无意义的。"},{"en":"a hypothesis about the function of dreams","cn":"关于梦的作用的假说"}]},"hindered":{"lemma":"hinder"},"here":{"media":{"uk":"media/uk/here__gb_1.mp3","us":"media/us/here__us_1.mp3"},"oxford":{"phon":"hɪə(r)","pos":"adverb","senses":[{"en":"used after a verb or preposition to mean ‘in, at or to this position or place’","cn":"（用于动词或介词之后）在这里，向这里","ex":{"en":"I live here.","cn":"我住这儿。"}},{"en":"used when you are giving or showing something to somebody","cn":"（给某人东西或指出某物时说）","ex":{"en":"Here's the money I promised you.","cn":"这是我答应给你的钱。"}},{"en":"used to show your role in a situation","cn":"（表示某人的作用）","ex":{"en":"I'm here to help you.","cn":"我是来帮助你的。"}},{"en":"now; at this point","cn":"现在；在这一点上","ex":{"en":"The countdown to Christmas starts here.","cn":"现在开始圣诞节倒计时。"}},{"en":"used to attract somebody’s attention","cn":"（用以引起注意）喂，嘿","lab":"British English","ex":{"en":"Here, where are you going with that ladder?","cn":"嘿，你要把梯子搬到哪里？"},"pos":"exclamation"},{"en":"used when offering something to somebody","cn":"（主动提议时说）","ex":{"en":"Here, let me carry that for you.","cn":"来，让我帮你搬吧。"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在这里;在这儿","en":"You use here when you are referring to the place where you are.","ex":{"en":"I'm here all by myself and I know I'm going to get lost","cn":"这里只有我一个人，我知道我会迷路的。"}},{"pos":"ADV 副词","cn":"在此处（指所指向的地方）","en":"You use here when you are pointing towards a place that is near you, in order to draw someone else's attention to it.","ex":{"en":"...if you will just sign here","cn":"请在这里签字"}},{"pos":"ADV 副词","cn":"在身边;在手里","en":"You use here in order to indicate that the person or thing that you are talking about is near you or is being held by you.","ex":{"en":"My friend here writes for radio","cn":"我这位朋友是个电台撰稿人。"}},{"pos":"ADV 副词","cn":"在人世间","en":"You use here to refer to people in general and their life on Earth.","ex":{"en":"...where we have come from, where we are going to, or what our purpose here is, if any","cn":"我们从哪里来，到哪里去，或者倘若我们活在人世间有何目的的话，这个目的是什么"}},{"pos":"ADV 副词","cn":"来此（做…）","en":"If you say that you are here to do something, that is your role or function.","ex":{"en":"I'm here to help you","cn":"我是来帮你的。"}},{"pos":"ADV 副词","cn":"（用于引起注意）…来了，…到了","en":"You use here in order to draw attention to something or someone who has just arrived in the place where you are, or to draw attention to the place you have just arrived at.","ex":{"en":"'Here's the taxi,' she said politely","cn":"“出租车来了，”她礼貌地说。"}},{"pos":"ADV 副词","cn":"在这一点上;在这一阶段;在这一方面","en":"You use here to refer to a particular point or stage of a situation or subject that you have come to or that you are dealing with.","ex":{"en":"Both sides will have to sell the agreement to their people. It's here that the real test will come","cn":"双方都必须要让各自的民众接受这项协议。真正的考验就在这里。"}},{"pos":"ADV 副词","cn":"这时;此刻","en":"You use here to refer to a period of time, a situation, or an event that is present or happening now.","ex":{"en":"Here comes the summer","cn":"夏天到了。"}},{"pos":"ADV 副词","cn":"（用在句首以引起注意或引出介绍）下面，以下","en":"You use here at the beginning of a sentence in order to draw attention to something or to introduce something.","ex":{"en":"From Nairobi here's our East Africa correspondent, Colin Blane","cn":"以下是我们来自内罗毕的东非记者科林·布兰的报道。"}},{"pos":"ADV 副词","cn":"给（对方）","en":"You use here when you are offering or giving something to someone.","ex":{"en":"You know you can phone me — here's my mother's number","cn":"你可以给我打电话——给你，这是我母亲的电话号码。"}},{"pos":"PHRASE 短语","cn":"（表示接下来对某人性格或处境的描述出人意料）看看，瞧瞧","en":"You say 'here we are' or 'here you are' when the statement that you are making about someone's character or situation is unexpected.","ex":{"en":"Here you are, saying these terrible things","cn":"看看你，说这些难听的话。"}},{"pos":"CONVENTION 惯用语","cn":"找到了; 这就是了","en":"You say 'here we are' when you have just found something that you have been looking for.","ex":{"en":"I rummaged through the drawers and came up with Amanda's folder. 'Here we are.'","cn":"我翻遍了抽屉，找出了阿曼达的文件夹。“找到了。”"}},{"pos":"CONVENTION 惯用语","cn":"（表示即将开始做或说困难或令人不快的事）这就开始","en":"You say 'here goes' when you are about to do or say something difficult or unpleasant.","ex":{"en":"Dr Culver nervously muttered 'Here goes,' and gave the little girl an injection.","cn":"卡尔弗医生紧张地嘟囔了一句“要打了啊”，然后就给小女孩打了一针。"}},{"pos":"PHRASE 短语","cn":"（尤指令人不快的事）又发生了，又来了","en":"You use expressions such as 'here we go' and 'here we go again' in order to indicate that something is happening again in the way that you expected, especially something unpleasant.","ex":{"en":"'Police! Open up!' — 'Oh well,' I thought, 'here we go.'","cn":"“警察！开门！”——“哎呀。”我想，“又来了。”"}},{"pos":"PHRASE 短语","cn":"此时此刻;目前;眼下","en":"You use here and now to emphasize that something is happening at the present time, rather than in the future or past, or that you would like it to happen at the present time.","ex":{"en":"I'm a practicing physician trying to help people here and now","cn":"我是一名此时此刻只想治病救人的执业医师。"}},{"pos":"PHRASE 短语","cn":"在各处;零散地","en":"If something happens here and there, it happens in several different places.","ex":{"en":"I do a bit of teaching here and there","cn":"我零零散散地到处教些课。"}},{"pos":"CONVENTION 惯用语","cn":"（祝酒词）为我们干杯/为你的新工作干杯","en":"You use expressions such as 'here's to us' and 'here's to your new job' before drinking a toast in order to wish someone success or happiness.","ex":{"en":"He raised his glass. 'Here's to neighbors.'","cn":"他举起杯子： “各位高邻，干了这杯！”"}}]},"examples":[{"en":"‘Here we go,’ thought Fred, ‘she's sure to say something.’ “","cn":"这就开始了。”弗雷德想，“她肯定有话要说。”"},{"en":"I can't find my keys. Oh, here they are.","cn":"我找不到我的钥匙。哦，原来在这里。"}]},"hockey":{"oxford":{"phon":"ˈhɒki","pos":"noun","senses":[{"en":"a game played on a field by two teams of 11 players, with curved sticks and a small hard ball. Teams try to hit the ball into the other team’s goal.","cn":"曲棍球","lab":"British English","ex":{"en":"to play hockey","cn":"打曲棍球"}},{"en":"a game played on ice, in which players use long sticks to hit a hard rubber disc (called a puck) into the other team’s goal","cn":"冰球运动；冰上曲棍球","lab":"North American English","ex":{"en":"She plays hockey in the winter.","cn":"她在冬天打冰球。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"曲棍球","en":"Hockey is an outdoor game played between two teams of 11 players who use long curved sticks to hit a small ball and try to score goals.","ex":{"en":"She played hockey for the national side.","cn":"她在国家队打曲棍球。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"冰球;冰上曲棍球","en":"Hockey is a game played on ice between two teams of 11 players who use long curved sticks to hit a small rubber disk, called a puck, and try to score goals."}]},"media":{"img":["media/ldoce/img/hockey.jpg","media/pic/sports_comp.jpg"],"uk":"media/uk/hockey__gb_1.mp3","us":"media/us/hockey__us_1.mp3"},"examples":[{"en":"a hockey stick/player/team","cn":"曲棍球球棍/球员/球队"},{"en":"to play hockey","cn":"打曲棍球"}]},"hinges":{"lemma":"hinge"},"hammered":{"media":{"uk":"media/uk/hammered__gb_1.mp3","us":"media/us/hammered__us_1.mp3"},"oxford":{"phon":"ˈhæməd","pos":"adjective","senses":[{"en":"very drunk","cn":"烂醉"}]},"base":"hammer"},"hung":{"media":{"uk":"media/uk/hung__gb_2.mp3","us":"media/us/hung__us_2.mp3"},"oxford":{"phon":"hʌŋ","pos":"adjective","senses":[{"en":"in which no political party has more elected members than all the other parties added together","cn":"任何政党都不占多数席位的","lab":"British English","ex":{"en":"a hung parliament","cn":"悬浮议会"}},{"en":"unable to agree about whether somebody is guilty of a crime","cn":"不能取得一致意见的"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Hung is the past tense and past participle of most of the senses of hang ."},{"pos":"ADJ 形容词","cn":"（陪审团）不能达成一致意见的;（英国议会或政务委员会）任何政党都不占多数席位的","en":"A hung jury is the situation that occurs when a jury is unable to reach a decision because there is not a clear majority of its members in favour of any one decision. In British English you can also talk about a hung parliament or a hung council.","ex":{"en":"In the event of a hung Parliament he would still fight for everything in the manifesto","cn":"假如出现一个没有多数党的议会，他也仍将继续为实现宣言里提出的所有目标而奋斗。"}}]},"base":"hang"},"harmonize":{"oxford":{"phon":"ˈhɑːmənaɪz","pos":"verb","senses":[{"en":"if two or more things harmonize with each other or one thing harmonizes with the other, the things go well together and produce an attractive result","cn":"（和某事物）协调，和谐","g":"[intransitive]","ex":{"en":"The new building does not harmonize with its surroundings.","cn":"那栋新楼与周围环境不协调。"}},{"en":"to make systems or rules similar in different countries or organizations","cn":"使（不同国家或组织的体制或规则）相一致；使协调","g":"[transitive]","ex":{"en":"the need to harmonize tax levels across the European Union","cn":"使欧盟各国的税收标准相一致的必要"}},{"en":"to play or sing music that combines with the main tune to make a pleasant sound","cn":"为（主调）配和声","g":"[intransitive]","ex":{"en":"Sally sang the melody while I harmonized.","cn":"当我和声时，莎莉唱着旋律。"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"（与…）融洽，和谐，与…协调一致","en":"If two or more things harmonize with each other, they fit in well with each other.","ex":{"en":"...slabs of pink and beige stone that harmonize with the carpet","cn":"与地毯协调搭配的粉色和米色相间的石板"}},{"pos":"VERB 动词","cn":"使（法律、制度或规则）协调;使统一","en":"When governments or organizations harmonize laws, systems, or regulations, they agree in a friendly way to make them the same or similar.","ex":{"en":"How far will members have progressed towards harmonising their economies?","cn":"各成员国在使彼此经济协调一致的进程上会有多大进展？"}},{"pos":"VERB 动词","cn":"用和声唱（或演奏）;为（主调）配和声","en":"When people harmonize, they sing or play notes which are different from the main tune but which sound nice with it.","ex":{"en":"Bremer and Garland harmonize on the title song, 'Meet Me in St. Louis'.","cn":"布雷默和加兰为主题曲《相逢圣路易斯》配和声。"}}]},"media":{"uk":"media/uk/harmonize__gb_1.mp3","us":"media/us/harmonize__us_1.mp3"},"examples":[{"en":"the need to harmonize tax levels across the European Union","cn":"使欧盟各国的税收标准相一致的必要"},{"en":"The new building does not harmonize with its surroundings.","cn":"那栋新楼与周围环境不协调。"}]},"hoarding":{"media":{"uk":"media/uk/hoarding__gb_1.mp3","us":"media/us/hoarding__us_1.mp3"},"oxford":{"phon":"ˈhɔːdɪŋ","pos":"noun","senses":[{"en":"a large board on the outside of a building or at the side of the road, used for displaying advertisements","cn":"大幅广告牌","g":"[countable]","lab":"British English","ex":{"en":"advertising hoardings","cn":"大幅大幅的广告牌"}},{"en":"a temporary fence made of boards that is placed around an area of land until a building has been built","cn":"（建筑工地用木板搭起的）临时围栏","g":"[countable]","lab":"British English"},{"en":"the act of collecting and keeping large amounts of food, money, etc., often secretly","cn":"（常指偷偷的）贮藏，囤积","g":"[uncountable]","ex":{"en":"Consumer hoarding of limited goods, such as gasoline and paper, is creating shortages in stores.","cn":"消费者囤积汽油和纸张等有限商品，导致商店出现短缺。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（路旁或建筑物侧面的）巨幅广告牌，告示牌","en":"A hoarding is a very large board at the side of a road or on the side of a building, which is used for displaying advertisements and posters.","ex":{"en":"An advertising hoarding on the platform caught her attention.","cn":"站台上的一幅巨幅广告牌吸引了她的注意力。"}}]},"examples":[{"en":"advertising hoardings","cn":"大幅大幅的广告牌"}],"base":"hoard"},"highlighting":{"lemma":"highlight","media":{"uk":"media/uk/highlight__gb_1.mp3","us":"media/us/highlight__us_1.mp3"}},"hacker":{"media":{"uk":"media/uk/hacker__gb_1.mp3","us":"media/us/hacker__us_1.mp3"},"oxford":{"phon":"ˈhækə(r)","pos":"noun","senses":[{"en":"a person who uses computers to get access to data in somebody else's computer or phone system without permission","cn":"黑客（在未经许可的情况下侵入他人计算机或手机系统以获取信息的人）"},{"en":"a person who uses or writes computer programs with enthusiasm and skill","cn":"黑客：以热情和技巧使用或编写计算机程序的人","lab":"informal","ex":{"en":"The software is so complicated that only experienced hackers can use it.","cn":"该软件非常复杂，只有经验丰富的黑客才能使用。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指盗取他人计算机系统中保密信息的）黑客","en":"A computer hacker is someone who tries to break into computer systems, especially in order to get secret information."},{"pos":"N-COUNT 可数名词","cn":"黑客（指沉迷于电脑之中，无暇顾及其他的电脑迷）","en":"A computer hacker is someone who uses a computer a lot, especially so much that they have no time to do anything else."}]},"examples":[{"en":"A hacker had managed to get into the system.","cn":"一个黑客设法侵入了系统。"}]},"hard-pressed":{"oxford":{"phon":"ˌhɑːd ˈprest","pos":"adjective","senses":[{"en":"having a lot of problems, especially too much work, and too little time or money","cn":"处于强大压力下的（尤指工作重、时间紧、资金少）","ex":{"en":"Hard-pressed junior doctors want shorter working hours.","cn":"实习医生压力太大，希望缩短工作时间。"}},{"en":"finding something very difficult to do","cn":"很难（做某事）","ex":{"en":"You would be hard-pressed to find a better secretary.","cn":"找一位更好的秘书很难。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"处于困境的;经济窘迫的;承受高压的","en":"If someone is hard-pressed, they are under a great deal of strain and worry, usually because they have not got enough money.","ex":{"en":"The region's hard-pressed consumers are spending less on luxuries.","cn":"该地区的消费者经济窘迫，在奢侈品上的开销比以前少了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很难做到的;（做…）有困难的","en":"If you will be hard-pressed to do something, you will have great difficulty doing it.","ex":{"en":"This year the airline will be hard-pressed to make a profit.","cn":"今年该航空公司将很难赢利。"}}]},"media":{"uk":"media/uk/hard_pressed_1_gb_1.mp3","us":"media/us/hard_pressed_1_us_1.mp3"},"examples":[{"en":"You would be hard-pressed to find a better secretary.","cn":"找一位更好的秘书很难。"},{"en":"The new exams will only add to the workload of already hard-pressed teachers.","cn":"新推出的考试只会给原本就承受巨大压力的老师们增加工作负担。"}]},"hope":{"media":{"uk":"media/uk/hope__gb_1.mp3","us":"media/us/hope__us_1.mp3"},"oxford":{"phon":"həʊp","pos":"verb","senses":[{"en":"to want something to happen and think that it is possible","cn":"希望，期望（某事发生）","g":"[intransitive, transitive]","ex":{"en":"All we can do now is wait and hope.","cn":"我们现在所能做的就是等候和期待。"}},{"en":"to intend to do something if possible","cn":"希望，想要（做某事）","g":"[transitive]","ex":{"en":"We're hoping to address all these issues.","cn":"我们希望解决所有这些问题。"}},{"en":"a feeling of wanting and expecting a particular thing to happen; something that you wish for","cn":"希望；愿望","g":"[uncountable, countable]","lab":"North American English","ex":{"en":"Don't lose hope—we'll find her.","cn":"别失去希望，我们会找到她的。"},"pos":"noun"},{"en":"a reason to believe that something good may happen","cn":"有实现的可能；有希望","g":"[uncountable]","ex":{"en":"The future is not without hope.","cn":"未来并非没有希望。"},"pos":"noun"},{"en":"a person, a thing or a situation that will help you get what you want","cn":"被寄予希望的人（或事物、情况）","g":"[countable, usually singular]","ex":{"en":"He turned to her in despair and said, ‘You're my last hope.’","cn":"他绝望地向她求助说：“你是我最后的希望。”"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"希望;期望","en":"If you hope that something is true, or if you hope for something, you want it to be true or to happen, and you usually believe that it is possible or likely.","ex":{"en":"She had decided she must go on as usual, follow her normal routine, and hope and pray","cn":"她打定主意必须像平时一样生活，遵循自己通常的作息规律，同时怀抱希望、虔诚祈祷。"}},{"pos":"VERB 动词","cn":"指望;奢望","en":"If you say that you cannot hope for something, or if you talk about the only thing that you can hope to get, you mean that you are in a bad situation, and there is very little chance of improving it.","ex":{"en":"Things aren't ideal, but that's the best you can hope for","cn":"事情并不理想，但你只能指望这样了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对未来的）希望，期望，指望","en":"Hope is a feeling of desire and expectation that things will go well in the future.","ex":{"en":"Now that he has become President, many people once again have hope for genuine changes in the system","cn":"既然他已当上了总统，很多人又再次看到了进行真正的体制改革的希望。"}},{"pos":"N-COUNT 可数名词","cn":"希望;期望;盼望","en":"If someone wants something to happen, and considers it likely or possible, you can refer to their hopes of that thing, or to their hope that it will happen.","ex":{"en":"They have hopes of increasing trade between the two regions","cn":"他们希望增进两个地区之间的贸易。"}},{"pos":"N-COUNT 可数名词","cn":"被寄予希望的人（或事物）","en":"If you think that the help or success of a particular person or thing will cause you to be successful or to get what you want, you can refer to them as your hope .","ex":{"en":"...England's last hope in the English Open Table Tennis Championships","cn":"英格兰队在英国乒乓球公开锦标赛中的最后希望"}},{"pos":"PHRASE 短语","cn":"从最好的方面想;抱乐观的希望","en":"If you are in a difficult situation and do something and hope for the best, you hope that everything will happen in the way you want, although you know that it may not.","ex":{"en":"I took the risk and hoped for the best","cn":"我冒了这个险，心里祈祷能够诸事顺利。"}},{"pos":"PHRASE 短语","cn":"（不应）抱有很大的希望","en":"If you tell someone not to get their hopes up, or not to build their hopes up, you are warning them that they should not become too confident of progress or success.","ex":{"en":"There is no reason for people to get their hopes up over this mission","cn":"不必对这次行动抱太大希望。"}},{"pos":"PHRASE 短语","cn":"没有一线希望;毫无机会","en":"If you say that someone has not got a hope in hell of doing something, you are emphasizing that they will not be able to do it.","ex":{"en":"Everybody knows they haven't got a hope in hell of forming a government anyway.","cn":"众人皆知他们根本就无力组建政府。"}},{"pos":"PHRASE 短语","cn":"很高期望;很大希望;厚望","en":"If you have high hopes or great hopes that something will happen, you are confident that it will happen.","ex":{"en":"I had high hopes that Derek Randall might play an important part","cn":"我对德里克·兰德尔发挥重要作用寄予厚望。"}},{"pos":"PHRASE 短语","cn":"存一线希望;抱着万分之一的希望","en":"If you hope against hope that something will happen, you hope that it will happen, although it seems impossible.","ex":{"en":"She glanced about the hall, hoping against hope that Richard would be waiting for her.","cn":"她眼睛扫过大厅，对理查德会在那里等她仍怀有一丝希望。"}},{"pos":"PHRASE 短语","cn":"（表示礼貌）我希望，但愿","en":"You use 'I hope' in expressions such as 'I hope you don't mind' and 'I hope I'm not disturbing you', when you are being polite and want to make sure that you have not offended someone or disturbed them.","ex":{"en":"I hope you don't mind me coming to see you","cn":"希望你不介意我来见你。"}},{"pos":"PHRASE 短语","cn":"（表示警告他人不要做愚蠢或危险的事）我希望，但愿","en":"You say 'I hope' when you want to warn someone not to do something foolish or dangerous.","ex":{"en":"You're not trying to see him, I hope?","cn":"但愿你不是想要去见他吧？"}},{"pos":"PHRASE 短语","cn":"（表示更加礼貌和委婉）我希望，我想","en":"You add 'I hope' to what you are saying to make it sound more polite and less rude or less definite.","ex":{"en":"I'm the best man for the job, I hope","cn":"希望我是那份工作的最佳人选。"}},{"pos":"PHRASE 短语","cn":"怀着（…发生的）希望","en":"If you do one thing in the hope of another thing happening, you do it because you think it might cause or help the other thing to happen, which is what you want.","ex":{"en":"He was studying in the hope of being admitted to an engineering college","cn":"他努力学习，希望能被一所工程学院录取。"}},{"pos":"PHRASE 短语","cn":"（在不太可能的情况下）对…继续抱有希望，痴心妄想","en":"If you live in hope that something will happen, you continue to hope that it will happen, although it seems unlikely, and you realize that you are being foolish.","ex":{"en":"I just live in hope that one day she'll talk to me","cn":"我只是妄想着有一天她会和我说话。"}},{"pos":"CONVENTION 惯用语","cn":"毫无希望;绝无可能","en":"If you say 'Some hope', or 'Not a hope', you think there is no possibility that something will happen, although you may want it to happen.","ex":{"en":"The industry reckons it will see orders swell by 10% this financial year. Some hope.","cn":"业界估计本财年订单会增加10%。这绝对不可能。"}}]},"examples":[{"en":"I called early in the hope of catching her before she went to work.","cn":"我很早就打了个电话，希望在她上班之前找到她。"},{"en":"He turned to her in despair and said, ‘You're my last hope. ’","cn":"他绝望地向她求助说：“你是我最后的希望。”"}]},"harmonized":{"lemma":"harmonize"},"hears":{"lemma":"hear","media":{"uk":"media/uk/hear__gb_1.mp3","us":"media/us/hear__us_1.mp3"}},"humor":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/humor__gb_1.mp3","us":"media/us/humor__us_1.mp3"},"oxford":{"phon":"ˈhjuːmə(r)","pos":"noun","senses":[{"en":"the quality in something that makes it funny; the ability to laugh at things that are funny","cn":"幽默；幽默感","g":"[uncountable]","ex":{"en":"It was a story full of gentle humor.","cn":"这是一个充满温柔幽默的故事。"}},{"en":"the state of your feelings or mind at a particular time","cn":"感觉；心情；精神状态","g":"[countable, uncountable]","lab":"formal","ex":{"en":"to be in the best of humors","cn":"保持最佳心情"}},{"en":"one of the four liquids that were thought in the past to be in a person’s body and to influence health and character","cn":"体液（旧时认为存在人体内，有四种，可影响健康和性格）","g":"[countable]","lab":"old use"},{"en":"to agree with somebody’s wishes, even if they seem unreasonable, in order to keep the person happy","cn":"迁就；顺应","ex":{"en":"She thought it best to humor him rather than get into an argument.","cn":"她认为最好是迁就他，而不是陷入争论。"},"pos":"verb"}]}},"humankind":{"oxford":{"phon":"ˌhjuːmənˈkaɪnd","pos":"noun","senses":[{"en":"people in general","cn":"（统称）人；人类","ex":{"en":"These advances should be used for the benefit of all humankind.","cn":"这些进步应该用于造福全人类。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 mankind","en":"Humankind is the same as mankind ."}]},"media":{"uk":"media/uk/humankind__gb_1.mp3","us":"media/us/humankind__us_1.mp3"}},"heath":{"media":{"uk":"media/uk/heath__gb_1.mp3","us":"media/us/heath__us_1.mp3"},"oxford":{"phon":"hiːθ","pos":"noun","senses":[{"en":"a large area of open land that is not used for farming and is covered with rough grass and other small wild plants","cn":"（杂草和灌木丛生的）荒地，荒野","ex":{"en":"Wild ponies roam free on the heath.","cn":"野生小马在荒原上自由漫步。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（野草或石南丛生的）荒野，荒原","en":"A heath is an area of open land covered with rough grass or heather and with very few trees or bushes."}]}},"haunted":{"media":{"uk":"media/uk/haunted__gb_1.mp3","us":"media/us/haunted__us_1.mp3"},"oxford":{"phon":"ˈhɔːntɪd","pos":"adjective","senses":[{"en":"believed to be visited by ghosts","cn":"（被认为）闹鬼的，有鬼魂出没的","ex":{"en":"a haunted house","cn":"闹鬼的房子"}},{"en":"showing that somebody is very worried","cn":"忧心忡忡的；满面愁容的","ex":{"en":"There was a haunted look in his eyes.","cn":"他眼中透露出忧虑的神色。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（房屋等）有鬼魂出没的，闹鬼的","en":"A haunted building or other place is one where a ghost regularly appears.","ex":{"en":"Tracy said the cabin was haunted.","cn":"特蕾西说小木屋闹鬼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表情）焦虑的，忧心忡忡的","en":"Someone who has a haunted expression looks very worried or troubled.","ex":{"en":"She looked so haunted, I almost didn't recognize her.","cn":"她愁容满面，我差点儿没认出她来。"}}]},"examples":[{"en":"There was a haunted look in his eyes.","cn":"他眼中透露出忧虑的神色。"},{"en":"a haunted house","cn":"闹鬼的房子"}],"base":"haunt"},"him":{"media":{"uk":"media/uk/him__gb_1.mp3","us":"media/us/him__us_1.mp3"},"oxford":{"phon":"hɪm","pos":"pronoun","senses":[{"en":"used as the object of a verb, after the verb be or after a preposition to refer to a male person or animal that has already been mentioned or is easily identified","cn":"他，它（用作动词或介词的宾语，或作表语）","lab":"British English","ex":{"en":"When did you see him?","cn":"你什么时候见到他的？"}},{"en":"used when referring to God","cn":"（指上帝）"}]},"collins":{"senses":[{"pos":"PRON-SING 单数型代词","cn":"他;它（指雄性动物）","en":"You use him to refer to a man, boy, or male animal.","ex":{"en":"John's aunt died suddenly and left him a surprisingly large sum","cn":"约翰的婶婶突然去世了，留给他一笔巨额财产。"}},{"pos":"PRON-SING 单数型代词","cn":"（书面英语中泛指人）他，她（有些人不喜欢这种用法，更倾向于使用 him or her 或 them）","en":"In written English, him is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'him or her' or 'them'.","ex":{"en":"If the child sees the word 'hear', we should show him that this is the base word in 'hearing' and 'hears'.","cn":"如果孩子看到hear这个词，我们就应该告诉他这是hearing和hears的词干。"}},{"pos":"PRON-SING 单数型代词","cn":"（一些宗教中指）上帝","en":"In some religions, Him is used to refer to God.","ex":{"en":"God will help you if you turn to Him in humility and trust.","cn":"如果你怀着一颗谦恭而信任的心向上帝求助，上帝会帮助你。"}}]},"examples":[{"en":"When did you see him?","cn":"你什么时候见到他的？"},{"en":"He took the children with him.","cn":"他带着孩子。"}]},"hairless":{"media":{"uk":"media/uk/hairless__gb_1.mp3","us":"media/us/hairless__us_1.mp3"},"oxford":{"phon":"ˈheələs","pos":"adjective","senses":[{"en":"without hair","cn":"无发的；无毛的；秃的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（身体部位）无毛的，光秃秃的","en":"A part of your body that is hairless has no hair on it.","ex":{"en":"...a smooth and hairless body.","cn":"光滑无毛的身体"}}]},"examples":[{"en":"Young rabbits are born blind and hairless.","cn":"小兔子生下来时看不见东西﹐而且没有毛。"}]},"hinge":{"oxford":{"phon":"hɪndʒ","pos":"noun","senses":[{"en":"a piece of metal, plastic, etc. on which a door, lid or gate moves freely as it opens or closes","cn":"铰链；合叶","ex":{"en":"The door had been pulled off its hinges.","cn":"门从铰链上扯下来了。"}},{"en":"to attach something with a hinge","cn":"给（某物）装铰链","ex":{"en":"The ironing board was set into the wall and hinged at the bottom.","cn":"烫衣板固定在墙上, 底部装有铰链"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（门等的）铰链，合页","en":"A hinge is a piece of metal, wood, or plastic that is used to join a door to its frame or to join two things together so that one of them can swing freely.","ex":{"en":"The top swung open on well-oiled hinges.","cn":"用润滑良好的铰链固定的盖子一旋转就打开了。"}},{"pos":"","cn":"","en":"相关词组：hinge on"}]},"media":{"img":["media/ldoce/img/hinge.jpg","media/pic/hinge.jpg"],"uk":"media/uk/hinge__gb_1.mp3","us":"media/us/hinge__us_1.mp3"},"examples":[{"en":"His success hinges on how well he does at the interview.","cn":"他能否成功要看他在面试中的表现。"},{"en":"Everything hinges on the outcome of these talks.","cn":"一切都取决于这几次会谈的结果。"}]},"horn":{"oxford":{"phon":"hɔːn","pos":"noun","senses":[{"en":"a hard pointed part that grows, usually in pairs, on the heads of some animals, such as sheep and cows. Horns are often curved.","cn":"（羊、牛等动物的）角","g":"[countable]","ex":{"en":"a large bull with curved horns","cn":"长着弯曲犄角的大公牛"}},{"en":"the hard substance of which animal horns are made","cn":"角质","g":"[uncountable]","ex":{"en":"ornaments made of rhino horn","cn":"犀牛角制成的装饰品"}},{"en":"a device in a vehicle for making a loud sound as a warning or signal","cn":"（车辆的）喇叭","g":"[countable]","lab":"British English","ex":{"en":"to honk your car horn","cn":"按响汽车喇叭"}},{"en":"a simple musical instrument that consists of a curved metal tube that you blow into","cn":"（乐器）号","g":"[countable]","ex":{"en":"a hunting horn","cn":"猎号"}},{"en":"a brass musical instrument that consists of a long tube curled around in a circle with a wide opening at the end","cn":"（铜管乐器）法国号，圆号","g":"[countable]","lab":"especially British English","ex":{"en":"a horn concerto","cn":"法国号协奏曲"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（汽车等的）喇叭;汽笛;警报器","en":"On a vehicle such as a car, the horn is the device that makes a loud noise as a signal or warning.","ex":{"en":"He sounded the car horn.","cn":"他按响了汽车喇叭。"}},{"pos":"N-COUNT 可数名词","cn":"(牛、鹿等动物的）角","en":"The horns of an animal such as a cow or deer are the hard pointed things that grow from its head.","ex":{"en":"A mature cow has horns.","cn":"成年奶牛有犄角。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"角质","en":"Horn is the hard substance that the horns of animals are made of. Horn is sometimes used to make objects such as spoons, buttons, or ornaments."},{"pos":"N-COUNT 可数名词","cn":"（铜管乐器中的）法国号，圆号","en":"A horn is a musical instrument of the brass family. It is a long circular metal tube, wide at one end, which you play by blowing."},{"pos":"N-COUNT 可数名词","cn":"号（角）（一种简单乐器，由一根金属管组成，一端宽，一端窄）","en":"A horn is a simple musical instrument consisting of a metal tube that is wide at one end and narrow at the other. You play it by blowing into it.","ex":{"en":"...a hunting horn.","cn":"猎号"}},{"pos":"N-COUNT 可数名词","cn":"角状物;喇叭形物","en":"A horn is a hollow curved object that is narrow at one end and wide at the other.","ex":{"en":"...a wind-up gramophone with a big horn.","cn":"带有一个大喇叭形扬声器的发条式留声机"}},{"pos":"PHRASE 短语","cn":"自夸;自吹自擂","en":"If you blow your own horn, you boast about yourself."},{"pos":"PHR-RECIP 相互短语","cn":"争吵;争论","en":"If two people lock horns, they argue about something.","ex":{"en":"During his six years in office, Seidman has often locked horns with lawmakers.","cn":"在任的6年中，塞德曼经常和立法议员争得不可开交。"}},{"pos":"PHRASE 短语","cn":"进退维谷;左右为难","en":"If you are on the horns of a dilemma, you have to choose between two things, both of which are unpleasant or difficult.","ex":{"en":"The bird is caught on the horns of a dilemma. Should it attack the predator, even though it then risks its own life? Or should it get out while the going is good?","cn":"这只鸟进退维谷。是应该冒着生命危险攻击捕食者呢？还是应该及早逃命？"}},{"pos":"PHRASE 短语","cn":"变得谨慎行事；（尤指）紧缩开支","en":"If someone pulls in their horns or draws in their horns, they start behaving more cautiously than they did before, especially by spending less money.","ex":{"en":"Customers are drawing in their horns at a time of high interest rates.","cn":"消费者在高利率时期都在紧缩开支。"}},{"pos":"","cn":"","en":"to take the bull by the horns→see: ;"}]},"media":{"img":["media/pic/mammals_comp.jpg","media/thumb/horn.jpg"],"uk":"media/uk/horn__gb_1.mp3","us":"media/us/horn__us_1.mp3"},"examples":[{"en":"I'm sure she doesn't want us horning in on her business.","cn":"我肯定她不希望我们插手她的事。"},{"en":"( BrE ) to sound/toot your horn","cn":"鸣喇叭"}]},"harmed":{"lemma":"harm"},"harbour":{"media":{"uk":"media/uk/harbour__gb_1.mp3","us":"media/us/harbour__us_1.mp3"},"oxford":{"phon":"ˈhɑːbə(r)","pos":"noun","senses":[{"en":"an area of water on the coast, protected from the open sea by strong walls, where ships can shelter","cn":"（海）港；港口；港湾","lab":"figurative","ex":{"en":"Several boats lay at anchor in the harbour.","cn":"港湾里停泊着几条船。"}},{"en":"to hide and protect somebody who is hiding from the police","cn":"窝藏，庇护（罪犯等）","ex":{"en":"Police believe someone must be harbouring the killer.","cn":"警方相信一定有人窝藏了杀人犯。"},"pos":"verb"},{"en":"to keep feelings or thoughts, especially negative ones, in your mind for a long time","cn":"怀有，心怀（尤指负面感情或想法）","ex":{"en":"The arsonist may harbour a grudge against the company.","cn":"纵火犯可能对公司怀恨在心。"},"pos":"verb"},{"en":"to contain something and allow it to develop","cn":"包含；藏有","ex":{"en":"Your dishcloth can harbour many germs.","cn":"洗碗布中可能藏有很多病菌。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"海港;港口;港湾","en":"A harbour is an area of the sea at the coast which is partly enclosed by land or strong walls, so that boats can be left there safely.","ex":{"en":"She led us to a room with a balcony overlooking the harbour","cn":"她把我们领进了一个带阳台的房间，从那里可以俯瞰海港。"}},{"pos":"VERB 动词","cn":"心怀，怀藏，怀有（情感、想法或秘密）","en":"If you harbour an emotion, thought, or secret, you have it in your mind over a long period of time.","ex":{"en":"He might have been murdered by a former client or someone harbouring a grudge","cn":"他可能已经被以前的客户或某个对他怀恨在心的人谋杀了。"}},{"pos":"VERB 动词","cn":"窝藏，庇护（罪犯）","en":"If a person or country harbours someone who is wanted by the police, they let them stay in their house or country and offer them protection.","ex":{"en":"Accusations of harbouring suspects were raised against the former Hungarian leadership.","cn":"匈牙利前领导层被指控窝藏嫌犯。"}}]},"examples":[{"en":"Police believe someone must be harbouring the killer.","cn":"警方相信一定有人窝藏了杀人犯。"},{"en":"The arsonist may harbour a grudge against the company.","cn":"纵火犯可能对公司怀恨在心。"}]},"hang":{"media":{"uk":"media/uk/hang__gb_1.mp3","us":"media/us/hang__us_1.mp3"},"oxford":{"phon":"hæŋ","pos":"verb","senses":[{"en":"to attach something, or to be attached, at the top so that the lower part is free or loose","cn":"悬挂；吊","g":"[transitive, intransitive]","lab":"British English","sc":"attach from top","ex":{"en":"Hang your coat on the hook.","cn":"把你的大衣挂在衣钩上。"}},{"en":"when something hangs in a particular way, it falls in that way","cn":"垂下；垂落","g":"[intransitive]","sc":"fall loosely","ex":{"en":"Her hair hung down to her waist.","cn":"她的长发垂及腰际。"}},{"en":"to bend or let something bend downwards","cn":"（使）低垂，下垂","g":"[intransitive, transitive]","sc":"bend downwards","ex":{"en":"The dog's tongue was hanging out.","cn":"狗的舌头耷拉在外面。"}},{"en":"to kill somebody by tying a rope around their neck and allowing them to drop; to be killed in this way","cn":"（被）绞死，施以绞刑","g":"[transitive, intransitive]","sc":"kill somebody","ex":{"en":"He was the last man to be hanged for murder in this country.","cn":"他是这个国家中最后一个被处以绞刑的谋杀犯。"}},{"en":"to spend time relaxing or enjoying yourself","cn":"休闲；玩耍","g":"[intransitive]","lab":"especially North American English, informal，，","sc":"relax","ex":{"en":"‘What are you all doing?’ ‘Just hanging.’","cn":"“你们都在做什么？”“只是挂着。”"}},{"en":"to attach something, especially a picture, to a hook (= a curved piece of metal) on a wall; to be attached in this way","cn":"（把…）挂在墙上","g":"[transitive, intransitive]","sc":"pictures","ex":{"en":"We hung her portrait above the fireplace.","cn":"我们把她的画像挂在壁炉上方。"}},{"en":"to decorate a place by placing paintings, etc. on a wall","cn":"挂图画等装饰（某处）","g":"[transitive, usually passive]","sc":"pictures","ex":{"en":"The rooms were hung with tapestries.","cn":"这些房间装饰着挂毯。"}},{"en":"to stick wallpaper to a wall","cn":"（在墙上）贴壁纸","g":"[transitive]","sc":"wallpaper"},{"en":"to attach a door or gate to a post so that it moves freely","cn":"把（门）装在门柱上；装（门）","g":"[transitive]","sc":"door/gate"},{"en":"to stay in the air","cn":"悬浮（在空中）","g":"[intransitive]","lab":"figurative","sc":"stay in the air","ex":{"en":"Smoke hung in the air above the city.","cn":"城市上空烟雾弥漫。"}},{"en":"the way in which a dress, piece of cloth, etc. falls or moves","cn":"（衣服、织物等的）悬挂方式，下垂","ex":{"en":"Small weights sewn into the hems will improve the hang of your curtains.","cn":"缝在下摆上的小重物可以改善窗帘的悬挂效果。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"悬挂;吊","en":"If something hangs in a high place or position, or if you hang it there, it is attached there so it does not touch the ground.","ex":{"en":"Notices painted on sheets hang at every entrance","cn":"写在纸上的告示悬挂在每个入口。"}},{"pos":"VERB 动词","cn":"（衣服或织物）下垂，披垂，飘垂","en":"If a piece of clothing or fabric hangs in a particular way or position, that is how it is worn or arranged.","ex":{"en":"...a ragged fur coat that hung down to her calves","cn":"她穿的一件长及小腿肚的破旧毛皮大衣"}},{"pos":"VERB 动词","cn":"（以某种方式）垂下，披下，悬挂","en":"If something hangs loose or hangs open, it is partly fixed in position, but is not firmly held, supported, or controlled, often in such a way that it moves freely.","ex":{"en":"...her long golden hair which hung loose about her shoulders","cn":"她那松散着披在肩上的长长的金发"}},{"pos":"VERB 动词","cn":"悬挂（画等）","en":"If something such as a wall is hung with pictures or other objects, they are attached to it.","ex":{"en":"The walls were hung with huge modern paintings.","cn":"墙上挂着巨幅的现代画。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（被）施以绞刑;（被）绞死","en":"If someone is hanged or if they hang, they are killed, usually as a punishment, by having a rope tied around their neck and the support taken away from under their feet.","ex":{"en":"The five were expected to be hanged at 7 am on Tuesday","cn":"那5个人将在周二早上7点被施以绞刑。"}},{"pos":"VERB 动词","cn":"悬浮","en":"If something such as someone's breath or smoke hangs in the air, it remains there without appearing to move or change position.","ex":{"en":"His breath was hanging in the air before him","cn":"他的哈气悬浮在自己面前。"}},{"pos":"VERB 动词","cn":"逼近;威胁;使忧心忡忡","en":"If a possibility hangs over you, it worries you and makes your life unpleasant or difficult because you think it might happen.","ex":{"en":"A constant threat of unemployment hangs over thousands of university researchers","cn":"持续存在的失业威胁困扰着数千名大学科研人员。"}},{"pos":"VERB 动词","cn":"对…毫不操心;对…满不在乎","en":"Hang is used in expressions such as hang it and hang the money to indicate that you are not concerned about something or the consequences of doing something.","ex":{"en":"Once the Americans decide to do a thing, they do it well, and hang the cost.","cn":"一旦美国人决定要做一件事，他们就会把它做好，且丝毫不计代价。"}},{"pos":"PHRASE 短语","cn":"掌握…的窍门;熟悉…的门道","en":"If you get the hang of something such as a skill or activity, you begin to understand or realize how to do it.","ex":{"en":"It's a bit tricky at first till you get the hang of it.","cn":"刚开始有点儿难，掌握窍门后就好了。"}},{"pos":"PHRASE 短语","cn":"坚持下去;别泄气","en":"If you tell someone to hang in there or to hang on in there, you are encouraging them to keep trying to do something and not to give up even though it might be difficult.","ex":{"en":"Hang in there and you never know what you might achieve.","cn":"坚持下去，你永远都无法预料会有什么样的收获。"}},{"pos":"PHRASE 短语","cn":"放松随便;不拘礼节","en":"If you let it all hang out, you relax completely and enjoy yourself without worrying about hiding your emotions or behaving politely."},{"pos":"","cn":"","en":"to hang by a thread→see: ; to hang on someone's every word→see: ;"},{"pos":"","cn":"","en":"相关词组：hang around hang back hang on hang out hang round hang together hang up"}]},"examples":[{"en":"I haven't heard if I've got the job yet — they've kept me hanging on for days.","cn":"我是否得到了那份工作的事还没消息，他们让我等了好几天了。"},{"en":"I was sure she knew the answer but for some reason she hung back.","cn":"我敢保证她知道答案，但不知为什么她不敢说出来。"}]},"hurting":{"lemma":"hurt"},"hen":{"oxford":{"phon":"hen","pos":"noun","senses":[{"en":"a female chicken, often kept for its eggs or meat","cn":"母鸡","ex":{"en":"a small flock of laying hens","cn":"一小群下蛋的母鸡"}},{"en":"any female bird","cn":"雌禽","ex":{"en":"a hen pheasant","cn":"雌雉"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"母鸡","en":"A hen is a female chicken. People often keep hens in order to eat them or sell their eggs."},{"pos":"N-COUNT 可数名词","cn":"雌禽","en":"The female of any bird can be referred to as a hen .","ex":{"en":"...ostrich hens.","cn":"雌性鸵鸟"}}]},"media":{"uk":"media/uk/hen__gb_1.mp3","us":"media/us/hen__us_1.mp3"},"examples":[{"en":"a small flock of laying hens","cn":"一小群下蛋的母鸡"},{"en":"battery hens","cn":"层架式鸡笼饲养的母鸡"}]},"hack":{"media":{"uk":"media/uk/hack__gb_1.mp3","us":"media/us/hack__us_1.mp3"},"oxford":{"phon":"hæk","pos":"verb","senses":[{"en":"to hit and cut somebody/something in a rough, heavy way","cn":"砍；劈","g":"[transitive, intransitive]","ex":{"en":"I hacked the dead branches off.","cn":"我把枯树枝砍掉了。"}},{"en":"to kick something roughly or without control","cn":"猛踢","g":"[transitive]","ex":{"en":"He hacked the ball away.","cn":"他把球一脚踢开。"}},{"en":"to secretly find a way of looking at and/or changing information on somebody else’s computer system without permission","cn":"非法侵入（他人的计算机系统）","g":"[intransitive, transitive]","lab":"computing","ex":{"en":"He hacked into the bank's computer.","cn":"他侵入了这家银行的计算机。"}},{"en":"to work together informally and often quickly with other people to create a program using different technologies","cn":"（多人合作用不同技术）快速编程","g":"[intransitive]","lab":"computing","ex":{"en":"We spent the morning hacking around with HTML and building web pages.","cn":"我们花了一上午的时间处理 HTML 问题和制作网页。"}},{"en":"to be able/not able to manage in a particular situation","cn":"能／不能应付（某情形）","g":"[transitive]","lab":"informal","ex":{"en":"Lots of people leave this job because they can't hack it.","cn":"很多人由于应付不了这项工作而放弃了。"}},{"en":"to ride a horse for pleasure","cn":"骑马消遣","g":"[intransitive]","lab":"especially British English"},{"en":"to drive a taxi","cn":"开出租车","g":"[intransitive]","lab":"North American English, informal，，"},{"en":"a writer, especially of newspaper articles, who does a lot of low quality work and does not get paid much","cn":"雇佣文人（尤指廉价受雇撰写报纸庸俗文章者）","lab":"disapproving","pos":"noun"},{"en":"a person who does the hard and often boring work for an organization, especially a politician","cn":"（受雇于组织，尤其是政客）从事艰苦乏味工作的人；杂务人员","lab":"disapproving","ex":{"en":"a party hack","cn":"政党杂务人员"},"pos":"noun"},{"en":"an ordinary horse or one that can be hired","cn":"马；可出租的马","pos":"noun"},{"en":"a taxi","cn":"出租车","lab":"North American English, informal，，","pos":"noun"},{"en":"an act of hitting something, especially with a cutting tool","cn":"砍；劈","ex":{"en":"I was sure he was going to take a hack at us.","cn":"我确信他会攻击我们。"},"pos":"noun"},{"en":"a piece of computer code that provides a quick solution to a problem by adding to the official function of a program","cn":"（解决计算机程序问题的）快速修正方法","pos":"noun"},{"en":"a strategy or technique that you use in order to manage an activity in a more efficient way","cn":"好方法；高招","lab":"informal","ex":{"en":"Have you got any clever parenting hacks?","cn":"你有什么育儿高招吗？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"劈;砍;乱劈;猛砍","en":"If you hack something or hack at it, you cut it with strong, rough strokes using a sharp tool such as an axe or knife.","ex":{"en":"An armed gang barged onto the train and began hacking and shooting anyone in sight","cn":"一伙持械歹徒闯上火车，开始见人就砍、举枪便射。"}},{"pos":"VERB 动词","cn":"（在丛林等中）开辟道路","en":"If you hack your way through an area such as a jungle or hack a path through it, you move forward, cutting back the trees or plants that are in your way.","ex":{"en":"We undertook the task of hacking our way through the jungle.","cn":"我们负责在丛林中开路。"}},{"pos":"VERB 动词","cn":"大幅缩减（大小、长度）;大幅降低（价格）","en":"If you hack at or hack something which is too large, too long, or too expensive, you reduce its size, length, or cost by cutting out or getting rid of large parts of it.","ex":{"en":"He hacked away at the story, eliminating one character entirely.","cn":"他大幅缩短了这篇故事，将其中一个人物彻底砍掉了。"}},{"pos":"N-COUNT 可数名词","cn":"（粗制滥造的）职业文人，雇佣文人","en":"If you refer to a professional writer, such as a journalist, as a hack, you disapprove of them because they write for money without worrying very much about the quality of their writing.","ex":{"en":"...tabloid hacks, always eager to find victims in order to sell newspapers.","cn":"为了使报纸好卖而总是急于寻找牺牲品的小报蹩脚记者们"}},{"pos":"N-COUNT 可数名词","cn":"二流政客;政治仆从","en":"If you refer to a politician as a hack, you disapprove of them because they are too loyal to their party and perhaps do not deserve the position they have.","ex":{"en":"Far too many party hacks from the old days still hold influential jobs.","cn":"太多以前的老党棍依然身居要职。"}},{"pos":"VERB 动词","cn":"（尤指为获取机密信息）侵入，非法进入（他人的计算机系统）","en":"If someone hacks into a computer system, they break into the system, especially in order to get secret information.","ex":{"en":"The saboteurs had demanded money in return for revealing how they hacked into the systems.","cn":"那些故意破坏者索要钱财，以作为透露自己是如何非法进入该电脑系统的交换条件。"}},{"pos":"VERB 动词","cn":"骑马","en":"If you hack or go hacking, you go out for a ride on horseback.","ex":{"en":"The children could be seen hacking across the hillside on their ponies.","cn":"可以看到孩子们正骑着小马穿过山坡。"}},{"pos":"N-COUNT 可数名词","cn":"骑马","en":"A hack is a ride on horseback."},{"pos":"N-COUNT 可数名词","cn":"供出租的骑用马","en":"A hack is a horse which people can hire from a stable to go out riding."},{"pos":"PHRASE 短语","cn":"做不来;无法应付","en":"If you say that someone can't hack it or couldn't hack it, you mean that they do not or did not have the qualities needed to do a task or cope with a situation.","ex":{"en":"You have to be strong and confident and never give the slightest impression that you can't hack it","cn":"你必须坚强自信，千万不要给人留下丝毫你应付不来的印象。"}},{"pos":"","cn":"","en":"相关词组：hack away hack off"}]},"examples":[{"en":"Lots of people leave this job because they can't hack it.","cn":"很多人由于应付不了这项工作而放弃了。"},{"en":"We had to hack our way through the jungle.","cn":"我们不得不在丛林中辟路穿行。"}]},"helpful":{"oxford":{"phon":"ˈhelpfl","pos":"adjective","senses":[{"en":"able to improve a particular situation","cn":"有用的；有益的；有帮助的","ex":{"en":"helpful advice/information","cn":"有用的忠告／信息"}},{"en":"willing to help somebody","cn":"愿意帮忙的","ex":{"en":"I called the police but they weren't very helpful.","cn":"我叫了警察，但他们不太肯帮忙。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）给予帮助的，帮上忙的","en":"If you describe someone as helpful, you mean that they help you in some way, such as doing part of your job for you or by giving you advice or information.","ex":{"en":"The staff in the London office are helpful but only have limited information","cn":"伦敦办事处的工作人员给予了帮助，但他们掌握的信息有限。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（信息、建议等）有帮助的，有用的","en":"If you describe information or advice as helpful, you mean that it is useful for you.","ex":{"en":"The catalog includes helpful information on the different bike models available","cn":"目录中包括了在售的各种型号自行车的有用信息。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(事物）有助于改善局面的，有好处的","en":"Something that is helpful makes a situation more pleasant or more easy to tolerate.","ex":{"en":"A predominantly liquid diet for a day or two may be helpful","cn":"一两天里主要吃流质食物可能会有好处。"}}]},"media":{"uk":"media/uk/helpful__gb_1.mp3","us":"media/us/helpful__us_1.mp3"},"examples":[{"en":"It would be helpful for me to see the damage for myself.","cn":"要能亲眼看看造成的破坏会对我有所帮助。"},{"en":"The booklet should be very helpful to parents of disabled children.","cn":"这本小册子对于残疾儿童的父母会很有用。"}]},"holy":{"media":{"uk":"media/uk/holy__gb_1.mp3","us":"media/us/holy__us_1.mp3"},"oxford":{"phon":"ˈhəʊli","pos":"adjective","senses":[{"en":"connected with God or a particular religion","cn":"与神（或宗教）有关的；神圣的","g":"[usually before noun]","ex":{"en":"the Holy Bible","cn":"《圣经》"}},{"en":"good in a moral and religious way","cn":"圣洁的","ex":{"en":"a holy life/man","cn":"圣洁的生活／人"}},{"en":"used to emphasize that you are surprised, afraid, etc.","cn":"（强调惊讶、害怕等）","g":"[only before noun]","lab":"informal","ex":{"en":"Holy cow! What was that?","cn":"天哪！那是什么？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"与上帝（或宗教）有关的;神圣的","en":"If you describe something as holy, you mean that it is considered to be special because it is connected with God or a particular religion.","ex":{"en":"To them, as to all Christians, this is a holy place.","cn":"对他们以及所有基督徒来说，这里是一处圣地。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"虔诚的;圣洁的;献身于宗教（或教会）的","en":"A holy person is a religious leader or someone who leads a religious life.","ex":{"en":"The Indians think of him as a holy man, a combination of doctor and priest.","cn":"印度人把他视为圣人，他既是医生又是僧侣。"}},{"pos":"ADJ 形容词","cn":"（表示惊讶、恐慌等）天啊，上帝啊","en":"Holy is used in exclamations such as 'Holy cow!' and 'Holy smoke!' to express an emotion such as surprise or panic."}]},"examples":[{"en":"Holy cow! What was that?","cn":"天哪！那是什么？"},{"en":"a holy war (= one fought to defend the beliefs of a particular religion)","cn":"圣战"}]},"hobbies":{"lemma":"hobby","media":{"img":["media/pic/hobbies_comp.jpg"]}},"hunting":{"media":{"uk":"media/uk/hunting__gb_1.mp3","us":"media/us/hunting__us_1.mp3"},"oxford":{"phon":"ˈhʌntɪŋ","pos":"noun","senses":[{"en":"going after and killing wild animals as a sport or for food","cn":"狩猎运动；打猎","ex":{"en":"He goes hunting every weekend.","cn":"他每个周末都去打猎。"}},{"en":"a sport in which foxes are hunted by specially trained dogs and by people on horses. Fox hunting with dogs is now illegal in the UK.","cn":"猎狐（一种体育运动，如今在英国用狗猎狐是违法的）","g":"[uncountable]","lab":"British English"},{"en":"the process of looking for something","cn":"找；寻找","ex":{"en":"How's the job-hunting going?","cn":"工作找得怎么样了？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"打猎;狩猎;（野兽的）猎食","en":"Hunting is the chasing and killing of wild animals by people or other animals, for food or as a sport.","ex":{"en":"Hunting is one of Italy's most popular sports","cn":"狩猎是意大利最受欢迎的体育运动之一。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"搜寻;寻找","en":"Hunting is the activity of searching for a particular thing.","ex":{"en":"Jobclub can help you with job hunting.","cn":"失业救助所可以为您在求职方面提供帮助。"}}]},"examples":[{"en":"Since 1977 otter hunting has been illegal.","cn":"捕猎水獭 1977 年以后就被列为非法了。"},{"en":"We're going house-hunting at the weekend.","cn":"周末我们去找房子。"}],"base":"hunt"},"honor":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/honor__gb_1.mp3","us":"media/us/honor__us_1.mp3"},"oxford":{"phon":"ˈɒnə(r)","pos":"noun","senses":[{"en":"great respect for somebody","cn":"尊敬；尊重；崇敬","g":"[uncountable]","ex":{"en":"the guest of honor (= the most important one)","cn":"(正餐等的)主客,贵宾"}},{"en":"something that you are very pleased or proud to do because people are showing you great respect","cn":"指荣幸、光荣","g":"[singular]","ex":{"en":"It was a great honor to be invited here today.","cn":"今天承蒙邀请到此，深感荣幸。"}},{"en":"the quality of knowing and doing what is morally right","cn":"正义感；道义；节操","g":"[uncountable]","ex":{"en":"a man of honor","cn":"守信义的人"}},{"en":"a good reputation; respect from other people","cn":"荣誉；名誉；他人的尊敬","g":"[uncountable]","ex":{"en":"upholding the honor of your country","cn":"捍卫祖国的荣誉"}},{"en":"a person or thing that causes others to respect and admire something/somebody","cn":"引起尊敬（或尊重、崇敬）的人（或事物）","g":"[singular]","ex":{"en":"She is an honor to the profession.","cn":"她是这个职业的荣耀。"}},{"en":"an award, official title, etc. given to somebody as a reward for something that they have done","cn":"（为表扬某人的）奖励，荣誉称号，头衔","g":"[countable]","ex":{"en":"to win the highest honor","cn":"赢得最高荣誉"}},{"en":"a university course that is of a higher level than a basic course (in the US also used to describe a class in school that is at a higher level than other classes)","cn":"大学荣誉学位课程；（美国学校的）优等班","g":"[plural]","lab":"North American English","ex":{"en":"an honors degree/course","cn":"荣誉学位／课程"}},{"en":"if you pass an exam or graduate from a university or school with honors, you receive a special grade for having achieved a very high standard","cn":"优异成绩","g":"[plural]"},{"en":"a title of respect used when talking to or about a judge or a US mayor","cn":"法官大人；（美国）市长阁下","g":"[countable]","ex":{"en":"No more questions, Your Honor.","cn":"没有其他问题了，法官大人。"}},{"en":"the cards that have the highest value","cn":"最大点数的牌","g":"[countable, usually plural]"},{"en":"to do something that shows great respect for somebody/something","cn":"尊敬，尊重（某人）","lab":"ironic","sc":"show respect","ex":{"en":"It was a simple ceremony to honor the Goddess of water.","cn":"这是一个简单的仪式，以纪念水之女神。"},"pos":"verb"},{"en":"to give public praise, an award or a title to somebody for something they have done","cn":"给予表扬（或奖励、头衔、称号）","sc":"give award","ex":{"en":"She has never been properly honored in her own country.","cn":"她在自己的国家从未受到过适当的荣誉。"},"pos":"verb"},{"en":"to do what you have agreed or promised to do","cn":"信守，执行（承诺）","lab":"formal","sc":"keep promise","ex":{"en":"I have every intention of honoring our contract.","cn":"我完全愿意执行我们的合约。"},"pos":"verb"}]}},"hairy":{"media":{"uk":"media/uk/hairy__gb_1.mp3","us":"media/us/hairy__us_1.mp3"},"oxford":{"phon":"ˈheəri","pos":"adjective","senses":[{"en":"covered with a lot of hair","cn":"多毛的","ex":{"en":"a hairy chest/monster","cn":"多毛的胸脯；全身长满毛的怪兽"}},{"en":"dangerous or frightening but often exciting","cn":"惊险的；可怕（但刺激）的","lab":"informal","ex":{"en":"Driving on icy roads can be pretty hairy.","cn":"在结冰的道路上开车很惊险。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多毛的;毛茸茸的","en":"Someone or something that is hairy is covered with hairs.","ex":{"en":"He was wearing shorts which showed his long, muscular, hairy legs","cn":"他穿着短裤，露出自己强壮多毛的长腿。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情况）惊险刺激的，令人担忧的，令人害怕的","en":"If you describe a situation as hairy, you mean that it is exciting, worrying, and rather frightening.","ex":{"en":"His driving was a bit hairy.","cn":"他的车技让人不放心。"}}]},"examples":[{"en":"Driving on icy roads can be pretty hairy.","cn":"在结冰的道路上开车很惊险。"},{"en":"a hairy chest/monster","cn":"多毛的胸脯；长满毛的怪兽"}]},"hence":{"media":{"uk":"media/uk/hence__gb_1.mp3","us":"media/us/hence__us_1.mp3"},"oxford":{"phon":"hens","pos":"adverb","senses":[{"en":"for this reason","cn":"因此；由此","ex":{"en":"We suspect they are trying to hide something, hence the need for an independent inquiry.","cn":"我们怀疑他们在企图隐瞒什么事，因此有必要进行独立调查。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"因此;由此;所以","en":"You use hence to indicate that the statement you are about to make is a consequence of what you have just said.","ex":{"en":"The trade imbalance is likely to rise again in 1990. Hence a new set of policy actions will be required soon","cn":"贸易失衡可能会在1990年再次加剧。因此需要很快采取一系列新的政策行动。"}},{"pos":"ADV 副词","cn":"（尤指未来的长时间）之后","en":"You use hence in expressions such as 'several years hence' or 'six months hence' to refer to a time in the future, especially a long time in the future.","ex":{"en":"The gases that may be warming the planet will have their main effect many years hence.","cn":"可能正导致地球变暖的那些气体，其主要影响将在多年后显现。"}}]},"examples":[{"en":"We suspect they are trying to hide something, hence the need for an independent inquiry.","cn":"我们怀疑他们在企图隐瞒什么事，因此有必要进行独立调查。"},{"en":"The true consequences will only be known several years hence.","cn":"真正的后果只有在几年之后才能知道。"}]},"health":{"media":{"uk":"media/uk/health__gb_1.mp3","us":"media/us/health__us_1.mp3"},"oxford":{"phon":"helθ","pos":"noun","senses":[{"en":"the condition of a person’s body or mind","cn":"人的身体（或精神）状况；健康","ex":{"en":"to be good/bad for your health","cn":"对健康有益／有害"}},{"en":"the state of being physically and mentally healthy","cn":"健康","ex":{"en":"Slowly they nursed him back to health.","cn":"他们慢慢地护理他恢复健康。"}},{"en":"the work of providing medical services","cn":"医疗；保健；卫生","ex":{"en":"All parties are promising to increase spending on health.","cn":"各政党都在许诺增加医疗开支。"}},{"en":"how successful something is","cn":"状况；牢靠性","ex":{"en":"the health of the economy","cn":"经济健康状况"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"健康状况;身体状况","en":"A person's health is the condition of their body and the extent to which it is free from illness or is able to resist illness.","ex":{"en":"Caffeine is bad for your health.","cn":"咖啡因对人体健康有害。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"健康","en":"Health is a state in which a person is not suffering from any illness and is feeling well.","ex":{"en":"In hospital they nursed me back to health.","cn":"在医院里他们对我进行治疗及护理，使我恢复了健康。"}},{"pos":"PHRASE 短语","cn":"为…的健康干杯","en":"When you drink to someone's health or drink their health, you have a drink as a sign of wishing them health and happiness.","ex":{"en":"In the village pub, regulars drank the health of John and his father.","cn":"在村子的酒馆里，老顾客们举杯祝愿约翰和他的父亲身体健康。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"兴旺;良好运行","en":"The health of something such as an organization or a system is its success and the fact that it is working well.","ex":{"en":"There's no way to predict the future health of the banking industry.","cn":"银行业未来是否会兴旺发达根本无法预测。"}}]},"examples":[{"en":"As long as you have your health, nothing else matters.","cn":"只要身体健康，其他任何事都无关紧要。"},{"en":"She was glowing with health and clearly enjoying life.","cn":"她容光焕发，显然生活得很快活。"}]},"hammers":{"lemma":"hammer","media":{"img":["media/pic/tools_diy_comp.jpg","media/thumb/hammer.jpg"],"uk":"media/uk/hammer__gb_1.mp3","us":"media/us/hammer__us_1.mp3"}},"harmony":{"oxford":{"phon":"ˈhɑːməni","pos":"noun","senses":[{"en":"a state of peaceful existence and agreement","cn":"融洽；和睦","g":"[uncountable]","lab":"approving","ex":{"en":"social/racial harmony","cn":"社会／种族融洽"}},{"en":"the way in which different notes that are played or sung together combine to make a pleasant sound","cn":"和声","g":"[uncountable, countable]","lab":"music","ex":{"en":"to sing in harmony","cn":"用和声唱"}},{"en":"an attractive combination of related things","cn":"和谐；协调","g":"[countable, uncountable]","lab":"approving","ex":{"en":"the harmony of colour in nature","cn":"自然界色彩的协调"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（人际关系的）融洽，和睦","en":"If people are living in harmony with each other, they are living together peacefully rather than fighting or arguing.","ex":{"en":"We must try to live in peace and harmony with ourselves and those around us","cn":"我们必须努力和我们自己及周围的人和睦相处。"}},{"pos":"N-VAR 可变名词","cn":"和声;和谐悦耳的音调","en":"Harmony is the pleasant combination of different notes of music played at the same time.","ex":{"en":"...complex vocal harmonies.","cn":"复杂的声乐和声"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（各组成部分的）协调，和谐，调和","en":"The harmony of something is the way in which its parts are combined into a pleasant arrangement.","ex":{"en":"...the ordered harmony of the universe","cn":"宇宙的有序和谐"}}]},"media":{"uk":"media/uk/harmony__gb_1.mp3","us":"media/us/harmony__us_1.mp3"},"examples":[{"en":"passionate lyrics and stunning vocal harmonies","cn":"充满激情的歌词和绝妙的和声演唱"},{"en":"the need to be in harmony with our environment","cn":"同我们的环境协调的必要"}]},"hybrid":{"oxford":{"phon":"ˈhaɪbrɪd","pos":"adjective","senses":[{"en":"having parents of different species or varieties","cn":"有不同物种或品种的双亲的","ex":{"en":"hybrid flowers","cn":"杂交花"}},{"en":"that is the product of mixing two or more different things","cn":"指两个或多个不同事物混合的产物","ex":{"en":"a hybrid language","cn":"混合语言"}},{"en":"using two different types of power, especially petrol or diesel and electricity","cn":"使用两种不同类型的动力，尤其是汽油、柴油和电力","ex":{"en":"a hybrid car/vehicle","cn":"混合动力车"}},{"en":"an animal or plant that has parents of different species or varieties","cn":"杂种动物；杂交植物；杂种","ex":{"en":"A mule is a hybrid of a male donkey and a female horse.","cn":"骡子是公驴和母马交配而生的杂种动物。"},"pos":"noun"},{"en":"something that is the product of mixing two or more different things","cn":"（不同事物的）混合物，合成物","ex":{"en":"The music was a hybrid of Western pop and traditional folk song.","cn":"这种音乐融合了西方流行音乐和传统民歌。"},"pos":"noun"},{"en":"a vehicle that uses two different types of power, especially petrol or diesel and electricity","cn":"混合动力车（尤指汽油或柴油与电混合使用）","pos":"noun"},{"en":"a bicycle that has been designed for use on the road or on rough ground","cn":"公路山地两用自行车","ex":{"en":"The rented bike was a hybrid that rode like a dream.","cn":"租来的自行车是一辆混合动力车，骑起来就像梦一样。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（动物或植物的）杂（交）种，混（合）种","en":"A hybrid is an animal or plant that has been bred from two different species of animal or plant.","ex":{"en":"All these brightly coloured hybrids are so lovely in the garden.","cn":"花园里所有这些色彩鲜艳的杂交花真美丽。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指两种不同物质的）混合物，合成物","en":"You can use hybrid to refer to anything that is a mixture of other things, especially two other things.","ex":{"en":"...a hybrid of solid and liquid fuel.","cn":"固体和液体燃料的混合物"}},{"pos":"","cn":"混合动力车；油电混合车","en":"A hybrid or a hybrid car is a car that has both an electric motor and an ordinary car engine. It uses the ordinary engine when it needs extra power.","ex":{"en":"Hybrids, unlike pure electric cars, never need to be plugged in.","cn":"与纯电动汽车不同，混合动力车永远不需要接电源。"}}]},"media":{"uk":"media/uk/hybrid__gb_1.mp3","us":"media/us/hybrid__us_1.mp3"},"examples":[{"en":"The music was a hybrid of Western pop and traditional folk song.","cn":"这种音乐融合了西方流行音乐和传统民歌。"},{"en":"A mule is a hybrid of a male donkey and a female horse.","cn":"骡子是公驴和母马交配而生的杂种动物。"}]},"humbly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wanting to talk about your abilities or achievements and to say that you are good at something, even when you are – used to show approval","cn":""},{"en":"not wanting to talk about yourself or to attract attention","cn":""}]},"examples":[{"en":"He started his career as a humble peanut farmer.","cn":"","src":"ld"},{"en":"Iacocca rose from humble beginnings to become boss of Ford.","cn":"","src":"ld"}],"media":{"uk":"media/uk/humbly__gb_1.mp3","us":"media/us/humbly__us_1.mp3"},"oxford":{"phon":"ˈhʌmbli","pos":"adverb","senses":[{"en":"in a way that shows you do not think you are as important as other people","cn":"谦逊的；虚心的","ex":{"en":"I would humbly suggest that there is something wrong here.","cn":"愚以为此处有误。"}},{"en":"born into a low social position","cn":"（级别或地位）低下的，卑微的"}]}},"headquartered":{"media":{"uk":"media/uk/headquartered__gb_1.mp3","us":"media/us/headquartered__us_1.mp3"},"oxford":{"phon":"ˌhedˈkwɔːtəd","pos":"adjective","senses":[{"en":"having headquarters in a particular place","cn":"总部在某地","ex":{"en":"News Corporation is headquartered in New York.","cn":"新闻集团的总部设在纽约。"}}]},"collins":{"senses":[{"pos":"V-PASSIVE 被动动词","cn":"总部设在…","en":"If an organization is headquartered in a particular place, that is where its main offices are.","ex":{"en":"The company is headquartered in Chicago.","cn":"公司总部设在芝加哥。"}}]},"examples":[{"en":"News Corporation is headquartered in New York.","cn":"新闻集团的总部设在纽约。"},{"en":"Many top companies are headquartered in northern California.","cn":"很多大公司都把总部设在加利福尼亚北部。"}]},"hormonal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"激素的;荷尔蒙的;有关激素的","en":"Hormonal means relating to or involving hormones.","ex":{"en":"...our individual hormonal balance.","cn":"我们每个人体内的激素平衡"}}]},"media":{"uk":"media/uk/hormonal__gb_1.mp3","us":"media/us/hormonal__us_1.mp3"},"examples":[{"en":"the hormonal changes occurring during pregnancy","cn":"妊娠期间的激素变化"}],"oxford":{"phon":"hɔːˈməʊnl","pos":"adjective","senses":[{"en":"connected with hormones (= chemicals produced in the body or in a plant that influence how cells and tissues function)","cn":"激素的","g":"[usually before noun]","ex":{"en":"the hormonal changes occurring during pregnancy","cn":"妊娠期间的激素变化"}},{"en":"affected by hormone changes in your body in a way that makes you feel emotional","cn":"（因激素的关系而）情绪变化的","lab":"informal","ex":{"en":"I was 14—rebellious, sulky and hormonal.","cn":"那年我 14 岁——叛逆、闷闷不乐、荷尔蒙旺盛。"}}]}},"hurt":{"oxford":{"phon":"hɜːt","pos":"verb","senses":[{"en":"to cause physical pain to somebody/yourself; to injure somebody/yourself","cn":"（使）疼痛，受伤","g":"[transitive, intransitive]","lab":"especially British English","ex":{"en":"He hurt his back playing squash.","cn":"他打壁球时背部受伤了。"}},{"en":"to feel painful","cn":"感到疼痛","g":"[intransitive]","ex":{"en":"My feet hurt.","cn":"我脚疼。"}},{"en":"to make somebody unhappy or upset","cn":"使不快；使烦恼","g":"[intransitive, transitive]","ex":{"en":"What really hurt was that he never answered my letter.","cn":"真正让我伤心的是他从不给我回信。"}},{"en":"to feel unhappy or upset","cn":"感到不高兴（或烦恼）","g":"[intransitive]","lab":"informal","ex":{"en":"I know you're hurting and I want to help you.","cn":"我知道你心烦，我想帮助你。"}},{"en":"to have a bad effect on somebody/something","cn":"对…有不良影响","g":"[transitive]","ex":{"en":"Hard work never hurt anyone.","cn":"努力工作绝无害处。"}},{"en":"to be in a difficult situation because you need something, especially money","cn":"处于困境；手头拮据","g":"[intransitive]","lab":"North American English","ex":{"en":"His campaign is already hurting for money.","cn":"他从事的社会运动已经因缺乏经费而难以为继了。"}},{"en":"injured physically","cn":"（身体上）受伤的","ex":{"en":"None of the passengers were badly hurt.","cn":"乘客中没有人严重受伤。"},"pos":"adjective"},{"en":"upset and offended by something that somebody has said or done","cn":"（感情上）受伤的","ex":{"en":"a hurt look/expression","cn":"伤心的眼神／表情"},"pos":"adjective"},{"en":"a feeling of unhappiness because somebody has been unkind or unfair to you","cn":"心灵创伤；委屈","ex":{"en":"There was hurt and real anger in her voice.","cn":"她的声音里有难过，也有真正的愤怒。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使（自己或身体某部位）受伤","en":"If you hurt yourself or hurt a part of your body, you feel pain because you have injured yourself.","ex":{"en":"Yasin had seriously hurt himself while trying to escape from the police","cn":"亚辛试图从警察手中逃脱时受了重伤。"}},{"pos":"VERB 动词","cn":"（身体某部位）感到疼痛","en":"If a part of your body hurts, you feel pain there.","ex":{"en":"His collar bone only hurt when he lifted his arm.","cn":"他的锁骨只有在抬臂时才感觉到痛。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受伤的","en":"If you are hurt, you have been injured.","ex":{"en":"His comrades asked him if he was hurt","cn":"战友问他是否受伤了。"}},{"pos":"VERB 动词","cn":"弄伤，弄痛（他人）","en":"If you hurt someone, you cause them to feel pain.","ex":{"en":"I didn't mean to hurt her, only to keep her still","cn":"我不是故意要弄痛她，只是想让她别乱动。"}},{"pos":"VERB 动词","cn":"伤害（感情）;使伤心","en":"If someone hurts you, they say or do something that makes you unhappy.","ex":{"en":"He is afraid of hurting Bessy's feelings","cn":"他怕伤害了贝茜的感情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（感情上）受到伤害的，伤心的","en":"If you are hurt, you are upset because of something that someone has said or done.","ex":{"en":"Yes, I was hurt, jealous","cn":"是的，我感到伤心、嫉妒。"}},{"pos":"VERB 动词","cn":"伤心;感到痛苦","en":"If you say that you are hurting, you mean that you are experiencing emotional pain.","ex":{"en":"I am lonely and I am hurting.","cn":"我很孤单，很难过。"}},{"pos":"VERB 动词","cn":"危害;损害;妨碍;对…产生不良影响","en":"To hurt someone or something means to have a bad effect on them or prevent them from succeeding.","ex":{"en":"The combination of hot weather and decreased water supplies is hurting many industries","cn":"炎热的天气和供水的减少正危及很多行业。"}},{"pos":"N-VAR 可变名词","cn":"伤心;痛苦;委屈","en":"A feeling of hurt is a feeling that you have when you think that you have been treated badly or judged unfairly.","ex":{"en":"...feelings of hurt and anger, fear and despair","cn":"伤心、愤怒、恐惧、绝望的复杂情感"}},{"pos":"PHRASE 短语","cn":"（做…）不会有坏处","en":"If you say 'It won't hurt to do something' or 'It never hurts to do something', you are recommending an action which you think is helpful or useful.","ex":{"en":"It never hurts to ask","cn":"多问无妨。"}}]},"media":{"uk":"media/uk/hurt__gb_1.mp3","us":"media/us/hurt__us_1.mp3"},"examples":[{"en":"Our eyes were burning from the chemicals in the air.","cn":"空气中弥漫的化学物质熏得我们的眼睛火辣辣地痛。"},{"en":"His campaign is already hurting for money.","cn":"他从事的社会运动已经因缺乏经费而难以为继了。"}]},"historian":{"media":{"uk":"media/uk/historian__gb_1.mp3","us":"media/us/historian__us_1.mp3"},"oxford":{"phon":"hɪˈstɔːriən","pos":"noun","senses":[{"en":"a person who studies or writes about history; an expert in history","cn":"史学工作者；历史学家","ex":{"en":"No serious historian today accepts this theory.","cn":"当今任何一位严肃的史学家都不会接受这种理论。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"历史学家","en":"A historian is a person who specializes in the study of history, and who writes books and articles about it."}]}},"hyperbole":{"media":{"uk":"media/uk/hyperbole__gb_1.mp3","us":"media/us/hyperbole__us_1.mp3"},"oxford":{"phon":"haɪˈpɜːbəli","pos":"noun","senses":[{"en":"a way of speaking or writing that makes something sound better, more exciting, more dangerous, etc. than it really is","cn":"夸张","ex":{"en":"The film is being promoted with all the usual hyperbole.","cn":"这部电影的宣传方式与平常一样夸张。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"夸张（法）","en":"If someone uses hyperbole, they say or write things that make something sound much more impressive than it really is.","ex":{"en":"...the hyperbole that portrays him as one of the greatest visionaries in the world.","cn":"将他描绘成世界上最伟大的愿景家之一的夸张"}}]},"examples":[{"en":"It was not hyperbole to call it the worst storm in twenty years.","cn":"称它是20年来最大的风暴并不为过。"}]},"hasn't":{"media":{"uk":"media/uk/hasn_t_1_gb_1.mp3","us":"media/us/hasn_t_1_us_1.mp3"},"oxford":{"phon":"ˈhæznt","pos":"short form","senses":[{"en":"has not","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（has not 的常用口语形式）","en":"Hasn't is the usual spoken form of 'has not'."}]},"examples":[{"en":"Hasn’t she finished yet?","cn":""}]},"herald":{"media":{"uk":"media/uk/herald__gb_1.mp3","us":"media/us/herald__us_1.mp3"},"oxford":{"phon":"ˈherəld","pos":"verb","senses":[{"en":"to be a sign that something is going to happen","cn":"是（某事）的前兆；预示","ex":{"en":"These talks could herald a new era of peace.","cn":"这些谈判可能预示着新的和平时代的来临。"}},{"en":"to say in public that somebody/something is good or important","cn":"宣称（…是好的或重要的）","g":"[often passive]","ex":{"en":"The report is being heralded as a blueprint for the future of transport.","cn":"这份报告被宣称是未来运输的蓝图。"}},{"en":"something that shows that something else is going to happen soon","cn":"预兆","ex":{"en":"The government claims that the fall in unemployment is the herald of economic recovery.","cn":"政府宣称失业人数减少是经济复苏的先兆。"},"pos":"noun"},{"en":"a person who made announcements and carried messages from a ruler","cn":"信使；传令官；使者","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"预告;预示…的来临","en":"Something that heralds a future event or situation is a sign that it is going to happen or appear.","ex":{"en":"...the sultry evening that heralded the end of the baking hot summer","cn":"预示着炙热的夏天即将结束的闷热夜晚"}},{"pos":"N-COUNT 可数名词","cn":"预兆","en":"Something that is a herald of a future event or situation is a sign that it is going to happen or appear.","ex":{"en":"I welcome the report as a herald of more freedom, not less","cn":"我认为这份报告预示着会有更多、而不是更少的自由，因此对它表示欢迎。"}},{"pos":"VERB 动词","cn":"宣布;报告…的消息","en":"If an important event or action is heralded by people, announcements are made about it so that it is publicly known and expected.","ex":{"en":"Janet Jackson's new album has been heralded by a massive media campaign","cn":"珍妮·杰克逊的新专辑已经在媒体上进行了大规模宣传。"}},{"pos":"N-COUNT 可数名词","cn":"（古时的）传令官，使节","en":"In former times, a herald was a person who delivered and announced important messages."}]},"examples":[{"en":"These talks could herald a new era of peace.","cn":"这些谈判可能预示着新的和平时代的来临。"},{"en":"The government claims that the fall in unemployment is the herald of economic recovery.","cn":"政府宣称失业人数减少是经济复苏的先兆。"}]},"high-tech":{"oxford":{"phon":"ˌhaɪ ˈtek","pos":"adjective","senses":[{"en":"using the most modern methods and machines, especially electronic ones","cn":"高技术的，高科技的（尤指电子方面）","ex":{"en":"high-tech industries","cn":"高科技产业"}},{"en":"very modern in appearance; using modern materials","cn":"样式新颖的；用高新技术材料的","ex":{"en":"a high-tech table made of glass and steel","cn":"用玻璃和钢制成的现代化桌子"}}]},"media":{"uk":"media/uk/high_tech_1_gb_1.mp3","us":"media/us/high_tech_1_us_1.mp3"},"examples":[{"en":"a high-tech table made of glass and steel","cn":"用玻璃和钢制成的现代化桌子"},{"en":"high-tech industries","cn":"高科技产业"}]},"help":{"media":{"uk":"media/uk/help__gb_1.mp3","us":"media/us/help__us_1.mp3"},"oxford":{"phon":"help","pos":"verb","senses":[{"en":"to make it easier or possible for somebody to do something by doing something for them or by giving them something that they need","cn":"帮助；协助；援助","g":"[intransitive, transitive]","lab":"informal or North American English","sc":"make easier/better","ex":{"en":"What can I do to help?","cn":"我能提供什么帮助吗？"}},{"en":"to improve a situation; to make it easier for something to happen","cn":"改善状况；促进；促使","g":"[intransitive, transitive]","sc":"make easier/better","ex":{"en":"The support of our families has helped enormously.","cn":"家庭的支持给了我们巨大的帮助。"}},{"en":"to help somebody move or do some other action by letting them lean on you, guiding them, etc.","cn":"搀扶；扶着走；带领","g":"[transitive]","sc":"somebody to move","ex":{"en":"She helped him to his feet.","cn":"她扶他站了起来。"}},{"en":"to give yourself/somebody food, drinks, etc.","cn":"为（自己或某人）取用","g":"[transitive]","sc":"give food/drink","ex":{"en":"If you want another drink, just help yourself.","cn":"你要是想再喝一杯就请自便。"}},{"en":"to take something without permission","cn":"擅自拿走；窃取","g":"[transitive]","lab":"informal, disapproving，，","sc":"steal","ex":{"en":"He'd been helping himself to the money in the cash register.","cn":"他一直在偷现金出纳机中的钱。"}},{"en":"the act of helping somebody to do something","cn":"帮助；协助；援助","g":"[uncountable]","sc":"making easier/better","ex":{"en":"Thank you for all your help.","cn":"感谢你的一切帮助。"},"pos":"noun"},{"en":"the act of helping somebody who is in danger","cn":"救助","g":"[uncountable]","sc":"for somebody in danger","ex":{"en":"Quick, get help!","cn":"快，找人援救！"},"pos":"noun"},{"en":"advice, money, etc. that is given to somebody in order to solve their problems","cn":"有助益的东西（如忠告、钱等）","g":"[uncountable]","sc":"advice/money","ex":{"en":"professional/medical/financial help","cn":"专业／医疗／财政援助"},"pos":"noun"},{"en":"a function on a computer, phone, etc. that provides information on how to use the computer, phone, etc.","cn":"（计算机、电话等的）帮助功能","g":"[uncountable]","sc":"on a computer/phone, etc.","ex":{"en":"The online help is very good.","cn":"线上帮助功能很有用。"},"pos":"noun"},{"en":"the fact of being useful","cn":"有用","g":"[uncountable]","sc":"being useful","ex":{"en":"The map wasn't much help.","cn":"这张地图没多大用处。"},"pos":"noun"},{"en":"a person or thing that helps somebody","cn":"有帮助的人（或事物）","g":"[singular]","lab":"ironic","sc":"person/thing","ex":{"en":"She was more of a hindrance than a help.","cn":"她非但没帮上忙，反而碍事。"},"pos":"noun"},{"en":"the person or people employed by somebody to clean their house, etc.","cn":"帮工；家政人员","g":"[uncountable + singular or plural verb]","lab":"especially North American English","sc":"in house","pos":"noun"},{"en":"used to call for help because you are in a dangerous situation","cn":"救命（遇到危险时用于呼救）","ex":{"en":"Help, I'm stuck!","cn":"救命，我被卡住了！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"帮助;帮忙","en":"If you help someone, you make it easier for them to do something, for example by doing part of the work for them or by giving them advice or money.","ex":{"en":"He has helped to raise a lot of money","cn":"他帮着筹集了很多钱。"}},{"pos":"VERB 动词","cn":"有帮助;有用","en":"If you say that something helps, you mean that it makes something easier to do or get, or that it improves a situation to some extent.","ex":{"en":"The right style of swimsuit can help to hide, minimise or emphasise what you want it to","cn":"款式选择得当的泳装有助于按照意愿掩饰、缩小或突出某些部位。"}},{"pos":"VERB 动词","cn":"扶持;搀扶","en":"If you help someone go somewhere or move in some way, you give them support so that they can move more easily.","ex":{"en":"Martin helped Tanya over the rail","cn":"马丁扶着塔尼娅越过栏杆。"}},{"pos":"VERB 动词","cn":"帮助（自己）摆脱困境","en":"If you help yourself, you try to get yourself out of a difficult situation rather than accept it and think you can do nothing to change it.","ex":{"en":"He tries to help people with problems, but firmly believes they should do more to help themselves.","cn":"他尽力帮助有困难的人，但仍坚信他们应该更加努力自救。"}},{"pos":"N-SING 单数名词","cn":"帮助解决困难的人（或事物）","en":"If you say that someone or something has been a help or has been some help, you mean that they have helped you to solve a problem.","ex":{"en":"Thank you. You've been a great help already.","cn":"谢谢你。你已经帮了大忙了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"援救;救命","en":"Help is action taken to rescue a person who is in danger. You shout 'help!' when you are in danger in order to attract someone's attention so that they can come and rescue you.","ex":{"en":"He was screaming for help","cn":"他高呼求救。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"帮助（文件）","en":"In computing, help, or the help menu, is a file that gives you information and advice, for example about how to use a particular program.","ex":{"en":"If you get stuck, click on Help.","cn":"如果碰到疑难，就点击“帮助”。"}},{"pos":"VERB 动词","cn":"自助;自取","en":"If you help yourself to something, you serve yourself or you take it for yourself. If someone tells you to help yourself, they are telling you politely to serve yourself anything you want or to take anything you want.","ex":{"en":"There's bread on the table. Help yourself","cn":"桌上有面包。你自己拿吧。"}},{"pos":"VERB 动词","cn":"偷;窃取","en":"If someone helps themselves to something, they steal it.","ex":{"en":"Has somebody helped himself to some film star's diamonds?","cn":"有人偷了某个影星的钻石了吗？"}},{"pos":"PHRASE 短语","cn":"不禁;忍不住;无法控制","en":"If you can't help the way you feel or behave, you cannot control it or stop it happening. You can also say that you can't help yourself .","ex":{"en":"I can't help feeling sorry for the poor man","cn":"我不禁为这个可怜的男人感到难过。"}},{"pos":"PHRASE 短语","cn":"（用于委婉地表示观点）不免，禁不住（想）","en":"If you say you can't help thinking something, you are expressing your opinion in an indirect way, often because you think it seems rude.","ex":{"en":"I can't help feeling that this may just be another of her schemes","cn":"我不免觉得这可能只是她的又一个诡计。"}},{"pos":"PHRASE 短语","cn":"有帮助;有用","en":"If someone or something is of help, they make a situation easier or better.","ex":{"en":"Can I be of help to you?","cn":"我能帮上你吗？"}},{"pos":"","cn":"","en":"相关词组：help off with help on with help out"}]},"examples":[{"en":"I always end up having an argument with her, I don't know why, I just can't help it.","cn":"我总是和她意见不合，闹得不欢而散，我不知道为什么，我就是忍不住。"},{"en":"a help key/screen (= a function on a computer that provides information on how to use the computer)","cn":"帮助键/屏幕（计算机中提供计算机使用信息的功能）"}]},"heal":{"media":{"uk":"media/uk/heal__gb_1.mp3","us":"media/us/heal__us_1.mp3"},"oxford":{"phon":"hiːl","pos":"verb","senses":[{"en":"to become healthy again; to make something healthy again","cn":"（使）康复，复原","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"It took a long time for the wounds to heal.","cn":"伤口过了很长时间才愈合。"}},{"en":"to cure somebody who is ill; to make somebody feel happy again","cn":"治疗（病人）；使又愉快起来","g":"[transitive]","lab":"old use or formal","ex":{"en":"the story of Jesus healing ten lepers of their disease","cn":"耶稣治愈十个麻风病人的故事"}},{"en":"to put an end to something or make something easier to bear; to end or become easier to bear","cn":"（使）结束，较容易忍受","g":"[transitive, intransitive]","ex":{"en":"She was never able to heal the rift between herself and her father.","cn":"她一直未能填平和她父亲之间的鸿沟。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"痊愈;愈合;治愈","en":"When a broken bone or other injury heals or when something heals it, it becomes healthy and normal again.","ex":{"en":"Within six weeks the bruising had gone, but it was six months before it all healed","cn":"青瘀在6周内就消退了，但伤却是6个月后才全好了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（感情创伤）愈合;（情感）恢复常态","en":"When someone's emotional pain heals, they feel normal and happy again.","ex":{"en":"A year later, she had healed to the point of at least being able to consider a romantic relationship with another man","cn":"一年以后，她的感情创伤已慢慢愈合，至少能考虑和另一个男性开始恋爱关系了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（裂痕、创伤）弥合;（使）和好","en":"If you heal something such as a rift or a wound, or if it heals, the situation is put right so that people are friendly or happy again.","ex":{"en":"Today Sophie and her sister have healed the family rift and visit their family every weekend","cn":"如今索菲和她的姐姐已经和家人和好，每个周末都回家探望他们。"}},{"pos":"","cn":"","en":"相关词组：heal up"}]},"examples":[{"en":"She was never able to heal the rift between herself and her father.","cn":"她一直未能填平和她父亲之间的鸿沟。"},{"en":"The breach between them never really healed.","cn":"他们之间的裂痕从来没有真正弥合。"}]},"hobby":{"oxford":{"phon":"ˈhɒbi","pos":"noun","senses":[{"en":"an activity that you do for pleasure when you are not working","cn":"业余爱好","ex":{"en":"Do you have any hobbies?","cn":"你有什么业余爱好吗 ?"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"业余爱好;嗜好","en":"A hobby is an activity that you enjoy doing in your spare time.","ex":{"en":"My hobbies are letter writing, football, music, photography, and tennis.","cn":"我的业余爱好是写信、踢足球、听音乐、玩摄影和打网球。"}}]},"media":{"img":["media/pic/creativehobbies_comp.jpg","media/thumb/model.jpg"],"uk":"media/uk/hobby__gb_1.mp3","us":"media/us/hobby__us_1.mp3"},"examples":[{"en":"I only play jazz as a hobby.","cn":"我弹奏爵士乐只是一种业余爱好。"},{"en":"Her hobbies include swimming and gardening.","cn":"她爱好游泳和园艺。"}]},"hungry":{"media":{"uk":"media/uk/hungry__gb_1.mp3","us":"media/us/hungry__us_1.mp3"},"oxford":{"phon":"ˈhʌŋɡri","pos":"adjective","senses":[{"en":"feeling that you want to eat something","cn":"感到饿的","ex":{"en":"I'm really hungry.","cn":"我饿极了。"}},{"en":"not having enough food to eat","cn":"饥饿的；挨饿的","ex":{"en":"Thousands are going hungry because of the failure of this year's harvest.","cn":"由于今年粮食歉收，成千上万的人将挨饿。"}},{"en":"people who do not have enough food to eat","cn":"（统称）饥民","g":"[plural]"},{"en":"causing you to feel that you want to eat something","cn":"使人饥饿的；引起食欲的","g":"[only before noun]","ex":{"en":"All this gardening is hungry work.","cn":"这些园艺活儿让人干了肚子饿。"}},{"en":"having or showing a strong desire for something","cn":"渴望得到；渴求","ex":{"en":"power-hungry corporations","cn":"渴求权力的公司"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"饥饿的;感到饿的;辘辘饥肠的","en":"When you are hungry, you want some food because you have not eaten for some time and have an uncomfortable or painful feeling in your stomach.","ex":{"en":"My friend was hungry, so we drove to a shopping mall to get some food","cn":"我的朋友饿了，于是我们开车去一家购物中心吃饭。"}},{"pos":"PHRASE 短语","cn":"挨饿;吃不饱","en":"If people go hungry, they do not have enough food to eat.","ex":{"en":"Leonidas' family had been poor, he went hungry for years.","cn":"利奥尼达斯家曾经很穷，他有很多年都吃不饱肚子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"渴望的;热望的","en":"If you say that someone is hungry for something, you are emphasizing that they want it very much.","ex":{"en":"Susan was certainly hungry for a life different from the one she had made for herself","cn":"苏珊无疑一心想过一种和现在不同的生活。"}}]},"examples":[{"en":"Thousands are going hungry because of the failure of this year's harvest.","cn":"由于今年粮食歉收，成千上万的人将挨饿。"},{"en":"They gazed hungrily at the display of food.","cn":"他们饥肠辘辘地盯着那些摆放着的食物。"}]},"heavens":{"lemma":"heaven"},"hotels":{"lemma":"hotel"},"hundreds":{"lemma":"hundred"},"hangs":{"lemma":"hang"},"hairs":{"lemma":"hair"},"hunters":{"oxford":{"phon":"ˈhʌntə(r)","pos":"noun","senses":[{"en":"a person who hunts wild animals for food or sport; an animal that hunts its food","cn":"猎人；狩猎者；（猎食其他动物的）猎兽"},{"en":"( usually in compounds","cn":"通常构成复合词 ) a person who looks for and collects a particular kind of thing 搜集某种东西的人"}]}},"hooks":{"lemma":"hook"},"housings":{"lemma":"house"},"helicopters":{"lemma":"helicopter"},"helps":{"lemma":"help"},"habits":{"lemma":"habit"},"heroes":{"lemma":"hero"},"heels":{"lemma":"heel"},"housemaids":{"oxford":{"phon":"ˈhaʊsmeɪd","pos":"noun","senses":[{"en":"a female servant in a large house who cleans the rooms, etc. and often lives there （","cn":"家庭的）女仆，女佣"}]}},"hillocks":{"oxford":{"phon":"ˈhɪlək","pos":"noun","senses":[{"en":"a small hill","cn":"小丘"}]}},"handed":{"lemma":"hand"},"hurries":{"lemma":"hurry"},"housewives":{"lemma":"housewife"},"honed":{"oxford":{"phon":"həʊn","pos":"verb","senses":[{"en":"to develop and improve sth, especially a skill, over a period of time","cn":"磨练，训练（尤指技艺）"},{"en":"to make a blade sharp or sharper","cn":"磨（刀）；把（刀）磨快"}]}},"happens":{"lemma":"happen"},"households":{"lemma":"household"},"harder":{"lemma":"hard"},"hacked":{"lemma":"hack"},"hacking":{"oxford":{"phon":"ˈhækɪŋ","pos":"noun","senses":[{"en":"the activity of using computers to get access to data in somebody else's computer or phone system without permission","cn":"黑客行为；黑客攻击；非法侵入他人计算机（或手机）系统","ex":{"en":"The government tax website is vulnerable to hacking, putting taxpayers' information at risk.","cn":"政府税收网站容易遭到黑客入侵，使纳税人的信息受到威胁。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（咳嗽）干涩刺耳的","en":"A hacking cough is a dry, painful cough with a harsh, unpleasant sound.","ex":{"en":"The quiet was broken by Astley's hacking cough.","cn":"这片宁静被阿斯特利刺耳的干咳声打破了。"}}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41hacker.mp3","us":"media/ldoce/hwd/ame/7/hacker.mp3"},"examples":[{"en":"A hacker had managed to get into the system.","cn":""}],"base":"hack"},"houses":{"lemma":"house"},"highways":{"lemma":"highway"},"hoping":{"lemma":"hope"},"helped":{"lemma":"help"},"holidaymakers":{"oxford":{"phon":"ˈhɒlədeɪmeɪkə(r)","pos":"noun","senses":[{"en":"a person who is visiting a place on holiday/vacation","cn":"度假者"}]}},"huts":{"lemma":"hut"},"heights":{"lemma":"height"},"heads":{"lemma":"head"},"hoped":{"lemma":"hope"},"highest":{"lemma":"high"},"horizons":{"lemma":"horizon"},"hats":{"lemma":"hat","media":{"img":["media/pic/hats_comp.jpg"]}},"heard":{"lemma":"hear"},"humans":{"lemma":"human"},"holidays":{"lemma":"holiday"},"haggling":{"lemma":"haggle","media":{"uk":"media/ldoce/hwd/bre/f/haggle0205.mp3","us":"media/ldoce/hwd/ame/0/haggle.mp3"}},"herding":{"lemma":"herd"},"hurrying":{"lemma":"hurry"},"hopes":{"lemma":"hope"},"heavier":{"lemma":"heavy"},"heightened":{"lemma":"heighten"},"hangers":{"oxford":{"phon":"ˈhæŋə(r)","pos":"noun","senses":[{"en":"a curved piece of wood, plastic or wire, with a hook at the top, that you use to hang clothes up on","cn":"衣架"}]}},"hesitating":{"lemma":"hesitate"},"holidaying":{"lemma":"holiday"},"hours":{"lemma":"hour"},"herbs":{"lemma":"herb","media":{"img":["media/pic/herbs_comp.jpg"]}},"happened":{"lemma":"happen"},"hands":{"lemma":"hand"},"historians":{"lemma":"historian"},"haunts":{"lemma":"haunt"},"herders":{"oxford":{"phon":"","pos":"noun","senses":[{"en":"a person whose job is to take care of a group of animals such as sheep and cows in the countryside","cn":"放牧人；牧工"}]}},"happier":{"lemma":"happy"},"hawkers":{"oxford":{"phon":"ˈhɔːkə(r)","pos":"noun","senses":[{"en":"a person who makes money by hawking goods","cn":"沿街叫卖者；小贩"}]}},"hummed":{"lemma":"hum"},"horrors":{"lemma":"horror"},"hired":{"lemma":"hire"},"hackers":{"lemma":"hacker"},"homes":{"lemma":"home","media":{"img":["media/pic/homes_comp.jpg"]}},"handbrakes":{"oxford":{"phon":"ˈhændbreɪk","pos":"noun","senses":[{"en":"a brake in a vehicle that is operated by hand, used especially when the vehicle is not moving （","cn":"车辆的）手闸，手刹车"}]}},"holds":{"lemma":"hold"},"hospitals":{"lemma":"hospital"},"horses":{"lemma":"horse"},"hunks":{"oxford":{"phon":"hʌŋk","pos":"noun","senses":[{"en":"a large piece of sth, especially food, that has been cut or broken from a larger piece （","cn":"尤指食物切下或掰下的）大块，大片"},{"en":"( informal ) a man who is big, strong and sexually attractive","cn":"魁梧性感的男子；猛男"}]}},"hierarchies":{"lemma":"hierarchy"},"hills":{"lemma":"hill"},"hogging":{"oxford":{"phon":"hɒɡ","pos":"noun","senses":[{"en":"( especially NAmE ) a pig, especially one that is kept and made fat for eating （","cn":"尤指喂肥供食用的）猪"},{"en":"( BrE ) a male pig that has been castrated (= had part of its sex organs removed) and is kept for its meat （","cn":"供食用的）阉公猪"}]}},"heaved":{"lemma":"heave"},"helpers":{"lemma":"helper"},"hams":{"lemma":"ham"},"having":{"lemma":"have"},"hesitated":{"lemma":"hesitate"},"hangars":{"oxford":{"phon":"ˈhæŋə(r)","pos":"noun","senses":[{"en":"a large building in which aircraft are kept","cn":"飞机库"}]}},"homemakers":{"oxford":{"phon":"ˈhəʊmmeɪkə(r)","pos":"noun","senses":[{"en":"a person who works at home and takes care of the house and family","cn":"料理家务者；操持家务者"}]}},"halls":{"lemma":"hall"},"hated":{"lemma":"hate","media":{"uk":"media/ldoce/hwd/bre/d/hate_v0205.mp3","us":"media/ldoce/hwd/ame/c/hate1.mp3"}},"honorable":{"oxford":{"phon":"ˈɒnərəbl","pos":"adjective","senses":[{"en":"deserving great respect","cn":"可敬的；值得钦佩的"},{"en":"showing high moral standards","cn":"品格高尚的"},{"en":"allowing somebody to keep their good name and the respect of others","cn":"保护声誉的；体面的"},{"en":"a title of respect used for an official of high rank","cn":"（高级官员的尊称）","g":"[only before noun]"}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdehonorable.mp3","us":"media/ldoce/hwd/ame/1/laadhonorable.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"howl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（狼、狗等）长嚎，嗥叫","en":"If an animal such as a wolf or a dog howls, it makes a long, loud, crying sound.","ex":{"en":"Somewhere in the streets beyond a dog suddenly howled, baying at the moon.","cn":"远处的街上，有只狗突然对月长嚎起来。"}},{"pos":"VERB 动词","cn":"（人因疼痛、愤怒、愁苦而）吼叫，嚎哭，哀号","en":"If a person howls, they make a long, loud cry expressing pain, anger, or unhappiness.","ex":{"en":"He howled like a wounded animal as blood spurted from the gash","cn":"当血从伤口中喷出时，他像一只受伤的动物一样嚎叫起来。"}},{"pos":"VERB 动词","cn":"（风）呼啸，怒号","en":"When the wind howls, it blows hard and makes a loud noise.","ex":{"en":"The wind howled all night, but I slept a little","cn":"风整夜怒号着，但我还是睡了一会儿。"}},{"pos":"VERB 动词","cn":"（人）高声嚷，大声呼叫","en":"If you howl something, you say it in a very loud voice.","ex":{"en":"'Get away, get away, get away' he howled","cn":"“滚开，滚开，都滚开”他高声嚷道。"}},{"pos":"VERB 动词","cn":"放声（大笑）","en":"If you howl with laughter, you laugh very loudly.","ex":{"en":"Joe, Pink, and Booker howled with delight","cn":"乔、平克和布克高兴得放声大笑。"}},{"pos":"","cn":"","en":"相关词组：howl down"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to laugh very loudly because you think something is very funny","cn":""},{"en":"to suddenly laugh loudly because you think a situation, someone's words, something you are reading etc is very funny","cn":""},{"en":"to laugh loudly and unpleasantly in a high voice, like someone who is mad","cn":""}]},"collocations":{"phrases":["ADJ. deep | mournful The dog gave a mournful howl.","VERB + HOWL give, let out | hear","PREP. with a ~ With a howl he leapt at his foe. | ~ of a howl of laughter/protest","PHRASES be greeted/met with howls of sth His comments were met with howls of outrage. | the howl of the wind/a wolf, howls of laughter, howl"]},"media":{"uk":"media/ldoce/hwd/bre/a/howl_n0205.mp3","us":"media/ldoce/hwd/ame/0/howl1.mp3"},"examples":[{"en":"The baby was howling (= crying loudly) all the time I was there.","cn":"我在那里时孩子一直哭得很厉害。"},{"en":"They listened to the howl of the wind through the trees.","cn":"他们听着风在林间呼啸的声音。"}],"oxford":{"phon":"haʊl","pos":"verb","senses":[{"en":"to make a long, loud call","cn":"长嚎；嗥叫","g":"[intransitive]","ex":{"en":"the sound of wolves howling in the night","cn":"夜里狼嚎的声音"}},{"en":"to make a loud noise when you are angry, in pain, etc. or you find something funny","cn":"（因愤怒、疼痛、开心等）大声叫喊，吼","g":"[intransitive]","ex":{"en":"The child howled in pain.","cn":"那孩子疼得直叫。"}},{"en":"to blow hard and make a long loud noise","cn":"怒号；呼啸","g":"[intransitive]","ex":{"en":"The wind was howling around the house.","cn":"狂风在房子四周呼啸。"}},{"en":"to say something loudly and angrily","cn":"怒吼","g":"[transitive]","ex":{"en":"The crowd howled its displeasure.","cn":"群众不满地怒吼着。"}},{"en":"a long loud call made by a dog, wolf, etc.","cn":"（狗、狼等的）嗥叫，长嚎","ex":{"en":"the mournful howl of a lone dog","cn":"一只孤独的狗的哀嚎"},"pos":"noun"},{"en":"a loud noise showing that you are angry, in pain, etc. or you find something funny","cn":"（因愤怒、疼痛、开心等发出的）喊叫声，吼叫","ex":{"en":"to let out a howl of anguish","cn":"发出痛苦的喊叫声"},"pos":"noun"},{"en":"a long loud sound made when the wind is blowing strongly","cn":"（狂风的）啸鸣，怒号","ex":{"en":"They listened to the howl of the wind through the trees.","cn":"他们听着风在林间呼啸的声音。"},"pos":"noun"}]}},"huff":{"collins":{"senses":[{"pos":"VERB 动词","cn":"生气;气恼;恼怒地说","en":"If you huff, you indicate that you are annoyed or offended about something, usually by the way that you say something.","ex":{"en":"'This', huffed Mr Buthelezi, 'was discrimination.'","cn":"“这个，”布特莱齐先生气愤地说，“是歧视。”"}},{"pos":"PHRASE 短语","cn":"生气;气恼;怒气冲冲","en":"If someone is in a huff, they are behaving in a bad-tempered way because they are annoyed and offended.","ex":{"en":"After the row in a pub he drove off in a huff.","cn":"在酒吧里吵了一架后，他气鼓鼓地开车走了。"}},{"pos":"PHRASE 短语","cn":"愤愤不满;生闷气","en":"If someone huffs and puffs, they express their annoyance or dissatisfaction with a decision or situation loudly but do not do anything to change it.","ex":{"en":"The British government huffed and puffed at the commission's decision.","cn":"英国政府对委员会的决定愤愤不满。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to breathe out in a noisy way, especially when you do something that involves a lot of physical effort","cn":"气喘吁吁"},{"en":"to show clearly that you strongly disagree with or are annoyed about something","cn":"强烈反对﹔发脾气"},{"en":"to say something in a way that shows you are annoyed, often because someone has offended you 〔","cn":"常指因受到冒犯而〕生气地说"}]},"collocations":{"phrases":["VERB + HUFF get in, go into | go off in, march off in, storm off in, walk off in She went off in a huff after losing the game.","PREP. in a ~ He's in a huff because he wasn't invited. | ~ at She got in a huff at being doubted. | ~ over Alison's in a huff over the joke "]},"media":{"uk":"media/ldoce/hwd/bre/d/huff_n0205.mp3","us":"media/ldoce/hwd/ame/5/huff1.mp3"},"examples":[{"en":"After much huffing and puffing, she finally agreed to help.","cn":"她生了好一阵闷气之后才终于同意帮忙。"},{"en":"‘Well, nobody asked you,’ she huffed irritably. “","cn":"哼，谁问你了。”她怒气冲冲地说。"}],"oxford":{"phon":"hʌf","pos":"verb","senses":[{"en":"to say something or make a noise in a way that shows you are offended or annoyed","cn":"生气地说；怒气冲冲","ex":{"en":"‘Well, nobody asked you,’ she huffed irritably.","cn":"“哼，谁问你了。”她怒气冲冲地说。"}}]}},"halt":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）停止行进;（使）停住","en":"When a person or a vehicle halts or when something halts them, they stop moving in the direction they were going and stand still.","ex":{"en":"They halted at a short distance from the house","cn":"他们在离房子不远处停了下来。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（生长、发展、活动等）停止（或中止）","en":"When something such as growth, development, or activity halts or when you halt it, it stops completely.","ex":{"en":"Striking workers halted production at the auto plant yesterday","cn":"罢工工人于昨日停止了汽车厂的生产。"}},{"pos":"VERB 动词","cn":"（军队口令）立定！站住！停止前进！","en":"'Halt!' is a military order to stop walking or marching and stand still.","ex":{"en":"The colonel ordered 'Halt!'","cn":"上校命令道：“立定！”"}},{"pos":"N-COUNT 可数名词","cn":"（只有小型站台、无建筑物的)小火车站","en":"A halt is a very small station on a country railway line, which often consists only of a short platform and no building."},{"pos":"PHRASE 短语","cn":"下令停止;叫停","en":"If someone calls a halt to something such as an activity, they decide not to continue with it or to end it immediately.","ex":{"en":"The Russian government had called a halt to the construction of a new project in the Rostov region.","cn":"俄罗斯政府已叫停了罗斯托夫地区的一个新工程。"}},{"pos":"PHRASE 短语","cn":"停止移动;停下","en":"If someone or something comes to a halt, they stop moving.","ex":{"en":"Sofia and Alex came to a halt and both tried to regain their breath","cn":"索菲娅和亚历克斯停了下来，两人都想喘口气。"}},{"pos":"PHRASE 短语","cn":"（使）（生长、发展、活动等）完全停止","en":"If something such as growth, development, or activity comes or grinds to a halt or is brought to a halt, it stops completely.","ex":{"en":"Her political career came to a halt in December 1988","cn":"她的政治生涯于1988年12月画上了句号。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to stop an activity, especially one that you consider to be harmful or unacceptable","cn":""},{"en":"to completely stop an illegal or harmful activity","cn":""},{"en":"to take severe action to stop an illegal activity","cn":""}]},"vocab":{"pos":"1 v n 2 adj","senses":[{"en":"Whether it's used as a noun or a verb, the word halt means stop . You can remember this by remembering that when you step on the brake to halt your car (verb), it comes to a halt (noun)."}]},"collocations":{"phrases":["ADJ. abrupt, sudden The bus came to an abrupt halt outside the school. | grinding, shuddering The strike brought the capital city to a grind","VERB + HALT come to, draw to, grind to, jolt to, lurch to, scream to, screech to, shudder to, skid to, slide to, slither to The economy seem","PREP. ~ in a halt in nuclear testing | ~ to The protesters are calling for a halt to the export of live animals."]},"media":{"uk":"media/ldoce/hwd/bre/2/halt_n0205.mp3","us":"media/ldoce/hwd/ame/b/halt1.mp3"},"examples":[{"en":"The police were halting traffic on the parade route.","cn":"警察正阻止游行路线上的车辆前行。"},{"en":"Work came to a halt when the machine broke down.","cn":"机器一坏，工作便停了下来。"}],"oxford":{"phon":"hɔːlt","pos":"verb","senses":[{"en":"to stop; to make somebody/something stop","cn":"（使）停止，停下","ex":{"en":"She walked towards him and then halted.","cn":"她向他走去，然后停下。"}},{"en":"an act of stopping the movement or progress of somebody/something","cn":"停止；阻止；暂停","g":"[singular]","ex":{"en":"Work came to a halt when the machine broke down.","cn":"机器一坏，工作便停了下来。"},"pos":"noun"},{"en":"a small train station in the country that has a platform but no buildings","cn":"小火车站（只有站台）","g":"[countable]","lab":"British English","pos":"noun"}]}},"homeless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无家可归的","en":"Homeless people have nowhere to live.","ex":{"en":"...the growing number of homeless families","cn":"越来越多的居无定所家庭"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having no home to live in, especially because you are very poor or have been forced to leave your old home","cn":""},{"en":"to sleep outdoors in a city because you do not have anywhere to live","cn":""},{"en":"someone who has no home or regular work","cn":""}]},"collocations":{"phrases":["VERBS be | become, end up, find yourself He found himself homeless after his marriage broke up. | leave sb, make sb, render sb Three hundred","ADV. officially | intentionally, voluntarily The local authority ruled that he had made himself intentionally homeless and was therefore not"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdehomeless.mp3","us":"media/ldoce/hwd/ame/b/homeless.mp3"},"examples":[{"en":"The scheme has been set up to help homeless people.","cn":"这个计划的目的是帮助无家可归的人。"},{"en":"helping the homeless","cn":"帮助无家可归者"}],"oxford":{"phon":"ˈhəʊmləs","pos":"adjective","senses":[{"en":"having no home, and therefore typically living on the streets","cn":"无家可归的；露宿街头的","ex":{"en":"The scheme has been set up to help homeless people.","cn":"这个计划的目的是帮助无家可归的人。"}},{"en":"people who have no home","cn":"无家可归的人们","g":"[plural]","ex":{"en":"helping the homeless","cn":"帮助无家可归者"}}]}},"hindsight":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"后见之明;事后聪明","en":"Hindsight is the ability to understand and realize something about an event after it has happened, although you did not understand or realize it at the time.","ex":{"en":"With hindsight, we'd all do things differently","cn":"有了事后的认识，我们都会以不同的方式行事。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to understand a situation only after it has happened","cn":"事后聪明﹐事后领悟"},{"en":"→ foresight with/in hindsight With hindsight, I should have seen the warning signs.","cn":"事后想来﹐我是应该看见那些警示牌的。 the benefit/wisdom of hindsight With the benefit of hindsight, it’s easy to criticize. 事后指责自然容易。"}]},"vocab":{"pos":"n","senses":[{"en":"People who are able to look back on the past and understand what happened have hindsight . If you go skating on a frozen lake and it cracks, in hindsight you'd know you should've paid attention to the giant \"danger\" sign."}]},"collocations":{"phrases":["PREP. in ~ Their first scheme was deemed, in hindsight, a mistake. | with ~ This all seems obvious with hindsight.","PHRASES (with) the advantage/benefit/wisdom of hindsight It is easy to criticize others when you have the benefit of hindsight."]},"media":{"uk":"media/ldoce/hwd/bre/f/hindsight0205.mp3","us":"media/ldoce/hwd/ame/a/hindsight.mp3"},"examples":[{"en":"With hindsight it is easy to say they should not have released him.","cn":"事后才说他们本不应该释放他，这倒容易。"},{"en":"What looks obvious in hindsight was not at all obvious at the time.","cn":"事后一目了然的事在当时根本看不清。"}],"oxford":{"phon":"ˈhaɪndsaɪt","pos":"noun","senses":[{"en":"the understanding that you have of a situation only after it has happened and that means you would have done things in a different way","cn":"事后聪明；事后的领悟","ex":{"en":"With hindsight it is easy to say they should not have released him.","cn":"事后才说他们本不应该释放他，这倒容易。"}}]}},"hoarse":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（嗓音）嘶哑的，粗哑的","en":"If your voice is hoarse or if you are hoarse, your voice sounds rough and unclear, for example because your throat is sore.","ex":{"en":"'So what do you think?' she said in a hoarse whisper","cn":"“那么你认为如何？”她声音嘶哑地悄声问道。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not sounding soft or gentle, especially because the person speaking is angry or rude","cn":""},{"en":"deep and rough, as if the sounds are produced deep down in your throat","cn":""},{"en":"slightly rough, as though you have a sore throat, but also attractive and deep","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A hoarse voice is deep and rough and kind of hard to make out. People get hoarse when they're sick, or when they are calling in sick to work."}]},"collocations":{"phrases":["VERBS be, sound | become, get, go | leave sb, make sb/sth, scream yourself, shout yourself All the shouting had left her rather hoarse. Exci","ADV. extremely, very | rather, slightly","PREP. from Her voice was hoarse from shouting. | with His voice was hoarse with anxiety."]},"media":{"uk":"media/ldoce/hwd/bre/1/hoarse0205.mp3","us":"media/ldoce/hwd/ame/6/hoarse.mp3"},"examples":[{"en":"He shouted himself hoarse.","cn":"他把嗓子喊哑了。"},{"en":"a hoarse cough/cry/scream","cn":"粗哑的咳嗽；嘶哑的哭声/尖叫声"}],"oxford":{"phon":"hɔːs","pos":"adjective","senses":[{"en":"if a person or their voice is hoarse, their voice sounds rough and unpleasant, especially because of a sore throat (= a painful throat because of an infection)","cn":"嘶哑的；沙哑的","ex":{"en":"He shouted himself hoarse.","cn":"他把嗓子喊哑了。"}}]}},"hysteria":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（一群人的）情绪失控，狂野情绪的爆发","en":"Hysteria among a group of people is a state of uncontrolled excitement, anger, or panic.","ex":{"en":"No one could help getting carried away by the hysteria","cn":"所有人都不由自主地受到狂热情绪的感染。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"癔病;歇斯底里","en":"A person who is suffering from hysteria is in a state of violent and disturbed emotion as a result of shock.","ex":{"en":"By now, she was screaming, completely overcome with hysteria.","cn":"现在她正在尖叫，完全处于癔病发作状态。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden very strong feeling of excitement, mixed with pleasure and sometimes fear","cn":""},{"en":"a feeling of happy excitement, for example that you get from an exciting physical activity or from something you have achieved","cn":""},{"en":"excited and cheerful feelings or behaviour, especially of a group of young people","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Hysteria is a medical condition or general state of extreme fear and panic. When hysteria sets in, people are out of control."}]},"collocations":{"phrases":["ADJ. mass, public | mild, near | rising | media, tabloid Unnecessary anxiety has been caused by media hysteria and misinformation. | religio","QUANT. fit She smashed the place up in a fit of hysteria. | note, touch the touch of hysteria in her voice","VERB + HYSTERIA border on Sam arrived in a state of excitement bordering on hysteria. | bring on, engender, generate That thought was enough","HYSTERIA + VERB mount, rise She felt hysteria rising. | die down, diminish Eventually the hysteria died down. | sweep (across/through) sth t","PREP. ~ about public hysteria about the bombings | ~ over hysteria over Aids","PHRASES on the brink/point/verge of hysteria She was babbling, on the verge of hysteria."]},"media":{"uk":"media/ldoce/hwd/bre/7/hysteria0205.mp3","us":"media/ldoce/hwd/ame/c/hysteria.mp3"},"examples":[{"en":"the usual media hysteria that surrounds royal visits","cn":"媒体对于王室成员访问的惯常的大肆渲染"},{"en":"A note of hysteria crept into her voice.","cn":"她的声音听来有点歇斯底里。"}],"oxford":{"phon":"hɪˈstɪəriə","pos":"noun","senses":[{"en":"a state of extreme excitement, fear or anger in which a person, or a group of people, loses control of their emotions and starts to cry, laugh, etc.","cn":"歇斯底里；情绪失控","ex":{"en":"There was mass hysteria when the band came on stage.","cn":"乐队登台时观众一片疯狂。"}},{"en":"an extremely excited and exaggerated way of behaving or reacting to an event","cn":"大肆鼓吹；狂热夸张；大惊小怪","lab":"disapproving","ex":{"en":"the usual media hysteria that surrounds royal visits","cn":"媒体对于王室成员访问的惯常的大肆渲染"}},{"en":"a condition in which somebody experiences violent or extreme emotions that they cannot control, especially as a result of shock","cn":"癔症；歇斯底里","lab":"medical"}]}},"hurdle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"障碍;困难;难关","en":"A hurdle is a problem, difficulty, or part of a process that may prevent you from achieving something.","ex":{"en":"Two-thirds of candidates fail at this first hurdle and are packed off home","cn":"三分之二的候选人在第一个难关就败下阵来，只好打包回家了。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"跨栏赛跑;障碍赛跑","en":"Hurdles is a race in which people have to jump over a number of obstacles that are also called hurdles. You can use hurdles to refer to one or more races.","ex":{"en":"Davis won the 400m. hurdles in a new Olympic time of 49.3 sec.","cn":"戴维斯以49.3秒的成绩刷新奥运会纪录，在400米跨栏赛跑中一举夺冠。"}},{"pos":"VERB 动词","cn":"（在跑步过程中）跳跃，跨越","en":"If you hurdle, you jump over something while you are running.","ex":{"en":"He crossed the lawn and hurdled the short fence","cn":"他跑过草地，跳过低矮的栅栏。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens which stops you making progress or which makes things worse than they were before","cn":""},{"en":"a problem or difficulty that must be dealt with before you can do or achieve something else","cn":""},{"en":"a fact or situation that will make it very difficult for something to be achieved","cn":""}]},"collocations":{"phrases":["VERB + HURDLE clear, jump (over) She cleared the first few hurdles easily. | fall at, hit His horse fell at the final hurdle. 2 problem/diff","ADJ. big, difficult | main, major | final, first, last, next The first big hurdle in putting your car on the road is getting insurance.","VERB + HURDLE face This is perhaps the most difficult hurdle that we face. | clear, jump, overcome, pass We'll jump each hurdle as we come t"]},"media":{"uk":"media/ldoce/hwd/bre/5/hurdle_n0205.mp3","us":"media/ldoce/hwd/ame/2/hurdle1.mp3"},"examples":[{"en":"His horse fell at the final hurdle.","cn":"他骑的马在最后一个跨栏倒下了。"},{"en":"The next hurdle will be getting her parents' agreement.","cn":"下一个难关是征得她父母的同意。"}],"oxford":{"phon":"ˈhɜːdl","pos":"noun","senses":[{"en":"each of a series of vertical frames that a person or horse jumps over in a race","cn":"（供人或马在赛跑中跨越的）栏架，跨栏","ex":{"en":"His horse fell at the final hurdle.","cn":"他骑的马在最后一个栏架倒下了。"}},{"en":"a race in which runners or horses have to jump over hurdles","cn":"跨栏赛","g":"[plural]","ex":{"en":"the 300 m hurdles","cn":"300 米跨栏赛"}},{"en":"a problem or difficulty that must be solved or dealt with before you can achieve something","cn":"难关；障碍","ex":{"en":"The next hurdle will be getting her parents' agreement.","cn":"下一个难关是征得她父母的同意。"}},{"en":"to jump over something while you are running","cn":"（奔跑中）跳越（某物）","g":"[transitive, intransitive]","ex":{"en":"He hurdled two barriers to avoid reporters.","cn":"他跳过了两个障碍物以躲避记者。"},"pos":"verb"},{"en":"to run in a hurdles race","cn":"参加跨栏赛","g":"[intransitive]","pos":"verb"}]}},"hysterical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"歇斯底里的;情绪狂暴失控的","en":"Someone who is hysterical is in a state of uncontrolled excitement, anger, or panic.","ex":{"en":"Police and bodyguards had to protect him as the almost hysterical crowds struggled to approach him","cn":"当情绪几近失控的人群拼命想接近他时，警察和保镖不得不保护他。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"癔病的;（通常指因惊吓而）情绪异常激动的","en":"Someone who is hysterical is in a state of violent and disturbed emotion that is usually a result of shock.","ex":{"en":"I suffered bouts of really hysterical depression.","cn":"我曾患阵发的严重癔病性抑郁症。"}},{"pos":"ADJ 形容词","cn":"（笑声）疯狂失控的，不可抑制的","en":"Hysterical laughter is loud and uncontrolled.","ex":{"en":"I had to rush to the loo to avoid an attack of hysterical giggles.","cn":"我不得不冲向卫生间，以免遭到别人的疯狂嘲笑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极可笑的;非常滑稽的","en":"If you describe something or someone as hysterical, you think that they are very funny and they make you laugh a lot.","ex":{"en":"Paul Mazursky was Master of Ceremonies, and he was pretty hysterical.","cn":"保罗·马祖尔斯基担任司仪，他简直把人笑坏了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone, especially a child, who is overexcited has become too excited to behave calmly","cn":""},{"en":"unable to stop shouting, crying etc because you are extremely excited","cn":""},{"en":"in a state of great and uncontrollable excitement","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Hysterical means \"marked by uncontrollable, extreme emotion.\" If your favorite sports team wins a championship, you might get hysterical and started weeping and screaming all at once."}]},"collocations":{"phrases":["VERBS be, feel, sound Emily realized that she sounded hysterical. | become, get Calm down, you're getting hysterical.","ADV. completely | almost, nearly By this time Mary was almost hysterical. | faintly, mildly, rather, slightly 2 very funny","VERBS be","ADV. absolutely, totally The whole episode was absolutely hysterical!"]},"media":{"uk":"media/ldoce/hwd/bre/0/hysterical0205.mp3","us":"media/ldoce/hwd/ame/a/hysterical.mp3"},"examples":[{"en":"( disapproving ) He thought I was being a hysterical female.","cn":"他觉得我当时像个歇斯底里的女人。"},{"en":"He became almost hysterical when I told him.","cn":"我告诉他时，他几乎要发疯了。"}],"oxford":{"phon":"hɪˈsterɪkl","pos":"adjective","senses":[{"en":"in a state of extreme excitement, and crying, laughing, etc. without any control","cn":"歇斯底里的；情绪狂暴不可抑止的","lab":"disapproving","ex":{"en":"hysterical screams","cn":"歇斯底里的尖叫"}},{"en":"extremely funny","cn":"滑稽的；极可笑的；令人捧腹的","lab":"informal","ex":{"en":"She seemed to find my situation absolutely hysterical.","cn":"她好像觉得我的处境极端可笑。"}}]}},"hearsay":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"传闻;谣言;道听途说","en":"Hearsay is information which you have been told but do not know to be true.","ex":{"en":"Much of what was reported to them was hearsay","cn":"向他们汇报的消息中很多都是道听途说。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"information which is passed from one person to another and which may or may not be true, especially information about people's private lives or about something that a government, company etc has done or is planning to do","cn":""},{"en":"if there is speculation about something, especially about something that is happening in politics or public life, a lot of people are talking about it and trying to guess what the truth is - used especially in news reports","cn":""},{"en":"information which people tell each other about other people's private lives, and which may or may not be true, especially when this is done in an unkind or disapproving way","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Ever hear someone say something so juicy you decide to tell other people about it, even if you don't know if it's true or not? Admit it. That hearsay , or gossip, is precisely how rumors get started."}]},"collocations":{"phrases":["VERB + HEARSAY be based on, rely on Her judgements are based on hearsay rather than evidence.","HEARSAY + NOUN evidence","PREP. by ~ She discovered a world of parties and pleasure she had hitherto only known by hearsay. | from ~ They started to piece the story t"]},"media":{"uk":"media/ldoce/hwd/bre/8/hearsay0205.mp3","us":"media/ldoce/hwd/ame/a/hearsay.mp3"},"examples":[{"en":"We can't make a decision based on hearsay and guesswork.","cn":"我们不能根据传言和猜测作决定。"},{"en":"hearsay evidence","cn":"传闻的证据"}],"oxford":{"phon":"ˈhɪəseɪ","pos":"noun","senses":[{"en":"things that you have heard from another person but do not (definitely) know to be true","cn":"道听途说；传闻","ex":{"en":"We can't make a decision based on hearsay and guesswork.","cn":"我们不能根据传言和猜测作决定。"}}]}},"hedge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"树篱","en":"A hedge is a row of bushes or small trees, usually along the edge of a garden, field, or road."},{"pos":"VERB 动词","cn":"防备，防范（尤指金钱损失）","en":"If you hedge against something unpleasant or unwanted that might affect you, especially losing money, you do something which will protect you from it.","ex":{"en":"You can hedge against redundancy or illness with insurance","cn":"可以购买保险以防失业或患病。"}},{"pos":"N-COUNT 可数名词","cn":"防护物;防备手段;防范措施","en":"Something that is a hedge against something unpleasant will protect you from its effects.","ex":{"en":"Gold is traditionally a hedge against inflation.","cn":"购买黄金是防范通货膨胀的一种传统手段。"}},{"pos":"VERB 动词","cn":"躲闪;回避","en":"If you hedge, you avoid answering a question or committing yourself to a particular action or decision.","ex":{"en":"They hedged in answering various questions about the operation","cn":"他们闪烁其词，不愿回答有关此次行动的各种问题。"}},{"pos":"PHRASE 短语","cn":"两面下注以防损失;骑墙","en":"If you hedge your bets, you reduce the risk of losing a lot by supporting more than one person or thing in a situation where they are opposed to each other.","ex":{"en":"Hawker Siddeley tried to hedge its bets by diversifying into other fields","cn":"霍克·西德利试图通过在其他领域进行多样化发展来规避风险。"}},{"pos":"","cn":"","en":"相关词组：hedge about"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of short grass in a garden","cn":""},{"en":"an area of ground where you grow flowers","cn":""},{"en":"an area of a garden where there are rocks with small flowers growing between them","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n v","senses":[{"en":"A hedge is a living fence made of closely planted bushes, which, as they grow and get trimmed and shaped, form a wall of green."}]},"collocations":{"phrases":["ADJ. high, low, tall, thick | boundary, garden, roadside Establish which boundary hedges are yours, and which belong to a neighbour. | beech","VERB + HEDGE plant | clip, trim Trim the hedge and collect the trimmings.","HEDGE + NOUN clippings, trimmings | trimmer"]},"media":{"uk":"media/ldoce/hwd/bre/a/hedge_v0205.mp3","us":"media/ldoce/hwd/ame/2/hedge1.mp3"},"examples":[{"en":"Just answer ‘yes’ or ‘no’ — and stop hedging.","cn":"只要回答“是”或“不是”，别再闪烁其词了。"},{"en":"Their offer was hedged around with all sorts of conditions.","cn":"他们的建议附带了各种各样的限制条件。"}],"oxford":{"phon":"hedʒ","pos":"noun","senses":[{"en":"a row of bushes or small trees planted close together, usually along the edge of a field, garden or road","cn":"树篱","ex":{"en":"a privet hedge","cn":"女贞树篱"}},{"en":"a way of protecting yourself against the loss of something, especially money","cn":"防止损失（尤指金钱）的手段","ex":{"en":"I bought gold as a hedge against inflation.","cn":"我购买黄金是为了对冲通货膨胀。"}},{"en":"to avoid giving a direct answer to a question or promising to support a particular idea, etc.","cn":"避免正面回答；不直接许诺；拐弯抹角","g":"[intransitive]","ex":{"en":"Just answer ‘yes’ or ‘no’—and stop hedging.","cn":"只要回答“是”或“不是”，别再闪烁其词了。"},"pos":"verb"},{"en":"to put a hedge around a field, etc.","cn":"在（田地等）周围植树篱；用树篱围住","g":"[transitive]","pos":"verb"},{"en":"to surround or limit somebody/something","cn":"包围；限制","g":"[transitive, usually passive]","lab":"formal","ex":{"en":"His religious belief was always hedged with doubt.","cn":"他的宗教信仰一直受到心不诚的局限。"},"pos":"verb"}]}},"heir":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继承人","en":"An heir is someone who has the right to inherit a person's money, property, or title when that person dies.","ex":{"en":"His heir, Lord Doune, cuts a bit of a dash in the city.","cn":"他的继承人杜恩勋爵在城里出了一番风头。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person who has the legal right to receive the property or title of another person when they die","cn":"继承人"},{"en":"the person who will take over a position or job after you, or who does things or thinks in a similar way to you","cn":"继任人﹐接班人"}]},"vocab":{"pos":"n","senses":[{"en":"If your grandfather leaves his candy factory to you in his will, it means you're the heir to the family candy business, and after your grandfather dies, you will inherit the factory."}]},"collocations":{"phrases":["ADJ. lawful, legal, legitimate, rightful the rightful heir to the throne | natural, real, true The socialists saw themselves as true heirs o","VERB + HEIR have He has no heir to leave his fortune to. | beget, get, produce He planned to marry and produce an heir for his estate. | bec","PREP. ~ to He is the sole heir to a large mining fortune.","PHRASES the heir to the throne, sb's son and heir He left most of his property to his eldest son and heir."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeheir.mp3","us":"media/ldoce/hwd/ame/f/air1.mp3"},"examples":[{"en":"to be heir to a large fortune","cn":"是大笔财产的继承人"},{"en":"the heir to the throne (= the person who will be the next king or queen)","cn":"王位继承人"}],"oxford":{"phon":"eə(r)","pos":"noun","senses":[{"en":"a person who has the legal right to receive somebody’s property, money or title when that person dies","cn":"继承人；后嗣","ex":{"en":"to be heir to a large fortune","cn":"是大笔财产的继承人"}},{"en":"a person who is thought to continue the work or a tradition started by somebody else","cn":"（工作或传统的）继承者，承袭者，传人","ex":{"en":"the president’s political heirs","cn":"总统的政治继承者"}}]}},"harp":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"竖琴","en":"A harp is a large musical instrument consisting of a row of strings stretched from the top to the bottom of a frame. You play the harp by plucking the strings with your fingers."},{"pos":"","cn":"","en":"相关词组：harp on"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large musical instrument with strings that are stretched across a vertical frame with three corners, and that you play with your fingers","cn":"竖琴"},{"en":"to keep talking or complaining about something, in a way that is annoying or boring","cn":""},{"en":"to keep mentioning something in a way that other people find annoying","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"A harp is a large, stringed musical instrument with a beautiful sound. If you want to play an instrument that's portable, you should choose a ukulele instead of a harp ."}]},"collocations":{"phrases":["ADV. always, constantly He is always harping on about the war. | still","PREP. about","PHRASES keep harping on Don't keep harping on about my age!"]},"media":{"img":["media/ldoce/img/harp.jpg","media/thumb/harp.jpg"],"uk":"media/ldoce/hwd/bre/3/harp_v0205.mp3","us":"media/ldoce/hwd/ame/c/harp1.mp3"},"examples":[{"en":"My grandfather harps on about the war all the time.","cn":"我的祖父总是喋喋不休地说那场战争的事。"}],"oxford":{"phon":"hɑːp","pos":"noun","senses":[{"en":"a large musical instrument with strings stretched from top to bottom on a frame, played with the fingers","cn":"竖琴","ex":{"en":"By means of pedals, a harp can be set in any desired key.","cn":"利用踏板可以给竖琴调出任何一种调子。"}}]}},"hostility":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"敌意;对抗;敌对行为","en":"Hostility is unfriendly or aggressive behaviour towards people or ideas.","ex":{"en":"The last decade has witnessed a serious rise in the levels of racism and hostility to Black and ethnic groups","cn":"过去十年里，对黑人及少数族裔的种族歧视和敌对行为变得日益猖獗。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"反对;抵制","en":"Your hostility to something you do not approve of is your opposition to it.","ex":{"en":"There is hostility among traditionalists to this method of teaching history.","cn":"传统主义者反对这种讲授历史的方法。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"strong disagreement with or protest against something","cn":""},{"en":"a reason you give for opposing an idea or plan","cn":""},{"en":"a strong feeling of opposition to something, or dislike for someone, which is shown in your behaviour, and has often existed for a long time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Hostility is the state of ill will and bad feeling. If a teacher embarrasses you in front of the whole class, you will probably regard him or her with hostility for the remainder of the school year."}]},"collocations":{"phrases":["ADJ. bitter, considerable, deep, extreme, great, implacable | downright, open, outright Mixed-race couples faced open hostility. | veiled Th","VERB + HOSTILITY feel the deep hostility felt by many teenagers against the police | express, show | arouse, attract, provoke The prime mini","PREP. ~ between You could almost feel the hostility between her and her mother. | ~ against/to/towards the bitter hostility towards the occu","VERB + HOSTILITY cease, end, suspend Both sides finally agreed to suspend hostilities. | resume Hostilities were resumed later that year.","HOSTILITY + VERB begin, break out | cease, end On the 11th of November 1918 hostilities ceased. | resume","PREP. ~ against the beginning of hostilities against Germany in 1914 | ~ between Hostilities broke out between the two provinces later that ","PHRASES the cessation of hostilities, an outbreak of hostilities"]},"media":{"uk":"media/ldoce/hwd/bre/7/hostility0205.mp3","us":"media/ldoce/hwd/ame/2/hostility.mp3"},"examples":[{"en":"feelings of hostility towards people from other backgrounds","cn":"对其他不同背景的人的敌视情绪"},{"en":"There was open hostility between the two schools.","cn":"这两所学校公开相互敌对。"}],"oxford":{"phon":"hɒˈstɪləti","pos":"noun","senses":[{"en":"aggressive or unfriendly feelings or behaviour","cn":"敌意；对抗","g":"[uncountable]","ex":{"en":"There was a barely veiled hostility in her tone.","cn":"她语气中带着几乎未加掩饰的敌意。"}},{"en":"strong and angry opposition towards an idea, a plan or a situation","cn":"（对思想、计划或情形的）愤怒反对，愤怒反抗","g":"[uncountable]","ex":{"en":"The proposal was met with outright hostility.","cn":"提议遭到公然反对。"}},{"en":"acts of fighting in a war","cn":"战争行为","g":"[plural]","lab":"formal","ex":{"en":"the start/outbreak of hostilities between the two sides","cn":"双方之间敌对行为的爆发"}}]}},"harassment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"骚扰;烦扰","en":"Harassment is behaviour which is intended to trouble or annoy someone, for example repeated attacks on them or attempts to cause them problems.","ex":{"en":"Another survey found that 51 per cent of women had experienced some form of sexual harassment in their working lives.","cn":"另一个调查发现，51%的女性在工作中曾遭遇过某种形式的性骚扰。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone behaves in an unpleasant or threatening way towards you","cn":"骚扰"}]},"vocab":{"pos":"n","senses":[{"en":"If someone is abusing, insulting, or otherwise harming you on a regular basis, it's called harassment . Cruel and usually really annoying, harassment is also illegal in some cases."}]},"collocations":{"phrases":["ADJ. racial, sexual | police | constant, continual","VERB + HARASSMENT be subject to, be subjected to, suffer She had been subjected to continual sexual harassment.","PREP. ~ by They are complaining about harassment by the police","PHRASES a victim of harassment • Note at CRIME (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeharassment.mp3","us":"media/ldoce/hwd/ame/2/laadharassment.mp3"},"examples":[{"en":"racial/sexual harassment","cn":"种族侵扰；性骚扰"},{"en":"African-Americans have been complaining about police harassment for years.","cn":"非洲裔美国人多年来一直抱怨受到警察的骚扰。"}],"oxford":{"phon":"ˈhærəsmənt","pos":"noun","senses":[{"en":"the act of annoying or worrying somebody by putting pressure on them or saying or doing unpleasant things to them","cn":"侵扰；骚扰","ex":{"en":"sexual/racial harassment","cn":"性/种族骚扰"}},{"en":"the act of making repeated attacks on an enemy","cn":"（对敌人的）不断攻击","ex":{"en":"guerrilla harassment of the enemy","cn":"敌人的游击袭扰"}}]}},"homicide":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"凶杀;杀人","en":"Homicide is the illegal killing of a person.","ex":{"en":"The police arrived at the scene of the homicide.","cn":"警方赶到了凶杀现场。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of physically attacking someone","cn":""},{"en":"the crime of attacking and robbing someone in a public place","cn":""},{"en":"the crime of deliberately killing someone","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The noun homicide means a murder. If you kill another person, you are committing a homicide . The level of the homicide is legally defined as murder if the act was intentional, and \"manslaughter\" if it was unintentional."}]},"collocations":{"phrases":["ADJ. criminal, culpable, unlawful | justifiable The jury returned a verdict of justifiable homicide. • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/9/homicide0205.mp3","us":"media/ldoce/hwd/ame/f/homicide.mp3"},"oxford":{"phon":"ˈhɒmɪsaɪd","pos":"noun","senses":[{"en":"the act of killing another person, especially when it is a crime","cn":"（蓄意）杀人罪","ex":{"en":"He has been arrested on homicide and assault charges.","cn":"他因杀人和侵犯他人身体的指控被逮捕。"}}]}},"hiccup":{"collins":{"senses":[{"pos":"","cn":"","en":"also hiccough."},{"pos":"N-COUNT 可数名词","cn":"小问题;（尤指）暂时的耽搁","en":"You can refer to a small problem or difficulty as a hiccup, especially if it does not last very long or is easily put right.","ex":{"en":"A recent sales hiccup is nothing to panic about","cn":"用不着为最近销售上出现的一点小问题感到惊慌。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"呃逆;打嗝","en":"When you have hiccups, you make repeated sharp sounds in your throat, often because you have been eating or drinking too quickly.","ex":{"en":"A young baby may frequently get a bout of hiccups during or soon after a feed.","cn":"小婴儿进食过程中或刚刚进食后经常会打嗝。"}},{"pos":"N-COUNT 可数名词","cn":"打嗝声","en":"A hiccup is a sound of the kind that you make when you have hiccups."},{"pos":"VERB 动词","cn":"呃逆;打嗝","en":"When you hiccup, you make repeated sharp sounds in your throat.","ex":{"en":"She was still hiccuping from the egg she had swallowed whole.","cn":"刚才一口吞下整个鸡蛋，她现在还在打嗝。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bad situation that must be dealt with, because it is causing harm or inconvenience, or it is stopping you from doing what you want to do","cn":""},{"en":"a problem that makes it more difficult to do something that you are trying to do","cn":""},{"en":"a problem or several problems that make something difficult, spoil your plans etc","cn":""}]},"collocations":{"phrases":["ADJ. small | loud","VERB + HICCUP give, let out She gave a loud hiccup. 2 (the) hiccups: series of hiccups","QUANT. attack He suddenly had an attack of the hiccups.","VERB + HICCUP get, suffer from I ate too quickly and got hiccups. 3 small problem","ADJ. little, slight | occasional | temporary","PREP. ~ in This one defeat was the only hiccup in the team's steady progress up the League."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdehiccup.mp3","us":"media/ldoce/hwd/ame/e/hiccup1.mp3"},"examples":[{"en":"I ate too quickly and got hiccups.","cn":"我吃得太快，结果不断地打嗝。"},{"en":"There was a slight hiccup in the timetable.","cn":"时间安排上出了点小问题。"}],"oxford":{"phon":"ˈhɪkʌp","pos":"noun","senses":[{"en":"a sharp, usually repeated, sound made in the throat, that is caused by a sudden movement of the diaphragm and that you cannot control","cn":"嗝；呃逆","g":"[countable]","ex":{"en":"She gave a loud hiccup.","cn":"她打了一个响嗝。"}},{"en":"a series of hiccups","cn":"一连串的打嗝","g":"[plural]","ex":{"en":"I ate too quickly and got hiccups.","cn":"我吃得太快，结果不断地打嗝。"}},{"en":"a small problem or temporary delay","cn":"小问题；暂时性耽搁","g":"[countable]","lab":"informal","ex":{"en":"There was a slight hiccup in the timetable.","cn":"时间安排上出了点小问题。"}},{"en":"to have (the) hiccups or a single hiccup","cn":"打嗝；打呃","pos":"verb"}]}},"hound":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"猎犬;赛犬","en":"A hound is a type of dog that is often used for hunting or racing.","ex":{"en":"Rainey's chief interest in life is hunting with hounds.","cn":"雷尼生活的最大爱好就是带着猎狗去打猎。"}},{"pos":"VERB 动词","cn":"（不断地）烦扰，叨唠，纠缠","en":"If someone hounds you, they constantly disturb or speak to you in an annoying or upsetting way.","ex":{"en":"Newcomers are constantly hounding them for advice","cn":"新人总是一刻不停地缠着向他们讨教。"}},{"pos":"VERB 动词","cn":"（常指通过不断批评而）逼迫（某人辞职或离开某地）","en":"If someone is hounded out of a job or place, they are forced to leave it, often because other people are constantly criticizing them.","ex":{"en":"There is a general view around that he has been hounded out of office by the press.","cn":"人们普遍认为他不堪舆论压力被迫离职。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a dog that is fast and has a good sense of smell, used for hunting","cn":"猎犬"},{"en":"a dog","cn":"狗"},{"en":"if someone such as a police officer tails someone, they secretly follow that person to find out where they are going or what they are doing","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A hound is a type of dog with big floppy ears, mainly used for hunting. To hound someone is to relentlessly pursue or pester them. When Elvis sings, “You ain’t nothing but a hound dog,” he’s referring to both."}]},"collocations":{"phrases":["ADJ. hunting","QUANT. pack","HOUND + VERB bark, bay We could hear the hounds barking at the fox. | pick up the scent The hounds picked up the scent of the fox. | chase s","PHRASES ride to hounds Days off were spent riding to hounds (= hunting) ."]},"media":{"uk":"media/ldoce/hwd/bre/b/hound_n0205.mp3","us":"media/ldoce/hwd/ame/1/hound1.mp3"},"examples":[{"en":"They were hounded day and night by the press.","cn":"他们日夜遭到新闻界的跟踪。"},{"en":"After the court case, Lee was hounded relentlessly by the press.","cn":"案件审结后﹐李不断受到新闻界的骚扰。"}],"oxford":{"phon":"haʊnd","pos":"noun","senses":[{"en":"a dog that can run fast and has a good sense of smell, used for hunting","cn":"猎犬；猎狗","ex":{"en":"The hounds picked up the scent of the fox.","cn":"猎狗嗅到了那只狐狸的气味。"}},{"en":"to keep following somebody and not leave them alone, especially in order to get something from them or ask them questions","cn":"追踪；追逐；纠缠","ex":{"en":"They were hounded day and night by the press.","cn":"他们日夜遭到新闻界的跟踪。"},"pos":"verb"}]}},"ham":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"火腿","en":"Ham is meat from the top of the back leg of a pig, specially treated so that it can be kept for a long period of time.","ex":{"en":"...a huge baked ham.","cn":"巨大的烤火腿"}},{"pos":"N-COUNT 可数名词","cn":"无线电爱好者；“火腿”","en":"A ham is a person whose hobby consists of using special radio equipment to talk to other people with the same hobby, often people who are in other countries.","ex":{"en":"I became a ham radio operator at the age of eleven.","cn":"我在11岁时成了一名业余无线电操作员。"}},{"pos":"N-COUNT 可数名词","cn":"蹩脚演员;表演过火的演员","en":"A ham actor is someone who acts badly, exaggerating every emotion and gesture."},{"pos":"PHRASE 短语","cn":"（常指演员故意地）表演过火，夸张做作","en":"If actors or actresses ham it up, they exaggerate every emotion and gesture when they are acting, often deliberately because they think that the audience will be more amused.","ex":{"en":"Thrusting themselves into the spirit of the farce, they ham it up like mad.","cn":"他们全力投入到这部闹剧中去，极尽搞怪之能事。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the upper part of a pig’s leg, or the meat from this that has been preserved with salt or smoke","cn":"火腿﹐火腿肉"},{"en":"someone who receives and sends radio messages for fun rather than as their job","cn":"业余无线电爱好者"},{"en":"an actor who performs with too much false emotion","cn":"演技做作的演员﹐表演过火的演员"}]},"collocations":{"phrases":["ADJ. lean | baked, boiled, cooked, cured, honey-roast, Parma, smoked | cold cold ham and salad | sliced","QUANT. bit, piece, slice | joint, leg","VERB + HAM eat, have | boil, cook, roast | carve, slice","HAM + NOUN roll, salad, sandwich","PHRASES ham on the bone We had boiled ham on the bone for dinner. •"]},"media":{"uk":"media/ldoce/hwd/bre/1/ham_n0205.mp3","us":"media/ldoce/hwd/ame/9/ham1.mp3"},"examples":[{"en":"The hams were cooked whole.","cn":"这些火腿是整条烹制的。"},{"en":"a radio ham","cn":"无线电通讯爱好者"}],"oxford":{"phon":"hæm","pos":"noun","senses":[{"en":"meat from the top part of a pig’s leg that has been cured (= preserved using salt or smoke)","cn":"火腿；火腿肉","g":"[uncountable, countable]","ex":{"en":"a slice of ham","cn":"一片火腿"}},{"en":"a person who sends and receives radio messages as a hobby rather than as a job","cn":"无线电通信爱好者","g":"[countable]","ex":{"en":"a radio ham","cn":"无线电通信爱好者"}},{"en":"an actor who performs badly, especially by exaggerating emotions","cn":"拙劣演员（尤指表演过火者）","g":"[countable]","lab":"informal","ex":{"en":"a ham actor","cn":"表演过火的演员"}},{"en":"the back part of a person’s leg above the knee","cn":"（人的）大腿后部","g":"[countable, usually plural]","lab":"informal"}]}},"haunt":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（不愉快的事）萦绕在心头，缠绕","en":"If something unpleasant haunts you, you keep thinking or worrying about it over a long period of time.","ex":{"en":"The decision to leave her children now haunts her","cn":"抛下孩子们的决定现在总让她不安。"}},{"pos":"VERB 动词","cn":"长期困扰","en":"Something that haunts a person or organization regularly causes them problems over a long period of time.","ex":{"en":"The stigma of being a bankrupt is likely to haunt him for the rest of his life.","cn":"破产的耻辱可能会让他余生不得安宁。"}},{"pos":"N-COUNT 可数名词","cn":"常去的地方","en":"A place that is the haunt of a particular person is one which they often visit because they enjoy going there.","ex":{"en":"The Channel Islands are a favourite summer haunt for UK and French yachtsmen alike.","cn":"海峡群岛是英国和法国的帆船运动爱好者夏日最爱去的地方。"}},{"pos":"VERB 动词","cn":"（鬼魂等）常出没于","en":"A ghost or spirit that haunts a place or a person regularly appears in the place, or is seen by the person and frightens them.","ex":{"en":"His ghost is said to haunt some of the rooms, banging a toy drum.","cn":"据说他的鬼魂经常敲着玩具鼓出没在其中的一些房间里。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a place that is haunted has ghosts in it","cn":""},{"en":"if a ghost haunts a place, it appears there often","cn":""},{"en":"a place that is spooky feels strange and makes you feel that there are ghosts there","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"The verb to haunt means to appear as a ghost or some kind of supernatural phenomenon. Ebenezer Scrooge was haunted by the Ghosts of Christmases Past, Present and Future."}]},"collocations":{"phrases":["ADV. reputedly, supposedly a Norman castle which is reputedly haunted","VERB + HAUNT come back to, return to He said he would come back to haunt her. (figurative) That decision came back to haunt him in later lif","ADV. still the great fear that still haunts her","VERB + HAUNT continue to These visions continued to haunt her for many years."]},"media":{"uk":"media/ldoce/hwd/bre/d/haunt_n0205.mp3","us":"media/ldoce/hwd/ame/a/haunt1.mp3"},"examples":[{"en":"A headless rider haunts the country lanes.","cn":"一个无头骑士常出没于乡间的小路上。"},{"en":"The memory of that day still haunts me.","cn":"我的脑海中常常回想起那天的情景。"}],"oxford":{"phon":"hɔːnt","pos":"verb","senses":[{"en":"if the ghost of a dead person haunts a place, people say that they have seen it there","cn":"（鬼魂）出没","ex":{"en":"A headless rider haunts the country lanes.","cn":"一个无头骑士常出没于乡间的小路上。"}},{"en":"if something unpleasant haunts you, it keeps coming to your mind so that you cannot forget it","cn":"（不快的事情）萦绕于脑际，使难以忘却","ex":{"en":"The memory of that day still haunts me.","cn":"我的脑海中还常常回想起那天的情景。"}},{"en":"to continue to cause problems for somebody for a long time","cn":"长期不断地缠扰（某人）","ex":{"en":"That decision came back to haunt him.","cn":"那个决定对他造成无法摆脱的困扰。"}},{"en":"a place that somebody visits often or where they spend a lot of time","cn":"常去的场所；消磨时光的去处","ex":{"en":"The pub is a favourite haunt of artists.","cn":"这家酒吧是艺术家最爱光顾的地方。"},"pos":"noun"}]}},"handy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有用的;方便的","en":"Something that is handy is useful.","ex":{"en":"The book gives handy hints on looking after indoor plants","cn":"这本书提供了一些关于如何照料室内花草的有用信息。"}},{"pos":"PHRASE 短语","cn":"派上用场","en":"If something comes in handy, it is useful in a particular situation.","ex":{"en":"That key will come in handy if you lock yourself out","cn":"要是你把自己锁在了屋外，那把钥匙就派上用场了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"手边的;附近的","en":"A thing or place that is handy is nearby and therefore easy to get or reach.","ex":{"en":"It would be good to have a pencil and paper handy","cn":"最好在手边准备好纸和笔。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"手巧的;有手艺的","en":"Someone who is handy with a particular tool is skilful at using it.","ex":{"en":"If you're handy with a needle you could brighten up your sweater with daisies.","cn":"如果你针线活做得好，可以在自己的毛衣上绣几朵雏菊做点缀。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is useful makes it easier for you to do something","cn":""},{"en":"useful – used especially about something that is convenient and easy to use","cn":""},{"en":"useful because it helps you to do something","cn":""}]},"collocations":{"phrases":["VERBS be | come in I advise you to buy one?it may come in handy one day.","ADV. very | quite","PREP. for The arrangement was handy for both of us. 2 nearby","VERBS be | keep sth Always keep a cloth handy to wipe up any mess.","ADV. very | quite","PREP. for The house was near Drury Lane, very handy for the theatre. 3 good at using sth","VERBS be","ADV. very | fairly, pretty, quite"]},"media":{"uk":"media/ldoce/hwd/bre/a/handy0205.mp3","us":"media/ldoce/hwd/ame/6/handy.mp3"},"examples":[{"en":"The extra money came in very handy.","cn":"这笔额外的钱正好派上了用场。"},{"en":"to be handy around the house","cn":"对家里敲打修理的杂事很在行"}],"oxford":{"phon":"ˈhændi","pos":"adjective","senses":[{"en":"easy to use or to do","cn":"易使用的；容易做的；便利的","ex":{"en":"a handy little tool","cn":"好用的小工具"}},{"en":"located near to somebody/something; located or stored in a convenient place","cn":"近便；便利","g":"[not before noun]","lab":"British English","ex":{"en":"Always keep a first-aid kit handy.","cn":"手边要常备急救箱。"}},{"en":"able to use your hands or tools to make or repair things well","cn":"手巧；有手艺","g":"[not before noun]","ex":{"en":"to be handy around the house","cn":"对家里制作、修理等杂事很在行"}}]}},"hardback":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"硬皮书;精装本 (Compare 比较 paperback.）","en":"A hardback is a book which has a stiff hard cover.","ex":{"en":"His autobiography has sold more than 36,000 copies in hardback.","cn":"他的自传精装本已经卖出了36,000多册。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book about imaginary people and events","cn":""},{"en":"books that describe imaginary people and events","cn":""},{"en":"novels and plays that are considered to be important works of art","cn":""}]},"collocations":{"phrases":["VERB + HARDBACK publish | come out in His second book came out in hardback last month.","HARDBACK + NOUN book, edition","PREP. in ~ It's only available in hardback."]},"media":{"uk":"media/ldoce/hwd/bre/8/hardback0205.mp3","us":"media/ldoce/hwd/ame/9/hardback.mp3"},"examples":[{"en":"It was published in hardback last year.","cn":"这书去年以精装本出版。"},{"en":"What's the price of the hardback?","cn":"精装本多少钱？"}],"oxford":{"phon":"ˈhɑːdbæk","pos":"noun","senses":[{"en":"a book that has a stiff cover","cn":"精装书","ex":{"en":"What's the price of the hardback?","cn":"精装本多少钱？"}}]}},"hike":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"远足;（尤指）徒步旅行","en":"A hike is a long walk in the country, especially one that you go on for pleasure."},{"pos":"VERB 动词","cn":"远足;徒步旅行","en":"If you hike, you go for a long walk in the country.","ex":{"en":"You could hike through the Fish River Canyon","cn":"你可以徒步穿越鱼河峡谷。"}},{"pos":"N-COUNT 可数名词","cn":"（价格、比率、税率或数量的）突然上涨,大幅上升","en":"A hike is a sudden or large increase in prices, rates, taxes, or quantities.","ex":{"en":"...a sudden 1.75 per cent hike in Italian interest rates","cn":"意大利利率1.75%的突然上浮"}},{"pos":"VERB 动词","cn":"使（价格、比率、税率或数量）突然上升，大幅提高","en":"To hike prices, rates, taxes, or quantities means to increase them suddenly or by a large amount.","ex":{"en":"It has now been forced to hike its rates by 5.25 per cent","cn":"它目前已经被迫将利率提高了5.25%。"}},{"pos":"","cn":"","en":"相关词组：hike up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when the amount or number of something becomes bigger","cn":""},{"en":"an increase in the number, size, or importance of something. Growth is also used when saying that a company or a country’s economy becomes more successful","cn":""},{"en":"an increase in the amount of something, or in the standard or level of something","cn":""}]},"vocab":{"pos":"1 v n 2 v n","senses":[{"en":"To hike is to walk a long way at a leisurely pace. You might love to hike in the woods on weekends."}]},"collocations":{"phrases":["ADJ. long | strenuous | ten-mile, two-day, etc.","VERB + HIKE go on The boys have gone on a long hike with the Boy Scouts.","PREP. on a ~ They met on a hike. | ~ from, ~ to It's a hell of a hike from Sydney to Perth."]},"media":{"uk":"media/ldoce/hwd/bre/a/hike_v0205.mp3","us":"media/ldoce/hwd/ame/3/hike1.mp3"},"examples":[{"en":"They went on a ten-mile hike through the forest.","cn":"他们进行了一次穿越森林的十英里徒步旅行。"},{"en":"strong boots for hiking over rough country","cn":"适合在崎岖不平的山路徒步旅行用的结实靴子"}],"oxford":{"phon":"haɪk","pos":"noun","senses":[{"en":"a long walk in the country","cn":"远足；徒步旅行","ex":{"en":"They went on a ten-mile hike through the forest.","cn":"他们进行了一次穿越森林的十英里徒步旅行。"}},{"en":"a large or sudden increase in prices, costs, etc.","cn":"（价格、花费等的）大幅度提高，猛增","lab":"informal","ex":{"en":"a tax/price hike","cn":"税额／价格的大幅度增长"}},{"en":"to go for a long walk in the country, especially for pleasure","cn":"去…远足；做徒步旅行","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"You'll need some strong boots for hiking over rough country.","cn":"在崎岖不平的地区徒步旅行，你需要结实的靴子。"},"pos":"verb"},{"en":"to spend time hiking for pleasure","cn":"远足；徒步旅行","g":"[intransitive]","ex":{"en":"If the weather's fine, we'll go hiking this weekend.","cn":"如果天气好，我们这个周末就去远足。"},"pos":"verb"},{"en":"to increase prices, taxes, etc. suddenly by large amounts","cn":"把（价格、税率等）大幅提高","g":"[transitive]","ex":{"en":"The government hiked up the price of milk by over 40%.","cn":"政府把牛奶的价格提高了四成多。"},"pos":"verb"}]}},"hurricane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"飓风","en":"A hurricane is an extremely violent wind or storm."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of very bad weather when there is a lot of rain or snow, strong winds, and often lightning","cn":""},{"en":"a storm in which there is a lot of thunder (= loud noise in the sky ) and lightning (= flashes of light in the sky )","cn":""},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A hurricane is a severe tropical storm with high winds and heavy rain. When a hurricane comes through your town, you should board up the windows and stay inside."}]},"collocations":{"phrases":["HURRICANE + VERB hit sth, strike (sth) A hurricane hit the city yesterday at 5 p.m. | damage sth, destroy sth, devastate sth The fields were","HURRICANE + NOUN force hurricane-force winds","PREP. in a/the ~ The roof blew off in a hurricane.","PHRASES the eye of the hurricane (= the central point)"]},"media":{"uk":"media/ldoce/hwd/bre/f/hurricane0205.mp3","us":"media/ldoce/hwd/ame/2/hurricane1.mp3"},"examples":[{"en":"Hurricane Betty is now approaching the coast of Florida.","cn":"飓风贝蒂正在逼近佛罗里达州海岸。"},{"en":"hurricane-force winds","cn":"飓风级大风"}],"oxford":{"phon":"ˈhʌrɪkən","pos":"noun","senses":[{"en":"a violent storm with very strong winds, especially in the western Atlantic Ocean","cn":"（尤指西大西洋的）飓风","lab":"North American English","ex":{"en":"A powerful hurricane hit the Florida coast.","cn":"强飓风袭击了佛罗里达海岸。"}}]}},"hazard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"危险;危害","en":"A hazard is something which could be dangerous to you, your health or safety, or your plans or reputation.","ex":{"en":"A new report suggests that chewing-gum may be a health hazard","cn":"一份新报告指出，口香糖可能对健康有害。"}},{"pos":"VERB 动词","cn":"使冒风险;使处于危险中","en":"If you hazard someone or something, you put them into a situation which might be dangerous for them.","ex":{"en":"He could not believe that, had the Englishman known how much he was at risk, he would have hazarded his grandson.","cn":"他无法相信，如果当时那个英国人知道他冒的风险有多大，他还会让自己的孙子去冒这个险。"}},{"pos":"VERB 动词","cn":"斗胆提出;作无把握猜测","en":"If you hazard or if you hazard a guess, you make a suggestion about something which is only a guess and which you know might be wrong.","ex":{"en":"I would hazard a guess that they'll do fairly well in the next election","cn":"我斗胆猜测，他们在下一轮竞选中会有不错的表现。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the chance that something bad may happen","cn":""},{"en":"the possibility that something very bad will happen","cn":""},{"en":"something that may be dangerous or cause accidents or problems","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If something is a hazard , it is a potential source of danger. Balloons are fun, but they're a hazard for little kids who might put them in their mouths."}]},"collocations":{"phrases":["ADJ. big, great, major, real, serious | constant | possible, potential | hidden, unexpected, unseen | environmental, industrial, natural, oc","VERB + HAZARD cause, create, pose Production of these chemicals poses serious environmental hazards. | be exposed to, encounter, face, meet ","PREP. ~ for Holes in the pavement are a hazard for blind people. | ~ to The burning of industrial waste is a major hazard to human health.","PHRASES exposure to a hazard Try and reduce your exposure to hazards such as poor quality air."]},"media":{"uk":"media/ldoce/hwd/bre/1/hazard_v0205.mp3","us":"media/ldoce/hwd/ame/4/hazard1.mp3"},"examples":[{"en":"Growing levels of pollution represent a serious health hazard to the local population.","cn":"日益严重的污染对当地人民的健康构成了重大威胁。"},{"en":"Careless drivers hazard other people's lives as well as their own.","cn":"粗心大意的驾驶者拿他人和自己的生命冒险。"}],"oxford":{"phon":"ˈhæzəd","pos":"noun","senses":[{"en":"something that can be dangerous or cause damage","cn":"危险；危害","ex":{"en":"a fire/safety hazard","cn":"火灾／安全隐患"}},{"en":"to make a suggestion or guess that you know may be wrong","cn":"试着提出；大胆猜测","ex":{"en":"Would you like to hazard a guess?","cn":"你想猜猜看吗？"},"pos":"verb"},{"en":"to risk something or put it in danger","cn":"冒…的风险；使处于危险中","lab":"formal","ex":{"en":"Careless drivers hazard other people's lives as well as their own.","cn":"粗心大意的驾驶者拿他人和自己的生命冒险。"},"pos":"verb"}]}},"hernia":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（脏器的）突出;疝（气）","en":"A hernia is a medical condition which is often caused by strain or injury. It results in one of your internal organs sticking through a weak point in the surrounding tissue."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical condition in which an organ pushes through the muscles that are supposed to contain it","cn":"疝气"}]},"vocab":{"pos":"n","senses":[{"en":"A hernia is a rip in your muscle tissue that leads to an organ protruding through the muscle. It's painful and dangerous."}]},"collocations":{"phrases":["VERB + HERNIA have, suffer from | remove, repair","HERNIA + NOUN operation, repair •"]},"media":{"uk":"media/ldoce/hwd/bre/f/hernia0205.mp3","us":"media/ldoce/hwd/ame/1/hernia.mp3"},"oxford":{"phon":"ˈhɜːniə","pos":"noun","senses":[{"en":"a medical condition in which part of an organ is pushed through a weak part in the muscle or tissue around it","cn":"疝；突出"}]}},"helmet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"头盔;防护帽","en":"A helmet is a hat made of a strong material which you wear to protect your head."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong hard hat that soldiers, motorcycle riders, the police etc wear to protect their heads","cn":"头盔﹐钢盔﹐安全帽"}]},"collocations":{"phrases":["ADJ. visored | crash, cycle, flying, motorcycle, safety | fireman's, policeman's, etc.","VERB + HELMET have on, wear | put on | remove, take off"]},"media":{"img":["media/ldoce/img/motorcycle_helmet.jpg","media/thumb/helmet.jpg"],"uk":"media/ldoce/hwd/bre/f/helmet0205.mp3","us":"media/ldoce/hwd/ame/d/helmet.mp3"},"oxford":{"phon":"ˈhelmɪt","pos":"noun","senses":[{"en":"a type of hard hat that protects the head, worn, for example, by a police officer, a soldier or a person riding a bike or motorbike or playing some sports","cn":"头盔；防护帽","ex":{"en":"Police in riot helmets lined the streets.","cn":"戴着防暴头盔的警察站在沿街两边。"}}]}},"homesick":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"想家的;思乡的","en":"If you are homesick, you feel unhappy because you are away from home and are missing your family, friends, and home very much.","ex":{"en":"She's feeling a little homesick.","cn":"她有点想家。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not happy","cn":""},{"en":"sad, especially for a long time – used about people and periods of time","cn":""},{"en":"sad because you are away from your home, family, and friends","cn":""}]},"collocations":{"phrases":["VERBS be, feel | become, get | make sb Seeing other families together made him terribly homesick.","ADV. desperately, terribly, very | a bit, a little"]},"media":{"uk":"media/ldoce/hwd/bre/7/homesick0205.mp3","us":"media/ldoce/hwd/ame/2/homesick.mp3"},"examples":[{"en":"I felt homesick for Scotland.","cn":"我思念故乡苏格兰。"}],"oxford":{"phon":"ˈhəʊmsɪk","pos":"adjective","senses":[{"en":"sad because you are away from home and you miss your family and friends","cn":"思乡的；想家的；患怀乡病的","ex":{"en":"I felt homesick for Scotland.","cn":"我思念故乡苏格兰。"}}]}},"hazy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"雾气腾腾的;雾蒙蒙的","en":"Hazy weather conditions are those in which things are difficult to see, because of light mist, hot air, or dust.","ex":{"en":"The air was thin and crisp, filled with hazy sunshine and frost","cn":"空气稀薄清新，其间日光蒙眬，寒气逼人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对想法或细节）不太了解的;不确定的;不清楚的","en":"If you are hazy about ideas or details, or if they are hazy, you are uncertain or confused about them.","ex":{"en":"I'm a bit hazy about that","cn":"那件事我不太清楚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"模糊的;看不清楚的","en":"If things seem hazy, you cannot see things clearly, for example because you are feeling ill.","ex":{"en":"She sipped the wine. Everything was hazy now, except for Nick's face","cn":"她小口地抿着酒。现在一切都变得模糊起来，除了尼克的脸。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"with a lot of clouds","cn":""},{"en":"grey in colour, because there are dark clouds – used especially in written descriptions","cn":""},{"en":"dark and completely covered with clouds","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If it's hazy , it's definitely not clear — there's fog, mist, smoke or something like that blurring the view."}]},"collocations":{"phrases":["VERBS be, look The distant mountains looked hazy and mysterious. | become | remain","ADV. very | a little, quite, rather, slightly Generally, it will be rather hazy today, with some hill fog.","PREP. with The summers were hazy with pollution. 2 confused","VERBS be | become | remain","ADV. extremely, very I have only a very hazy idea about how the economy works. | a bit, fairly, a little, rather, somewhat My memory of that","PREP. about I'm a bit hazy about my family history."]},"media":{"uk":"media/ldoce/hwd/bre/d/hazy0205.mp3","us":"media/ldoce/hwd/ame/1/hazy.mp3"},"examples":[{"en":"I'm a little hazy about what to do next.","cn":"我还有点拿不准下一步要做什么。"},{"en":"‘Why now?’ she wondered hazily. “","cn":"为什么是现在？”她困惑地思忖。"}],"oxford":{"phon":"ˈheɪzi","pos":"adjective","senses":[{"en":"not clear because of haze","cn":"朦胧的；薄雾蒙蒙的","ex":{"en":"a hazy afternoon/sky","cn":"雾蒙蒙的下午／天空"}},{"en":"not clear because of a lack of memory, understanding or detail","cn":"记不清的；模糊的","ex":{"en":"a hazy memory/idea","cn":"模糊不清的记忆／概念"}},{"en":"uncertain or confused about something","cn":"主意不定的；困惑的","ex":{"en":"I'm a little hazy about what to do next.","cn":"我还有点拿不准下一步要做什么。"}}]}},"handbag":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（女用）手提包，手袋","en":"A handbag is a small bag which a woman uses to carry things such as her money and keys in when she goes out."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small bag in which a woman carries money and personal things 〔","cn":"女用〕手提包﹔手袋"},{"en":"used humorously to describe a situation in which two people are fighting, but in a way that is so weak or lacking in force that the fight is funny to watch 〔","cn":"软弱无力的〕打闹〔幽默用法〕"}]},"collocations":{"phrases":["ADJ. big, capacious, large","VERB + HANDBAG clutch, hold | carry | swing | delve into, fish about/around in, fumble in, reach into, rummage (around) in, search (in/throu","PREP. from a/the ~, out of a/the ~ She took a pen out of her large leather handbag. | in a/the ~, into a/the ~ She put her purse into her ha","PHRASES the contents of a handbag"]},"media":{"img":["media/ldoce/img/handbag.jpg","media/thumb/handbag.jpg"],"uk":"media/ldoce/hwd/bre/1/handbag0205.mp3","us":"media/ldoce/hwd/ame/1/handbag1.mp3"},"examples":[{"en":"Dennis looked like he threw a punch, but it was just handbags.","cn":"丹尼斯看似挥了一拳﹐其实只是装样子。"}],"oxford":{"phon":"ˈhændbæɡ","pos":"noun","senses":[{"en":"a small bag for money, keys, etc., especially one carried by a woman","cn":"手提包；（尤指）坤包","ex":{"en":"She was rummaging in her handbag for her keys.","cn":"她正在手提包里翻找钥匙。"}}]}},"hormone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"激素;荷尔蒙","en":"A hormone is a chemical, usually occurring naturally in your body, that makes an organ of your body do something."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical substance produced by your body that influences its growth, development, and condition","cn":"激素﹐荷尔蒙"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun hormone to describe a message-sending chemical sent out by glands in the human body, which make you hungry or moody or ready to fight."}]},"collocations":{"phrases":["ADJ. female, male | growth, sex children who do not produce enough growth hormone","VERB + HORMONE produce, release, secrete Hormones are secreted into the bloodstream.","HORMONE + NOUN production | replacement therapy, treatment | deficiency, imbalance | balance, level"]},"media":{"uk":"media/ldoce/hwd/bre/c/hormone0205.mp3","us":"media/ldoce/hwd/ame/f/hormone.mp3"},"examples":[{"en":"Oestrogen is a female sex hormone.","cn":"雌激素是一种雌性荷尔蒙。"},{"en":"the hormonal changes occurring during pregnancy","cn":"妊娠期间的激素变化"}],"oxford":{"phon":"ˈhɔːməʊn","pos":"noun","senses":[{"en":"a chemical substance produced in the body or in a plant that encourages growth or influences how the cells and tissues function; an artificial substance that has similar effects","cn":"激素；荷尔蒙","ex":{"en":"growth hormones","cn":"生长激素"}}]}},"hawk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鹰;隼","en":"A hawk is a large bird with a short, hooked beak, sharp claws, and very good eyesight. Hawks catch and eat small birds and animals."},{"pos":"N-COUNT 可数名词","cn":"（政治上的）鹰派人物，主战分子","en":"In politics, if you refer to someone as a hawk, you mean that they believe in using force and violence to achieve something, rather than using more peaceful or diplomatic methods.","ex":{"en":"Both hawks and doves have expanded their conditions for ending the war.","cn":"鹰派和鸽派都充分阐明了各自的停战条件。"}},{"pos":"VERB 动词","cn":"叫卖;兜售","en":"If someone hawks goods, they sell them by walking through the streets or knocking at people's houses, and asking people to buy them.","ex":{"en":"...vendors hawking trinkets.","cn":"沿街兜售小饰品的小贩"}},{"pos":"VERB 动词","cn":"（竭力）推销，兜售","en":"You can say that someone is hawking something if you do not like the forceful way in which they are asking people to buy it.","ex":{"en":"Developers will be hawking cut-price flats and houses.","cn":"开发商会竭力推销减价的公寓和房子。"}},{"pos":"VERB 动词","cn":"用力咳痰","en":"If someone hawks, they noisily clear mucus from their throat and spit it out.","ex":{"en":"He hawked and spat.","cn":"他用力咳了咳，吐了口痰。"}},{"pos":"PHRASE 短语","cn":"像鹰一样注视;警惕地监视","en":"If you watch someone like a hawk, you observe them very carefully, usually to make sure that they do not make a mistake or do something you do not want them to do."},{"pos":"","cn":"","en":"相关词组：hawk around"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, especially a politician or a military leader, who is too keen to start wars or to settle arguments by starting a war","cn":""},{"en":"someone, especially a politician or a military leader, who is too keen to increase the size and power of their country's armed forces so that it can attack other countries","cn":""},{"en":"a person, especially a politician, who supports the use of military force and strong action in order to settle arguments with other countries","cn":""}]},"collocations":{"phrases":["HAWK + VERB hover | swoop (down) The hawk swooped low over the field.","PHRASES watch (sb) like a hawk He waited, watching her like a hawk."]},"media":{"img":["media/ldoce/img/hawk.jpg"],"uk":"media/ldoce/hwd/bre/6/hawk_n0205.mp3","us":"media/ldoce/hwd/ame/7/hawk1.mp3"},"examples":[{"en":"He waited, watching her like a hawk (= watching her very closely).","cn":"他等待着，用鹰一样锐利的目光紧盯着她。"}],"oxford":{"phon":"hɔːk","pos":"noun","senses":[{"en":"a strong fast bird of prey (= a bird that kills other creatures for food). There are several different types of hawks.","cn":"鹰；隼","ex":{"en":"He waited, watching her like a hawk (= watching her very closely).","cn":"他等待着，用鹰一样锐利的目光紧盯着她。"}},{"en":"a person, especially a politician, who supports the use of military force to solve problems","cn":"鹰派分子；主战分子"},{"en":"to try to sell things by going from place to place asking people to buy them","cn":"沿街叫卖","g":"[transitive]","ex":{"en":"He made a living hawking cleaning products from door to door.","cn":"他以挨家挨户兜售清洁产品为生。"},"pos":"verb"},{"en":"to get phlegm (= a thick substance that forms in your nose and throat when you are ill) in your mouth when you cough","cn":"咳痰","g":"[intransitive, transitive]","pos":"verb"}]}},"heroism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"英雄气概;英雄主义;大无畏精神","en":"Heroism is great courage and bravery.","ex":{"en":"...individual acts of heroism.","cn":"个人英雄主义行为"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of being brave when you are facing a difficult or dangerous situation, or when you are very ill","cn":""},{"en":"courage in a dangerous or frightening situation, especially when you are fighting in a war","cn":""},{"en":"the courage and determination to do something difficult or unpleasant","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you think of heroism , you might think of great acts of bravery, such as rushing into burning buildings and facing danger in battle. Heroism consists of putting others first, even at your own peril."}]},"collocations":{"phrases":["ADJ. great, real, true","PHRASES an act of heroism"]},"media":{"uk":"media/ldoce/hwd/bre/5/heroism0205.mp3","us":"media/ldoce/hwd/ame/e/laadheroism.mp3"},"examples":[{"en":"stories of heroism and self-sacrifice","cn":"关于英勇无畏和自我牺牲的故事"}],"oxford":{"phon":"ˈherəʊɪzəm","pos":"noun","senses":[{"en":"very great courage","cn":"英勇表现；英雄精神","ex":{"en":"The firefighters displayed both heroism and staunchness.","cn":"消防队员显示出英雄气概和不屈不挠的精神。"}}]}},"headline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指报纸头版的）标题，大字标题","en":"A headline is the title of a newspaper story, printed in large letters at the top of the story, especially on the front page.","ex":{"en":"The Daily Mail has the headline 'The Voice of Conscience'","cn":"《每日邮报》的头版标题为“良知的声音”。"}},{"pos":"N-PLURAL 复数名词","cn":"（广播或电视里的）新闻提要，简明新闻","en":"The headlines are the main points of the news which are read on radio or television.","ex":{"en":"I'm Claudia Polley with the news headlines.","cn":"我是克劳迪娅·波利，下面是新闻提要。"}},{"pos":"VERB 动词","cn":"标题为","en":"If a newspaper or magazine article is headlined a particular thing, that is the headline that introduces it.","ex":{"en":"The article was headlined 'Tell us the truth'.","cn":"文章题为“告诉我们真相”。"}},{"pos":"VERB 动词","cn":"在（演出）中担任主演","en":"If someone headlines a show, they are the main performer in it.","ex":{"en":"Sir Cliff Richard headlined the event.","cn":"克利夫·理查德爵士担任本次活动的主角。"}},{"pos":"PHRASE 短语","cn":"成为新闻焦点","en":"Someone or something that hits the headlines or grabs the headlines gets a lot of publicity from the media.","ex":{"en":"El Salvador first hit the world headlines at the beginning of the 1980s","cn":"萨尔瓦多在20世纪80年代初首次成为世人关注的新闻焦点。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"reports about recent events, reported in newspapers or on television, radio or the Internet","cn":""},{"en":"events that are reported in newspapers or in news programmes","cn":""},{"en":"a short news programme, in which only the most important pieces of news are read","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A headline is the title of a newspaper story. You'll know the headline , because it's printed in the largest font on the front of the paper."}]},"collocations":{"phrases":["ADJ. newspaper, tabloid &lsquo;Carnage at Airport&rsquo;, screamed the tabloid headline. | banner, front-page | screaming | lurid lurid head","VERB + HEADLINE carry, have, run The Guardian carried the front-page headline &lsquo;Drugs Firms Shamed&rsquo;. | read, scan, see I just had","HEADLINE + VERB proclaim sth, read sth, say sth, scream sth The Sunday Observer had a headline saying, &lsquo;Pop Star Arrested on Drugs Cha","HEADLINE + NOUN news &lsquo;Queen Mother goes on Holiday&rsquo; is hardly headline news!","PREP. in a/the ~ The most unusual fact in the story is often used in the headline. | under a/the ~ The Daily Gazette ran a story under the h","PHRASES make headline news The engagement of the two tennis stars made headline news. 2 the headlines: main news stories on TV/radio","ADJ. news","VERB + HEADLINE hear, listen to Let's just hear the news headlines. | look at, see, watch"]},"media":{"uk":"media/ldoce/hwd/bre/3/headline_n0205.mp3","us":"media/ldoce/hwd/ame/c/headline1.mp3"},"examples":[{"en":"They ran the story under the headline ‘Home at last!’.","cn":"报纸刊登这个报道的大标题为“终于回家了！”。"},{"en":"The scandal was in the headlines for several days.","cn":"这一丑闻连续几天都刊登在头版头条。"}],"oxford":{"phon":"ˈhedlaɪn","pos":"noun","senses":[{"en":"the title of a news article printed in large letters, especially at the top of the front page on a newspaper or the home page on a news website","cn":"（报纸或新闻网站首页的）大字标题","g":"[countable]","ex":{"en":"a newspaper headline","cn":"报纸大标题"}},{"en":"a short summary of the most important items of news, read at the beginning of a news programme on the radio or television","cn":"（电台或电视的）新闻摘要","g":"[plural]","ex":{"en":"Do you mind if I listen to the headlines before we leave?","cn":"你介意我在离开前听听头条新闻吗？"}},{"en":"to give a story or article a particular headline","cn":"给（报道、文章）加标题","g":"[transitive, usually passive]","ex":{"en":"The story was headlined ‘Back to the future’.","cn":"报道的标题是“回到未来”。"},"pos":"verb"},{"en":"to be the main performer in a concert or show","cn":"是（音乐会或演出的）主角","g":"[transitive, intransitive]","ex":{"en":"The concert is to be headlined by Ed Sheeran.","cn":"音乐会将由埃德·希兰主唱。"},"pos":"verb"},{"en":"particularly important","cn":"特别重要","ex":{"en":"The story was headline news for two weeks.","cn":"这个故事连续两周成为头条新闻。"},"pos":"adjective"},{"en":"used to describe the most important and popular performers at an entertainment event","cn":"用于描述娱乐活动中最重要和最受欢迎的表演者","ex":{"en":"The band were one of the headline acts at the music festival.","cn":"该乐队是音乐节上的主角之一。"},"pos":"adjective"}]}},"heave":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（用力地）推，拉，拖，举起","en":"If you heave something heavy or difficult to move somewhere, you push, pull, or lift it using a lot of effort.","ex":{"en":"It took five strong men to heave the statue up a ramp and lower it into place","cn":"靠了5个强壮的男子才将雕像拉上坡道，再下放到合适的位置。"}},{"pos":"VERB 动词","cn":"（有节奏地）起伏","en":"If something heaves, it moves up and down with large regular movements.","ex":{"en":"His chest heaved, and he took a deep breath.","cn":"他的胸脯上下起伏，然后他深深地吸了口气。"}},{"pos":"VERB 动词","cn":"呕吐;恶心","en":"If you heave, or if your stomach heaves, you vomit or feel sick.","ex":{"en":"He gasped and heaved and vomited again","cn":"他又开始又喘又吐起来。"}},{"pos":"VERB 动词","cn":"深叹，长舒（一口气）","en":"If you heave a sigh, you give a big sigh.","ex":{"en":"Mr Collier heaved a sigh and got to his feet.","cn":"科利尔先生深叹一口气，站了起来。"}},{"pos":"VERB 动词","cn":"人头攒动;挤满（人）","en":"If a place is heaving or if it is heaving with people, it is full of people.","ex":{"en":"The Happy Bunny club was heaving","cn":"“快乐兔”俱乐部里人头攒动。"}},{"pos":"PHRASE 短语","cn":"出现;进入视野","en":"When something heaves into view or heaves into sight, it appears.","ex":{"en":"The train that now hove into view was clearly of a much older vintage.","cn":"现在进入视野的火车显然是一种古老得多的车型。"}},{"pos":"","cn":"","en":"to heave a sigh of relief→see: ;"},{"pos":"","cn":"","en":"相关词组：heave to"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something or someone move in the direction that your hands are moving","cn":""},{"en":"to pull something suddenly with a short quick movement, often to get someone’s attention","cn":""},{"en":"to pull something along the ground, especially because it is heavy","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 v n 4 ","senses":[{"en":"When you heave something, you haul or lift a heavy object. You might not realize how fat your cat has become until you have to heave him out of the way to make room for yourself on the sofa."}]},"collocations":{"phrases":["ADJ. great, mighty","VERB + HEAVE give (sth) She gave a great heave and the box inched forward."]},"media":{"uk":"media/ldoce/hwd/bre/7/heave_n0205.mp3","us":"media/ldoce/hwd/ame/2/heave1.mp3"},"examples":[{"en":"With a mighty heave he lifted the sack onto the truck.","cn":"他用劲一举，把大麻袋扔到卡车上。"},{"en":"They heaved the body overboard.","cn":"他们使劲把尸体从船上抛入水中。"}],"oxford":{"phon":"hiːv","pos":"verb","senses":[{"en":"to lift, pull or throw somebody/something very heavy with one great effort","cn":"（用力）举起，拖，拉，抛","g":"[transitive, intransitive]","ex":{"en":"I managed to heave the trunk down the stairs.","cn":"我用力把箱子弄下楼梯。"}},{"en":"to rise up and down with strong, regular movements","cn":"（强烈而有节奏地）起伏","g":"[intransitive]","ex":{"en":"The boat heaved beneath them.","cn":"小船在他们脚下颠簸着。"}},{"en":"to make a sound slowly and often with effort","cn":"（常指吃力地）缓慢发出（声音）","g":"[transitive]","ex":{"en":"We all heaved a sigh of relief.","cn":"我们都如释重负地舒了一口气。"}},{"en":"to experience the tight feeling in your stomach that you get before you vomit","cn":"恶心","g":"[intransitive]","ex":{"en":"The thought of it makes me heave.","cn":"一想到那事我就恶心。"}},{"en":"an act of lifting, pulling or throwing","cn":"举；拖；拉；抛","g":"[countable]","ex":{"en":"With a mighty heave he lifted the sack onto the truck.","cn":"他用劲一举，把大麻袋扔到卡车上。"},"pos":"noun"},{"en":"a rising and falling movement","cn":"起伏","g":"[uncountable]","lab":"especially literary","ex":{"en":"the steady heave of the sea","cn":"大海汹涌不断的波涛"},"pos":"noun"}]}},"hurtful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"伤人感情的;使人痛苦的;刻薄的","en":"If you say that someone's comments or actions are hurtful, you mean that they are unkind and upsetting.","ex":{"en":"Her comments can only be hurtful to Mrs Green's family.","cn":"她的话只会使格林夫人的家人感到伤心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"treating people in a way that makes them unhappy or upset. Unkind sounds rather formal. In everyday English, people usually say mean or nasty","cn":""},{"en":"unkind","cn":""},{"en":"deliberately unkind, and seeming to enjoy making people unhappy","cn":""}]},"collocations":{"phrases":["VERBS be | find sth I found some of his comments rather hurtful.","ADV. deeply, very She made some very hurtful remarks. | a bit, rather","PREP. to What he said was deeply hurtful to me."]},"media":{"uk":"media/ldoce/hwd/bre/1/hurtful0205.mp3","us":"media/ldoce/hwd/ame/5/hurtful.mp3"},"examples":[{"en":"He said, rather hurtfully, that he had better things to do than come and see me.","cn":"他相当刻薄地说来看我还不如去干别的事。"},{"en":"The bad reviews of her new book were very hurtful to her.","cn":"对她的新书的负面评论使她很难过。"}],"oxford":{"phon":"ˈhɜːtfl","pos":"adjective","senses":[{"en":"making you feel upset and offended","cn":"伤感情的；伤害自尊的","ex":{"en":"I cannot forget the hurtful things he said.","cn":"我无法忘记他说的那些伤感情的话。"}}]}},"hinduism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"印度教","en":"Hinduism is an Indian religion. It has many gods and teaches that people have another life on earth after they die."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the main religion in India, which includes belief in reincarnation","cn":"印度教"}]},"media":{"uk":"media/ldoce/hwd/bre/2/hinduism0205.mp3","us":"media/ldoce/hwd/ame/d/hinduism.mp3"},"oxford":{"phon":"ˈhɪnduːɪzəm","pos":"noun","senses":[{"en":"the main religion of India and Nepal which includes the worship of one or more gods and belief in reincarnation","cn":"印度教（印度和尼泊尔的主要宗教，敬拜一位或多位神祇，相信轮回转世）"}]}},"handout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"救济金;救济物;施舍物","en":"A handout is a gift of money, clothing, or food, which is given free to poor people.","ex":{"en":"Soldiers oversee the food handouts","cn":"士兵们看管着救济食品。"}},{"pos":"N-COUNT 可数名词","cn":"白给的钱;不劳而获的钱","en":"If you call money that is given to someone a handout, you disapprove of it because you believe that the person who receives it has done nothing to earn or deserve it.","ex":{"en":"...the tendency of politicians to use money on vote-buying handouts rather than on investment in the future","cn":"政客把钱用于可以拉选票的福利上而不是用作未来投资的趋势"}},{"pos":"N-COUNT 可数名词","cn":"传单;宣传材料","en":"A handout is a document which contains news or information about something and which is given, for example, to journalists or members of the public.","ex":{"en":"Official handouts describe the Emperor as 'particularly noted as a scholar'.","cn":"官方印发的材料将皇帝描述为“尤以学识渊博而著称”。"}},{"pos":"N-COUNT 可数名词","cn":"（发给听众的）讲义，提纲","en":"A handout is a paper containing a summary of information or topics which will be dealt with in a lecture or talk."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something, especially money that is given to help people","cn":""},{"en":"money or help given to help the poor, the sick etc","cn":""},{"en":"money, food, medicine etc that is given by a government or organization to the people of another country or to people who are in a very difficult situation","cn":""}]},"collocations":{"phrases":["ADJ. free | government, state | cash","VERB + HANDOUT give (sb) | get, receive All those eligible will receive a cash handout.","PREP. ~ from a handout from the government | ~ to state handouts to the poor 2 sheet/leaflet","VERB + HANDOUT distribute, give sb, give out","PREP. in a/the ~ More information can be found in the handout. | ~ on We were given a handout on job hunting."]},"media":{"uk":"media/ldoce/hwd/bre/f/handout0205.mp3","us":"media/ldoce/hwd/ame/9/handout.mp3"},"examples":[{"en":"people who have to live on handouts from the state","cn":"必须依赖国家发放的救济金生活的人们"},{"en":"Please read the handout.","cn":"请看一下发下来的材料。"}],"oxford":{"phon":"ˈhændaʊt","pos":"noun","senses":[{"en":"food, money or clothes that are given to a person who is poor","cn":"捐赠品；救济品","lab":"sometimes disapproving","ex":{"en":"to be dependent on handouts","cn":"依赖施舍"}},{"en":"money that is given to a person or an organization by the government, etc., for example to encourage commercial activity","cn":"政府拨款（为促进商业活动）","lab":"often disapproving","ex":{"en":"a handout from the government","cn":"来自政府的救济"}},{"en":"a free document that gives information about an event or a matter of public interest, or that states the views of a political party, etc.","cn":"传单","ex":{"en":"We were given a handout on job hunting.","cn":"我们获发一份有关求职的印刷品。"}},{"en":"a document that is given to students in class or people attending a talk, etc. and that contains a summary of the lesson/talk, a set of exercises, etc.","cn":"（发给学生或参与讨论者等的）讲义，文字材料"}]}},"heroin":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"海洛因","en":"Heroin is a powerful drug which some people take for pleasure, but which they can become addicted to."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a powerful and illegal drug made from morphine","cn":"海洛因"}]},"collocations":{"phrases":["ADJ. pure | street","QUANT. dose, gram, ounce, shot, wrap","VERB + HEROIN fix, inject, smoke","HEROIN + NOUN injector | possession | injection | overdose a fatal heroin overdose | dealing • Note at DRUG (for more verbs and nouns)"]},"media":{"uk":"media/ldoce/hwd/bre/7/heroin0205.mp3","us":"media/ldoce/hwd/ame/f/heroin.mp3"},"examples":[{"en":"a heroin addict","cn":"吸海洛因上瘾的人"}],"oxford":{"phon":"ˈherəʊɪn","pos":"noun","senses":[{"en":"a powerful illegal drug made from morphine, that some people take for pleasure and can become addicted to","cn":"海洛因","ex":{"en":"a heroin addict","cn":"吸海洛因上瘾的人"}}]}},"honourable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）值得尊敬的，正直的;（行为）光荣的，体面的","en":"If you describe people or actions as honourable, you mean that they are good and deserve to be respected and admired.","ex":{"en":"I believe he was an honourable man, dedicated to the people and his union","cn":"我认为他是个品行高洁的人，一心奉献于人民和工会的事业。"}},{"pos":"ADJ 形容词","cn":"（用于某些贵族和法官等官员名字前的尊称）尊敬的，阁下","en":"Honourable is used as a title before the names of some members of the nobility, judges, and some other officials.","ex":{"en":"...the Honourable Mr Justice Swinton Thomas.","cn":"尊敬的斯温顿·托马斯法官先生"}},{"pos":"ADJ 形容词","cn":"（英国议会辩论时议员彼此间的尊称）尊敬的，阁下","en":"In debates in the British parliament, one member of parliament refers to another as the honourable member, the honourable gentleman, the honourable lady, or their honourable friend.","ex":{"en":"...the Honourable Member for Billericay.","cn":"比勒里基区的议员阁下"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"morally correct","cn":""},{"en":"morally correct, especially according to a set of ideas about how people should behave in a particular profession","cn":""},{"en":"fair, honest, or kind","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. very a very honourable man | completely, entirely, perfectly My intentions were perfectly honourable."]},"media":{"uk":"media/ldoce/hwd/bre/7/honourable0205.mp3","us":"media/ldoce/hwd/ame/4/honorable.mp3"},"examples":[{"en":"With a few honourable exceptions, the staff were found to be incompetent.","cn":"除了几个优秀的人以外，其他职员都不能胜任工作。"},{"en":"They managed an honourable 2–2 draw.","cn":"他们奋力打成了 2:2 平局，值得敬佩。"}],"oxford":{"phon":"ˈɒnərəbl","pos":"adjective","senses":[{"en":"deserving great respect","cn":"可敬的；值得钦佩的","ex":{"en":"She had a long and honourable career in government.","cn":"她从政时间长，且名声清白。"}},{"en":"showing high moral standards","cn":"品格高尚的","ex":{"en":"He was an honourable man who could not lie.","cn":"他是个高尚的人，不会说谎。"}},{"en":"allowing somebody to keep their good name and the respect of others","cn":"保护声誉的；体面的","ex":{"en":"an honourable compromise","cn":"体面的妥协"}},{"en":"(in the UK) a title used by a child of some ranks of the nobility","cn":"（英国某些贵族子女的头衔）","g":"[only before noun]"},{"en":"(in the UK) a title used by Members of Parliament when talking about or to another Member during a debate","cn":"（英国议会议员辩论时相互间的尊称）","g":"[only before noun]","ex":{"en":"If my Honourable Friend would give me a chance to answer,…","cn":"如果尊敬的阁下能给我答辩的机会…"}},{"en":"a title of respect used for an official of high rank","cn":"（高级官员的尊称）","g":"[only before noun]","ex":{"en":"the Honorable Alan Simpson, US senator","cn":"美国参议员艾伦·辛普森"}}]}},"hunch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"直觉;预感;第六感","en":"If you have a hunch about something, you are sure that it is correct or true, even though you do not have any proof.","ex":{"en":"I had a hunch that Susan and I would work well together","cn":"我有预感和苏珊共事会很融洽。"}},{"pos":"VERB 动词","cn":"（常指因寒冷、生病或愁苦而）耸肩弓身，蜷起身子","en":"If you hunch forward, you raise your shoulders, put your head down, and lean forwards, often because you are cold, ill, or unhappy.","ex":{"en":"He got out his map of Yorkshire and hunched over it to read the small print.","cn":"他拿出约克郡地图，弓身趴在上面努力看清那些细小的字体。"}},{"pos":"VERB 动词","cn":"耸起（双肩）","en":"If you hunch your shoulders, you raise them and lean forwards slightly.","ex":{"en":"Wes hunched his shoulders and leaned forward on the edge of the counter.","cn":"韦斯耸起双肩，身体前倾靠在柜台边上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the answer you give when you are trying to guess a number or amount but are not able to be exact","cn":""},{"en":"a strange feeling that you know the answer to something, even though you have very little information to help you to guess","cn":""},{"en":"a guess, especially an answer, that seems stupid or is very likely to be wrong","cn":""}]},"vocab":{"pos":"1 n 2 v n","senses":[{"en":"When you pose for pictures with short friends, you hunch over so you don't tower above them — you scrunch up your shoulders, bend your knees, and try to look smaller."}]},"collocations":{"phrases":["VERB + HUNCH have I had a hunch that she was not telling the truth. | act on, follow, play Acting on a hunch, I waited outside her house to ","PREP. on a ~ I phoned on a hunch to ask if they had any work for me."]},"media":{"uk":"media/ldoce/hwd/bre/2/hunch_v0205.mp3","us":"media/ldoce/hwd/ame/5/hunch1.mp3"},"examples":[{"en":"He hunched his shoulders and thrust his hands deep into his pockets.","cn":"他耸着肩，双手深深地插进衣袋。"},{"en":"She leaned forward, hunching over the desk.","cn":"她身体前倾，伏在写字台上。"}],"oxford":{"phon":"hʌntʃ","pos":"verb","senses":[{"en":"to bend the top part of your body forward and raise your shoulders and back","cn":"弓身；弓背；耸肩","ex":{"en":"She leaned forward, hunching over the desk.","cn":"她身体前倾，伏在写字台上。"}},{"en":"a feeling that something is true even though you do not have any evidence to prove it","cn":"预感；直觉","ex":{"en":"It seemed that the doctor's hunch had been right.","cn":"看起来医生的直觉是对的。"},"pos":"noun"}]}},"hoard":{"collins":{"senses":[{"pos":"VERB 动词","cn":"贮藏;囤积","en":"If you hoard things such as food or money, you save or store them, often in secret, because they are valuable or important to you.","ex":{"en":"They've begun to hoard food and gasoline and save their money","cn":"他们已经存钱并开始贮藏食物和汽油。"}},{"pos":"N-COUNT 可数名词","cn":"贮藏物;隐藏物;收藏物","en":"A hoard is a store of things that you have saved and that are valuable or important to you or you do not want other people to have.","ex":{"en":"The case involves a hoard of silver and jewels valued at up to $40m.","cn":"此案涉及密藏的一批价值高达4,000万美元的银子和珠宝。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large quantity of something that you keep, and that you replace regularly because you use it often","cn":""},{"en":"the amount of a particular product that a shop keeps to be sold","cn":""},{"en":"something such as money, food, or water that you keep because you might need it in the future","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To hoard is to save something (or lots of things) for future use. Squirrels hoard nuts for the winter. Old ladies tend to hoard canned food and used plastic bags."}]},"collocations":{"phrases":["ADJ. big, large, major, vast one of the biggest hoards of Roman coins ever found | small | secret her secret hoard of food","PREP. in ~s Gold coins have been found in hoards in many parts of the country. | ~ of a vast hoard of treasure"]},"media":{"uk":"media/ldoce/hwd/bre/0/hoard_las2_br.mp3","us":"media/ldoce/hwd/ame/3/hoard1.mp3"},"examples":[{"en":"the discovery of a hoard of gold coins","cn":"一批秘藏金币的发现"},{"en":"families who hoarded food during the strike","cn":"罢工期间囤积食品的家庭"}],"oxford":{"phon":"hɔːd","pos":"noun","senses":[{"en":"a collection of money, food, valuable objects, etc., especially one that somebody keeps in a secret place so that other people will not find or steal it","cn":"（钱、食物、贵重物品等的）贮存，聚藏；（尤指）秘藏","ex":{"en":"They dug up a hoard of Roman coins.","cn":"他们挖出一批秘藏的古罗马硬币。"}},{"en":"to collect and keep large amounts of food, money, etc., often secretly","cn":"（常指偷偷地）贮藏，囤积","ex":{"en":"The prisoners used to hoard scraps of food in secret places.","cn":"过去囚犯常把残羹剩饭存放在隐秘的地方。"},"pos":"verb"}]}},"harass":{"collins":{"senses":[{"pos":"VERB 动词","cn":"骚扰;烦扰","en":"If someone harasses you, they trouble or annoy you, for example by attacking you repeatedly or by causing you as many problems as they can.","ex":{"en":"A woman reporter complained one of them sexually harassed her in the locker room","cn":"一名女记者投诉说，他们中有一人在更衣室里对她进行性骚扰。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone’s life unpleasant, for example by frequently saying offensive things to them or threatening them","cn":"骚扰"},{"en":"to keep attacking an enemy again and again","cn":"反复攻击﹐屡次侵扰〔敌人〕"}]},"vocab":{"pos":"v","senses":[{"en":"When you harass someone, you bother them to the point of exhaustion. It’s not that each attack is so severe, it’s the constant small attacks that wear someone out. If you harass your boss for a raise, you might end up getting fired instead!"}]},"collocations":{"phrases":["ADV. racially, sexually She had been sexually harassed at work."]},"media":{"uk":"media/ldoce/hwd/bre/1/harass_las3_br.mp3","us":"media/ldoce/hwd/ame/5/harass.mp3"},"examples":[{"en":"She claims she has been sexually harassed at work.","cn":"她声称在工作中受到性骚扰。"},{"en":"He has complained of being harassed by the police.","cn":"他投诉受到警方侵扰。"}],"oxford":{"phon":"ˈhærəs","pos":"verb","senses":[{"en":"to annoy or worry somebody by putting pressure on them or saying or doing unpleasant things to them","cn":"侵扰；骚扰","g":"[often passive]","ex":{"en":"He has complained of being harassed by the police.","cn":"他投诉受到警方侵扰。"}},{"en":"to make repeated attacks on an enemy","cn":"反复进攻；不断攻击（敌人）","ex":{"en":"Our convoys are being continually harassed by enemy submarines.","cn":"我们的船队不断受到敌方潜艇的攻击。"}}]}},"horoscope":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"星象（指某人诞生时各天体的位置，用以占卜命运）","en":"Your horoscope is a prediction of events which some people believe will happen to you in the future. Horoscopes are based on the position of the stars when you were born."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of the positions and movements of the stars and how they might influence people and events","cn":""},{"en":"a description of people’s characters and the things that will happen to them, based on the position of the stars and planets at the time of their birth – especially a description that is printed in a newspaper or magazine","cn":""},{"en":"the twelve signs that you can belong to according to your birth date and the position of the stars then, which some people believe influence our characters and our lives","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"You can usually read your daily horoscope in the local newspaper. A horoscope is a forecast of your future based on the month in which you were born."}]},"collocations":{"phrases":["VERB + HOROSCOPE cast, draw up To draw up someone's horoscope, you need to know their date and exact time of birth. | consult, read | believ","HOROSCOPE + VERB say sth What does your horoscope say?"]},"media":{"uk":"media/ldoce/hwd/bre/e/horoscope0205.mp3","us":"media/ldoce/hwd/ame/c/horoscope.mp3"},"oxford":{"phon":"ˈhɒrəskəʊp","pos":"noun","senses":[{"en":"a prediction of what is going to happen to somebody in the future, based on the position of the stars and the planets when the person was born","cn":"占星术","ex":{"en":"Do you believe in horoscopes?","cn":"你相信占星术吗？"}}]}},"hindrance":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"妨碍者;障碍物","en":"A hindrance is a person or thing that makes it more difficult for you to do something.","ex":{"en":"The higher rates have been a hindrance to economic recovery","cn":"高利率已经成为经济复苏的障碍。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"阻碍;妨碍","en":"Hindrance is the act of hindering someone or something.","ex":{"en":"They boarded their flight to Paris without hindrance.","cn":"他们顺利地登上了飞往巴黎的航班。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens which stops you making progress or which makes things worse than they were before","cn":""},{"en":"a problem or difficulty that must be dealt with before you can do or achieve something else","cn":""},{"en":"a fact or situation that will make it very difficult for something to be achieved","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A hindrance is something in the way, an obstacle. An untied shoelace is a hindrance to walking, and tripping in the lunchroom might be a hindrance to getting a seat at the cool table."}]},"collocations":{"phrases":["ADJ. great","VERB + HINDRANCE be, prove Having a car in the city might prove a hindrance.","PREP. without ~ (formal) The cook needs room to get at the cooker, sink and cupboards without hindrance. | ~ to The new regulations are actu","PHRASES without let or hindrance (law)"]},"media":{"uk":"media/ldoce/hwd/bre/b/hindrance0205.mp3","us":"media/ldoce/hwd/ame/b/hindrance.mp3"},"examples":[{"en":"To be honest, she was more of a hindrance than a help.","cn":"说实在的，她没帮上忙，反而成了累赘。"},{"en":"The high price is a major hindrance to potential buyers.","cn":"价格高是使潜在买主却步的主要因素。"}],"oxford":{"phon":"ˈhɪndrəns","pos":"noun","senses":[{"en":"a person or thing that makes it more difficult for somebody to do something or for something to happen","cn":"造成妨碍的人（或事物）","g":"[countable, usually singular]","ex":{"en":"To be honest, she was more of a hindrance than a help.","cn":"说实在的，她没帮上忙，反而成了累赘。"}},{"en":"the act of making it more difficult for somebody to do something or for something to happen","cn":"妨碍；阻挠","g":"[uncountable]","lab":"formal","ex":{"en":"They were able to complete their journey without further hindrance.","cn":"剩下的旅程他们没再受到阻碍。"}}]}},"hesitate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"犹豫;迟疑;踌躇","en":"If you hesitate, you do not speak or act for a short time, usually because you are uncertain, embarrassed, or worried about what you are going to say or do.","ex":{"en":"The telephone rang. Catherine hesitated, debating whether to answer it","cn":"电话响了。凯瑟琳犹豫了一下要不要去接。"}},{"pos":"VERB 动词","cn":"（因有顾虑而）不愿意（做某事）","en":"If you hesitate to do something, you delay doing it or are unwilling to do it, usually because you are not certain it would be right. If you do not hesitate to do something, you do it immediately.","ex":{"en":"Some parents hesitate to take these steps because they suspect that their child is exaggerating","cn":"一些家长不愿意采取这些措施，因为他们怀疑自己的孩子在夸大其词。"}},{"pos":"VERB 动词","cn":"尽管给我打电话/ 尽管和我们联系","en":"You can use hesitate in expressions such as 'don't hesitate to call me' or 'don't hesitate to contact us' when you are telling someone that they should do something as soon as it needs to be done and should not worry about disturbing other people.","ex":{"en":"In the event of difficulties, please do not hesitate to contact our Customer Service Department","cn":"如果遇到困难，请尽管和我们的客户服务部联系。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stop speaking or stop doing something for a very short time before starting again. Pause is used especially in written descriptions. In everyday spoken English, people usually just say stop","cn":""},{"en":"to stop for a moment and wait before doing something, because you feel unsure or nervous about it","cn":""},{"en":"to stop working for a short time in order to rest, eat etc","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To hesitate is to pause before doing something, often out of concern or worry."}]},"collocations":{"phrases":["ADV. briefly, a little, (for) a minute/moment/second, momentarily Alison hesitated a moment, as if she were waiting for him.","VERB + HESITATE appear to, seem to | make sb Something about his smile made her hesitate.","PREP. about I didn't hesitate about working with Craig. | between He was hesitating between a glass of wine and an orange juice. | over He s"]},"media":{"uk":"media/ldoce/hwd/bre/5/hesitate0205.mp3","us":"media/ldoce/hwd/ame/5/hesitate.mp3"},"examples":[{"en":"I have no hesitation in recommending her for the job.","cn":"我毫不犹豫地推荐她做这项工作。"},{"en":"I didn't hesitate for a moment about taking the job.","cn":"我毫不犹豫地接受了那份工作。"}],"oxford":{"phon":"ˈhezɪteɪt","pos":"verb","senses":[{"en":"to be slow to speak or act because you feel uncertain or nervous","cn":"（对某事）犹豫，迟疑不决","g":"[intransitive, transitive]","ex":{"en":"She hesitated before replying.","cn":"她犹豫了一下才回答。"}},{"en":"to be worried about doing something, especially because you are not sure that it is right or appropriate","cn":"顾虑；疑虑","g":"[intransitive]","ex":{"en":"Please do not hesitate to contact me if you have any queries.","cn":"如果有疑问就请尽管和我联系。"}}]}},"harvard":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a famous and respected university in Cambridge, Massachusetts, established in 1636, which is the oldest university in the US","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/p028-000005872.mp3","us":"media/ldoce/hwd/ame/a/p028-000005872.mp3"}},"heroic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"英雄的;英勇的","en":"If you describe a person or their actions as heroic, you admire them because they show extreme bravery.","ex":{"en":"The heroic sergeant risked his life to rescue 29 fishermen from their blazing trawler","cn":"英勇的中士冒着生命危险从熊熊燃烧着的拖网渔船上救出了29名渔民。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"矢志不渝的;艰苦卓绝的","en":"If you describe an action or event as heroic, you admire it because it involves great effort or determination to succeed.","ex":{"en":"The company has made heroic efforts at cost reduction","cn":"公司在降低成本方面付出了艰苦卓绝的努力。"}},{"pos":"ADJ 形容词","cn":"男主角的","en":"Heroic means being or relating to the hero of a story.","ex":{"en":"...the book's central, heroic figure.","cn":"书中的中心主角人物"}},{"pos":"N-PLURAL 复数名词","cn":"英雄壮举;英勇果断的行为","en":"Heroics are actions involving bravery, courage, or determination.","ex":{"en":"...the man whose aerial heroics helped save the helicopter pilot","cn":"以空中的英雄壮举拯救了直升机飞行员的人"}},{"pos":"N-PLURAL 复数名词","cn":"（愚蠢或危险的）逞英雄行为","en":"If you describe someone's actions or plans as heroics, you think that they are foolish or dangerous because they are too difficult or brave for the situation in which they occur.","ex":{"en":"He said his advice was: 'No heroics, stay within the law'","cn":"他说自己的建议是：“不要逞英雄，要遵纪守法。”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing that you are not afraid to do things that other people find dangerous or difficult","cn":""},{"en":"very brave – used especially about someone fighting for what they believe in, or fighting against a disease","cn":""},{"en":"brave and willing to take a lot of risks","cn":""}]},"vocab":{"pos":"1 adj 2 adj n","senses":[{"en":"Heroic means having the qualities of a hero, such as bravery. Maybe on your daily walk, you see a house on fire, and you run into the flames repeatedly to save the family and their pets, including the fish! That’s heroic ."}]},"collocations":{"phrases":["VERBS be","ADV. truly a truly heroic battle | suitably He struck a suitably heroic pose."]},"media":{"uk":"media/ldoce/hwd/bre/e/heroic0205.mp3","us":"media/ldoce/hwd/ame/9/heroic.mp3"},"examples":[{"en":"We watched our team's heroic struggle to win back the cup.","cn":"我们目睹了我队为赢回奖杯所付出的不懈努力。"},{"en":"Rescuers made heroic efforts to save the crew.","cn":"救援人员不畏艰险努力营救全体船员。"}],"oxford":{"phon":"həˈrəʊɪk","pos":"adjective","senses":[{"en":"showing extreme courage and admired by many people","cn":"英勇的；英雄的","ex":{"en":"She is a heroic figure we can all look up to.","cn":"她是我们都会敬仰的英雄人物。"}},{"en":"showing a determined effort to succeed or to achieve something, especially something difficult","cn":"有必胜决心的；不畏艰难的","ex":{"en":"We watched our team's heroic struggle to win back the cup.","cn":"我们目睹了我队为赢回奖杯所付出的不懈努力。"}},{"en":"that is about or involves a hero","cn":"（关于）英雄的","ex":{"en":"a heroic story/poem","cn":"英雄故事／颂诗"}},{"en":"very large or great","cn":"巨大的；了不起的","ex":{"en":"This was foolishness on a heroic scale.","cn":"这简直是天大的蠢事。"}}]}},"heighten":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）（情感）增强;（使）加深","en":"If something heightens a feeling or if the feeling heightens, the feeling increases in degree or intensity.","ex":{"en":"The move has heightened tension in the state","cn":"该举动加剧了州里的紧张气氛。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something such as someone's determination or belief increase so that it is even stronger than it was before","cn":""},{"en":"if something heightens knowledge, fears, the effect of something etc, it makes it increase so that it is felt more strongly","cn":""},{"en":"to increase a feeling or problem, so that it becomes worse","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you heighten something, you increase it or make it more intense. If you want to heighten awareness about homelessness, you might write an article for your local newspaper."}]},"collocations":{"phrases":["ADV. greatly This latest attack has greatly heightened fears of an all-out war. | further","VERB + HEIGHTEN serve to Seeing others enjoying themselves only served to heighten his sense of loneliness. | seek to an exercise which seek"]},"media":{"uk":"media/ldoce/hwd/bre/c/heighten0205.mp3","us":"media/ldoce/hwd/ame/1/heighten.mp3"},"examples":[{"en":"The campaign is intended to heighten public awareness of the disease.","cn":"这场运动的目的是使公众更加了解这种疾病。"},{"en":"Tension has heightened after the recent bomb attack.","cn":"最近的炸弹袭击之后，情势更加紧张。"}],"oxford":{"phon":"ˈhaɪtn","pos":"verb","senses":[{"en":"if a feeling or an effect heightens, or something heightens it, it becomes stronger or increases","cn":"（使）加强，提高，增加","ex":{"en":"Tension has heightened after the recent bomb attack.","cn":"最近的炸弹袭击之后，情势更加紧张。"}}]}},"handicapped":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"残疾的，有生理缺陷的，弱智的（可能具冒犯意味）","en":"Someone who is handicapped has a physical or mental disability that prevents them living a totally normal life. Many people who have a disability find this word offensive.","ex":{"en":"I'm going to work two days a week teaching handicapped kids to fish","cn":"我将每周工作两天，教残疾儿童钓鱼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not able to use a part of your body properly or not able to learn normally, because of a permanent problem","cn":""},{"en":"if someone has special needs, they have physical or mental disabilities","cn":""},{"en":"if someone has learning difficulties, they have difficulty learning basic skills or information","cn":""}]},"collocations":{"phrases":["VERBS be, be born Steven was born severely handicapped. | leave sb An accident at birth left him badly handicapped.","ADV. badly, profoundly, seriously, severely | mildly, slightly | permanently | mentally, physically, visually special equipment for visually"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdehandicapped.mp3","us":"media/ldoce/hwd/ame/a/handicapped.mp3"},"examples":[{"en":"The accident left him physically handicapped.","cn":"那次事故使他落下了残疾。"},{"en":"a school for the physically handicapped","cn":"残疾人学校"}],"oxford":{"phon":"ˈhændikæpt","pos":"adjective","senses":[{"en":"having a condition that makes it difficult for you to do some things that most other people can do","cn":"丧失能力的；有残疾的；无能力的","lab":"old-fashioned, usually offensive，，","ex":{"en":"The accident left him physically handicapped.","cn":"那次事故使他落下了残疾。"}},{"en":"people who are handicapped","cn":"残疾人；弱智者","g":"[plural]","lab":"old-fashioned, offensive，，"}]},"base":"handicap"},"haphazard":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无计划的;杂乱无章的;任意的","en":"If you describe something as haphazard, you are critical of it because it is not at all organized or is not arranged according to a plan.","ex":{"en":"The investigation does seem haphazard","cn":"调查工作确实看起来缺乏计划。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done in a careless and lazy way - use this about someone's work or the way someone writes or speaks","cn":""},{"en":"done extremely carelessly and quickly, without paying any attention to the correct ways of working","cn":""},{"en":"done without any clear plan or system","cn":""}]},"vocab":{"pos":"1 adj 2 adj adv","senses":[{"en":"Anything haphazard is random, disorganized, slipshod, or hit-or-miss. A tent erected haphazardly might look more like a big nylon bag of dirty laundry than a place to sleep."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. very | entirely, totally The local authority's approach to health care seems totally haphazard. | fairly, rather, somewhat | apparently","PHRASES in a haphazard fashion/manner/way The town had grown in a somewhat haphazard way."]},"media":{"uk":"media/ldoce/hwd/bre/a/haphazard0205.mp3","us":"media/ldoce/hwd/ame/7/haphazard.mp3"},"examples":[{"en":"The government's approach to the problem was haphazard.","cn":"政府解决这一问题的方法缺乏计划。"},{"en":"The books had been piled on the shelves in a haphazard fashion.","cn":"书架上的书堆放得杂乱无序。"}],"oxford":{"phon":"hæpˈhæzəd","pos":"adjective","senses":[{"en":"with no particular order or plan; not organized well","cn":"无秩序的；无计划的；组织混乱的","ex":{"en":"The books had been piled on the shelves in a haphazard fashion.","cn":"书架上的书堆放得杂乱无序。"}}]}},"haste":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"急速;仓促;匆忙","en":"Haste is the quality of doing something quickly, sometimes too quickly so that you are careless and make mistakes.","ex":{"en":"In their haste to escape the rising water, they dropped some expensive equipment","cn":"他们在河水上涨仓促逃离时，丢掉了一些值钱的装备。"}},{"pos":"PHRASE 短语","cn":"匆忙地;急忙地;草率地","en":"If you do something in haste, you do it quickly and hurriedly, and sometimes carelessly.","ex":{"en":"Don't act in haste or be hot-headed.","cn":"不可草率行事，不可头脑发热。"}},{"pos":"PHRASE 短语","cn":"赶快;赶紧","en":"If someone is told to make haste, they are told to do something quickly and not waste time.","ex":{"en":"As Simon was under orders to make haste, some days they covered thirty miles.","cn":"西蒙接到命令要求抓紧行动，有些日子他们一走就是30英里。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to go somewhere or do something more quickly than usual, for example because you are late or because you must finish something by a particular time","cn":""},{"en":"to do something or go somewhere very quickly, often so quickly that you do not do it carefully or properly","cn":""},{"en":"to go somewhere very quickly, usually by running, especially because there is something important or urgent you must do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When something is done in haste, it's done fast, and often with carelessness. In his haste to finish the paper, he didn't notice he had replaced \"taste\" with \"waste\" during spell-checking, so his title became, \"Foods of Our Home State: What a Waste!\""}]},"collocations":{"phrases":["ADJ. blind, breathless, frantic, great She worked with frantic haste. | indecent, reckless, undue He accused the government of undue haste i","VERB + HASTE make I had to make haste if I wasn't to be late.","PREP. in (your) ~ They obviously left in great haste. In his haste to get home, he forgot to go to the library. | with ~ He married again wi","PHRASES with all haste The ships were ordered to sea with all haste."]},"media":{"uk":"media/ldoce/hwd/bre/7/haste0205.mp3","us":"media/ldoce/hwd/ame/6/haste.mp3"},"examples":[{"en":"After his first wife died, he married again with almost indecent haste.","cn":"他的第一任妻子死后，他几乎是迫不及待地就再婚了。"},{"en":"In her haste to complete the work on time, she made a number of mistakes.","cn":"她急急忙忙想按时完工，结果出了不少错。"}],"oxford":{"phon":"heɪst","pos":"noun","senses":[{"en":"speed in doing something, especially because you do not have enough time","cn":"急速；匆忙；仓促","lab":"old-fashioned","ex":{"en":"In her haste to complete the work on time, she made a number of mistakes.","cn":"她急急忙忙想按时完工，结果出了不少错。"}}]}},"hiss":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出嘶嘶声","en":"To hiss means to make a sound like a long 's'.","ex":{"en":"The tires of Lenny's bike hissed over the wet pavement as he slowed down","cn":"伦尼放缓车速，听到自行车轮胎在湿漉漉的路面上发出嘶嘶的响声。"}},{"pos":"VERB 动词","cn":"低声呵斥","en":"If you hiss something, you say it forcefully in a whisper.","ex":{"en":"'Now, quiet,' my mother hissed","cn":"“好了，安静点，”母亲压低嗓音厉声道。"}},{"pos":"VERB 动词","cn":"（对不喜欢的表演者或发言人）发嘘声，向…喝倒彩","en":"If people hiss at someone such as a performer or a person making a speech, they express their disapproval or dislike of that person by making long loud 's' sounds.","ex":{"en":"One had to listen hard to catch the words of the President's speech as the delegates booed and hissed","cn":"代表们嘘声四起，很难听清总统的讲话。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a continuous high sound when air or gas comes out of something","cn":""},{"en":"to shout 'boo' to show that you do not like a speaker, performance etc","cn":""},{"en":"to make a noise which sounds like 'ssss' to show that you do not like a speaker, performance etc","cn":""}]},"collocations":{"phrases":["ADJ. sharp | faint, soft, low There was a low hiss on the tape. | audible","VERB + HISS give, let out The snake gave a hiss. | hear","PREP. with a ~ She drew in her breath with a hiss. | ~ of We could hear the faint hiss of escaping gas.","PHRASES boos and hisses, a hiss of air, the hiss of a snake • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/d/hiss0205.mp3","us":"media/ldoce/hwd/ame/c/hiss.mp3"},"examples":[{"en":"The steam escaped with a loud hissing noise.","cn":"蒸汽冒了出来，发出很响的嘶嘶声。"},{"en":"He was booed and hissed off the stage.","cn":"他在一片倒彩声和嘘声中被轰下台。"}],"oxford":{"phon":"hɪs","pos":"verb","senses":[{"en":"to make a sound like a long ‘s’","cn":"发嘶嘶声","g":"[intransitive]","ex":{"en":"The steam escaped with a loud hissing noise.","cn":"蒸汽冒了出来，发出很响的嘶嘶声。"}},{"en":"to make a sound like a long ‘s’ to show disapproval of somebody/something, especially an actor or a speaker","cn":"发嘘声（表示不满，尤指对演员或演讲人）","g":"[transitive, intransitive]","ex":{"en":"He was booed and hissed off the stage.","cn":"他在一片倒彩声和嘘声中被轰下台。"}},{"en":"to say something in a quiet angry voice","cn":"带怒气地低声说出（某事）","g":"[intransitive, transitive]","ex":{"en":"He hissed at them to be quiet.","cn":"他生气地低声要他们安静点。"}},{"en":"a sound like a long ‘s’; this sound used to show disapproval of somebody","cn":"嘶嘶声；嘘声","ex":{"en":"The hiss of air brakes announced the arrival of the tour bus.","cn":"一听到气动刹车的嘶嘶声就知道旅游巴士到了。"},"pos":"noun"}]}},"hoax":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"恶作剧;假警报;骗局","en":"A hoax is a trick in which someone tells people a lie, for example that there is a bomb somewhere when there is not, or that a picture is genuine when it is not.","ex":{"en":"A series of bomb hoaxes has disrupted Christmas shopping in the city centre","cn":"一系列炸弹假警报扰乱了市中心的圣诞节购物活动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a clever plan designed to make someone believe something that you want them to believe, or do something that you want them to do","cn":""},{"en":"a clever plan designed to harm someone, for example by making them go somewhere where they will be caught or attacked, or making them say something they will be punished for","cn":""},{"en":"something that is said or done with the deliberate intention of deceiving people","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you put on big fake feet, stomp through your muddy backyard and tell everyone you saw Bigfoot fixing a steak on your grill, you are playing a hoax on your friends."}]},"collocations":{"phrases":["ADJ. elaborate It turned out to be an elaborate hoax. | cruel He described the deception as a cruel hoax. | bomb","VERB + HOAX perpetrate, play, stage a hoax perpetrated by the British government","HOAX + NOUN call, caller","PREP. ~ on The organizers staged a hoax on some of the competitors."]},"media":{"uk":"media/ldoce/hwd/bre/7/hoax0205.mp3","us":"media/ldoce/hwd/ame/2/hoax1.mp3"},"examples":[{"en":"hoax calls","cn":"恶作剧的电话"},{"en":"a bomb hoax","cn":"炸弹骗局"}],"oxford":{"phon":"həʊks","pos":"noun","senses":[{"en":"an act intended to make somebody believe something that is not true, especially something unpleasant","cn":"骗局；恶作剧","ex":{"en":"He was accused of using a bomb hoax to empty a rival restaurant.","cn":"他被控谎称有炸弹以吓跑一家对手餐厅的食客。"}},{"en":"to trick somebody by making them believe something that is not true, especially something unpleasant","cn":"作弄；欺骗","ex":{"en":"He hoaxed us by sending a friend instead of coming himself. We’d never met him so we had no reason to think it wasn’t him.","cn":"他派了一个朋友来欺骗我们，而不是亲自来。我们从未见过他，所以我们没有理由认为那不是他。"},"pos":"verb"}]}},"housekeeping":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"料理家务;家政管理","en":"Housekeeping is the work and organization involved in running a home, including the shopping and cleaning.","ex":{"en":"I thought that cooking and housekeeping were unimportant, easy tasks.","cn":"我认为做饭和料理家务微不足道，一下子就能搞定。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（旅馆的）客房勤杂","en":"Housekeeping is the part of the organization of a hotel which deals with keeping the rooms clean and properly equipped."},{"pos":"N-UNCOUNT 不可数名词","cn":"家务开支;家用钱","en":"Housekeeping is the money that you use to buy food, cleaning materials, and other things that you need in your home.","ex":{"en":"...the housekeeping money Jim gave her each week.","cn":"吉姆每周给她的家用钱"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the work and organization of things that need to be done in a house, hotel etc, for example cooking and buying food","cn":"家务﹔后勤"},{"en":"an amount of money that is kept and used to pay for food and other things needed in the home","cn":"家务开支﹐家用钱"},{"en":"jobs that need to be done to keep a system working properly 〔","cn":"维持某个系统正常运转的〕内务工作"}]},"collocations":{"phrases":["ADJ. careful, good, prudent The company has made considerable savings through good housekeeping, such as avoiding wastage. | bad, poor My fi","HOUSEKEEPING + NOUN allowance, money Her husband spent the housekeeping money on gambling."]},"media":{"uk":"media/ldoce/hwd/bre/3/housekeeping0205.mp3","us":"media/ldoce/hwd/ame/9/housekeeping.mp3"},"examples":[{"en":"Call housekeeping and ask them to bring us some clean towels.","cn":"给总务处打电话，让他们给我们送些干净的毛巾来。"},{"en":"Most large companies now use computers for accounting and housekeeping operations.","cn":"多数大公司现在用计算机进行会计运算和内务操作。"}],"oxford":{"phon":"ˈhaʊskiːpɪŋ","pos":"noun","senses":[{"en":"the work involved in taking care of a house, especially shopping and managing money","cn":"家务（尤指采购和管理开支）","ex":{"en":"My financial problems were made worse by my bad housekeeping.","cn":"我持家无方，使得经济状况更加糟糕。"}},{"en":"the department in a hotel, a hospital, an office building, etc. that is responsible for cleaning the rooms, etc.","cn":"（旅馆、医院、写字楼等的）总务处，后勤部","ex":{"en":"Call housekeeping and ask them to bring us some clean towels.","cn":"给总务处打电话，让他们给我们送些干净的毛巾来。"}},{"en":"the money used to buy food, cleaning materials and other things needed for taking care of a house","cn":"家务开支","lab":"especially in British English"},{"en":"jobs that are done to enable an organization or computer system to work well","cn":"内务处理","ex":{"en":"The company has made considerable savings through good housekeeping, such as avoiding wastage.","cn":"公司通过如避免浪费等有效的内部管理方法节约了数量可观的资金。"}}]}},"habitable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可居住的;适宜居住的","en":"If a place is habitable, it is good enough for people to live in.","ex":{"en":"Making the house habitable was a major undertaking.","cn":"把这所房子收拾得可以住人，那可是项大工程。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a building or area of land that is habitable is suitable for people to live in, for example because it is clean enough, warm enough, safe enough etc","cn":""},{"en":"if a building is fit to live in , it is in a suitable condition for people to live in it","cn":""},{"en":"not suitable for living in or on","cn":""}]},"collocations":{"phrases":["VERBS be | remain | make sth, render sth They've done their best to make the house habitable. | consider sth The houses were not considered ","ADV. barely The room was barely habitable."]},"media":{"uk":"media/ldoce/hwd/bre/7/habitable0205.mp3","us":"media/ldoce/hwd/ame/b/habitable.mp3"},"examples":[{"en":"The house should be habitable by the new year.","cn":"房子到新年时应该就可以住进去了。"},{"en":"It would cost a fortune to make the place habitable.","cn":"要想让这个地方可以住人得花一大笔钱。"}],"oxford":{"phon":"ˈhæbɪtəbl","pos":"adjective","senses":[{"en":"suitable for people to live in","cn":"适合居住的","ex":{"en":"The house should be habitable by the new year.","cn":"房子到新年时应该就可以住进去了。"}}]}},"horrific":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（攻击、事故、伤势等）令人震惊的，极其可怕的，十分严重的","en":"If you describe a physical attack, accident, or injury as horrific, you mean that it is very bad, so that people are shocked when they see it or think about it.","ex":{"en":"I have never seen such horrific injuries","cn":"我从来没有见过如此严重的伤势。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大得令人厌恶的","en":"If you describe something as horrific, you mean that it is so big that it is extremely unpleasant.","ex":{"en":"...piling up horrific extra amounts of money on top of your original debt.","cn":"在你原来债务的基础上又高筑债台"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not at all pleasant, enjoyable, or successful","cn":""},{"en":"very bad","cn":""},{"en":"so bad that you are shocked","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something horrific causes horror. It’s disastrous and makes you shudder with fear. Yikes!"}]},"collocations":{"phrases":["VERBS be, look | describe sth as Police described the attack as horrific.","ADV. really | absolutely, quite, truly Some of the scenes we witnessed were quite horrific. | fairly, pretty"]},"media":{"uk":"media/ldoce/hwd/bre/7/horrific0205.mp3","us":"media/ldoce/hwd/ame/3/horrific.mp3"},"examples":[{"en":"a horrific murder/accident/attack, etc.","cn":"骇人听闻的谋杀、事故、攻击等"},{"en":"We had a horrific trip.","cn":"我们的旅行糟糕透顶。"}],"oxford":{"phon":"həˈrɪfɪk","pos":"adjective","senses":[{"en":"extremely bad and making you feel shocked or frightened","cn":"极坏的；令人震惊的；令人惊恐的","ex":{"en":"a horrific murder/accident/attack, etc.","cn":"骇人听闻的谋杀、事故、攻击等"}},{"en":"very bad or unpleasant","cn":"极差的；很不愉快的","lab":"informal","ex":{"en":"We had a horrific trip.","cn":"我们的旅行糟糕透顶。"}}]}},"handkerchief":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手帕","en":"A handkerchief is a small square piece of fabric which you use for blowing your nose."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of cloth that you use for drying your nose or eyes","cn":"手帕"}]},"collocations":{"phrases":["ADJ. clean | crumpled, dirty, grubby, used | pocket | lace, linen, paper, silk | embroidered","VERB + HANDKERCHIEF blow your nose on, use He blew his nose on a grubby handkerchief. | wave"]},"media":{"uk":"media/ldoce/hwd/bre/c/handkerchief0205.mp3","us":"media/ldoce/hwd/ame/7/handkerchief.mp3"},"oxford":{"phon":"ˈhæŋkətʃɪf","pos":"noun","senses":[{"en":"a small piece of material or paper that you use for blowing your nose, etc.","cn":"手帕；纸巾","ex":{"en":"He blew his nose on a dirty handkerchief.","cn":"他用一块脏兮兮的手帕擤鼻涕。"}}]}},"heartbeat":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"心搏;心跳","en":"Your heartbeat is the regular movement of your heart as it pumps blood around your body.","ex":{"en":"Your baby's heartbeat will be monitored continuously.","cn":"宝宝的心搏将会受到持续监控。"}},{"pos":"N-COUNT 可数名词","cn":"（一次）心搏，心跳","en":"A heartbeat is one of the movements of your heart.","ex":{"en":"Smoking could lead to irregular heartbeats.","cn":"吸烟会引起心律失常。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the action or sound of your heart as it pumps blood through your body","cn":"心跳﹐心搏"},{"en":"to be very close to a situation or position 〔","cn":"状态或位置〕非常接近某事物"},{"en":"very quickly, without delay","cn":"一下子"}]},"collocations":{"phrases":["ADJ. irregular, regular | racing She was suddenly aware of her racing heartbeat.","VERB + HEARTBEAT monitor | feel","PHRASES the sound/thud of a heartbeat I could feel the thud of my heartbeat."]},"media":{"uk":"media/ldoce/hwd/bre/0/heartbeat0205.mp3","us":"media/ldoce/hwd/ame/a/heartbeat.mp3"},"examples":[{"en":"The candidate said that he understood the heartbeat of the Hispanic community in California.","cn":"这位候选人说他了解加利福尼亚州的西班牙语裔美国人社区的特点。"},{"en":"If I was offered another job, I'd leave in a heartbeat.","cn":"如果能找到另外一份工作，我马上就走。"}],"oxford":{"phon":"ˈhɑːtbiːt","pos":"noun","senses":[{"en":"the movement or sound of the heart as it sends blood around the body","cn":"心跳；心搏；心跳声","g":"[countable, uncountable]","ex":{"en":"a rapid/regular heartbeat","cn":"急速／正常的心跳"}},{"en":"an important feature of something, that is responsible for making it what it is","cn":"重要特征；中心","g":"[singular]","ex":{"en":"The candidate said that he understood the heartbeat of the Hispanic community in California.","cn":"这位候选人说他了解加利福尼亚州的拉美裔美国人社区的特点。"}}]}},"hip":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"髋;臀部","en":"Your hips are the two areas at the sides of your body between the tops of your legs and your waist.","ex":{"en":"Tracey put her hands on her hips and sighed.","cn":"特蕾西双手叉腰叹了口气。"}},{"pos":"N-COUNT 可数名词","cn":"髋;髋部（指骨骼）","en":"You refer to the bones between the tops of your legs and your waist as your hips ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"新潮的;赶时髦的","en":"If you say that someone is hip, you mean that they are very modern and follow all the latest fashions, for example in clothes and ideas.","ex":{"en":"...a hip young character with tight-cropped blond hair and stylish glasses.","cn":"留着一头毛寸金发、戴着时尚眼镜的时髦青年"}},{"pos":"N-COUNT 可数名词","cn":"野蔷薇果","en":"A hip is a rosehip ."},{"pos":"EXCLAM 感叹语","cn":"（表示欣赏或赞许的呼声）好啊！加油！万岁！","en":"If a large group of people want to show their appreciation or approval of someone, one of them says 'Hip hip' and they all shout 'hooray'."},{"pos":"PHRASE 短语","cn":"鲁莽行事;轻举妄动;信口开河","en":"If you say that someone shoots from the hip or fires from the hip, you mean that they react to situations or give their opinion very quickly, without stopping to think.","ex":{"en":"Judges don't have to shoot from the hip. They have the leisure to think, to decide.","cn":"法官们不必贸然行事。他们可以不慌不忙地去思考，去决定。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two parts on each side of your body between the top of your leg and your waist","cn":"臀部﹔髋部"},{"en":"the red fruit of some kinds of rose s","cn":"蔷薇果（实）"},{"en":"clothes, styles, places or activities that are fashionable are popular at the present time, but will probably only be popular for a short time","cn":""}]},"collocations":{"phrases":["ADJ. lean, narrow Her hips were still narrow like a girl's. | sturdy, wide | broken, dislocated, fractured | arthritic | artificial","VERB + HIP have/put your hands on He put his hands on his hips and sighed. | roll, sway, swing, wiggle She wiggled her hips seductively as s","HIP + VERB spread Her hips had spread since having a baby.","HIP + NOUN fracture, injury | deformity | operation, replacement My grandmother's having a hip replacement. | bone, joint, socket | flask He","PREP. across the ~s She was wearing a short blue dress, belted across the hips. | at the ~ He had his leg amputated at the hip. | from the ~","PHRASES hands on hips He leaned casually against the door frame, hands on hips."]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdehip.mp3","us":"media/ldoce/hwd/ame/1/hip1.mp3"},"examples":[{"en":"‘Three cheers for the bride and groom: Hip, hip … ’ ‘Hooray!’ “","cn":"向新娘和新郎欢呼三声：嘿嘿 … ” “好哪！”"},{"en":"These jeans are too tight around the hips.","cn":"这条牛仔裤的臀部太窄。"}],"oxford":{"phon":"hɪp","pos":"noun","senses":[{"en":"the area at either side of the body between the top of the leg and the middle part of the body; the joint at the top of the leg that connects it with the top part of the body","cn":"臀部；髋","lab":"informal","ex":{"en":"She stood with her hands on her hips.","cn":"她双手叉腰站着。"}},{"en":"having hips of the size or shape mentioned","cn":"臀部…的","ex":{"en":"large-hipped","cn":"臀部大的"}},{"en":"the red fruit that grows on some types of wild rose bush","cn":"野蔷薇果"},{"en":"following or knowing what is fashionable in clothes, music, etc.","cn":"（衣服、音乐等方面）时髦的，赶时髦的","ex":{"en":"He's just trying to be hip!","cn":"他只是想时髦一点！"},"pos":"adjective"}]}},"hypnosis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"催眠状态","en":"Hypnosis is a state in which a person seems to be asleep but can still see, hear, or respond to things said to them.","ex":{"en":"Bevin is now an adult and has relived her birth experience under hypnosis.","cn":"贝文现在是个成年人了，她在催眠状态下重温了自己的出生过程。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"催眠（术）","en":"Hypnosis is the art or practice of hypnotizing people."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a state similar to sleep, in which someone’s thoughts and actions can be influenced by someone else （","cn":"受）催眠状态"},{"en":"the act of producing this state","cn":"催眠（术）"}]},"vocab":{"pos":"n","senses":[{"en":"Hypnosis is a trance-like state induced by a hypnotist in which the subject becomes highly open to suggestions by others. In movies, hypnosis usually starts with the phrase, \"You are feeling very sleepy...\""}]},"collocations":{"phrases":["VERB + HYPNOSIS be given, have, undergo | practise, put sb under I decided to put him under hypnosis and ask him again. | induce | be suscep","HYPNOSIS + NOUN session","PREP. during ~ changes in breathing observed during hypnosis | under ~ the things that people remember under hypnosis"]},"media":{"uk":"media/ldoce/hwd/bre/4/hypnosis0205.mp3","us":"media/ldoce/hwd/ame/7/hypnosis.mp3"},"examples":[{"en":"She only remembered details of the accident under hypnosis.","cn":"她只有在催眠状态下才能记起那次事故的细节。"},{"en":"He uses hypnosis as part of the treatment.","cn":"他用催眠术作为治疗的一部分。"}],"oxford":{"phon":"hɪpˈnəʊsɪs","pos":"noun","senses":[{"en":"an unconscious state in which somebody can still see and hear and can be influenced to follow commands or answer questions","cn":"催眠状态","ex":{"en":"She only remembered details of the accident under hypnosis.","cn":"她只有在催眠状态下才能记起那次事故的细节。"}},{"en":"the practice of hypnotizing a person (= putting them into an unconscious state)","cn":"催眠术；催眠","ex":{"en":"He uses hypnosis as part of the treatment.","cn":"他用催眠术作为治疗的一部分。"}}]}},"honeymoon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（新婚夫妇的）蜜月","en":"A honeymoon is a holiday taken by a man and a woman who have just got married."},{"pos":"VERB 动词","cn":"度蜜月","en":"When a recently-married couple honeymoon somewhere, they go there on their honeymoon.","ex":{"en":"They honeymooned in Venice.","cn":"他们在威尼斯度了蜜月。"}},{"pos":"N-COUNT 可数名词","cn":"（新工作开始或新政府成立后的）和谐时期，蜜月期","en":"You can use honeymoon to refer to a period of time after the start of a new job or new government when everyone is pleased with the person or people concerned and is nice to them.","ex":{"en":"Austrians voted for EU membership by a two-to-one majority in a June 1994 referendum, but the honeymoon is definitely over","cn":"奥地利在1994年6月举行的全民公决中以2比1的多数票支持加入欧盟，但这一蜜月期明显已经结束了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ceremony in which two people get married, especially one with a religious service","cn":""},{"en":"a wedding. Marriage is less common and more formal than wedding","cn":""},{"en":"a large formal meal or party after a wedding","cn":""}]},"collocations":{"phrases":["ADJ. brief, short We had a brief honeymoon in Paris. | long | second After so many years of marriage, we're planning a second honeymoon.","VERB + HONEYMOON go on, have, leave for, spend They go on honeymoon the day after the wedding.","HONEYMOON + VERB be over (usually figurative) The honeymoon was over and the reality of what she had taken on began to dawn.","HONEYMOON + NOUN couple | suite | period (figurative) There was always a honeymoon period when Mum started a new job.","PREP. for a ~ They can't decide where to go for their honeymoon. | on ~ While on honeymoon in Bali, she learned to scuba dive."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdehoneymoon.mp3","us":"media/ldoce/hwd/ame/d/honeymoon1.mp3"},"examples":[{"en":"The honeymoon period for the government is now over.","cn":"这届政府的蜜月期现在已经过去了。"},{"en":"We went to Venice for our honeymoon.","cn":"我们去了威尼斯度蜜月。"}],"oxford":{"phon":"ˈhʌnimuːn","pos":"noun","senses":[{"en":"a holiday taken by a couple who have just got married","cn":"蜜月","ex":{"en":"We went to Venice for our honeymoon.","cn":"我们去威尼斯度的蜜月。"}},{"en":"the period of time at the start of a new activity when nobody is criticized and people feel enthusiastic","cn":"（新活动之初的）和谐时期","ex":{"en":"The honeymoon period for the government is now over.","cn":"这届政府的蜜月期现在已经过去了。"}},{"en":"to spend your honeymoon somewhere","cn":"（去某处）度蜜月","ex":{"en":"They are honeymooning in Paris.","cn":"他们正在巴黎度蜜月。"},"pos":"verb"}]}},"heaven":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"天堂;天国","en":"In some religions, heaven is said to be the place where God lives, where good people go when they die, and where everyone is always happy. It is usually imagined as being high up in the sky.","ex":{"en":"I believed that when I died I would go to heaven and see God.","cn":"我相信自己死后会升入天堂，见到上帝。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"极乐（之地）；天堂般美好（的世界）","en":"You can use heaven to refer to a place or situation that you like very much.","ex":{"en":"We went touring in Wales and Ireland. It was heaven","cn":"我们去了威尔士和爱尔兰旅游。那里真是人间仙境。"}},{"pos":"N-PLURAL 复数名词","cn":"天空","en":"The heavens are the sky.","ex":{"en":"He walked out into the middle of the road, looking up at the heavens.","cn":"他走出去站在大路中间，抬头仰望着天空。"}},{"pos":"PHRASE 短语","cn":"但愿不会这样;千万不要这样;苍天不容;老天不许","en":"You say 'Heaven forbid!' to emphasize that you very much hope that something will not happen.","ex":{"en":"Heaven forbid that he should leave because of me!","cn":"但愿他不会因为我而离开！"}},{"pos":"EXCLAM 感叹语","cn":"（表示惊讶或强调）天哪","en":"You say 'Good heavens!' or 'Heavens!' to express surprise or to emphasize that you agree or disagree with someone.","ex":{"en":"Good Heavens! That explains a lot!","cn":"天哪！这下我明白了！"}},{"pos":"PHRASE 短语","cn":"…只有靠天帮忙了;谁也帮不了…了","en":"You say 'Heaven help someone' when you are worried that something bad is going to happen to them, often because you disapprove of what they are doing or the way they are behaving.","ex":{"en":"If this makes sense to our leaders, then heaven help us all","cn":"如果我们的领导人认为这是合情合理的，那么谁也帮不了我们了。"}},{"pos":"PHRASE 短语","cn":"天知道;谁晓得","en":"You can say 'Heaven knows' to emphasize that you do not know something, or that you find something very surprising.","ex":{"en":"Heaven knows what they put in it.","cn":"天知道他们在里面放了些什么。"}},{"pos":"PHRASE 短语","cn":"确实;一定;无疑","en":"You can say 'Heaven knows' to emphasize something that you feel or believe very strongly.","ex":{"en":"Heaven knows they have enough money","cn":"他们的钱够多了。"}},{"pos":"PHRASE 短语","cn":"想尽一切办法;竭尽全力;千方百计","en":"If you move heaven and earth to do something, you try as hard as you can to do it.","ex":{"en":"They would move heaven and earth to stop me if they could.","cn":"可能的话，他们会千方百计地阻止我。"}},{"pos":"PHRASE 短语","cn":"（用于以 what、when、who、why 及 how 开头的疑问句中表示强调）到底，究竟","en":"You can use in heaven's name in questions beginning with 'what', 'when', 'who', 'why' and 'how' to add emphasis in a way that shows that you are very angry or surprised.","ex":{"en":"Where in heaven's name was she?","cn":"她到底在哪儿？"}},{"pos":"PHRASE 短语","cn":"突然下起倾盆大雨","en":"If the heavens open, it suddenly starts raining very heavily.","ex":{"en":"The match had just begun when the heavens opened and play was suspended.","cn":"比赛刚刚开始就突然下起倾盆大雨，所以只好暂停了。"}},{"pos":"","cn":"","en":"for heaven's sake→see: ; thank heavens→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"say this when you hope that what has just been mentioned will not happen or is not true","cn":""},{"en":"use this to say very strongly that you hope something does not happen or has not happened","cn":""},{"en":"say this when you mean that it is impossible to know something","cn":""}]},"collocations":{"phrases":["VERB + HEAVEN ascend to, go to I feel like I've died and gone to heaven.","PREP. from ~ Our child seemed a gift from heaven. | in ~ (figurative) It was a marriage made in heaven.","PHRASES the kingdom of heaven 2 place/situation in which you are very happy","ADJ. absolute, sheer It was sheer heaven being alone at last.","PREP. in ~ The kids were in absolute heaven at the fair.","PHRASES a heaven on earth The island is truly a heaven on earth. | sb's idea of heaven Building up a tan by the pool with a good book is my "]},"media":{"uk":"media/ldoce/hwd/bre/d/heaven0205.mp3","us":"media/ldoce/hwd/ame/7/heaven1.mp3"},"examples":[{"en":"I feel like I've died and gone to heaven.","cn":"我彷佛觉得自己已经死了，进了天堂。"},{"en":"It was heaven being away from the office for a week.","cn":"一个星期远离办公室真是快活极了。"}],"oxford":{"phon":"ˈhevn","pos":"noun","senses":[{"en":"the place believed to be the home of God where good people go when they die, sometimes imagined to be in the sky","cn":"天堂；天国","g":"[uncountable]","ex":{"en":"the kingdom of heaven","cn":"天国"}},{"en":"a place or situation in which you are very happy","cn":"极乐之地；极乐","g":"[uncountable, countable]","lab":"informal","ex":{"en":"This isn't exactly my idea of heaven!","cn":"这可不太像我所想象的那么美妙！"}},{"en":"the sky","cn":"天空","g":"[plural]","lab":"literary","ex":{"en":"Four tall trees stretched up to the heavens.","cn":"四棵大树参天而立。"}}]}},"harmless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无害的;（尤指对健康）不造成伤害的","en":"Something that is harmless does not have any bad effects, especially on people's health.","ex":{"en":"Industry has been working at developing harmless substitutes for these gases","cn":"该行业一直在努力开发一些可以替代这些气体的无害物质。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无关紧要的;不讨人厌的;不会惹麻烦的","en":"If you describe someone or something as harmless, you mean that they are not important and therefore unlikely to annoy other people or cause trouble.","ex":{"en":"He seemed harmless enough","cn":"他看起来不会惹什么麻烦。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not harmful - use this especially when people have said or believe that something or someone is harmful","cn":""},{"en":"if an action, activity, experience etc does no harm , it does not harm someone or something and may even help","cn":""},{"en":"used especially about products in shops, meaning that they do not harm the environment etc","cn":""}]},"collocations":{"phrases":["VERBS appear, be, look, seem, sound | make sth, render sth chemical wastes which have to be rendered harmless | consider sth","ADV. absolutely, completely, perfectly, quite, totally | almost, virtually | enough He looks harmless enough. | comparatively, fairly, prett","PREP. to The substance is harmless to people."]},"media":{"uk":"media/ldoce/hwd/bre/9/harmless0205.mp3","us":"media/ldoce/hwd/ame/c/harmless.mp3"},"examples":[{"en":"The missile fell harmlessly into the sea.","cn":"导弹落到了海里，没有造成任何伤害。"},{"en":"It's just a bit of harmless fun.","cn":"开个小玩笑罢了，并无恶意的。"}],"oxford":{"phon":"ˈhɑːmləs","pos":"adjective","senses":[{"en":"unable or unlikely to cause damage or harm","cn":"无害的；不会导致损伤的","ex":{"en":"The bacteria is harmless to humans.","cn":"这种细菌对人类无害。"}},{"en":"unlikely to upset or offend anyone","cn":"不会引起不快的；无恶意的","ex":{"en":"It's just a bit of harmless fun.","cn":"开个小玩笑罢了，并无恶意的。"}}]}},"headache":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"头痛","en":"If you have a headache, you have a pain in your head.","ex":{"en":"I have had a terrible headache for the last two days.","cn":"两天来我一直头痛得厉害。"}},{"pos":"N-COUNT 可数名词","cn":"使人头痛的事;棘手的事;难题","en":"If you say that something is a headache, you mean that it causes you difficulty or worry.","ex":{"en":"The airline's biggest headache is the increase in the price of aviation fuel","cn":"令航空公司最头痛的事就是航空燃料价格的上涨。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pain in your head","cn":"头痛"},{"en":"a headache and feeling of sickness that you get the day after you have drunk too much alcohol","cn":"宿醉"},{"en":"a very bad headache, which makes you feel sick and have difficulty seeing","cn":"偏头痛"}]},"vocab":{"pos":"n","senses":[{"en":"A headache is a pain or ache in your head, especially one that lasts longer than a few minutes. You might get a headache after a day of staring at a computer screen."}]},"collocations":{"phrases":["ADJ. bad, severe, terrible, violent | mild, slight | dull | pounding, splitting, throbbing | migraine, tension He developed a sever e migrai","VERB + HEADACHE have, suffer from I've got a splitting headache. | get, develop We all get headaches from time to time. | complain of The wo","HEADACHE + NOUN pill, tablet •","ADJ. big, major, real | constant","PREP. ~ for Uneven cash flo w proved to be a major headache for the company."]},"media":{"uk":"media/ldoce/hwd/bre/d/headache0205.mp3","us":"media/ldoce/hwd/ame/f/headache.mp3"},"examples":[{"en":"The real headache will be getting the bank to lend you the money.","cn":"真正的麻烦将是设法让银行贷款给你。"},{"en":"Red wine gives me a headache.","cn":"我喝红酒会头痛。"}],"oxford":{"phon":"ˈhedeɪk","pos":"noun","senses":[{"en":"a continuous pain in the head","cn":"头痛","lab":"British English","ex":{"en":"He had a terrible headache.","cn":"他头痛得厉害。"}},{"en":"a person or thing that causes worry or trouble","cn":"令人头痛的人（或事物）；麻烦","lab":"informal","ex":{"en":"The real headache will be getting the bank to lend you the money.","cn":"真正的麻烦将是设法让银行贷款给你。"}}]}},"hymn":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（基督教的）赞美诗，圣歌","en":"A hymn is a religious song that Christians sing in church.","ex":{"en":"I like singing hymns.","cn":"我喜欢唱圣歌。"}},{"pos":"N-COUNT 可数名词","cn":"歌颂;赞美","en":"If you describe a film, book, or speech as a hymn to something, you mean that it praises or celebrates that thing.","ex":{"en":"...a hymn to freedom and rebellion","cn":"对自由和反抗的赞颂"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the official song of a country, which is sung or played on public occasions","cn":""},{"en":"a religious song that is sung in a church","cn":""},{"en":"a traditional Christmas song","cn":""}]},"collocations":{"phrases":["ADJ. rousing The service began with a rousing hymn. | traditional | modern","VERB + HYMN play, sing","HYMN + NOUN book | tune"]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdehymn.mp3","us":"media/ldoce/hwd/ame/a/him.mp3"},"examples":[{"en":"He liked to sing hymns as he worked.","cn":"他工作时喜欢唱赞美诗。"},{"en":"Their first single was a hymn to selfishness called ‘Looking After Number One’.","cn":"他们的第一首单曲颂扬利己﹐名为《珍惜自我》。"}],"oxford":{"phon":"hɪm","pos":"noun","senses":[{"en":"a religious song of praise to God or a god, especially one sung by Christians in church","cn":"赞美诗，圣歌（尤指基督徒唱的颂扬上帝的歌）","ex":{"en":"The service began with a rousing hymn.","cn":"礼拜仪式开始时先唱了一首令人心潮澎湃的赞美诗。"}},{"en":"if a film, book, etc. is a hymn to something, it praises it very strongly","cn":"歌颂某事物的电影（或书等）","g":"[usually singular]"}]}},"hostage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人质","en":"A hostage is someone who has been captured by a person or organization and who may be killed or injured if people do not do what that person or organization demands.","ex":{"en":"It is hopeful that two hostages will be freed in the next few days.","cn":"有两名人质可望在几天后获释。"}},{"pos":"PHRASE 短语","cn":"被扣作人质","en":"If someone is taken hostage or is held hostage, they are captured and kept as a hostage.","ex":{"en":"He was taken hostage while on his first foreign assignment as a television journalist.","cn":"他第一次作为电视记者出国采访时就被扣作人质。"}},{"pos":"N-VAR 可变名词","cn":"受限制的人;不由自主的人","en":"If you say you are hostage to something, you mean that your freedom to take action is restricted by things that you cannot control.","ex":{"en":"With the reduction in foreign investments, the government will be even more a hostage to the whims of the international oil price","cn":"随着外资的减少，政府将更加受制于起伏不定的国际油价。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is kept in a prison as a punishment for a crime, or while they are waiting for their trial","cn":""},{"en":"someone who has been found guilty of a crime and sent to a prison. Convict is used especially about someone who is sent to prison for a long time. It is more commonly used in historical descriptions, or in the phrase an escaped convict","cn":""},{"en":"someone who is kept in a prison or a mental hospital","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A hostage is a prisoner taken by kidnappers and held until the kidnappers get whatever they’re asking for. If you refuse to empty the litter box, your roommate might take your cat as a hostage until you clean it."}]},"collocations":{"phrases":["VERB + HOSTAGE hold (sb) Eight people were held hostage for four months. | seize, take (sb) The gunmen took 24 hostages. | free, release, se"]},"media":{"uk":"media/ldoce/hwd/bre/e/hostage0205.mp3","us":"media/ldoce/hwd/ame/8/hostage.mp3"},"examples":[{"en":"Three children were taken hostage during the bank robbery.","cn":"在银行抢劫案中有三名儿童被扣为人质。"},{"en":"The government is negotiating the release of the hostages.","cn":"政府正就释放人质进行谈判。"}],"oxford":{"phon":"ˈhɒstɪdʒ","pos":"noun","senses":[{"en":"a person who is captured and held prisoner by a person or group, and who may be injured or killed if people do not do what the person or group is asking","cn":"人质","ex":{"en":"Three children were taken hostage during the bank robbery.","cn":"在银行抢劫案中有三名儿童被扣为人质。"}}]}},"hepatitis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"肝炎","en":"Hepatitis is a serious disease which affects the liver."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a disease of the liver that causes fever and makes your skin yellow. There are several types of hepatitis: hepatitis A, which is less severe, and hepatitis B and C, which are much more serious.","cn":"肝炎"}]},"collocations":{"phrases":["ADJ. severe | acute, chronic | active | viral","VERB + HEPATITIS have, suffer from | be infected with, contract, get","HEPATITIS + NOUN virus | patient","PHRASES hepatitis A/B/C •"]},"media":{"uk":"media/ldoce/hwd/bre/e/hepatitis0205.mp3","us":"media/ldoce/hwd/ame/f/hepatitis.mp3"},"oxford":{"phon":"ˌhepəˈtaɪtɪs","pos":"noun","senses":[{"en":"a serious disease of the liver. There are three main forms: hepatitis A, the least serious, caused by infected food (= containing harmful bacteria), and hepatitis B and hepatitis C, both very serious and caused by infected blood.","cn":"肝炎","ex":{"en":"Have you had your hepatitis B vaccination?","cn":"你接种过乙肝疫苗吗？"}}]}},"horace":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"(65–8 BC) a Roman poet and writer of satire (= literature making fun of stupid or evil people ) , whose work greatly influenced English poetry. His full Latin name was Quintus Horatius Flaccus.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/p028-000006209.mp3","us":"media/ldoce/hwd/ame/9/p028-000006209.mp3"},"oxford":{"phon":"ˈhɒrəs","pos":"","senses":[{"en":"a first name for boys","cn":"贺拉斯（男子名）"}]}},"hitch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（短暂的）小故障，小障碍","en":"A hitch is a slight problem or difficulty which causes a short delay.","ex":{"en":"After some technical hitches the show finally got under way","cn":"一些小技术故障解决后，演出终于开始了。"}},{"pos":"VERB 动词","cn":"搭便车（旅行）；搭顺风车","en":"If you hitch ,hitch a lift, or hitch a ride, you hitchhike.","ex":{"en":"There was no garage in sight, so I hitched a lift into town","cn":"放眼望去看不到修车厂，所以我就搭顺风车进了城。"}},{"pos":"VERB 动词","cn":"把…钩（或拴、系）在…上","en":"If you hitch something to something else, you hook it or fasten it there.","ex":{"en":"Last night we hitched the horse to the cart and moved here.","cn":"昨晚我们套上马车，拉着东西搬到了这里。"}},{"pos":"PHRASE 短语","cn":"结婚","en":"If you get hitched, you get married.","ex":{"en":"The report shows that fewer couples are getting hitched.","cn":"报告显示，结婚的人数呈下降趋势。"}},{"pos":"","cn":"","en":"相关词组：hitch up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get free rides from the drivers of passing cars by standing at the side of the road and putting a hand out with the thumb raised","cn":"搭便车﹐免费搭〔车〕"},{"en":"to move a piece of clothing you are wearing so that it is higher than it was before","cn":"把〔衣物〕向上拉"},{"en":"to get married","cn":"结婚"}]},"vocab":{"pos":"1 v n 2 n 3 v 4 v n ","senses":[{"en":"A hitch is an obstacle or hindrance. You might be late because of a last minute hitch , like waiting for a family of ducks to cross the road. If things go well, they go off without a hitch ."}]},"collocations":{"phrases":["ADJ. slight | last-minute There are always a few last-minute hitches at the dress rehearsal. | legal, technical There was a slight technical","PREP. without a ~ Everything went without a hitch. | ~ in There's been a hitch in the plans."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdehitch.mp3","us":"media/ldoce/hwd/ame/7/hitch1.mp3"},"examples":[{"en":"We spent the summer hitching around Europe.","cn":"我们藉搭便车在欧洲各地旅行了一个夏天。"},{"en":"They hitched a ride in a truck.","cn":"他们搭乘了一辆路过的货车。"}],"oxford":{"phon":"hɪtʃ","pos":"verb","senses":[{"en":"to get a free ride in a person’s car; to travel around in this way, by standing at the side of the road and trying to get passing cars to stop","cn":"免费搭车；搭便车","g":"[transitive, intransitive]","lab":"British English also","ex":{"en":"They hitched a ride in a truck.","cn":"他们搭乘了一辆路过的货车。"}},{"en":"to pull up a piece of your clothing","cn":"提起，拉起（衣服）","g":"[transitive]","ex":{"en":"She hitched up her skirt and waded into the river.","cn":"她提起裙子，蹚进河里。"}},{"en":"to lift yourself into a higher position, or the position mentioned","cn":"攀上；跃上","g":"[transitive]","ex":{"en":"She hitched herself up.","cn":"她爬了上去。"}},{"en":"to tie or fasten something to something else with a rope, a hook, etc.","cn":"拴住；套住；钩住","g":"[transitive]","ex":{"en":"She hitched the pony to the gate.","cn":"她把小马拴在大门上。"}},{"en":"a problem or difficulty that causes a short delay","cn":"暂时的困难（或问题）；故障；障碍","ex":{"en":"The ceremony went off without a hitch.","cn":"仪式进行得很顺利。"},"pos":"noun"},{"en":"a type of knot (= a join made by tying together two pieces or ends of rope, etc.)","cn":"（某种）结","ex":{"en":"a clove hitch","cn":"双套结"},"pos":"noun"}]}},"homeland":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"祖国","en":"Your homeland is your native country.","ex":{"en":"Many are planning to return to their homeland.","cn":"很多人正计划回到自己的祖国去。"}},{"pos":"N-COUNT 可数名词","cn":"“黑人家园”（指过去南非种族隔离制度下的黑人有一定自治权的地区）","en":"The homelands were regions within South Africa in which black South Africans had a limited form of self-government."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the country where someone was born","cn":"祖国﹐家乡"},{"en":"a large area of land where a particular group of people can live 〔","cn":"某一群人的〕定居点﹐聚居地"}]},"collocations":{"phrases":["ADJ. beloved They were devastated that they had to leave their beloved homeland. | ancient, traditional the struggle to defend their ancient","VERB + HOMELAND flee, leave During the war, they were forced to flee their homeland. | go back to, return to, visit He longs to return to hi","PREP. in a/sb's ~ They hope to remain in their homeland."]},"media":{"uk":"media/ldoce/hwd/bre/f/homeland0205.mp3","us":"media/ldoce/hwd/ame/2/homeland.mp3"},"examples":[{"en":"Many refugees have been forced to flee their homeland.","cn":"很多难民被迫逃离了祖国。"},{"en":"the Transkei homeland","cn":"特兰斯凯黑人定居地"}],"oxford":{"phon":"ˈhəʊmlænd","pos":"noun","senses":[{"en":"the country where a person was born","cn":"祖国；家乡","g":"[usually singular]","ex":{"en":"Many refugees have been forced to flee their homeland.","cn":"很多难民被迫逃离了祖国。"}},{"en":"(in the Republic of South Africa under the apartheid system in the past) one of the areas with some self-government that were intended for a group of black African people to live in","cn":"（南非共和国过去在种族隔离制度下设立、有一定自治权的）黑人定居地","ex":{"en":"the Transkei homeland","cn":"特兰斯凯黑人定居地"}}]}},"hamper":{"collins":{"senses":[{"pos":"VERB 动词","cn":"妨碍;阻碍;牵制;束缚","en":"If someone or something hampers you, they make it difficult for you to do what you are trying to do.","ex":{"en":"The bad weather hampered rescue operations","cn":"恶劣的天气阻碍了救援工作的进行。"}},{"pos":"N-COUNT 可数名词","cn":"（装有各种食品的）礼物篮","en":"A hamper is a basket containing food of various kinds that is given to people as a present.","ex":{"en":"...a luxury food hamper.","cn":"豪华食品礼物篮"}},{"pos":"N-COUNT 可数名词","cn":"（尤指装食品用的）带盖大篮","en":"A hamper is a large basket with a lid, used especially for carrying food in.","ex":{"en":"...a picnic hamper.","cn":"野餐篮子"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make it very difficult for an activity or plan to continue successfully","cn":""},{"en":"to cause problems and therefore delay the development or progress of something","cn":""},{"en":"to make progress or the development of something slower or more difficult","cn":""}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"Use the verb hamper to describe an action that slows progress or makes it difficult to do something, like the presence of your parents that hamper your ability to look cool at the mall."}]},"collocations":{"phrases":["ADV. badly, greatly, seriously, severely Rescue efforts were severely hampered by the bad weather. | further"]},"media":{"img":["media/ldoce/img/picnic.jpg"],"uk":"media/ldoce/hwd/bre/a/hamper_n0205.mp3","us":"media/ldoce/hwd/ame/9/hamper1.mp3"},"examples":[{"en":"a Christmas hamper","cn":"圣诞礼品盒"},{"en":"a picnic hamper","cn":"野餐篮"}],"oxford":{"phon":"ˈhæmpə(r)","pos":"verb","senses":[{"en":"to prevent somebody from easily doing or achieving something","cn":"妨碍；阻止；阻碍","ex":{"en":"High winds hampered the rescue attempt.","cn":"大风阻碍了救援行动。"}},{"en":"a large basket with a lid (= cover), especially one used to carry food in","cn":"（尤指用于盛食物的）带盖大篮子","ex":{"en":"a picnic hamper","cn":"野餐篮"},"pos":"noun"},{"en":"a box or package containing food, sent as a gift","cn":"（作为礼品的）盒装食物，袋装食物","lab":"especially British English","ex":{"en":"a Christmas hamper","cn":"圣诞礼品盒"},"pos":"noun"},{"en":"a large basket that you keep your dirty clothes in until they are washed","cn":"盛脏衣服的大篮子","lab":"North American English","pos":"noun"}]}},"herring":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"鲱（鱼）","en":"A herring is a long silver-coloured fish. Herring live in large groups in the sea."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin silver sea fish that can be eaten","cn":"鲱鱼"}]},"collocations":{"phrases":["ADJ. fresh | pickled, salted, smoked, soused","VERB + HERRING catch | eat, have","HERRING + NOUN fillet •"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeherring.mp3","us":"media/ldoce/hwd/ame/9/herring.mp3"},"examples":[{"en":"fresh herring fillets","cn":"新鲜鲱鱼片"},{"en":"pickled herrings","cn":"腌制的鲱鱼"}],"oxford":{"phon":"ˈherɪŋ","pos":"noun","senses":[{"en":"a N Atlantic fish that swims in very large groups and is used for food","cn":"鲱鱼（产于北大西洋，成大群游动，可食）","ex":{"en":"shoals of herring","cn":"鲱鱼群"}}]}},"hazardous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指对健康或安全）有危险的，有危害的","en":"Something that is hazardous is dangerous, especially to people's health or safety.","ex":{"en":"They have no way to dispose of the hazardous waste they produce","cn":"他们没有办法处理掉自己产生的有害废料。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"likely to cause death or serious harm, or cause something bad to happen","cn":""},{"en":"if something is risky, something bad could easily happen or you could easily make a mistake","cn":""},{"en":"dangerous – used especially about substances, jobs, and journeys","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"The noun \"hazard\" means something dangerous, and the adjective hazardous refers to anything that involves danger. A golf course with lots of sand traps is especially hazardous for golfers. That's why those traps are called hazards."}]},"collocations":{"phrases":["VERBS be, prove | become | consider sth","ADV. extremely, highly, particularly, very | rather, somewhat | potentially burning potentially hazardous medical waste | environmentally en","PREP. for These conditions are very hazardous for shipping. | to chemicals that are hazardous to human beings"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41hazardous.mp3","us":"media/ldoce/hwd/ame/a/hazardous.mp3"},"examples":[{"en":"a list of products that are potentially hazardous to health","cn":"对健康有潜在危害的产品清单"},{"en":"It would be hazardous to invest so much.","cn":"投资这么多会有风险。"}],"oxford":{"phon":"ˈhæzədəs","pos":"adjective","senses":[{"en":"involving risk or danger, especially to somebody’s health or safety","cn":"危险的；有害的","ex":{"en":"hazardous waste/materials/substances/chemicals","cn":"有害废物／物料／物质／化学品"}}]}},"hyundai":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a group of companies based in South Korea which makes cars, ships and electronic products. Its activities also include construction (= building things such as houses, bridges, roads etc ) , providing financial services, and retail ing (= selling goods to custo","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/lpd_hyundai.mp3","us":"media/ldoce/hwd/ame/b/lpd_hyundai.mp3"}},"hiv":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"人类免疫缺陷病毒;艾滋病病毒","en":"HIV is a virus which reduces people's resistance to illness and can cause AIDS. HIV is an abbreviation for (缩略=) 'hu-man immunodeficiency virus'."},{"pos":"PHRASE 短语","cn":"艾滋病病毒检测呈阳性的/阴性的","en":"If someone is HIV positive, they are infected with the HIV virus, and may develop AIDS. If someone is HIV negative, they are not infected with the virus."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of virus (= a very small living thing that causes disease ) that enters the body through blood or sexual activity, and can develop into AIDS","cn":"人类免疫缺陷病毒﹐艾滋病病毒"}]},"collocations":{"phrases":["VERB + HIV be at risk from | contract, get | have, suffer from people suffering from HIV and Aids | be affected by, be infected by | spread,","HIV + NOUN infection | antibody, virus | carrier, sufferer | status If you are unsure of your HIV status, consider having a test. | test","PHRASES HIV negative/positive •"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdehiv.mp3","us":"media/ldoce/hwd/ame/7/hiv.mp3"},"examples":[{"en":"to be HIV-positive/HIV-negative (= to have had a medical test which shows that you are/are not infected with HIV)","cn":"人体免疫缺损病毒检测呈阳性/阴性反应"},{"en":"to be infected with HIV","cn":"染上艾滋病病毒"}],"oxford":{"phon":"ˌeɪtʃ aɪ ˈviː","pos":"noun","senses":[{"en":"the virus that can cause AIDS (the abbreviation for ‘human immunodeficiency virus’)","cn":"人类免疫缺陷病毒，艾滋病病毒（全写为 human immunodeficiency virus）","ex":{"en":"to have HIV","cn":"感染艾滋病毒"}}]}},"himalayas":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a long range of mountains in southern Asia which includes the highest mountain in the world, Mount everest , and other mountains which only very experienced climbers try to climb","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000006080.mp3","us":"media/ldoce/hwd/ame/7/p028-000006080.mp3"}},"hum":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出连续而低沉的声音;发嗡嗡声","en":"If something hums, it makes a low continuous noise.","ex":{"en":"The birds sang, the bees hummed","cn":"鸟儿叫，蜂儿鸣。"}},{"pos":"VERB 动词","cn":"哼（曲子）","en":"When you hum a tune, you sing it with your lips closed.","ex":{"en":"She was humming a merry little tune","cn":"她哼着一支欢快的小曲儿。"}},{"pos":"VERB 动词","cn":"(地方）热闹，活跃，繁忙","en":"If you say that a place hums, you mean that it is full of activity.","ex":{"en":"The place is really beginning to hum","cn":"这个地方真正开始热闹起来了。"}},{"pos":"CONVENTION 惯用语","cn":"（踌躇时发出的声音）嗯，呃","en":"Hum is sometimes used to represent the sound people make when they are not sure what to say.","ex":{"en":"Hum, I am sorry but I thought you were French.","cn":"嗯，很抱歉，我以为你是法国人。"}},{"pos":"See also:","cn":"","en":"hum and haw→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make musical sounds with your voice, but with your mouth closed","cn":""},{"en":"to make musical sounds by blowing air out between your lips","cn":""},{"en":"to make a continuous sound, for example, like the sound made by bees","cn":""}]},"collocations":{"phrases":["ADV. quietly, softly | happily | tunelessly | along humming along with the music","VERB + HUM begin to He began to hum, somewhat tunelessly.","PHRASES hum to yourself She was humming softly to herself."]},"media":{"uk":"media/ldoce/hwd/bre/d/hum_v0205.mp3","us":"media/ldoce/hwd/ame/4/hum.mp3"},"examples":[{"en":"The room filled with the hum of conversation.","cn":"房间里充满了嘈杂的谈话声。"},{"en":"She was humming softly to herself.","cn":"她在轻声哼着曲子。"}],"oxford":{"phon":"hʌm","pos":"verb","senses":[{"en":"to sing a tune with your lips closed","cn":"哼（曲子）","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"She was humming softly to herself.","cn":"她在轻声哼着曲子。"}},{"en":"to make a low continuous sound","cn":"发嗡嗡声","g":"[intransitive]","ex":{"en":"The computers were humming away.","cn":"计算机在嗡嗡作响。"}},{"en":"to be full of activity","cn":"活跃；繁忙","g":"[intransitive]","ex":{"en":"The streets were beginning to hum with life.","cn":"街道开始热闹起来。"}},{"en":"a low continuous sound","cn":"嗡嗡声；嘈杂声","ex":{"en":"the hum of bees/traffic/voices","cn":"蜜蜂的嗡嗡声；车辆的呜呜声；人的嘈杂声"},"pos":"noun"}]}},"halve":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"把…减半;减到一半","en":"When you halve something or when it halves, it is reduced to half its previous size or amount.","ex":{"en":"Dr Lee believes that men who exercise can halve their risk of cancer of the colon","cn":"李医生相信，锻炼身体能使患结肠癌的风险降低一半。"}},{"pos":"VERB 动词","cn":"将…对半分;把…二等分","en":"If you halve something, you divide it into two equal parts.","ex":{"en":"Halve the pineapple and scoop out the inside.","cn":"将菠萝对半切开，挖出里面的果肉。"}},{"pos":"","cn":"（half 的复数）","en":"Halves is the plural of half."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something less in amount or level","cn":""},{"en":"to reduce an amount, limit, or level - use this especially in writing about business or technical subjects","cn":""},{"en":"to reduce something by a lot, especially prices, time, or money","cn":""}]},"collocations":{"phrases":["ADV. more than | almost, nearly, virtually | approximately, roughly | effectively","PREP. in The shares have more than halved in value since the summer high of 572p. | to Overall operating profits halved to $24 million."]},"media":{"uk":"media/ldoce/hwd/bre/0/halve0205.mp3","us":"media/ldoce/hwd/ame/9/halve.mp3"},"examples":[{"en":"The company is halving its prices.","cn":"该公司正将产品半价出售。"},{"en":"The shares have halved in value.","cn":"股价已经跌了一半。"}],"oxford":{"phon":"hɑːv","pos":"verb","senses":[{"en":"to reduce by a half; to make something reduce by a half","cn":"（使）减半","g":"[intransitive, transitive]","ex":{"en":"The shares have halved in value.","cn":"股价已经跌了一半。"}},{"en":"to divide something into two equal parts","cn":"平分；把…对半分","g":"[transitive]"}]}},"heirloom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"祖传遗物;传家宝","en":"An heirloom is an ornament or other object that has belonged to a family for a very long time and that has been handed down from one generation to another."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a valuable object that has been owned by a family for many years and that is passed from the older members to the younger members","cn":"传家宝﹐祖传之宝"},{"en":"an heirloom vegetable or plant is one of a kind that was first grown many years ago, and has now become rare or unusual 〔","cn":"蔬菜或植物〕珍稀的﹐不常见的"}]},"vocab":{"pos":"n","senses":[{"en":"An heirloom is something passed down in a family for generations. Your grandma's prized necklace could be an heirloom ."}]},"collocations":{"phrases":["ADJ. family | ancient","HEIRLOOM + VERB be passed down, come down The brooch is a family heirloom which came down to her from her great-grandmother."]},"media":{"uk":"media/ldoce/hwd/bre/c/heirloom0205.mp3","us":"media/ldoce/hwd/ame/7/heirloom.mp3"},"examples":[{"en":"a family heirloom","cn":"传家宝"},{"en":"They sell many kinds of heirloom seeds.","cn":"他们出售各种稀有种子。"}],"oxford":{"phon":"ˈeəluːm","pos":"noun","senses":[{"en":"a valuable object that has belonged to the same family for many years","cn":"传家宝；世代相传之物","ex":{"en":"a family heirloom","cn":"传家宝"}},{"en":"heirloom plants are varieties that were commonly grown in the past but are no longer grown as commercial crops","cn":"（植物）原种的（指过去很常见，但如今已不再作为经济作物而种植的品种）","pos":"adjective"}]}},"holder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拥有人;持有人","en":"A holder is someone who owns or has something.","ex":{"en":"This season the club has had 73,500 season-ticket holders.","cn":"本赛季该俱乐部已经有73,500名持有季票的观众。"}},{"pos":"N-COUNT 可数名词","cn":"盛放器;支托物","en":"A holder is a container in which you put an object, usually in order to protect it or to keep it in place.","ex":{"en":"...a toothbrush holder.","cn":"牙刷托"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who owns or controls something","cn":"拥有人﹐持有人"},{"en":"something that is used to hold an object","cn":"支托物"}]},"collocations":{"phrases":["ADJ. licence, passport, ticket Only ticket holders will be allowed into the ground. | account, credit card, policy Account holders with the "]},"media":{"uk":"media/ldoce/hwd/bre/1/holder0205.mp3","us":"media/ldoce/hwd/ame/7/l3holder.mp3"},"examples":[{"en":"the current holder of the world record","cn":"目前的世界纪录保持者"},{"en":"the holder of a French passport","cn":"持有法国护照者"}],"oxford":{"phon":"ˈhəʊldə(r)","pos":"noun","senses":[{"en":"a person who has or owns the thing mentioned","cn":"持有者；拥有者","ex":{"en":"a licence holder","cn":"执照持有人"}},{"en":"a thing that holds the object mentioned","cn":"支托（或握持）…之物","ex":{"en":"a pen holder","cn":"笔筒"}}]}},"homosexual":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同性恋的;同性性欲的","en":"A homosexual relationship is a sexual relationship between people of the same sex."},{"pos":"ADJ 形容词","cn":"（人）同性恋性向的","en":"Someone who is homosexual is sexually attracted to people of the same sex.","ex":{"en":"A fraud trial involving two homosexual lawyers was abandoned.","cn":"一桩涉及两名同性恋律师的欺诈案审判被撤销了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sexually attracted to people of the same sex","cn":""},{"en":"a woman who is sexually attracted to other women","cn":""},{"en":"sexually attracted to people of the same sex","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Homosexual is a noun and adjective. Either way, it has to do with people who are attracted to members of the same sex."}]},"collocations":{"phrases":["ADJ. practising | closet, repressed | female, male","VERB + HOMOSEXUAL come out as He came out as a homosexual after his mother died.","HOMOSEXUAL + VERB come out of the closet","PHRASES discrimination against homosexuals"]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41homosexual.mp3","us":"media/ldoce/hwd/ame/b/homosexual.mp3"},"examples":[{"en":"a practising homosexual","cn":"有同性恋行为的人"},{"en":"a homosexual act/relationship","cn":"同性恋行为/关系"}],"oxford":{"phon":"ˌhəʊməˈsekʃuəl","pos":"adjective","senses":[{"en":"sexually attracted to people of the same sex; showing this","cn":"同性恋者（通常指男性）","ex":{"en":"a homosexual act/relationship","cn":"同性恋行为／关系"}},{"en":"a person, usually a man, who is sexually attracted to people of the same sex","cn":"同性恋者（通常指男性）","ex":{"en":"He came out as a homosexual after his mother died.","cn":"他在母亲死后公开承认自己是同性恋者。"},"pos":"noun"}]}},"herb":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（调味或药用的）芳草;香草;药草","en":"A herb is a plant whose leaves are used in cooking to add flavour to food, or as a medicine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a living thing that has leaves and roots and grows in earth, especially one that is smaller than a tree","cn":""},{"en":"a small plant that is used to improve the taste of food, or to make medicine","cn":"香草﹔药草"},{"en":"a wild plant growing where it is not wanted that prevents crops or garden flowers from growing properly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"What do food, medicine, and perfume have in common? Well, they all can be created from herbs . An herb is a plant that has a soft rather than a woody stem, and it tends to have a unique taste or smell."}]},"collocations":{"phrases":["ADJ. dried, fresh | mixed Add a teaspoonful of mixed herbs. | aromatic, fragrant | culinary, medicinal","QUANT. bunch","VERB + HERB garnish sth with Serve cold, garnished with fresh herbs.","HERB + NOUN bed, border, garden •"]},"media":{"uk":"media/ldoce/hwd/bre/e/herb0205.mp3","us":"media/ldoce/hwd/ame/5/herb.mp3"},"examples":[{"en":"( NAmE ) an herb garden","cn":"芳草园"},{"en":"a herb garden","cn":"芳草园"}],"oxford":{"phon":"hɜːb","pos":"noun","senses":[{"en":"a plant whose leaves, flowers or seeds are used to add taste to food, in medicines or for their pleasant smell. parsley, mint and oregano are all herbs.","cn":"药草；香草","lab":"North American English","ex":{"en":"a herb garden","cn":"芳草园"}},{"en":"a plant with a soft stem that dies down after flowering","cn":"草本","lab":"specialist"},{"en":"a first name for boys, short for Herbert","cn":"赫布（男子名，Herbert缩写）","pos":""}]}},"hassle":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"麻烦;困难;争吵","en":"A hassle is a situation that is difficult and involves problems, effort, or arguments with people.","ex":{"en":"I don't think it's worth the money or the hassle","cn":"我认为不值得为此花费那么多金钱和精力。"}},{"pos":"VERB 动词","cn":"烦扰;纠缠","en":"If someone hassles you, they cause problems for you, often by repeatedly telling you or asking you to do something, in an annoying way.","ex":{"en":"Then my husband started hassling me","cn":"然后我丈夫开始不停地烦我。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a problem that stops you from making progress","cn":""},{"en":"a problem, especially one that you had not expected","cn":""},{"en":"a small problem that delays or prevents something","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Something that is bothersome or annoying can be called a hassle . It's a huge hassle to go back to the grocery story after unloading fifteen bags and realizing you forgot milk."}]},"collocations":{"phrases":["ADJ. legal They faced interminable legal hassles if they wanted to claim compensation.","VERB + HASSLE get, have I started to get all this hassle from my boss about increasing productivity. | give sb He gave me so much hassle I d","PREP. with no/without ~ She got the computer set up with no hassle at all. | ~ about/over I've had so much hassle over this business.","PHRASES take the hassle out of sth Package holidays take all the hassle out of travel arrangements."]},"media":{"uk":"media/ldoce/hwd/bre/8/hassle_n0205.mp3","us":"media/ldoce/hwd/ame/a/hassle1.mp3"},"examples":[{"en":"Send them an email — it's a lot less hassle than phoning.","cn":"给他们发个电邮吧，这比打电话省事多了。"},{"en":"Do as you're told and don't give me any hassle!","cn":"告诉你怎么做就怎么做，别跟我顶嘴！"}],"oxford":{"phon":"ˈhæsl","pos":"noun","senses":[{"en":"a situation that is annoying because it involves doing something difficult or complicated that needs a lot of effort","cn":"困难；麻烦","ex":{"en":"It’s a hassle having to travel with so many bags.","cn":"要带着这么多大包小包去旅行，真麻烦。"}},{"en":"a situation in which people disagree, argue or annoy you","cn":"分歧；争论；烦恼","lab":"North American English","ex":{"en":"Do as you're told and don't give me any hassle!","cn":"告诉你怎么做就怎么做，别跟我顶嘴！"}},{"en":"to annoy somebody or cause them trouble, especially by asking them to do something many times","cn":"（不断）烦扰，麻烦","ex":{"en":"Don't keep hassling me! I'll do it later.","cn":"别老烦我！我待会儿会做的。"},"pos":"verb"}]}},"horrible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讨厌的;糟透的","en":"If you describe something or someone as horrible, you do not like them at all.","ex":{"en":"The record sounds horrible.","cn":"唱片难听极了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人震惊的;使人恐惧的;让人极度反感的","en":"You can call something horrible when it causes you to feel great shock, fear, and disgust.","ex":{"en":"Still the horrible shrieking came out of his mouth.","cn":"他的嘴里还是发出了恐怖的尖叫声。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极严重的","en":"Horrible is used to emphasize how bad something is.","ex":{"en":"That seems like a horrible mess that will drag on for years","cn":"看起来那像是个会拖延多年的大烂摊子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very bad and unpleasant","cn":"糟糕的﹐令人不快的"},{"en":"horrible, especially in a way that makes you feel slightly sick","cn":"恶心的﹐使人反感的"},{"en":"very unpleasant – often used about a taste that stays in your mouth 〔","cn":"常指口中的余味〕令人极为不快的"}]},"vocab":{"pos":"adj","senses":[{"en":"The difference between bad and horrible is like the difference between an unpleasant dream and an awful nightmare."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, smell, sound, taste","ADV. bloody (taboo) , really That was a really horrible thing to say! | absolutely, perfectly, quite, truly a truly horrible sight | pretty,","PREP. to My sister has always been horrible to me."]},"media":{"uk":"media/ldoce/hwd/bre/6/horrible0205.mp3","us":"media/ldoce/hwd/ame/b/horrible.mp3"},"examples":[{"en":"I've got a horrible feeling she lied to us.","cn":"我有种不快的感觉，觉得她对我们说了谎。"},{"en":"My sister was being horrible to me all day.","cn":"我姐姐一整天都对我很凶。"}],"oxford":{"phon":"ˈhɒrəbl","pos":"adjective","senses":[{"en":"very bad or unpleasant; used to describe something that you do not like","cn":"极坏的；十分讨厌的；可恶的","lab":"informal","ex":{"en":"What horrible weather!","cn":"这个鬼天气！"}},{"en":"making you feel very shocked and frightened","cn":"令人震惊的；恐怖的","ex":{"en":"a pretty horrible experience","cn":"非常可怕的经历"}},{"en":"unfriendly, unpleasant or unkind","cn":"不友善的；讨厌的；不厚道的","lab":"informal","ex":{"en":"a horrible person","cn":"讨厌鬼"}}]}},"heap":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指杂乱的）一堆","en":"A heap of things is a pile of them, especially a pile arranged in a rather untidy way.","ex":{"en":"...a heap of bricks","cn":"一堆砖"}},{"pos":"VERB 动词","cn":"堆放;堆积;堆起","en":"If you heap things somewhere, you arrange them in a large pile.","ex":{"en":"Mrs. Madrigal heaped more carrots onto Michael's plate.","cn":"马德里加尔夫人将更多的胡萝卜堆到了迈克尔的盘子里。"}},{"pos":"VERB 动词","cn":"（对…）极力（赞扬或批评）","en":"If you heap praise or criticism on someone or something, you give them a lot of praise or criticism.","ex":{"en":"The head of the navy heaped scorn on both the methods and motives of the conspirators.","cn":"海军首长对密谋分子的手法和动机都表示出极大的轻蔑。"}},{"pos":"QUANT 数量词","cn":"大量;许多","en":"Heaps of something or a heap of something is a large quantity of it.","ex":{"en":"You have heaps of time","cn":"你有的是时间。"}},{"pos":"PHRASE 短语","cn":"身处底层/身处高层","en":"Someone who is at the bottom of the heap or at the top of the heap is low down or high up in society or an organization.","ex":{"en":"...those at the top of the social heap","cn":"那些身处社会高层的人们"}},{"pos":"PHRASE 短语","cn":"颓然（倒下）；重重地（倒下）","en":"If someone collapses in a heap, they fall heavily and untidily and do not move.","ex":{"en":"The young footballer collapsed in a heap after a heavy tackle.","cn":"年青的足球队员完成激烈的阻截后瘫倒在地动弹不得。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of things of the same type that are put on top of each other","cn":""},{"en":"a neat pile of things of the same type","cn":""},{"en":"a large messy pile of things","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A great big pile of something is a heap . Your sloppy brother might keep all of his clothes in a heap on his bedroom floor."}]},"collocations":{"phrases":["ADJ. big, great, large | little, small | crumpled, untidy | compost, manure, muck, rubbish, scrap, slag, spoil colliery spoil heaps","VERB + HEAP be piled in Papers were piled in great heaps on the desk. | collapse in, fall (down) in (both figurative) He collapsed in an exh","PREP. in a/the ~ His clothes lay in a crumpled heap on the floor. | on/onto a/the ~ Throw the potato peelings on the compost heap. | ~ of a ","PHRASES the bottom/top of the heap (figurative) These workers are at the bottom of the economic heap."]},"media":{"uk":"media/ldoce/hwd/bre/9/heap_n0205.mp3","us":"media/ldoce/hwd/ame/9/heap1.mp3"},"examples":[{"en":"He looks heaps better than when I last saw him.","cn":"他看上去比我上回见他时好多了。"},{"en":"These workers are at the bottom of the economic heap.","cn":"这些工人处在经济结构的底层。"}],"oxford":{"phon":"hiːp","pos":"noun","senses":[{"en":"an untidy pile of something","cn":"（凌乱的）一堆","ex":{"en":"The building was reduced to a heap of rubble.","cn":"大楼变成了一堆废墟。"}},{"en":"a lot of something","cn":"大量；许多","g":"[usually plural]","lab":"informal","ex":{"en":"There's heaps of time before the plane leaves.","cn":"离飞机起飞还有很多时间。"}},{"en":"a car that is old and in bad condition","cn":"破旧的汽车；老爷车","lab":"informal, humorous，，"},{"en":"to put things in an untidy pile","cn":"堆积（东西）；堆置","ex":{"en":"Rocks were heaped up on the side of the road.","cn":"路边堆积着石头。"},"pos":"verb"},{"en":"to put a lot of something in a pile on something","cn":"在…上放很多（东西）","ex":{"en":"She heaped food on my plate.","cn":"她往我的盘子里放了很多食物。"},"pos":"verb"},{"en":"to give a lot of something such as praise or criticism to somebody","cn":"对（某人）大加赞扬（或批评等）","ex":{"en":"He heaped praise on his team.","cn":"他高度赞扬了他的队。"},"pos":"verb"}]}},"humiliation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"耻辱;屈辱;丢脸;蒙羞","en":"Humiliation is the embarrassment and shame you feel when someone makes you appear stupid, or when you make a mistake in public.","ex":{"en":"She faced the humiliation of discussing her husband's affair.","cn":"她面临要谈及丈夫外遇的羞辱。"}},{"pos":"N-COUNT 可数名词","cn":"丢脸的事;尴尬的场合","en":"A humiliation is an occasion or a situation in which you feel embarrassed and ashamed.","ex":{"en":"The result is a humiliation for the prime minister.","cn":"这一结果让首相出丑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling you have when you feel guilty and embarrassed because you, or someone who is close to you, have done something wrong","cn":""},{"en":"a feeling of shame and embarrassment because you have been made to look weak or stupid in front of other people","cn":""},{"en":"the loss of other people’s respect because you have done something bad, or you have been unsuccessful","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Humiliation describes a strong feeling of embarrassment or mortification — like that time in sixth grade when your mother wiped your face and called you \"honey bunny\" in front of all your friends."}]},"collocations":{"phrases":["ADJ. great, intense, painful | total | further | public | national | final, ultimate He was forced to face the ultimate humiliation the next","VERB + HUMILIATION be subjected to, endure, face, suffer She suffered the humiliation of having her house searched. | feel feeling the inten","PHRASES a feeling/sense of humiliation"]},"media":{"uk":"media/ldoce/hwd/bre/a/humiliation0205.mp3","us":"media/ldoce/hwd/ame/d/laadhumiliation.mp3"},"examples":[{"en":"She suffered the humiliation of being criticized in public.","cn":"她当众受到指责，丢了面子。"},{"en":"the humiliation of having to ask her parents for money","cn":"不得不开口向她父母要钱的难堪"}],"oxford":{"phon":"hjuːˌmɪliˈeɪʃn","pos":"noun","senses":[{"en":"a feeling of being ashamed or stupid and having lost the respect of other people; the act of making somebody feel like this","cn":"丢脸，蒙羞；羞辱","ex":{"en":"She suffered the humiliation of being criticized in public.","cn":"她当众受到指责，丢了面子。"}}]}},"heater":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"加热器;加热装置;暖气设备;炉子","en":"A heater is a piece of equipment or a machine which is used to raise the temperature of something, especially of the air inside a room or a car.","ex":{"en":"There's an electric heater in the bedroom.","cn":"卧室里有个电暖器。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine for making air or water hotter","cn":"加热器﹔暖气机﹔暖炉"}]},"collocations":{"phrases":["ADJ. convector, fan, immersion, instantaneous, multi-point, storage | electric, gas, oil, paraffin | aquarium, car, greenhouse, pool, room, ","VERB + HEATER have off/on | turn off/on | turn down/up","HEATER + VERB be off/on Even with the heater full on, the room felt cold."]},"media":{"uk":"media/ldoce/hwd/bre/e/heater0205.mp3","us":"media/ldoce/hwd/ame/7/heater.mp3"},"examples":[{"en":"a gas heater","cn":"煤气炉"},{"en":"a water heater","cn":"热水器"}],"oxford":{"phon":"ˈhiːtə(r)","pos":"noun","senses":[{"en":"a machine used for making air or water warmer","cn":"加热器；炉子；热水器","ex":{"en":"a gas heater","cn":"煤气炉"}}]}},"hierarchy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"等级制度","en":"A hierarchy is a system of organizing people into different ranks or levels of importance, for example in society or in a company.","ex":{"en":"Like most other American companies with a rigid hierarchy, workers and managers had strictly defined duties","cn":"和其他多数拥有严格等级制度的美国公司一样，这里的工人和管理人员都有界定严格的职责。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（组织中的）掌权集团，统治集团","en":"The hierarchy of an organization such as the Church is the group of people who manage and control it."},{"pos":"N-COUNT 可数名词","cn":"（思想、信仰的）等级体系，分级结构","en":"A hierarchy of ideas and beliefs involves organizing them into a system or structure.","ex":{"en":"...the notion of 'cultural imperialism' implies a hierarchy of cultures, some of which are stronger than others.","cn":"“文化扩张主义”意味着一种文化等级体系的存在，其中有些文化要比其他文化更强大。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your job in an organization, company, or profession - use this to talk about how important someone is and how much responsibility they have","cn":""},{"en":"all the jobs in an organization that are similar in importance and that pay similar amounts of money","cn":""},{"en":"someone's position in an organization such as the army or police force","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Hierarchy describes a system that organizes or ranks things, often according to power or importance. At school the principal is at the top of the staff hierarchy , while the seniors rule the student hierarchy ."}]},"collocations":{"phrases":["ADJ. complex | rigid, strict the rigid class hierarchy of rural society | administrative, bureaucratic, corporate, management, managerial, o","VERB + HIERARCHY create, establish A new management hierarchy was created within the company. | move up, rise in/through He joined the party","PREP. in a/the ~ She is above me in the hierarchy. | within a/the ~ There was a range of opinion within the ecclesiastical hierarchy on the ","PHRASES sb's level/position/status in a hierarchy"]},"media":{"uk":"media/ldoce/hwd/bre/a/hierarchy0205.mp3","us":"media/ldoce/hwd/ame/e/hierarchy.mp3"},"examples":[{"en":"She's quite high up in the management hierarchy.","cn":"她位居管理层要职。"},{"en":"the social/political hierarchy","cn":"社会/政治等级制度"}],"oxford":{"phon":"ˈhaɪərɑːki","pos":"noun","senses":[{"en":"a system, especially in a society or an organization, in which people are organized into different levels of importance from highest to lowest","cn":"等级制度（尤指社会或组织）","g":"[countable, uncountable]","ex":{"en":"the social/political hierarchy","cn":"社会／政治等级制度"}},{"en":"the group of people in control of a large organization or institution","cn":"统治集团","g":"[countable + singular or plural verb]","ex":{"en":"It was on orders from the party hierarchy that she dropped the investigation.","cn":"她是根据党内高层的命令放弃调查的。"}},{"en":"a system that ideas or beliefs can be arranged into according to their importance","cn":"层次体系","g":"[countable]","lab":"formal","ex":{"en":"a hierarchy of needs","cn":"不同层次的需要"}}]}},"haemorrhage":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"体内大出血","en":"A haemorrhage is serious bleeding inside a person's body.","ex":{"en":"Shortly after his admission into hospital he had a massive brain haemorrhage and died","cn":"住院后不久，他就死于大面积脑溢血。"}},{"pos":"VERB 动词","cn":"体内大出血","en":"If someone is haemorrhaging, there is serious bleeding inside their body.","ex":{"en":"I haemorrhaged badly after the birth of all three of my sons","cn":"生我3个儿子时，我每次都出现产后大出血。"}},{"pos":"N-SING 单数名词","cn":"（人员或资源的）严重流失","en":"A haemorrhage of people or resources is a rapid loss of them from a group or place, seriously weakening its position.","ex":{"en":"He said the move would definitely stem the haemorrhage of talent and enterprise from the colony.","cn":"他表示这一举措势必会抑制殖民地人才和企业严重流失的现象。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（人员或资源）严重流失","en":"To haemorrhage people or resources means to lose them rapidly and become weak. You can also say that people or resources haemorrhage from a place or organization.","ex":{"en":"Venice is haemorrhaging the very resource which could save it: its own people","cn":"威尼斯正在丧失它的立足之本，那就是它的人民。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious medical condition in which a person bleed s a lot, sometimes inside their body 〔","cn":"体内〕(大)出血"},{"en":"when a company or country loses a lot of money or people very quickly 〔","cn":"资金﹑人才的〕大量流失"},{"en":"to lose a lot of blood in a very short time","cn":"大出血"}]},"collocations":{"phrases":["ADJ. massive, severe | recurrent | acute The patient died from acute cerebral haemorrhage. | brain, cerebral","VERB + HAEMORRHAGE have, suffer Twelve hours later she suffered a massive brain haemorrhage. | die from/of | halt, stop (both usually figura"]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdehaemorrhage.mp3","us":"media/ldoce/hwd/ame/d/hemorrhage1.mp3"},"examples":[{"en":"Poor working conditions have led to a steady haemorrhage of qualified teachers from our schools.","cn":"工作条件欠佳导致各校大量合格教师不断流失。"},{"en":"He was checked for any signs of haemorrhage.","cn":"他接受检查，以确定是否有出血迹象。"}],"oxford":{"phon":"ˈhemərɪdʒ","pos":"noun","senses":[{"en":"a medical condition in which there is severe loss of blood from a damaged blood vessel inside a person’s body","cn":"体内（大）出血","g":"[countable, uncountable]","ex":{"en":"a massive brain/cerebral haemorrhage","cn":"重度脑出血"}},{"en":"a serious loss of people, money, etc. from a country, a group or an organization","cn":"（人、资金等的）大量流失","g":"[countable, usually singular]","ex":{"en":"Poor working conditions have led to a steady haemorrhage of qualified teachers from our schools.","cn":"工作条件欠佳导致各校大量合格教师不断流失。"}},{"en":"to lose blood heavily, especially from a damaged blood vessel inside the body; to have a haemorrhage","cn":"（尤指体内）大出血","g":"[intransitive]","ex":{"en":"After the operation she started to haemorrhage.","cn":"手术后，她开始流血。"},"pos":"verb"},{"en":"to lose money or people in large amounts at a fast rate","cn":"大量快速流失（资金、人等）","g":"[transitive]","ex":{"en":"The company has been haemorrhaging money for months.","cn":"该公司几个月来一直在亏损。"},"pos":"verb"}]}},"haze":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（阴）霾;雾霭","en":"Haze is light mist, caused by particles of water or dust in the air, which prevents you from seeing distant objects clearly. Haze often forms in hot weather.","ex":{"en":"They vanished into the haze near the horizon","cn":"他们消失在天边的雾霾中。"}},{"pos":"N-SING 单数名词","cn":"雾状物","en":"If there is a haze of something such as smoke or steam, you cannot see clearly through it.","ex":{"en":"Dan smiled at him through a haze of smoke and steaming coffee","cn":"丹透过烟雾和咖啡的热气朝他笑了笑。"}},{"pos":"N-SING 单数名词","cn":"迷糊;懵懂","en":"If someone is in a haze, they are not thinking clearly or not really noticing what is happening around them.","ex":{"en":"His mind was a haze of fear and confusion.","cn":"由于害怕和困惑，他当时处于一种混沌状态。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a white or grey mass in the sky that forms from very small drops of water","cn":""},{"en":"very thick cloud near the ground which is difficult to see through","cn":""},{"en":"light cloud near the ground that makes it difficult for you to see very far. Mist is usually not as thick as fog . You often get mist near areas of water or mountains","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"Haze is the fog or mist that's caused by small particles in the air. There is often a haze hovering over the city of Los Angeles."}]},"collocations":{"phrases":["ADJ. thick a thick haze of smoke | faint, thin The sun now had a faint golden haze around it. | shimmering | heat A heat haze shimmered abov","HAZE + VERB hang, shimmer In the evenings a blue haze hung in the valleys.","PREP. in a/the ~ Meetings are always conducted in a haze of cigarette smoke. | through a/the ~ He watched the world through a haze of tobacc"]},"media":{"uk":"media/ldoce/hwd/bre/7/haze_n0205.mp3","us":"media/ldoce/hwd/ame/e/haze1.mp3"},"examples":[{"en":"a haze of smoke/dust/steam","cn":"烟雾；尘雾；蒸汽雾"},{"en":"an alcoholic haze","cn":"喝醉酒的迷糊"}],"oxford":{"phon":"heɪz","pos":"noun","senses":[{"en":"air that is difficult to see through because it contains very small drops of water, especially caused by hot weather","cn":"（尤指热天引起的）薄雾，雾霭","g":"[countable, uncountable]","ex":{"en":"a heat haze","cn":"热天的雾气"}},{"en":"air containing something that makes it difficult to see through it","cn":"（烟尘等的）雾霭，烟雾","g":"[singular]","ex":{"en":"a haze of smoke/dust/steam","cn":"烟雾；尘雾；蒸汽雾"}},{"en":"a mental state in which your thoughts, feelings, etc. are not clear","cn":"迷蒙；迷糊","g":"[singular]","ex":{"en":"an alcoholic haze","cn":"喝醉酒的迷糊"}},{"en":"to become covered or to cover something in a haze","cn":"（使）笼罩在薄雾中","g":"[intransitive, transitive]","pos":"verb"},{"en":"to play tricks on somebody, especially a new student or somebody who has just joined the army, or to give them very unpleasant things to do, sometimes as a condition for entering a fraternity or sorority","cn":"戏弄，刁难（新生、新兵等）","g":"[transitive]","lab":"North American English","ex":{"en":"Rookies were mercilessly hazed.","cn":"新兵们被无情地折腾。"},"pos":"verb"}]}},"heroine":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（书、戏剧、电影或故事中品行端正的）女主角，女主人公","en":"The heroine of a book, play, film, or story is the main female character, who usually has good qualities.","ex":{"en":"The heroine is a senior TV executive.","cn":"女主角是一名电视台的高级主管。"}},{"pos":"N-COUNT 可数名词","cn":"女英雄;女杰;女豪杰","en":"A heroine is a woman who has done something brave, new, or good, and who is therefore greatly admired by a lot of people.","ex":{"en":"The national heroine of the day was Xing Fen, winner of the first Gold medal of the Games.","cn":"现今的民族英雄是在该运动会上获得首枚金牌的邢芬。"}},{"pos":"N-COUNT 可数名词","cn":"（女）偶像;心目中的女英雄","en":"If you describe a woman as your heroine, you mean that you admire her greatly, usually because of a particular quality or skill that she has.","ex":{"en":"My heroine was Elizabeth Taylor.","cn":"我心目中的偶像是伊丽莎白·泰勒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who you admire very much because of what they have done. Use hero about a man, use heroine about a woman","cn":""},{"en":"a famous actor, actress, musician, or sports player that a lot of people admire","cn":""},{"en":"a person in a story","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A heroine is a real-life or fictional woman who has lots of courage and fights on the side of good, maybe by rescuing a kitten from a tree, slaying an evil dragon, or helping you with your science fair project."}]},"collocations":{"phrases":["ADJ. great Violetta is one of the great tragic heroines of Verdi's operas. | national | romantic, tragic | unsung She remains one of the uns"]},"media":{"uk":"media/ldoce/hwd/bre/7/heroin0205.mp3","us":"media/ldoce/hwd/ame/f/heroin.mp3"},"examples":[{"en":"The heroine is played by Demi Moore.","cn":"女主角由黛米 · 穆尔扮演。"},{"en":"Madonna was her teenage heroine.","cn":"麦当娜是她十几岁时的偶像。"}],"oxford":{"phon":"ˈherəʊɪn","pos":"noun","senses":[{"en":"a girl or woman who is admired by many for doing something brave or good","cn":"女英雄；女豪杰","ex":{"en":"the heroines of the revolution","cn":"那场革命中的各位女英雄"}},{"en":"the main female character in a story, novel, film, etc.","cn":"（故事、小说、电影等中的）女主人公，女主角","ex":{"en":"The heroine is played by Demi Moore.","cn":"女主角由黛米·摩尔扮演。"}},{"en":"a woman that you admire because of a particular quality or skill that she has","cn":"崇拜的女人；女偶像","ex":{"en":"Madonna was her teenage heroine.","cn":"麦当娜是她十几岁时的偶像。"}}]}},"hierarchical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"等级制度的;等级森严的","en":"A hierarchical system or organization is one in which people have different ranks or positions, depending on how important they are.","ex":{"en":"...the traditional hierarchical system of military organization.","cn":"军事组织内传统的等级制度"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a system, organization etc is hierarchical, people or things are divided into levels of importance","cn":"按等级划分的﹔等级制度的"},{"en":"hierarchical structure/organization/system etc a hierarchical society","cn":"等级社会"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is hierarchical it has clear levels of power and importance, such as a hierarchical corporation that has the boss at the top, or the hierarchical social order of junior high school popularity."}]},"collocations":{"phrases":["VERBS be The company's structure is rigidly hierarchical. | become","ADV. extremely, rigidly, strictly, strongly, very | fairly | essentially"]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41hierarchical.mp3","us":"media/ldoce/hwd/ame/4/ld41hierarchical.mp3"},"examples":[{"en":"a hierarchical society/structure/organization","cn":"分等级的社会/结构/组织"}],"oxford":{"phon":"ˌhaɪəˈrɑːkɪkl","pos":"adjective","senses":[{"en":"arranged in a hierarchy","cn":"按等级划分的；等级制度的","ex":{"en":"a hierarchical society/structure/organization","cn":"分等级的社会／结构／组织"}}]}},"honey":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"蜂蜜","en":"Honey is a sweet, sticky, yellowish substance that is made by bees."},{"pos":"N-VOC 称呼名词","cn":"(爱称）亲爱的，宝贝","en":"You call someone honey as a sign of affection.","ex":{"en":"Honey, I don't really think that's a good idea.","cn":"亲爱的，我不认为那是个好主意。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sweet sticky substance produced by bee s , used as food","cn":"蜂蜜"},{"en":"used to address someone you love","cn":"亲爱的﹐宝贝〔用于称呼心爱的人〕"},{"en":"an attractive woman","cn":"美女"}]},"collocations":{"phrases":["ADJ. clear | runny | wild","QUANT. dollop | jar, pot","VERB + HONEY make, produce learning how bees make honey a jar of locally-produced honey | gather to gather honey from the hive | spread (sth","HONEY + NOUN bee","PHRASES as sweet as honey •"]},"media":{"uk":"media/ldoce/hwd/bre/9/honey0205.mp3","us":"media/ldoce/hwd/ame/5/honey.mp3"},"examples":[{"en":"Have you seen my keys, honey?","cn":"你见到我的钥匙了吗，宝贝？"},{"en":"He can be a real honey when he wants to be.","cn":"他高兴的时候挺招人喜欢的。"}],"oxford":{"phon":"ˈhʌni","pos":"noun","senses":[{"en":"a sweet, sticky yellow-brown substance made by bees that is spread on bread, etc. like jam","cn":"蜂蜜","g":"[uncountable]","ex":{"en":"How do bees make honey?","cn":"蜜蜂如何酿蜜？"}},{"en":"a way of addressing somebody that you like or love","cn":"（爱称）亲爱的，宝贝儿","g":"[countable]","lab":"informal","ex":{"en":"Have you seen my keys, honey?","cn":"你见到我的钥匙了吗，宝贝？"}},{"en":"a person that you like or love and think is very kind","cn":"可爱的人","g":"[countable]","lab":"informal","ex":{"en":"He can be a real honey when he wants to be.","cn":"他高兴的时候挺招人喜欢的。"}}]}},"hanker":{"collins":{"senses":[{"pos":"VERB 动词","cn":"渴望;热望","en":"If you hanker after something, you want it very much.","ex":{"en":"I hankered after a floor-length brown suede coat.","cn":"我渴望有一件长及脚跟的棕色绒面革大衣。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to want something that you have wanted for a long time, but which you are unlikely to get","cn":""},{"en":"to very much want to have something or do something, especially when this used to happen or exist in the past, or when it may do in the future - used especially in stories or literature","cn":""},{"en":"to want something so much that you do not feel happy or complete without it","cn":""}]},"collocations":{"phrases":["ADV. secretly | always | still","PREP. after She's always hankering after excitement. | for I still hankered for the farm life."]},"media":{"uk":"media/ldoce/hwd/bre/e/hanker0205.mp3","us":"media/ldoce/hwd/ame/3/hanker.mp3"},"examples":[{"en":"She hankered to go back to Australia.","cn":"她渴望回到澳大利亚。"},{"en":"He had hankered after fame all his life.","cn":"他一生追求名望。"}],"oxford":{"phon":"ˈhæŋkə(r)","pos":"verb","senses":[{"en":"to have a strong desire for something","cn":"渴望，渴求（某事物）","ex":{"en":"He had hankered after fame all his life.","cn":"他一生追求名望。"}}]}},"hesitation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"犹豫;疑虑;不情愿","en":"Hesitation is an unwillingness to do something, or a delay in doing it, because you are uncertain, worried, or embarrassed about it.","ex":{"en":"He promised there would be no more hesitations in pursuing reforms.","cn":"他答应在推进改革这件事上不再迟疑不决。"}},{"pos":"PHRASE 短语","cn":"毫不犹豫","en":"If you say that you have no hesitation in doing something, you are emphasizing that you will do it immediately or willingly because you are certain that it is the right thing to do.","ex":{"en":"The board said it had no hesitation in unanimously rejecting the offer","cn":"董事会自称毫不犹豫地一致否决了该项报价。"}},{"pos":"PHRASE 短语","cn":"毫不犹豫地;心甘情愿地","en":"If you say that someone does something without hesitation, you are emphasizing that they do it immediately and willingly.","ex":{"en":"The great majority of players would, of course, sign the contract without hesitation","cn":"绝大多数球员当然会毫不犹豫地签合同。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone hesitates","cn":"犹豫﹐踌躇﹐迟疑"}]},"vocab":{"pos":"n","senses":[{"en":"A hesitation is a pause. If your friend asks you, \"Do I look fat in this dress?\" you'd better make sure there's not a second's hesitation before you answer, \"No, not at all!\""}]},"collocations":{"phrases":["ADJ. brief, fractional, momentary, slight There was a momentary hesitation before he replied. | initial After some initial hesitation, teach","PREP. after &hellip; ~ After much hesitation, they decided to leave. | without ~ She answered immediately, without any hesitation.","PHRASES have no hesitation in doing sth I have no hesitation in recommending him for the job. | a moment's hesitation, a moment of hesitatio"]},"media":{"uk":"media/ldoce/hwd/bre/3/hesitation0205.mp3","us":"media/ldoce/hwd/ame/c/hesitation.mp3"},"examples":[{"en":"I have no hesitation in recommending her for the job.","cn":"我毫不犹豫地推荐她做这项工作。"},{"en":"He spoke fluently and without unnecessary hesitations.","cn":"他说得很流畅，毫不支吾。"}],"oxford":{"phon":"ˌhezɪˈteɪʃn","pos":"noun","senses":[{"en":"the act of being slow to speak or act because you feel uncertain or nervous","cn":"（对某事）犹豫，迟疑不决","g":"[uncountable, countable]","ex":{"en":"She agreed without the slightest hesitation.","cn":"她毫不犹豫地同意了。"}},{"en":"the fact of being worried about doing something, especially because you are not sure that it is right or appropriate","cn":"顾虑；疑虑","g":"[uncountable]","ex":{"en":"I have no hesitation in recommending her for the job.","cn":"我毫不犹豫地推荐她做这项工作。"}}]}},"hopeful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)抱有希望的，满怀希望的","en":"If you are hopeful, you are fairly confident that something that you want to happen will happen.","ex":{"en":"I am hopeful this misunderstanding will be rectified very quickly","cn":"我相信这个误会将很快得到纠正。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（征兆、事件等）给人以希望的","en":"If something such as a sign or event is hopeful, it makes you feel that what you want to happen will happen.","ex":{"en":"The result of the election in is yet another hopeful sign that peace could come to the Middle East.","cn":"已出炉的选举结果再次显示在中东实现和平是有希望的。"}},{"pos":"ADJ 形容词","cn":"（行动）被寄予希望的","en":"A hopeful action is one that you do in the hope that you will get what you want to get.","ex":{"en":"We've chartered the aircraft in the hopeful anticipation that the government will allow them to leave.","cn":"我们已经包租了那架飞机，希望政府会对他们放行。"}},{"pos":"N-COUNT 可数名词","cn":"希望获得成功的人","en":"If you refer to someone as a hopeful, you mean that they are hoping and trying to achieve success in a particular career, election, or competition.","ex":{"en":"His soccer skills continue to be put to good use in his job as football coach to young hopefuls.","cn":"他的球技在他给这些希望成为明日之星的年轻人担任教练的过程中继续发挥出很大作用。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"believing that good things will happen","cn":""},{"en":"believing that what you hope for will happen","cn":""},{"en":"thinking about what is good in a situation, rather than what is bad","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"If you're hopeful about something, you're optimistic. You think it's going to turn out OK. Your team has been doing well in practice, so you're hopeful that you'll win the finals."}]},"collocations":{"phrases":["VERBS be, feel, seem, sound I feel quite hopeful that a peaceful solution will be found. | become, get Don't get too hopeful. We may not be ","ADV. extremely, very | almost | fairly, pretty, quite | eternally Only Janet, eternally hopeful, thought it was worth trying again.","PREP. about She was not very hopeful about her situation. | of The police are quite hopeful of catching the thieves. 2 making you think that","VERBS be, look, seem Things aren't looking very hopeful at the moment.","ADV. extremely, very | fairly, quite There are some fairly hopeful signs of recovery in the US market."]},"media":{"uk":"media/ldoce/hwd/bre/7/hopeful_n0205.mp3","us":"media/ldoce/hwd/ame/2/hopeful1.mp3"},"examples":[{"en":"50 young hopefuls are trying for a place in the England team. * 50","cn":"名雄心勃勃的年轻人亟欲跻身英格兰队。"},{"en":"I feel hopeful that we'll find a suitable house very soon.","cn":"我对很快找到合适的房子抱有希望。"}],"oxford":{"phon":"ˈhəʊpfl","pos":"adjective","senses":[{"en":"believing that something you want will happen","cn":"抱有希望；满怀希望","g":"[not usually before noun]","lab":"British English","ex":{"en":"I feel hopeful that we'll find a suitable house very soon.","cn":"我对很快找到合适的房子抱有希望。"}},{"en":"showing hope","cn":"表现出希望的","g":"[only before noun]","ex":{"en":"a hopeful smile","cn":"充满希望的微笑"}},{"en":"making you believe that something you want will happen; bringing hope","cn":"给人以希望的","ex":{"en":"The latest trade figures are a hopeful sign.","cn":"最新贸易数字令人鼓舞。"}},{"en":"a person who wants to succeed at something","cn":"希望成功的人；雄心勃勃的人","ex":{"en":"50 young hopefuls are trying for a place in the England team.","cn":"50 名雄心勃勃的年轻人亟欲跻身英格兰队。"},"pos":"noun"}]}},"heartland":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（某活动或信仰占优势的）中心区域，核心地区","en":"Journalists use heartland or heartlands to refer to the area or region where a particular set of activities or beliefs is most significant.","ex":{"en":"...his six-day bus tour around the industrial heartland of America","cn":"他在美国工业中心区域的大巴6日游"}},{"pos":"N-COUNT 可数名词","cn":"（国家或大陆的）心脏地带，腹地","en":"The most central area of a country or continent can be referred to as its heartland or heartlands.","ex":{"en":"We then headed west towards the heartland of Poland","cn":"我们随后朝西前往波兰中部。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the central part of a country or area of land","cn":"中心区域"},{"en":"the most important part of a country or area for a particular activity, or the part where a political group has most support 〔","cn":"国家或地区的〕心脏地带﹐最重要地区﹔〔某政党占优势的〕根据地﹐大本营"}]},"collocations":{"phrases":["ADJ. agricultural, industrial the industrial heartland of Germany | Conservative, Labour, etc. | traditional","PREP. in a/the ~ The party has lost seats in its traditional heartland of southern Thailand."]},"media":{"uk":"media/ldoce/hwd/bre/b/heartland0205.mp3","us":"media/ldoce/hwd/ame/6/heartland.mp3"},"examples":[{"en":"the traditional Tory heartland of Britain's boardrooms","cn":"保守党的传统领地：英国的各董事会"},{"en":"the great Russian heartlands","cn":"广袤的俄罗斯中心地带"}],"oxford":{"phon":"ˈhɑːtlænd","pos":"noun","senses":[{"en":"the central part of a country or an area","cn":"（国家或地区的）腹地，中心区域","ex":{"en":"the great Russian heartlands","cn":"广袤的俄罗斯中心地带"}},{"en":"an area that is important for a particular activity or political party","cn":"（活动或政党的）重要场所，核心区域","ex":{"en":"the industrial heartland of Germany","cn":"德国的工业中心区"}}]}},"humidity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"潮湿","en":"You say there is humidity when the air feels very heavy and damp.","ex":{"en":"The heat and humidity were insufferable.","cn":"高温和潮湿让人难以忍受。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（空气）湿度","en":"Humidity is the amount of water in the air.","ex":{"en":"The humidity is relatively low.","cn":"湿度相对较低。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of water contained in the air","cn":"湿度﹔湿气"},{"en":"when the air is very warm and wet","cn":"湿热"}]},"vocab":{"pos":"n","senses":[{"en":"Humidity has to do with how much moisture is in the air. High humidity is a lot of moisture; low humidity is not much at all."}]},"collocations":{"phrases":["ADJ. high, low | ambient, relative in dry weather, when the ambient humidity is low","QUANT. level","HUMIDITY + VERB increase, rise | decrease, fall","HUMIDITY + NOUN level | control The museum is equipped with sophisticated humidity controls."]},"media":{"uk":"media/ldoce/hwd/bre/5/humidity0205.mp3","us":"media/ldoce/hwd/ame/8/humidity.mp3"},"examples":[{"en":"These plants need heat and humidity to grow well.","cn":"这些植物在高温潮湿的环境中才能生长得旺盛。"},{"en":"The humidity was becoming unbearable.","cn":"这种潮湿使人越来越难以忍受了。"}],"oxford":{"phon":"hjuːˈmɪdəti","pos":"noun","senses":[{"en":"the amount of water in the air","cn":"（空气中的）湿度","ex":{"en":"Instruments constantly monitor temperature and humidity.","cn":"仪器始终在监测温度和湿度。"}},{"en":"conditions in which the air is wet and very warm","cn":"湿热；高温潮湿","ex":{"en":"These plants need heat and humidity to grow well.","cn":"这些植物在高温潮湿的环境中才能生长得旺盛。"}}]}},"herd":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兽群;畜群","en":"A herd is a large group of animals of one kind that live together.","ex":{"en":"...large herds of elephant and buffalo.","cn":"大群的大象和水牛"}},{"pos":"N-SING 单数名词","cn":"（缺乏独立思想的）一般民众，芸芸众生","en":"If you say that someone has joined the herd or follows the herd, you are criticizing them because you think that they behave just like everyone else and do not think for themselves.","ex":{"en":"They are individuals; they will not follow the herd.","cn":"他们是独立的个体，不愿随大溜。"}},{"pos":"VERB 动词","cn":"使集在一起;把…赶在一起","en":"If you herd people somewhere, you make them move there in a group.","ex":{"en":"He began to herd the prisoners out","cn":"他开始将犯人集中在一起赶出来。"}},{"pos":"VERB 动词","cn":"驱赶，牧放（畜群）","en":"If you herd animals, you make them move along as a group.","ex":{"en":"Stefano used a motor cycle to herd the sheep","cn":"斯特凡诺骑一辆摩托车放羊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of cows, deer, or elephants","cn":""},{"en":"a group of animals that work together","cn":""},{"en":"a group of sheep or birds","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A herd is a bunch of animals, or — people who act like a bunch of animals. It's also a verb — when people herd animals, they try to keep them moving in the same direction."}]},"collocations":{"phrases":["ADJ. great, large | small | beef, breeding, dairy The farm has only a small dairy herd. | cattle, elephant, etc.","HERD + NOUN instinct","PREP. in a/the ~ The animals tend to graze in a herd. | ~ of a large herd of cows","PHRASES a member of a herd 2 group of people","ADJ. common","VERB + HERD follow If you feel so strongly, why follow the herd (= do the same as everybody else) ? | stand out from She prided herself on s","HERD + NOUN instinct"]},"media":{"uk":"media/ldoce/hwd/bre/a/herd_n0205.mp3","us":"media/ldoce/hwd/ame/a/herd1.mp3"},"examples":[{"en":"She pushed her way through a herd of lunchtime drinkers.","cn":"她从一群午餐时饮酒的人中间挤了过去。"},{"en":"They were herded together into trucks and driven away.","cn":"他们被一起赶上卡车拉走了。"}],"oxford":{"phon":"hɜːd","pos":"noun","senses":[{"en":"a group of animals of the same type that live and feed together","cn":"兽群；牧群","ex":{"en":"a herd of cows/deer/elephants","cn":"一群牛／鹿／象"}},{"en":"a large group of people of the same type","cn":"人群；芸芸众生","lab":"usually disapproving","ex":{"en":"She pushed her way through a herd of lunchtime drinkers.","cn":"她从一群午餐时饮酒的人中间挤了过去。"}},{"en":"to move or make somebody/something move in a particular direction","cn":"（使）向…移动","g":"[intransitive, transitive]","ex":{"en":"We all herded on to the bus.","cn":"我们全都拥上公共汽车。"},"pos":"verb"},{"en":"to keep or look after a group of animals; to make animals move together as a group","cn":"牧放（牲畜）；把（牲畜）赶到一起","g":"[transitive]","ex":{"en":"a shepherd herding his flock","cn":"正在放羊的羊倌"},"pos":"verb"}]}},"hygiene":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指为防止患病或疾病传播的）卫生","en":"Hygiene is the practice of keeping yourself and your surroundings clean, especially in order to prevent illness or the spread of diseases.","ex":{"en":"Be extra careful about personal hygiene.","cn":"要非常注意个人卫生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the practice of keeping yourself and the place where you live or work clean, so that diseases cannot spread","cn":""},{"en":"to use chemicals to clean a place, a piece of equipment, or a wound, in order to prevent disease","cn":""},{"en":"to make something safe to use by heating it or using chemicals, in order to kill all bacteria and prevent disease - use this about medical or scientific equipment, or babies' bottles","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Hygiene is any practice or activity that you do to keep things healthy and clean. Washing hands, coughing into your elbow, and regular house cleaning are all part of good hygiene ."}]},"collocations":{"phrases":["ADJ. good, scrupulous | poor infections that are the result of poor food hygiene | dental, food, oral, personal, public Many skin diseases c","HYGIENE + NOUN practices, regulations, standards","PHRASES standards of hygiene"]},"media":{"uk":"media/ldoce/hwd/bre/4/hygiene0205.mp3","us":"media/ldoce/hwd/ame/0/hygiene.mp3"},"examples":[{"en":"In the interests of hygiene, please wash your hands.","cn":"为了卫生，请洗手。"},{"en":"food hygiene","cn":"食物卫生"}],"oxford":{"phon":"ˈhaɪdʒiːn","pos":"noun","senses":[{"en":"the practice of keeping yourself and your living and working areas clean in order to prevent illness and disease","cn":"卫生","ex":{"en":"The restaurant was in breach of food hygiene regulations.","cn":"饭店违反了食物卫生规章制度。"}}]}},"humiliate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"羞辱;使蒙羞;使出丑","en":"To humiliate someone means to say or do something which makes them feel ashamed or stupid.","ex":{"en":"She had been beaten and humiliated by her husband","cn":"她遭到丈夫的殴打和羞辱。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel ashamed","cn":""},{"en":"to make someone feel very ashamed and upset, especially by making them look weak or stupid","cn":""},{"en":"if you disgrace yourself or disgrace your family, your school etc, you behave very badly so that other people lose respect for you or for your family or school","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Humiliate means to make someone feel ashamed or stupid, often publicly. It would humiliate all but the most self-assured person to realize that everyone else in the room has noticed their fly is down."}]},"collocations":{"phrases":["ADV. deeply | totally, utterly | publicly Lowe was publicly humiliated by his colleagues.","PREP. in front of I had been assaulted and deeply humiliated in front of all my friends.","PHRASES feel humiliated I have never felt so humiliated in all my life."]},"media":{"uk":"media/ldoce/hwd/bre/a/humiliate0205.mp3","us":"media/ldoce/hwd/ame/9/humiliate.mp3"},"examples":[{"en":"I didn't want to humiliate her in front of her colleagues.","cn":"我不想当着她同事们的面令她难堪。"},{"en":"The party was humiliated in the recent elections.","cn":"该党在新近的选举中耻辱地失败了。"}],"oxford":{"phon":"hjuːˈmɪlieɪt","pos":"verb","senses":[{"en":"to make somebody feel ashamed or stupid and lose the respect of other people","cn":"羞辱；使丧失尊严","ex":{"en":"I didn't want to humiliate her in front of her colleagues.","cn":"我不想当着她同事们的面令她难堪。"}}]}},"html":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（用于生成因特网文件的）超文本标记语言","en":"HTML is a system of codes for producing documents for the Internet. HTML is an abbreviation for (缩略=) 'hypertext markup language'."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a computer language used for producing pages of writing and pictures that can be put on the Internet","cn":"超文本置标语言〔用于编写网页的计算机语言〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld42html.mp3","us":"media/ldoce/hwd/ame/7/laadhtml.mp3"},"examples":[{"en":"HTML documents","cn":"超文本置标语言文件"}],"oxford":{"phon":"ˌeɪtʃ tiː em ˈel","pos":"abbreviation","senses":[{"en":"Hypertext Markup Language (a system used to mark text for World Wide Web pages in order to obtain colours, style, pictures, etc.)","cn":"超文本置标语言；超文本标记语言"}]}},"haggle":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"（尤指就价格）争论;讨价还价","en":"If you haggle, you argue about something before reaching an agreement, especially about the cost of something that you are buying.","ex":{"en":"Ella taught her how to haggle with used furniture dealers","cn":"埃拉教她如何和旧家具经销商砍价。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to persuade someone to reduce the price of something by arguing with them about what it is worth","cn":""},{"en":"to try to persuade someone to reduce the price of something by discussing it with them","cn":""},{"en":"to persuade someone to reduce the price of something by arguing with them about it","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you want a great deal on a used TV, then you can try to haggle with the sellers to see if they’ll bring the price down. To haggle is to negotiate or argue over something, usually a price."}]},"media":{"uk":"media/ldoce/hwd/bre/f/haggle0205.mp3","us":"media/ldoce/hwd/ame/0/haggle.mp3"},"examples":[{"en":"I left him in the market haggling over the price of a shirt.","cn":"我扔下他自己在市场上就一件衬衫讨价还价。"},{"en":"tourists haggling over the price of souvenirs","cn":"对纪念品讨价还价的游客"}],"oxford":{"phon":"ˈhæɡl","pos":"verb","senses":[{"en":"to argue with somebody in order to reach an agreement, especially about the price of something","cn":"争论；（尤指）讲价","ex":{"en":"I left him in the market haggling over the price of a shirt.","cn":"我扔下他自己在市场上就一件衬衫讨价还价。"}}]}}});
